DECLARE
 result jsonb := CAST('{}' AS JSONB);
 content_metadata jsonb := CAST('{}' AS JSONB);
 field_name text;
 field_value json;
BEGIN
 FOR field_name, field_value IN SELECT anon_1.key, anon_1.value 
FROM json_each(CAST(convert_from(p_payload, 'UTF8') AS JSON)) AS anon_1 LOOP
  IF (field_name = 'content') THEN
   SELECT coalesce(jsonb_object_agg(anon_1.key, CAST(anon_1.value AS JSONB)), CAST('{}' AS JSONB)) AS coalesce_1 
FROM json_each(field_value) AS anon_1 
WHERE anon_1.key IN ('schema_digest', 'recipe_digest', 'health') INTO content_metadata;
  ELSE
   IF ((field_name NOT IN ('occurrences', 'relations', 'coverage', 'inputs', 'mapping_reports'))) THEN
    result := result || jsonb_build_object(field_name, CAST(field_value AS JSONB));
   END IF;
  END IF;
 END LOOP;
 IF ((result ->> 'kind') = 'integrated') THEN
  result := result || jsonb_build_object('content_metadata', content_metadata);
 END IF;
 RETURN result;
END

