DECLARE
 tag text;
 n integer;
 lexical text;
 result jsonb;
BEGIN
 IF (jsonb_typeof(v) != 'array' OR jsonb_array_length(v) = 0 OR jsonb_typeof(v[0]) != 'string') THEN
  RAISE EXCEPTION USING MESSAGE = 'DDO semantic value must be tagged', ERRCODE = '23514';
 END IF;
 tag := v ->> 0;
 n := jsonb_array_length(v);
 IF (tag IN ('null', 'known-absent', 'unavailable', 'unknown') AND n = 1 OR tag = 'boolean' AND n = 2 AND jsonb_typeof(v[1]) = 'boolean') THEN
  RETURN v;
 END IF;
 IF (tag IN ('string', 'date', 'datetime', 'float', 'integer', 'decimal') AND n = 2 AND jsonb_typeof(v[1]) = 'string') THEN
  lexical := v ->> 1;
  IF (tag = 'integer') THEN
   IF (lexical !~ '^[+-]?[0-9]+$') THEN
    RAISE EXCEPTION USING MESSAGE = 'invalid integer meaning', ERRCODE = 'P0001';
   END IF;
   lexical := data.decimal_canonical(lexical);
  END IF;
  IF (tag = 'decimal') THEN
   IF (lexical !~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$') THEN
    RAISE EXCEPTION USING MESSAGE = 'invalid decimal meaning', ERRCODE = 'P0001';
   END IF;
   lexical := data.decimal_canonical(lexical);
  END IF;
  IF (tag = 'float') THEN
   lexical := data.require_float_lexical(lexical);
  END IF;
  IF (tag = 'date') THEN
   IF ((lexical !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$') OR lexical != CAST(CAST(lexical AS DATE) AS TEXT)) THEN
    RAISE EXCEPTION USING MESSAGE = 'date meaning requires canonical ISO date', ERRCODE = 'P0001';
   END IF;
  END IF;
  IF (tag = 'datetime') THEN
   IF ((lexical !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{6})?[+]00:00$') OR lexical IS DISTINCT FROM ((to_char(timezone('UTC', CAST(lexical AS TIMESTAMP WITH TIME ZONE)), 'YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN (CAST(EXTRACT(microseconds FROM CAST(lexical AS TIMESTAMP WITH TIME ZONE)) AS BIGINT) % 1000000 != 0) THEN '.' || to_char(timezone('UTC', CAST(lexical AS TIMESTAMP WITH TIME ZONE)), 'US') ELSE '' END) || '+00:00')) THEN
    RAISE EXCEPTION USING MESSAGE = 'datetime meaning requires canonical Python UTC ISO instant', ERRCODE = 'P0001';
   END IF;
  END IF;
  RETURN jsonb_build_array(tag, lexical);
 END IF;
 IF (tag = 'present' AND n = 2) THEN
  RETURN jsonb_build_array(tag, data.ddo_normalize(v[1]));
 END IF;
 IF (tag IN ('sequence', 'ordered-bag', 'bag', 'set') AND n = 2 AND jsonb_typeof(v[1]) = 'array') THEN
  SELECT coalesce(jsonb_agg(data.ddo_normalize(anon_1.value) ORDER BY anon_1.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(v[1]) WITH ORDINALITY AS anon_1(value, ordinal) INTO result;
  IF (tag = 'set') THEN
   SELECT coalesce(jsonb_agg(distinct_members.value ORDER BY convert_to(data.canonical_json(distinct_members.value), 'UTF8')), CAST('[]' AS JSONB)) AS coalesce_1 
FROM (SELECT DISTINCT anon_1.value AS value 
FROM jsonb_array_elements(result) AS anon_1) AS distinct_members INTO result;
  END IF;
  IF (tag = 'bag') THEN
   SELECT coalesce(jsonb_agg(anon_1.value ORDER BY convert_to(data.canonical_json(anon_1.value), 'UTF8')), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(result) AS anon_1 INTO result;
  END IF;
  RETURN jsonb_build_array(tag, result);
 END IF;
 IF (tag = 'mapping' AND n = 2 AND jsonb_typeof(v[1]) = 'array') THEN
  IF ((EXISTS (SELECT 1 
FROM jsonb_array_elements(v[1]) AS anon_1 
WHERE jsonb_typeof(anon_1.value) != 'array' OR jsonb_array_length(anon_1.value) != 2 OR jsonb_typeof(anon_1.value[0]) != 'string')) OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(v[1]) AS anon_1 GROUP BY (anon_1.value ->> 0) 
HAVING count(*) != 1))) THEN
   RAISE EXCEPTION USING MESSAGE = 'invalid mapping members', ERRCODE = 'P0001';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_array(anon_1.value[0], data.ddo_normalize(anon_1.value[1])) ORDER BY (anon_1.value ->> 0) COLLATE "C"), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(v[1]) AS anon_1 INTO result;
  RETURN jsonb_build_array(tag, result);
 END IF;
 RAISE EXCEPTION USING MESSAGE = 'invalid or unsupported DDO semantic tag ' || coalesce(tag, '<NULL>'), ERRCODE = '23514';
END

