DECLARE
 current_values jsonb := jsonb_build_array(body);
 following jsonb;
 part text;
 item jsonb;
BEGIN
 FOR part IN SELECT part.value 
FROM unnest(data.ddo_witness_path(pointer)) WITH ORDINALITY AS part(value, ordinality) ORDER BY part.ordinality LOOP
  following := CAST('[]' AS JSONB);
  FOR item IN SELECT current_item.value 
FROM jsonb_array_elements(current_values) AS current_item(value) LOOP
   IF (part = '*') THEN
    IF (jsonb_typeof(item) != 'array') THEN
     RAISE EXCEPTION USING MESSAGE = 'output witness member step requires an array', ERRCODE = 'P0001';
    END IF;
    following := following || item;
   ELSE
    IF (jsonb_typeof(item) != 'object') THEN
     RAISE EXCEPTION USING MESSAGE = 'output witness property step requires a record', ERRCODE = 'P0001';
    END IF;
    IF ((item ? part) AND item[part] != CAST('null' AS JSONB)) THEN
     following := following || jsonb_build_array(item[part]);
    END IF;
   END IF;
  END LOOP;
  current_values := following;
 END LOOP;
 RETURN QUERY SELECT current_item.value 
FROM jsonb_array_elements(current_values) AS current_item(value);
END

