DECLARE
 parts text[];
 whole text;
 fraction text;
 digits text;
 fixed text;
 exponent_digits text;
 point bigint;
 exponent bigint;
 negative boolean;
BEGIN
 IF (raw !~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$') THEN
  RAISE EXCEPTION USING MESSAGE = 'invalid finite decimal lexical', ERRCODE = '23514';
 END IF;
 negative := left(raw, 1) = '-';
 parts := regexp_split_to_array(ltrim(raw, '+-'), '[eE]');
 whole := split_part(parts[1], '.', 1);
 fraction := split_part(parts[1], '.', 2);
 digits := ltrim(whole || fraction, '0');
 IF (digits = '') THEN
  RETURN '0';
 END IF;
 exponent_digits := ltrim(ltrim(coalesce(parts[2], '0'), '+-'), '0');
 IF (length(exponent_digits) > 10) THEN
  RAISE EXCEPTION USING MESSAGE = 'decimal exceeds canonical fixed-point digit limit', ERRCODE = '23514';
 END IF;
 exponent := CASE WHEN (left(parts[2], 1) = '-') THEN -1 ELSE 1 END * CAST(coalesce(nullif(exponent_digits, ''), '0') AS BIGINT);
 point := (exponent + length(digits)) - length(fraction);
 digits := rtrim(digits, '0');
 IF (greatest(point, 1) + greatest(length(digits) - point, 0) > 16384) THEN
  RAISE EXCEPTION USING MESSAGE = 'decimal exceeds canonical fixed-point digit limit', ERRCODE = '23514';
 END IF;
 IF (point <= 0) THEN
  fixed := '0.' || repeat('0', CAST(-point AS INTEGER)) || digits;
 ELSE
  IF (point >= length(digits)) THEN
   fixed := digits || repeat('0', CAST(point - length(digits) AS INTEGER));
  ELSE
   fixed := CAST(left(digits, CAST(point AS INTEGER)) AS TEXT) || '.' || substr(digits, CAST(point + 1 AS INTEGER));
  END IF;
 END IF;
 RETURN CASE WHEN negative THEN '-' ELSE '' END || fixed;
END

