DECLARE
 result jsonb;
BEGIN
 IF (jsonb_typeof(p) = 'null') THEN
  RETURN jsonb_build_array('null');
 END IF;
 IF (jsonb_typeof(p) = 'string') THEN
  RETURN jsonb_build_array('string', p);
 END IF;
 IF (jsonb_typeof(p) = 'boolean') THEN
  RETURN jsonb_build_array('boolean', p);
 END IF;
 IF (jsonb_typeof(p) = 'number') THEN
