DECLARE
 lexical text;
 digits text;
 exponent integer;
 result double precision;
BEGIN
 IF ((p ->> 'kind') = 'integer') THEN
  IF (jsonb_typeof(p['integer']) IS DISTINCT FROM 'number' OR (p ->> 'integer') !~ '^-?(0|[1-9][0-9]*)$') THEN
   RAISE EXCEPTION USING MESSAGE = 'source report integer must be an integer', ERRCODE = '23514';
  END IF;
  RETURN CAST(p ->> 'integer' AS DOUBLE PRECISION);
 END IF;
 IF ((p ->> 'kind') IS DISTINCT FROM 'float' OR jsonb_typeof(p['hexadecimal']) IS DISTINCT FROM 'string') THEN
  RAISE EXCEPTION USING MESSAGE = 'record event score is not numeric', ERRCODE = '23514';
 END IF;
 lexical := data.require_float_lexical(p ->> 'hexadecimal');
 digits := replace(split_part(split_part(ltrim(lexical, '-'), 'p', 1), 'x', 2), '.', '');
 exponent := CAST(split_part(lexical, 'p', 2) AS INTEGER) - 52;
 result := CAST(CAST(CAST('x' || lpad(digits, 16, '0') AS BIT(64)) AS BIGINT) AS DOUBLE PRECISION) * power(CAST(2 AS DOUBLE PRECISION), exponent);
 IF (left(lexical, 1) = '-') THEN
  result := -result;
 END IF;
 RETURN result;
END

