   RAISE EXCEPTION USING MESSAGE = 'invalid source report integer scalar', ERRCODE = '23514';
  END IF;
  RETURN p['integer'];
 END IF;
 IF (kind = 'float') THEN
  RETURN to_jsonb(data.record_source_float(p));
 END IF;
 IF (kind = 'array') THEN
  IF ((p ? 'items') AND jsonb_typeof(p['items']) IS DISTINCT FROM 'array') THEN
   RAISE EXCEPTION USING MESSAGE = 'source report items must be an array', ERRCODE = '23514';
  END IF;
  SELECT coalesce(jsonb_agg(data.record_source_json(items.value) ORDER BY items.position), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(coalesce(p['items'], CAST('[]' AS JSONB))) WITH ORDINALITY AS items(value, position) INTO result;
  RETURN result;
