DECLARE
 principal name := SESSION_USER;
 owner_oid oid;
 required_role text;
BEGIN
 required_role := CASE purpose WHEN 'write' THEN 'corpus_sem_writer' WHEN 'read' THEN 'corpus_sem_reader' WHEN 'evaluate' THEN 'corpus_sem_evaluator' WHEN 'fit' THEN 'corpus_sem_fitter' WHEN 'admit' THEN 'corpus_sem_admitter' END;
 IF (required_role IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'unknown runtime purpose', ERRCODE = 'P0001';
 END IF;
 SELECT pg_catalog.pg_namespace.nspowner 
FROM pg_catalog.pg_namespace 
WHERE pg_catalog.pg_namespace.nspname = 'sem' INTO owner_oid;
 IF (NOT pg_catalog.pg_has_role(principal, required_role, 'USAGE') OR (pg_catalog.current_setting('role') NOT IN ('none', CAST(principal AS TEXT))) OR pg_catalog.pg_has_role(principal, owner_oid, 'MEMBER') OR pg_catalog.pg_has_role(principal, 'corpus_sem_publisher', 'MEMBER') OR (EXISTS (SELECT pg_catalog.pg_roles.oid 
FROM pg_catalog.pg_roles 
WHERE pg_catalog.pg_roles.rolname = principal AND (pg_catalog.pg_roles.rolsuper OR pg_catalog.pg_roles.rolcreaterole OR pg_catalog.pg_roles.rolcreatedb OR pg_catalog.pg_roles.rolbypassrls OR pg_catalog.pg_roles.rolreplication))) OR pg_catalog.has_database_privilege(principal, pg_catalog.current_database(), 'TEMP') OR (EXISTS (SELECT pg_catalog.pg_namespace.oid 
FROM pg_catalog.pg_namespace 
WHERE pg_catalog.pg_namespace.nspname IN ('sem', 'data', 'ops', 'kb', 'eval') AND pg_catalog.has_schema_privilege(principal, pg_catalog.pg_namespace.oid, 'CREATE'))) OR (EXISTS (SELECT pg_catalog.pg_class.oid 
FROM pg_catalog.pg_class JOIN pg_catalog.pg_namespace ON pg_catalog.pg_class.relnamespace = pg_catalog.pg_namespace.oid 
WHERE pg_catalog.pg_namespace.nspname IN ('sem', 'data') AND pg_catalog.pg_class.relkind IN ('r', 'p') AND (pg_catalog.has_table_privilege(principal, pg_catalog.pg_class.oid, 'INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER') OR pg_catalog.has_any_column_privilege(principal, pg_catalog.pg_class.oid, 'INSERT,UPDATE'))))) THEN
  RAISE EXCEPTION USING MESSAGE = pg_catalog.format('unrestricted or mismatched runtime principal for %s', purpose), ERRCODE = '42501';
 END IF;
