CREATE OR REPLACE FUNCTION data.require_runtime_principal(purpose text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 principal name := SESSION_USER;
 owner_oid oid;
 required_role text;
BEGIN
 required_role := CASE purpose WHEN 'write' THEN 'corpus_sem_writer' WHEN 'read' THEN 'corpus_sem_reader' WHEN 'evaluate' THEN 'corpus_sem_evaluator' WHEN 'fit' THEN 'corpus_sem_fitter' WHEN 'admit' THEN 'corpus_sem_admitter' END;
 IF (required_role IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'unknown runtime purpose', ERRCODE = 'P0001';
 END IF;
 SELECT pg_catalog.pg_namespace.nspowner 
FROM pg_catalog.pg_namespace 
WHERE pg_catalog.pg_namespace.nspname = 'sem' INTO owner_oid;
 IF (NOT pg_catalog.pg_has_role(principal, required_role, 'USAGE') OR (pg_catalog.current_setting('role') NOT IN ('none', CAST(principal AS TEXT))) OR pg_catalog.pg_has_role(principal, owner_oid, 'MEMBER') OR pg_catalog.pg_has_role(principal, 'corpus_sem_publisher', 'MEMBER') OR (EXISTS (SELECT pg_catalog.pg_roles.oid 
FROM pg_catalog.pg_roles 
WHERE pg_catalog.pg_roles.rolname = principal AND (pg_catalog.pg_roles.rolsuper OR pg_catalog.pg_roles.rolcreaterole OR pg_catalog.pg_roles.rolcreatedb OR pg_catalog.pg_roles.rolbypassrls OR pg_catalog.pg_roles.rolreplication))) OR pg_catalog.has_database_privilege(principal, pg_catalog.current_database(), 'TEMP') OR (EXISTS (SELECT pg_catalog.pg_namespace.oid 
FROM pg_catalog.pg_namespace 
WHERE pg_catalog.pg_namespace.nspname IN ('sem', 'data', 'ops', 'kb', 'eval') AND pg_catalog.has_schema_privilege(principal, pg_catalog.pg_namespace.oid, 'CREATE'))) OR (EXISTS (SELECT pg_catalog.pg_class.oid 
FROM pg_catalog.pg_class JOIN pg_catalog.pg_namespace ON pg_catalog.pg_class.relnamespace = pg_catalog.pg_namespace.oid 
WHERE pg_catalog.pg_namespace.nspname IN ('sem', 'data') AND pg_catalog.pg_class.relkind IN ('r', 'p') AND (pg_catalog.has_table_privilege(principal, pg_catalog.pg_class.oid, 'INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER') OR pg_catalog.has_any_column_privilege(principal, pg_catalog.pg_class.oid, 'INSERT,UPDATE'))))) THEN
  RAISE EXCEPTION USING MESSAGE = pg_catalog.format('unrestricted or mismatched runtime principal for %s', purpose), ERRCODE = '42501';
 END IF;
 IF (NOT pg_catalog.has_table_privilege(principal, 'sem.release', 'SELECT') OR NOT pg_catalog.has_schema_privilege(principal, 'ops', 'USAGE') OR purpose IN ('read', 'write', 'evaluate') AND NOT coalesce(pg_catalog.has_function_privilege(principal, pg_catalog.to_regprocedure('ops.read_demand_result(jsonb)'), 'EXECUTE'), false) OR purpose = 'write' AND NOT coalesce(pg_catalog.has_function_privilege(principal, pg_catalog.to_regprocedure('ops.initialize_source_project(jsonb)'), 'EXECUTE'), false) OR purpose IN ('write', 'evaluate') AND NOT coalesce(pg_catalog.has_function_privilege(principal, pg_catalog.to_regprocedure('ops.register_data_demand(jsonb)'), 'EXECUTE'), false) OR purpose = 'evaluate' AND NOT coalesce(pg_catalog.has_function_privilege(principal, pg_catalog.to_regprocedure('ops.admit_authored_data(jsonb)'), 'EXECUTE'), false) OR purpose = 'admit' AND (NOT coalesce(pg_catalog.has_function_privilege(principal, pg_catalog.to_regprocedure('sem.publish_release_archive(text)'), 'EXECUTE'), false) OR NOT coalesce(pg_catalog.has_function_privilege(principal, pg_catalog.to_regprocedure('ops.inspect_data_execution(jsonb)'), 'EXECUTE'), false))) THEN
  RAISE EXCEPTION USING MESSAGE = 'required runtime capability unavailable', ERRCODE = '42501';
 END IF;
 IF (EXISTS (SELECT 1 
FROM jsonb_array_elements((data.execution_contract_descriptor())['functions']) AS anon_1 LEFT OUTER JOIN pg_catalog.pg_proc ON pg_catalog.pg_proc.oid = pg_catalog.to_regprocedure((anon_1.value ->> 'signature')) 
WHERE pg_catalog.pg_proc.oid IS NULL OR pg_catalog.has_function_privilege(principal, pg_catalog.pg_proc.oid, 'EXECUTE') IS DISTINCT FROM ((anon_1.value['execute_roles'] ? required_role)))) THEN
  RAISE EXCEPTION USING MESSAGE = 'runtime operation privileges differ from purpose contract', ERRCODE = '42501';
 END IF;
 IF (purpose != 'evaluate' AND (EXISTS (SELECT pg_catalog.pg_class.oid 
FROM pg_catalog.pg_class JOIN pg_catalog.pg_namespace ON pg_catalog.pg_class.relnamespace = pg_catalog.pg_namespace.oid 
WHERE pg_catalog.pg_namespace.nspname IN ('eval') AND pg_catalog.pg_class.relkind IN ('r', 'p') AND pg_catalog.has_table_privilege(principal, pg_catalog.pg_class.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'runtime principal has independent reference access', ERRCODE = '42501';
 END IF;
END$$

