DECLARE
 build ops.pdf_stage_build%ROWTYPE;
 receipt ops.pdf_stage_receipt%ROWTYPE;
 n bigint;
 bytes bigint;
 total bigint := 0;
 total_bytes bigint := 0;
 hashes text := '';
 digest text;
BEGIN
 build := ops.require_pdf_build(p_build, p_task, p_attempt, p_holder);
 PERFORM ops.require_pdf_operation(build.release_id, 'adopt_pdf_batch');
 IF (p_key IS NULL OR p_key = '' OR octet_length(p_key) > 1024) THEN
  RAISE EXCEPTION USING MESSAGE = 'invalid private replay key', ERRCODE = '23514';
 END IF;
 PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_artifact_part', ops.pdf_part_upload_contract());
 SELECT count(*) AS count_1, coalesce(sum(1 + CASE WHEN (s.product_id IS NULL) THEN 0 ELSE 4 + octet_length(s.product_id) END + CASE WHEN (s.revision_id IS NULL) THEN 0 ELSE 4 + octet_length(s.revision_id) END + CASE WHEN (s.stream_id IS NULL) THEN 0 ELSE 4 + octet_length(s.stream_id) END + CASE WHEN (s.ordinal IS NULL) THEN 0 ELSE 8 END + CASE WHEN (s.byte_offset IS NULL) THEN 0 ELSE 8 END + CASE WHEN (s.byte_length IS NULL) THEN 0 ELSE 8 END + CASE WHEN (s.body IS NULL) THEN 0 ELSE 4 + octet_length(s.body) END + CASE WHEN (s.sha256_digest IS NULL) THEN 0 ELSE 4 + octet_length(s.sha256_digest) END), 0) AS coalesce_1 
FROM pg_temp.ps_pdf_stage_artifact_part AS s INTO n, bytes;
 total := total + n;
 total_bytes := total_bytes + bytes;
 IF (total > 65536 OR total_bytes > 8388608) THEN
  RAISE EXCEPTION USING MESSAGE = 'private PDF upload profile exceeded', ERRCODE = '23514';
 END IF;
 IF ((EXISTS (SELECT 1 
FROM pg_temp.ps_pdf_stage_artifact_part AS s 
WHERE s.product_id IS DISTINCT FROM p_build OR s.revision_id IS DISTINCT FROM p_build)) OR (EXISTS (SELECT 1 
FROM pg_temp.ps_pdf_stage_artifact_part AS s GROUP BY s.product_id, s.revision_id, s.stream_id, s.ordinal 
HAVING count(*) > 1))) THEN
  RAISE EXCEPTION USING MESSAGE = 'private PDF upload ownership or duplicate key differs', ERRCODE = '23514';
 END IF;
 SELECT hashes || 'ops.pdf_stage_artifact_part' || ':' || encode(sha256(convert_to(coalesce(string_agg(CAST(to_jsonb(s) AS TEXT), '
' ORDER BY s.product_id, s.revision_id, s.stream_id, s.ordinal), ''), 'UTF8')), 'hex') AS anon_1 
FROM pg_temp.ps_pdf_stage_artifact_part AS s INTO hashes;
 PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_artifact_stream', CAST('ops.pdf_stage_artifact_stream' AS REGCLASS));
 SELECT count(*) AS count_1, coalesce(sum(1 + CASE WHEN (s.product_id IS NULL) THEN 0 ELSE 4 + octet_length(s.product_id) END + CASE WHEN (s.revision_id IS NULL) THEN 0 ELSE 4 + octet_length(s.revision_id) END + CASE WHEN (s.stream_id IS NULL) THEN 0 ELSE 4 + octet_length(s.stream_id) END + CASE WHEN (s.byte_length IS NULL) THEN 0 ELSE 8 END + CASE WHEN (s.serialization_sha256 IS NULL) THEN 0 ELSE 4 + octet_length(s.serialization_sha256) END + CASE WHEN (s.byte_root IS NULL) THEN 0 ELSE 4 + octet_length(s.byte_root) END + CASE WHEN (s.encoding_profile IS NULL) THEN 0 ELSE 4 + octet_length(s.encoding_profile) END), 0) AS coalesce_1 
FROM pg_temp.ps_pdf_stage_artifact_stream AS s INTO n, bytes;
 total := total + n;
 total_bytes := total_bytes + bytes;
 IF (total > 65536 OR total_bytes > 8388608) THEN
  RAISE EXCEPTION USING MESSAGE = 'private PDF upload profile exceeded', ERRCODE = '23514';
 END IF;
 IF ((EXISTS (SELECT 1 
FROM pg_temp.ps_pdf_stage_artifact_stream AS s 
WHERE s.product_id IS DISTINCT FROM p_build OR s.revision_id IS DISTINCT FROM p_build)) OR (EXISTS (SELECT 1 
FROM pg_temp.ps_pdf_stage_artifact_stream AS s GROUP BY s.product_id, s.revision_id, s.stream_id 
HAVING count(*) > 1))) THEN
  RAISE EXCEPTION USING MESSAGE = 'private PDF upload ownership or duplicate key differs', ERRCODE = '23514';
 END IF;
 SELECT hashes || 'ops.pdf_stage_artifact_stream' || ':' || encode(sha256(convert_to(coalesce(string_agg(CAST(to_jsonb(s) AS TEXT), '
' ORDER BY s.product_id, s.revision_id, s.stream_id), ''), 'UTF8')), 'hex') AS anon_1 
FROM pg_temp.ps_pdf_stage_artifact_stream AS s INTO hashes;
 PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_document', CAST('ops.pdf_stage_document' AS REGCLASS));
 SELECT count(*) AS count_1, coalesce(sum(1 + CASE WHEN (s.product_id IS NULL) THEN 0 ELSE 4 + octet_length(s.product_id) END + CASE WHEN (s.revision_id IS NULL) THEN 0 ELSE 4 + octet_length(s.revision_id) END + CASE WHEN (s.release_id IS NULL) THEN 0 ELSE 4 + octet_length(s.release_id) END + CASE WHEN (s.source_digest IS NULL) THEN 0 ELSE 4 + octet_length(s.source_digest) END + CASE WHEN (s.mapping_profile IS NULL) THEN 0 ELSE 4 + octet_length(s.mapping_profile) END + CASE WHEN (s.contract_version IS NULL) THEN 0 ELSE 4 + octet_length(s.contract_version) END + CASE WHEN (s.native_schema_digest IS NULL) THEN 0 ELSE 4 + octet_length(s.native_schema_digest) END + CASE WHEN (s.root_id IS NULL) THEN 0 ELSE 4 + octet_length(s.root_id) END), 0) AS coalesce_1 
FROM pg_temp.ps_pdf_stage_document AS s INTO n, bytes;
 total := total + n;
 total_bytes := total_bytes + bytes;
 IF (total > 65536 OR total_bytes > 8388608) THEN
  RAISE EXCEPTION USING MESSAGE = 'private PDF upload profile exceeded', ERRCODE = '23514';
 END IF;
 IF ((EXISTS (SELECT 1 
FROM pg_temp.ps_pdf_stage_document AS s 
WHERE s.product_id IS DISTINCT FROM p_build OR s.revision_id IS DISTINCT FROM p_build)) OR (EXISTS (SELECT 1 
