DECLARE
 owner record;
 build ops.pdf_stage_build%ROWTYPE;
 id text;
BEGIN
 SELECT anon_1.project_id, anon_1.release_id, anon_1.request_id, anon_1.generation, anon_1.document_id, anon_1.source_digest 
FROM ops.require_pdf_stage_owner(p_task, p_attempt, p_holder) AS anon_1 INTO STRICT owner;
 IF (EXISTS (SELECT 1 
FROM ops.data_request JOIN sem.data_operation_definition ON sem.data_operation_definition.release_id = ops.data_request.release_id AND sem.data_operation_definition.operation_id = ops.data_request.operation_id 
WHERE ops.data_request.id = owner.request_id AND ((sem.data_operation_definition.support_contract['effects'][0]) ->> 'name') = 'retain_pdf_observations')) THEN
  RAISE EXCEPTION USING MESSAGE = 'recognition retention cannot stage a sealed PDF publication', ERRCODE = '23514';
 END IF;
 PERFORM ops.require_pdf_operation(owner.release_id, 'begin_pdf_build');
 IF (p_source IS NULL OR p_recipe IS NULL OR p_schema IS DISTINCT FROM encode(sha256(ops.pdf_contract_input(owner.release_id, 'implementation/pdf/docling-validation.schema.json')), 'hex') OR p_key IS NULL OR p_key = '' OR octet_length(p_key) > 1024 OR NOT (EXISTS (SELECT 1 
FROM ops.source_build 
WHERE ops.source_build.task_id = p_task AND ops.source_build.release_id = owner.release_id AND ops.source_build.artifact_digest = p_source AND (ops.source_build.recipe_digest = p_recipe OR (EXISTS (SELECT 1 
FROM ops.pdf_stage_recipe 
WHERE ops.pdf_stage_recipe.task_id = p_task AND ops.pdf_stage_recipe.source_digest = p_source AND ops.pdf_stage_recipe.root_recipe_digest = ops.source_build.recipe_digest AND ops.pdf_stage_recipe.stage_recipe_digest = p_recipe))))) OR p_source IS DISTINCT FROM owner.source_digest OR NOT (EXISTS (SELECT 1 
FROM kb.document 
WHERE kb.document.id = owner.document_id AND kb.document.project_id = owner.project_id AND kb.document.content_hash = p_source))) THEN
  RAISE EXCEPTION USING MESSAGE = 'private PDF build source custody differs', ERRCODE = '23514';
 END IF;
 id := encode(sha256(convert_to(CAST(jsonb_build_array(p_task, p_source, p_recipe, p_schema, p_key) AS TEXT), 'UTF8')), 'hex');
 INSERT INTO ops.pdf_stage_build (build_id, task_id, release_id, source_digest, recipe_digest, schema_digest, replay_key, attempt, holder, state) VALUES (id, p_task, owner.release_id, p_source, p_recipe, p_schema, p_key, p_attempt, p_holder, 'open') ON CONFLICT (task_id, replay_key) DO NOTHING;
 SELECT ops.pdf_stage_build.build_id, ops.pdf_stage_build.task_id, ops.pdf_stage_build.release_id, ops.pdf_stage_build.source_digest, ops.pdf_stage_build.recipe_digest, ops.pdf_stage_build.schema_digest, ops.pdf_stage_build.replay_key, ops.pdf_stage_build.attempt, ops.pdf_stage_build.holder, ops.pdf_stage_build.state 
FROM ops.pdf_stage_build 
WHERE ops.pdf_stage_build.task_id = p_task AND ops.pdf_stage_build.replay_key = p_key INTO STRICT build;
 IF (build.build_id IS DISTINCT FROM id OR build.attempt IS DISTINCT FROM p_attempt OR build.holder IS DISTINCT FROM p_holder OR build.state != 'open') THEN
  RAISE EXCEPTION USING MESSAGE = 'private PDF build replay differs or requires explicit resume', ERRCODE = '23514';
 END IF;
 RETURN QUERY SELECT build.build_id, build.task_id, build.release_id, build.source_digest, build.recipe_digest, build.schema_digest, build.replay_key, build.attempt, build.holder, build.state;
END

