 SELECT count(*) AS count_1 
FROM ops.pdf_roundtrip_oracle 
WHERE ops.pdf_roundtrip_oracle.build_id = p_build INTO index_;
 id_ := encode(sha256(convert_to(CAST(jsonb_build_array(p_build, p_frozen, c.lowering_identity, p_attempt, p_holder, index_) AS TEXT), 'UTF8')), 'hex');
