DECLARE
 p jsonb := p_payload;
 d ops.data_demand%ROWTYPE;
 frozen jsonb;
 fact jsonb;
 kind text;
 product text;
 identity text;
 snapshot jsonb;
 kind_name text;
 kind_universe text;
 key text;
 admitted ops.original_source_admission%ROWTYPE;
 rooted boolean;
 subject_scopes jsonb;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['demand_id', 'selection_name', 'reference', 'selectors']);
 SELECT ops.data_demand.* 
FROM ops.data_demand 
WHERE ops.data_demand.id = (p ->> 'demand_id') INTO STRICT d;
 frozen := d.selection['original_sources'][(p ->> 'selection_name')];
 IF (frozen IS NULL OR frozen IS DISTINCT FROM ((p - 'demand_id') - 'selection_name') OR ((p['reference']) ->> 'project_id') IS DISTINCT FROM d.project_id) THEN
  RAISE EXCEPTION USING MESSAGE = 'original source selection differs from immutable demand', ERRCODE = 'P0001';
 END IF;
 IF (((p['reference']) ->> 'kind') = 'authored-fact') THEN
  IF (p['selectors'] IS DISTINCT FROM jsonb_build_array(jsonb_build_object('scope', 'authored-fact'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'authored input requires its explicit immutable selection scope', ERRCODE = 'P0001';
  END IF;
  SELECT sem.data_kind_contract.kind, sem.data_kind_contract.universe 
FROM sem.data_kind_contract JOIN sem.data_kind_release ON sem.data_kind_release.kind_contract = sem.data_kind_contract.kind_contract 
WHERE sem.data_kind_release.release_id = d.release_id AND sem.data_kind_contract.kind_contract = ((p['reference']) ->> 'kind_contract') AND sem.data_kind_contract.universe IN ('ordinary', 'evaluator') INTO STRICT kind_name, kind_universe;
  PERFORM ops.ddo_authorize(kind_universe);
  fact := jsonb_build_object('subject', (p['reference']) ->> 'subject', 'subject_definition', (p['reference']) ->> 'subject_definition', 'original_source', (p['reference']) ->> 'original_source', 'analyzed_scope', p['reference']['analyzed_scope'], 'meaning_body', data.ddo_normalize(p['reference']['meaning_body']), 'evidence', jsonb_build_object('standing', 'authored', 'author_assertion', (p['reference']) ->> 'author', 'selection_id', (p['reference']) ->> 'selection_id', 'submitted_by', coalesce(nullif(current_setting('role'), 'none'), SESSION_USER)));
 ELSE
  IF (((p['reference']) ->> 'kind') = 'original-document') THEN
   IF (p['selectors'] IS DISTINCT FROM jsonb_build_array(jsonb_build_object('scope', 'whole-document'))) THEN
    RAISE EXCEPTION USING MESSAGE = 'original document scope differs from immutable whole document', ERRCODE = 'P0001';
   END IF;
   fact := ops.ddo_original_document_view(p['reference']);
   kind_name := 'https://corpus-structure.dev/semantic/data-operation-source/DdoOriginalDocument';
  ELSE
   RAISE EXCEPTION USING MESSAGE = 'unknown original source admission reference', ERRCODE = 'P0001';
  END IF;
 END IF;
 subject_scopes := ops.ddo_release_subject_scopes(d.release_id);
 PERFORM ops.ddo_require_subject_source(subject_scopes, fact ->> 'subject_definition', fact ->> 'original_source');
 rooted := EXISTS (SELECT 1 
FROM jsonb_array_elements(d.root) AS root(value) 
WHERE ((root.value ->> 'subject'), (root.value ->> 'original_source')) IS NOT DISTINCT FROM ((fact ->> 'subject'), (fact ->> 'original_source')) AND root.value['analyzed_scope'] = fact['analyzed_scope']);
 IF (NOT rooted) THEN
  RAISE EXCEPTION USING MESSAGE = 'authenticated source context is outside frozen roots', ERRCODE = 'P0001';
 END IF;
 snapshot := ops.ddo_lock_support(d.project_id, fact ->> 'original_source', CAST('[]' AS JSONB));
 PERFORM ops.ddo_require_active_demand(d.id);
 SELECT sem.data_kind_release.kind_contract 
FROM sem.data_kind_release JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = sem.data_kind_release.kind_contract 
WHERE sem.data_kind_release.release_id = d.release_id AND sem.data_kind_contract.kind = kind_name INTO STRICT kind;
 product := ops.ddo_install_product_context(jsonb_build_object('project_id', d.project_id, 'release_id', d.release_id, 'subject', fact ->> 'subject', 'subject_definition', fact ->> 'subject_definition', 'original_source', fact ->> 'original_source', 'analyzed_scope', fact['analyzed_scope']), jsonb_build_object('kind_contract', kind, 'body', fact['meaning_body'], 'members', (SELECT coalesce(jsonb_agg(jsonb_build_object('member_id', data.ddo_json(data.ddo_field(packet.value, 'member_id')), 'kind_contract', data.ddo_json(data.ddo_field(packet.value, 'kind_contract')), 'context', data.ddo_json(data.ddo_field(packet.value, 'context')), 'body', data.ddo_field(packet.value, 'body')) || (SELECT coalesce(jsonb_object_agg(family_field.field, data.ddo_json(data.ddo_field(data.ddo_field(packet.value, 'body'), family_field.field))), CAST('{}' AS JSONB)) AS coalesce_2 
FROM unnest(ARRAY['coordinates', 'roles', 'endpoints', 'coverage', 'choices']) AS family_field(field) 
WHERE data.ddo_field(data.ddo_field(packet.value, 'body'), family_field.field) IS NOT NULL)), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(CASE WHEN (((fact['meaning_body']) ->> 0) = 'mapping') THEN coalesce((data.ddo_field(fact['meaning_body'], 'members'))[1], CAST('[]' AS JSONB)) ELSE CAST('[]' AS JSONB) END) AS packet(value))), subject_scopes);
 identity := ops.ddo_digest(p['reference']);
 key := 'original-admission:' || ops.ddo_digest(jsonb_build_array(d.id, (p ->> 'selection_name'), identity, p['selectors'], product));
 INSERT INTO ops.original_source_admission (id, demand_id, project_id, release_id, selection_name, source_reference, reference, selectors, product_id, subject, original_source, analyzed_scope, trust_snapshot, evidence, created_at, created_xid) VALUES (key, d.id, d.project_id, d.release_id, (p ->> 'selection_name'), identity, (p['reference']), (p['selectors']), product, (fact ->> 'subject'), (fact ->> 'original_source'), (fact['analyzed_scope']), snapshot, (fact['evidence']), clock_timestamp(), CAST(pg_current_xact_id() AS TEXT)) ON CONFLICT DO NOTHING;
 SELECT ops.original_source_admission.* 
FROM ops.original_source_admission 
WHERE ops.original_source_admission.demand_id = d.id AND ops.original_source_admission.selection_name = (p ->> 'selection_name') INTO STRICT admitted;
 IF (admitted.id != key) THEN
  RAISE EXCEPTION USING MESSAGE = 'immutable original source admission changed', ERRCODE = 'P0001';
 END IF;
 IF (NOT ops.ddo_original_admission_valid(admitted)) THEN
  RAISE EXCEPTION USING MESSAGE = 'original source admission is revoked', ERRCODE = 'P0001';
 END IF;
 RETURN jsonb_build_object('payload', jsonb_build_object('admission_id', admitted.id, 'selection_name', admitted.selection_name, 'product_id', product, 'kind_contract', kind, 'subject', admitted.subject, 'subject_definition', fact ->> 'subject_definition', 'original_source', admitted.original_source, 'analyzed_scope', admitted.analyzed_scope, 'source_reference', identity, 'trust_snapshot', snapshot, 'evidence', admitted.evidence));
END

