DECLARE
 definition sem.data_operation_definition%ROWTYPE;
 witness jsonb;
 output jsonb;
 body jsonb;
 record jsonb;
 candidate jsonb;
 candidates jsonb;
 comparison jsonb;
 actual jsonb;
 expected jsonb;
 complete boolean;
 matched boolean;
BEGIN
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id INTO STRICT definition;
 IF (jsonb_array_length(coalesce(definition.support_contract['output_witnesses'], CAST('[]' AS JSONB))) > 0) THEN
  PERFORM ops.ddo_binding_body_access(r.binding, r.project_id);
 END IF;
 FOR witness IN SELECT witness_row.value 
FROM jsonb_array_elements(coalesce(definition.support_contract['output_witnesses'], CAST('[]' AS JSONB))) AS witness_row(value) LOOP
  SELECT coalesce(jsonb_agg(jsonb_build_object('product', kb.data_product.id, 'member', kb.data_product_member.member_id, 'reference', jsonb_build_array(kb.data_product.id, kb.data_product_member.member_id), 'kind_contract', coalesce(kb.data_product_member.kind_contract, kb.data_product.kind_contract), 'project_id', kb.data_product.project_id, 'subject', coalesce(kb.data_product_member.subject, kb.data_product.subject), 'subject_definition', coalesce(kb.data_product_member.subject_definition, kb.data_product.subject_definition), 'original_source', coalesce(kb.data_product_member.original_source, kb.data_product.original_source), 'analyzed_scope', coalesce(kb.data_product_member.analyzed_scope, kb.data_product.analyzed_scope), 'body', data.ddo_json(coalesce(kb.data_product_member.body, kb.data_product.canonical_body)))), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(r.binding['inputs']) AS input_row(value) JOIN kb.data_product ON kb.data_product.id = (input_row.value ->> 'product_id') LEFT OUTER JOIN kb.data_product_member ON kb.data_product_member.product_id = kb.data_product.id AND kb.data_product_member.member_id = (input_row.value ->> 'member_id') 
WHERE (input_row.value ->> 'role') = (witness ->> 'input_role') AND ((input_row.value ->> 'member_id') IS NULL OR kb.data_product_member.member_id IS NOT NULL) INTO candidates;
  FOR output IN SELECT output_row.value 
FROM jsonb_array_elements(completion['outputs']) AS output_row(value) 
WHERE (output_row.value ->> 'role') = (witness ->> 'output_role') LOOP
   body := output['product']['body'];
   IF ((output ->> 'member_id') IS NOT NULL) THEN
    SELECT member_row.value['body'] AS anon_1 
FROM jsonb_array_elements(output['product']['members']) AS member_row(value) 
WHERE (member_row.value ->> 'member_id') = (output ->> 'member_id') INTO STRICT body;
   END IF;
   FOR record IN SELECT record_row.value 
FROM data.ddo_witness_records(data.ddo_json(data.ddo_normalize(body)), witness ->> 'records') AS record_row(value) LOOP
    matched := false;
    FOR candidate IN SELECT candidate_row.value 
FROM jsonb_array_elements(candidates) AS candidate_row(value) LOOP
     complete := true;
     FOR comparison IN SELECT comparison_row.value 
FROM jsonb_array_elements(witness['comparisons']) AS comparison_row(value) LOOP
      actual := coalesce(record #> data.ddo_witness_path((comparison ->> 'output_field')), CAST('null' AS JSONB));
      IF (((comparison['input']) ->> 'projection') = 'selected-input') THEN
       expected := candidate[((comparison['input']) ->> 'field')];
      ELSE
       expected := coalesce(candidate['body'] #> data.ddo_witness_path(((comparison['input']) ->> 'field')), CAST('null' AS JSONB));
      END IF;
      IF (coalesce(expected, CAST('null' AS JSONB)) = CAST('null' AS JSONB) AND (comparison ->> 'encoding') = 'value' AND NOT (((comparison['input']) ->> 'projection') = 'selected-input' AND ((comparison['input']) ->> 'field') = 'member')) THEN
       complete := false;
       EXIT;
      END IF;
      IF ((comparison ->> 'encoding') != 'value') THEN
       IF (jsonb_typeof(actual) != 'string') THEN
        complete := false;
        EXIT;
       END IF;
       actual := CAST(actual #>> ARRAY[]::TEXT[] AS JSONB);
      END IF;
      IF ((comparison ->> 'encoding') = 'context-meaning-json') THEN
       expected := data.ddo_json_meaning(expected);
      END IF;
      IF (actual IS DISTINCT FROM expected) THEN
       complete := false;
       EXIT;
      END IF;
     END LOOP;
     IF (complete) THEN
      matched := true;
      EXIT;
     END IF;
    END LOOP;
    IF (NOT matched) THEN
     RAISE EXCEPTION USING MESSAGE = 'output witness has no complete selected input member: ' || coalesce((witness ->> 'output_role') || (witness ->> 'records'), '<NULL>'), ERRCODE = 'P0001';
    END IF;
   END LOOP;
  END LOOP;
 END LOOP;
END

