      END IF;
      IF (coalesce(expected, CAST('null' AS JSONB)) = CAST('null' AS JSONB) AND (comparison ->> 'encoding') = 'value' AND NOT (((comparison['input']) ->> 'projection') = 'selected-input' AND ((comparison['input']) ->> 'field') = 'member')) THEN
       complete := false;
       EXIT;
      END IF;
