CREATE OR REPLACE FUNCTION ops.ddo_attach_data_request(p_payload jsonb, p_read_trust jsonb, p_snapshot jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 o ops.data_obligation%ROWTYPE;
 d ops.data_demand%ROWTYPE;
 def sem.data_operation_definition%ROWTYPE;
 r ops.data_request%ROWTYPE;
 retained ops.data_completion_intent%ROWTYPE;
 current_task ops.task%ROWTYPE;
 binding_use ops.demand_use%ROWTYPE;
 boundary ops.data_demand_read%ROWTYPE;
 project data.project%ROWTYPE;
 p jsonb := p_payload;
 snapshot jsonb;
 read_trust jsonb;
 item jsonb;
 declared jsonb;
 key text;
 episode text;
 usekey text;
 retained_id text;
 task bigint;
 cnt bigint;
 invalid_current boolean;
 invalid_retained boolean;
 replace_capture boolean;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['obligation_id', 'request_meaning', 'binding', 'replicate'], ARRAY['rebind_derivation', 'request_key']);
 IF (((p['request_meaning']) ->> 0) = 'ddo') THEN
  IF (((p['request_meaning']) ->> 1) != 'semantic-request' OR ((p['request_meaning']) ->> 2) != '1' OR jsonb_array_length(p['request_meaning']) != 4) THEN
   RAISE EXCEPTION USING MESSAGE = 'invalid semantic request frame', ERRCODE = '23514';
  END IF;
  p := jsonb_set(p, ARRAY['request_meaning'], p['request_meaning'][3]);
 END IF;
 SELECT ops.data_obligation.* 
FROM ops.data_obligation 
WHERE ops.data_obligation.id = (p ->> 'obligation_id') INTO STRICT o;
 SELECT ops.data_demand.* 
FROM ops.data_demand 
WHERE ops.data_demand.id = o.demand_id INTO STRICT d;
 SELECT data.project.* 
FROM data.project 
WHERE data.project.project_id = d.project_id FOR SHARE INTO STRICT project;
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = d.release_id AND sem.data_operation_definition.operation_id = o.operation_id INTO STRICT def;
 PERFORM ops.ddo_require_subject_source(ops.ddo_release_subject_scopes(d.release_id), def.subject_definition, o.original_source);
 PERFORM ops.ddo_authorize(sem.data_kind_contract.universe) AS ddo_authorize_1 
FROM jsonb_array_elements(def.input_roles || def.output_roles) AS operation_role(value) JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = (operation_role.value ->> 'kind_contract');
 IF (coalesce(def.command_class = 'pdf', false)) THEN
  PERFORM ops.require_pdf_operation(d.release_id, 'retain_pdf_original');
 ELSE
  IF (coalesce(def.command_class = 'rich', false)) THEN
   IF (NOT pg_has_role(coalesce(nullif(current_setting('role'), 'none'), SESSION_USER), 'corpus_sem_writer', 'MEMBER')) THEN
    RAISE EXCEPTION USING MESSAGE = 'rich admission requires native write purpose', ERRCODE = '42501';
   END IF;
  ELSE
   IF (coalesce(def.command_class = 'policy', false) OR coalesce(def.command_class = 'structural', false) OR coalesce(def.command_class = 'operation_event', false)) THEN
    IF (NOT pg_has_role(coalesce(nullif(current_setting('role'), 'none'), SESSION_USER), 'corpus_sem_evaluator', 'MEMBER')) THEN
     RAISE EXCEPTION USING MESSAGE = 'policy authorization requires native evaluator purpose', ERRCODE = '42501';
    END IF;
   ELSE
    IF ((def.profile NOT IN ('derivation', 'discovery')) OR coalesce(def.support_contract['effects'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB)) THEN
     IF (NOT pg_has_role(coalesce(nullif(current_setting('role'), 'none'), SESSION_USER), 'corpus_sem_writer', 'MEMBER')) THEN
      RAISE EXCEPTION USING MESSAGE = 'external command requires native write purpose', ERRCODE = '42501';
     END IF;
     IF (def.profile != 'command' OR def.support_contract['external'] IS NULL OR coalesce(def.support_contract['effects'], CAST('[]' AS JSONB)) = CAST('[]' AS JSONB) OR (EXISTS (SELECT operation_effect.value 
FROM jsonb_array_elements(def.support_contract['effects']) AS operation_effect(value) 
WHERE operation_effect.value['authorization'] != CAST('["native-purpose:write"]' AS JSONB) OR (operation_effect.value ->> 'idempotency') != 'external-packet' OR (operation_effect.value ->> 'fulfillment') != 'native-publication-receipt'))) THEN
      RAISE EXCEPTION USING MESSAGE = 'operation profile requires its own declared command/read execution contract', ERRCODE = '23514';
     END IF;
    END IF;
   END IF;
  END IF;
 END IF;
 IF ((p ->> 'replicate') = '' OR ops.ddo_replicate_required((def.support_contract ->> 'replicate_policy')) IS DISTINCT FROM ((p ->> 'replicate') IS NOT NULL)) THEN
  RAISE EXCEPTION USING MESSAGE = 'replicate selection differs from declared operation policy', ERRCODE = '23514';
 END IF;
 PERFORM ops.ddo_fields(p['binding'], ARRAY['inputs', 'support', 'parameters', 'request_inputs', 'inference', 'populations', 'read_id'], ARRAY[]::TEXT[]);
 SELECT ops.data_demand_read.* 
FROM ops.data_demand_read 
WHERE ops.data_demand_read.id = ((p['binding']) ->> 'read_id') AND ops.data_demand_read.demand_id = d.id INTO STRICT boundary;
 read_trust := p_read_trust;
 IF (data.ddo_field(p['request_meaning'], 'recipe') IS DISTINCT FROM jsonb_build_array('string', def.recipe) OR data.ddo_field(p['request_meaning'], 'subject') IS DISTINCT FROM jsonb_build_array('string', o.subject) OR data.ddo_field(p['request_meaning'], 'subject_context') IS DISTINCT FROM data.ddo_json_meaning(jsonb_build_object('project_id', d.project_id, 'subject', o.subject, 'subject_definition', ops.ddo_operation_subject(d.release_id, o.operation_id), 'original_source', o.original_source, 'analyzed_scope', o.analyzed_scope)) OR data.ddo_field(p['request_meaning'], 'inputs') IS DISTINCT FROM data.ddo_normalize(p['binding']['request_inputs']) OR data.ddo_field(p['request_meaning'], 'parameters') IS DISTINCT FROM data.ddo_normalize(p['binding']['parameters']) OR data.ddo_field(p['request_meaning'], 'inference') IS DISTINCT FROM jsonb_build_array('string', ((p['binding']) ->> 'inference')) OR data.ddo_field(p['request_meaning'], 'execution_scope') IS DISTINCT FROM CASE WHEN ((def.support_contract ->> 'reuse_eligible') = 'false') THEN jsonb_build_array('string', d.id) ELSE NULL END) THEN
  RAISE EXCEPTION USING MESSAGE = 'request identity differs from compiled binding', ERRCODE = '23514';
 END IF;
 key := data.ddo_identity('semantic-request', p['request_meaning']);
 IF ((p ? 'request_key') AND (p ->> 'request_key') != key) THEN
  RAISE EXCEPTION USING MESSAGE = 'request key differs from canonical meaning', ERRCODE = '23514';
 END IF;
 snapshot := p_snapshot;
 PERFORM ops.ddo_require_active_demand(d.id);
 INSERT INTO ops.data_request (id, request_key, project_id, release_id, runtime_id, operation_id, recipe, subject, original_source, analyzed_scope, binding, replicate, generation, live_task_id) VALUES (key, key, d.project_id, d.release_id, d.runtime_id, o.operation_id, def.recipe, o.subject, o.original_source, o.analyzed_scope, (p['binding'] || jsonb_build_object('execution_profile', d.selection['execution_profile'])), (p ->> 'replicate'), 1, NULL) ON CONFLICT (request_key) DO NOTHING;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.request_key = key FOR UPDATE INTO STRICT r;
 IF ((r.project_id, r.recipe, r.subject, r.original_source, r.replicate) IS DISTINCT FROM (d.project_id, def.recipe, o.subject, o.original_source, (p ->> 'replicate')) OR r.analyzed_scope IS DISTINCT FROM o.analyzed_scope) THEN
  RAISE EXCEPTION USING MESSAGE = 'request custody or contract mismatch', ERRCODE = '23514';
 END IF;
 IF (NOT ops.ddo_bound_support_available(r, p['binding']['support'], p['binding'])) THEN
  RAISE EXCEPTION USING MESSAGE = 'selected support is unavailable or revoked', ERRCODE = '23514';
 END IF;
 PERFORM ops.ddo_validate_binding(r, o, def, p['binding'], p['request_meaning'], p ->> 'replicate');
 IF (NOT (ops.ddo_trust_snapshot_meaning(read_trust) @> ops.ddo_trust_snapshot_meaning(snapshot))) THEN
  RAISE EXCEPTION USING MESSAGE = 'binding trust snapshot changed after support locking', ERRCODE = '23514';
 END IF;
 PERFORM ops.ddo_require_binding(d.id, o.operation_id, o.subject, p['request_meaning'], p['binding'], read_trust, true);
 IF (jsonb_typeof(p['binding']['inputs']) != 'array') THEN
  RAISE EXCEPTION USING MESSAGE = 'input manifest must be an array', ERRCODE = '23514';
 END IF;
 FOR item IN SELECT manifest_input.value 
FROM jsonb_array_elements(p['binding']['inputs']) AS manifest_input(value) LOOP
  PERFORM ops.ddo_fields(item, ARRAY['role', 'position', 'multiplicity', 'product_id', 'support_derivation_ids', 'producer_output'], ARRAY['member_id']);
  SELECT input_role.value 
FROM jsonb_array_elements(def.input_roles) AS input_role(value) 
WHERE (input_role.value ->> 'name') = (item ->> 'role') INTO declared;
  PERFORM ops.ddo_authorize(sem.data_kind_contract.universe) AS ddo_authorize_1 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = (declared ->> 'kind_contract');
  IF (declared IS NULL OR NOT (EXISTS (SELECT input_product.id 
FROM kb.data_product AS input_product LEFT OUTER JOIN kb.data_product_member AS input_member ON input_member.product_id = input_product.id AND input_member.member_id = (item ->> 'member_id') JOIN sem.data_kind_release AS input_kind_release ON input_kind_release.kind_contract = CASE WHEN ((item ->> 'member_id') IS NULL) THEN input_product.kind_contract ELSE input_member.kind_contract END AND input_kind_release.release_id = d.release_id 
WHERE input_product.id = (item ->> 'product_id') AND input_product.project_id = d.project_id AND ops.ddo_binding_source(declared, jsonb_build_object('product', input_product.id, 'member', (item ->> 'member_id'), 'subject', coalesce(input_member.subject, input_product.subject), 'subject_definition', coalesce(input_member.subject_definition, input_product.subject_definition), 'original_source', input_product.original_source, 'analyzed_scope', coalesce(input_member.analyzed_scope, input_product.analyzed_scope), 'meaning_body', coalesce(input_member.body, input_product.canonical_body), 'support_references', (SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('kind', coalesce((input_support.value ->> 'kind'), 'computation'), 'derivation_id', (input_support.value ->> 'derivation_id'), 'admission_use_id', (input_support.value ->> 'admission_use_id')))), CAST('[]' AS JSONB)) AS coalesce_1 
FROM ops.ddo_input_support_refs(p['binding'], item) AS input_support(value)), 'support_evidence', jsonb_build_object('producer_output', item['producer_output'])), o.original_source, coalesce(d.selection['source_sets'], CAST('{}' AS JSONB))) AND ((item ->> 'member_id') IS NULL AND (declared['accepted_kind_contracts'] ? input_product.kind_contract) OR input_member.member_id IS NOT NULL AND (declared['accepted_kind_contracts'] ? input_member.kind_contract)))) OR CAST((item ->> 'position') AS INTEGER) < 0 OR CAST((item ->> 'multiplicity') AS INTEGER) < 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'input role/member/kind/source mismatch', ERRCODE = '23514';
  END IF;
  IF (NOT (EXISTS (SELECT input_support.value 
FROM ops.ddo_input_support_refs(p['binding'], item) AS input_support(value) 
WHERE coalesce((input_support.value ->> 'kind'), 'computation') = 'computation' OR (EXISTS (SELECT ops.original_source_admission.id 
FROM ops.original_source_admission 
WHERE ops.original_source_admission.id = (input_support.value ->> 'admission_id') AND ops.ddo_original_admission_valid(original_source_admission)))))) THEN
   RAISE EXCEPTION USING MESSAGE = 'input lacks selected authentic support', ERRCODE = '23514';
  END IF;
 END LOOP;
 FOR declared IN SELECT input_role.value 
FROM jsonb_array_elements(def.input_roles) AS input_role(value) LOOP
  SELECT coalesce(sum(CAST(manifest_input.value ->> 'multiplicity' AS INTEGER)), 0) AS coalesce_1 
FROM jsonb_array_elements(p['binding']['inputs']) AS manifest_input(value) 
WHERE (manifest_input.value ->> 'role') = (declared ->> 'name') INTO cnt;
  IF (cnt < coalesce(CAST((declared ->> 'minimum') AS INTEGER), 0) OR (declared ->> 'maximum') IS NOT NULL AND cnt > CAST((declared ->> 'maximum') AS INTEGER)) THEN
   RAISE EXCEPTION USING MESSAGE = 'input cardinality mismatch', ERRCODE = '23514';
  END IF;
 END LOOP;
 SELECT ops.data_derivation.id 
FROM ops.data_derivation 
WHERE ops.data_derivation.request_id = r.id AND (ops.data_derivation.generation = r.generation OR (def.support_contract ->> 'reuse_eligible') = 'true' AND (EXISTS (SELECT 1 
FROM ops.data_draft_consumption 
WHERE ops.data_draft_consumption.intent_id = ops.data_derivation.intent_id AND ops.data_draft_consumption.request_id = r.id AND ops.data_draft_consumption.generation = r.generation))) AND ops.ddo_node_valid('episode', ops.data_derivation.id) ORDER BY ops.data_derivation.id 
 LIMIT 1 INTO episode;
 IF (p ? 'rebind_derivation') THEN
  episode := p ->> 'rebind_derivation';
  IF (d.strength != 'value' OR (def.support_contract ->> 'reuse_eligible') = 'false' OR (def.support_contract ->> 'provenance') != 'value_substitution' OR NOT (EXISTS (SELECT producer.id 
FROM ops.data_derivation AS producer JOIN ops.data_request AS source_request ON source_request.id = producer.request_id 
WHERE producer.id = episode AND producer.outcome IN ('success', 'empty') AND source_request.request_key = r.request_key AND NOT (EXISTS (SELECT 1 AS anon_1 
FROM ops.data_revocation 
WHERE ops.data_revocation.scope = ops.ddo_scope(source_request.project_id, source_request.original_source) AND (ops.data_revocation.selector_kind = 'derivation' AND ops.data_revocation.selector = producer.id OR ops.data_revocation.selector_kind = 'recipe' AND ops.data_revocation.selector = producer.recipe OR ops.data_revocation.selector_kind = 'runtime' AND ops.data_revocation.selector = producer.runtime_id OR ops.data_revocation.selector_kind = 'product' AND (EXISTS (SELECT produced.product_id 
FROM ops.data_derivation_output AS produced 
WHERE produced.derivation_id = producer.id AND produced.product_id = ops.data_revocation.selector))))))) OR (EXISTS (SELECT input_role.value 
FROM jsonb_array_elements(def.input_roles) AS input_role(value) 
WHERE coalesce(input_role.value['identity_requirements'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB)))) THEN
   RAISE EXCEPTION USING MESSAGE = 'support substitution cannot rehabilitate this producer/contract', ERRCODE = '23514';
  END IF;
 END IF;
 IF (episode IS NULL) THEN
  IF (r.live_task_id IS NOT NULL) THEN
   SELECT ops.task.* 
FROM ops.task 
WHERE ops.task.id = r.live_task_id FOR UPDATE INTO STRICT current_task;
   SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.request_id = r.id AND ops.data_completion_intent.generation = r.generation AND NOT (EXISTS (SELECT ops.data_publication_receipt.intent_id 
FROM ops.data_publication_receipt 
WHERE ops.data_publication_receipt.intent_id = ops.data_completion_intent.id)) INTO retained;
   IF (retained.id IS NULL AND r.release_id = project.active_release_id AND r.release_id != d.release_id) THEN
    RAISE EXCEPTION USING MESSAGE = 'inactive demand cannot replace the active release generation', ERRCODE = '23514';
   END IF;
   replace_capture := retained.id IS NULL AND r.release_id != d.release_id AND d.release_id = project.active_release_id;
   invalid_current := NOT ops.ddo_support_available(r, r.binding['support']) OR (EXISTS (SELECT 1 AS anon_1 
FROM ops.data_revocation 
WHERE ops.data_revocation.scope = ops.ddo_scope(r.project_id, r.original_source) AND (ops.data_revocation.selector_kind = 'runtime' AND ops.data_revocation.selector = r.runtime_id OR ops.data_revocation.selector_kind = 'recipe' AND ops.data_revocation.selector = r.recipe)));
   invalid_retained := retained.id IS NOT NULL AND ((EXISTS (SELECT old_support.value 
FROM jsonb_array_elements(retained.payload['support']) AS old_support(value) 
WHERE CASE WHEN ((old_support.value ->> 'kind') IN ('original-source', 'authored')) THEN NOT (EXISTS (SELECT ops.original_source_admission.id 
FROM ops.original_source_admission 
WHERE ops.original_source_admission.id = (old_support.value ->> 'admission_id') AND ops.original_source_admission.source_reference = (old_support.value ->> 'source_reference') AND ops.ddo_original_admission_valid(original_source_admission))) WHEN ((old_support.value ->> 'admission_use_id') IS NULL) THEN NOT ops.ddo_node_valid('episode', (old_support.value ->> 'derivation_id')) ELSE NOT (EXISTS (SELECT ops.demand_use.id 
FROM ops.demand_use 
WHERE ops.demand_use.id = (old_support.value ->> 'admission_use_id') AND ops.demand_use.derivation_id = (old_support.value ->> 'derivation_id') AND ops.ddo_node_valid('use', ops.demand_use.id))) END)) OR (EXISTS (SELECT 1 AS anon_1 
FROM ops.data_revocation 
WHERE ops.data_revocation.scope = ops.ddo_scope(r.project_id, r.original_source) AND (ops.data_revocation.selector_kind = 'runtime' AND ops.data_revocation.selector = retained.runtime_id OR ops.data_revocation.selector_kind = 'recipe' AND ops.data_revocation.selector = r.recipe))));
   IF ((invalid_current OR invalid_retained OR replace_capture) AND current_task.status = 'running' AND (current_task.lease_until IS NULL OR current_task.lease_until > clock_timestamp())) THEN
    RAISE EXCEPTION USING MESSAGE = 'invalid current generation still has an active producer lease', ERRCODE = '23514';
   END IF;
   IF (current_task.status IN ('done', 'empty', 'failed', 'cancelled') OR (invalid_current OR invalid_retained OR replace_capture) AND (current_task.status = 'pending' OR current_task.status = 'running' AND current_task.lease_until <= clock_timestamp())) THEN
    IF (EXISTS (SELECT 1 AS anon_1 
FROM ops.data_revocation 
WHERE ops.data_revocation.scope = ops.ddo_scope(d.project_id, o.original_source) AND (ops.data_revocation.selector_kind = 'runtime' AND ops.data_revocation.selector = d.runtime_id OR ops.data_revocation.selector_kind = 'recipe' AND ops.data_revocation.selector = def.recipe))) THEN
     RAISE EXCEPTION USING MESSAGE = 'replacement runtime or recipe was directly revoked', ERRCODE = '23514';
    END IF;
    UPDATE ops.data_request SET release_id=d.release_id, runtime_id=d.runtime_id, binding=(p['binding'] || jsonb_build_object('execution_profile', d.selection['execution_profile'])), generation=(ops.data_request.generation + 1), live_task_id=NULL WHERE ops.data_request.id = r.id RETURNING ops.data_request.id, ops.data_request.request_key, ops.data_request.project_id, ops.data_request.release_id, ops.data_request.runtime_id, ops.data_request.operation_id, ops.data_request.recipe, ops.data_request.subject, ops.data_request.original_source, ops.data_request.analyzed_scope, ops.data_request.binding, ops.data_request.replicate, ops.data_request.generation, ops.data_request.live_task_id INTO r;
   END IF;
  END IF;
  IF (r.live_task_id IS NULL) THEN
   UPDATE ops.data_request SET release_id=d.release_id, runtime_id=d.runtime_id, binding=(p['binding'] || jsonb_build_object('execution_profile', d.selection['execution_profile'])) WHERE ops.data_request.id = r.id RETURNING ops.data_request.id, ops.data_request.request_key, ops.data_request.project_id, ops.data_request.release_id, ops.data_request.runtime_id, ops.data_request.operation_id, ops.data_request.recipe, ops.data_request.subject, ops.data_request.original_source, ops.data_request.analyzed_scope, ops.data_request.binding, ops.data_request.replicate, ops.data_request.generation, ops.data_request.live_task_id INTO r;
   INSERT INTO ops.task (release_id, data_request_id, data_generation, status, attempt, cost, priority, created_at) VALUES (r.release_id, r.id, r.generation, 'pending', 0, CAST('{}' AS JSONB), 0, clock_timestamp()) RETURNING ops.task.id INTO task;
   INSERT INTO ops.data_request_generation (request_id, generation, task_id) VALUES (r.id, r.generation, task);
   UPDATE ops.data_request SET live_task_id=task WHERE ops.data_request.id = r.id RETURNING ops.data_request.id, ops.data_request.request_key, ops.data_request.project_id, ops.data_request.release_id, ops.data_request.runtime_id, ops.data_request.operation_id, ops.data_request.recipe, ops.data_request.subject, ops.data_request.original_source, ops.data_request.analyzed_scope, ops.data_request.binding, ops.data_request.replicate, ops.data_request.generation, ops.data_request.live_task_id INTO r;
  END IF;
 ELSE
  PERFORM ops.ddo_require_consuming_episode(episode, jsonb_populate_record(r, jsonb_build_object('binding', p['binding'] || jsonb_build_object('execution_profile', d.selection['execution_profile']), 'release_id', d.release_id, 'runtime_id', d.runtime_id)));
 END IF;
 SELECT ops.data_completion_intent.id 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.request_id = r.id AND ops.data_completion_intent.generation = r.generation AND NOT (EXISTS (SELECT ops.data_publication_receipt.intent_id 
FROM ops.data_publication_receipt 
WHERE ops.data_publication_receipt.intent_id = ops.data_completion_intent.id)) INTO retained_id;
 usekey := 'use:' || ops.ddo_digest(jsonb_build_array(o.id, r.id, r.generation, episode, p['binding'], snapshot));
 INSERT INTO ops.demand_use (id, demand_id, obligation_id, fate, request_id, generation, derivation_id, selection, trust_snapshot, created_at, created_xid) VALUES (usekey, d.id, o.id, CASE WHEN (episode IS NULL) THEN 'attached' ELSE 'fulfilled' END, r.id, r.generation, episode, (p['binding']), snapshot, clock_timestamp(), CAST(pg_current_xact_id() AS TEXT)) ON CONFLICT DO NOTHING;
 SELECT original_use.* 
FROM ops.demand_use AS original_use 
WHERE original_use.request_id = r.id AND original_use.generation = r.generation AND original_use.selection = (r.binding - 'execution_profile') ORDER BY original_use.id 
 LIMIT 1 INTO STRICT binding_use;
 RETURN jsonb_build_object('payload', jsonb_build_object('request_id', r.id, 'release_id', r.release_id, 'runtime_id', r.runtime_id, 'binding', r.binding - 'execution_profile', 'binding_demand_id', binding_use.demand_id, 'binding_obligation_id', binding_use.obligation_id, 'generation', r.generation, 'task_id', r.live_task_id, 'fate', CASE WHEN (episode IS NULL) THEN 'attached' ELSE 'fulfilled' END, 'derivation_id', episode, 'use_id', usekey, 'trust_snapshot', snapshot, 'action', CASE WHEN (episode IS NOT NULL) THEN 'reuse' WHEN (retained_id IS NOT NULL) THEN 'reconcile' ELSE 'compute' END, 'retained_intent_id', retained_id));
END$$

