DECLARE
 tag text := left_value ->> 0;
 l numeric;
 r numeric;
 ordering integer;
BEGIN
 IF ((left_value ->> 0) = 'subject-context' OR (right_value ->> 0) = 'subject-context') THEN
  IF (comparison != 'equal' OR (left_value ->> 0) IS DISTINCT FROM 'subject-context' OR (right_value ->> 0) IS DISTINCT FROM 'subject-context') THEN
   RAISE EXCEPTION USING MESSAGE = 'context operands support equality only', ERRCODE = 'P0001';
  END IF;
  RETURN left_value[1] = right_value[1];
 END IF;
 IF (tag IS DISTINCT FROM (right_value ->> 0)) THEN
  RAISE EXCEPTION USING MESSAGE = 'binding operand type mismatch', ERRCODE = '23514';
 END IF;
 IF (comparison = 'equal') THEN
  IF (tag = 'float') THEN
   RETURN ops.ddo_binding_float((left_value ->> 1)) = ops.ddo_binding_float((right_value ->> 1));
  END IF;
  RETURN left_value = right_value;
 END IF;
 IF (tag IN ('integer', 'decimal', 'float')) THEN
  l := CASE WHEN (tag = 'float') THEN ops.ddo_binding_float(left_value ->> 1) ELSE CAST(left_value ->> 1 AS NUMERIC) END;
  r := CASE WHEN (tag = 'float') THEN ops.ddo_binding_float(right_value ->> 1) ELSE CAST(right_value ->> 1 AS NUMERIC) END;
  ordering := CASE WHEN (l < r) THEN -1 WHEN (l > r) THEN 1 ELSE 0 END;
 ELSE
  IF (tag = 'date') THEN
   ordering := CASE WHEN (CAST((left_value ->> 1) AS DATE) < CAST((right_value ->> 1) AS DATE)) THEN -1 WHEN (CAST((left_value ->> 1) AS DATE) > CAST((right_value ->> 1) AS DATE)) THEN 1 ELSE 0 END;
  ELSE
   IF (tag = 'datetime') THEN
    ordering := CASE WHEN (CAST((left_value ->> 1) AS TIMESTAMP WITH TIME ZONE) < CAST((right_value ->> 1) AS TIMESTAMP WITH TIME ZONE)) THEN -1 WHEN (CAST((left_value ->> 1) AS TIMESTAMP WITH TIME ZONE) > CAST((right_value ->> 1) AS TIMESTAMP WITH TIME ZONE)) THEN 1 ELSE 0 END;
   ELSE
    IF (tag = 'string') THEN
     ordering := CASE WHEN (((left_value ->> 1) COLLATE "C") < ((right_value ->> 1) COLLATE "C")) THEN -1 WHEN (((left_value ->> 1) COLLATE "C") > ((right_value ->> 1) COLLATE "C")) THEN 1 ELSE 0 END;
    ELSE
     RAISE EXCEPTION USING MESSAGE = format('binding range does not support type %s', coalesce(tag, '<NULL>')), ERRCODE = '23514';
    END IF;
   END IF;
  END IF;
 END IF;
 IF (comparison = 'lower') THEN
  RETURN ordering >= 0;
 ELSE
  IF (comparison = 'upper') THEN
   RETURN ordering <= 0;
  END IF;
 END IF;
 RAISE EXCEPTION USING MESSAGE = 'unsupported native binding comparison', ERRCODE = '23514';
END

