DECLARE
 digits text;
 exact_text text;
 fraction integer;
 exponent integer;
 shift integer;
 i integer;
 digit integer;
 result numeric := 0;
 signum integer := 1;
BEGIN
 PERFORM data.require_float_lexical(value);
 IF (left(value, 1) = '-') THEN
  signum := -1;
  value := substr(value, 2);
 END IF;
 exponent := CAST(split_part(value, 'p', 2) AS INTEGER);
 digits := substr(split_part(value, 'p', 1), 3);
 fraction := length(split_part(digits, '.', 2));
 digits := replace(digits, '.', '');
 FOR i IN SELECT hex_position.position 
FROM generate_series(1, length(digits)) AS hex_position(position) LOOP
  digit := strpos('0123456789abcdef', substr(digits, i, 1)) - 1;
  result := result * 16 + digit;
 END LOOP;
 shift := exponent - 4 * fraction;
 IF (shift >= 0) THEN
  RETURN signum * result * power(CAST(2 AS NUMERIC), shift);
 END IF;
 result := result * power(CAST(5 AS NUMERIC), -shift);
 exact_text := lpad(CAST(trunc(result) AS TEXT), -shift + 1, '0');
 IF (length(CAST(trunc(result) AS TEXT)) > -shift + 1) THEN
  exact_text := CAST(trunc(result) AS TEXT);
 END IF;
 exact_text := substr(exact_text, 1, length(exact_text) + shift) || '.' || substr(exact_text, length(exact_text) + shift + 1);
 RETURN signum * CAST(exact_text AS NUMERIC);
END

