DECLARE
 child jsonb;
 selected jsonb;
 choice text;
 matches integer := 0;
 active text[];
 role text;
 inactive text[] := ARRAY[]::TEXT[];
BEGIN
 IF ((node ->> 'operator') = 'choice') THEN
  choice := coalesce(node ->> 'selected', (context['choices']) ->> ((node ->> 'choice_parameter')));
  FOR child IN SELECT child_node.value 
FROM jsonb_array_elements(coalesce(node['children'], CAST('[]' AS JSONB))) AS child_node(value) LOOP
   IF (choice = ANY (ops.ddo_binding_roles(child))) THEN
    selected := child;
    matches := matches + 1;
   END IF;
  END LOOP;
  IF (matches != 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'native branch choice is not uniquely frozen', ERRCODE = 'P0001';
  END IF;
  active := ops.ddo_binding_roles(selected);
  FOR child IN SELECT child_node.value 
FROM jsonb_array_elements(coalesce(node['children'], CAST('[]' AS JSONB))) AS child_node(value) LOOP
   IF (child != selected) THEN
    FOR role IN SELECT child_role.value 
FROM unnest(ops.ddo_binding_roles(child)) AS child_role(value) LOOP
     IF (NOT (role = ANY (active))) THEN
      inactive := array_append(inactive, role);
     END IF;
    END LOOP;
   END IF;
  END LOOP;
  RETURN inactive || ops.ddo_binding_inactive(selected, context);
 END IF;
 FOR child IN SELECT child_node.value 
FROM jsonb_array_elements(coalesce(node['children'], CAST('[]' AS JSONB))) AS child_node(value) LOOP
  inactive := inactive || ops.ddo_binding_inactive(child, context);
 END LOOP;
 RETURN (SELECT coalesce(array_agg(DISTINCT inactive_name.value ORDER BY inactive_name.value), ARRAY[]::TEXT[]) AS coalesce_1 
FROM unnest(inactive) AS inactive_name(value));
END

