CREATE OR REPLACE FUNCTION ops.ddo_binding_inactive(node jsonb, context jsonb) RETURNS text[] LANGUAGE plpgsql IMMUTABLE RETURNS NULL ON NULL INPUT SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 child jsonb;
 selected jsonb;
 choice text;
 matches integer := 0;
 active text[];
 role text;
 inactive text[] := ARRAY[]::TEXT[];
BEGIN
 IF ((node ->> 'operator') = 'choice') THEN
  choice := coalesce(node ->> 'selected', (context['choices']) ->> ((node ->> 'choice_parameter')));
  FOR child IN SELECT child_node.value 
FROM jsonb_array_elements(coalesce(node['children'], CAST('[]' AS JSONB))) AS child_node(value) LOOP
   IF (choice = ANY (ops.ddo_binding_roles(child))) THEN
    selected := child;
    matches := matches + 1;
   END IF;
  END LOOP;
