  FOR child IN SELECT child_node.value 
FROM jsonb_array_elements(coalesce(node['children'], CAST('[]' AS JSONB))) AS child_node(value) LOOP
   IF (choice = ANY (ops.ddo_binding_roles(child))) THEN
    result := ops.ddo_binding_population_refs(child, context);
    matches := matches + 1;
   END IF;
  END LOOP;
  IF (matches != 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'population scope branch is not uniquely frozen', ERRCODE = 'P0001';
  END IF;
  RETURN result;
 END IF;
 IF ((node ->> 'operator') IN ('forall', 'absent')) THEN
  SELECT coalesce(array_agg(role_node.value #>> ARRAY[]::TEXT[]), ARRAY[]::TEXT[]) AS coalesce_1 
FROM jsonb_array_elements(node['roles']) AS role_node(value) INTO names;
  IF (cardinality(names) = 0) THEN
   SELECT coalesce(array_agg(role_definition.value ->> 'name'), ARRAY[]::TEXT[]) AS coalesce_1 
FROM jsonb_array_elements(context['roledefs']) AS role_definition(value) INTO names;
  END IF;
  FOR name IN SELECT role_name.value 
FROM unnest(names) AS role_name(value) LOOP
   result := jsonb_set(result, ARRAY[name], node['population']);
  END LOOP;
 END IF;
 FOR item IN SELECT operand_node.value 
FROM jsonb_array_elements(coalesce(node['operands'], CAST('[]' AS JSONB))) AS operand_node(value) 
WHERE (operand_node.value ->> 'kind') = 'population' LOOP
  IF (((node ->> 'operator') NOT IN ('membership', 'covers'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'unsupported population operand scope', ERRCODE = 'P0001';
  END IF;
  names := ops.ddo_binding_roles(jsonb_set(node, ARRAY['children'], CAST('[]' AS JSONB)));
  IF (cardinality(names) = 0) THEN
   RAISE EXCEPTION USING MESSAGE = 'population operand lacks an identity-bearing role', ERRCODE = 'P0001';
  END IF;
  FOR name IN SELECT role_name.value 
FROM unnest(names) AS role_name(value) LOOP
   IF ((result ? name) AND (result ->> name) IS DISTINCT FROM (item ->> 'name')) THEN
    RAISE EXCEPTION USING MESSAGE = 'one role cannot carry two population scopes', ERRCODE = 'P0001';
   END IF;
   result := jsonb_set(result, ARRAY[name], item['name']);
  END LOOP;
 END LOOP;
 FOR child IN SELECT child_node.value 
FROM jsonb_array_elements(coalesce(node['children'], CAST('[]' AS JSONB))) AS child_node(value) LOOP
  refs := ops.ddo_binding_population_refs(child, context);
  FOR entry_key, entry_value IN SELECT population_reference.key, population_reference.value 
FROM jsonb_each(refs) AS population_reference(key, value) LOOP
   IF ((result ? entry_key) AND result[entry_key] IS DISTINCT FROM entry_value) THEN
    RAISE EXCEPTION USING MESSAGE = 'one role cannot carry two population scopes', ERRCODE = 'P0001';
   END IF;
   result := jsonb_set(result, ARRAY[entry_key], entry_value);
  END LOOP;
 END LOOP;
 RETURN result;
END

