DECLARE
 lexical text;
 tag text := kind;
BEGIN
 IF (value IS NULL OR value = CAST('null' AS JSONB)) THEN
  RAISE EXCEPTION USING MESSAGE = 'unknown or null binding operand', ERRCODE = '23514';
 END IF;
 IF (kind IN ('uri', 'uriorcurie', 'bytes')) THEN
  tag := 'string';
 END IF;
 IF (kind = 'double') THEN
  tag := 'float';
 END IF;
 IF (tag IN ('string', 'date', 'datetime', 'float')) THEN
  IF (jsonb_typeof(value) != 'string') THEN
   RAISE EXCEPTION USING MESSAGE = 'typed binding string representation required', ERRCODE = '23514';
  END IF;
  lexical := value #>> ARRAY[]::TEXT[];
  IF (tag = 'float') THEN
   PERFORM data.require_float_lexical(lexical);
  END IF;
  RETURN data.ddo_normalize(pg_catalog.jsonb_build_array(tag, lexical));
 ELSE
  IF (tag = 'boolean') THEN
   IF (jsonb_typeof(value) != 'boolean') THEN
    RAISE EXCEPTION USING MESSAGE = 'typed boolean operand required', ERRCODE = '23514';
   END IF;
   RETURN pg_catalog.jsonb_build_array(tag, value);
  ELSE
   IF (tag IN ('integer', 'decimal')) THEN
    IF (jsonb_typeof(value) != 'number' OR tag = 'integer' AND CAST(value #>> ARRAY[]::TEXT[] AS NUMERIC) != trunc(CAST(value #>> ARRAY[]::TEXT[] AS NUMERIC))) THEN
     RAISE EXCEPTION USING MESSAGE = 'typed numeric operand required', ERRCODE = '23514';
    END IF;
    RETURN data.ddo_normalize(pg_catalog.jsonb_build_array(tag, value #>> ARRAY[]::TEXT[]));
   ELSE
    IF (tag = 'json') THEN
     RETURN pg_catalog.jsonb_build_array('json', value);
    END IF;
   END IF;
  END IF;
 END IF;
