DECLARE
 association jsonb;
 path text;
 part text;
 target text;
BEGIN
 IF ((roledef ->> 'subject_target') = 'source-set') THEN
  IF (((roledef['support']) ->> 'source_set') IS NULL OR (roledef ->> 'subject_field') IS NOT NULL) THEN
   RAISE EXCEPTION USING MESSAGE = 'source-set association lacks exact declared scope', ERRCODE = 'P0001';
  END IF;
  RETURN true;
 ELSE
  IF (coalesce((roledef ->> 'subject_target'), 'subject') = 'original-source') THEN
   IF ((roledef ->> 'subject_field') IS NULL OR consumer_source IS NULL) THEN
    RAISE EXCEPTION USING MESSAGE = 'original-source association lacks exact context', ERRCODE = 'P0001';
   END IF;
   target := consumer_source;
  ELSE
   IF (coalesce((roledef ->> 'subject_target'), 'subject') = 'subject') THEN
    target := consumer_subject;
   ELSE
    RAISE EXCEPTION USING MESSAGE = 'unsupported role subject association target', ERRCODE = 'P0001';
   END IF;
  END IF;
 END IF;
 IF ((roledef ->> 'subject_field') IS NULL) THEN
  RETURN (row_value ->> 'subject') = target;
 END IF;
 path := roledef ->> 'subject_field';
 association := row_value['meaning_body'];
 IF (left(path, 1) = '/') THEN
  FOR part IN SELECT subject_path.value 
FROM unnest(string_to_array(substr(path, 2), '/')) AS subject_path(value) LOOP
   association := data.ddo_field(association, replace(replace(part, '~1', '/'), '~0', '~'));
  END LOOP;
 ELSE
  association := data.ddo_field(association, path);
 END IF;
 RETURN (association ->> 0) = 'string' AND (association ->> 1) = target;
END

