DECLARE
 operator text := node ->> 'operator';
 child jsonb;
 selected jsonb;
 row_value jsonb;
 other_row jsonb;
 a jsonb;
 b jsonb;
 c jsonb;
 operands jsonb;
 operand jsonb;
 population jsonb;
 assignment jsonb;
 altered jsonb;
 role text;
 choice text;
 names text[];
 active text[];
 matching integer := 0;
 i integer;
 j integer;
 total bigint;
BEGIN
 IF (operator IS NULL OR (operator NOT IN ('scan', 'join', 'equal', 'literal', 'same', 'distinct', 'cardinality', 'collection', 'all', 'choice', 'optional', 'forall', 'absent', 'range', 'membership', 'covers'))) THEN
  RAISE EXCEPTION USING MESSAGE = format('unsupported native binding operator %s', operator), ERRCODE = '23514';
 END IF;
 IF (operator = 'choice') THEN
  IF ((node ->> 'selected') IS NOT NULL AND (node ->> 'choice_parameter') IS NOT NULL) THEN
   RAISE EXCEPTION USING MESSAGE = 'ambiguous native branch selector', ERRCODE = 'P0001';
  END IF;
  choice := coalesce(node ->> 'selected', (context['choices']) ->> ((node ->> 'choice_parameter')));
  IF (choice IS NULL) THEN
   RAISE EXCEPTION USING MESSAGE = 'missing frozen native branch selector', ERRCODE = 'P0001';
  END IF;
  FOR child IN SELECT child_node.value 
FROM jsonb_array_elements(coalesce(node['children'], CAST('[]' AS JSONB))) AS child_node(value) LOOP
   IF (choice = ANY (ops.ddo_binding_roles(child))) THEN
    selected := child;
    matching := matching + 1;
   END IF;
  END LOOP;
  IF (matching != 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'native choice does not select exactly one declared branch', ERRCODE = 'P0001';
  END IF;
  active := ops.ddo_binding_roles(selected);
  FOR child IN SELECT child_node.value 
FROM jsonb_array_elements(coalesce(node['children'], CAST('[]' AS JSONB))) AS child_node(value) LOOP
   IF (child = selected) THEN
    CONTINUE;
   END IF;
   FOR role IN SELECT child_role.value 
FROM unnest(ops.ddo_binding_roles(child)) AS child_role(value) LOOP
    IF (NOT (role = ANY (active)) AND jsonb_array_length(coalesce(context['roles'][role], CAST('[]' AS JSONB))) != 0) THEN
     RETURN false;
    END IF;
   END LOOP;
  END LOOP;
  RETURN ops.ddo_binding_test(selected, context);
 END IF;
 IF (operator = 'optional' AND ops.ddo_binding_missing(node, context)) THEN
  RETURN true;
 END IF;
 IF (operator = 'absent') THEN
  IF (EXISTS (WITH RECURSIVE descendants(n) AS 
(SELECT child_node.value AS n 
FROM jsonb_array_elements(coalesce(node['children'], CAST('[]' AS JSONB))) AS child_node(value) UNION ALL SELECT descendant_child.value AS value 
FROM descendants JOIN LATERAL jsonb_array_elements(coalesce(descendants.n['children'], CAST('[]' AS JSONB))) AS descendant_child(value) ON true)
 SELECT descendants.n 
FROM descendants 
WHERE (descendants.n ->> 'operator') IS NULL OR ((descendants.n ->> 'operator') NOT IN ('all', 'scan', 'equal', 'join', 'literal', 'range', 'membership', 'same', 'distinct', 'optional')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'absence children must be row predicates, not nested aggregate or branch scopes', ERRCODE = 'P0001';
  END IF;
  SELECT coalesce(array_agg(node_role.value), ARRAY[]::TEXT[]) AS coalesce_1 
FROM jsonb_array_elements_text(coalesce(node['roles'], CAST('[]' AS JSONB))) AS node_role(value) INTO names;
  IF (cardinality(names) != 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'native absence requires one qualified role', ERRCODE = 'P0001';
  END IF;
  role := names[1];
  population := context['populations'][(node ->> 'population')];
  IF (population IS NULL OR (population ->> 'complete') IS DISTINCT FROM 'true') THEN
   RAISE EXCEPTION USING MESSAGE = 'native absence requires closed population', ERRCODE = 'P0001';
  END IF;
  IF (context['witnesses'][role] IS DISTINCT FROM population) THEN
   RAISE EXCEPTION USING MESSAGE = 'native absence witness differs from named population', ERRCODE = 'P0001';
  END IF;
  IF (jsonb_array_length(coalesce(context['roles'][role], CAST('[]' AS JSONB))) != 0) THEN
   RETURN false;
  END IF;
  IF (EXISTS (SELECT population_member.value 
FROM jsonb_array_elements_text(population['members']) AS population_member(value) 
WHERE NOT (EXISTS (SELECT candidate.value 
FROM jsonb_array_elements(context['universe']) AS candidate(value) 
WHERE (candidate.value ->> 'member') = population_member.value AND ((SELECT role_definition.value 
FROM jsonb_array_elements(context['roledefs']) AS role_definition(value) 
WHERE (role_definition.value ->> 'name') = role)['accepted_kind_contracts'] ? (candidate.value ->> 'kind_contract')) AND ops.ddo_binding_subject((SELECT role_definition.value 
FROM jsonb_array_elements(context['roledefs']) AS role_definition(value) 
WHERE (role_definition.value ->> 'name') = role), candidate.value, (context ->> 'subject'), (context ->> 'original_source')) AND ops.ddo_binding_source((SELECT role_definition.value 
FROM jsonb_array_elements(context['roledefs']) AS role_definition(value) 
WHERE (role_definition.value ->> 'name') = role), candidate.value, (context ->> 'original_source'), context['source_sets']) AND ops.ddo_binding_population_product(population, candidate.value))))) THEN
   RAISE EXCEPTION USING MESSAGE = 'negative population lacks admitted candidate facts', ERRCODE = 'P0001';
  END IF;
  FOR row_value IN SELECT candidate.value 
FROM jsonb_array_elements(context['universe']) AS candidate(value) 
WHERE ((SELECT role_definition.value 
FROM jsonb_array_elements(context['roledefs']) AS role_definition(value) 
WHERE (role_definition.value ->> 'name') = role)['accepted_kind_contracts'] ? (candidate.value ->> 'kind_contract')) AND ops.ddo_binding_subject((SELECT role_definition.value 
FROM jsonb_array_elements(context['roledefs']) AS role_definition(value) 
WHERE (role_definition.value ->> 'name') = role), candidate.value, (context ->> 'subject'), (context ->> 'original_source')) AND ops.ddo_binding_source((SELECT role_definition.value 
FROM jsonb_array_elements(context['roledefs']) AS role_definition(value) 
WHERE (role_definition.value ->> 'name') = role), candidate.value, (context ->> 'original_source'), context['source_sets']) AND ops.ddo_binding_population_product(population, candidate.value) AND (population['members'] ? (candidate.value ->> 'member')) LOOP
   altered := jsonb_set(context, ARRAY['roles', role], jsonb_build_array(row_value));
   matching := 1;
   FOR child IN SELECT child_node.value 
FROM jsonb_array_elements(coalesce(node['children'], CAST('[]' AS JSONB))) AS child_node(value) LOOP
    IF (NOT ops.ddo_binding_test(child, altered)) THEN
     matching := 0;
    END IF;
   END LOOP;
   IF (matching = 1) THEN
    RETURN false;
   END IF;
  END LOOP;
  RETURN true;
 END IF;
 FOR child IN SELECT child_node.value 
FROM jsonb_array_elements(coalesce(node['children'], CAST('[]' AS JSONB))) AS child_node(value) LOOP
  IF (NOT ops.ddo_binding_test(child, context)) THEN
   RETURN false;
  END IF;
 END LOOP;
 SELECT coalesce(array_agg(node_role.value), ARRAY[]::TEXT[]) AS coalesce_1 
FROM jsonb_array_elements_text(coalesce(node['roles'], CAST('[]' AS JSONB))) AS node_role(value) INTO names;
 IF (operator IN ('cardinality', 'collection', 'forall') AND cardinality(names) = 0) THEN
  SELECT coalesce(array_agg(role_definition.value ->> 'name'), ARRAY[]::TEXT[]) AS coalesce_1 
FROM jsonb_array_elements(context['roledefs']) AS role_definition(value) INTO names;
 END IF;
 IF (operator IN ('scan', 'all', 'optional')) THEN
  RETURN true;
 END IF;
 IF (operator IN ('cardinality', 'collection', 'forall')) THEN
  FOR role IN SELECT role_name.value 
FROM unnest(names) AS role_name(value) LOOP
   SELECT coalesce(sum(CAST(selected_row.value ->> 'multiplicity' AS BIGINT)), 0) AS coalesce_1 
FROM jsonb_array_elements(coalesce(context['roles'][role], CAST('[]' AS JSONB))) AS selected_row(value) INTO total;
   IF (operator = 'cardinality') THEN
    IF ((node ->> 'minimum') IS NOT NULL AND total < CAST((node ->> 'minimum') AS BIGINT)) THEN
     RETURN false;
    END IF;
    IF ((node ->> 'maximum') IS NOT NULL AND total > CAST((node ->> 'maximum') AS BIGINT)) THEN
     RETURN false;
    END IF;
   END IF;
   IF (operator = 'collection') THEN
    SELECT role_definition.value 
FROM jsonb_array_elements(context['roledefs']) AS role_definition(value) 
WHERE (role_definition.value ->> 'name') = role INTO STRICT selected;
    IF ((node ->> 'collection') IS DISTINCT FROM (selected ->> 'collection')) THEN
     RAISE EXCEPTION USING MESSAGE = 'native collection differs from role', ERRCODE = 'P0001';
    END IF;
   END IF;
   IF (operator = 'forall') THEN
    population := context['populations'][(node ->> 'population')];
    IF (population IS NULL OR (population ->> 'complete') IS DISTINCT FROM 'true') THEN
     RAISE EXCEPTION USING MESSAGE = 'native universal binding requires closed population', ERRCODE = 'P0001';
    END IF;
    IF (context['witnesses'][role] IS DISTINCT FROM population) THEN
     RAISE EXCEPTION USING MESSAGE = 'native universal witness differs from named population', ERRCODE = 'P0001';
    END IF;
    IF ((EXISTS (SELECT selected_row.value 
FROM jsonb_array_elements(coalesce(context['roles'][role], CAST('[]' AS JSONB))) AS selected_row(value) 
WHERE NOT (population['members'] ? (selected_row.value ->> 'member')) OR NOT ops.ddo_binding_population_product(population, selected_row.value))) OR (EXISTS (SELECT population_member.value 
FROM jsonb_array_elements_text(population['members']) AS population_member(value) 
WHERE NOT (EXISTS (SELECT selected_row.value 
FROM jsonb_array_elements(coalesce(context['roles'][role], CAST('[]' AS JSONB))) AS selected_row(value) 
WHERE (selected_row.value ->> 'member') = population_member.value AND ops.ddo_binding_population_product(population, selected_row.value)))))) THEN
     RETURN false;
    END IF;
   END IF;
  END LOOP;
  RETURN true;
 END IF;
 IF (operator IN ('same', 'distinct')) THEN
  IF (cardinality(names) < 2) THEN
   RAISE EXCEPTION USING MESSAGE = 'native identity predicate requires two roles', ERRCODE = 'P0001';
  END IF;
  FOR i IN SELECT left_position.position 
FROM generate_series(1, cardinality(names)) AS left_position(position) LOOP
   FOR j IN SELECT right_position.position 
FROM generate_series(i + 1, cardinality(names)) AS right_position(position) LOOP
    FOR row_value IN SELECT left_row.value 
FROM jsonb_array_elements(context['roles'][(names[i])]) AS left_row(value) LOOP
     FOR other_row IN SELECT right_row.value 
FROM jsonb_array_elements(context['roles'][(names[j])]) AS right_row(value) LOOP
      IF (operator = 'same' AND jsonb_build_array(row_value['product'], row_value['member']) != jsonb_build_array(other_row['product'], other_row['member']) OR operator = 'distinct' AND jsonb_build_array(row_value['product'], row_value['member']) = jsonb_build_array(other_row['product'], other_row['member'])) THEN
       RETURN false;
      END IF;
     END LOOP;
    END LOOP;
   END LOOP;
  END LOOP;
  RETURN true;
 END IF;
 operands := coalesce(node['operands'], CAST('[]' AS JSONB));
 IF (jsonb_array_length(operands) = 0) THEN
  FOR operand IN SELECT node_field.value 
FROM jsonb_array_elements(coalesce(node['fields'], CAST('[]' AS JSONB))) AS node_field(value) LOOP
   operands := operands || jsonb_build_array(jsonb_build_object('kind', 'field', 'field', operand));
  END LOOP;
 END IF;
 IF (operator = 'covers') THEN
  IF (jsonb_array_length(operands) != 2 OR ((operands[0]) ->> 'kind') != 'field' OR (((operands[1]) ->> 'kind') NOT IN ('parameter', 'literal', 'population'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'invalid native coverage operands', ERRCODE = 'P0001';
  END IF;
  a := ops.ddo_binding_values(operands[0], context);
  b := ops.ddo_binding_values(operands[1], context);
  FOR operand IN SELECT expected_value.value 
FROM jsonb_array_elements(b) AS expected_value(value) LOOP
   IF (NOT (EXISTS (SELECT actual_value.value 
FROM jsonb_array_elements(a) AS actual_value(value) 
WHERE ops.ddo_binding_compare(actual_value.value, operand, 'equal')))) THEN
    RETURN false;
   END IF;
  END LOOP;
  RETURN true;
 END IF;
 IF (operator = 'literal') THEN
  IF (jsonb_array_length(operands) != 1 OR node['value']['json'] IS NULL) THEN
   RAISE EXCEPTION USING MESSAGE = 'invalid native literal predicate', ERRCODE = 'P0001';
  END IF;
  operands := operands || jsonb_build_array(jsonb_build_object('kind', 'literal', 'value_type', ((node['value']['json']) ->> 0), 'value', node['value']));
 END IF;
 FOR operand IN SELECT operand_row.value 
FROM jsonb_array_elements(operands) AS operand_row(value) 
WHERE (operand_row.value ->> 'kind') = 'population' LOOP
  IF ((operator NOT IN ('membership', 'covers'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'native population operands are membership/coverage universes', ERRCODE = 'P0001';
  END IF;
  population := context['populations'][(operand ->> 'name')];
  names := ops.ddo_binding_roles(jsonb_set(node, ARRAY['children'], CAST('[]' AS JSONB)));
  IF (cardinality(names) = 0) THEN
   RAISE EXCEPTION USING MESSAGE = 'population operand requires an identity-bearing input role', ERRCODE = 'P0001';
  END IF;
  FOR role IN SELECT role_name.value 
FROM unnest(names) AS role_name(value) LOOP
   IF (context['witnesses'][role] IS DISTINCT FROM population) THEN
    RAISE EXCEPTION USING MESSAGE = 'native membership witness differs from named population', ERRCODE = 'P0001';
   END IF;
   IF (EXISTS (SELECT selected_row.value 
FROM jsonb_array_elements(coalesce(context['roles'][role], CAST('[]' AS JSONB))) AS selected_row(value) 
WHERE NOT ops.ddo_binding_population_product(population, selected_row.value))) THEN
    RETURN false;
   END IF;
  END LOOP;
 END LOOP;
 FOR assignment IN SELECT assignment_row.value 
FROM ops.ddo_binding_assignments(node, context) AS assignment_row(value) LOOP
  a := ops.ddo_binding_values(operands[0], assignment);
  IF (jsonb_array_length(a) != 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'native scalar predicate requires one operand value', ERRCODE = 'P0001';
  END IF;
  IF (operator IN ('equal', 'join', 'literal')) THEN
   IF (jsonb_array_length(operands) < 2) THEN
    RAISE EXCEPTION USING MESSAGE = 'invalid native equality predicate', ERRCODE = 'P0001';
   END IF;
   FOR i IN SELECT operand_position.position 
FROM generate_series(1, jsonb_array_length(operands) - 1) AS operand_position(position) LOOP
    b := ops.ddo_binding_values(operands[i], assignment);
    IF (jsonb_array_length(b) != 1) THEN
     RAISE EXCEPTION USING MESSAGE = 'native equality requires scalar operands', ERRCODE = 'P0001';
    END IF;
    IF (NOT ops.ddo_binding_compare(a[0], b[0], 'equal')) THEN
     RETURN false;
    END IF;
   END LOOP;
  ELSE
   IF (operator = 'range') THEN
    IF (jsonb_array_length(operands) != 3) THEN
     RAISE EXCEPTION USING MESSAGE = 'invalid native range', ERRCODE = 'P0001';
    END IF;
    b := ops.ddo_binding_values(operands[1], assignment);
    c := ops.ddo_binding_values(operands[2], assignment);
    IF (jsonb_array_length(b) != 1 OR jsonb_array_length(c) != 1) THEN
     RAISE EXCEPTION USING MESSAGE = 'native range requires scalar bounds', ERRCODE = 'P0001';
    END IF;
    IF (NOT ops.ddo_binding_compare(a[0], b[0], 'lower') OR NOT ops.ddo_binding_compare(a[0], c[0], 'upper')) THEN
     RETURN false;
    END IF;
   ELSE
    IF (operator = 'membership') THEN
     IF (jsonb_array_length(operands) != 2 OR ((operands[1]) ->> 'kind') = 'field') THEN
      RAISE EXCEPTION USING MESSAGE = 'invalid native membership universe', ERRCODE = 'P0001';
     END IF;
     b := ops.ddo_binding_values(operands[1], assignment);
     matching := 0;
     FOR c IN SELECT expected_value.value 
FROM jsonb_array_elements(b) AS expected_value(value) LOOP
      IF (ops.ddo_binding_compare(a[0], c, 'equal')) THEN
       matching := 1;
      END IF;
     END LOOP;
     IF (matching = 0) THEN
      RETURN false;
     END IF;
    ELSE
     IF (true) THEN
      RAISE EXCEPTION USING MESSAGE = 'unsupported native predicate', ERRCODE = '23514';
     END IF;
    END IF;
   END IF;
  END IF;
 END LOOP;
 RETURN true;
END

