DECLARE
 kind_row jsonb;
 facts jsonb;
 primitive text;
BEGIN
 IF (declared = 'subject-context') THEN
  RETURN declared;
 END IF;
 IF (declared LIKE 'primitive:%') THEN
  primitive := substr(declared, 11);
 ELSE
  SELECT model_kind.value 
FROM jsonb_array_elements(context['model']['kinds']) AS model_kind(value) 
WHERE (model_kind.value ->> 'semantic_id') = declared OR (model_kind.value ->> 'name') = declared INTO kind_row;
  IF (kind_row IS NULL) THEN
   RAISE EXCEPTION USING MESSAGE = format('unknown native binding type %s', declared), ERRCODE = '23514';
  END IF;
  facts := kind_row['facts']['json'];
  primitive := coalesce(facts ->> 'primitive', facts ->> 'effective_primitive');
  IF (primitive IS NULL AND (kind_row ->> 'category') IN ('class', 'enum')) THEN
   primitive := 'string';
  END IF;
 END IF;
 primitive := CASE primitive WHEN 'str' THEN 'string' WHEN 'int' THEN 'integer' WHEN 'bool' THEN 'boolean' WHEN 'Decimal' THEN 'decimal' ELSE primitive END;
 IF (primitive IN ('string', 'uri', 'uriorcurie', 'integer', 'boolean', 'float', 'double', 'decimal', 'date', 'datetime', 'bytes', 'json')) THEN
  RETURN primitive;
 END IF;
 RAISE EXCEPTION USING MESSAGE = format('unsupported native binding type %s', declared), ERRCODE = '23514';
END

