DECLARE
 source text := operand ->> 'kind';
 kind text;
 expected text;
 item jsonb;
 roledef jsonb;
 field jsonb;
 raw jsonb;
 property jsonb;
 population jsonb;
 result jsonb := CAST('[]' AS JSONB);
BEGIN
 IF (source = 'field') THEN
  field := operand['field'];
  SELECT declared_role.value 
FROM jsonb_array_elements(context['roledefs']) AS declared_role(value) 
WHERE (declared_role.value ->> 'name') = (field ->> 'role') INTO STRICT roledef;
  IF ((field ->> 'projection') != (roledef ->> 'kind') AND NOT (EXISTS (SELECT declared_kind.value 
FROM jsonb_array_elements(context['model']['kinds']) AS declared_kind(value) 
WHERE (declared_kind.value ->> 'semantic_id') = (roledef ->> 'kind') AND (declared_kind.value ->> 'name') = (field ->> 'projection')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'native binding projection differs from qualified role', ERRCODE = 'P0001';
  END IF;
  IF ((field ->> 'field') IN ('@product', '@member')) THEN
   kind := ops.ddo_binding_type(context, coalesce(operand ->> 'value_type', 'primitive:string'));
   IF (kind != 'string') THEN
    RAISE EXCEPTION USING MESSAGE = 'native header binding field requires string type', ERRCODE = 'P0001';
   END IF;
   FOR item IN SELECT role_member.value 
FROM jsonb_array_elements(coalesce(context['roles'][(field ->> 'role')], CAST('[]' AS JSONB))) AS role_member(value) LOOP
    result := result || jsonb_build_array(ops.ddo_binding_scalar(item[substr((field ->> 'field'), 2)], kind));
   END LOOP;
   RETURN result;
  END IF;
  IF ((field ->> 'field') = '@context') THEN
   IF ((operand ->> 'value_type') IS DISTINCT FROM 'subject-context' OR nullif((context ->> 'project_id'), '') IS NULL) THEN
    RAISE EXCEPTION USING MESSAGE = 'native qualified context lacks project/type', ERRCODE = 'P0001';
   END IF;
   FOR item IN SELECT role_member.value 
FROM jsonb_array_elements(coalesce(context['roles'][(field ->> 'role')], CAST('[]' AS JSONB))) AS role_member(value) LOOP
    result := result || jsonb_build_array(jsonb_build_array('subject-context', jsonb_build_object('project_id', (context ->> 'project_id'), 'subject', (item ->> 'subject'), 'original_source', (item ->> 'original_source'), 'analyzed_scope', item['analyzed_scope'], 'subject_definition', (item ->> 'subject_definition'))));
   END LOOP;
   RETURN result;
  END IF;
  SELECT declared_kind.value 
FROM jsonb_array_elements(context['model']['kinds']) AS declared_kind(value) 
WHERE (declared_kind.value ->> 'semantic_id') = ((roledef ->> 'kind') || '/property/' || (field ->> 'field')) INTO STRICT property;
  expected := (property['facts']['json']) ->> 'range';
  kind := ops.ddo_binding_type(context, coalesce(operand ->> 'value_type', expected));
  IF ((operand ? 'value_type') AND ops.ddo_binding_type(context, expected) != kind) THEN
   RAISE EXCEPTION USING MESSAGE = 'native binding field type differs', ERRCODE = 'P0001';
  END IF;
  FOR item IN SELECT role_member.value 
FROM jsonb_array_elements(coalesce(context['roles'][(field ->> 'role')], CAST('[]' AS JSONB))) AS role_member(value) LOOP
   raw := data.ddo_field(item['meaning_body'], field ->> 'field');
   result := result || jsonb_build_array(ops.ddo_binding_typed(raw, kind));
  END LOOP;
  RETURN result;
 END IF;
 kind := ops.ddo_binding_type(context, operand ->> 'value_type');
 IF (source = 'literal') THEN
  raw := operand['value']['json'];
  IF (raw IS NULL) THEN
   RAISE EXCEPTION USING MESSAGE = 'missing typed native literal', ERRCODE = 'P0001';
  END IF;
  IF ((raw ->> 0) = 'sequence') THEN
   FOR item IN SELECT operand_item.value 
FROM jsonb_array_elements(raw[1]) AS operand_item(value) LOOP
    result := result || jsonb_build_array(ops.ddo_binding_typed(item, kind));
   END LOOP;
  ELSE
   result := jsonb_build_array(ops.ddo_binding_typed(raw, kind));
  END IF;
 ELSE
  IF (source = 'parameter') THEN
   IF (NOT (context['parameters'] ? (operand ->> 'name'))) THEN
    RAISE EXCEPTION USING MESSAGE = 'missing frozen native binding parameter', ERRCODE = 'P0001';
   END IF;
   raw := data.ddo_field(context['parameter_meaning'], operand ->> 'name');
   IF (raw IS NOT NULL) THEN
    IF ((raw ->> 0) = 'sequence') THEN
     FOR item IN SELECT operand_item.value 
FROM jsonb_array_elements(raw[1]) AS operand_item(value) LOOP
      result := result || jsonb_build_array(ops.ddo_binding_typed(item, kind));
     END LOOP;
    ELSE
     result := jsonb_build_array(ops.ddo_binding_typed(raw, kind));
    END IF;
    RETURN result;
   END IF;
   IF (kind IN ('float', 'double')) THEN
    RAISE EXCEPTION USING MESSAGE = 'float demand parameter requires frozen typed meaning', ERRCODE = 'P0001';
   END IF;
   raw := context['parameters'][(operand ->> 'name')];
   IF (jsonb_typeof(raw) = 'array') THEN
    FOR item IN SELECT operand_item.value 
FROM jsonb_array_elements(raw) AS operand_item(value) LOOP
     result := result || jsonb_build_array(ops.ddo_binding_scalar(item, kind));
    END LOOP;
   ELSE
    result := jsonb_build_array(ops.ddo_binding_scalar(raw, kind));
   END IF;
  ELSE
   IF (source = 'population') THEN
    population := context['populations'][(operand ->> 'name')];
    IF (population IS NULL OR (population ->> 'complete') IS DISTINCT FROM 'true') THEN
     RAISE EXCEPTION USING MESSAGE = 'binding membership population is not closed', ERRCODE = 'P0001';
    END IF;
    IF (coalesce((operand ->> 'population_projection'), 'member') IS DISTINCT FROM coalesce((population ->> 'projection'), 'member')) THEN
     RAISE EXCEPTION USING MESSAGE = 'native population projection differs from frozen operand', ERRCODE = 'P0001';
    END IF;
    IF ((operand ->> 'population_projection') = 'qualified-context') THEN
     IF (kind != 'subject-context') THEN
      RAISE EXCEPTION USING MESSAGE = 'native context population type differs', ERRCODE = 'P0001';
     END IF;
     FOR item IN SELECT population_member.value 
FROM jsonb_array_elements(population['members']) AS population_member(value) LOOP
      result := result || jsonb_build_array(jsonb_build_array('subject-context', item));
     END LOOP;
    ELSE
     FOR item IN SELECT population_member.value 
FROM jsonb_array_elements(population['members']) AS population_member(value) LOOP
      result := result || jsonb_build_array(ops.ddo_binding_scalar(item, kind));
     END LOOP;
    END IF;
   ELSE
    RAISE EXCEPTION USING MESSAGE = format('unsupported native binding operand %s', coalesce(source, '<NULL>')), ERRCODE = '23514';
   END IF;
  END IF;
 END IF;
 RETURN result;
END

