DECLARE
 kind sem.data_kind_contract%ROWTYPE;
 child_kind sem.data_kind_contract%ROWTYPE;
 members jsonb;
 packet jsonb;
 child_body jsonb;
 child text;
BEGIN
 SELECT sem.data_kind_contract.* 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = p_kind INTO STRICT kind;
 RETURN NEXT p_kind;
 IF (kind.member_schema = CAST('{"not":{}}' AS JSONB)) THEN
  RETURN;
 END IF;
 members := data.ddo_field(p_body, 'members');
 IF (members IS NULL) THEN
  RETURN;
 END IF;
 IF ((members ->> 0) IS DISTINCT FROM 'sequence') THEN
  RAISE EXCEPTION USING MESSAGE = 'invalid nominal member body', ERRCODE = 'P0001';
 END IF;
 FOR packet IN SELECT packets.value 
FROM jsonb_array_elements(members[1]) AS packets(value) LOOP
  child := data.ddo_field(packet, 'kind_contract') ->> 1;
  child_body := data.ddo_field(packet, 'body');
  IF (child IS NULL OR child_body IS NULL OR NOT ((kind.member_contracts ? child))) THEN
   RAISE EXCEPTION USING MESSAGE = 'body member kind is outside its captured nominal contract', ERRCODE = 'P0001';
  END IF;
  SELECT sem.data_kind_contract.* 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = child INTO STRICT child_kind;
  IF (NOT public.json_matches_schema(CAST(child_kind.meaning_schema AS JSON), CAST(child_body AS JSON)) OR NOT public.json_matches_schema(CAST(child_kind.body_schema AS JSON), CAST(data.ddo_json(child_body) AS JSON))) THEN
   RAISE EXCEPTION USING MESSAGE = 'body member value differs from its captured nominal kind', ERRCODE = 'P0001';
  END IF;
  RETURN QUERY SELECT * 
FROM ops.ddo_body_kind_contracts(child, child_body);
 END LOOP;
END

