DECLARE
 item jsonb;
 episode ops.data_derivation%ROWTYPE;
 source_request ops.data_request%ROWTYPE;
 selected ops.demand_use%ROWTYPE;
 original ops.original_source_admission%ROWTYPE;
BEGIN
 IF (jsonb_typeof(support) IS DISTINCT FROM 'array') THEN
  RAISE EXCEPTION USING MESSAGE = 'support manifest must be array', ERRCODE = 'P0001';
 END IF;
 FOR item IN SELECT support.value 
FROM jsonb_array_elements(support) AS support LOOP
  IF ((item ->> 'kind') IN ('original-source', 'authored')) THEN
   PERFORM ops.ddo_fields(item, ARRAY['kind', 'admission_id', 'source_reference', 'role', 'position'], ARRAY[]::TEXT[]);
   SELECT ops.original_source_admission.* 
FROM ops.original_source_admission 
WHERE ops.original_source_admission.id = (item ->> 'admission_id') INTO original;
   IF (original.id IS NULL OR (item ->> 'kind') IS DISTINCT FROM CASE WHEN ((original.reference ->> 'kind') = 'authored-fact') THEN 'authored' ELSE 'original-source' END OR original.project_id IS DISTINCT FROM r.project_id OR original.source_reference IS DISTINCT FROM (item ->> 'source_reference') OR NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(binding['inputs']) AS selected_input JOIN kb.data_product ON kb.data_product.id = (selected_input.value ->> 'product_id') JOIN sem.data_operation_definition ON sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id JOIN LATERAL jsonb_array_elements(sem.data_operation_definition.input_roles) AS roledef_1 ON true 
WHERE (selected_input.value ->> 'role') = (item ->> 'role') AND (selected_input.value ->> 'position') IS NOT DISTINCT FROM (item ->> 'position') AND (roledef_1.value ->> 'name') = (selected_input.value ->> 'role') AND kb.data_product.id = original.product_id AND (selected_input.value ->> 'member_id') IS NULL AND kb.data_product.original_source IS NOT DISTINCT FROM r.original_source AND ops.ddo_binding_subject(roledef_1.value, jsonb_build_object('subject', kb.data_product.subject, 'meaning_body', kb.data_product.canonical_body), r.subject, r.original_source) AND ((roledef_1.value ->> 'subject_field') IS NOT NULL OR original.analyzed_scope = r.analyzed_scope)))) THEN
    RAISE EXCEPTION USING MESSAGE = 'original support differs from selected factual input custody', ERRCODE = 'P0001';
   END IF;
   IF (NOT ops.ddo_original_admission_valid(original)) THEN
    RETURN false;
   END IF;
   CONTINUE;
  END IF;
  IF (coalesce((item ->> 'kind'), 'computation') != 'computation') THEN
   RAISE EXCEPTION USING MESSAGE = 'unknown support reference origin', ERRCODE = 'P0001';
  END IF;
  PERFORM ops.ddo_fields(item, ARRAY['derivation_id', 'role', 'position'], ARRAY['admission_use_id', 'kind']);
  SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = (item ->> 'derivation_id') INTO STRICT episode;
  SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = episode.request_id INTO STRICT source_request;
  IF (source_request.project_id IS DISTINCT FROM r.project_id) THEN
   RAISE EXCEPTION USING MESSAGE = 'support outside project custody', ERRCODE = 'P0001';
  END IF;
  IF (source_request.original_source IS DISTINCT FROM r.original_source AND NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(binding['inputs']) AS selected_input JOIN kb.data_product ON kb.data_product.id = (selected_input.value ->> 'product_id') JOIN sem.data_operation_definition ON sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id JOIN LATERAL jsonb_array_elements(sem.data_operation_definition.input_roles) AS roledef_1 ON true LEFT OUTER JOIN kb.data_product_member ON kb.data_product_member.product_id = kb.data_product.id AND kb.data_product_member.member_id = (selected_input.value ->> 'member_id') 
WHERE (roledef_1.value ->> 'name') = (selected_input.value ->> 'role') AND ((item ->> 'role') = (selected_input.value ->> 'role') OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(binding['populations']) AS reference JOIN ops.data_population ON ops.data_population.id = (reference.value ->> 'population_id') 
WHERE (reference.value ->> 'role') = (selected_input.value ->> 'role') AND (item ->> 'role') = ('population:' || ops.data_population.name) AND (ops.data_population.evidence ->> 'derivation_id') = episode.id))) AND (EXISTS (SELECT 1 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = episode.id AND ops.data_derivation_output.product_id = kb.data_product.id AND (ops.data_derivation_output.member_id IS NULL OR ops.data_derivation_output.member_id = (selected_input.value ->> 'member_id')))) AND ops.ddo_binding_source(roledef_1.value, jsonb_build_object('product', kb.data_product.id, 'member', kb.data_product_member.member_id, 'subject', coalesce(kb.data_product_member.subject, kb.data_product.subject), 'subject_definition', coalesce(kb.data_product_member.subject_definition, kb.data_product.subject_definition), 'original_source', kb.data_product.original_source, 'analyzed_scope', coalesce(kb.data_product_member.analyzed_scope, kb.data_product.analyzed_scope), 'meaning_body', coalesce(kb.data_product_member.body, kb.data_product.canonical_body), 'support_references', jsonb_build_array(jsonb_build_object('kind', 'computation', 'derivation_id', (item ->> 'derivation_id'), 'admission_use_id', (item ->> 'admission_use_id'))), 'support_evidence', jsonb_build_object('producer_output', selected_input.value['producer_output'])), r.original_source, coalesce((SELECT ops.data_demand.selection['source_sets'] AS anon_1 
FROM ops.data_demand JOIN ops.data_demand_read ON ops.data_demand_read.demand_id = ops.data_demand.id 
WHERE ops.data_demand_read.id = (binding ->> 'read_id')), CAST('{}' AS JSONB)))))) THEN
   RAISE EXCEPTION USING MESSAGE = 'foreign support outside exact frozen source-set custody', ERRCODE = '23514';
  END IF;
  IF ((item ->> 'admission_use_id') IS NULL) THEN
   IF (NOT ops.ddo_node_valid('episode', episode.id)) THEN
    RETURN false;
   END IF;
  ELSE
   SELECT ops.demand_use.* 
FROM ops.demand_use 
WHERE ops.demand_use.id = (item ->> 'admission_use_id') AND ops.demand_use.derivation_id = episode.id INTO selected;
   IF (NOT found OR NOT ops.ddo_node_valid('use', selected.id)) THEN
    RETURN false;
   END IF;
  END IF;
 END LOOP;
 RETURN true;
END

