FROM ops.data_request 
WHERE ops.data_request.id = r.id FOR UPDATE INTO STRICT r;
 IF (r.generation IS DISTINCT FROM CAST((p ->> 'generation') AS INTEGER)) THEN
  RETURN pg_catalog.jsonb_build_object('payload', pg_catalog.jsonb_build_object('state', 'no-work'));
