WHERE ops.data_completion_intent.request_id = r.id AND (ops.data_completion_intent.generation = r.generation OR (EXISTS (SELECT 1 
FROM ops.data_draft_consumption 
WHERE ops.data_draft_consumption.intent_id = ops.data_completion_intent.id AND ops.data_draft_consumption.request_id = r.id AND ops.data_draft_consumption.generation = r.generation))) AND NOT (EXISTS (SELECT 1 
