 IF ((p ? 'external_packet_id') AND (packet.id IS NULL OR packet.id != (p ->> 'external_packet_id') OR packet.task_id != t.id)) THEN
  RAISE EXCEPTION USING MESSAGE = 'external claim differs from its exact current packet/task', ERRCODE = '23514';
 END IF;
