 LIMIT 1 INTO STRICT binding_use;
 UPDATE ops.task SET status='running', attempt=(ops.task.attempt + 1), claimed_by=(p ->> 'holder'), lease_until=(clock_timestamp() + make_interval(0, 0, 0, 0, 0, 0, CAST((p ->> 'lease_seconds') AS INTEGER))), started_at=coalesce(ops.task.started_at, clock_timestamp()) WHERE ops.task.id = t.id RETURNING ops.task.id, ops.task.release_id, ops.task.data_request_id, ops.task.data_generation, ops.task.invocation_key, ops.task.trigger, ops.task.status, ops.task.attempt, ops.task.claimed_by, ops.task.lease_until, ops.task.result_digest, ops.task.error, ops.task.cost, ops.task.reason, ops.task.priority, ops.task.created_at, ops.task.started_at, ops.task.finished_at INTO t;
 SELECT ops.data_completion_intent.id 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.request_id = r.id AND (ops.data_completion_intent.generation = r.generation OR (EXISTS (SELECT 1 
FROM ops.data_draft_consumption 
WHERE ops.data_draft_consumption.intent_id = ops.data_completion_intent.id AND ops.data_draft_consumption.request_id = r.id AND ops.data_draft_consumption.generation = r.generation))) AND NOT (EXISTS (SELECT 1 
FROM ops.data_publication_receipt 
WHERE ops.data_publication_receipt.intent_id = ops.data_completion_intent.id)) INTO retained_id;
 RETURN pg_catalog.jsonb_build_object('payload', pg_catalog.jsonb_build_object('state', 'claimed', 'request_id', r.id, 'release_id', r.release_id, 'runtime_id', r.runtime_id, 'binding', r.binding - 'execution_profile', 'binding_demand_id', binding_use.demand_id, 'binding_obligation_id', binding_use.obligation_id, 'generation', r.generation, 'task_id', t.id, 'attempt', t.attempt, 'holder', t.claimed_by, 'lease_until', t.lease_until, 'trust_snapshot', snapshot, 'action', CASE WHEN (retained_id IS NULL) THEN 'compute' ELSE 'reconcile' END, 'retained_intent_id', retained_id));
END

