FROM jsonb_array_elements(coalesce(def.support_contract['transitions'], CAST('[]' AS JSONB))) AS transition 
WHERE (transition.value ->> 'dimension') = 'completion' AND (transition.value ->> 'outcome') = outcome AND (transition.value ->> 'before') = 'pending' AND (transition.value ->> 'after') IN ('success', 'empty', 'failed') AND coalesce(transition.value['effects'], CAST('[]' AS JSONB)) = CAST('[]' AS JSONB) INTO n, result;
 IF (n = 1) THEN
  RETURN result;
 END IF;
 IF (true) THEN
  RAISE EXCEPTION USING MESSAGE = 'completion requires one declared terminal-state mapping', ERRCODE = 'P0001';
 END IF;
END$$

