DECLARE
 episode ops.data_derivation%ROWTYPE;
 request ops.data_request%ROWTYPE;
 intent ops.data_completion_intent%ROWTYPE;
BEGIN
 SELECT ops.data_derivation.* 
FROM ops.data_derivation JOIN ops.data_request ON ops.data_request.id = ops.data_derivation.request_id AND (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = ops.data_request.release_id AND sem.data_operation_definition.operation_id = ops.data_request.operation_id AND (sem.data_operation_definition.validity_families @> ARRAY['contextual']))) AND ((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = ops.data_request.release_id AND sem.data_operation_definition.operation_id = ops.data_request.operation_id) @> jsonb_build_array(jsonb_build_object('name', operation_name))) JOIN ops.data_publication_receipt ON ops.data_publication_receipt.derivation_id = ops.data_derivation.id AND ops.data_publication_receipt.intent_id = ops.data_derivation.intent_id JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id 
WHERE ops.data_derivation_output.product_id = (data.ddo_field(selected_input, 'product_id') ->> 1) AND (ops.data_derivation_output.member_id IS NULL OR ops.data_derivation_output.member_id = (data.ddo_field(selected_input, 'member_id') ->> 1)) AND ops.data_derivation_output.multiplicity = 1 AND ops.data_derivation.outcome = 'success' AND ops.data_derivation.id IN (SELECT (reference.value ->> 'derivation_id') AS anon_1 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(selected_input, 'support'))) AS reference(value) 
WHERE (reference.value ->> 'kind') = 'computation') INTO STRICT episode;
 IF (NOT ops.ddo_contextual_dependencies_valid(episode.id)) THEN
  RAISE EXCEPTION USING MESSAGE = 'contextual definition lineage lacks its authentic sealed producer', ERRCODE = '23514';
 END IF;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = episode.request_id INTO STRICT request;
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = episode.intent_id AND ops.data_completion_intent.request_id = episode.request_id AND ops.data_completion_intent.generation = episode.generation INTO STRICT intent;
 request.release_id := episode.release_id;
 request.runtime_id := episode.runtime_id;
 request.recipe := episode.recipe;
 request.generation := episode.generation;
 request.binding := request.binding || jsonb_build_object('inputs', intent.payload['inputs'], 'support', intent.payload['support']);
 RETURN ops.ddo_cpu_input_basis(request);
END

