DECLARE
 original ops.data_request%ROWTYPE := r;
 basis jsonb;
 item jsonb;
 producer_basis jsonb;
 vector_query jsonb;
 query_context jsonb;
 result jsonb := CAST('{}' AS JSONB);
 role_name text;
 episode ops.data_derivation%ROWTYPE;
 producing ops.data_request%ROWTYPE;
 intent ops.data_completion_intent%ROWTYPE;
 scores_episode ops.data_derivation%ROWTYPE;
 witness_episode ops.data_derivation%ROWTYPE;
 vectors_episode ops.data_derivation%ROWTYPE;
 query_episode ops.data_derivation%ROWTYPE;
 scores_request ops.data_request%ROWTYPE;
 witness_request ops.data_request%ROWTYPE;
 vectors_request ops.data_request%ROWTYPE;
 definition sem.data_operation_definition%ROWTYPE;
 score_definition sem.data_operation_definition%ROWTYPE;
BEGIN
 original.binding := r.binding || jsonb_build_object('inputs', completion['inputs'], 'support', completion['support']);
 basis := ops.ddo_cpu_input_basis(original);
 FOR item IN SELECT role_row.value 
FROM jsonb_array_elements((data.ddo_field(basis, 'roles'))[1]) AS role_row(value) LOOP
  role_name := data.ddo_field(item, 'role') ->> 1;
  IF ((result ? role_name) OR (role_name NOT IN ('query', 'inventory', 'vectors', 'policy', 'scores', 'witnesses')) OR data.ddo_field(item, 'member_id') IS DISTINCT FROM CAST('["null"]' AS JSONB) OR data.ddo_field(item, 'multiplicity') IS DISTINCT FROM CAST('["integer","1"]' AS JSONB)) THEN
   RAISE EXCEPTION USING MESSAGE = 'native contextual scoring requires exact distinct whole role products', ERRCODE = '23514';
  END IF;
  result := result || jsonb_build_object(role_name, data.ddo_json(data.ddo_field(item, 'body')));
  IF (role_name = 'policy') THEN
   CONTINUE;
  END IF;
  SELECT ops.data_derivation.* 
FROM ops.data_derivation JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id JOIN ops.data_publication_receipt ON ops.data_publication_receipt.derivation_id = ops.data_derivation.id AND ops.data_publication_receipt.intent_id = ops.data_derivation.intent_id 
WHERE ops.data_derivation_output.product_id = (data.ddo_field(item, 'product_id') ->> 1) AND ops.data_derivation_output.member_id IS NULL AND ops.data_derivation_output.multiplicity = 1 AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(item, 'support'))) AS reference(value) 
WHERE (reference.value ->> 'kind') = 'computation' AND (reference.value ->> 'derivation_id') = ops.data_derivation.id)) INTO STRICT episode;
  SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = episode.request_id AND ops.data_request.project_id = r.project_id INTO STRICT producing;
  IF (NOT ((EXISTS (SELECT 1 
FROM jsonb_array_elements((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id)) AS contextual_input_role(value) 
WHERE (contextual_input_role.value ->> 'name') = role_name AND (contextual_input_role.value ->> 'direction') = 'input' AND ((contextual_input_role.value['support']) ->> 'source') = 'frozen-source-set' AND nullif(((contextual_input_role.value['support']) ->> 'source_set'), '') IS NOT NULL)) OR ((SELECT sem.data_operation_definition.dependencies 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id)['required'] @> jsonb_build_array(producing.operation_id)) OR ((SELECT sem.data_operation_definition.dependencies 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id)['potential'] @> jsonb_build_array(producing.operation_id))) OR NOT ops.ddo_contextual_dependencies_valid(episode.id)) THEN
   RAISE EXCEPTION USING MESSAGE = 'native contextual input lacks its actual declared producer/common receipt', ERRCODE = '23514';
  END IF;
  IF (role_name = 'witnesses') THEN
   witness_episode := episode;
   witness_request := producing;
  END IF;
  IF (role_name = 'scores') THEN
   scores_episode := episode;
   scores_request := producing;
  END IF;
  IF (role_name = 'vectors') THEN
   vectors_episode := episode;
   vectors_request := producing;
  END IF;
  IF (role_name = 'query') THEN
   query_episode := episode;
   query_context := data.ddo_field(item, 'context');
  END IF;
 END LOOP;
 IF ((SELECT array_agg(keys.key ORDER BY keys.key) AS array_agg_1 
FROM jsonb_object_keys(result) AS keys(key)) IS DISTINCT FROM CASE WHEN (((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'policy'))) AND NOT (((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'scores'))))) THEN ARRAY['inventory', 'policy', 'query', 'vectors'] WHEN (((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'witnesses')))) THEN ARRAY['inventory', 'policy', 'query', 'scores', 'vectors', 'witnesses'] ELSE ARRAY['inventory', 'policy', 'query', 'scores', 'vectors'] END) THEN
  RAISE EXCEPTION USING MESSAGE = 'native contextual input population is incomplete or foreign', ERRCODE = '23514';
 END IF;
 IF (query_context IS DISTINCT FROM data.ddo_field(basis, 'context') OR ((result['query']['source_pin']) ->> 'project_id') IS DISTINCT FROM r.project_id OR ((result['query']['source_pin']) ->> 'original_source') IS DISTINCT FROM r.original_source) THEN
  RAISE EXCEPTION USING MESSAGE = 'native contextual query differs from selected product/original context', ERRCODE = '23514';
 END IF;
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = vectors_episode.intent_id INTO STRICT intent;
 vectors_request.release_id := vectors_episode.release_id;
 vectors_request.runtime_id := vectors_episode.runtime_id;
 vectors_request.recipe := vectors_episode.recipe;
 vectors_request.generation := vectors_episode.generation;
 vectors_request.binding := vectors_request.binding || jsonb_build_object('inputs', intent.payload['inputs'], 'support', intent.payload['support']);
 producer_basis := ops.ddo_cpu_input_basis(vectors_request);
 IF (ops.ddo_rich_role_population(basis, 'inventory') IS DISTINCT FROM ops.ddo_rich_role_population(producer_basis, 'inventory')) THEN
  RAISE EXCEPTION USING MESSAGE = 'native scoring inventory differs from actual selected vector assembly', ERRCODE = '23514';
 END IF;
 SELECT selected_role.value 
FROM jsonb_array_elements((data.ddo_field(producer_basis, 'roles'))[1]) AS selected_role(value) 
WHERE (data.ddo_field(selected_role.value, 'role') ->> 1) = 'query' INTO STRICT vector_query;
 IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(vector_query, 'support'))) AS reference(value) JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = (reference.value ->> 'derivation_id') 
WHERE (reference.value ->> 'kind') = 'computation' AND ops.data_derivation_output.derivation_id = query_episode.id AND ops.data_derivation_output.product_id = (data.ddo_field(vector_query, 'product_id') ->> 1) AND ops.data_derivation_output.member_id IS NULL AND ops.data_derivation_output.role = 'vector' AND ops.data_derivation_output.multiplicity = 1))) THEN
  RAISE EXCEPTION USING MESSAGE = 'native scoring query and assembly vector have different original encoder episodes', ERRCODE = '23514';
 END IF;
 IF (scores_episode.id IS NOT NULL) THEN
  SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = scores_episode.intent_id INTO STRICT intent;
  scores_request.release_id := scores_episode.release_id;
  scores_request.runtime_id := scores_episode.runtime_id;
  scores_request.recipe := scores_episode.recipe;
  scores_request.generation := scores_episode.generation;
  scores_request.binding := scores_request.binding || jsonb_build_object('inputs', intent.payload['inputs'], 'support', intent.payload['support']);
  producer_basis := ops.ddo_cpu_input_basis(scores_request);
  IF (ops.ddo_rich_role_population(basis, 'query') IS DISTINCT FROM ops.ddo_rich_role_population(producer_basis, 'query')) THEN
   RAISE EXCEPTION USING MESSAGE = 'native scores belong to another exact selected input/support population', ERRCODE = '23514';
  END IF;
  IF (ops.ddo_rich_role_population(basis, 'inventory') IS DISTINCT FROM ops.ddo_rich_role_population(producer_basis, 'inventory')) THEN
   RAISE EXCEPTION USING MESSAGE = 'native scores belong to another exact selected input/support population', ERRCODE = '23514';
  END IF;
  IF (ops.ddo_rich_role_population(basis, 'vectors') IS DISTINCT FROM ops.ddo_rich_role_population(producer_basis, 'vectors')) THEN
   RAISE EXCEPTION USING MESSAGE = 'native scores belong to another exact selected input/support population', ERRCODE = '23514';
  END IF;
  IF (ops.ddo_rich_role_population(basis, 'policy') IS DISTINCT FROM ops.ddo_rich_role_population(producer_basis, 'policy')) THEN
   RAISE EXCEPTION USING MESSAGE = 'native scores belong to another exact selected input/support population', ERRCODE = '23514';
  END IF;
  SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id INTO STRICT definition;
  SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = scores_episode.release_id AND sem.data_operation_definition.operation_id = scores_request.operation_id INTO STRICT score_definition;
  IF (definition.support_contract['numerical_policy'] IS DISTINCT FROM score_definition.support_contract['numerical_policy']) THEN
   RAISE EXCEPTION USING MESSAGE = 'native scores and CPU reduction have different captured numerical policies', ERRCODE = '23514';
  END IF;
 END IF;
 IF (witness_episode.id IS NOT NULL) THEN
  SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = witness_episode.intent_id INTO STRICT intent;
  witness_request.release_id := witness_episode.release_id;
  witness_request.runtime_id := witness_episode.runtime_id;
  witness_request.recipe := witness_episode.recipe;
  witness_request.generation := witness_episode.generation;
  witness_request.binding := witness_request.binding || jsonb_build_object('inputs', intent.payload['inputs'], 'support', intent.payload['support']);
  producer_basis := ops.ddo_cpu_input_basis(witness_request);
  IF (ops.ddo_rich_role_population(basis, 'query') IS DISTINCT FROM ops.ddo_rich_role_population(producer_basis, 'query')) THEN
   RAISE EXCEPTION USING MESSAGE = 'contextual witness binding belongs to another exact query/inventory support population', ERRCODE = '23514';
  END IF;
  IF (ops.ddo_rich_role_population(basis, 'inventory') IS DISTINCT FROM ops.ddo_rich_role_population(producer_basis, 'inventory')) THEN
   RAISE EXCEPTION USING MESSAGE = 'contextual witness binding belongs to another exact query/inventory support population', ERRCODE = '23514';
  END IF;
 END IF;
 RETURN result;
END

