 query_ jsonb;
 hypotheses jsonb;
 inventory_ jsonb;
 query_basis jsonb;
 original_occurrence jsonb;
 original_source jsonb;
 cue jsonb;
 reference_ jsonb;
 assertion_ jsonb;
 actual_refs jsonb;
 carrier_ jsonb;
 cues jsonb := CAST('[]' AS JSONB);
 query_episode ops.data_derivation%ROWTYPE;
 inventory_episode ops.data_derivation%ROWTYPE;
 query_request ops.data_request%ROWTYPE;
 query_intent ops.data_completion_intent%ROWTYPE;
 admission ops.original_source_admission%ROWTYPE;
 seen text[] := ARRAY[]::TEXT[];
 name_ text;
BEGIN
 original.binding := r.binding || jsonb_build_object('inputs', completion['inputs'], 'support', completion['support']);
 basis := ops.ddo_cpu_input_basis(original);
 FOR row_ IN SELECT role_row.value 
FROM jsonb_array_elements((data.ddo_field(basis, 'roles'))[1]) AS role_row(value) LOOP
  name_ := data.ddo_field(row_, 'role') ->> 1;
  IF ((name_ NOT IN ('source', 'query', 'inventory', 'hypotheses', 'cues')) OR data.ddo_field(row_, 'multiplicity') IS DISTINCT FROM CAST('["integer","1"]' AS JSONB)) THEN
   RAISE EXCEPTION USING MESSAGE = 'contextual witness input population is foreign or repeated', ERRCODE = '23514';
  END IF;
  IF (name_ = 'cues') THEN
   cues := cues || jsonb_build_array(row_);
   CONTINUE;
  END IF;
  IF (name_ = ANY (seen)) THEN
   RAISE EXCEPTION USING MESSAGE = 'contextual witness requires exact scalar inputs', ERRCODE = '23514';
  END IF;
  seen := array_append(seen, name_);
  IF (name_ = 'source') THEN
   source_row := row_;
  ELSE
   IF (name_ = 'query') THEN
    query_row := row_;
   ELSE
    IF (name_ = 'inventory') THEN
     inventory_row := row_;
    ELSE
     IF (name_ = 'hypotheses') THEN
      hypothesis_row := row_;
     ELSE
      RAISE EXCEPTION USING MESSAGE = 'case not found', ERRCODE = '20000';
     END IF;
    END IF;
   END IF;
  END IF;
 END LOOP;
 IF (query_row IS NULL OR inventory_row IS NULL OR source_row IS NULL OR hypothesis_row IS NULL OR cues = CAST('[]' AS JSONB) OR data.ddo_field(query_row, 'member_id') IS DISTINCT FROM CAST('["null"]' AS JSONB) OR data.ddo_field(inventory_row, 'member_id') IS DISTINCT FROM CAST('["null"]' AS JSONB) OR data.ddo_field(hypothesis_row, 'member_id') IS DISTINCT FROM CAST('["null"]' AS JSONB) OR data.ddo_field(query_row, 'context') IS DISTINCT FROM data.ddo_field(basis, 'context') OR data.ddo_field(inventory_row, 'context') IS DISTINCT FROM data.ddo_field(basis, 'context')) THEN
  RAISE EXCEPTION USING MESSAGE = 'contextual witness lacks its exact selected input context/population', ERRCODE = '23514';
 END IF;
 query_ := data.ddo_json(data.ddo_field(query_row, 'body'));
 hypotheses := data.ddo_json(data.ddo_field(hypothesis_row, 'body'));
 inventory_ := data.record_source_json((data.ddo_json(data.ddo_field(inventory_row, 'body')))['inventory']);
 SELECT ops.data_derivation.* 
FROM ops.data_derivation JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id JOIN ops.data_request ON ops.data_request.id = ops.data_derivation.request_id JOIN ops.data_publication_receipt ON ops.data_publication_receipt.derivation_id = ops.data_derivation.id AND ops.data_publication_receipt.intent_id = ops.data_derivation.intent_id 
WHERE ops.data_derivation_output.product_id = (data.ddo_field(query_row, 'product_id') ->> 1) AND ops.data_derivation_output.member_id IS NULL AND (((SELECT sem.data_operation_definition.dependencies 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id)['required'] @> jsonb_build_array(ops.data_request.operation_id)) OR ((SELECT sem.data_operation_definition.dependencies 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id)['potential'] @> jsonb_build_array(ops.data_request.operation_id))) AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(query_row, 'support'))) AS selected_support(value) 
WHERE (selected_support.value ->> 'kind') = 'computation' AND (selected_support.value ->> 'derivation_id') = ops.data_derivation.id)) AND ops.data_derivation_output.role = 'query' INTO STRICT query_episode;
 IF (NOT ops.ddo_contextual_dependencies_valid(query_episode.id)) THEN
  RAISE EXCEPTION USING MESSAGE = 'contextual witness query lacks original native/CPU publication', ERRCODE = '23514';
 END IF;
 SELECT ops.data_derivation.* 
FROM ops.data_derivation JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id JOIN ops.data_request ON ops.data_request.id = ops.data_derivation.request_id JOIN ops.data_publication_receipt ON ops.data_publication_receipt.derivation_id = ops.data_derivation.id AND ops.data_publication_receipt.intent_id = ops.data_derivation.intent_id 
WHERE ops.data_derivation_output.product_id = (data.ddo_field(inventory_row, 'product_id') ->> 1) AND ops.data_derivation_output.member_id IS NULL AND (((SELECT sem.data_operation_definition.dependencies 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id)['required'] @> jsonb_build_array(ops.data_request.operation_id)) OR ((SELECT sem.data_operation_definition.dependencies 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id)['potential'] @> jsonb_build_array(ops.data_request.operation_id))) AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(inventory_row, 'support'))) AS selected_support(value) 
WHERE (selected_support.value ->> 'kind') = 'computation' AND (selected_support.value ->> 'derivation_id') = ops.data_derivation.id)) INTO STRICT inventory_episode;
 IF (NOT ops.ddo_contextual_dependencies_valid(inventory_episode.id)) THEN
  RAISE EXCEPTION USING MESSAGE = 'contextual witness inventory lacks its genuine native/CPU producer', ERRCODE = '23514';
 END IF;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = query_episode.request_id INTO STRICT query_request;
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = query_episode.intent_id INTO STRICT query_intent;
 query_request.release_id := query_episode.release_id;
 query_request.runtime_id := query_episode.runtime_id;
 query_request.recipe := query_episode.recipe;
 query_request.generation := query_episode.generation;
 query_request.binding := query_request.binding || jsonb_build_object('inputs', query_intent.payload['inputs'], 'support', query_intent.payload['support']);
 query_basis := ops.ddo_cpu_input_basis(query_request);
 SELECT selected_role.value 
FROM jsonb_array_elements((data.ddo_field(query_basis, 'roles'))[1]) AS selected_role(value) 
WHERE (data.ddo_field(selected_role.value, 'role') ->> 1) = 'occurrence' INTO STRICT original_occurrence;
 SELECT selected_role.value 
FROM jsonb_array_elements((data.ddo_field(query_basis, 'roles'))[1]) AS selected_role(value) 
WHERE (data.ddo_field(selected_role.value, 'role') ->> 1) = 'source' INTO STRICT original_source;
 carrier_ := ops.ddo_contextual_input_reference(original_occurrence, true);
 IF (carrier_ IS DISTINCT FROM query_['carrier'] OR ops.ddo_contextual_input_reference(source_row, false) IS DISTINCT FROM ops.ddo_contextual_input_reference(original_source, false) OR ops.ddo_rich_role_population(basis, 'source') IS DISTINCT FROM ops.ddo_rich_role_population(query_basis, 'source')) THEN
  RAISE EXCEPTION USING MESSAGE = 'contextual witness source/query carrier differs from original query custody', ERRCODE = '23514';
 END IF;
 actual_refs := CAST('[]' AS JSONB);
 FOR cue IN SELECT cue_row.value 
FROM jsonb_array_elements(cues) AS cue_row(value) LOOP
  IF (jsonb_array_length(data.ddo_json(data.ddo_field(cue, 'support'))) = 0 OR data.ddo_field(data.ddo_field(cue, 'body'), 'pin') IS DISTINCT FROM data.ddo_field(data.ddo_field(query_row, 'body'), 'source_pin') OR data.ddo_field(data.ddo_field(cue, 'body'), 'occurrence_id') IS NULL OR jsonb_array_length(coalesce(data.ddo_json(data.ddo_field(data.ddo_field(cue, 'body'), 'anchors')), CAST('[]' AS JSONB))) = 0 OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(data.ddo_field(cue, 'body'), 'anchors'))) AS anchor(value) 
WHERE (anchor.value ->> 'precision') IS DISTINCT FROM 'exact' OR (anchor.value ->> 'space') IS DISTINCT FROM 'native' OR anchor.value['pin'] IS DISTINCT FROM query_['source_pin'])) OR ops.ddo_contextual_input_reference(cue, true) = carrier_ AND ops.ddo_rich_support_population(data.ddo_json(data.ddo_field(cue, 'support'))) IS DISTINCT FROM ops.ddo_rich_support_population(data.ddo_json(data.ddo_field(original_occurrence, 'support')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'contextual witness cue differs from actual original parent/source/anchors', ERRCODE = '23514';
  END IF;
  FOR reference_ IN SELECT cue_support.value 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(cue, 'support'))) AS cue_support(value) LOOP
   IF ((reference_ ->> 'kind') IS DISTINCT FROM 'computation' OR NOT (EXISTS (SELECT 1 
FROM ops.data_derivation JOIN ops.data_publication_receipt ON ops.data_publication_receipt.derivation_id = ops.data_derivation.id AND ops.data_publication_receipt.intent_id = ops.data_derivation.intent_id JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id 
WHERE ops.data_derivation.id = (reference_ ->> 'derivation_id') AND ops.data_derivation.outcome = 'success' AND ops.data_derivation_output.product_id = (data.ddo_field(cue, 'product_id') ->> 1) AND (ops.data_derivation_output.member_id IS NULL OR ops.data_derivation_output.member_id = (data.ddo_field(cue, 'member_id') ->> 1))))) THEN
    RAISE EXCEPTION USING MESSAGE = 'contextual witness cue lacks its actual original producer/common receipt', ERRCODE = '23514';
   END IF;
  END LOOP;
  actual_refs := actual_refs || jsonb_build_array(ops.ddo_contextual_input_reference(cue, true));
 END LOOP;
 IF (NOT (actual_refs @> jsonb_build_array(carrier_))) THEN
  RAISE EXCEPTION USING MESSAGE = 'contextual witness omits its exact qualifying query carrier', ERRCODE = '23514';
 END IF;
 IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(hypothesis_row, 'support'))) AS hypothesis_support(value) 
WHERE (hypothesis_support.value ->> 'kind') = 'authored'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'contextual witness lacks admitted authored hypotheses', ERRCODE = '23514';
 END IF;
 FOR reference_ IN SELECT hypothesis_support.value 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(hypothesis_row, 'support'))) AS hypothesis_support(value) LOOP
  SELECT ops.original_source_admission.* 
FROM ops.original_source_admission 
WHERE ops.original_source_admission.id = (reference_ ->> 'admission_id') AND ops.original_source_admission.source_reference = (reference_ ->> 'source_reference') AND ops.original_source_admission.product_id = (data.ddo_field(hypothesis_row, 'product_id') ->> 1) INTO STRICT admission;
  IF ((reference_ ->> 'kind') IS DISTINCT FROM 'authored' OR (admission.reference ->> 'kind') IS DISTINCT FROM 'authored-fact' OR (admission.reference ->> 'author') IS DISTINCT FROM (hypotheses ->> 'author_assertion') OR data.ddo_normalize(admission.reference['meaning_body']) IS DISTINCT FROM data.ddo_field(hypothesis_row, 'body')) THEN
   RAISE EXCEPTION USING MESSAGE = 'contextual witness author assertion differs from original authored admission', ERRCODE = '23514';
  END IF;
 END LOOP;
 FOR assertion_ IN SELECT assertion_row.value 
FROM jsonb_array_elements(hypotheses['hypotheses']) AS assertion_row(value) LOOP
  IF (NOT ((assertion_['cue_refs'] @> jsonb_build_array(carrier_))) OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(assertion_['cue_refs']) AS cited(value) 
WHERE NOT ((actual_refs @> jsonb_build_array(cited.value))))) OR NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(inventory_['targets']) AS target(value) 
WHERE ((target.value ->> 'target_id') COLLATE "C") = ((assertion_ ->> 'target_id') COLLATE "C")))) THEN
   RAISE EXCEPTION USING MESSAGE = 'contextual witness assertion differs from exact carrier/cues/selected target', ERRCODE = '23514';
  END IF;
 END LOOP;
END

