 IF (carrier_ IS DISTINCT FROM query_['carrier'] OR ops.ddo_contextual_input_reference(source_row, false) IS DISTINCT FROM ops.ddo_contextual_input_reference(original_source, false) OR ops.ddo_rich_role_population(basis, 'source') IS DISTINCT FROM ops.ddo_rich_role_population(query_basis, 'source')) THEN
  RAISE EXCEPTION USING MESSAGE = 'contextual witness source/query carrier differs from original query custody', ERRCODE = '23514';
 END IF;
 actual_refs := CAST('[]' AS JSONB);
 FOR cue IN SELECT cue_row.value 
FROM jsonb_array_elements(cues) AS cue_row(value) LOOP
  IF (jsonb_array_length(data.ddo_json(data.ddo_field(cue, 'support'))) = 0 OR data.ddo_field(data.ddo_field(cue, 'body'), 'pin') IS DISTINCT FROM data.ddo_field(data.ddo_field(query_row, 'body'), 'source_pin') OR data.ddo_field(data.ddo_field(cue, 'body'), 'occurrence_id') IS NULL OR jsonb_array_length(coalesce(data.ddo_json(data.ddo_field(data.ddo_field(cue, 'body'), 'anchors')), CAST('[]' AS JSONB))) = 0 OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(data.ddo_field(cue, 'body'), 'anchors'))) AS anchor(value) 
WHERE (anchor.value ->> 'precision') IS DISTINCT FROM 'exact' OR (anchor.value ->> 'space') IS DISTINCT FROM 'native' OR anchor.value['pin'] IS DISTINCT FROM query_['source_pin'])) OR ops.ddo_contextual_input_reference(cue, true) = carrier_ AND ops.ddo_rich_support_population(data.ddo_json(data.ddo_field(cue, 'support'))) IS DISTINCT FROM ops.ddo_rich_support_population(data.ddo_json(data.ddo_field(original_occurrence, 'support')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'contextual witness cue differs from actual original parent/source/anchors', ERRCODE = '23514';
  END IF;
  FOR reference_ IN SELECT cue_support.value 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(cue, 'support'))) AS cue_support(value) LOOP
   IF ((reference_ ->> 'kind') IS DISTINCT FROM 'computation' OR NOT (EXISTS (SELECT 1 
FROM ops.data_derivation JOIN ops.data_publication_receipt ON ops.data_publication_receipt.derivation_id = ops.data_derivation.id AND ops.data_publication_receipt.intent_id = ops.data_derivation.intent_id JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id 
WHERE ops.data_derivation.id = (reference_ ->> 'derivation_id') AND ops.data_derivation.outcome = 'success' AND ops.data_derivation_output.product_id = (data.ddo_field(cue, 'product_id') ->> 1) AND (ops.data_derivation_output.member_id IS NULL OR ops.data_derivation_output.member_id = (data.ddo_field(cue, 'member_id') ->> 1))))) THEN
    RAISE EXCEPTION USING MESSAGE = 'contextual witness cue lacks its actual original producer/common receipt', ERRCODE = '23514';
   END IF;
  END LOOP;
  actual_refs := actual_refs || jsonb_build_array(ops.ddo_contextual_input_reference(cue, true));
 END LOOP;
 IF (NOT (actual_refs @> jsonb_build_array(carrier_))) THEN
  RAISE EXCEPTION USING MESSAGE = 'contextual witness omits its exact qualifying query carrier', ERRCODE = '23514';
 END IF;
 IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(hypothesis_row, 'support'))) AS hypothesis_support(value) 
WHERE (hypothesis_support.value ->> 'kind') = 'authored'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'contextual witness lacks admitted authored hypotheses', ERRCODE = '23514';
 END IF;
 FOR reference_ IN SELECT hypothesis_support.value 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(hypothesis_row, 'support'))) AS hypothesis_support(value) LOOP
  SELECT ops.original_source_admission.* 
FROM ops.original_source_admission 
WHERE ops.original_source_admission.id = (reference_ ->> 'admission_id') AND ops.original_source_admission.source_reference = (reference_ ->> 'source_reference') AND ops.original_source_admission.product_id = (data.ddo_field(hypothesis_row, 'product_id') ->> 1) INTO STRICT admission;
  IF ((reference_ ->> 'kind') IS DISTINCT FROM 'authored' OR (admission.reference ->> 'kind') IS DISTINCT FROM 'authored-fact' OR (admission.reference ->> 'author') IS DISTINCT FROM (hypotheses ->> 'author_assertion') OR data.ddo_normalize(admission.reference['meaning_body']) IS DISTINCT FROM data.ddo_field(hypothesis_row, 'body')) THEN
   RAISE EXCEPTION USING MESSAGE = 'contextual witness author assertion differs from original authored admission', ERRCODE = '23514';
  END IF;
 END LOOP;
 FOR assertion_ IN SELECT assertion_row.value 
FROM jsonb_array_elements(hypotheses['hypotheses']) AS assertion_row(value) LOOP
  IF (NOT ((assertion_['cue_refs'] @> jsonb_build_array(carrier_))) OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(assertion_['cue_refs']) AS cited(value) 
WHERE NOT ((actual_refs @> jsonb_build_array(cited.value))))) OR NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(inventory_['targets']) AS target(value) 
WHERE ((target.value ->> 'target_id') COLLATE "C") = ((assertion_ ->> 'target_id') COLLATE "C")))) THEN
   RAISE EXCEPTION USING MESSAGE = 'contextual witness assertion differs from exact carrier/cues/selected target', ERRCODE = '23514';
  END IF;
 END LOOP;
END$$

