DECLARE
 episode ops.data_derivation%ROWTYPE;
 request ops.data_request%ROWTYPE;
 intent ops.data_completion_intent%ROWTYPE;
 receipt ops.data_publication_receipt%ROWTYPE;
 product kb.data_product%ROWTYPE;
 definition sem.data_operation_definition%ROWTYPE;
 reply jsonb;
 projected jsonb;
 chosen jsonb;
 fence jsonb;
 selected_output jsonb;
 member_index bigint;
 result_field text;
BEGIN
 SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = episode_id INTO STRICT episode;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = episode.request_id INTO STRICT request;
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = episode.intent_id AND ops.data_completion_intent.request_id = request.id AND ops.data_completion_intent.generation = episode.generation INTO STRICT intent;
 SELECT ops.data_publication_receipt.* 
FROM ops.data_publication_receipt 
WHERE ops.data_publication_receipt.derivation_id = episode.id AND ops.data_publication_receipt.intent_id = intent.id INTO STRICT receipt;
 IF (selected_use IS NOT NULL AND NOT (EXISTS (SELECT 1 
FROM ops.demand_use 
WHERE ops.demand_use.id = selected_use AND ops.demand_use.derivation_id = episode.id AND ops.demand_use.request_id = episode.request_id AND ops.demand_use.generation = episode.generation AND ops.demand_use.fate = 'fulfilled'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'execution leaf differs from actual selected use', ERRCODE = '23514';
 END IF;
 SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = selected_product AND kb.data_product.project_id = request.project_id INTO STRICT product;
 IF (NOT (EXISTS (SELECT 1 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = episode.id AND ops.data_derivation_output.product_id = product.id AND ops.data_derivation_output.role = selected_role AND ops.data_derivation_output.position = selected_position AND ops.data_derivation_output.member_id IS NULL AND ops.data_derivation_output.multiplicity = 1))) THEN
  RAISE EXCEPTION USING MESSAGE = 'execution projection requires its exact logical output occurrence', ERRCODE = '23514';
 END IF;
 SELECT declared_output.value 
FROM jsonb_array_elements(intent.payload['outputs']) AS declared_output(value) 
WHERE (declared_output.value ->> 'role') = selected_role AND CAST((declared_output.value ->> 'position') AS BIGINT) = selected_position AND (declared_output.value ->> 'member_id') IS NULL AND CAST((declared_output.value ->> 'multiplicity') AS BIGINT) = 1 AND ((declared_output.value['product']) ->> 'kind_contract') = product.kind_contract AND declared_output.value['product']['body'] = product.canonical_body INTO STRICT selected_output;
 request.release_id := episode.release_id;
 request.runtime_id := episode.runtime_id;
 request.recipe := episode.recipe;
 request.generation := episode.generation;
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = episode.release_id AND sem.data_operation_definition.operation_id = request.operation_id INTO STRICT definition;
 projected := CAST(ops.ddo_cpu_reply_output(request, intent.payload) AS JSONB);
 IF (jsonb_typeof(definition.support_contract['result_fields']) IS DISTINCT FROM 'object') THEN
  RAISE EXCEPTION USING MESSAGE = 'execution output lacks its archived result-field projection', ERRCODE = '23514';
 END IF;
 IF (definition.support_contract['result_fields'] != CAST('{}' AS JSONB)) THEN
  result_field := (definition.support_contract['result_fields']) ->> selected_role;
  IF (result_field IS NULL) THEN
   RAISE EXCEPTION USING MESSAGE = 'execution output lacks its exact archived result field', ERRCODE = '23514';
  END IF;
  projected := CAST(data.ddo_field(projected, result_field) AS JSONB);
 ELSE
  IF (NOT (jsonb_array_length(definition.output_roles) = 1 AND ((definition.output_roles[0]) ->> 'name') = selected_role)) THEN
   RAISE EXCEPTION USING MESSAGE = 'execution output requires its archived single-output contract', ERRCODE = '23514';
  END IF;
 END IF;
 IF (projected IS DISTINCT FROM product.canonical_body) THEN
  RAISE EXCEPTION USING MESSAGE = 'execution projection differs from its actual selected member output', ERRCODE = '23514';
 END IF;
 reply := CAST(ops.ddo_cpu_reply_value(intent.payload) AS JSONB);
 IF ((reply ->> 'version') IS DISTINCT FROM 'cpu-authority-batch-reply-1') THEN
  RAISE EXCEPTION USING MESSAGE = 'execution evidence leaf requires its actual whole batch reply', ERRCODE = '23514';
 END IF;
 fence := CAST(ops.ddo_cpu_original_producer(request, intent.payload) AS JSONB);
 SELECT batch.item, batch.ordinal - 1 AS anon_1 
FROM jsonb_array_elements(reply['members']) WITH ORDINALITY AS batch(item, ordinal) 
WHERE batch.item['producer'] = fence INTO STRICT chosen, member_index;
 RETURN jsonb_build_object('format', 'ddo-native-execution-evidence-leaf-v1', 'derivation_id', episode.id, 'use_id', selected_use, 'issuer_operation', request.operation_id, 'release_id', episode.release_id, 'runtime_id', intent.runtime_id, 'recipe', episode.recipe, 'producer', fence, 'intent_id', intent.id, 'intent_payload_digest', intent.payload_digest, 'publication_receipt_id', receipt.id, 'selected_completion', jsonb_set(jsonb_set(intent.payload, '{execution_evidence}', intent.payload['execution_evidence'] - 'cpu_replies'), '{outputs}', jsonb_build_array(selected_output)), 'product_id', product.id, 'kind_contract', product.kind_contract, 'output_role', selected_role, 'output_position', selected_position, 'cpu_receipt', intent.payload['execution_evidence']['cpu_receipts'][0], 'whole_reply_digest', (intent.payload['execution_evidence']['cpu_receipts'][0]) ->> 'result_digest', 'member', chosen ->> 'member', 'member_ordinal', member_index, 'cohort_size', jsonb_array_length(reply['members']), 'cohort_membership_digest', ops.ddo_digest((SELECT jsonb_agg(batch.item - 'output' ORDER BY batch.ordinal) AS jsonb_agg_1 
FROM jsonb_array_elements(reply['members']) WITH ORDINALITY AS batch(item, ordinal))), 'input_basis_digest', chosen ->> 'input_basis_digest', 'member_output_digest', ops.ddo_digest(projected), 'physical_cohort', 'undisclosed', 'verification', 'native-checked-member-projection');
END

