DECLARE
 selected jsonb;
 product kb.data_product%ROWTYPE;
 member kb.data_product_member%ROWTYPE;
 roles jsonb := CAST('[]' AS JSONB);
 support_refs jsonb;
 meaning jsonb;
 context_meaning jsonb;
 output_meaning jsonb;
BEGIN
 IF (data.ddo_field(r.binding['parameters'], 'replicate') IS DISTINCT FROM data.ddo_json_meaning((jsonb_build_object('replicate', r.replicate))['replicate'])) THEN
  RAISE EXCEPTION USING MESSAGE = 'CPU input basis requires the actual exact request replicate wrapper', ERRCODE = '23514';
 END IF;
 FOR selected IN SELECT inputs.value 
FROM jsonb_array_elements(r.binding['inputs']) AS inputs LOOP
  SELECT kb.data_product.id, kb.data_product.kind_contract, kb.data_product.project_id, kb.data_product.subject, kb.data_product.subject_definition, kb.data_product.original_source, kb.data_product.analyzed_scope, kb.data_product.canonical_body, kb.data_product.body_digest, kb.data_product.artifact_digest 
FROM kb.data_product 
WHERE kb.data_product.id = (selected ->> 'product_id') AND kb.data_product.project_id = r.project_id INTO STRICT product;
  member := NULL;
  IF ((selected ->> 'member_id') IS NOT NULL) THEN
   SELECT kb.data_product_member.product_id, kb.data_product_member.member_id, kb.data_product_member.kind_contract, kb.data_product_member.subject, kb.data_product_member.subject_definition, kb.data_product_member.original_source, kb.data_product_member.analyzed_scope, kb.data_product_member.body 
FROM kb.data_product_member 
WHERE kb.data_product_member.product_id = product.id AND kb.data_product_member.member_id = (selected ->> 'member_id') INTO STRICT member;
  END IF;
  SELECT coalesce(jsonb_agg(admitted.reference ORDER BY convert_to(data.canonical_json(data.ddo_json_meaning(admitted.reference)), 'UTF8')), CAST('[]' AS JSONB)) AS coalesce_1 
FROM (SELECT DISTINCT jsonb_strip_nulls(CASE WHEN (coalesce((entry.item ->> 'kind'), 'computation') = 'computation') THEN jsonb_build_object('kind', 'computation', 'derivation_id', entry.item ->> 'derivation_id', 'admission_use_id', entry.item ->> 'admission_use_id') ELSE jsonb_build_object('kind', entry.item ->> 'kind', 'admission_id', entry.item ->> 'admission_id', 'source_reference', entry.item ->> 'source_reference') END) AS reference 
FROM ops.ddo_input_support_refs(r.binding, selected) AS entry(item)) AS admitted INTO support_refs;
  IF (NOT ((selected ? 'producer_output')) OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(support_refs) AS ref 
WHERE (ref.value ->> 'kind') = 'computation')) AND jsonb_typeof(selected['producer_output']) IS DISTINCT FROM 'object' OR NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(support_refs) AS ref 
WHERE (ref.value ->> 'kind') = 'computation')) AND selected['producer_output'] IS DISTINCT FROM CAST('null' AS JSONB) OR ((selected['producer_output']) ->> 'member_id') IS NOT NULL AND ((selected['producer_output']) ->> 'member_id') IS DISTINCT FROM member.member_id) THEN
   RAISE EXCEPTION USING MESSAGE = 'CPU input basis requires its exact emitting occurrence and selected member', ERRCODE = '23514';
  END IF;
  output_meaning := CASE WHEN (selected['producer_output'] = CAST('null' AS JSONB)) THEN CAST('["null"]' AS JSONB) ELSE jsonb_build_array('mapping', jsonb_build_array(jsonb_build_array('member_id', CASE WHEN (((selected['producer_output']) ->> 'member_id') IS NULL) THEN CAST('["null"]' AS JSONB) ELSE jsonb_build_array('string', (selected['producer_output']) ->> 'member_id') END), jsonb_build_array('role', jsonb_build_array('string', (selected['producer_output']) ->> 'role')), jsonb_build_array('position', jsonb_build_array('integer', (selected['producer_output']) ->> 'position')), jsonb_build_array('multiplicity', jsonb_build_array('integer', (selected['producer_output']) ->> 'multiplicity')))) END;
  context_meaning := data.ddo_json_meaning(jsonb_build_object('project_id', r.project_id, 'subject', coalesce(member.subject, product.subject), 'subject_definition', coalesce(member.subject_definition, product.subject_definition), 'original_source', CASE WHEN (member.member_id IS NULL) THEN product.original_source ELSE member.original_source END, 'analyzed_scope', coalesce(member.analyzed_scope, product.analyzed_scope)));
  meaning := jsonb_build_array('mapping', jsonb_build_array(jsonb_build_array('role', jsonb_build_array('string', selected ->> 'role')), jsonb_build_array('position', CASE WHEN ((selected ->> 'position') IS NULL) THEN CAST('["null"]' AS JSONB) ELSE jsonb_build_array('integer', selected ->> 'position') END), jsonb_build_array('multiplicity', jsonb_build_array('integer', selected ->> 'multiplicity')), jsonb_build_array('product_id', jsonb_build_array('string', product.id)), jsonb_build_array('member_id', CASE WHEN (member.member_id IS NULL) THEN CAST('["null"]' AS JSONB) ELSE jsonb_build_array('string', member.member_id) END), jsonb_build_array('kind_contract', jsonb_build_array('string', coalesce(member.kind_contract, product.kind_contract))), jsonb_build_array('context', context_meaning), jsonb_build_array('body', coalesce(member.body, product.canonical_body)), jsonb_build_array('support', data.ddo_json_meaning(support_refs)), jsonb_build_array('producer_output', output_meaning)));
  roles := roles || jsonb_build_array(meaning);
 END LOOP;
 SELECT coalesce(jsonb_agg(role_rows.value ORDER BY (data.ddo_field(role_rows.value, 'role') ->> 1) COLLATE "C", CAST(data.ddo_field(role_rows.value, 'position') ->> 1 AS BIGINT) NULLS FIRST, (data.ddo_field(role_rows.value, 'product_id') ->> 1) COLLATE "C", ((data.ddo_field(role_rows.value, 'member_id') ->> 1) COLLATE "C") NULLS FIRST, (data.ddo_field(role_rows.value, 'kind_contract') ->> 1) COLLATE "C", convert_to(data.canonical_json(data.ddo_normalize(data.ddo_field(role_rows.value, 'support'))), 'UTF8'), convert_to(data.canonical_json(data.ddo_normalize(data.ddo_field(role_rows.value, 'producer_output'))), 'UTF8')), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(roles) AS role_rows INTO roles;
 RETURN data.ddo_normalize(jsonb_build_array('mapping', jsonb_build_array(jsonb_build_array('version', jsonb_build_array('string', 'cpu-input-basis-3')), jsonb_build_array('recipe', jsonb_build_array('string', r.recipe)), jsonb_build_array('context', data.ddo_json_meaning(jsonb_build_object('project_id', r.project_id, 'subject', r.subject, 'subject_definition', ops.ddo_operation_subject(r.release_id, r.operation_id), 'original_source', r.original_source, 'analyzed_scope', r.analyzed_scope))), jsonb_build_array('roles', jsonb_build_array('sequence', roles)), jsonb_build_array('parameters', data.ddo_normalize(data.ddo_field(r.binding['parameters'], 'parameters'))), jsonb_build_array('replicate', data.ddo_normalize(data.ddo_field(r.binding['parameters'], 'replicate'))))));
END

