DECLARE
 original ops.data_completion_intent%ROWTYPE;
 task ops.task%ROWTYPE;
 result jsonb;
 runtime text;
BEGIN
 SELECT ops.data_completion_intent.id, ops.data_completion_intent.request_id, ops.data_completion_intent.generation, ops.data_completion_intent.producer_task_id, ops.data_completion_intent.producer_attempt, ops.data_completion_intent.producer_holder, ops.data_completion_intent.runtime_id, ops.data_completion_intent.payload, ops.data_completion_intent.payload_digest, ops.data_completion_intent.created_at, ops.data_completion_intent.validation_seal 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.request_id = r.id AND ops.data_completion_intent.generation = CAST(((completion['execution_evidence']) ->> 'generation') AS INTEGER) INTO original;
 IF (found) THEN
  IF (original.payload_digest IS DISTINCT FROM ops.ddo_digest(completion) OR original.payload IS DISTINCT FROM completion) THEN
   RAISE EXCEPTION USING MESSAGE = 'CPU batch completion differs from immutable original intent digest/payload', ERRCODE = '23514';
  END IF;
  result := jsonb_build_object('request_id', original.request_id, 'generation', original.generation, 'task_id', original.producer_task_id, 'attempt', original.producer_attempt, 'holder', original.producer_holder);
  runtime := original.runtime_id;
 ELSE
  IF (EXISTS (SELECT 1 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.request_id = r.id AND ops.data_completion_intent.generation = r.generation)) THEN
   RAISE EXCEPTION USING MESSAGE = 'CPU batch completion differs from immutable original retained intent', ERRCODE = '23514';
  END IF;
  SELECT ops.task.id, ops.task.release_id, ops.task.data_request_id, ops.task.data_generation, ops.task.invocation_key, ops.task.trigger, ops.task.status, ops.task.attempt, ops.task.claimed_by, ops.task.lease_until, ops.task.result_digest, ops.task.error, ops.task.cost, ops.task.reason, ops.task.priority, ops.task.created_at, ops.task.started_at, ops.task.finished_at 
FROM ops.task 
WHERE ops.task.id = r.live_task_id AND ops.task.data_request_id = r.id AND ops.task.data_generation = r.generation AND ops.task.status = 'running' AND ops.task.lease_until > clock_timestamp() INTO STRICT task;
  result := jsonb_build_object('request_id', r.id, 'generation', r.generation, 'task_id', task.id, 'attempt', task.attempt, 'holder', task.claimed_by);
  runtime := (completion['execution_evidence']) ->> 'runtime_id';
  PERFORM sem.require_runtime_binding(r.release_id, runtime);
  PERFORM ops.ddo_require_provider_profile(r.release_id, r.operation_id, runtime);
  IF (NOT (EXISTS (SELECT 1 
FROM sem.runtime_binding 
WHERE sem.runtime_binding.release_id = r.release_id AND sem.runtime_binding.runtime_id = runtime AND (CAST(convert_from(sem.runtime_binding.manifest_bytes, 'UTF8') AS JSONB) ->> 'execution_profile') = (r.binding ->> 'execution_profile')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'CPU original runtime execution profile differs from admitted request', ERRCODE = '23514';
  END IF;
 END IF;
 IF ((EXISTS (SELECT 1 
FROM jsonb_each(result) AS field 
WHERE field.value IS DISTINCT FROM (completion['execution_evidence'] -> field.key))) OR ((completion['execution_evidence']) ->> 'runtime_id') IS DISTINCT FROM runtime) THEN
  RAISE EXCEPTION USING MESSAGE = 'CPU batch evidence differs from its native original producer owner', ERRCODE = '23514';
 END IF;
 RETURN result;
END

