DECLARE
 reply jsonb := ops.ddo_cpu_reply_value(completion);
 original ops.data_request%ROWTYPE := r;
 forms jsonb;
 item jsonb;
 chosen jsonb;
 producer jsonb;
 matches integer := 0;
BEGIN
 IF (NOT (completion ?& ARRAY['inputs', 'support'])) THEN
  RAISE EXCEPTION USING MESSAGE = 'CPU reply requires its original completion input/support binding', ERRCODE = '23514';
 END IF;
 original.binding := r.binding || jsonb_build_object('inputs', completion['inputs'], 'support', completion['support']);
 SELECT sem.data_operation_definition.support_contract['capabilities']['forms'] AS anon_1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id INTO STRICT forms;
 IF ((reply ->> 'version') = 'cpu-authority-reply-2') THEN
  IF (forms IS DISTINCT FROM CAST('["scalar"]' AS JSONB) OR NOT ((reply ?& ARRAY['version', 'input_basis_digest', 'output'])) OR (reply - ARRAY['version', 'input_basis_digest', 'output']) IS DISTINCT FROM CAST('{}' AS JSONB) OR (reply ->> 'input_basis_digest') IS DISTINCT FROM ops.ddo_digest(ops.ddo_cpu_input_basis(original))) THEN
   RAISE EXCEPTION USING MESSAGE = 'CPU authority reply differs from exact native input basis/form', ERRCODE = '23514';
  END IF;
  RETURN data.ddo_normalize(reply['output']);
 ELSE
  IF ((reply ->> 'version') = 'cpu-authority-batch-reply-1') THEN
   IF (forms IS DISTINCT FROM CAST('["batch"]' AS JSONB) OR NOT ((reply ?& ARRAY['version', 'members'])) OR (reply - ARRAY['version', 'members']) IS DISTINCT FROM CAST('{}' AS JSONB) OR jsonb_typeof(reply['members']) IS DISTINCT FROM 'array' OR jsonb_array_length(reply['members']) < 1) THEN
    RAISE EXCEPTION USING MESSAGE = 'CPU batch reply differs from its actual declared invocation form/membership', ERRCODE = '23514';
   END IF;
   IF ((EXISTS (SELECT 1 
FROM jsonb_array_elements(reply['members']) AS batch_member GROUP BY (batch_member.value ->> 'member') 
HAVING count(*) != 1)) OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(reply['members']) AS batch_member GROUP BY ((batch_member.value['producer']) ->> 'request_id'), batch_member.value['producer']['generation'] 
HAVING count(*) != 1))) THEN
    RAISE EXCEPTION USING MESSAGE = 'CPU batch reply repeats a logical member or original producing generation', ERRCODE = '23514';
   END IF;
   producer := ops.ddo_cpu_original_producer(r, completion);
   FOR item IN SELECT batch_member.value 
FROM jsonb_array_elements(reply['members']) AS batch_member LOOP
    IF (NOT ((item ?& ARRAY['member', 'producer', 'input_basis_digest', 'output'])) OR (item - ARRAY['member', 'producer', 'input_basis_digest', 'output']) IS DISTINCT FROM CAST('{}' AS JSONB) OR jsonb_typeof(item['member']) IS DISTINCT FROM 'string' OR nullif((item ->> 'member'), '') IS NULL OR jsonb_typeof(item['producer']) IS DISTINCT FROM 'object' OR NOT ((item['producer'] ?& ARRAY['request_id', 'generation', 'task_id', 'attempt', 'holder'])) OR (item['producer'] - ARRAY['request_id', 'generation', 'task_id', 'attempt', 'holder']) IS DISTINCT FROM CAST('{}' AS JSONB) OR ((item ->> 'input_basis_digest') ~ '^[0-9a-f]{64}$') IS NOT true) THEN
     RAISE EXCEPTION USING MESSAGE = 'CPU batch member lacks its exact original producer/basis/output', ERRCODE = '23514';
    END IF;
    PERFORM data.ddo_normalize(item['output']);
    IF (((item['producer']) ->> 'request_id') = r.id AND item['producer'] = producer) THEN
     matches := matches + 1;
     chosen := item;
    END IF;
   END LOOP;
   IF (matches != 1 OR (chosen ->> 'input_basis_digest') IS DISTINCT FROM ops.ddo_digest(ops.ddo_cpu_input_basis(original))) THEN
    RAISE EXCEPTION USING MESSAGE = 'CPU batch output differs from original producer fence/exact input basis', ERRCODE = '23514';
   END IF;
   RETURN data.ddo_normalize(chosen['output']);
  ELSE
   RAISE EXCEPTION USING MESSAGE = 'CPU authority reply has no current scalar or batch contract', ERRCODE = '23514';
  END IF;
 END IF;
END

