WHERE ops.data_derivation_output.product_id = (data.ddo_field(selected_input, 'product_id') ->> 1) AND ops.data_derivation_output.member_id IS NULL AND ops.data_derivation_output.multiplicity = 1 AND ops.data_derivation.outcome = 'success' AND ops.data_derivation.id IN (SELECT (references_.value ->> 'derivation_id') AS anon_1 
FROM jsonb_array_elements(data.ddo_json(data.ddo_field(selected_input, 'support'))) AS references_(value) 
WHERE (references_.value ->> 'kind') = 'computation') INTO STRICT episode;
 SELECT ops.data_derivation_output.role 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = episode.id AND ops.data_derivation_output.product_id = (data.ddo_field(selected_input, 'product_id') ->> 1) AND ops.data_derivation_output.member_id IS NULL AND ops.data_derivation_output.multiplicity = 1 INTO STRICT output_role;
