FROM ops.data_request 
WHERE ops.data_request.id = episode.request_id INTO STRICT r;
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = episode.intent_id AND ops.data_completion_intent.request_id = episode.request_id AND ops.data_completion_intent.generation = episode.generation INTO STRICT intent;
 r.release_id := episode.release_id;
 r.runtime_id := episode.runtime_id;
 r.recipe := episode.recipe;
 r.generation := episode.generation;
 r.binding := r.binding || jsonb_build_object('inputs', intent.payload['inputs'], 'support', intent.payload['support']);
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = episode.release_id AND sem.data_operation_definition.operation_id = r.operation_id INTO STRICT definition;
 IF (definition.profile IS DISTINCT FROM 'derivation' OR definition.support_contract['effects'] IS DISTINCT FROM CAST('[]' AS JSONB) OR definition.support_contract['capabilities']['forms'] IS DISTINCT FROM CAST('["scalar"]' AS JSONB) OR (((definition.support_contract['capabilities']['prepared_factory']) ->> 'source_digest') ~ '^[0-9a-f]{64}$') IS NOT true) THEN
  RAISE EXCEPTION USING MESSAGE = 'contextual component report lacks an actual captured scalar CPU producer', ERRCODE = '23514';
 END IF;
