 IF (jsonb_typeof(definition.support_contract['result_fields']) IS DISTINCT FROM 'object') THEN
  RAISE EXCEPTION USING MESSAGE = 'component source lacks its admitted exact result-field projection', ERRCODE = '23514';
 END IF;
