   RAISE EXCEPTION USING MESSAGE = 'component CPU reply lacks its admitted output projection', ERRCODE = '23514';
  END IF;
  actual := data.ddo_field(actual, result_field);
 ELSE
  IF (jsonb_array_length(definition.output_roles) != 1 OR ((definition.output_roles[0]) ->> 'name') IS DISTINCT FROM output_role) THEN
   RAISE EXCEPTION USING MESSAGE = 'component CPU reply requires its actual admitted single output contract', ERRCODE = '23514';
  END IF;
 END IF;
 IF (actual IS DISTINCT FROM data.ddo_field(selected_input, 'body')) THEN
  RAISE EXCEPTION USING MESSAGE = 'component source body differs from its actual original CPU reply', ERRCODE = '23514';
 END IF;
