 SELECT original_sources_.value 
FROM jsonb_array_elements((data.ddo_field(basis, 'roles'))[1]) AS original_sources_(value) 
WHERE (data.ddo_field(original_sources_.value, 'role') ->> 1) = 'source' INTO STRICT original_source_row;
