CREATE OR REPLACE FUNCTION ops.ddo_impl_admit_external_data_result(p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 p jsonb := p_payload;
 r ops.data_request%ROWTYPE;
 t ops.task%ROWTYPE;
 packet ops.data_external_packet%ROWTYPE;
 receipt ops.data_external_receipt%ROWTYPE;
 completion jsonb;
 evidence jsonb;
 retained jsonb;
 digest_ text;
 key text;
 intent text;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['packet_id', 'request_id', 'generation', 'task_id', 'attempt', 'holder', 'actor_assertion', 'model_assertion', 'completion'], ARRAY[]::TEXT[]);
 SELECT ops.data_external_packet.* 
FROM ops.data_external_packet 
WHERE ops.data_external_packet.id = (p ->> 'packet_id') AND ops.data_external_packet.request_id = (p ->> 'request_id') AND ops.data_external_packet.generation = CAST((p ->> 'generation') AS BIGINT) INTO STRICT packet;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = packet.request_id INTO STRICT r;
 PERFORM ops.ddo_authorize_request(r);
 completion := p['completion'];
 IF (completion ? 'execution_evidence') THEN
  RAISE EXCEPTION USING MESSAGE = 'external callers cannot manufacture execution custody', ERRCODE = 'P0001';
 END IF;
 digest_ := ops.ddo_digest(completion);
 SELECT ops.data_external_receipt.* 
FROM ops.data_external_receipt 
WHERE ops.data_external_receipt.packet_id = packet.id INTO receipt;
 IF (receipt.id IS NOT NULL) THEN
  IF (receipt.result_digest != digest_ OR receipt.actor_assertion != (p ->> 'actor_assertion') OR receipt.model_assertion IS DISTINCT FROM (p ->> 'model_assertion')) THEN
   RAISE EXCEPTION USING MESSAGE = 'external packet already retains a different immutable result/assertion', ERRCODE = 'P0001';
  END IF;
  SELECT ops.data_completion_intent.id 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.request_id = packet.request_id AND ops.data_completion_intent.generation = packet.generation INTO STRICT intent;
  RETURN jsonb_build_object('payload', jsonb_build_object('receipt', ops.ddo_external_receipt_value(receipt), 'intent_id', intent));
 END IF;
 PERFORM ops.ddo_lock_support(r.project_id, r.original_source, r.binding['support']);
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = r.id FOR UPDATE INTO STRICT r;
 SELECT ops.data_external_receipt.* 
FROM ops.data_external_receipt 
WHERE ops.data_external_receipt.packet_id = packet.id INTO receipt;
 IF (receipt.id IS NOT NULL) THEN
  IF (receipt.result_digest != digest_ OR receipt.actor_assertion != (p ->> 'actor_assertion') OR receipt.model_assertion IS DISTINCT FROM (p ->> 'model_assertion')) THEN
   RAISE EXCEPTION USING MESSAGE = 'external packet already retains a different immutable result/assertion', ERRCODE = 'P0001';
  END IF;
  SELECT ops.data_completion_intent.id 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.request_id = packet.request_id AND ops.data_completion_intent.generation = packet.generation INTO STRICT intent;
  RETURN jsonb_build_object('payload', jsonb_build_object('receipt', ops.ddo_external_receipt_value(receipt), 'intent_id', intent));
 END IF;
 t := ops.ddo_claim(r, p);
 PERFORM ops.ddo_assert_external_active(r);
 PERFORM ops.ddo_assert_support(r, r.binding['support']);
 IF (packet.payload['binding'] IS DISTINCT FROM r.binding OR (packet.payload ->> 'recipe') != r.recipe OR t.id != packet.task_id OR ((packet.payload['protocol']) ->> 'requested_actor') IS DISTINCT FROM (p ->> 'actor_assertion') OR ((packet.payload['protocol']) ->> 'requested_model') IS DISTINCT FROM (p ->> 'model_assertion')) THEN
  RAISE EXCEPTION USING MESSAGE = 'external result differs from exact packet/native claim/actor/model assertion contract', ERRCODE = 'P0001';
 END IF;
 IF (completion['inputs'] IS DISTINCT FROM r.binding['inputs'] OR completion['support'] IS DISTINCT FROM r.binding['support'] OR (completion ->> 'implementation_revision') IS DISTINCT FROM (packet.payload ->> 'implementation_revision')) THEN
  RAISE EXCEPTION USING MESSAGE = 'external result changes its immutable input/implementation binding', ERRCODE = 'P0001';
 END IF;
 IF (EXISTS (SELECT included.kind_contract 
FROM jsonb_array_elements(completion['outputs']) AS external_output(value) JOIN LATERAL ops.ddo_body_kind_contracts((external_output.value['product']) ->> 'kind_contract', data.ddo_normalize(external_output.value['product']['body'])) AS included(kind_contract) ON true JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = included.kind_contract 
WHERE sem.data_kind_contract.universe = 'evaluator')) THEN
  RAISE EXCEPTION USING MESSAGE = 'protected evaluator data cannot leave an external packet', ERRCODE = 'P0001';
 END IF;
 key := 'external-result:' || ops.ddo_digest(jsonb_build_array(packet.id, digest_));
 INSERT INTO ops.data_external_receipt (id, packet_id, packet_digest, request_id, generation, task_id, attempt, holder, runtime_id, admitting_principal, actor_assertion, model_assertion, result_digest, created_at) VALUES (key, packet.id, packet.payload_digest, r.id, r.generation, t.id, t.attempt, t.claimed_by, packet.runtime_id, SESSION_USER, (p ->> 'actor_assertion'), (p ->> 'model_assertion'), digest_, clock_timestamp()) RETURNING ops.data_external_receipt.id, ops.data_external_receipt.packet_id, ops.data_external_receipt.packet_digest, ops.data_external_receipt.request_id, ops.data_external_receipt.generation, ops.data_external_receipt.task_id, ops.data_external_receipt.attempt, ops.data_external_receipt.holder, ops.data_external_receipt.runtime_id, ops.data_external_receipt.admitting_principal, ops.data_external_receipt.actor_assertion, ops.data_external_receipt.model_assertion, ops.data_external_receipt.result_digest, ops.data_external_receipt.created_at INTO receipt;
 evidence := jsonb_build_object('version', 'native-execution-evidence-v1', 'request_id', r.id, 'generation', r.generation, 'task_id', t.id, 'attempt', t.attempt, 'holder', t.claimed_by, 'runtime_id', packet.runtime_id, 'host_receipts', CAST('[]' AS JSONB), 'cpu_receipts', CAST('[]' AS JSONB), 'pdf_receipts', CAST('[]' AS JSONB), 'provider_receipts', CAST('[]' AS JSONB), 'external_receipts', jsonb_build_array(ops.ddo_external_receipt_value(receipt)));
 completion := completion || jsonb_build_object('execution_evidence', evidence);
 retained := ops.retain_data_completion_intent(jsonb_build_object('request_id', r.id, 'generation', r.generation, 'task_id', t.id, 'attempt', t.attempt, 'holder', t.claimed_by, 'runtime_id', packet.runtime_id, 'completion', completion));
 RETURN jsonb_build_object('payload', jsonb_build_object('receipt', ops.ddo_external_receipt_value(receipt), 'intent_id', (retained['payload']) ->> 'intent_id'));
END$$

