 snapshot jsonb;
 results jsonb := CAST('[]' AS JSONB);
 cached jsonb := CAST('{}' AS JSONB);
 cache_key text;
 scope_key text;
BEGIN
 SELECT ops.data_demand_read.* 
FROM ops.data_demand_read 
WHERE ops.data_demand_read.id = (p ->> 'read_id') INTO STRICT boundary;
 SELECT ops.data_demand.* 
FROM ops.data_demand 
WHERE ops.data_demand.id = boundary.demand_id INTO STRICT demand;
 FOR scope_key IN SELECT DISTINCT scopes.scope 
FROM jsonb_array_elements(p['items']) AS attach_entry(value) JOIN ops.data_obligation ON ops.data_obligation.id = (attach_entry.value ->> 'obligation_id') AND ops.data_obligation.demand_id = demand.id JOIN LATERAL ops.ddo_support_scopes(demand.project_id, ops.data_obligation.original_source, attach_entry.value['binding']['support']) AS scopes(scope) ON true ORDER BY scopes.scope LOOP
  INSERT INTO ops.data_trust_scope (scope, project_id, epoch) VALUES (scope_key, demand.project_id, 0) ON CONFLICT DO NOTHING;
  PERFORM 1 AS anon_1 
FROM ops.data_trust_scope 
WHERE ops.data_trust_scope.scope = scope_key AND ops.data_trust_scope.project_id = demand.project_id FOR SHARE;
 END LOOP;
 read_trust := ops.ddo_require_read_current(boundary, demand.project_id);
 PERFORM ops.ddo_require_source_set_acquisitions(coalesce(demand.selection['source_sets'], CAST('{}' AS JSONB)), demand.project_id);
 FOR item IN SELECT attach_entry.value 
FROM jsonb_array_elements(p['items']) AS attach_entry(value) LOOP
  cache_key := ops.ddo_digest(item);
  IF (cached ? cache_key) THEN
   results := results || jsonb_build_array(cached[cache_key]);
   CONTINUE;
  END IF;
  BEGIN
   SELECT ops.data_obligation.* 
FROM ops.data_obligation 
WHERE ops.data_obligation.id = (item ->> 'obligation_id') AND ops.data_obligation.demand_id = demand.id INTO obligation;
   IF (obligation.id IS NULL OR ((item['binding']) ->> 'read_id') IS DISTINCT FROM boundary.id) THEN
    RAISE EXCEPTION USING MESSAGE = 'attach item differs from the admitted demand/read', ERRCODE = '23514';
   END IF;
   SELECT coalesce(jsonb_object_agg(item_scope.scope, read_trust[item_scope.scope]), CAST('{}' AS JSONB)) AS coalesce_1 
FROM ops.ddo_support_scopes(demand.project_id, obligation.original_source, item['binding']['support']) AS item_scope(scope) INTO snapshot;
   IF (EXISTS (SELECT support_epoch.value 
FROM jsonb_each(snapshot) AS support_epoch(key, value) 
WHERE support_epoch.value = CAST('null' AS JSONB))) THEN
    RAISE EXCEPTION USING MESSAGE = 'attach support is outside the pinned read scopes', ERRCODE = '23514';
   END IF;
   result := (ops.ddo_attach_data_request(item, read_trust, snapshot))['payload'];
   result := jsonb_build_object('state', result ->> 'fate', 'result', result);
  EXCEPTION WHEN check_violation THEN
   result := jsonb_build_object('state', 'refused', 'sqlstate', sqlstate, 'reason', sqlerrm);
  END;
  cached := cached || jsonb_build_object(cache_key, result);
  results := results || jsonb_build_array(result);
 END LOOP;
 RETURN jsonb_build_object('payload', jsonb_build_object('items', results));
END

