CREATE OR REPLACE FUNCTION ops.ddo_impl_claim_external_data_packet(p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 p jsonb := p_payload;
 packet ops.data_external_packet%ROWTYPE;
 r ops.data_request%ROWTYPE;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['packet_id', 'project_id', 'holder', 'lease_seconds'], ARRAY['demand_id']);
 SELECT ops.data_external_packet.* 
FROM ops.data_external_packet 
WHERE ops.data_external_packet.id = (p ->> 'packet_id') INTO STRICT packet;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = packet.request_id INTO STRICT r;
 PERFORM ops.ddo_authorize_request(r);
 IF (r.project_id != (p ->> 'project_id') OR (p ? 'demand_id') AND NOT (EXISTS (SELECT ops.demand_use.id 
FROM ops.demand_use 
WHERE ops.demand_use.demand_id = (p ->> 'demand_id') AND (ops.demand_use.request_id, ops.demand_use.generation) = (packet.request_id, packet.generation) AND ops.demand_use.fate = 'attached' AND ops.ddo_demand_active(ops.demand_use.demand_id)))) THEN
  RAISE EXCEPTION USING MESSAGE = 'external packet is outside the selected project/demand', ERRCODE = 'P0001';
 END IF;
 IF ((r.generation, r.live_task_id) IS DISTINCT FROM (packet.generation, packet.task_id)) THEN
  RETURN jsonb_build_object('payload', jsonb_build_object('state', 'no-work'));
 END IF;
 RETURN ops.ddo_claim_data_request(jsonb_build_object('request_id', r.id, 'generation', packet.generation, 'external_packet_id', packet.id, 'holder', p ->> 'holder', 'lease_seconds', p['lease_seconds']));
END$$

