DECLARE
 d ops.data_demand%ROWTYPE;
 x kb.data_product%ROWTYPE;
 producer ops.data_derivation%ROWTYPE;
 r ops.data_request%ROWTYPE;
 relation_ jsonb;
 members jsonb;
 complete boolean;
 evidence jsonb;
 key text;
 old ops.data_population%ROWTYPE;
 snapshot jsonb;
 semantic_key text;
 source_use ops.demand_use%ROWTYPE;
 source_obligation ops.data_obligation%ROWTYPE;
 inserted_count bigint;
BEGIN
 PERFORM ops.ddo_fields(p_payload, ARRAY['demand_id', 'name', 'product_id', 'derivation_id', 'member_role']);
 SELECT ops.data_demand.* 
FROM ops.data_demand 
WHERE ops.data_demand.id = (p_payload ->> 'demand_id') INTO STRICT d;
 SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = (p_payload ->> 'derivation_id') INTO STRICT producer;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = producer.request_id INTO STRICT r;
 SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = (p_payload ->> 'product_id') INTO STRICT x;
 snapshot := ops.ddo_lock_support(r.project_id, r.original_source, jsonb_build_array(jsonb_build_object('derivation_id', producer.id)));
 PERFORM ops.ddo_require_active_demand(d.id);
 SELECT ops.demand_use.* 
FROM ops.demand_use JOIN ops.data_obligation ON ops.data_obligation.id = ops.demand_use.obligation_id 
WHERE ops.demand_use.demand_id = d.id AND ops.demand_use.derivation_id = producer.id AND ops.ddo_node_valid('use', ops.demand_use.id) AND ops.demand_use.fate = 'fulfilled' AND ops.data_obligation.demand_id = d.id AND ops.data_obligation.subject IS NOT DISTINCT FROM x.subject AND ops.data_obligation.original_source IS NOT DISTINCT FROM x.original_source AND ops.data_obligation.analyzed_scope IS NOT DISTINCT FROM x.analyzed_scope AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(d.selection['discovery']) AS relation 
WHERE (relation.value ->> 'population') = (p_payload ->> 'name') AND (relation.value ->> 'producer') = ops.data_obligation.operation_id AND (relation.value ->> 'output_role') = (p_payload ->> 'member_role'))) ORDER BY ops.demand_use.created_at DESC, ops.demand_use.id DESC 
 LIMIT 1 INTO source_use;
 IF (source_use.id IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'population lacks admitted declared discovery output', ERRCODE = 'P0001';
 END IF;
 SELECT ops.data_obligation.* 
FROM ops.data_obligation 
WHERE ops.data_obligation.id = source_use.obligation_id INTO STRICT source_obligation;
 SELECT DISTINCT (relation.value - 'target') - 'target_role' AS anon_1 
FROM jsonb_array_elements(d.selection['discovery']) AS relation 
WHERE (relation.value ->> 'population') = (p_payload ->> 'name') AND (relation.value ->> 'producer') = source_obligation.operation_id AND (relation.value ->> 'output_role') = (p_payload ->> 'member_role') INTO STRICT relation_;
 IF (x.project_id != d.project_id OR r.project_id != d.project_id OR source_obligation.demand_id != d.id OR source_obligation.subject IS DISTINCT FROM x.subject OR source_obligation.original_source IS DISTINCT FROM x.original_source OR source_obligation.analyzed_scope IS DISTINCT FROM x.analyzed_scope OR NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = d.release_id AND sem.data_operation_definition.operation_id = source_obligation.operation_id AND sem.data_operation_definition.profile = 'discovery' AND sem.data_operation_definition.recipe = producer.recipe AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(sem.data_operation_definition.output_roles) AS current_discovery_output 
WHERE (current_discovery_output.value ->> 'name') = (p_payload ->> 'member_role') AND (current_discovery_output.value ->> 'kind_contract') = x.kind_contract)))) OR NOT (EXISTS (SELECT 1 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = producer.id AND ops.data_derivation_output.product_id = x.id AND ops.data_derivation_output.role = (p_payload ->> 'member_role')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'population lacks admitted declared discovery output', ERRCODE = 'P0001';
 END IF;
 PERFORM ops.ddo_authorize(sem.data_kind_contract.universe) AS ddo_authorize_1 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = x.kind_contract;
 IF (jsonb_typeof(data.ddo_json(data.ddo_field(x.canonical_body, 'complete'))) IS DISTINCT FROM 'boolean') THEN
  RAISE EXCEPTION USING MESSAGE = 'discovery closure must declare complete boolean', ERRCODE = 'P0001';
 END IF;
 complete := CAST(data.ddo_json(data.ddo_field(x.canonical_body, 'complete')) #>> '{}' AS BOOLEAN);
 IF (EXISTS (SELECT 1 
FROM kb.data_product_member 
WHERE kb.data_product_member.product_id = x.id AND (nullif(kb.data_product_member.subject, '') IS NULL OR nullif(kb.data_product_member.subject_definition, '') IS NULL OR kb.data_product_member.original_source IS DISTINCT FROM x.original_source OR kb.data_product_member.analyzed_scope IS NULL))) THEN
  RAISE EXCEPTION USING MESSAGE = 'discovery member lacks qualified subject/source/scope', ERRCODE = 'P0001';
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('member_id', kb.data_product_member.member_id, 'subject', kb.data_product_member.subject, 'subject_definition', kb.data_product_member.subject_definition, 'original_source', kb.data_product_member.original_source, 'analyzed_scope', kb.data_product_member.analyzed_scope) ORDER BY kb.data_product_member.member_id), CAST('[]' AS JSONB)) AS coalesce_1 
FROM kb.data_product_member 
WHERE kb.data_product_member.product_id = x.id INTO members;
 IF (EXISTS (SELECT 1 
FROM jsonb_array_elements(members) AS recorded GROUP BY recorded.value ->> 'subject', recorded.value ->> 'subject_definition', recorded.value ->> 'original_source', recorded.value['analyzed_scope'] 
HAVING count(*) != 1)) THEN
  RAISE EXCEPTION USING MESSAGE = 'discovery has ambiguous duplicate complete contexts', ERRCODE = 'P0001';
 END IF;
 semantic_key := 'population-value:' || ops.ddo_digest(jsonb_build_object('product', x.id, 'member_role', (p_payload ->> 'member_role'), 'members', members, 'complete', complete));
 evidence := jsonb_build_object('product_id', x.id, 'derivation_id', producer.id, 'member_role', p_payload ->> 'member_role', 'admission_use_id', source_use.id, 'trust_snapshot', snapshot, 'producer_context', jsonb_build_object('operation_id', r.operation_id, 'subject', r.subject, 'subject_definition', ops.ddo_operation_subject(r.release_id, source_obligation.operation_id), 'original_source', r.original_source, 'analyzed_scope', r.analyzed_scope));
 key := 'population:' || ops.ddo_digest(jsonb_build_array(d.id, (p_payload ->> 'name'), semantic_key, evidence));
 evidence := evidence || jsonb_build_object('population_id', key);
 PERFORM 1 
FROM ops.data_demand 
WHERE ops.data_demand.id = d.id FOR UPDATE;
 INSERT INTO ops.data_population (id, demand_id, semantic_key, name, context_key, members, complete, evidence, created_at, created_xid) VALUES (key, d.id, semantic_key, (p_payload ->> 'name'), ops.ddo_digest(ops.ddo_population_evidence_scope(evidence)), members, complete, evidence, clock_timestamp(), CAST(pg_current_xact_id() AS TEXT)) ON CONFLICT DO NOTHING;
 SELECT ops.data_population.* 
FROM ops.data_population 
WHERE ops.data_population.id = key INTO STRICT old;
 IF (NOT ops.ddo_node_valid('population', old.id)) THEN
  RAISE EXCEPTION USING MESSAGE = 'population witness is historical or no longer admitted', ERRCODE = 'P0001';
 END IF;
 WITH RECURSIVE allowed_operations(id) AS 
(SELECT relation.value ->> 'target' AS id 
FROM jsonb_array_elements(d.selection['discovery']) AS relation 
WHERE (relation.value ->> 'population') = old.name UNION SELECT allowed_operations_dependency_1.value AS value 
FROM allowed_operations JOIN jsonb_array_elements(d.selection['operations']) AS selected ON (selected.value ->> 'operation') = allowed_operations.id JOIN LATERAL jsonb_array_elements_text(selected.value['dependencies']) AS allowed_operations_dependency_1 ON true), 
qualified AS 
(SELECT jsonb_build_object('demand_id', d.id, 'operation_id', selected.value ->> 'operation', 'subject', admitted_member.value ->> 'subject', 'original_source', admitted_member.value ->> 'original_source', 'analyzed_scope', admitted_member.value['analyzed_scope'], 'parameters', selected.value['parameters']) AS payload 
FROM jsonb_array_elements(old.members) AS admitted_member JOIN jsonb_array_elements(d.selection['operations']) AS selected ON true JOIN allowed_operations ON allowed_operations.id = (selected.value ->> 'operation') 
WHERE (admitted_member.value ->> 'subject_definition') = ops.ddo_operation_subject(d.release_id, allowed_operations.id))
 INSERT INTO ops.data_obligation (id, demand_id, operation_id, subject, original_source, analyzed_scope, parameters, created_at, created_xid) SELECT 'obligation:' || ops.ddo_digest(qualified.payload) AS anon_1, d.id, qualified.payload ->> 'operation_id' AS anon_2, qualified.payload ->> 'subject' AS anon_3, qualified.payload ->> 'original_source' AS anon_4, qualified.payload['analyzed_scope'] AS anon_5, qualified.payload['parameters'] AS anon_6, clock_timestamp() AS clock_timestamp_1, CAST(pg_current_xact_id() AS TEXT) AS pg_current_xact_id_1 
FROM qualified 
WHERE true ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS inserted_count = ROW_COUNT;
 RETURN jsonb_build_object('payload', jsonb_build_object('inserted_obligations', inserted_count, 'population_id', key, 'semantic_key', semantic_key, 'name', old.name, 'complete', old.complete, 'members', old.members, 'evidence', old.evidence));
END

