DECLARE
 p jsonb := p_payload;
 r ops.data_request%ROWTYPE;
 t ops.task%ROWTYPE;
 key_ text;
 origin_ ops.data_execution_origin%ROWTYPE;
 definition_ sem.data_operation_definition%ROWTYPE;
 intent_ ops.data_completion_intent%ROWTYPE;
 consumed_ ops.data_draft_consumption%ROWTYPE;
 original_request_ ops.data_request%ROWTYPE;
 snapshot_ jsonb;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['request_id', 'generation', 'task_id', 'attempt', 'holder', 'origin_id', 'draft_id', 'completion']);
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = (p ->> 'request_id') INTO STRICT r;
 snapshot_ := ops.ddo_lock_completion_support(r, p['completion']);
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = (p ->> 'request_id') FOR UPDATE INTO STRICT r;
 t := ops.ddo_claim(r, p);
 SELECT ops.data_execution_origin.* 
FROM ops.data_execution_origin 
WHERE ops.data_execution_origin.id = (p ->> 'origin_id') INTO STRICT origin_;
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id INTO STRICT definition_;
 IF (NOT ((origin_.request_snapshot['request_key'] IS NOT DISTINCT FROM (to_jsonb(r))['request_key'] OR (((origin_.definition_snapshot['support_contract']) ->> 'reuse_eligible') = 'true' AND (((to_jsonb(definition_))['support_contract']) ->> 'reuse_eligible') = 'true') IS true) AND origin_.request_snapshot['project_id'] IS NOT DISTINCT FROM (to_jsonb(r))['project_id'] AND origin_.request_snapshot['operation_id'] IS NOT DISTINCT FROM (to_jsonb(r))['operation_id'] AND origin_.request_snapshot['recipe'] IS NOT DISTINCT FROM (to_jsonb(r))['recipe'] AND origin_.request_snapshot['subject'] IS NOT DISTINCT FROM (to_jsonb(r))['subject'] AND origin_.request_snapshot['original_source'] IS NOT DISTINCT FROM (to_jsonb(r))['original_source'] AND origin_.request_snapshot['analyzed_scope'] IS NOT DISTINCT FROM (to_jsonb(r))['analyzed_scope'] AND origin_.request_snapshot['replicate'] IS NOT DISTINCT FROM (to_jsonb(r))['replicate'] AND origin_.request_snapshot['binding']['inputs'] IS NOT DISTINCT FROM (to_jsonb(r))['binding']['inputs'] AND origin_.request_snapshot['binding']['support'] IS NOT DISTINCT FROM (to_jsonb(r))['binding']['support'] AND origin_.request_snapshot['binding']['parameters'] IS NOT DISTINCT FROM (to_jsonb(r))['binding']['parameters'] AND origin_.request_snapshot['binding']['request_inputs'] IS NOT DISTINCT FROM (to_jsonb(r))['binding']['request_inputs'] AND origin_.request_snapshot['binding']['inference'] IS NOT DISTINCT FROM (to_jsonb(r))['binding']['inference'] AND origin_.request_snapshot['binding']['execution_profile'] IS NOT DISTINCT FROM (to_jsonb(r))['binding']['execution_profile'] AND origin_.request_snapshot['binding']['populations'] IS NOT DISTINCT FROM (to_jsonb(r))['binding']['populations'] AND origin_.definition_snapshot['implementation_revision'] IS NOT DISTINCT FROM (to_jsonb(definition_))['implementation_revision'] AND origin_.definition_snapshot['profile'] IS NOT DISTINCT FROM (to_jsonb(definition_))['profile'] AND origin_.definition_snapshot['output_roles'] IS NOT DISTINCT FROM (to_jsonb(definition_))['output_roles'] AND origin_.definition_snapshot['support_contract'] IS NOT DISTINCT FROM (to_jsonb(definition_))['support_contract'])) THEN
  RAISE EXCEPTION USING MESSAGE = 'private completion material differs from the current request', ERRCODE = '23514';
 END IF;
 IF ((definition_.support_contract ->> 'reuse_eligible') = 'false' AND (origin_.request_id IS DISTINCT FROM r.id OR origin_.generation IS DISTINCT FROM r.generation OR origin_.task_id IS DISTINCT FROM t.id OR origin_.attempt IS DISTINCT FROM t.attempt OR origin_.holder IS DISTINCT FROM t.claimed_by)) THEN
  RAISE EXCEPTION USING MESSAGE = 'attempt-only completion cannot be adopted by another producer attempt', ERRCODE = '23514';
 END IF;
