DECLARE
 p jsonb := p_payload;
 pin jsonb;
 publication ops.pdf_published_revision%ROWTYPE;
 population ops.pdf_source_search_population%ROWTYPE;
 catalog jsonb;
 expected jsonb;
 actual jsonb;
 item jsonb;
 nodes jsonb;
 selected jsonb;
 ancestors jsonb;
 outcomes jsonb;
 body jsonb;
 rows jsonb;
 digest text;
 byte_count bigint;
 bound bigint;
BEGIN
 pin := ops.ddo_pdf_search_pin(p['source'], p['recipe']);
 publication := pg_catalog.jsonb_populate_record(CAST(NULL AS ops.pdf_published_revision), pin -> 'publication');
 IF ((p ->> 'configuration') IS DISTINCT FROM 'english') THEN
  RAISE EXCEPTION USING MESSAGE = 'unsupported search text configuration', ERRCODE = '23514';
 END IF;
 SELECT ops.pdf_source_search_population.population_id, ops.pdf_source_search_population.project_id, ops.pdf_source_search_population.build_id, ops.pdf_source_search_population.task_id, ops.pdf_source_search_population.product_key, ops.pdf_source_search_population.logical_digest, ops.pdf_source_search_population.recipe_digest, ops.pdf_source_search_population.configuration, ops.pdf_source_search_population.set_digest, ops.pdf_source_search_population.row_count, ops.pdf_source_search_population.byte_count, ops.pdf_source_search_population.sections 
FROM ops.pdf_source_search_population 
WHERE ops.pdf_source_search_population.population_id = (pin ->> 'population_id') INTO population;
 IF (population.population_id IS NULL) THEN
  PERFORM pg_advisory_xact_lock(hashtextextended(pin ->> 'population_id', 0));
  SELECT ops.pdf_source_search_population.population_id, ops.pdf_source_search_population.project_id, ops.pdf_source_search_population.build_id, ops.pdf_source_search_population.task_id, ops.pdf_source_search_population.product_key, ops.pdf_source_search_population.logical_digest, ops.pdf_source_search_population.recipe_digest, ops.pdf_source_search_population.configuration, ops.pdf_source_search_population.set_digest, ops.pdf_source_search_population.row_count, ops.pdf_source_search_population.byte_count, ops.pdf_source_search_population.sections 
FROM ops.pdf_source_search_population 
WHERE ops.pdf_source_search_population.population_id = (pin ->> 'population_id') INTO population;
 END IF;
 IF (NOT (p ? 'rows')) THEN
  RETURN jsonb_build_object('payload', jsonb_build_object('state', CASE WHEN (population.population_id IS NULL) THEN 'missing' ELSE 'ready' END, 'population_id', pin ->> 'population_id', 'set_digest', population.set_digest, 'row_count', coalesce(population.row_count, 0)));
 END IF;
 bound := coalesce(CAST(p ->> 'fill_max_bytes' AS BIGINT), 134217728);
 byte_count := octet_length(convert_to(data.canonical_json(p), 'UTF8'));
 IF (bound NOT BETWEEN 1 AND 134217728 OR byte_count > bound) THEN
  RAISE EXCEPTION USING MESSAGE = 'publication search fill exceeds its byte bound', ERRCODE = '54000';
 END IF;
 SELECT coalesce(jsonb_agg(source_rows.value ORDER BY (source_rows.value ->> 'section_pointer') COLLATE "C", (source_rows.value ->> 'membership') COLLATE "C"), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(p['rows']) AS source_rows(value) INTO rows;
 IF (EXISTS (SELECT 1 
FROM jsonb_array_elements(rows) AS ordered_rows(value) GROUP BY ordered_rows.value ->> 'section_pointer', ordered_rows.value ->> 'membership' 
HAVING count(*) != 1)) THEN
  RAISE EXCEPTION USING MESSAGE = 'search projection repeats a section/membership', ERRCODE = '23514';
 END IF;
 digest := ops.ddo_digest(rows);
 IF (population.population_id IS NOT NULL) THEN
  IF (population.set_digest IS DISTINCT FROM digest OR population.row_count != jsonb_array_length(rows) OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(rows) AS ordered_rows(value) 
WHERE NOT (EXISTS (SELECT 1 
FROM ops.pdf_source_search_section 
WHERE ops.pdf_source_search_section.population_id = population.population_id AND ops.pdf_source_search_section.section_pointer = (ordered_rows.value ->> 'section_pointer') AND ops.pdf_source_search_section.membership = (ordered_rows.value ->> 'membership') AND ops.pdf_source_search_section.text = ((ordered_rows.value['projection']) ->> 'text') AND ops.pdf_source_search_section.projection_digest = (ordered_rows.value ->> 'projection_digest') AND ops.pdf_source_search_section.packet_digest = ops.ddo_digest(ordered_rows.value))))) OR (SELECT count(*) AS count_1 
FROM ops.pdf_source_search_section 
WHERE ops.pdf_source_search_section.population_id = population.population_id) != population.row_count) THEN
   RAISE EXCEPTION USING MESSAGE = 'search projection exact-set replay differs', ERRCODE = '23514';
  END IF;
  RETURN jsonb_build_object('payload', jsonb_build_object('state', 'ready', 'population_id', population.population_id, 'set_digest', population.set_digest, 'row_count', population.row_count));
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('pointer', read_published_sections.pointer, 'name', read_published_sections.name, 'ancestors', to_jsonb(read_published_sections.ancestors)) ORDER BY read_published_sections.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM ops.read_pdf_published_sections(publication.task_id, publication.product_key, publication.logical_digest) AS read_published_sections INTO catalog;
 SELECT coalesce(jsonb_agg(jsonb_build_array(expected_keys.pointer, expected_keys.membership) ORDER BY expected_keys.pointer COLLATE "C", expected_keys.membership COLLATE "C"), CAST('[]' AS JSONB)) AS coalesce_1 
FROM (SELECT catalog_entries.value ->> 'pointer' AS pointer, memberships.membership AS membership 
FROM jsonb_array_elements(catalog) AS catalog_entries(value), (SELECT 'direct' AS membership UNION ALL SELECT 'descendants' AS membership) AS memberships UNION ALL SELECT '#/body' AS anon_1, 'direct' AS anon_2 
WHERE EXISTS (SELECT 1 
FROM ops.read_pdf_published_section_nodes(publication.task_id, publication.product_key, publication.logical_digest, '#/body', 'direct') AS read_published_section_nodes 
WHERE read_published_section_nodes.role = 'selected' AND read_published_section_nodes.pointer != '#/body')) AS expected_keys INTO expected;
 SELECT coalesce(jsonb_agg(jsonb_build_array(ordered_rows.value ->> 'section_pointer', ordered_rows.value ->> 'membership') ORDER BY (ordered_rows.value ->> 'section_pointer') COLLATE "C", (ordered_rows.value ->> 'membership') COLLATE "C"), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(rows) AS ordered_rows(value) INTO actual;
 IF (actual IS DISTINCT FROM expected) THEN
  RAISE EXCEPTION USING MESSAGE = 'search projection is not the complete publication section/membership set', ERRCODE = '23514';
 END IF;
 FOR item IN SELECT ordered_rows.value 
FROM jsonb_array_elements(rows) AS ordered_rows(value) LOOP
  SELECT coalesce(jsonb_agg(read_published_section_nodes.native_json ORDER BY read_published_section_nodes.ordinal), CAST('[]' AS JSONB)) AS coalesce_1, coalesce(jsonb_agg(to_jsonb(read_published_section_nodes.pointer) ORDER BY read_published_section_nodes.ordinal) FILTER (WHERE read_published_section_nodes.role = 'selected'), CAST('[]' AS JSONB)) AS coalesce_2, coalesce(jsonb_agg(to_jsonb(read_published_section_nodes.pointer) ORDER BY read_published_section_nodes.ordinal) FILTER (WHERE read_published_section_nodes.role = 'ancestor'), CAST('[]' AS JSONB)) AS coalesce_3 
FROM ops.read_pdf_published_section_nodes(publication.task_id, publication.product_key, publication.logical_digest, item ->> 'section_pointer', item ->> 'membership') AS read_published_section_nodes INTO nodes, selected, ancestors;
  IF (item['projection']['items'] IS DISTINCT FROM selected OR item['projection']['ancestors'] IS DISTINCT FROM ancestors) THEN
   RAISE EXCEPTION USING MESSAGE = 'search projection original member/ancestor population differs', ERRCODE = '23514';
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('pointer', read_published_section_reports.body ->> 'pointer', 'outcome', read_published_section_reports.body['outcome']) ORDER BY read_published_section_reports.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM ops.read_pdf_published_section_reports(publication.task_id, publication.product_key, publication.logical_digest, (SELECT coalesce(array_agg(selected_items.value), CAST('{}' AS TEXT[])) AS coalesce_2 
FROM jsonb_array_elements_text(selected) AS selected_items(value)), (SELECT coalesce(array_agg(report_scopes.pointer), CAST('{}' AS TEXT[])) AS coalesce_3 
FROM (SELECT item ->> 'section_pointer' AS pointer UNION SELECT ancestor_items.value AS value 
FROM jsonb_array_elements_text(ancestors) AS ancestor_items(value)) AS report_scopes)) AS read_published_section_reports 
WHERE (read_published_section_reports.body ->> 'kind') = 'formula_outcomes' INTO outcomes;
  IF (item['projection']['health']['formula_outcomes'] IS DISTINCT FROM outcomes) THEN
   RAISE EXCEPTION USING MESSAGE = 'search projection recognition differs from original source reports', ERRCODE = '23514';
  END IF;
  body := ops.ddo_native_source_body((pin['selected']) ->> 'original_source', item ->> 'section_pointer', item ->> 'membership', item['projection'], item ->> 'projection_digest', nodes, jsonb_build_array(jsonb_build_object('projection', item ->> 'projection_digest')));
  IF (((body['source']) ->> 'projection') IS DISTINCT FROM (item ->> 'projection_digest')) THEN
   RAISE EXCEPTION USING MESSAGE = 'search projection digest differs from authentic source packet', ERRCODE = '23514';
  END IF;
 END LOOP;
 INSERT INTO ops.pdf_source_search_population (population_id, project_id, build_id, task_id, product_key, logical_digest, recipe_digest, configuration, set_digest, row_count, byte_count, sections) VALUES ((pin ->> 'population_id'), ((p['source']) ->> 'project_id'), publication.build_id, publication.task_id, publication.product_key, publication.logical_digest, (pin ->> 'recipe_digest'), 'english', digest, jsonb_array_length(rows), byte_count, catalog);
 INSERT INTO ops.pdf_source_search_section (population_id, section_pointer, membership, text, projection_digest, packet_digest) SELECT pin ->> 'population_id' AS anon_1, ordered_rows.value ->> 'section_pointer' AS anon_2, ordered_rows.value ->> 'membership' AS anon_3, (ordered_rows.value['projection']) ->> 'text' AS anon_4, ordered_rows.value ->> 'projection_digest' AS anon_5, ops.ddo_digest(ordered_rows.value) AS ddo_digest_1 
FROM jsonb_array_elements(rows) AS ordered_rows(value);
 RETURN jsonb_build_object('payload', jsonb_build_object('state', 'ready', 'population_id', pin ->> 'population_id', 'set_digest', digest, 'row_count', jsonb_array_length(rows)));
END

