DECLARE
 i ops.data_completion_intent%ROWTYPE;
 r ops.data_request%ROWTYPE;
 receipt ops.data_publication_receipt%ROWTYPE;
BEGIN
 PERFORM ops.ddo_fields(p_payload, ARRAY['intent_id'], ARRAY['demand_id', 'request_id', 'generation']);
 IF (NOT ((p_payload ? 'demand_id') OR (p_payload ? 'request_id') AND (p_payload ? 'generation')) OR ((p_payload ? 'request_id')) != ((p_payload ? 'generation'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'inspection requires demand or exact request/generation binding', ERRCODE = 'P0001';
 END IF;
 IF ((p_payload ? 'demand_id') AND NOT (EXISTS (SELECT 1 
FROM ops.data_demand 
WHERE ops.data_demand.id = (p_payload ->> 'demand_id')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'unknown inspection demand', ERRCODE = 'P0001';
 END IF;
 IF (p_payload ? 'request_id') THEN
  SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = (p_payload ->> 'request_id') FOR SHARE INTO STRICT r;
 ELSE
  SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = (p_payload ->> 'intent_id') INTO i;
  IF (NOT found) THEN
   RETURN jsonb_build_object('payload', jsonb_build_object('state', 'unavailable', 'intent_retained', false, 'reason', 'intent-request-binding-unavailable'));
  END IF;
  SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = i.request_id FOR SHARE INTO STRICT r;
 END IF;
 PERFORM ops.ddo_authorize_request(r);
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = (p_payload ->> 'intent_id') AND ops.data_completion_intent.request_id = r.id AND (NOT ((p_payload ? 'generation')) OR ops.data_completion_intent.generation = CAST((p_payload ->> 'generation') AS BIGINT) OR (EXISTS (SELECT 1 
FROM ops.data_draft_consumption 
WHERE ops.data_draft_consumption.intent_id = ops.data_completion_intent.id AND ops.data_draft_consumption.request_id = r.id AND ops.data_draft_consumption.generation = CAST((p_payload ->> 'generation') AS BIGINT)))) INTO i;
 IF ((p_payload ? 'demand_id') AND NOT (EXISTS (SELECT 1 
FROM ops.demand_use 
WHERE ops.demand_use.demand_id = (p_payload ->> 'demand_id') AND ops.demand_use.request_id = r.id AND (NOT ((p_payload ? 'generation')) OR ops.demand_use.generation = CAST((p_payload ->> 'generation') AS BIGINT))))) THEN
  RAISE EXCEPTION USING MESSAGE = 'intent request outside inspection demand', ERRCODE = 'P0001';
 END IF;
 IF (i.id IS NULL) THEN
  RETURN jsonb_build_object('payload', jsonb_build_object('state', 'known-uncommitted', 'intent_retained', false));
 END IF;
 SELECT ops.data_publication_receipt.* 
FROM ops.data_publication_receipt 
WHERE ops.data_publication_receipt.intent_id = i.id INTO receipt;
 RETURN jsonb_build_object('payload', CASE WHEN found THEN jsonb_build_object('state', 'committed', 'intent_retained', true, 'receipt_id', receipt.id, 'derivation_id', receipt.derivation_id, 'producer_task_id', i.producer_task_id, 'producer_attempt', i.producer_attempt, 'runtime_id', i.runtime_id, 'semantic_outcome', i.payload ->> 'outcome', 'completion_state', (SELECT ops.data_derivation.outcome 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = receipt.derivation_id), 'trust_snapshot', receipt.trust_snapshot) ELSE jsonb_build_object('state', 'known-uncommitted', 'intent_retained', true, 'producer_task_id', i.producer_task_id, 'producer_attempt', i.producer_attempt) END);
END

