DECLARE
 p jsonb := p_payload;
 origin_ ops.data_execution_origin%ROWTYPE;
 intent_ ops.data_completion_intent%ROWTYPE;
 key_ text;
 receipt_id_ text;
 failure_id_ text;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['project_id', 'origin_id', 'draft_id', 'producer']);
 PERFORM ops.ddo_fields(p['producer'], ARRAY['request_id', 'generation', 'task_id', 'attempt', 'holder', 'runtime_id', 'completion']);
 SELECT ops.data_execution_origin.* 
FROM ops.data_execution_origin 
WHERE ops.data_execution_origin.id = (p ->> 'origin_id') INTO STRICT origin_;
 IF ((origin_.request_snapshot ->> 'project_id') IS DISTINCT FROM (p ->> 'project_id') OR to_jsonb(origin_.request_id) IS DISTINCT FROM p['producer']['request_id'] OR to_jsonb(origin_.generation) IS DISTINCT FROM p['producer']['generation'] OR to_jsonb(origin_.task_id) IS DISTINCT FROM p['producer']['task_id'] OR to_jsonb(origin_.attempt) IS DISTINCT FROM p['producer']['attempt'] OR to_jsonb(origin_.holder) IS DISTINCT FROM p['producer']['holder'] OR to_jsonb(origin_.runtime_id) IS DISTINCT FROM p['producer']['runtime_id'] OR (coalesce((p ->> 'draft_id'), '') !~ '^[0-9a-f]{64}$')) THEN
  RAISE EXCEPTION USING MESSAGE = 'completion draft differs from original custody', ERRCODE = 'P0001';
 END IF;
 key_ := 'intent:' || ops.ddo_digest(jsonb_build_array(origin_.request_id, origin_.generation, origin_.task_id, origin_.attempt, origin_.holder, origin_.runtime_id, p['producer']['completion']));
 IF (NOT (EXISTS (SELECT 1 
