DECLARE
 p jsonb := p_payload;
 projection jsonb;
 archived jsonb;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['release_id'], ARRAY['validity_only']);
 IF (NOT coalesce(CAST(p ->> 'validity_only' AS BOOLEAN), false)) THEN
  PERFORM data.require_execution_release(p ->> 'release_id');
 END IF;
 SELECT CAST(convert_from(sem.artifact.content, 'UTF8') AS JSONB) AS convert_from_1 
FROM sem.artifact 
WHERE sem.artifact.release_id = (p ->> 'release_id') AND sem.artifact.artifact_name = 'data_operation_native_definitions.json' AND (EXISTS (SELECT 1 
FROM sem.data_operation_release 
WHERE sem.data_operation_release.release_id = sem.artifact.release_id AND sem.data_operation_release.native_definitions_digest = encode(sha256(sem.artifact.content), 'hex'))) INTO projection;
 SELECT CAST(convert_from(sem.artifact.content, 'UTF8') AS JSONB) AS convert_from_1 
FROM sem.artifact 
WHERE sem.artifact.release_id = (p ->> 'release_id') AND sem.artifact.artifact_name = 'data_operations.json' AND encode(sha256(sem.artifact.content), 'hex') = (projection ->> 'model_digest') INTO archived;
 IF (projection IS NULL OR archived IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'read-only inspection lacks its authenticated operation archive', ERRCODE = '23514';
 END IF;
 IF (NOT (EXISTS (SELECT 1 
FROM sem.data_operation_release 
WHERE sem.data_operation_release.release_id = (p ->> 'release_id') AND (coalesce(CAST((p ->> 'validity_only') AS BOOLEAN), false) OR sem.data_operation_release.lowering_digest = (sem.data_operation_native_descriptor() ->> 'lowering_digest')) AND (coalesce(CAST((p ->> 'validity_only') AS BOOLEAN), false) OR sem.data_operation_release.binding_types = archived['kinds']) AND sem.data_operation_release.native_kernel_digest = (projection ->> 'native_digest') AND sem.data_operation_release.model_digest = (projection ->> 'model_digest')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'read-only inspection native source correspondence differs', ERRCODE = '23514';
 END IF;
 IF (NOT coalesce(CAST((p ->> 'validity_only') AS BOOLEAN), false) AND (EXISTS (WITH expected_kinds AS 
(SELECT (projected_kinds.value ->> 'kind_contract') AS key, projected_kinds.value AS body 
FROM jsonb_array_elements(projection['kinds']) AS projected_kinds(value)), 
actual_kinds AS 
(SELECT sem.data_kind_contract.kind_contract AS key, to_jsonb(data_kind_contract) AS body 
FROM sem.data_kind_contract JOIN sem.data_kind_release ON sem.data_kind_release.kind_contract = sem.data_kind_contract.kind_contract 
WHERE sem.data_kind_release.release_id = (p ->> 'release_id'))
 SELECT 1 
FROM expected_kinds FULL OUTER JOIN actual_kinds ON actual_kinds.key = expected_kinds.key 
WHERE expected_kinds.body IS DISTINCT FROM actual_kinds.body))) THEN
  RAISE EXCEPTION USING MESSAGE = 'read-only inspection admitted kind rowset differs from archived contracts', ERRCODE = '23514';
 END IF;
 IF (NOT coalesce(CAST((p ->> 'validity_only') AS BOOLEAN), false) AND (EXISTS (WITH expected_operations AS 
(SELECT (projected_operations.value ->> 'operation_id') AS key, (projected_operations.value - ARRAY['binding', 'definition', 'eligibility']) || jsonb_build_object('parameter_definitions', coalesce(authored_operations.value['parameters']['json'], jsonb_build_object())) AS body 
FROM jsonb_array_elements(projection['operations']) AS projected_operations(value) JOIN jsonb_array_elements(archived['operations']) AS authored_operations(value) ON (authored_operations.value ->> 'semantic_id') = (projected_operations.value ->> 'operation_id')), 
actual_operations AS 
(SELECT sem.data_operation_definition.operation_id AS key, to_jsonb(data_operation_definition) - ARRAY['release_id', 'binding_expression', 'definition_identity', 'eligibility_identity', 'quantified', 'command_class', 'dependencies'] AS body 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = (p ->> 'release_id'))
 SELECT 1 
FROM expected_operations FULL OUTER JOIN actual_operations ON actual_operations.key = expected_operations.key 
WHERE expected_operations.body IS DISTINCT FROM actual_operations.body))) THEN
  RAISE EXCEPTION USING MESSAGE = 'read-only inspection admitted operation rowset differs from archived contracts', ERRCODE = '23514';
 END IF;
 IF ((SELECT coalesce(jsonb_agg(sem.data_operation_definition.operation_id ORDER BY sem.data_operation_definition.operation_id), CAST('[]' AS JSONB)) AS coalesce_1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = (p ->> 'release_id') AND sem.data_operation_definition.validity_conservative) IS DISTINCT FROM (SELECT coalesce(jsonb_agg((projected_operations.value ->> 'operation_id') ORDER BY (projected_operations.value ->> 'operation_id')), CAST('[]' AS JSONB)) AS coalesce_2 
FROM jsonb_array_elements(projection['operations']) AS projected_operations(value) 
WHERE projected_operations.value['validity_conservative'] = CAST('true' AS JSONB))) THEN
  RAISE EXCEPTION USING MESSAGE = 'read-only inspection admitted validity differs from archived contracts', ERRCODE = '23514';
 END IF;
 RETURN jsonb_build_object('payload', jsonb_build_object('release_id', p ->> 'release_id', 'model_digest', projection ->> 'model_digest', 'native_digest', projection ->> 'native_digest', 'conservative_operations', (SELECT coalesce(jsonb_agg(sem.data_operation_definition.operation_id ORDER BY sem.data_operation_definition.operation_id), CAST('[]' AS JSONB)) AS coalesce_1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = (p ->> 'release_id') AND sem.data_operation_definition.validity_conservative)));
END

