DECLARE
 p jsonb := p_payload;
 r ops.data_request%ROWTYPE;
 packet ops.data_external_packet%ROWTYPE;
 receipt ops.data_external_receipt%ROWTYPE;
 intent text;
 publication jsonb;
 state_ text;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['packet_id'], ARRAY[]::TEXT[]);
 SELECT ops.data_external_packet.* 
FROM ops.data_external_packet 
WHERE ops.data_external_packet.id = (p ->> 'packet_id') INTO STRICT packet;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = packet.request_id INTO STRICT r;
 PERFORM ops.ddo_authorize_request(r);
 SELECT ops.data_external_receipt.* 
FROM ops.data_external_receipt 
WHERE ops.data_external_receipt.packet_id = packet.id INTO receipt;
 SELECT ops.data_completion_intent.id 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.request_id = packet.request_id AND ops.data_completion_intent.generation = packet.generation INTO intent;
 IF (intent IS NOT NULL) THEN
  publication := (ops.inspect_data_completion(jsonb_build_object('intent_id', intent, 'request_id', packet.request_id, 'generation', packet.generation)))['payload'];
 END IF;
 state_ := CASE WHEN ((publication ->> 'state') = 'committed') THEN 'committed' WHEN (r.generation != packet.generation) THEN 'superseded' WHEN NOT ops.ddo_request_useful(r) THEN 'cancelled' WHEN (receipt.id IS NOT NULL) THEN 'retained' ELSE 'awaiting-external' END;
 RETURN jsonb_build_object('payload', jsonb_build_object('packet_id', packet.id, 'state', state_, 'receipt', CASE WHEN (receipt.id IS NULL) THEN NULL ELSE ops.ddo_external_receipt_value(receipt) END, 'intent_id', intent, 'publication', publication));
END

