  RETURN jsonb_build_object('payload', jsonb_build_object('receipt_id', receipt.id, 'derivation_id', receipt.derivation_id, 'replayed', true, 'trust_snapshot', receipt.trust_snapshot));
 END IF;
 snapshot := ops.ddo_lock_completion_support(r, i.payload);
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = r.id FOR UPDATE INTO STRICT r;
 SELECT ops.data_publication_receipt.* 
FROM ops.data_publication_receipt 
WHERE ops.data_publication_receipt.intent_id = i.id INTO receipt;
 IF (found AND i.request_id = r.id AND (i.generation = CAST((p_payload ->> 'generation') AS BIGINT) OR (EXISTS (SELECT 1 
FROM ops.data_draft_consumption 
WHERE ops.data_draft_consumption.intent_id = i.id AND ops.data_draft_consumption.request_id = (p_payload ->> 'request_id') AND ops.data_draft_consumption.generation = CAST((p_payload ->> 'generation') AS BIGINT))))) THEN
  PERFORM ops.ddo_require_completion_effect_authority(r);
  PERFORM ops.ddo_reconfirm_completion_validity(receipt.id);
  RETURN jsonb_build_object('payload', jsonb_build_object('receipt_id', receipt.id, 'derivation_id', receipt.derivation_id, 'replayed', true, 'trust_snapshot', receipt.trust_snapshot));
 END IF;
 t := ops.ddo_claim(r, p_payload);
 IF (i.request_id != r.id OR NOT (EXISTS (SELECT 1 
FROM ops.data_draft_consumption 
WHERE ops.data_draft_consumption.intent_id = i.id AND ops.data_draft_consumption.request_id = (p_payload ->> 'request_id') AND ops.data_draft_consumption.generation = CAST((p_payload ->> 'generation') AS BIGINT))) AND (i.generation != r.generation OR i.generation != CAST((p_payload ->> 'generation') AS BIGINT)) OR NOT ((i.producer_task_id, i.producer_attempt, i.producer_holder) = (t.id, t.attempt, t.claimed_by) OR (EXISTS (SELECT 1 
FROM ops.data_intent_adoption 
WHERE ops.data_intent_adoption.intent_id = i.id AND (ops.data_intent_adoption.task_id, ops.data_intent_adoption.attempt, ops.data_intent_adoption.holder) = (t.id, t.attempt, t.claimed_by))))) THEN
  RAISE EXCEPTION USING MESSAGE = 'intent is not bound to current attempt', ERRCODE = 'P0001';
 END IF;
 IF (EXISTS (SELECT 1 
FROM ops.data_draft_consumption 
WHERE ops.data_draft_consumption.intent_id = i.id AND ops.data_draft_consumption.request_id = (p_payload ->> 'request_id') AND ops.data_draft_consumption.generation = CAST((p_payload ->> 'generation') AS BIGINT))) THEN
  PERFORM ops.ddo_require_completion_live(r, i.payload);
  SELECT ops.data_execution_origin.request_snapshot 
FROM ops.data_execution_origin JOIN ops.data_draft_consumption ON ops.data_draft_consumption.origin_id = ops.data_execution_origin.id 
WHERE ops.data_draft_consumption.intent_id = i.id AND ops.data_draft_consumption.request_id = r.id AND ops.data_draft_consumption.generation = CAST((p_payload ->> 'generation') AS BIGINT) INTO STRICT original_request_;
  r := jsonb_populate_record(r, original_request_);
 END IF;
 PERFORM ops.ddo_assert_support(r, i.payload['support']);
 PERFORM sem.require_runtime_binding(r.release_id, i.runtime_id);
 IF (NOT (EXISTS (SELECT 1 
FROM sem.runtime_binding 
WHERE sem.runtime_binding.release_id = r.release_id AND sem.runtime_binding.runtime_id = i.runtime_id AND sem.runtime_binding.execution_profile = (r.binding ->> 'execution_profile')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'producing runtime execution profile differs', ERRCODE = 'P0001';
 END IF;
 PERFORM ops.ddo_require_provider_profile(r.release_id, r.operation_id, i.runtime_id);
 IF (EXISTS (SELECT 1 
FROM ops.data_revocation 
WHERE ops.data_revocation.scope = ops.ddo_scope(r.project_id, r.original_source) AND (ops.data_revocation.selector_kind = 'runtime' AND ops.data_revocation.selector = i.runtime_id OR ops.data_revocation.selector_kind = 'recipe' AND ops.data_revocation.selector = r.recipe))) THEN
  RAISE EXCEPTION USING MESSAGE = 'producing runtime or recipe was directly revoked', ERRCODE = 'P0001';
 END IF;
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id INTO STRICT def;
 result_state := ops.ddo_completion_state(def, i.payload ->> 'outcome');
 IF ((i.payload ->> 'implementation_revision') != def.implementation_revision OR jsonb_typeof(i.payload['outputs']) != 'array') THEN
  RAISE EXCEPTION USING MESSAGE = 'invalid completion attestation/outcome', ERRCODE = 'P0001';
 END IF;
 IF (result_state IN ('empty', 'failed') AND i.payload['outputs'] != CAST('[]' AS JSONB)) THEN
  RAISE EXCEPTION USING MESSAGE = 'non-success completion cannot publish outputs', ERRCODE = 'P0001';
 END IF;
 IF (i.validation_seal IS DISTINCT FROM ops.ddo_completion_seal(r, i.payload, i.runtime_id, snapshot)) THEN
  PERFORM ops.ddo_require_completion_correspondence(r, i.payload, i.producer_task_id, i.producer_attempt, i.producer_holder);
 END IF;
 PERFORM ops.ddo_require_completion_live(r, i.payload);
 episode := 'derivation:' || ops.ddo_digest(jsonb_build_array(i.id, i.payload_digest));
 INSERT INTO ops.data_derivation (id, request_id, generation, intent_id, release_id, recipe, runtime_id, producer_task_id, producer_attempt, outcome, completed_at) VALUES (episode, r.id, r.generation, i.id, r.release_id, r.recipe, i.runtime_id, i.producer_task_id, i.producer_attempt, result_state, clock_timestamp());
 FOR item, n IN SELECT anon_1.input_record, anon_1.physical_position 
FROM ops.ddo_derivation_input_positions(i.payload['inputs'], def.input_roles) AS anon_1 LOOP
  INSERT INTO ops.data_derivation_input (derivation_id, role, position, multiplicity, product_id, member_id) VALUES (episode, (item ->> 'role'), n, CAST(item ->> 'multiplicity' AS BIGINT), (item ->> 'product_id'), (item ->> 'member_id'));
 END LOOP;
 FOR item, n IN SELECT ordered_support.value, ordered_support.ord - 1 AS anon_1 
FROM jsonb_array_elements(i.payload['support']) WITH ORDINALITY AS ordered_support(value, ord) LOOP
  IF ((item ->> 'kind') IN ('original-source', 'authored')) THEN
   INSERT INTO ops.data_derivation_original_support (derivation_id, occurrence, role, position, admission_id, source_reference, scope, epoch) SELECT episode, n, item ->> 'role' AS anon_1, CAST(item ->> 'position' AS BIGINT) AS anon_2, ops.original_source_admission.id, ops.original_source_admission.source_reference, ops.ddo_scope(ops.original_source_admission.project_id, ops.original_source_admission.original_source) AS ddo_scope_1, CAST(snapshot ->> ops.ddo_scope(ops.original_source_admission.project_id, ops.original_source_admission.original_source) AS BIGINT) AS anon_3 
FROM ops.original_source_admission 
WHERE ops.original_source_admission.id = (item ->> 'admission_id');
   CONTINUE;
  END IF;
  INSERT INTO ops.data_derivation_support (derivation_id, role, position, support_derivation_id, scope, epoch, admission_use_id, occurrence) SELECT episode, coalesce(item ->> 'role', 'support') AS coalesce_1, coalesce(CAST(item ->> 'position' AS BIGINT), n) AS coalesce_2, item ->> 'derivation_id' AS anon_1, ops.ddo_scope(ops.data_request.project_id, ops.data_request.original_source) AS ddo_scope_1, CAST(snapshot ->> ops.ddo_scope(ops.data_request.project_id, ops.data_request.original_source) AS BIGINT) AS anon_2, item ->> 'admission_use_id' AS anon_3, n 
FROM ops.data_derivation JOIN ops.data_request ON ops.data_request.id = ops.data_derivation.request_id 
WHERE ops.data_derivation.id = (item ->> 'derivation_id');
 END LOOP;
 subject_scopes := ops.ddo_release_subject_scopes(r.release_id);
 output_context := jsonb_build_object('project_id', r.project_id, 'release_id', r.release_id, 'subject', r.subject, 'subject_definition', ops.ddo_operation_subject(r.release_id, r.operation_id), 'original_source', r.original_source, 'analyzed_scope', r.analyzed_scope);
 FOR o IN SELECT output_rows.value 
FROM jsonb_array_elements(i.payload['outputs']) AS output_rows LOOP
  PERFORM ops.ddo_fields(o, ARRAY['role', 'position', 'multiplicity', 'product'], ARRAY['member_id']);
  SELECT output_roles.value 
FROM jsonb_array_elements(def.output_roles) AS output_roles 
WHERE (output_roles.value ->> 'name') = (o ->> 'role') INTO roledef;
  IF (roledef IS NULL OR (o ->> 'member_id') IS NULL AND (roledef ->> 'kind_contract') IS DISTINCT FROM ((o['product']) ->> 'kind_contract')) THEN
   RAISE EXCEPTION USING MESSAGE = 'output role/kind mismatch', ERRCODE = 'P0001';
  END IF;
  product := ops.ddo_install_product_context(output_context, o['product'], subject_scopes);
  IF ((o ->> 'member_id') IS NOT NULL AND NOT (EXISTS (SELECT 1 
FROM kb.data_product_member 
WHERE kb.data_product_member.product_id = product AND kb.data_product_member.member_id = (o ->> 'member_id') AND kb.data_product_member.kind_contract = (roledef ->> 'kind_contract')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'output member is outside its qualified product', ERRCODE = 'P0001';
  END IF;
  INSERT INTO ops.data_derivation_output (derivation_id, role, position, multiplicity, product_id, member_id) VALUES (episode, (o ->> 'role'), CAST(o ->> 'position' AS BIGINT), CAST(o ->> 'multiplicity' AS BIGINT), product, (o ->> 'member_id'));
 END LOOP;
 IF (result_state = 'success') THEN
  FOR roledef IN SELECT output_roles.value 
FROM jsonb_array_elements(def.output_roles) AS output_roles LOOP
   SELECT coalesce(sum(ops.data_derivation_output.multiplicity), 0) AS coalesce_1 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = episode AND ops.data_derivation_output.role = (roledef ->> 'name') INTO cnt;
   IF ((roledef ->> 'collection') = 'set' AND ((EXISTS (SELECT 1 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = episode AND ops.data_derivation_output.role = (roledef ->> 'name') AND ops.data_derivation_output.multiplicity != 1)) OR (EXISTS (SELECT 1 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = episode AND ops.data_derivation_output.role = (roledef ->> 'name') GROUP BY ops.data_derivation_output.product_id, ops.data_derivation_output.member_id 
HAVING count(*) != 1)))) THEN
    RAISE EXCEPTION USING MESSAGE = 'set output requires unique values and unit multiplicity', ERRCODE = 'P0001';
   END IF;
   IF (cnt < coalesce(CAST((roledef ->> 'minimum') AS INTEGER), 0) OR (roledef ->> 'maximum') IS NOT NULL AND cnt > CAST((roledef ->> 'maximum') AS INTEGER)) THEN
    RAISE EXCEPTION USING MESSAGE = 'output cardinality differs from contract', ERRCODE = 'P0001';
   END IF;
  END LOOP;
 END IF;
 key := 'receipt:' || ops.ddo_digest(jsonb_build_array(i.id, episode));
 INSERT INTO ops.data_publication_receipt (id, intent_id, derivation_id, publishing_task_id, publishing_attempt, trust_snapshot, validating_kernel_digest, validation_identities) VALUES (key, i.id, episode, t.id, t.attempt, snapshot, (sem.data_operation_native_descriptor() ->> 'source_digest'), ops.ddo_current_validation_identities(r.release_id, r.operation_id));
 UPDATE ops.task SET status=CASE WHEN (result_state = 'success') THEN 'done' WHEN (result_state = 'empty') THEN 'empty' ELSE 'failed' END, lease_until=NULL, result_digest=i.payload_digest, error=CASE WHEN (result_state = 'failed') THEN jsonb_build_object('data_operation', 'failed') END, finished_at=clock_timestamp() WHERE ops.task.id = t.id;
 INSERT INTO ops.demand_use (id, demand_id, obligation_id, fate, request_id, generation, derivation_id, selection, trust_snapshot, created_at, created_xid) SELECT 'use:' || ops.ddo_digest(jsonb_build_array(latest_observations.obligation_id, key)) AS anon_1, latest_observations.demand_id, latest_observations.obligation_id, CASE WHEN (result_state = 'failed') THEN 'failed' ELSE 'fulfilled' END AS anon_2, r.id, CAST(p_payload ->> 'generation' AS BIGINT) AS anon_3, episode, latest_observations.selection, snapshot, clock_timestamp() AS clock_timestamp_1, CAST(pg_current_xact_id() AS TEXT) AS pg_current_xact_id_1 
FROM (SELECT DISTINCT ON (ops.demand_use.obligation_id) ops.demand_use.id AS id, ops.demand_use.demand_id AS demand_id, ops.demand_use.obligation_id AS obligation_id, ops.demand_use.fate AS fate, ops.demand_use.request_id AS request_id, ops.demand_use.generation AS generation, ops.demand_use.derivation_id AS derivation_id, ops.demand_use.selection AS selection, ops.demand_use.trust_snapshot AS trust_snapshot, ops.demand_use.created_at AS created_at, ops.demand_use.created_xid AS created_xid 
FROM ops.demand_use 
WHERE ops.demand_use.request_id = r.id AND ops.demand_use.generation = CAST((p_payload ->> 'generation') AS BIGINT) ORDER BY ops.demand_use.obligation_id, ops.demand_use.created_at DESC, ops.demand_use.id DESC) AS latest_observations 
WHERE latest_observations.fate = 'attached' AND ops.ddo_demand_active(latest_observations.demand_id) ON CONFLICT DO NOTHING;
 RETURN jsonb_build_object('payload', jsonb_build_object('receipt_id', key, 'derivation_id', episode, 'replayed', false, 'trust_snapshot', snapshot));
END

