DECLARE
 keys jsonb;
 selection text;
 result jsonb;
 query tsquery;
 after_score double precision;
 after_key text;
 page_limit integer := CAST(p_payload ->> 'limit' AS INTEGER);
BEGIN
 SELECT coalesce(jsonb_agg(to_jsonb(key_rows)), CAST('[]' AS JSONB)) AS coalesce_1 
FROM ops.ddo_pdf_search_keys(p_payload) AS key_rows INTO keys;
 selection := ops.ddo_digest(jsonb_build_array(p_payload['binding'], p_payload ->> 'cut_id', (SELECT coalesce(jsonb_agg(entries.value ->> 'key' ORDER BY (entries.value ->> 'key') COLLATE "C"), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(keys) AS entries(value))));
 IF (p_payload ? 'after') THEN
  IF (((p_payload['after']) ->> 'selection') IS DISTINCT FROM selection) THEN
   RAISE EXCEPTION USING MESSAGE = 'search continuation belongs to another source population', ERRCODE = '22023';
  END IF;
  after_score := CAST((p_payload['after']) ->> 'score' AS FLOAT);
  after_key := (p_payload['after']) ->> 'key';
 END IF;
 query := websearch_to_tsquery(CAST('english' AS REGCONFIG), (p_payload['binding']) ->> 'text');
 WITH candidates AS MATERIALIZED 
(SELECT CAST(entries.value ->> 'source_index' AS INTEGER) AS source_index, ops.pdf_source_search_section.population_id AS population_id, ops.pdf_source_search_section.section_pointer AS section_pointer, ops.pdf_source_search_section.membership AS membership, ops.pdf_source_search_section.projection_digest AS projection_digest, entries.value ->> 'key' AS key, CAST(ts_rank_cd(ops.pdf_source_search_section.search_vector, query) AS FLOAT) AS score 
FROM jsonb_array_elements(keys) AS entries(value) JOIN ops.pdf_source_search_section ON ops.pdf_source_search_section.population_id = (entries.value ->> 'population_id') AND ops.pdf_source_search_section.section_pointer = (entries.value ->> 'section_pointer') AND ops.pdf_source_search_section.membership = (entries.value ->> 'membership') 
WHERE ops.pdf_source_search_section.search_vector @@ query), 
limited AS MATERIALIZED 
(SELECT candidates.source_index AS source_index, candidates.population_id AS population_id, candidates.section_pointer AS section_pointer, candidates.membership AS membership, candidates.projection_digest AS projection_digest, candidates.key AS key, candidates.score AS score 
FROM candidates 
WHERE after_key IS NULL OR candidates.score < after_score OR candidates.score = after_score AND (candidates.key COLLATE "C") > (after_key COLLATE "C") ORDER BY candidates.score DESC, candidates.key COLLATE "C" 
 LIMIT page_limit + 1), 
page AS MATERIALIZED 
(SELECT limited.source_index AS source_index, limited.population_id AS population_id, limited.section_pointer AS section_pointer, limited.membership AS membership, limited.projection_digest AS projection_digest, limited.key AS key, limited.score AS score 
FROM limited ORDER BY limited.score DESC, limited.key COLLATE "C" 
 LIMIT page_limit), 
returned AS MATERIALIZED 
(SELECT page.source_index AS source_index, page.population_id AS population_id, page.section_pointer AS section_pointer, page.membership AS membership, page.projection_digest AS projection_digest, page.key AS key, page.score AS score, ops.pdf_source_search_section.text AS text 
FROM page JOIN ops.pdf_source_search_section ON ops.pdf_source_search_section.population_id = page.population_id AND ops.pdf_source_search_section.section_pointer = page.section_pointer AND ops.pdf_source_search_section.membership = page.membership)
 SELECT jsonb_build_object('selection', selection, 'more', (SELECT count(*) > page_limit AS anon_1 
FROM limited), 'rows', coalesce(jsonb_agg(jsonb_build_object('source_index', returned.source_index, 'section_pointer', returned.section_pointer, 'membership', returned.membership, 'projection_digest', returned.projection_digest, 'key', returned.key, 'score', returned.score, 'excerpt', ts_headline(CAST('english' AS REGCONFIG), returned.text, query, 'MaxWords=45,MinWords=15')) ORDER BY returned.score DESC, returned.key COLLATE "C"), CAST('[]' AS JSONB))) AS jsonb_build_object_1 
FROM returned INTO result;
 RETURN jsonb_build_object('payload', result);
END

