DECLARE
 p jsonb := p_payload;
 r ops.data_request%ROWTYPE;
 packet ops.data_external_packet%ROWTYPE;
 t ops.task%ROWTYPE;
 receipt ops.data_external_receipt%ROWTYPE;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['packet_id', 'request_id', 'generation', 'task_id', 'attempt', 'holder', 'max_bytes'], ARRAY[]::TEXT[]);
 SELECT ops.data_external_packet.* 
FROM ops.data_external_packet 
WHERE ops.data_external_packet.id = (p ->> 'packet_id') AND ops.data_external_packet.request_id = (p ->> 'request_id') AND ops.data_external_packet.generation = CAST((p ->> 'generation') AS BIGINT) INTO STRICT packet;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = packet.request_id INTO STRICT r;
 PERFORM ops.ddo_authorize_request(r);
 SELECT ops.data_external_receipt.* 
FROM ops.data_external_receipt 
WHERE ops.data_external_receipt.packet_id = packet.id INTO receipt;
 IF (receipt.id IS NOT NULL AND (receipt.request_id, receipt.generation, receipt.task_id, receipt.attempt, receipt.holder) IS NOT DISTINCT FROM ((p ->> 'request_id'), CAST((p ->> 'generation') AS BIGINT), CAST((p ->> 'task_id') AS BIGINT), CAST((p ->> 'attempt') AS BIGINT), (p ->> 'holder'))) THEN
  IF (octet_length(data.canonical_json(packet.payload)) > CAST((p ->> 'max_bytes') AS INTEGER)) THEN
   RAISE EXCEPTION USING MESSAGE = 'historical external packet exceeds transport capacity', ERRCODE = 'P0001';
  END IF;
  RETURN jsonb_build_object('payload', jsonb_build_object('packet_id', packet.id, 'packet_digest', packet.payload_digest, 'packet', packet.payload));
 END IF;
 PERFORM ops.ddo_lock_support(r.project_id, r.original_source, r.binding['support']);
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = r.id FOR UPDATE INTO STRICT r;
 t := ops.ddo_claim(r, p);
 PERFORM ops.ddo_assert_external_active(r);
 PERFORM ops.ddo_assert_support(r, r.binding['support']);
 IF (t.id != packet.task_id OR packet.payload['binding'] IS DISTINCT FROM r.binding OR (packet.payload ->> 'recipe') != r.recipe) THEN
  RAISE EXCEPTION USING MESSAGE = 'external packet changed native request binding', ERRCODE = 'P0001';
 END IF;
 IF (octet_length(data.canonical_json(packet.payload)) > CAST((p ->> 'max_bytes') AS INTEGER)) THEN
  RAISE EXCEPTION USING MESSAGE = 'external packet exceeds transport capacity', ERRCODE = 'P0001';
 END IF;
 RETURN jsonb_build_object('payload', jsonb_build_object('packet_id', packet.id, 'packet_digest', packet.payload_digest, 'packet', packet.payload));
END

