DECLARE
 p jsonb := p_payload;
 lim integer;
 result jsonb;
 queue_id text;
 queue_payload_digest text;
 queue_request_id text;
 queue_generation bigint;
 queue_task_id bigint;
 queue_operation_id text;
 queue_subject text;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['project_id'], ARRAY['demand_id', 'limit']);
 lim := coalesce(CAST(p ->> 'limit' AS INTEGER), 1);
 IF (lim NOT BETWEEN 1 AND 64) THEN
  RAISE EXCEPTION USING MESSAGE = 'invalid external queue bound', ERRCODE = 'P0001';
 END IF;
 result := CAST('[]' AS JSONB);
 FOR queue_id, queue_payload_digest, queue_request_id, queue_generation, queue_task_id, queue_operation_id, queue_subject IN SELECT queue_packet.id, queue_packet.payload_digest, queue_packet.request_id, queue_packet.generation, queue_packet.task_id, queue_request.operation_id, queue_request.subject 
FROM ops.data_external_packet AS queue_packet JOIN ops.data_request AS queue_request ON (queue_request.id, queue_request.generation, queue_request.live_task_id) = (queue_packet.request_id, queue_packet.generation, queue_packet.task_id) JOIN ops.task AS queue_task ON queue_task.id = queue_packet.task_id 
WHERE queue_request.project_id = (p ->> 'project_id') AND ops.ddo_request_useful(queue_request) AND (queue_task.status = 'pending' OR queue_task.status = 'running' AND queue_task.lease_until <= clock_timestamp()) AND NOT (EXISTS (SELECT queue_receipt.id 
FROM ops.data_external_receipt AS queue_receipt 
WHERE queue_receipt.packet_id = queue_packet.id)) AND NOT (EXISTS (SELECT 1 AS anon_1 
FROM ops.data_revocation AS queue_revoked 
WHERE queue_revoked.scope = ops.ddo_scope(queue_request.project_id, queue_request.original_source) AND (queue_revoked.selector_kind = 'runtime' AND queue_revoked.selector = queue_request.runtime_id OR queue_revoked.selector_kind = 'recipe' AND queue_revoked.selector = queue_request.recipe))) AND (NOT (p ? 'demand_id') OR (EXISTS (SELECT queue_use.id 
FROM ops.demand_use AS queue_use 
WHERE queue_use.demand_id = (p ->> 'demand_id') AND (queue_use.request_id, queue_use.generation) = (queue_packet.request_id, queue_packet.generation) AND queue_use.fate = 'attached' AND ops.ddo_demand_active(queue_use.demand_id)))) ORDER BY queue_packet.created_at, queue_packet.id 
 LIMIT lim LOOP
  PERFORM ops.ddo_authorize_request(data_request) AS ddo_authorize_request_1 
FROM ops.data_request 
WHERE ops.data_request.id = queue_request_id;
  result := result || jsonb_build_array(jsonb_build_object('packet_id', queue_id, 'packet_digest', queue_payload_digest, 'request_id', queue_request_id, 'generation', queue_generation, 'task_id', queue_task_id, 'operation_id', queue_operation_id, 'subject', queue_subject, 'state', 'awaiting-external'));
 END LOOP;
 RETURN jsonb_build_object('payload', jsonb_build_object('packets', result));
END

