DECLARE
 p jsonb := p_payload;
 d ops.data_demand%ROWTYPE;
 boundary ops.data_demand_read%ROWTYPE;
 definition sem.data_operation_definition%ROWTYPE;
 episode ops.data_derivation%ROWTYPE;
 intent ops.data_completion_intent%ROWTYPE;
 p_use text := p ->> 'use_id';
 p_product text := p ->> 'product_id';
 p_derivation text := p ->> 'derivation_id';
 variant text := p ->> 'variant';
 snapshot jsonb;
 cut jsonb;
 grade jsonb;
 result jsonb;
 admitted boolean;
 expected_operation text;
 expected_factory text;
 expected_kind text;
 expected_role text;
 receipt_id text;
BEGIN
 PERFORM ops.ddo_require_feature_fit_principal();
 IF (variant = 'record-feature-grade') THEN
  expected_operation := 'record_policy.grade';
  expected_factory := 'corpus_structure.methods.declared_record_policy.RecordPolicyGrade.acquire_port';
  expected_kind := 'https://corpus-structure.dev/semantic/data-operation-record-policy/protected/DdoRecordGrade';
  expected_role := 'grade';
 ELSE
  IF (variant = 'operation-event-frame') THEN
   expected_operation := 'operation_event.frame';
   expected_factory := 'corpus_structure.methods.operation_events.OperationEventFrame.acquire_port';
   expected_kind := 'https://corpus-structure.dev/semantic/operation-events/protected/DdoOperationEventFrame';
   expected_role := 'frame';
  ELSE
   IF (true) THEN
    RAISE EXCEPTION USING MESSAGE = 'unknown selected feature fit frame variant', ERRCODE = '23514';
   END IF;
  END IF;
 END IF;
 SELECT ops.data_demand.* 
FROM ops.data_demand 
WHERE ops.data_demand.id = (p ->> 'demand_id') AND ops.data_demand.project_id = (p ->> 'project_id') INTO STRICT d;
 SELECT ops.data_demand_read.* 
FROM ops.data_demand_read 
WHERE ops.data_demand_read.id = (p ->> 'read_id') AND ops.data_demand_read.demand_id = d.id INTO STRICT boundary;
 p := p || jsonb_build_object('scope', boundary.scope);
 snapshot := ops.ddo_require_read_epochs(boundary, d.project_id);
 WITH RECURSIVE scoped_obligations AS 
(SELECT ops.data_obligation.id AS id, ops.data_obligation.demand_id AS demand_id, ops.data_obligation.operation_id AS operation_id, ops.data_obligation.subject AS subject, ops.data_obligation.original_source AS original_source, ops.data_obligation.analyzed_scope AS analyzed_scope, ops.data_obligation.parameters AS parameters, ops.data_obligation.created_at AS created_at, ops.data_obligation.created_xid AS created_xid 
FROM ops.data_obligation 
WHERE ops.data_obligation.demand_id = d.id AND (NOT (coalesce(p['scope'], CAST('{}' AS JSONB)) ? 'operation_id') OR ops.data_obligation.operation_id IS NOT DISTINCT FROM (coalesce(p['scope'], CAST('{}' AS JSONB)) ->> 'operation_id')) AND (NOT (coalesce(p['scope'], CAST('{}' AS JSONB)) ? 'subject') OR ops.data_obligation.subject IS NOT DISTINCT FROM (coalesce(p['scope'], CAST('{}' AS JSONB)) ->> 'subject')) AND (NOT (coalesce(p['scope'], CAST('{}' AS JSONB)) ? 'original_source') OR ops.data_obligation.original_source IS NOT DISTINCT FROM (coalesce(p['scope'], CAST('{}' AS JSONB)) ->> 'original_source')) AND (NOT (coalesce(p['scope'], CAST('{}' AS JSONB)) ? 'product_ids') OR (EXISTS (SELECT 1 
FROM ops.demand_use AS scope_use JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = scope_use.derivation_id JOIN jsonb_array_elements_text((coalesce(p['scope'], CAST('{}' AS JSONB)))['product_ids']) AS scope_product(value) ON ops.data_derivation_output.product_id = scope_product.value 
WHERE scope_use.obligation_id = ops.data_obligation.id AND ops.ddo_read_visible(scope_use.created_at, scope_use.created_xid, boundary) AND NOT (EXISTS (SELECT 1 
FROM ops.demand_use AS scope_later_use 
WHERE scope_later_use.obligation_id = scope_use.obligation_id AND ops.ddo_read_visible(scope_later_use.created_at, scope_later_use.created_xid, boundary) AND (scope_later_use.created_at > scope_use.created_at OR scope_later_use.created_at = scope_use.created_at AND scope_later_use.id > scope_use.id))))) OR (EXISTS (SELECT 1 
FROM ops.original_source_admission AS scope_original JOIN jsonb_array_elements_text((coalesce(p['scope'], CAST('{}' AS JSONB)))['product_ids']) AS scope_product(value) ON scope_original.product_id = scope_product.value 
WHERE scope_original.demand_id = d.id AND scope_original.project_id = d.project_id AND scope_original.subject = ops.data_obligation.subject AND scope_original.original_source IS NOT DISTINCT FROM ops.data_obligation.original_source AND scope_original.analyzed_scope = ops.data_obligation.analyzed_scope AND ops.ddo_read_visible(scope_original.created_at, scope_original.created_xid, boundary)))) AND ops.ddo_read_visible(ops.data_obligation.created_at, ops.data_obligation.created_xid, boundary)), 
selected_uses AS 
(SELECT latest.id AS id, latest.demand_id AS demand_id, latest.obligation_id AS obligation_id, latest.fate AS fate, latest.request_id AS request_id, latest.generation AS generation, latest.derivation_id AS derivation_id, latest.selection AS selection, latest.trust_snapshot AS trust_snapshot, latest.created_at AS created_at, latest.created_xid AS created_xid 
FROM scoped_obligations JOIN LATERAL (SELECT ops.demand_use.id AS id, ops.demand_use.demand_id AS demand_id, ops.demand_use.obligation_id AS obligation_id, ops.demand_use.fate AS fate, ops.demand_use.request_id AS request_id, ops.demand_use.generation AS generation, ops.demand_use.derivation_id AS derivation_id, ops.demand_use.selection AS selection, ops.demand_use.trust_snapshot AS trust_snapshot, ops.demand_use.created_at AS created_at, ops.demand_use.created_xid AS created_xid 
FROM ops.demand_use 
WHERE ops.demand_use.obligation_id = scoped_obligations.id AND ops.ddo_read_visible(ops.demand_use.created_at, ops.demand_use.created_xid, boundary) ORDER BY ops.demand_use.created_at DESC, ops.demand_use.id DESC 
 LIMIT 1) AS latest ON true), 
selected_output_validity AS MATERIALIZED 
(SELECT selected_output_validity_rows.kind AS kind, selected_output_validity_rows.id AS id, selected_output_validity_rows.valid AS valid 
FROM ops.ddo_valid_closure((SELECT array_agg(selected_uses.id) AS array_agg_1 
FROM selected_uses 
WHERE selected_uses.fate = 'fulfilled'), CAST('{}' AS TEXT[]), boundary, CAST('{}' AS TEXT[])) AS selected_output_validity_rows), 
selected_output_seed AS 
(SELECT CAST('use' AS TEXT) AS kind, CAST(selected_uses.id AS TEXT) AS id 
FROM selected_uses 
WHERE selected_uses.id = p_use AND selected_uses.fate = 'fulfilled' AND (EXISTS (SELECT 1 
FROM selected_output_validity 
WHERE selected_output_validity.kind = 'use' AND selected_uses.id = selected_output_validity.id AND selected_output_validity.valid))), 
support_closure(kind, id) AS 
(SELECT selected_output_seed.kind AS kind, selected_output_seed.id AS id 
FROM selected_output_seed 
WHERE selected_output_seed.id IS NOT NULL UNION SELECT support_edge.child_kind AS kind, support_edge.child_id AS id 
FROM support_closure JOIN LATERAL (SELECT CAST(0 AS INTEGER) AS alternative, CAST(CASE WHEN (ops.data_derivation_support.admission_use_id IS NOT NULL) THEN 'use' ELSE 'episode' END AS TEXT) AS child_kind, coalesce(ops.data_derivation_support.admission_use_id, ops.data_derivation_support.support_derivation_id) AS child_id 
FROM ops.data_derivation_support 
WHERE support_closure.kind = 'episode' AND ops.data_derivation_support.derivation_id = support_closure.id UNION ALL SELECT CAST(0 AS INTEGER) AS alternative, CAST('original' AS TEXT) AS child_kind, ops.data_derivation_original_support.admission_id AS child_id 
FROM ops.data_derivation_original_support 
WHERE support_closure.kind = 'episode' AND ops.data_derivation_original_support.derivation_id = support_closure.id UNION ALL SELECT CAST(0 AS INTEGER) AS alternative, CAST('episode' AS TEXT) AS child_kind, ops.demand_use.derivation_id AS child_id 
FROM ops.demand_use 
WHERE support_closure.kind = 'use' AND ops.demand_use.id = support_closure.id UNION ALL SELECT CAST(0 AS INTEGER) AS alternative, CAST((ops.ddo_support_reference_node(selected_support_reference.value) ->> 'kind') AS TEXT) AS child_kind, (ops.ddo_support_reference_node(selected_support_reference.value) ->> 'id') AS child_id 
FROM ops.demand_use JOIN jsonb_array_elements(coalesce(ops.demand_use.selection['support'], CAST('[]' AS JSONB))) AS selected_support_reference(value) ON true 
WHERE support_closure.kind = 'use' AND ops.demand_use.id = support_closure.id UNION ALL SELECT CAST(0 AS INTEGER) AS alternative, CAST('population' AS TEXT) AS child_kind, ops.data_population.id AS child_id 
FROM ops.demand_use JOIN jsonb_array_elements(coalesce(ops.demand_use.selection['populations'], CAST('[]' AS JSONB))) AS selected_population_reference(value) ON true JOIN ops.data_population ON ops.data_population.id = (selected_population_reference.value ->> 'population_id') AND ops.data_population.demand_id = ops.demand_use.demand_id 
WHERE support_closure.kind = 'use' AND ops.demand_use.id = support_closure.id UNION ALL SELECT CAST(0 AS INTEGER) AS alternative, CAST('use' AS TEXT) AS child_kind, ops.demand_use.id AS child_id 
FROM ops.data_population JOIN ops.demand_use ON ops.demand_use.id = (ops.data_population.evidence ->> 'admission_use_id') AND ops.demand_use.derivation_id = (ops.data_population.evidence ->> 'derivation_id') AND ops.demand_use.demand_id = ops.data_population.demand_id 
WHERE support_closure.kind = 'population' AND ops.data_population.id = support_closure.id UNION ALL SELECT CAST(0 AS INTEGER) AS alternative, CAST('population' AS TEXT) AS child_kind, ((ops.data_population.evidence['selection']) ->> 'parent_population_id') AS child_id 
FROM ops.data_population 
WHERE support_closure.kind = 'population' AND ops.data_population.id = support_closure.id) AS support_edge ON true 
WHERE support_edge.child_id IS NOT NULL), 
selected_whole_outputs AS 
(SELECT DISTINCT ops.data_derivation.id AS derivation_id, ops.data_derivation_output.product_id AS product_id 
FROM ops.data_derivation JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id JOIN kb.data_product ON kb.data_product.id = ops.data_derivation_output.product_id 
WHERE CASE WHEN ((EXISTS (SELECT 1 
FROM support_closure 
WHERE support_closure.kind IN ('episode', 'authority') AND ops.data_derivation.id = support_closure.id)) AND true AND ops.data_derivation_output.member_id IS NULL AND kb.data_product.project_id = d.project_id AND (EXISTS (SELECT 1 
FROM selected_output_validity 
WHERE selected_output_validity.kind = 'episode' AND ops.data_derivation.id = selected_output_validity.id AND selected_output_validity.valid))) THEN ops.ddo_feature_fit_body_access(kb.data_product.kind_contract, kb.data_product.canonical_body) ELSE false END)
 SELECT EXISTS (SELECT 1 
FROM selected_whole_outputs 
WHERE selected_whole_outputs.derivation_id = p_derivation AND selected_whole_outputs.product_id = p_product) AS anon_1 INTO admitted;
 IF (NOT coalesce(admitted, false)) THEN
  RAISE EXCEPTION USING MESSAGE = 'feature fit grade is outside exact current selected support', ERRCODE = '23514';
 END IF;
 SELECT jsonb_build_object('demand_id', d.id, 'project_id', d.project_id, 'release_id', d.release_id, 'runtime_id', d.runtime_id, 'selection', CASE WHEN (boundary.public_disclosure AND boundary.scope != CAST('{}' AS JSONB)) THEN jsonb_build_object('version', 'data-demand-public-selection-v1', 'model', d.selection['model'], 'intent_digest', ops.ddo_digest(d.selection), 'roots', d.selection['roots'], 'targets', d.selection['targets'], 'root_operations', d.selection['root_operations'], 'discovery', d.selection['discovery']) ELSE d.selection END, 'trust_snapshot', boundary.trust_snapshot, 'read_id', boundary.id, 'read_snapshot', boundary.read_snapshot, 'frontier_at', boundary.frontier_at, 'scope', boundary.scope) AS jsonb_build_object_1 INTO cut;
 IF (CAST((p ->> 'cut_canonical_json') AS JSONB) IS DISTINCT FROM cut OR (p ->> 'expected_cut') IS DISTINCT FROM ('cut-selection:' || encode(sha256(convert_to((p ->> 'cut_canonical_json'), 'UTF8')), 'hex'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'feature fit cut bytes or native pins differ', ERRCODE = '23514';
 END IF;
 SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = p_derivation AND ops.data_derivation.outcome = 'success' INTO STRICT episode;
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition JOIN ops.data_request ON sem.data_operation_definition.release_id = episode.release_id AND ops.data_request.operation_id = sem.data_operation_definition.operation_id 
WHERE ops.data_request.id = episode.request_id AND ops.data_request.project_id = d.project_id INTO STRICT definition;
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = episode.intent_id AND ops.data_completion_intent.request_id = episode.request_id AND ops.data_completion_intent.generation = episode.generation INTO STRICT intent;
 IF ((intent.producer_task_id, intent.producer_attempt, intent.runtime_id) IS DISTINCT FROM (episode.producer_task_id, episode.producer_attempt, episode.runtime_id)) THEN
  RAISE EXCEPTION USING MESSAGE = 'feature fit frame differs from original producer fences', ERRCODE = '23514';
 END IF;
 IF (definition.operation_id IS DISTINCT FROM expected_operation OR definition.profile IS DISTINCT FROM 'derivation' OR definition.support_contract['effects'] IS DISTINCT FROM CAST('[]' AS JSONB) OR ((definition.support_contract['capabilities']['prepared_factory']) ->> 'entrypoint') IS DISTINCT FROM expected_factory OR (((definition.support_contract['capabilities']['prepared_factory']) ->> 'source_digest') ~ '^[0-9a-f]{64}$') IS NOT true OR (definition.implementation_revision LIKE 'implementation-slice:%') IS NOT true OR (intent.payload ->> 'implementation_revision') IS DISTINCT FROM definition.implementation_revision OR jsonb_array_length(coalesce(intent.payload['execution_evidence']['cpu_receipts'], CAST('[]' AS JSONB))) != 1 OR episode.recipe IS DISTINCT FROM definition.recipe) THEN
  RAISE EXCEPTION USING MESSAGE = 'feature fit requires the actual admitted protected grade implementation', ERRCODE = '23514';
 END IF;
 SELECT ops.data_publication_receipt.id 
FROM ops.data_publication_receipt JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_publication_receipt.derivation_id 
WHERE ops.data_publication_receipt.derivation_id = episode.id AND ops.data_publication_receipt.intent_id = episode.intent_id AND ops.data_derivation_output.product_id = p_product AND ops.data_derivation_output.member_id IS NULL AND ops.data_derivation_output.role = expected_role AND ops.data_derivation_output.position = 0 AND ops.data_derivation_output.multiplicity = 1 INTO STRICT receipt_id;
 IF (NOT (EXISTS (SELECT kb.data_product.id 
FROM kb.data_product JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = kb.data_product.kind_contract 
WHERE kb.data_product.id = p_product AND kb.data_product.project_id = d.project_id AND sem.data_kind_contract.kind = expected_kind AND sem.data_kind_contract.universe = 'evaluator'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'feature fit variant differs from actual protected frame kind', ERRCODE = '23514';
 END IF;
 SELECT data.ddo_json(kb.data_product.canonical_body) AS ddo_json_1 
FROM kb.data_product 
WHERE kb.data_product.id = p_product AND kb.data_product.project_id = d.project_id INTO STRICT grade;
 IF ((grade ->> 'frame_digest') IS DISTINCT FROM (p ->> 'frame_digest') OR (grade ->> 'frame_digest') IS DISTINCT FROM encode(sha256(convert_to((grade ->> 'frame_canonical_json'), 'UTF8')), 'hex') OR CAST((grade ->> 'frame_canonical_json') AS JSONB) IS DISTINCT FROM grade['frame'] OR (CASE WHEN (variant = 'record-feature-grade') THEN ((grade['frame']) ->> 'project_id') ELSE ((grade['frame']['question']['prediction_selection']) ->> 'project_id') END) IS DISTINCT FROM d.project_id) THEN
  RAISE EXCEPTION USING MESSAGE = 'feature fit grade canonical frame differs', ERRCODE = '23514';
 END IF;
 result := jsonb_build_object('variant', variant, 'cut', cut, 'product_id', p_product, 'derivation_id', p_derivation, 'receipt_id', receipt_id, 'frame', grade);
 IF (coalesce(CAST((p ->> 'max_bytes') AS BIGINT), 8388608) < octet_length(data.canonical_json(result))) THEN
  RAISE EXCEPTION USING MESSAGE = 'feature fit frame exceeds explicit byte bound', ERRCODE = '23514';
 END IF;
 RETURN jsonb_build_object('payload', result);
END

