DECLARE
 source jsonb;
 cut jsonb;
 body jsonb;
 observation jsonb;
 image jsonb;
 mapping jsonb;
 raw_pin jsonb;
 raw_input jsonb;
 mapped jsonb;
 result jsonb;
 artifact bytea;
 image_bytes bytea;
 response_bytes bytea;
 total integer;
 offset_ integer;
 length_ integer;
 kind text;
 digest text;
 media text;
 product kb.data_product%ROWTYPE;
 boundary ops.data_demand_read%ROWTYPE;
 raw_product kb.data_product%ROWTYPE;
 episode ops.data_derivation%ROWTYPE;
 raw_episode ops.data_derivation%ROWTYPE;
 intent ops.data_completion_intent%ROWTYPE;
BEGIN
 source := (ops.ddo_impl_read_selected_pdf_source(p_payload['source']))['payload'];
 cut := ops.ddo_require_selected_output((p_payload['source']) ->> 'demand_id', (p_payload['source']) ->> 'read_id', (p_payload['evidence']) ->> 'use_id', (p_payload['evidence']) ->> 'product_id', (p_payload['evidence']) ->> 'derivation_id');
 IF (cut IS DISTINCT FROM source['cut']) THEN
  RAISE EXCEPTION USING MESSAGE = 'visual evidence differs from selected source cut', ERRCODE = '23514';
 END IF;
 SELECT ops.data_demand_read.* 
FROM ops.data_demand_read 
WHERE ops.data_demand_read.id = ((p_payload['source']) ->> 'read_id') AND ops.data_demand_read.demand_id = ((p_payload['source']) ->> 'demand_id') INTO STRICT boundary;
 IF (NOT boundary.public_disclosure AND boundary.scope != CAST('{}' AS JSONB)) THEN
  PERFORM ops.ddo_authorize('evaluator');
 END IF;
 SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = ((p_payload['evidence']) ->> 'product_id') AND kb.data_product.project_id = ((p_payload['source']) ->> 'project_id') INTO STRICT product;
 SELECT sem.data_kind_contract.kind 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = product.kind_contract INTO STRICT kind;
 SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = ((p_payload['evidence']) ->> 'derivation_id') INTO STRICT episode;
 body := data.ddo_json(product.canonical_body);
 raw_pin := p_payload['evidence'];
 raw_episode := episode;
 IF (kind = 'https://corpus-structure.dev/semantic/data-operation-visual/DdoVisualMapping') THEN
  mapping := body;
  observation := body['observation'];
  SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = episode.intent_id INTO STRICT intent;
  SELECT selected.value 
FROM jsonb_array_elements(intent.payload['inputs']) AS selected(value) 
WHERE (selected.value ->> 'role') = 'observation' AND (selected.value ->> 'member_id') IS NULL INTO STRICT raw_input;
  IF (NOT (EXISTS (SELECT 1 
FROM ops.data_derivation_input 
WHERE ops.data_derivation_input.derivation_id = episode.id AND ops.data_derivation_input.role = 'observation' AND ops.data_derivation_input.product_id = (raw_input ->> 'product_id') AND ops.data_derivation_input.member_id IS NULL)) OR NOT (EXISTS (SELECT 1 
FROM ops.data_derivation_support 
WHERE ops.data_derivation_support.derivation_id = episode.id AND ops.data_derivation_support.support_derivation_id = ops.ddo_single_input_support_episode(raw_input)))) THEN
   RAISE EXCEPTION USING MESSAGE = 'visual mapping lacks exact admitted raw input', ERRCODE = '23514';
  END IF;
  raw_pin := jsonb_build_object('use_id', (p_payload['evidence']) ->> 'use_id', 'product_id', raw_input ->> 'product_id', 'derivation_id', ops.ddo_single_input_support_episode(raw_input));
  PERFORM ops.ddo_require_selected_output((p_payload['source']) ->> 'demand_id', (p_payload['source']) ->> 'read_id', raw_pin ->> 'use_id', raw_pin ->> 'product_id', raw_pin ->> 'derivation_id');
  SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = (raw_pin ->> 'product_id') AND kb.data_product.project_id = product.project_id AND kb.data_product.original_source = product.original_source INTO STRICT raw_product;
  IF (NOT (EXISTS (SELECT 1 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = raw_product.kind_contract AND sem.data_kind_contract.kind = 'https://corpus-structure.dev/semantic/data-operation-visual/DdoChandraObservation')) OR data.ddo_json(raw_product.canonical_body) IS DISTINCT FROM observation) THEN
   RAISE EXCEPTION USING MESSAGE = 'visual mapping differs from its admitted raw observation', ERRCODE = '23514';
  END IF;
  SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = (raw_pin ->> 'derivation_id') INTO STRICT raw_episode;
 ELSE
  IF (kind = 'https://corpus-structure.dev/semantic/data-operation-visual/DdoChandraObservation') THEN
   observation := body;
  ELSE
   RAISE EXCEPTION USING MESSAGE = 'selected product is not visual evidence', ERRCODE = '23514';
  END IF;
 END IF;
 image := observation['image'];
 IF (product.original_source IS DISTINCT FROM (image ->> 'document') OR product.original_source IS DISTINCT FROM (source ->> 'original_source') OR (image ->> 'source_digest') IS DISTINCT FROM ((source['receipt']['publication']) ->> 'source_digest') OR (image ->> 'logical_digest') IS DISTINCT FROM ((source['receipt']['publication']) ->> 'logical_digest')) THEN
  RAISE EXCEPTION USING MESSAGE = 'visual image differs from selected original PDF source', ERRCODE = '23514';
 END IF;
 image_bytes := decode(image ->> 'content_hex', 'hex');
