 IF (encode(sha256(image_bytes), 'hex') IS DISTINCT FROM (image ->> 'content_digest') OR substr(image_bytes, 1, 8) IS DISTINCT FROM decode('89504e470d0a1a0a', 'hex') OR octet_length(image_bytes) < 24 OR 0 + CAST(get_byte(image_bytes, 16) AS BIGINT) * 16777216 + get_byte(image_bytes, 17) * 65536 + get_byte(image_bytes, 18) * 256 + get_byte(image_bytes, 19) != CAST((image ->> 'width') AS INTEGER) OR 0 + CAST(get_byte(image_bytes, 20) AS BIGINT) * 16777216 + get_byte(image_bytes, 21) * 65536 + get_byte(image_bytes, 22) * 256 + get_byte(image_bytes, 23) != CAST((image ->> 'height') AS INTEGER) OR encode(sha256(response_bytes), 'hex') IS DISTINCT FROM (observation ->> 'response_digest')) THEN
