BEGIN
 source := (ops.ddo_impl_read_selected_pdf_source(p_payload['source']))['payload'];
 cut := ops.ddo_require_selected_output((p_payload['source']) ->> 'demand_id', (p_payload['source']) ->> 'read_id', (p_payload['evidence']) ->> 'use_id', (p_payload['evidence']) ->> 'product_id', (p_payload['evidence']) ->> 'derivation_id');
 IF (cut IS DISTINCT FROM source['cut']) THEN
  RAISE EXCEPTION USING MESSAGE = 'visual evidence differs from selected source cut', ERRCODE = '23514';
 END IF;
 SELECT ops.data_demand_read.* 
FROM ops.data_demand_read 
WHERE ops.data_demand_read.id = ((p_payload['source']) ->> 'read_id') AND ops.data_demand_read.demand_id = ((p_payload['source']) ->> 'demand_id') INTO STRICT boundary;
 IF (NOT boundary.public_disclosure AND boundary.scope != CAST('{}' AS JSONB)) THEN
  PERFORM ops.ddo_authorize('evaluator');
 END IF;
 SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = ((p_payload['evidence']) ->> 'product_id') AND kb.data_product.project_id = ((p_payload['source']) ->> 'project_id') INTO STRICT product;
 SELECT sem.data_kind_contract.kind 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = product.kind_contract INTO STRICT kind;
 SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = ((p_payload['evidence']) ->> 'derivation_id') INTO STRICT episode;
