  IF (NOT (EXISTS (SELECT 1 
FROM ops.data_derivation_input 
WHERE ops.data_derivation_input.derivation_id = episode.id AND ops.data_derivation_input.role = 'observation' AND ops.data_derivation_input.product_id = (raw_input ->> 'product_id') AND ops.data_derivation_input.member_id IS NULL)) OR NOT (EXISTS (SELECT 1 
FROM ops.data_derivation_support 
