   END IF;
   length_ := least(65536, total - offset_);
   result := jsonb_build_object('kind', 'artifact', 'digest', digest, 'media_type', media, 'content_hex', encode(substr(artifact, offset_ + 1, length_), 'hex'), 'offset', offset_, 'total_bytes', total, 'next_offset', CASE WHEN (offset_ + length_ < total) THEN offset_ + length_ END);
  ELSE
   IF ((p_payload ->> 'mode') = 'rows') THEN
    result := ops.ddo_visual_candidate_rows(mapped, p_payload);
   ELSE
    RAISE EXCEPTION USING MESSAGE = 'unknown visual read mode', ERRCODE = '23514';
   END IF;
  END IF;
 END IF;
 IF (octet_length(CAST(result AS TEXT)) > CAST((p_payload ->> 'max_bytes') AS INTEGER)) THEN
  RAISE EXCEPTION USING MESSAGE = 'visual result exceeds byte bound', ERRCODE = '54000';
 END IF;
 RETURN jsonb_build_object('payload', result);
END$$

