CT FROM (to_jsonb(r))['binding']['execution_profile'] AND ops.data_execution_origin.request_snapshot['binding']['populations'] IS NOT DISTINCT FROM (to_jsonb(r))['binding']['populations'] AND ops.data_execution_origin.definition_snapshot['implementation_revision'] IS NOT DISTINCT FROM (to_jsonb(definition_))['implementation_revision'] AND ops.data_execution_origin.definition_snapshot['profile'] IS NOT DISTINCT FROM (to_jsonb(definition_))['profile'] AND ops.data_execution_origin.definition_snapshot['output_roles'] IS NOT DISTINCT FROM (to_jsonb(definition_))['output_roles'] AND ops.data_execution_origin.definition_snapshot['support_contract'] IS NOT DISTINCT FROM (to_jsonb(definition_))['support_contract'] AND (EXISTS (SELECT 1 
FROM ops.data_attempt_failure 
WHERE ops.data_attempt_failure.request_id = ops.data_execution_origin.request_id AND ops.data_attempt_failure.generation = ops.data_execution_origin.generation AND ops.data_attempt_failure.task_id = ops.data_execution_origin.task_id AND ops.data_attempt_failure.attempt = ops.data_execution_origin.attempt AND ops.data_attempt_failure.holder = ops.data_execution_origin.holder)) ORDER BY ops.data_execution_origin.created_at DESC, ops.data_execution_origin.id 
 LIMIT 64) AS prior_origin)));
END

