DECLARE
 p jsonb := p_payload;
 r ops.data_request%ROWTYPE;
 t ops.task%ROWTYPE;
 old ops.data_attempt_failure%ROWTYPE;
 key text;
 retained text;
 replayed boolean := false;
 diagnostic jsonb;
 evidence jsonb;
 question_request jsonb;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['request_id', 'generation', 'task_id', 'attempt', 'holder', 'physical_retirement', 'failure'], ARRAY[]::TEXT[]);
 PERFORM ops.ddo_fields(p['failure'], ARRAY['code', 'message'], ARRAY['d1_limitation']);
 IF ((p ->> 'physical_retirement') IS DISTINCT FROM 'confirmed' OR nullif((p ->> 'holder'), '') IS NULL OR nullif(((p['failure']) ->> 'code'), '') IS NULL OR nullif(((p['failure']) ->> 'message'), '') IS NULL OR CAST((p ->> 'generation') AS INTEGER) < 1 OR CAST((p ->> 'attempt') AS INTEGER) < 1 OR CAST((p ->> 'task_id') AS BIGINT) < 1) THEN
  RAISE EXCEPTION USING MESSAGE = 'attempt release requires exact known retirement/failure', ERRCODE = 'P0001';
 END IF;
 SELECT ops.data_request.id, ops.data_request.request_key, ops.data_request.project_id, ops.data_request.release_id, ops.data_request.runtime_id, ops.data_request.operation_id, ops.data_request.recipe, ops.data_request.subject, ops.data_request.original_source, ops.data_request.analyzed_scope, ops.data_request.binding, ops.data_request.replicate, ops.data_request.generation, ops.data_request.live_task_id 
FROM ops.data_request 
WHERE ops.data_request.id = (p ->> 'request_id') INTO STRICT r;
 PERFORM ops.ddo_authorize_request(r);
 IF (p['failure'] ? 'd1_limitation') THEN
  diagnostic := p['failure']['d1_limitation'];
  evidence := diagnostic['execution_evidence'];
  question_request := CAST(diagnostic ->> 'request_json' AS JSONB);
  IF ((r.operation_id NOT IN ('text.d1_source/source-native', 'text.d1_candidates/source-native')) OR ((p['failure']) ->> 'code') IS DISTINCT FROM 'd1-known-limitation' OR octet_length((diagnostic ->> 'request_json')) > 67108864 OR pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to((diagnostic ->> 'request_json'), 'UTF8')), 'hex') IS DISTINCT FROM (diagnostic ->> 'request_digest') OR question_request['interpretation']['assessed_scope']['pin'] IS DISTINCT FROM diagnostic['source_pin'] OR jsonb_typeof(question_request['questions']) IS DISTINCT FROM 'object' OR ((diagnostic['native_reply']) ->> 'reason') = 'question_count' AND (SELECT count(*) AS count_1 
FROM pg_catalog.jsonb_object_keys(question_request['questions']) AS question_key) <= 16 OR ((diagnostic['native_reply']) ->> 'reason') = 'packed_row_tokens' AND (SELECT count(*) AS count_1 
FROM pg_catalog.jsonb_object_keys(question_request['questions']) AS question_key) NOT BETWEEN 1 AND 16 OR (((diagnostic['source_pin']) ->> 'project_id'), ((diagnostic['source_pin']) ->> 'subject'), ((diagnostic['source_pin']) ->> 'original_source')) IS DISTINCT FROM (r.project_id, r.subject, r.original_source) OR ((diagnostic['source_pin']) ->> 'analyzed_scope_meaning') IS DISTINCT FROM data.canonical_json(data.ddo_json_meaning(r.analyzed_scope)) OR NOT (EXISTS (SELECT 1 
FROM pg_catalog.jsonb_array_elements(r.binding['inputs']) AS source_input(value) JOIN kb.data_product ON kb.data_product.id = (source_input.value ->> 'product_id') LEFT OUTER JOIN kb.data_product_member ON kb.data_product_member.product_id = kb.data_product.id AND kb.data_product_member.member_id = (source_input.value ->> 'member_id') 
WHERE (source_input.value ->> 'role') = 'source' AND kb.data_product.id = ((diagnostic['source_pin']) ->> 'source_product') AND (source_input.value ->> 'member_id') IS NOT DISTINCT FROM ((diagnostic['source_pin']) ->> 'source_member') AND coalesce(kb.data_product_member.kind_contract, kb.data_product.kind_contract) = ((diagnostic['source_pin']) ->> 'kind_contract') AND coalesce(kb.data_product_member.subject_definition, kb.data_product.subject_definition) = ((diagnostic['source_pin']) ->> 'subject_definition'))) OR (evidence - ARRAY['cpu_receipts', 'cpu_replies', 'external_receipts', 'host_receipts', 'pdf_observation_receipts', 'pdf_receipts', 'product_validations', 'provider_receipts', 'runtime_id', 'version']) IS DISTINCT FROM (p - ARRAY['physical_retirement', 'failure']) OR jsonb_array_length(evidence['provider_receipts']) != 1 OR (EXISTS (SELECT 1 
FROM pg_catalog.jsonb_array_elements(evidence['provider_receipts']) AS provider_receipt(value) 
WHERE jsonb_array_length(provider_receipt.value['logical_members']) = 0 OR jsonb_array_length(provider_receipt.value['physical']) = 0 OR provider_receipt.value['cohort_members'] IS DISTINCT FROM diagnostic['native_reply']['batch_receipt']['members'] OR NOT ((provider_receipt.value['native_member_digests'] ? (diagnostic ->> 'request_digest'))) OR (diagnostic['native_reply']['batch_receipt']['members'] ->> CAST(((diagnostic['native_reply']['batch_receipt']) ->> 'member_ordinal') AS INTEGER)) IS DISTINCT FROM (diagnostic ->> 'request_digest') OR (EXISTS (SELECT 1 
FROM pg_catalog.jsonb_array_elements(provider_receipt.value['logical_members']) AS logical_member(value) 
WHERE (logical_member.value['request_id'], logical_member.value['generation'], logical_member.value['task_id'], logical_member.value['attempt']) IS DISTINCT FROM (p['request_id'], p['generation'], p['task_id'], p['attempt']))) OR (EXISTS (SELECT 1 
FROM pg_catalog.jsonb_array_elements(provider_receipt.value['physical']) AS physical_receipt(value) 
WHERE (physical_receipt.value ->> 'provider') != 'd1' OR (physical_receipt.value ->> 'profile') IS DISTINCT FROM (diagnostic ->> 'profile_digest') OR physical_receipt.value['runtime'] IS DISTINCT FROM diagnostic['native_reply']['batch_receipt']['header']['runtime']))))) THEN
   RAISE EXCEPTION USING MESSAGE = 'D1 limitation differs from its exact source/attempt/provider custody', ERRCODE = '23514';
  END IF;
  PERFORM sem.require_runtime_binding(r.release_id, evidence ->> 'runtime_id');
  PERFORM ops.ddo_require_provider_profile(r.release_id, r.operation_id, evidence ->> 'runtime_id');
 END IF;
 PERFORM ops.ddo_lock_support(r.project_id, r.original_source, r.binding['support']);
 SELECT ops.data_request.id, ops.data_request.request_key, ops.data_request.project_id, ops.data_request.release_id, ops.data_request.runtime_id, ops.data_request.operation_id, ops.data_request.recipe, ops.data_request.subject, ops.data_request.original_source, ops.data_request.analyzed_scope, ops.data_request.binding, ops.data_request.replicate, ops.data_request.generation, ops.data_request.live_task_id 
FROM ops.data_request 
WHERE ops.data_request.id = r.id FOR UPDATE INTO STRICT r;
 SELECT ops.data_attempt_failure.id, ops.data_attempt_failure.request_id, ops.data_attempt_failure.generation, ops.data_attempt_failure.task_id, ops.data_attempt_failure.attempt, ops.data_attempt_failure.holder, ops.data_attempt_failure.failure, ops.data_attempt_failure.created_at, ops.data_attempt_failure.created_xid 
FROM ops.data_attempt_failure 
WHERE ops.data_attempt_failure.request_id = r.id AND (ops.data_attempt_failure.generation, ops.data_attempt_failure.task_id, ops.data_attempt_failure.attempt, ops.data_attempt_failure.holder) = (CAST((p ->> 'generation') AS INTEGER), CAST((p ->> 'task_id') AS BIGINT), CAST((p ->> 'attempt') AS INTEGER), (p ->> 'holder')) INTO old;
 IF (old.id IS NOT NULL) THEN
  IF (old.failure IS DISTINCT FROM p['failure']) THEN
   RAISE EXCEPTION USING MESSAGE = 'immutable attempt failure cannot change', ERRCODE = 'P0001';
  END IF;
  key := old.id;
  replayed := true;
 ELSE
  IF (NOT ops.ddo_request_useful(r)) THEN
   RETURN ops.ddo_lost_attempt(p, 'cancelled');
  END IF;
  SELECT ops.task.id, ops.task.release_id, ops.task.data_request_id, ops.task.data_generation, ops.task.invocation_key, ops.task.trigger, ops.task.status, ops.task.attempt, ops.task.claimed_by, ops.task.lease_until, ops.task.result_digest, ops.task.error, ops.task.cost, ops.task.reason, ops.task.priority, ops.task.created_at, ops.task.started_at, ops.task.finished_at 
FROM ops.task 
WHERE ops.task.id = r.live_task_id FOR UPDATE INTO t;
  IF (t.id IS NULL OR r.generation IS DISTINCT FROM CAST((p ->> 'generation') AS INTEGER) OR (t.data_request_id, t.data_generation, t.id, t.attempt, t.claimed_by) IS DISTINCT FROM (r.id, r.generation, CAST((p ->> 'task_id') AS BIGINT), CAST((p ->> 'attempt') AS INTEGER), (p ->> 'holder')) OR t.status IS DISTINCT FROM 'running') THEN
   RETURN ops.ddo_lost_attempt(p, 'fence');
  END IF;
  key := 'attempt-failure:' || ops.ddo_digest(p);
  INSERT INTO ops.data_attempt_failure (id, request_id, generation, task_id, attempt, holder, failure, created_at, created_xid) VALUES (key, r.id, r.generation, t.id, t.attempt, t.claimed_by, (p['failure']), clock_timestamp(), CAST(pg_current_xact_id() AS TEXT));
  UPDATE ops.task SET status='pending', lease_until=NULL, error=pg_catalog.jsonb_build_object('data_attempt_failure', key, 'failure', CASE WHEN (p['failure'] ? 'd1_limitation') THEN (p['failure'] - ARRAY['d1_limitation']) || pg_catalog.jsonb_build_object('d1_limitation_disclosure', 'undisclosed') ELSE p['failure'] END), finished_at=NULL WHERE ops.task.id = t.id;
