 IF ((r.generation, t.id, t.attempt, t.claimed_by) IS DISTINCT FROM (CAST((p ->> 'generation') AS BIGINT), CAST((p ->> 'task_id') AS BIGINT), CAST((p ->> 'attempt') AS BIGINT), (p ->> 'holder')) OR (t.status NOT IN ('running', 'pending'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'external release lost its exact packet/attempt fence', ERRCODE = 'P0001';
