 t ops.task%ROWTYPE;
 snapshot jsonb;
 key text;
 payload_digest_ text;
 old ops.data_completion_intent%ROWTYPE;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['request_id', 'generation', 'task_id', 'attempt', 'holder', 'runtime_id', 'completion']);
 PERFORM ops.ddo_fields(p['completion'], ARRAY['outcome', 'outputs', 'support', 'inputs', 'implementation_revision'], ARRAY['execution_evidence']);
 IF ((p['completion'] ? 'execution_evidence') AND (((((((((p['completion']['execution_evidence'] - 'version') - 'host_receipts') - 'cpu_receipts') - 'cpu_replies') - 'product_validations') - 'pdf_receipts') - 'pdf_observation_receipts') - 'provider_receipts') - 'external_receipts') IS DISTINCT FROM (p - 'completion')) THEN
  RAISE EXCEPTION USING MESSAGE = 'execution evidence differs from native producer fence/runtime', ERRCODE = 'P0001';
 END IF;
 IF (EXISTS (SELECT 1 
FROM jsonb_array_elements(coalesce(p['completion']['execution_evidence']['provider_receipts'], CAST('[]' AS JSONB))) AS provider_receipt(value) 
WHERE jsonb_array_length(provider_receipt.value['logical_members']) = 0 OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(provider_receipt.value['logical_members']) AS logical_member(value) 
WHERE logical_member.value['request_id'] IS DISTINCT FROM p['request_id'] OR logical_member.value['generation'] IS DISTINCT FROM p['generation'] OR logical_member.value['task_id'] IS DISTINCT FROM p['task_id'] OR logical_member.value['attempt'] IS DISTINCT FROM p['attempt'])))) THEN
  RAISE EXCEPTION USING MESSAGE = 'provider logical receipt differs from native attempt', ERRCODE = 'P0001';
 END IF;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = (p ->> 'request_id') INTO STRICT r;
 snapshot := ops.ddo_lock_completion_support(r, p['completion']);
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = r.id FOR UPDATE INTO STRICT r;
 t := ops.ddo_claim(r, p);
 PERFORM sem.require_runtime_binding(r.release_id, p ->> 'runtime_id');
 PERFORM ops.ddo_require_provider_profile(r.release_id, r.operation_id, p ->> 'runtime_id');
 IF (NOT (EXISTS (SELECT 1 
FROM sem.runtime_binding 
WHERE sem.runtime_binding.release_id = r.release_id AND sem.runtime_binding.runtime_id = (p ->> 'runtime_id') AND sem.runtime_binding.execution_profile = (r.binding ->> 'execution_profile')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'actual producer runtime execution profile differs from admitted request', ERRCODE = 'P0001';
 END IF;
 IF (r.generation != CAST((p ->> 'generation') AS BIGINT) OR p['completion']['inputs'] IS DISTINCT FROM r.binding['inputs'] OR p['completion']['support'] IS DISTINCT FROM r.binding['support'] OR NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id AND sem.data_operation_definition.implementation_revision = ((p['completion']) ->> 'implementation_revision')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'completion differs from admitted request/implementation', ERRCODE = 'P0001';
 END IF;
 PERFORM ops.ddo_assert_support(r, p['completion']['support']);
 PERFORM ops.ddo_require_completion_correspondence(r, p['completion'], t.id, t.attempt, t.claimed_by);
 PERFORM ops.ddo_require_completion_live(r, p['completion']);
 key := 'intent:' || ops.ddo_digest(jsonb_build_array(r.id, r.generation, t.id, t.attempt, t.claimed_by, (p ->> 'runtime_id'), p['completion']));
 IF (EXISTS (SELECT 1 
FROM ops.data_draft_consumption 
WHERE ops.data_draft_consumption.request_id = r.id AND ops.data_draft_consumption.generation = r.generation AND ops.data_draft_consumption.intent_id != key)) THEN
  RAISE EXCEPTION USING MESSAGE = 'immutable consumed draft must be adopted; a generation cannot replace its answer', ERRCODE = 'P0001';
 END IF;
 payload_digest_ := ops.ddo_digest(p['completion']);
 INSERT INTO ops.data_completion_intent (id, request_id, generation, producer_task_id, producer_attempt, producer_holder, runtime_id, payload, payload_digest, created_at, validation_seal) VALUES (key, r.id, r.generation, t.id, t.attempt, t.claimed_by, (p ->> 'runtime_id'), (p['completion']), payload_digest_, clock_timestamp(), jsonb_build_object('validators', ops.ddo_current_validation_identities(r.release_id, r.operation_id), 'request', r.id, 'generation', r.generation, 'release', r.release_id, 'recipe', r.recipe, 'runtime', p ->> 'runtime_id', 'payload', payload_digest_, 'trust', snapshot)) ON CONFLICT DO NOTHING;
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.request_id = r.id AND ops.data_completion_intent.generation = r.generation INTO STRICT old;
 IF (old.id != key) THEN
  RAISE EXCEPTION USING MESSAGE = 'immutable retained intent must be adopted; a generation cannot replace its answer', ERRCODE = 'P0001';
 END IF;
 RETURN jsonb_build_object('payload', jsonb_build_object('intent_id', key, 'payload_digest', old.payload_digest));
END

