DECLARE
 p jsonb := p_payload;
 r ops.data_request%ROWTYPE;
 t ops.task%ROWTYPE;
 definition sem.data_operation_definition%ROWTYPE;
 old ops.data_external_packet%ROWTYPE;
 packet_value jsonb;
 inputs jsonb;
 contracts jsonb;
 key text;
 count_ bigint;
 size_ bigint;
 forbidden boolean;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['request_id', 'generation', 'task_id', 'attempt', 'holder', 'runtime_id', 'max_bytes'], ARRAY[]::TEXT[]);
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = (p ->> 'request_id') INTO STRICT r;
 PERFORM ops.ddo_authorize_request(r);
 key := 'external-packet:' || ops.ddo_digest(jsonb_build_array(r.id, CAST((p ->> 'generation') AS BIGINT)));
 SELECT ops.data_external_packet.* 
FROM ops.data_external_packet 
WHERE ops.data_external_packet.id = key AND ops.data_external_packet.request_id = r.id AND ops.data_external_packet.generation = CAST((p ->> 'generation') AS BIGINT) INTO old;
 IF (old.id IS NOT NULL) THEN
  RETURN jsonb_build_object('payload', jsonb_build_object('packet_id', old.id, 'packet_digest', old.payload_digest, 'state', 'awaiting-external'));
 END IF;
 PERFORM ops.ddo_lock_support(r.project_id, r.original_source, r.binding['support']);
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = r.id FOR UPDATE INTO STRICT r;
 t := ops.ddo_claim(r, p);
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id INTO STRICT definition;
 IF (definition.support_contract['external'] IS NULL OR (p ->> 'runtime_id') != r.runtime_id) THEN
  RAISE EXCEPTION USING MESSAGE = 'request has no matching admitted external protocol/runtime', ERRCODE = 'P0001';
 END IF;
 PERFORM ops.ddo_assert_external_active(r);
 PERFORM ops.ddo_assert_support(r, r.binding['support']);
 IF ((EXISTS (WITH RECURSIVE exposed(kind_contract) AS 
(SELECT (exposed_role.value ->> 'kind_contract') AS kind_contract 
FROM jsonb_array_elements(definition.input_roles || definition.output_roles) AS exposed_role(value) UNION SELECT child.value AS value 
FROM exposed JOIN sem.data_kind_contract AS parent ON parent.kind_contract = exposed.kind_contract JOIN LATERAL jsonb_array_elements_text(parent.member_contracts) AS child(value) ON true)
 SELECT exposed.kind_contract 
FROM exposed JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = exposed.kind_contract 
WHERE sem.data_kind_contract.universe = 'evaluator')) OR (EXISTS (WITH RECURSIVE exposed(kind_contract) AS 
(SELECT (exposed_role.value ->> 'kind_contract') AS kind_contract 
FROM jsonb_array_elements(definition.input_roles || definition.output_roles) AS exposed_role(value) UNION SELECT child.value AS value 
FROM exposed JOIN sem.data_kind_contract AS parent ON parent.kind_contract = exposed.kind_contract JOIN LATERAL jsonb_array_elements_text(parent.member_contracts) AS child(value) ON true)
 SELECT kb.data_product_member.member_id 
FROM jsonb_array_elements(r.binding['inputs']) WITH ORDINALITY AS inputs(item, ordinal) JOIN kb.data_product_member ON kb.data_product_member.product_id = (inputs.item ->> 'product_id') JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = kb.data_product_member.kind_contract 
WHERE (inputs.item ->> 'member_id') IS NULL AND sem.data_kind_contract.universe = 'evaluator')) OR (EXISTS (WITH RECURSIVE exposed(kind_contract) AS 
(SELECT (exposed_role.value ->> 'kind_contract') AS kind_contract 
FROM jsonb_array_elements(definition.input_roles || definition.output_roles) AS exposed_role(value) UNION SELECT child.value AS value 
FROM exposed JOIN sem.data_kind_contract AS parent ON parent.kind_contract = exposed.kind_contract JOIN LATERAL jsonb_array_elements_text(parent.member_contracts) AS child(value) ON true)
 SELECT included.kind_contract 
FROM ops.ddo_external_input_rows(r) AS external_input(value) JOIN LATERAL ops.ddo_body_kind_contracts((external_input.value ->> 'kind_contract'), external_input.value['meaning']) AS included(kind_contract) ON true JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = included.kind_contract 
WHERE sem.data_kind_contract.universe = 'evaluator'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'protected evaluator data cannot enter an external packet', ERRCODE = 'P0001';
 END IF;
 SELECT count(*) AS count_1, coalesce(sum(octet_length(data.canonical_json(external_input.value))), 0) AS coalesce_1, coalesce(bool_or(sem.data_kind_contract.universe = 'evaluator' OR role.value IS NULL OR NOT (role.value['accepted_kind_contracts'] ? (external_input.value ->> 'kind_contract'))), false) AS coalesce_2 
FROM ops.ddo_external_input_rows(r) AS external_input(value) JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = (external_input.value ->> 'kind_contract') LEFT OUTER JOIN LATERAL (SELECT input_role.value AS value 
FROM jsonb_array_elements(definition.input_roles) AS input_role(value) 
WHERE (input_role.value ->> 'name') = (external_input.value ->> 'role')) AS role ON true INTO count_, size_, forbidden;
 IF (count_ != jsonb_array_length(r.binding['inputs']) OR forbidden) THEN
  RAISE EXCEPTION USING MESSAGE = 'external packet input differs from exact admitted role/kind membership', ERRCODE = 'P0001';
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('role', outputs.role ->> 'name', 'kind_contract', outputs.role ->> 'kind_contract', 'schema', sem.data_kind_contract.body_schema, 'minimum', outputs.role['minimum'], 'maximum', outputs.role['maximum'], 'collection', outputs.role['collection']) ORDER BY outputs.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(definition.output_roles) WITH ORDINALITY AS outputs(role, ordinal) JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = (outputs.role ->> 'kind_contract') INTO contracts;
 IF (size_ + octet_length(data.canonical_json(r.binding)) + octet_length(data.canonical_json(contracts)) + octet_length(data.canonical_json(definition.support_contract['external'])) > CAST((p ->> 'max_bytes') AS INTEGER)) THEN
  RAISE EXCEPTION USING MESSAGE = 'external packet exceeds owned packet capacity', ERRCODE = 'P0001';
 END IF;
 SELECT coalesce(jsonb_agg(external_input.value), CAST('[]' AS JSONB)) AS coalesce_1 
FROM ops.ddo_external_input_rows(r) AS external_input(value) INTO inputs;
 packet_value := jsonb_build_object('version', 'external-data-packet-v1', 'packet_id', key, 'request_id', r.id, 'request_key', r.request_key, 'generation', r.generation, 'task_id', t.id, 'project_id', r.project_id, 'release_id', r.release_id, 'runtime_id', r.runtime_id, 'operation_id', r.operation_id, 'recipe', r.recipe, 'implementation_revision', definition.implementation_revision, 'subject', r.subject, 'subject_definition', ops.ddo_operation_subject(r.release_id, r.operation_id), 'original_source', r.original_source, 'analyzed_scope', r.analyzed_scope, 'binding', r.binding, 'protocol', definition.support_contract['external'], 'inputs', inputs, 'result_contract', contracts, 'outcomes', definition.support_contract['outcomes']);
 IF (octet_length(data.canonical_json(packet_value)) > CAST((p ->> 'max_bytes') AS INTEGER)) THEN
  RAISE EXCEPTION USING MESSAGE = 'complete external packet exceeds owned packet capacity', ERRCODE = 'P0001';
 END IF;
 INSERT INTO ops.data_external_packet (id, request_id, generation, task_id, producer_attempt, producer_holder, runtime_id, payload, payload_digest, created_at) VALUES (key, r.id, r.generation, t.id, t.attempt, t.claimed_by, r.runtime_id, packet_value, ops.ddo_digest(packet_value), clock_timestamp());
 UPDATE ops.task SET status='pending', lease_until=NULL WHERE ops.task.id = t.id;
 RETURN jsonb_build_object('payload', jsonb_build_object('packet_id', key, 'packet_digest', ops.ddo_digest(packet_value), 'state', 'awaiting-external'));
END

