 packet_value := jsonb_build_object('version', 'external-data-packet-v1', 'packet_id', key, 'request_id', r.id, 'request_key', r.request_key, 'generation', r.generation, 'task_id', t.id, 'project_id', r.project_id, 'release_id', r.release_id, 'runtime_id', r.runtime_id, 'operation_id', r.operation_id, 'recipe', r.recipe, 'implementation_revision', definition.implementation_revision, 'subject', r.subject, 'subject_definition', ops.ddo_operation_subject(r.release_id, r.operation_id), 'original_source', r.original_source, 'analyzed_scope', r.analyzed_scope, 'binding', r.binding, 'protocol', definition.support_contract['external'], 'inputs', inputs, 'result_contract', contracts, 'outcomes', definition.support_contract['outcomes']);
 IF (octet_length(data.canonical_json(packet_value)) > CAST((p ->> 'max_bytes') AS INTEGER)) THEN
  RAISE EXCEPTION USING MESSAGE = 'complete external packet exceeds owned packet capacity', ERRCODE = 'P0001';
 END IF;
 INSERT INTO ops.data_external_packet (id, request_id, generation, task_id, producer_attempt, producer_holder, runtime_id, payload, payload_digest, created_at) VALUES (key, r.id, r.generation, t.id, t.attempt, t.claimed_by, r.runtime_id, packet_value, ops.ddo_digest(packet_value), clock_timestamp());
 UPDATE ops.task SET status='pending', lease_until=NULL WHERE ops.task.id = t.id;
 RETURN jsonb_build_object('payload', jsonb_build_object('packet_id', key, 'packet_digest', ops.ddo_digest(packet_value), 'state', 'awaiting-external'));
END$$

