DECLARE
 scope_key text;
 e bigint;
 key text;
BEGIN
 PERFORM ops.ddo_fields(p_payload, ARRAY['project_id', 'original_source', 'selector_kind', 'selector', 'reason']);
 IF (nullif((p_payload ->> 'reason'), '') IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'revocation requires reason', ERRCODE = 'P0001';
 END IF;
 IF (NOT ((EXISTS (SELECT 1 
FROM ops.data_derivation JOIN ops.data_request ON ops.data_request.id = ops.data_derivation.request_id 
WHERE ops.data_request.project_id = (p_payload ->> 'project_id') AND ops.data_request.original_source IS NOT DISTINCT FROM (p_payload ->> 'original_source') AND ((p_payload ->> 'selector_kind') = 'derivation' AND ops.data_derivation.id = (p_payload ->> 'selector') OR (p_payload ->> 'selector_kind') = 'recipe' AND ops.data_derivation.recipe = (p_payload ->> 'selector') OR (p_payload ->> 'selector_kind') = 'runtime' AND ops.data_derivation.runtime_id = (p_payload ->> 'selector') OR (p_payload ->> 'selector_kind') = 'product' AND (EXISTS (SELECT 1 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = ops.data_derivation.id AND ops.data_derivation_output.product_id = (p_payload ->> 'selector')))))) OR (EXISTS (SELECT 1 
FROM ops.original_source_admission 
WHERE ops.original_source_admission.project_id = (p_payload ->> 'project_id') AND ops.original_source_admission.original_source IS NOT DISTINCT FROM (p_payload ->> 'original_source') AND ((p_payload ->> 'selector_kind') = 'original-admission' AND ops.original_source_admission.id = (p_payload ->> 'selector') OR (p_payload ->> 'selector_kind') = 'original-source' AND ops.original_source_admission.source_reference = (p_payload ->> 'selector') OR (p_payload ->> 'selector_kind') = 'product' AND ops.original_source_admission.product_id = (p_payload ->> 'selector')))))) THEN
  RAISE EXCEPTION USING MESSAGE = 'revocation selector outside project/source scope', ERRCODE = 'P0001';
 END IF;
 scope_key := ops.ddo_scope(p_payload ->> 'project_id', p_payload ->> 'original_source');
 INSERT INTO ops.data_trust_scope (scope, project_id, epoch) VALUES (scope_key, (p_payload ->> 'project_id'), 0) ON CONFLICT DO NOTHING;
 PERFORM 1 
FROM ops.data_trust_scope 
WHERE ops.data_trust_scope.scope = scope_key FOR UPDATE;
 PERFORM ops.ddo_authorize_request(data_request) AS ddo_authorize_request_1 
FROM ops.data_request 
WHERE ops.data_request.project_id = (p_payload ->> 'project_id') AND ops.data_request.original_source IS NOT DISTINCT FROM (p_payload ->> 'original_source') AND ((p_payload ->> 'selector_kind') = 'recipe' AND ops.data_request.recipe = (p_payload ->> 'selector') OR (p_payload ->> 'selector_kind') = 'runtime' AND ops.data_request.runtime_id = (p_payload ->> 'selector') OR (EXISTS (SELECT 1 
FROM ops.data_derivation 
WHERE ops.data_derivation.request_id = ops.data_request.id AND ((p_payload ->> 'selector_kind') = 'derivation' AND ops.data_derivation.id = (p_payload ->> 'selector') OR (p_payload ->> 'selector_kind') = 'recipe' AND ops.data_derivation.recipe = (p_payload ->> 'selector') OR (p_payload ->> 'selector_kind') = 'runtime' AND ops.data_derivation.runtime_id = (p_payload ->> 'selector') OR (p_payload ->> 'selector_kind') = 'product' AND (EXISTS (SELECT 1 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = ops.data_derivation.id AND ops.data_derivation_output.product_id = (p_payload ->> 'selector')))))));
 PERFORM ops.ddo_authorize(sem.data_kind_contract.universe) AS ddo_authorize_1 
FROM ops.original_source_admission JOIN kb.data_product ON kb.data_product.id = ops.original_source_admission.product_id JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = kb.data_product.kind_contract 
WHERE ops.original_source_admission.project_id = (p_payload ->> 'project_id') AND ops.original_source_admission.original_source IS NOT DISTINCT FROM (p_payload ->> 'original_source') AND ((p_payload ->> 'selector_kind') = 'original-admission' AND ops.original_source_admission.id = (p_payload ->> 'selector') OR (p_payload ->> 'selector_kind') = 'original-source' AND ops.original_source_admission.source_reference = (p_payload ->> 'selector') OR (p_payload ->> 'selector_kind') = 'product' AND ops.original_source_admission.product_id = (p_payload ->> 'selector'));
 UPDATE ops.data_trust_scope SET epoch=(ops.data_trust_scope.epoch + 1) WHERE ops.data_trust_scope.scope = scope_key RETURNING ops.data_trust_scope.epoch INTO e;
 key := 'revocation:' || ops.ddo_digest(jsonb_build_array(scope_key, e, p_payload));
 INSERT INTO ops.data_revocation (id, scope, epoch, selector_kind, selector, reason, created_at) VALUES (key, scope_key, e, (p_payload ->> 'selector_kind'), (p_payload ->> 'selector'), (p_payload ->> 'reason'), clock_timestamp());
 RETURN jsonb_build_object('payload', jsonb_build_object('revocation_id', key, 'scope', scope_key, 'epoch', e));
END

