CREATE OR REPLACE FUNCTION ops.ddo_impl_select_data_population(p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 obligation ops.data_obligation%ROWTYPE;
 demand ops.data_demand%ROWTYPE;
 parent ops.data_population%ROWTYPE;
 boundary ops.data_demand_read%ROWTYPE;
 selected ops.data_population%ROWTYPE;
 source_request ops.data_request%ROWTYPE;
 p jsonb := p_payload;
 binding_model jsonb;
 compiled jsonb;
 selection jsonb;
 expression jsonb;
 context jsonb;
 refs jsonb;
 roledef jsonb;
 predicate jsonb;
 universe jsonb;
 row_value jsonb;
 expected jsonb;
 members jsonb := CAST('[]' AS JSONB);
 evidence jsonb;
 meaning jsonb;
 scope jsonb;
 candidates jsonb;
 role text;
 value_key text;
 key text;
 projection_mode text;
 count_roles integer;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['obligation_id', 'population_name', 'parent_population_id', 'read_id']);
 SELECT ops.data_obligation.* 
FROM ops.data_obligation 
WHERE ops.data_obligation.id = (p ->> 'obligation_id') INTO STRICT obligation;
 p := p || jsonb_build_object('demand_id', obligation.demand_id, 'operation_id', obligation.operation_id, 'subject', obligation.subject, 'original_source', obligation.original_source);
 SELECT ops.data_demand.* 
FROM ops.data_demand 
WHERE ops.data_demand.id = (p ->> 'demand_id') INTO STRICT demand;
 SELECT ops.data_population.* 
FROM ops.data_population 
WHERE ops.data_population.id = (p ->> 'parent_population_id') AND ops.data_population.demand_id = demand.id INTO STRICT parent;
 SELECT ops.data_request.* 
FROM ops.data_request JOIN ops.data_derivation ON ops.data_derivation.request_id = ops.data_request.id 
WHERE ops.data_derivation.id = (parent.evidence ->> 'derivation_id') INTO STRICT source_request;
 SELECT ops.data_demand_read.* 
FROM ops.data_demand_read 
WHERE ops.data_demand_read.id = (p ->> 'read_id') AND ops.data_demand_read.demand_id = demand.id INTO STRICT boundary;
 scope := ops.ddo_require_read_current(boundary, demand.project_id);
 PERFORM ops.ddo_require_active_demand(demand.id);
 IF (NOT ops.ddo_read_visible(parent.created_at, parent.created_xid, boundary) OR NOT ops.ddo_node_valid('population', parent.id, boundary) OR source_request.project_id IS DISTINCT FROM demand.project_id OR (parent.evidence ? 'selection') OR parent.name = (p ->> 'population_name')) THEN
  RAISE EXCEPTION USING MESSAGE = 'selected population lacks its pinned admitted base parent', ERRCODE = 'P0001';
 END IF;
 scope := boundary.trust_snapshot;
 PERFORM ops.ddo_authorize(sem.data_kind_contract.universe) AS ddo_authorize_1 
FROM kb.data_product JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = kb.data_product.kind_contract 
WHERE kb.data_product.id = (parent.evidence ->> 'product_id');
 SELECT selected_operation.value 
FROM jsonb_array_elements(demand.selection['operations']) AS selected_operation(value) 
WHERE (selected_operation.value ->> 'operation') = (p ->> 'operation_id') INTO STRICT selection;
 SELECT to_jsonb(data_operation_definition) AS to_jsonb_1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = demand.release_id AND sem.data_operation_definition.operation_id = (p ->> 'operation_id') INTO STRICT compiled;
 SELECT jsonb_build_object('kinds', sem.data_operation_release.binding_types) AS jsonb_build_object_1 
FROM sem.data_operation_release 
WHERE sem.data_operation_release.release_id = demand.release_id INTO STRICT binding_model;
 expression := compiled['binding_expression'];
 IF ((compiled ->> 'definition_identity') IS DISTINCT FROM (selection ->> 'definition') OR (compiled ->> 'eligibility_identity') IS DISTINCT FROM (selection ->> 'eligibility')) THEN
  RAISE EXCEPTION USING MESSAGE = 'population filter differs from frozen definition', ERRCODE = 'P0001';
 END IF;
 context := jsonb_build_object('model', binding_model, 'roledefs', compiled['input_roles'], 'parameters', selection['parameters'], 'parameter_meaning', selection['parameter_meaning'], 'parameterdefs', compiled['parameter_definitions'], 'choices', selection['choices'], 'subject', p ->> 'subject', 'original_source', p ->> 'original_source', 'roles', CAST('{}' AS JSONB), 'populations', CAST('{}' AS JSONB), 'witnesses', CAST('{}' AS JSONB));
 refs := ops.ddo_binding_population_refs(expression, context);
 SELECT count(*) AS count_1, min(population_reference.key) AS min_1 
FROM jsonb_each_text(refs) AS population_reference(key, value) 
WHERE population_reference.value = (p ->> 'population_name') INTO count_roles, role;
 IF (count_roles != 1) THEN
  RAISE EXCEPTION USING MESSAGE = 'selected population name must identify one frozen active role', ERRCODE = 'P0001';
 END IF;
 SELECT input_role.value 
FROM jsonb_array_elements(compiled['input_roles']) AS input_role(value) 
WHERE (input_role.value ->> 'name') = role INTO STRICT roledef;
 projection_mode := coalesce(ops.ddo_binding_population_projection(expression, context, role), 'member');
 predicate := ops.ddo_population_filter(expression, role, selection['choices']);
 IF (NOT (source_request.operation_id = ANY (ops.ddo_consumed_producers(demand.selection, (p ->> 'operation_id')))) OR NOT (EXISTS (SELECT discovery_relation.value 
FROM jsonb_array_elements(demand.selection['discovery']) AS discovery_relation(value) 
WHERE (discovery_relation.value ->> 'population') = parent.name AND (discovery_relation.value ->> 'producer') = source_request.operation_id AND (discovery_relation.value ->> 'output_role') = (parent.evidence ->> 'member_role')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'selected parent is not a declared prerequisite discovery population', ERRCODE = 'P0001';
 END IF;
 IF (projection_mode != 'qualified-context' AND NOT (EXISTS (SELECT kb.data_product.id 
FROM kb.data_product JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = kb.data_product.kind_contract 
WHERE kb.data_product.id = (parent.evidence ->> 'product_id') AND (EXISTS (SELECT accepted_kind.value 
FROM jsonb_array_elements_text(roledef['accepted_kind_contracts']) AS accepted_kind(value) 
WHERE sem.data_kind_contract.member_contracts ? accepted_kind.value))))) THEN
  RAISE EXCEPTION USING MESSAGE = 'selected parent does not declare the role member kind', ERRCODE = 'P0001';
 END IF;
 IF ((source_request.subject, ops.ddo_operation_subject(source_request.release_id, source_request.operation_id), source_request.original_source, source_request.analyzed_scope) IS DISTINCT FROM (obligation.subject, ops.ddo_operation_subject(demand.release_id, obligation.operation_id), obligation.original_source, obligation.analyzed_scope) AND NOT (EXISTS (SELECT source_entry.value 
FROM jsonb_array_elements(coalesce(demand.selection['source_sets'][(((roledef['support']) ->> 'source_set'))]['entries'], CAST('[]' AS JSONB))) AS source_entry(value) 
WHERE (source_entry.value ->> 'project_id') = demand.project_id AND (source_entry.value ->> 'original_source') IS NOT DISTINCT FROM source_request.original_source AND (source_entry.value ->> 'product') = (parent.evidence ->> 'product_id')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'selected parent source is outside the role frozen source set', ERRCODE = 'P0001';
 END IF;
 PERFORM ops.ddo_authorize(sem.data_kind_contract.universe) AS ddo_authorize_1 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = (roledef ->> 'kind_contract');
 SELECT coalesce(jsonb_agg(to_jsonb(binding_row)), CAST('[]' AS JSONB)) AS coalesce_1 
FROM ops.data_binding_rows(demand.id, p ->> 'operation_id', scope, boundary.id, p ->> 'subject', p['original_source'], obligation.analyzed_scope) AS binding_row 
WHERE binding_row.product = (parent.evidence ->> 'product_id') AND (roledef['accepted_kind_contracts'] ? binding_row.kind_contract) AND (binding_row.support_episodes ? (parent.evidence ->> 'derivation_id')) AND (binding_row.support_evidence ->> 'use_id') = (parent.evidence ->> 'admission_use_id') AND ((binding_row.support_evidence['producer_output']) ->> 'role') = (parent.evidence ->> 'member_role') INTO universe;
 IF (projection_mode = 'qualified-context') THEN
  IF (predicate != jsonb_build_object('operator', 'all', 'children', CAST('[]' AS JSONB))) THEN
   RAISE EXCEPTION USING MESSAGE = 'qualified-context closure cannot apply derived body filters to discovery members', ERRCODE = 'P0001';
  END IF;
  members := parent.members;
 ELSE
  FOR expected IN SELECT expected_member.value 
FROM jsonb_array_elements(parent.members) AS expected_member(value) LOOP
   SELECT to_jsonb(data_product_member) AS to_jsonb_1 
FROM kb.data_product_member 
WHERE kb.data_product_member.product_id = (parent.evidence ->> 'product_id') AND kb.data_product_member.member_id = (expected ->> 'member_id') AND (roledef['accepted_kind_contracts'] ? kb.data_product_member.kind_contract) INTO row_value;
   IF (row_value IS NULL) THEN
    CONTINUE;
   END IF;
   IF (NOT coalesce(ops.ddo_binding_source_address(roledef, jsonb_build_object('product', parent.evidence ->> 'product_id', 'member', row_value ->> 'member_id', 'subject', row_value ->> 'subject', 'subject_definition', row_value ->> 'subject_definition', 'original_source', row_value ->> 'original_source', 'analyzed_scope', row_value['analyzed_scope'], 'meaning_body', row_value['body']), obligation.original_source, coalesce(demand.selection['source_sets'], CAST('{}' AS JSONB))), false)) THEN
    CONTINUE;
   END IF;
   IF (ops.ddo_binding_subject(roledef, jsonb_build_object('subject', (row_value ->> 'subject'), 'meaning_body', row_value['body']), (p ->> 'subject'), obligation.original_source) IS NULL) THEN
    RAISE EXCEPTION USING MESSAGE = 'population subject relationship is unknown', ERRCODE = 'P0001';
   END IF;
   IF (NOT ops.ddo_binding_subject(roledef, jsonb_build_object('subject', row_value ->> 'subject', 'meaning_body', row_value['body']), p ->> 'subject', obligation.original_source)) THEN
    CONTINUE;
   END IF;
   SELECT coalesce(jsonb_agg(population_fact.value), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(universe) AS population_fact(value) 
WHERE (population_fact.value ->> 'member') = (expected ->> 'member_id') AND ops.ddo_binding_source(roledef, population_fact.value, obligation.original_source, coalesce(demand.selection['source_sets'], CAST('{}' AS JSONB))) INTO candidates;
   IF (jsonb_array_length(candidates) > 1) THEN
    RAISE EXCEPTION USING MESSAGE = 'parent population member has ambiguous producing occurrences', ERRCODE = 'P0001';
   END IF;
   IF (jsonb_array_length(candidates) = 0) THEN
    RAISE EXCEPTION USING MESSAGE = 'parent population member facts unavailable in pinned read', ERRCODE = 'P0001';
   END IF;
   row_value := candidates[0];
   IF (ops.ddo_binding_test(predicate, jsonb_set(context, ARRAY['roles', role], jsonb_build_array(row_value)))) THEN
    members := members || jsonb_build_array(expected);
   END IF;
  END LOOP;
 END IF;
 meaning := jsonb_build_object('parent', parent.semantic_key, 'operation', p ->> 'operation_id', 'kind_contract', roledef ->> 'kind_contract', 'role', role, 'subject', p ->> 'subject', 'subject_definition', ops.ddo_operation_subject(demand.release_id, obligation.operation_id), 'original_source', p ->> 'original_source', 'analyzed_scope', obligation.analyzed_scope, 'filter', predicate, 'parameters', selection['parameter_meaning'], 'members', members, 'complete', parent.complete);
 IF (projection_mode = 'qualified-context') THEN
  meaning := meaning || jsonb_build_object('projection', projection_mode);
 END IF;
 value_key := 'population-value:' || ops.ddo_digest(meaning);
 SELECT old.* 
FROM ops.data_population AS "old" 
WHERE "old".demand_id = demand.id AND "old".name = (p ->> 'population_name') AND "old".selected_obligation_id = obligation.id AND "old".semantic_key = value_key AND (("old".evidence['selection']) ->> 'parent_population_id') = parent.id AND ops.ddo_node_valid('population', "old".id) ORDER BY "old".created_at DESC, "old".id DESC 
 LIMIT 1 INTO selected;
 IF (selected.id IS NULL) THEN
  evidence := (parent.evidence - 'population_id') || jsonb_build_object('producer_context', ops.ddo_population_producer_context(parent), 'selection', jsonb_build_object('parent_population_id', parent.id, 'read_id', boundary.id, 'obligation_id', obligation.id, 'operation_id', (p ->> 'operation_id'), 'subject', (p ->> 'subject'), 'subject_definition', ops.ddo_operation_subject(demand.release_id, obligation.operation_id), 'original_source', (p ->> 'original_source'), 'analyzed_scope', obligation.analyzed_scope, 'role', role, 'definition', (selection ->> 'definition'), 'eligibility', (selection ->> 'eligibility'), 'filter', predicate, 'parameter_meaning', selection['parameter_meaning'], 'choices', selection['choices']));
  key := 'population:' || ops.ddo_digest(jsonb_build_array(demand.id, (p ->> 'population_name'), value_key, evidence));
  evidence := evidence || jsonb_build_object('population_id', key);
  INSERT INTO ops.data_population (id, demand_id, selected_obligation_id, semantic_key, name, context_key, members, complete, evidence, created_at, created_xid) VALUES (key, demand.id, obligation.id, value_key, (p ->> 'population_name'), ops.ddo_digest(ops.ddo_population_evidence_scope(evidence)), members, parent.complete, evidence, clock_timestamp(), CAST(pg_current_xact_id() AS TEXT)) ON CONFLICT DO NOTHING;
  SELECT ops.data_population.* 
FROM ops.data_population 
WHERE ops.data_population.id = key INTO STRICT selected;
 END IF;
 RETURN jsonb_build_object('payload', jsonb_build_object('inserted_obligations', 0, 'population_id', selected.id, 'name', selected.name, 'semantic_key', selected.semantic_key, 'members', selected.members, 'complete', selected.complete, 'evidence', selected.evidence));
END$$

