DECLARE
 selected jsonb := ops.ddo_input_support_selection(input_record);
 matched jsonb;
 episodes jsonb;
BEGIN
 IF (NOT (EXISTS (SELECT manifest_input.value 
FROM jsonb_array_elements(binding['inputs']) AS manifest_input(value) 
WHERE manifest_input.value = input_record))) THEN
  RAISE EXCEPTION USING MESSAGE = 'support selection is not an exact manifest input', ERRCODE = '23514';
 END IF;
 SELECT coalesce(jsonb_agg(selected_support.value), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(binding['support']) AS selected_support(value) 
WHERE (selected_support.value ->> 'role') = (input_record ->> 'role') AND selected_support.value['position'] IS NOT DISTINCT FROM input_record['position'] AND (coalesce((selected_support.value ->> 'kind'), 'computation') = 'computation' AND (selected ? (selected_support.value ->> 'derivation_id')) AND (EXISTS (SELECT ops.data_derivation_output.derivation_id 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = (selected_support.value ->> 'derivation_id') AND ops.data_derivation_output.product_id = (input_record ->> 'product_id') AND (ops.data_derivation_output.member_id IS NULL OR ops.data_derivation_output.member_id IS NOT DISTINCT FROM (input_record ->> 'member_id')))) OR (selected_support.value ->> 'kind') IN ('original-source', 'authored') AND selected = CAST('[]' AS JSONB) AND (input_record ->> 'member_id') IS NULL AND (EXISTS (SELECT ops.original_source_admission.id 
FROM ops.original_source_admission 
WHERE ops.original_source_admission.id = (selected_support.value ->> 'admission_id') AND ops.original_source_admission.product_id = (input_record ->> 'product_id') AND ops.original_source_admission.source_reference = (selected_support.value ->> 'source_reference')))) INTO matched;
 SELECT coalesce(jsonb_agg(known.episode ORDER BY known.episode COLLATE "C"), CAST('[]' AS JSONB)) AS coalesce_1 
FROM (SELECT DISTINCT known_support.value ->> 'derivation_id' AS episode 
FROM jsonb_array_elements(matched) AS known_support(value) 
WHERE coalesce((known_support.value ->> 'kind'), 'computation') = 'computation') AS known INTO episodes;
 IF (episodes IS DISTINCT FROM selected) THEN
  RAISE EXCEPTION USING MESSAGE = 'selected input episode set lacks exact authentic output support', ERRCODE = '23514';
 END IF;
 RETURN QUERY SELECT known_support.value 
FROM jsonb_array_elements(matched) AS known_support(value);
END

