DECLARE
 selected jsonb := input_record['support_derivation_ids'];
 canonical jsonb;
BEGIN
 IF (jsonb_typeof(selected) IS DISTINCT FROM 'array' OR (EXISTS (SELECT selected_input.value 
FROM jsonb_array_elements(selected) AS selected_input(value) 
WHERE jsonb_typeof(selected_input.value) IS DISTINCT FROM 'string' OR (selected_input.value #>> CAST('{}' AS TEXT[])) = ''))) THEN
  RAISE EXCEPTION USING MESSAGE = 'input support requires an explicit canonical episode set', ERRCODE = '23514';
 END IF;
 SELECT coalesce(jsonb_agg(unique_values.value ORDER BY (unique_values.value #>> CAST('{}' AS TEXT[])) COLLATE "C"), CAST('[]' AS JSONB)) AS coalesce_1 
FROM (SELECT DISTINCT selected_input.value AS value 
FROM jsonb_array_elements(selected) AS selected_input(value)) AS unique_values INTO canonical;
 IF (selected IS DISTINCT FROM canonical) THEN
  RAISE EXCEPTION USING MESSAGE = 'input support episode set is duplicated or unordered', ERRCODE = '23514';
 END IF;
 RETURN selected;
END

