DECLARE
 k sem.data_kind_contract%ROWTYPE;
 key text;
 b jsonb;
 bd text;
 m jsonb;
 raw jsonb;
 family_value jsonb;
 n bigint;
 previous kb.data_product%ROWTYPE;
 packet jsonb;
 member_context jsonb;
 canonical_members jsonb;
 member_body jsonb;
 member_kind sem.data_kind_contract%ROWTYPE;
 inserted_product bigint;
BEGIN
 PERFORM ops.ddo_fields(context, ARRAY['project_id', 'release_id', 'subject', 'subject_definition', 'original_source', 'analyzed_scope']);
 PERFORM ops.ddo_require_subject_source(subject_scopes, context ->> 'subject_definition', context ->> 'original_source');
 PERFORM ops.ddo_fields(o, ARRAY['kind_contract', 'body', 'members'], ARRAY['artifact_digest']);
 SELECT sem.data_kind_contract.* 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = (o ->> 'kind_contract') INTO STRICT k;
 PERFORM ops.ddo_authorize(k.universe);
 IF (NOT (EXISTS (SELECT 1 
FROM sem.data_kind_release 
WHERE sem.data_kind_release.release_id = (context ->> 'release_id') AND sem.data_kind_release.kind_contract = k.kind_contract))) THEN
  RAISE EXCEPTION USING MESSAGE = 'output kind is outside release', ERRCODE = 'P0001';
 END IF;
 IF ((o ->> 'artifact_digest') IS NOT NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'artifact publication requires an authenticated staged receipt profile', ERRCODE = 'P0001';
 END IF;
 b := data.ddo_normalize(o['body']);
 PERFORM ops.ddo_body_access(k.kind_contract, b);
 IF (NOT public.json_matches_schema(CAST(k.meaning_schema AS JSON), CAST(b AS JSON)) OR NOT public.json_matches_schema(CAST(k.body_schema AS JSON), CAST(data.ddo_json(b) AS JSON)) OR jsonb_typeof(o['members']) != 'array') THEN
  RAISE EXCEPTION USING MESSAGE = 'body violates kind contract', ERRCODE = 'P0001';
 END IF;
 IF (k.member_schema = CAST('{"not":{}}' AS JSONB)) THEN
  IF (o['members'] != CAST('[]' AS JSONB)) THEN
   RAISE EXCEPTION USING MESSAGE = 'noncontainer kind cannot publish projected members', ERRCODE = 'P0001';
  END IF;
 ELSE
  canonical_members := data.ddo_field(b, 'members');
  IF ((canonical_members ->> 0) IS DISTINCT FROM 'sequence' OR jsonb_array_length(canonical_members[1]) IS DISTINCT FROM jsonb_array_length(o['members'])) THEN
   RAISE EXCEPTION USING MESSAGE = 'body/member projection count disagreement', ERRCODE = 'P0001';
  END IF;
 END IF;
 IF (EXISTS (SELECT 1 
FROM jsonb_array_elements(o['members']) WITH ORDINALITY AS entry(value, ordinality) GROUP BY entry.value ->> 'member_id' 
HAVING count(*) != 1)) THEN
  RAISE EXCEPTION USING MESSAGE = 'duplicate member local identity', ERRCODE = 'P0001';
 END IF;
 bd := data.ddo_identity('body', b);
 key := data.ddo_identity('product', jsonb_build_array('mapping', jsonb_build_array(jsonb_build_array('body', jsonb_build_array('string', bd)), jsonb_build_array('kind', jsonb_build_array('string', k.kind_contract)), jsonb_build_array('subject', jsonb_build_array('string', context ->> 'subject')), jsonb_build_array('subject_context', data.ddo_json_meaning(jsonb_build_object('project_id', context ->> 'project_id', 'subject', context ->> 'subject', 'subject_definition', context ->> 'subject_definition', 'original_source', context ->> 'original_source', 'analyzed_scope', context['analyzed_scope']))))));
 INSERT INTO kb.data_product (id, kind_contract, project_id, subject, subject_definition, original_source, analyzed_scope, canonical_body, body_digest, artifact_digest) VALUES (key, k.kind_contract, (context ->> 'project_id'), (context ->> 'subject'), (context ->> 'subject_definition'), (context ->> 'original_source'), (context['analyzed_scope']), b, bd, (o ->> 'artifact_digest')) ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS inserted_product = ROW_COUNT;
 SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = key INTO STRICT previous;
 IF (previous.kind_contract IS DISTINCT FROM k.kind_contract OR previous.project_id IS DISTINCT FROM (context ->> 'project_id') OR previous.subject IS DISTINCT FROM (context ->> 'subject') OR previous.subject_definition IS DISTINCT FROM (context ->> 'subject_definition') OR previous.original_source IS DISTINCT FROM (context ->> 'original_source') OR previous.body_digest IS DISTINCT FROM bd OR previous.canonical_body IS DISTINCT FROM b OR previous.analyzed_scope IS DISTINCT FROM context['analyzed_scope']) THEN
  RAISE EXCEPTION USING MESSAGE = 'product identity/custody collision', ERRCODE = 'P0001';
 END IF;
 FOR m, packet IN SELECT entry.value, canonical.value AS value_1 
FROM jsonb_array_elements(o['members']) WITH ORDINALITY AS entry(value, ordinality) JOIN jsonb_array_elements(canonical_members[1]) WITH ORDINALITY AS canonical(value, ordinality) ON entry.ordinality = canonical.ordinality ORDER BY entry.ordinality LOOP
  PERFORM ops.ddo_fields(m, ARRAY['member_id', 'kind_contract', 'context', 'body'], ARRAY['coordinates', 'roles', 'endpoints', 'coverage', 'choices']);
  PERFORM ops.ddo_fields(m['context'], ARRAY['subject', 'subject_definition', 'original_source', 'analyzed_scope']);
  member_context := m['context'];
  member_body := data.ddo_normalize(m['body']);
  IF ((packet ->> 0) != 'mapping' OR jsonb_array_length(packet[1]) != 4 OR data.ddo_field(packet, 'member_id') IS DISTINCT FROM jsonb_build_array('string', (m ->> 'member_id')) OR data.ddo_field(packet, 'kind_contract') IS DISTINCT FROM jsonb_build_array('string', (m ->> 'kind_contract')) OR data.ddo_field(packet, 'body') IS DISTINCT FROM member_body OR data.ddo_json(data.ddo_field(packet, 'context')) IS DISTINCT FROM member_context OR nullif((member_context ->> 'subject'), '') IS NULL OR nullif((member_context ->> 'subject_definition'), '') IS NULL OR (member_context ->> 'original_source') IS DISTINCT FROM (context ->> 'original_source')) THEN
   RAISE EXCEPTION USING MESSAGE = 'member context/body differs from canonical container packet', ERRCODE = 'P0001';
  END IF;
  PERFORM ops.ddo_require_subject_source(subject_scopes, member_context ->> 'subject_definition', member_context ->> 'original_source');
  SELECT sem.data_kind_contract.* 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = (m ->> 'kind_contract') INTO STRICT member_kind;
  PERFORM ops.ddo_authorize(member_kind.universe);
  raw := data.ddo_json(member_body);
  IF (NOT (k.member_contracts ? member_kind.kind_contract) OR NOT (EXISTS (SELECT 1 
FROM sem.data_kind_release 
WHERE sem.data_kind_release.release_id = (context ->> 'release_id') AND sem.data_kind_release.kind_contract = member_kind.kind_contract)) OR NOT public.json_matches_schema(CAST(member_kind.meaning_schema AS JSON), CAST(member_body AS JSON)) OR NOT public.json_matches_schema(CAST(member_kind.body_schema AS JSON), CAST(raw AS JSON))) THEN
   RAISE EXCEPTION USING MESSAGE = 'member kind/body differs from declared nominal container member contract', ERRCODE = 'P0001';
  END IF;
  IF (nullif((m ->> 'member_id'), '') IS NULL OR NOT public.json_matches_schema(CAST(k.member_schema AS JSON), CAST(raw AS JSON))) THEN
   RAISE EXCEPTION USING MESSAGE = 'invalid member contract', ERRCODE = 'P0001';
  END IF;
  IF ((member_kind.families ? 'coordinate') AND coalesce(raw['coordinates'], CAST('[]' AS JSONB)) IS DISTINCT FROM coalesce(m['coordinates'], CAST('[]' AS JSONB)) OR NOT (member_kind.families ? 'coordinate') AND coalesce(m['coordinates'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB) OR (member_kind.families ? 'role') AND coalesce(raw['roles'], CAST('[]' AS JSONB)) IS DISTINCT FROM coalesce(m['roles'], CAST('[]' AS JSONB)) OR NOT (member_kind.families ? 'role') AND coalesce(m['roles'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB) OR (member_kind.families ? 'endpoint') AND coalesce(raw['endpoints'], CAST('[]' AS JSONB)) IS DISTINCT FROM coalesce(m['endpoints'], CAST('[]' AS JSONB)) OR NOT (member_kind.families ? 'endpoint') AND coalesce(m['endpoints'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB) OR (member_kind.families ? 'coverage') AND coalesce(raw['coverage'], CAST('[]' AS JSONB)) IS DISTINCT FROM coalesce(m['coverage'], CAST('[]' AS JSONB)) OR NOT (member_kind.families ? 'coverage') AND coalesce(m['coverage'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB) OR (member_kind.families ? 'choice') AND coalesce(raw['choices'], CAST('[]' AS JSONB)) IS DISTINCT FROM coalesce(m['choices'], CAST('[]' AS JSONB)) OR NOT (member_kind.families ? 'choice') AND coalesce(m['choices'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB)) THEN
   RAISE EXCEPTION USING MESSAGE = 'member projection differs from semantic body', ERRCODE = 'P0001';
  END IF;
 END LOOP;
 INSERT INTO kb.data_product_member (product_id, member_id, kind_contract, subject, subject_definition, original_source, analyzed_scope, body) SELECT key, entry.value ->> 'member_id' AS anon_1, entry.value ->> 'kind_contract' AS anon_2, (entry.value['context']) ->> 'subject' AS anon_3, (entry.value['context']) ->> 'subject_definition' AS anon_4, (entry.value['context']) ->> 'original_source' AS anon_5, entry.value['context']['analyzed_scope'] AS anon_6, data.ddo_normalize(entry.value['body']) AS ddo_normalize_1 
FROM jsonb_array_elements(o['members']) WITH ORDINALITY AS entry(value, ordinality) 
WHERE inserted_product = 1 ORDER BY entry.ordinality ON CONFLICT DO NOTHING;
 FOR m IN SELECT entry.value 
FROM jsonb_array_elements(o['members']) WITH ORDINALITY AS entry(value, ordinality) LOOP
  SELECT sem.data_kind_contract.* 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = (m ->> 'kind_contract') INTO STRICT member_kind;
  FOR family_value, n IN SELECT family_entry.value, family_entry.ordinality - 1 AS anon_1 
FROM jsonb_array_elements(coalesce(m['coordinates'], CAST('[]' AS JSONB))) WITH ORDINALITY AS family_entry(value, ordinality) LOOP
   PERFORM ops.ddo_fields(family_value, ARRAY['original_source', 'start', 'end'], ARRAY['page']);
   IF ((context ->> 'original_source') IS NULL OR (family_value ->> 'original_source') IS DISTINCT FROM (context ->> 'original_source') OR NOT (member_kind.families ? 'coordinate')) THEN
    RAISE EXCEPTION USING MESSAGE = 'coordinate source/family mismatch', ERRCODE = 'P0001';
   END IF;
  END LOOP;
  FOR family_value, n IN SELECT family_entry.value, family_entry.ordinality - 1 AS anon_1 
FROM jsonb_array_elements(coalesce(m['roles'], CAST('[]' AS JSONB))) WITH ORDINALITY AS family_entry(value, ordinality) LOOP
   PERFORM ops.ddo_fields(family_value, ARRAY['role', 'position', 'multiplicity']);
   IF (NOT (member_kind.families ? 'role')) THEN
    RAISE EXCEPTION USING MESSAGE = 'undeclared role family', ERRCODE = 'P0001';
   END IF;
  END LOOP;
  FOR family_value, n IN SELECT family_entry.value, family_entry.ordinality - 1 AS anon_1 
FROM jsonb_array_elements(coalesce(m['endpoints'], CAST('[]' AS JSONB))) WITH ORDINALITY AS family_entry(value, ordinality) LOOP
   IF ((family_value ->> 'scope') = 'local') THEN
    PERFORM ops.ddo_fields(family_value, ARRAY['scope', 'role', 'member_id']);
   ELSE
    IF ((family_value ->> 'scope') = 'external') THEN
     PERFORM ops.ddo_fields(family_value, ARRAY['scope', 'role', 'product_id', 'member_id']);
    ELSE
     RAISE EXCEPTION USING MESSAGE = 'endpoint requires explicit local/external scope', ERRCODE = 'P0001';
    END IF;
   END IF;
   IF (NOT (member_kind.families ? 'endpoint') OR NOT (EXISTS (SELECT 1 
FROM kb.data_product 
WHERE kb.data_product.id = CASE WHEN ((family_value ->> 'scope') = 'local') THEN key ELSE (family_value ->> 'product_id') END AND kb.data_product.project_id = (context ->> 'project_id') AND kb.data_product.original_source IS NOT DISTINCT FROM (context ->> 'original_source')))) THEN
    RAISE EXCEPTION USING MESSAGE = 'endpoint custody/family mismatch', ERRCODE = 'P0001';
   END IF;
  END LOOP;
  FOR family_value, n IN SELECT family_entry.value, family_entry.ordinality - 1 AS anon_1 
FROM jsonb_array_elements(coalesce(m['coverage'], CAST('[]' AS JSONB))) WITH ORDINALITY AS family_entry(value, ordinality) LOOP
   PERFORM ops.ddo_fields(family_value, ARRAY['scope', 'start', 'end', 'complete']);
   IF (NOT (member_kind.families ? 'coverage')) THEN
    RAISE EXCEPTION USING MESSAGE = 'undeclared coverage family', ERRCODE = 'P0001';
   END IF;
  END LOOP;
  FOR family_value, n IN SELECT family_entry.value, family_entry.ordinality - 1 AS anon_1 
FROM jsonb_array_elements(coalesce(m['choices'], CAST('[]' AS JSONB))) WITH ORDINALITY AS family_entry(value, ordinality) LOOP
   PERFORM ops.ddo_fields(family_value, ARRAY['choice_group', 'alternative', 'selected']);
   IF (NOT (member_kind.families ? 'choice')) THEN
    RAISE EXCEPTION USING MESSAGE = 'undeclared choice family', ERRCODE = 'P0001';
   END IF;
  END LOOP;
 END LOOP;
 INSERT INTO kb.data_member_coordinate (product_id, member_id, ordinal, original_source, start, "end", page) SELECT key, entry.value ->> 'member_id' AS anon_1, item_1.ordinality - 1 AS anon_2, CAST(item_1.value ->> 'original_source' AS TEXT) AS anon_3, CAST(item_1.value ->> 'start' AS BIGINT) AS anon_4, CAST(item_1.value ->> 'end' AS BIGINT) AS anon_5, CAST(item_1.value ->> 'page' AS BIGINT) AS anon_6 
FROM jsonb_array_elements(o['members']) WITH ORDINALITY AS entry(value, ordinality) JOIN LATERAL jsonb_array_elements(coalesce(entry.value['coordinates'], CAST('[]' AS JSONB))) WITH ORDINALITY AS item_1(value, ordinality) ON true 
WHERE inserted_product = 1 ORDER BY entry.value ->> 'member_id', item_1.ordinality ON CONFLICT DO NOTHING;
 INSERT INTO kb.data_member_role (product_id, member_id, ordinal, role, position, multiplicity) SELECT key, entry.value ->> 'member_id' AS anon_1, item_1.ordinality - 1 AS anon_2, CAST(item_1.value ->> 'role' AS TEXT) AS anon_3, CAST(item_1.value ->> 'position' AS BIGINT) AS anon_4, CAST(item_1.value ->> 'multiplicity' AS BIGINT) AS anon_5 
FROM jsonb_array_elements(o['members']) WITH ORDINALITY AS entry(value, ordinality) JOIN LATERAL jsonb_array_elements(coalesce(entry.value['roles'], CAST('[]' AS JSONB))) WITH ORDINALITY AS item_1(value, ordinality) ON true 
WHERE inserted_product = 1 ORDER BY entry.value ->> 'member_id', item_1.ordinality ON CONFLICT DO NOTHING;
 INSERT INTO kb.data_member_endpoint (product_id, member_id, ordinal, role, endpoint_product, endpoint_member) SELECT key, entry.value ->> 'member_id' AS anon_1, item_1.ordinality - 1 AS anon_2, CAST(item_1.value ->> 'role' AS TEXT) AS anon_3, CASE WHEN ((item_1.value ->> 'scope') = 'local') THEN key ELSE item_1.value ->> 'product_id' END AS anon_4, CAST(item_1.value ->> 'member_id' AS TEXT) AS anon_5 
FROM jsonb_array_elements(o['members']) WITH ORDINALITY AS entry(value, ordinality) JOIN LATERAL jsonb_array_elements(coalesce(entry.value['endpoints'], CAST('[]' AS JSONB))) WITH ORDINALITY AS item_1(value, ordinality) ON true 
WHERE inserted_product = 1 ORDER BY entry.value ->> 'member_id', item_1.ordinality ON CONFLICT DO NOTHING;
 INSERT INTO kb.data_member_coverage (product_id, member_id, ordinal, scope, start, "end", complete) SELECT key, entry.value ->> 'member_id' AS anon_1, item_1.ordinality - 1 AS anon_2, CAST(item_1.value ->> 'scope' AS TEXT) AS anon_3, CAST(item_1.value ->> 'start' AS BIGINT) AS anon_4, CAST(item_1.value ->> 'end' AS BIGINT) AS anon_5, CAST(item_1.value ->> 'complete' AS BOOLEAN) AS anon_6 
FROM jsonb_array_elements(o['members']) WITH ORDINALITY AS entry(value, ordinality) JOIN LATERAL jsonb_array_elements(coalesce(entry.value['coverage'], CAST('[]' AS JSONB))) WITH ORDINALITY AS item_1(value, ordinality) ON true 
WHERE inserted_product = 1 ORDER BY entry.value ->> 'member_id', item_1.ordinality ON CONFLICT DO NOTHING;
 INSERT INTO kb.data_member_choice (product_id, member_id, ordinal, choice_group, alternative, selected) SELECT key, entry.value ->> 'member_id' AS anon_1, item_1.ordinality - 1 AS anon_2, CAST(item_1.value ->> 'choice_group' AS TEXT) AS anon_3, CAST(item_1.value ->> 'alternative' AS TEXT) AS anon_4, CAST(item_1.value ->> 'selected' AS BOOLEAN) AS anon_5 
FROM jsonb_array_elements(o['members']) WITH ORDINALITY AS entry(value, ordinality) JOIN LATERAL jsonb_array_elements(coalesce(entry.value['choices'], CAST('[]' AS JSONB))) WITH ORDINALITY AS item_1(value, ordinality) ON true 
WHERE inserted_product = 1 ORDER BY entry.value ->> 'member_id', item_1.ordinality ON CONFLICT DO NOTHING;
 WITH member_packets AS 
(SELECT entry.value AS member 
FROM jsonb_array_elements(o['members']) WITH ORDINALITY AS entry(value, ordinality)), 
expected AS 
(SELECT 'member' AS family, member_packets.member ->> 'member_id' AS member_id, -1 AS ordinal, jsonb_build_array(member_packets.member ->> 'kind_contract', (member_packets.member['context']) ->> 'subject', (member_packets.member['context']) ->> 'subject_definition', (member_packets.member['context']) ->> 'original_source', member_packets.member['context']['analyzed_scope'], data.ddo_normalize(member_packets.member['body'])) AS value 
FROM member_packets UNION ALL SELECT 'coordinate' AS anon_1, member_packets.member ->> 'member_id' AS anon_2, expected_item_1.ordinality - 1 AS anon_3, jsonb_build_array(CAST(expected_item_1.value ->> 'original_source' AS TEXT), CAST(expected_item_1.value ->> 'start' AS BIGINT), CAST(expected_item_1.value ->> 'end' AS BIGINT), CAST(expected_item_1.value ->> 'page' AS BIGINT)) AS jsonb_build_array_1 
FROM member_packets JOIN LATERAL jsonb_array_elements(coalesce(member_packets.member['coordinates'], CAST('[]' AS JSONB))) WITH ORDINALITY AS expected_item_1(value, ordinality) ON true UNION ALL SELECT 'role' AS anon_4, member_packets.member ->> 'member_id' AS anon_5, expected_item_2.ordinality - 1 AS anon_6, jsonb_build_array(CAST(expected_item_2.value ->> 'role' AS TEXT), CAST(expected_item_2.value ->> 'position' AS BIGINT), CAST(expected_item_2.value ->> 'multiplicity' AS BIGINT)) AS jsonb_build_array_2 
FROM member_packets JOIN LATERAL jsonb_array_elements(coalesce(member_packets.member['roles'], CAST('[]' AS JSONB))) WITH ORDINALITY AS expected_item_2(value, ordinality) ON true UNION ALL SELECT 'endpoint' AS anon_7, member_packets.member ->> 'member_id' AS anon_8, expected_item_3.ordinality - 1 AS anon_9, jsonb_build_array(CAST(expected_item_3.value ->> 'role' AS TEXT), CASE WHEN ((expected_item_3.value ->> 'scope') = 'local') THEN key ELSE expected_item_3.value ->> 'product_id' END, CAST(expected_item_3.value ->> 'member_id' AS TEXT)) AS jsonb_build_array_3 
FROM member_packets JOIN LATERAL jsonb_array_elements(coalesce(member_packets.member['endpoints'], CAST('[]' AS JSONB))) WITH ORDINALITY AS expected_item_3(value, ordinality) ON true UNION ALL SELECT 'coverage' AS anon_10, member_packets.member ->> 'member_id' AS anon_11, expected_item_4.ordinality - 1 AS anon_12, jsonb_build_array(CAST(expected_item_4.value ->> 'scope' AS TEXT), CAST(expected_item_4.value ->> 'start' AS BIGINT), CAST(expected_item_4.value ->> 'end' AS BIGINT), CAST(expected_item_4.value ->> 'complete' AS BOOLEAN)) AS jsonb_build_array_4 
FROM member_packets JOIN LATERAL jsonb_array_elements(coalesce(member_packets.member['coverage'], CAST('[]' AS JSONB))) WITH ORDINALITY AS expected_item_4(value, ordinality) ON true UNION ALL SELECT 'choice' AS anon_13, member_packets.member ->> 'member_id' AS anon_14, expected_item_5.ordinality - 1 AS anon_15, jsonb_build_array(CAST(expected_item_5.value ->> 'choice_group' AS TEXT), CAST(expected_item_5.value ->> 'alternative' AS TEXT), CAST(expected_item_5.value ->> 'selected' AS BOOLEAN)) AS jsonb_build_array_5 
FROM member_packets JOIN LATERAL jsonb_array_elements(coalesce(member_packets.member['choices'], CAST('[]' AS JSONB))) WITH ORDINALITY AS expected_item_5(value, ordinality) ON true), 
actual AS 
(SELECT 'member' AS family, kb.data_product_member.member_id AS member_id, -1 AS ordinal, jsonb_build_array(kb.data_product_member.kind_contract, kb.data_product_member.subject, kb.data_product_member.subject_definition, kb.data_product_member.original_source, kb.data_product_member.analyzed_scope, kb.data_product_member.body) AS value 
FROM kb.data_product_member 
WHERE kb.data_product_member.product_id = key UNION ALL SELECT 'coordinate' AS anon_16, kb.data_member_coordinate.member_id AS member_id, kb.data_member_coordinate.ordinal AS ordinal, jsonb_build_array(kb.data_member_coordinate.original_source, kb.data_member_coordinate.start, kb.data_member_coordinate."end", kb.data_member_coordinate.page) AS jsonb_build_array_6 
FROM kb.data_member_coordinate 
WHERE kb.data_member_coordinate.product_id = key UNION ALL SELECT 'role' AS anon_17, kb.data_member_role.member_id AS member_id, kb.data_member_role.ordinal AS ordinal, jsonb_build_array(kb.data_member_role.role, kb.data_member_role.position, kb.data_member_role.multiplicity) AS jsonb_build_array_7 
FROM kb.data_member_role 
WHERE kb.data_member_role.product_id = key UNION ALL SELECT 'endpoint' AS anon_18, kb.data_member_endpoint.member_id AS member_id, kb.data_member_endpoint.ordinal AS ordinal, jsonb_build_array(kb.data_member_endpoint.role, kb.data_member_endpoint.endpoint_product, kb.data_member_endpoint.endpoint_member) AS jsonb_build_array_8 
FROM kb.data_member_endpoint 
WHERE kb.data_member_endpoint.product_id = key UNION ALL SELECT 'coverage' AS anon_19, kb.data_member_coverage.member_id AS member_id, kb.data_member_coverage.ordinal AS ordinal, jsonb_build_array(kb.data_member_coverage.scope, kb.data_member_coverage.start, kb.data_member_coverage."end", kb.data_member_coverage.complete) AS jsonb_build_array_9 
FROM kb.data_member_coverage 
WHERE kb.data_member_coverage.product_id = key UNION ALL SELECT 'choice' AS anon_20, kb.data_member_choice.member_id AS member_id, kb.data_member_choice.ordinal AS ordinal, jsonb_build_array(kb.data_member_choice.choice_group, kb.data_member_choice.alternative, kb.data_member_choice.selected) AS jsonb_build_array_10 
FROM kb.data_member_choice 
WHERE kb.data_member_choice.product_id = key)
 SELECT coalesce(expected.ordinal, actual.ordinal) AS coalesce_1 
FROM expected FULL OUTER JOIN actual ON expected.family = actual.family AND actual.member_id = expected.member_id AND expected.ordinal = actual.ordinal 
WHERE expected.value IS DISTINCT FROM actual.value ORDER BY coalesce(expected.member_id, actual.member_id), coalesce(expected.ordinal, actual.ordinal), coalesce(expected.family, actual.family) 
 LIMIT 1 INTO n;
 IF (found) THEN
  RAISE EXCEPTION USING MESSAGE = 'member projection identity collision at ordinal ' || CAST(n AS TEXT), ERRCODE = '23514';
 END IF;
 RETURN key;
END

