CREATE OR REPLACE FUNCTION ops.ddo_kind_access(contract text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 universe text;
BEGIN
 SELECT sem.data_kind_contract.universe 
FROM sem.data_kind_contract 
