DECLARE
 atom jsonb;
 original jsonb;
 piece jsonb;
 selector jsonb;
 cell jsonb;
 retained_cell jsonb;
 table_data jsonb;
 cells jsonb;
 coordinate jsonb;
 name text;
 pointers text[] := ARRAY[]::TEXT[];
 atoms jsonb := CAST('[]' AS JSONB);
 ancestors jsonb := CAST('[]' AS JSONB);
 all_atoms jsonb := CAST('[]' AS JSONB);
 pieces jsonb := CAST('[]' AS JSONB);
 recognition jsonb := CAST('[]' AS JSONB);
 selected jsonb := CAST('[]' AS JSONB);
 projection text;
 text_value text := p_projection ->> 'text';
 previous bigint := 0;
BEGIN
 IF (nullif(p_document, '') IS NULL OR nullif(p_section, '') IS NULL OR (p_membership NOT IN ('direct', 'descendants')) OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_typeof(p_selectors) IS DISTINCT FROM 'array' OR jsonb_array_length(p_selectors) = 0 OR jsonb_typeof(p_projection['items']) IS DISTINCT FROM 'array' OR jsonb_typeof(p_projection['ancestors']) IS DISTINCT FROM 'array' OR jsonb_typeof(p_projection['text']) IS DISTINCT FROM 'string' OR jsonb_typeof(p_projection['pieces']) IS DISTINCT FROM 'array') THEN
  RAISE EXCEPTION USING MESSAGE = 'original source projection/request has invalid declared shape', ERRCODE = '23514';
 END IF;
 FOR original IN SELECT original_items.value 
FROM jsonb_array_elements(p_items) AS original_items(value) LOOP
  atom := CAST('{}' AS JSONB);
  FOR name IN SELECT unnest(ARRAY['self_ref', 'label', 'text', 'orig', 'name', 'level', 'content_layer', 'marker', 'enumerated']) AS unnest_1 LOOP
   IF (original ? name) THEN
    atom := atom || jsonb_build_object(name, original[name]);
   END IF;
  END LOOP;
  IF (jsonb_typeof(original['parent']['$ref']) = 'string') THEN
   atom := atom || jsonb_build_object('parent', original['parent']['$ref']);
  END IF;
  FOR name IN SELECT unnest(ARRAY['children', 'captions', 'footnotes', 'references']) AS unnest_1 LOOP
   IF (original ? name) THEN
    atom := atom || jsonb_build_object(name, (SELECT coalesce(jsonb_agg(refs.value['$ref'] ORDER BY refs.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(original[name]) WITH ORDINALITY AS refs(value, ordinal)));
   END IF;
  END LOOP;
  IF (original['data'] ? 'table_cells') THEN
   table_data := CAST('{}' AS JSONB);
   cells := CAST('[]' AS JSONB);
   FOR name IN SELECT unnest(ARRAY['num_rows', 'num_cols', 'orientation']) AS unnest_1 LOOP
    IF (original['data'] ? name) THEN
     table_data := table_data || jsonb_build_object(name, original['data'][name]);
    END IF;
   END LOOP;
   FOR cell IN SELECT table_cells.value 
FROM jsonb_array_elements(original['data']['table_cells']) AS table_cells(value) LOOP
    retained_cell := CAST('{}' AS JSONB);
    FOR name IN SELECT unnest(ARRAY['text', 'row_span', 'col_span', 'start_row_offset_idx', 'end_row_offset_idx', 'start_col_offset_idx', 'end_col_offset_idx', 'column_header', 'row_header', 'row_section', 'fillable']) AS unnest_1 LOOP
     IF (cell ? name) THEN
      retained_cell := retained_cell || jsonb_build_object(name, cell[name]);
     END IF;
    END LOOP;
    IF (((cell['ref']) ->> '$ref') IS NOT NULL) THEN
     retained_cell := retained_cell || jsonb_build_object('ref', cell['ref']['$ref']);
    END IF;
    cells := cells || jsonb_build_array(retained_cell);
   END LOOP;
   atom := atom || jsonb_build_object('data', table_data || jsonb_build_object('table_cells', cells));
  END IF;
  atom := atom || jsonb_build_object('prov', (SELECT coalesce(jsonb_agg(jsonb_build_object('page_no', provenance.value['page_no']) ORDER BY provenance.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(coalesce(original['prov'], CAST('[]' AS JSONB))) WITH ORDINALITY AS provenance(value, ordinal) 
WHERE (provenance.value ? 'page_no')));
  IF (nullif((atom ->> 'self_ref'), '') IS NULL OR (atom ->> 'self_ref') = ANY (pointers)) THEN
   RAISE EXCEPTION USING MESSAGE = 'original source repeats or lacks an atom address', ERRCODE = 'P0001';
  END IF;
  pointers := array_append(pointers, atom ->> 'self_ref');
  atoms := atoms || jsonb_build_array(atom);
 END LOOP;
 all_atoms := atoms;
 SELECT coalesce(jsonb_agg(original_atoms.value ORDER BY requested_items.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements_text(p_projection['items']) WITH ORDINALITY AS requested_items(value, ordinal) JOIN jsonb_array_elements(all_atoms) AS original_atoms(value) ON (original_atoms.value ->> 'self_ref') = requested_items.value INTO atoms;
 SELECT coalesce(jsonb_agg(original_atoms.value ORDER BY requested_ancestors.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements_text(p_projection['ancestors']) WITH ORDINALITY AS requested_ancestors(value, ordinal) JOIN jsonb_array_elements(all_atoms) AS original_atoms(value) ON (original_atoms.value ->> 'self_ref') = requested_ancestors.value INTO ancestors;
 IF (jsonb_array_length(atoms) != jsonb_array_length(p_projection['items']) OR jsonb_array_length(ancestors) != jsonb_array_length(p_projection['ancestors'])) THEN
  RAISE EXCEPTION USING MESSAGE = 'original source selected/ancestor atom inventory is absent or ambiguous', ERRCODE = 'P0001';
 END IF;
 pointers := (SELECT coalesce(array_agg(selected_atoms.value ->> 'self_ref'), ARRAY[]::TEXT[]) AS coalesce_1 
FROM jsonb_array_elements(atoms) AS selected_atoms(value));
 FOR original IN SELECT source_pieces.value 
FROM jsonb_array_elements(p_projection['pieces']) AS source_pieces(value) LOOP
  piece := CAST('{}' AS JSONB);
  FOR name IN SELECT unnest(ARRAY['kind', 'start', 'end', 'item_ref', 'source_field', 'cell_index']) AS unnest_1 LOOP
   IF (original ? name) THEN
    piece := piece || jsonb_build_object(name, original[name]);
   END IF;
  END LOOP;
  IF (((piece ->> 'start') !~ '^(0|[1-9][0-9]*)$') OR ((piece ->> 'end') !~ '^[1-9][0-9]*$') OR CAST((piece ->> 'start') AS BIGINT) != previous OR CAST((piece ->> 'end') AS BIGINT) <= previous OR CAST((piece ->> 'end') AS BIGINT) > char_length(text_value) OR ((piece ->> 'kind') NOT IN ('native_text', 'synthetic_separator')) OR (piece ->> 'kind') = 'native_text' AND (NOT coalesce((piece ->> 'item_ref') = ANY (pointers), false) OR nullif((piece ->> 'source_field'), '') IS NULL)) THEN
   RAISE EXCEPTION USING MESSAGE = 'original source pieces do not partition the actual projection', ERRCODE = '23514';
  END IF;
  previous := CAST(piece ->> 'end' AS BIGINT);
  pieces := pieces || jsonb_build_array(piece);
 END LOOP;
 IF (previous != char_length(text_value)) THEN
  RAISE EXCEPTION USING MESSAGE = 'original source pieces omit actual projected text', ERRCODE = 'P0001';
 END IF;
 FOR original IN SELECT formula_outcomes.value 
FROM jsonb_array_elements(coalesce(p_projection['health']['formula_outcomes'], CAST('[]' AS JSONB))) AS formula_outcomes(value) LOOP
  IF (NOT coalesce((original ->> 'pointer') = ANY (pointers), false) OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(recognition) AS recorded_recognition(value) 
WHERE (recorded_recognition.value ->> 'pointer') = (original ->> 'pointer')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'original recognition differs from unique source atom inventory', ERRCODE = 'P0001';
  END IF;
  recognition := recognition || jsonb_build_array(jsonb_build_object('pointer', original['pointer'], 'outcome', original['outcome']));
 END LOOP;
 projection := ops.ddo_digest(jsonb_build_object('text', text_value, 'pieces', pieces, 'items', atoms, 'ancestors', ancestors, 'recognition', recognition));
 coordinate := jsonb_build_object('document', p_document, 'document_subject', 'original-document:' || ops.ddo_digest(jsonb_build_object('document', p_document)), 'section_pointer', p_section, 'membership', p_membership, 'projection', projection);
 FOR selector IN SELECT requested_selectors.value 
FROM jsonb_array_elements(p_selectors) AS requested_selectors(value) LOOP
  PERFORM ops.ddo_fields(selector, ARRAY['projection'], ARRAY['native_pointer', 'page', 'start', 'end']);
  IF ((selector ->> 'projection') IS DISTINCT FROM p_projection_digest OR (selector ? 'native_pointer') AND (jsonb_typeof(selector['native_pointer']) IS DISTINCT FROM 'string' OR NOT (EXISTS (WITH RECURSIVE ancestry(pointer, parent, path) AS 
(SELECT (ancestry_atoms.value ->> 'self_ref') AS pointer, (ancestry_atoms.value ->> 'parent') AS parent, ARRAY[(ancestry_atoms.value ->> 'self_ref')] AS path 
FROM jsonb_array_elements(atoms) AS ancestry_atoms(value) UNION ALL SELECT (original_atoms.value ->> 'self_ref') AS anon_1, (original_atoms.value ->> 'parent') AS anon_2, array_append(ancestry.path, (original_atoms.value ->> 'self_ref')) AS array_append_1 
FROM ancestry JOIN jsonb_array_elements(all_atoms) AS original_atoms(value) ON (original_atoms.value ->> 'self_ref') = ancestry.parent 
WHERE NOT ((original_atoms.value ->> 'self_ref') = ANY (ancestry.path)))
 SELECT 1 
FROM ancestry 
WHERE ancestry.pointer = (selector ->> 'native_pointer'))))) THEN
   RAISE EXCEPTION USING MESSAGE = 'original source selector differs from actual source projection/atom', ERRCODE = 'P0001';
  END IF;
  FOR name IN SELECT unnest(ARRAY['page', 'start', 'end']) AS unnest_1 LOOP
   IF ((selector ? name) AND (jsonb_typeof(selector[name]) IS DISTINCT FROM 'number' OR ((selector ->> name) !~ '^(0|[1-9][0-9]*)$'))) THEN
    RAISE EXCEPTION USING MESSAGE = 'original source selector requires exact integer bounds', ERRCODE = 'P0001';
   END IF;
  END LOOP;
  IF ((selector ? 'page') AND CAST((selector ->> 'page') AS BIGINT) < 1 OR coalesce(CAST((selector ->> 'start') AS BIGINT), 0) > coalesce(CAST((selector ->> 'end') AS BIGINT), char_length(text_value)) OR coalesce(CAST((selector ->> 'end') AS BIGINT), char_length(text_value)) > char_length(text_value)) THEN
   RAISE EXCEPTION USING MESSAGE = 'original source selector exceeds original coordinate bounds', ERRCODE = 'P0001';
  END IF;
  selected := selected || jsonb_build_array(jsonb_set(selector, ARRAY['projection'], to_jsonb(projection)));
 END LOOP;
 RETURN jsonb_build_object('source', coordinate, 'text', text_value, 'pieces', pieces, 'items', atoms, 'ancestors', ancestors, 'recognition', recognition, 'selectors', selected);
END

