DECLARE
 question jsonb;
 specification jsonb;
 selected jsonb;
BEGIN
 IF (NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id AND sem.data_operation_definition.validity_families @> ARRAY['operation-event']))) THEN
  RETURN;
 END IF;
 IF ((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'question'))) THEN
  question := (ops.ddo_record_grade_input(r, 'question'))['body'];
  FOR selected IN SELECT question['original_selection'] AS anon_1 UNION SELECT question['prediction_selection'] AS anon_2 LOOP
   IF ((selected ->> 'project_id') IS DISTINCT FROM r.project_id) THEN
    RAISE EXCEPTION USING MESSAGE = 'event frame cut belongs to another project', ERRCODE = '23514';
   END IF;
   RETURN QUERY SELECT grade_scope.scope 
FROM ops.ddo_record_grade_cut_scopes(r.project_id, selected ->> 'cut_canonical_json') AS grade_scope(scope);
  END LOOP;
 ELSE
  IF ((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'specification'))) THEN
   specification := (ops.ddo_record_grade_input(r, 'specification'))['body'];
   selected := specification['frame']['selection'];
   RETURN QUERY SELECT fit_scope.scope 
FROM ops.ddo_record_fit_cut_scopes(r.project_id, selected) AS fit_scope(scope);
  END IF;
 END IF;
END

