DECLARE
 r ops.data_request%ROWTYPE;
 producing ops.data_derivation%ROWTYPE;
 intent ops.data_completion_intent%ROWTYPE;
 selected jsonb;
 boundary ops.data_demand_read%ROWTYPE;
BEGIN
 BEGIN
  SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = episode INTO STRICT producing;
  SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = producing.request_id INTO STRICT r;
  IF (NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id AND sem.data_operation_definition.validity_families @> ARRAY['operation-event']))) THEN
   RETURN true;
  END IF;
  IF (producing.outcome IS DISTINCT FROM 'success') THEN
   RETURN false;
  END IF;
  SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = producing.intent_id AND ops.data_completion_intent.request_id = producing.request_id AND ops.data_completion_intent.generation = producing.generation INTO STRICT intent;
  r := ops.ddo_require_episode_operation_event_correspondence(producing, intent);
  IF ((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'question'))) THEN
   FOR selected IN SELECT (ops.ddo_record_grade_input(r, 'question'))['body']['original_selection'] AS anon_1 UNION SELECT (ops.ddo_record_grade_input(r, 'question'))['body']['prediction_selection'] AS anon_2 LOOP
    PERFORM ops.ddo_record_grade_require_cut_material(r.project_id, selected ->> 'cut_canonical_json', selected ->> 'cut_id');
   END LOOP;
  ELSE
   IF ((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'specification'))) THEN
    selected := (ops.ddo_record_grade_input(r, 'specification'))['body']['frame']['selection'];
    PERFORM ops.ddo_record_fit_cut_scopes(r.project_id, selected);
    SELECT ops.data_demand_read.* 
FROM ops.data_demand_read 
WHERE ops.data_demand_read.id = (selected ->> 'read_id') AND ops.data_demand_read.demand_id = (selected ->> 'demand_id') INTO STRICT boundary;
    PERFORM ops.ddo_require_read_epochs(boundary, r.project_id, true);
   END IF;
  END IF;
  RETURN true;
 EXCEPTION WHEN data_exception OR integrity_constraint_violation OR no_data_found OR too_many_rows THEN
  RETURN false;
 END;
END

