  RAISE EXCEPTION USING MESSAGE = 'event dependency scopes differ from original producer fences', ERRCODE = '23514';
 END IF;
 r.release_id := producing.release_id;
 r.runtime_id := producing.runtime_id;
 r.recipe := producing.recipe;
 r.generation := producing.generation;
 r.binding := r.binding || jsonb_build_object('inputs', intent.payload['inputs'], 'support', intent.payload['support']);
 RETURN QUERY SELECT event_scope.scope 
FROM ops.ddo_operation_event_completion_scopes(r) AS event_scope(scope);
END

