DECLARE
 specification jsonb := (ops.ddo_record_grade_input(r, 'specification'))['body'];
 selected jsonb := specification['frame'];
 selection_ jsonb := selected['selection'];
 d ops.data_demand%ROWTYPE;
 boundary ops.data_demand_read%ROWTYPE;
 p jsonb;
 p_use text := selected ->> 'use_id';
 p_product text := (selected['reference']) ->> 'product_id';
 p_derivation text := selected ->> 'derivation_id';
 admitted boolean;
 chosen jsonb;
 producer ops.data_derivation%ROWTYPE;
 frame_request ops.data_request%ROWTYPE;
 intent ops.data_completion_intent%ROWTYPE;
 actual kb.data_product%ROWTYPE;
 definition sem.data_operation_definition%ROWTYPE;
BEGIN
 IF ((selection_ ->> 'project_id') IS DISTINCT FROM r.project_id OR ((selected['reference']) ->> 'member_id') IS NOT NULL OR (selection_ ->> 'cut_id') IS DISTINCT FROM ('cut-selection:' || encode(sha256(convert_to((selection_ ->> 'cut_canonical_json'), 'UTF8')), 'hex'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'event fit changes exact selected frame project/cut', ERRCODE = '23514';
 END IF;
 PERFORM ops.ddo_record_fit_cut_scopes(r.project_id, selection_);
 SELECT ops.data_demand.* 
FROM ops.data_demand 
WHERE ops.data_demand.id = (selection_ ->> 'demand_id') AND ops.data_demand.project_id = r.project_id INTO STRICT d;
 SELECT ops.data_demand_read.* 
FROM ops.data_demand_read 
WHERE ops.data_demand_read.id = (selection_ ->> 'read_id') AND ops.data_demand_read.demand_id = d.id INTO STRICT boundary;
 PERFORM ops.ddo_require_read_epochs(boundary, r.project_id, true);
 p := jsonb_build_object('scope', boundary.scope);
 WITH RECURSIVE scoped_obligations AS 
(SELECT ops.data_obligation.id AS id, ops.data_obligation.demand_id AS demand_id, ops.data_obligation.operation_id AS operation_id, ops.data_obligation.subject AS subject, ops.data_obligation.original_source AS original_source, ops.data_obligation.analyzed_scope AS analyzed_scope, ops.data_obligation.parameters AS parameters, ops.data_obligation.created_at AS created_at, ops.data_obligation.created_xid AS created_xid 
FROM ops.data_obligation 
WHERE ops.data_obligation.demand_id = d.id AND (NOT (coalesce(p['scope'], CAST('{}' AS JSONB)) ? 'operation_id') OR ops.data_obligation.operation_id IS NOT DISTINCT FROM (coalesce(p['scope'], CAST('{}' AS JSONB)) ->> 'operation_id')) AND (NOT (coalesce(p['scope'], CAST('{}' AS JSONB)) ? 'subject') OR ops.data_obligation.subject IS NOT DISTINCT FROM (coalesce(p['scope'], CAST('{}' AS JSONB)) ->> 'subject')) AND (NOT (coalesce(p['scope'], CAST('{}' AS JSONB)) ? 'original_source') OR ops.data_obligation.original_source IS NOT DISTINCT FROM (coalesce(p['scope'], CAST('{}' AS JSONB)) ->> 'original_source')) AND (NOT (coalesce(p['scope'], CAST('{}' AS JSONB)) ? 'product_ids') OR (EXISTS (SELECT 1 
FROM ops.demand_use AS scope_use JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = scope_use.derivation_id JOIN jsonb_array_elements_text((coalesce(p['scope'], CAST('{}' AS JSONB)))['product_ids']) AS scope_product(value) ON ops.data_derivation_output.product_id = scope_product.value 
WHERE scope_use.obligation_id = ops.data_obligation.id AND ops.ddo_read_visible(scope_use.created_at, scope_use.created_xid, boundary) AND NOT (EXISTS (SELECT 1 
FROM ops.demand_use AS scope_later_use 
WHERE scope_later_use.obligation_id = scope_use.obligation_id AND ops.ddo_read_visible(scope_later_use.created_at, scope_later_use.created_xid, boundary) AND (scope_later_use.created_at > scope_use.created_at OR scope_later_use.created_at = scope_use.created_at AND scope_later_use.id > scope_use.id))))) OR (EXISTS (SELECT 1 
FROM ops.original_source_admission AS scope_original JOIN jsonb_array_elements_text((coalesce(p['scope'], CAST('{}' AS JSONB)))['product_ids']) AS scope_product(value) ON scope_original.product_id = scope_product.value 
WHERE scope_original.demand_id = d.id AND scope_original.project_id = d.project_id AND scope_original.subject = ops.data_obligation.subject AND scope_original.original_source IS NOT DISTINCT FROM ops.data_obligation.original_source AND scope_original.analyzed_scope = ops.data_obligation.analyzed_scope AND ops.ddo_read_visible(scope_original.created_at, scope_original.created_xid, boundary)))) AND ops.ddo_read_visible(ops.data_obligation.created_at, ops.data_obligation.created_xid, boundary)), 
selected_uses AS 
(SELECT latest.id AS id, latest.demand_id AS demand_id, latest.obligation_id AS obligation_id, latest.fate AS fate, latest.request_id AS request_id, latest.generation AS generation, latest.derivation_id AS derivation_id, latest.selection AS selection, latest.trust_snapshot AS trust_snapshot, latest.created_at AS created_at, latest.created_xid AS created_xid 
FROM scoped_obligations JOIN LATERAL (SELECT ops.demand_use.id AS id, ops.demand_use.demand_id AS demand_id, ops.demand_use.obligation_id AS obligation_id, ops.demand_use.fate AS fate, ops.demand_use.request_id AS request_id, ops.demand_use.generation AS generation, ops.demand_use.derivation_id AS derivation_id, ops.demand_use.selection AS selection, ops.demand_use.trust_snapshot AS trust_snapshot, ops.demand_use.created_at AS created_at, ops.demand_use.created_xid AS created_xid 
FROM ops.demand_use 
WHERE ops.demand_use.obligation_id = scoped_obligations.id AND ops.ddo_read_visible(ops.demand_use.created_at, ops.demand_use.created_xid, boundary) ORDER BY ops.demand_use.created_at DESC, ops.demand_use.id DESC 
 LIMIT 1) AS latest ON true), 
selected_output_validity AS MATERIALIZED 
(SELECT selected_output_validity_rows.kind AS kind, selected_output_validity_rows.id AS id, selected_output_validity_rows.valid AS valid 
FROM ops.ddo_valid_closure((SELECT array_agg(selected_uses.id) AS array_agg_1 
FROM selected_uses 
WHERE selected_uses.fate = 'fulfilled'), CAST('{}' AS TEXT[]), boundary, CAST('{}' AS TEXT[])) AS selected_output_validity_rows), 
selected_output_seed AS 
(SELECT CAST('use' AS TEXT) AS kind, CAST(selected_uses.id AS TEXT) AS id 
FROM selected_uses 
WHERE selected_uses.id = p_use AND selected_uses.fate = 'fulfilled' AND (EXISTS (SELECT 1 
FROM selected_output_validity 
WHERE selected_output_validity.kind = 'use' AND selected_uses.id = selected_output_validity.id AND selected_output_validity.valid))), 
support_closure(kind, id) AS 
(SELECT selected_output_seed.kind AS kind, selected_output_seed.id AS id 
FROM selected_output_seed 
WHERE selected_output_seed.id IS NOT NULL UNION SELECT support_edge.child_kind AS kind, support_edge.child_id AS id 
FROM support_closure JOIN LATERAL (SELECT CAST(0 AS INTEGER) AS alternative, CAST('use' AS TEXT) AS child_kind, (CAST(ops.ddo_structural_report_support(ops.demand_use.id, boundary, (coalesce(p['scope'], CAST('{}' AS JSONB)))['product_ids']) AS JSONB) ->> 'use_id') AS child_id 
FROM ops.demand_use 
WHERE support_closure.kind = 'use' AND ops.demand_use.id = support_closure.id AND boundary.public_disclosure AND ops.ddo_policy_authority_leaf(ops.demand_use.derivation_id) UNION ALL SELECT CAST(0 AS INTEGER) AS alternative, CAST(CASE WHEN (ops.data_derivation_support.admission_use_id IS NOT NULL) THEN 'use' ELSE CASE WHEN (boundary.public_disclosure AND ops.ddo_policy_authority_leaf(ops.data_derivation_support.support_derivation_id)) THEN 'authority' ELSE 'episode' END END AS TEXT) AS child_kind, coalesce(ops.data_derivation_support.admission_use_id, ops.data_derivation_support.support_derivation_id) AS child_id 
FROM ops.data_derivation_support 
WHERE support_closure.kind = 'episode' AND ops.data_derivation_support.derivation_id = support_closure.id UNION ALL SELECT CAST(0 AS INTEGER) AS alternative, CAST('original' AS TEXT) AS child_kind, ops.data_derivation_original_support.admission_id AS child_id 
FROM ops.data_derivation_original_support 
WHERE support_closure.kind = 'episode' AND ops.data_derivation_original_support.derivation_id = support_closure.id UNION ALL SELECT CAST(0 AS INTEGER) AS alternative, CAST(CASE WHEN (boundary.public_disclosure AND ops.ddo_policy_authority_leaf(ops.demand_use.derivation_id)) THEN 'authority' ELSE 'episode' END AS TEXT) AS child_kind, ops.demand_use.derivation_id AS child_id 
FROM ops.demand_use 
WHERE support_closure.kind = 'use' AND ops.demand_use.id = support_closure.id UNION ALL SELECT CAST(0 AS INTEGER) AS alternative, CAST(CASE WHEN ((ops.ddo_support_reference_node(selected_support_reference.value) ->> 'kind') = 'episode' AND boundary.public_disclosure AND ops.ddo_policy_authority_leaf((ops.ddo_support_reference_node(selected_support_reference.value) ->> 'id'))) THEN 'authority' ELSE (ops.ddo_support_reference_node(selected_support_reference.value) ->> 'kind') END AS TEXT) AS child_kind, (ops.ddo_support_reference_node(selected_support_reference.value) ->> 'id') AS child_id 
FROM ops.demand_use JOIN jsonb_array_elements(coalesce(ops.demand_use.selection['support'], CAST('[]' AS JSONB))) AS selected_support_reference(value) ON true 
WHERE support_closure.kind = 'use' AND ops.demand_use.id = support_closure.id AND NOT (boundary.public_disclosure AND ops.ddo_policy_authority_leaf(ops.demand_use.derivation_id)) UNION ALL SELECT CAST(0 AS INTEGER) AS alternative, CAST('population' AS TEXT) AS child_kind, ops.data_population.id AS child_id 
FROM ops.demand_use JOIN jsonb_array_elements(coalesce(ops.demand_use.selection['populations'], CAST('[]' AS JSONB))) AS selected_population_reference(value) ON true JOIN ops.data_population ON ops.data_population.id = (selected_population_reference.value ->> 'population_id') AND ops.data_population.demand_id = ops.demand_use.demand_id 
WHERE support_closure.kind = 'use' AND ops.demand_use.id = support_closure.id AND NOT (boundary.public_disclosure AND ops.ddo_policy_authority_leaf(ops.demand_use.derivation_id)) UNION ALL SELECT CAST(0 AS INTEGER) AS alternative, CAST('use' AS TEXT) AS child_kind, ops.demand_use.id AS child_id 
FROM ops.data_population JOIN ops.demand_use ON ops.demand_use.id = (ops.data_population.evidence ->> 'admission_use_id') AND ops.demand_use.derivation_id = (ops.data_population.evidence ->> 'derivation_id') AND ops.demand_use.demand_id = ops.data_population.demand_id 
WHERE support_closure.kind = 'population' AND ops.data_population.id = support_closure.id UNION ALL SELECT CAST(0 AS INTEGER) AS alternative, CAST('population' AS TEXT) AS child_kind, ((ops.data_population.evidence['selection']) ->> 'parent_population_id') AS child_id 
FROM ops.data_population 
WHERE support_closure.kind = 'population' AND ops.data_population.id = support_closure.id) AS support_edge ON true 
WHERE support_edge.child_id IS NOT NULL), 
selected_whole_outputs AS 
(SELECT DISTINCT ops.data_derivation.id AS derivation_id, ops.data_derivation_output.product_id AS product_id 
FROM ops.data_derivation JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id JOIN kb.data_product ON kb.data_product.id = ops.data_derivation_output.product_id 
WHERE CASE WHEN ((EXISTS (SELECT 1 
FROM support_closure 
WHERE support_closure.kind IN ('episode', 'authority') AND ops.data_derivation.id = support_closure.id)) AND true AND ops.data_derivation_output.member_id IS NULL AND kb.data_product.project_id = d.project_id AND (EXISTS (SELECT 1 
FROM selected_output_validity 
WHERE selected_output_validity.kind = 'episode' AND ops.data_derivation.id = selected_output_validity.id AND selected_output_validity.valid))) THEN (NOT boundary.public_disclosure OR (EXISTS (SELECT 1 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = kb.data_product.kind_contract AND sem.data_kind_contract.universe IN ('ordinary', 'source')))) AND NOT (EXISTS (SELECT 1 
FROM ops.ddo_body_kind_contracts(kb.data_product.kind_contract, kb.data_product.canonical_body) AS custody_body_kind(kind_contract) LEFT OUTER JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = custody_body_kind.kind_contract 
WHERE sem.data_kind_contract.kind_contract IS NULL OR NOT coalesce(boundary.access_universes ? sem.data_kind_contract.universe, false))) ELSE false END)
 SELECT EXISTS (SELECT 1 
FROM selected_whole_outputs 
WHERE selected_whole_outputs.derivation_id = p_derivation AND selected_whole_outputs.product_id = p_product) AS anon_1 INTO admitted;
 IF (NOT coalesce(admitted, false)) THEN
  RAISE EXCEPTION USING MESSAGE = 'event frame is outside exact native selected support', ERRCODE = '23514';
 END IF;
 SELECT item.value 
FROM jsonb_array_elements(r.binding['inputs']) AS item(value) 
WHERE (item.value ->> 'role') = 'frame' AND (item.value ->> 'product_id') = p_product AND (item.value ->> 'member_id') IS NULL AND CAST((item.value ->> 'multiplicity') AS INTEGER) = 1 INTO STRICT chosen;
 IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(r.binding['support']) AS support(value) 
WHERE (support.value ->> 'role') = 'frame' AND (support.value ->> 'derivation_id') = p_derivation))) THEN
  RAISE EXCEPTION USING MESSAGE = 'event fit changes exact frame producing support', ERRCODE = '23514';
 END IF;
 SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = p_derivation AND ops.data_derivation.outcome = 'success' INTO STRICT producer;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = producer.request_id AND ops.data_request.project_id = r.project_id INTO STRICT frame_request;
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = producer.intent_id AND ops.data_completion_intent.request_id = producer.request_id AND ops.data_completion_intent.generation = producer.generation INTO STRICT intent;
 IF ((intent.producer_task_id, intent.producer_attempt, intent.runtime_id) IS DISTINCT FROM (producer.producer_task_id, producer.producer_attempt, producer.runtime_id)) THEN
  RAISE EXCEPTION USING MESSAGE = 'event frame differs from original producer fences', ERRCODE = '23514';
 END IF;
 frame_request.release_id := producer.release_id;
 frame_request.runtime_id := producer.runtime_id;
 frame_request.recipe := producer.recipe;
 frame_request.generation := producer.generation;
 frame_request.binding := frame_request.binding || jsonb_build_object('inputs', intent.payload['inputs'], 'support', intent.payload['support']);
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = producer.release_id AND sem.data_operation_definition.operation_id = frame_request.operation_id INTO STRICT definition;
 SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = p_product AND kb.data_product.project_id = r.project_id INTO STRICT actual;
 IF (selected['reference'] IS DISTINCT FROM ops.ddo_structural_product_reference(actual) OR (data.ddo_json(actual.canonical_body) ->> 'frame_digest') IS DISTINCT FROM (selected ->> 'frame_digest') OR NOT (((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = definition.release_id AND sem.data_operation_definition.operation_id = definition.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'question')))) OR NOT (EXISTS (SELECT 1 
FROM ops.data_publication_receipt JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_publication_receipt.derivation_id 
WHERE ops.data_publication_receipt.derivation_id = producer.id AND ops.data_publication_receipt.intent_id = intent.id AND ops.data_derivation_output.product_id = p_product AND ops.data_derivation_output.member_id IS NULL AND ops.data_derivation_output.role = 'frame'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'event fit lacks actual selected current frame CPU/common receipt', ERRCODE = '23514';
 END IF;
 PERFORM ops.ddo_require_operation_event_completion(frame_request, intent.payload);
 IF (data.ddo_normalize(intent.payload['outputs'][0]['product']['body']) IS DISTINCT FROM actual.canonical_body) THEN
  RAISE EXCEPTION USING MESSAGE = 'event frame differs from actual original CPU completion body', ERRCODE = '23514';
 END IF;
 IF (body['specification'] IS DISTINCT FROM specification OR ((body['result']) ->> 'frame_digest') IS DISTINCT FROM (selected ->> 'frame_digest') OR body['result']['parameters'] IS NOT NULL AND body['result']['parameters'] != CAST('null' AS JSONB) AND (body['result']['parameters']['algorithm'] IS DISTINCT FROM specification['algorithm'] OR ((body['result']['parameters']) ->> 'frame_digest') IS DISTINCT FROM (selected ->> 'frame_digest'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'event fit changes actual frame identity or declared algorithm', ERRCODE = '23514';
 END IF;
END

