 admitted boolean;
 chosen jsonb;
 producer ops.data_derivation%ROWTYPE;
 frame_request ops.data_request%ROWTYPE;
 intent ops.data_completion_intent%ROWTYPE;
 actual kb.data_product%ROWTYPE;
