DECLARE
 question_product kb.data_product%ROWTYPE;
 question jsonb;
 frame jsonb := body['frame'];
 selected jsonb;
 original_census jsonb;
 prediction_census jsonb;
 report_pin jsonb;
 source_pin jsonb;
 bound jsonb;
 actual jsonb;
 report_product kb.data_product%ROWTYPE;
 producer ops.data_derivation%ROWTYPE;
 definition sem.data_operation_definition%ROWTYPE;
 cpu_roles jsonb := data.ddo_field(ops.ddo_cpu_input_basis(r), 'roles');
 role_meaning jsonb;
 u jsonb;
 reports_ jsonb := CAST('[]' AS JSONB);
 sources_ jsonb := CAST('[]' AS JSONB);
BEGIN
 SELECT kb.data_product.* 
FROM jsonb_array_elements(r.binding['inputs']) AS item(value) JOIN kb.data_product ON kb.data_product.id = (item.value ->> 'product_id') AND kb.data_product.project_id = r.project_id JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = kb.data_product.kind_contract 
WHERE (item.value ->> 'role') = 'question' AND (item.value ->> 'member_id') IS NULL AND CAST((item.value ->> 'multiplicity') AS INTEGER) = 1 AND sem.data_kind_contract.kind = 'https://corpus-structure.dev/semantic/operation-events/protected/DdoOperationEventQuestion' AND sem.data_kind_contract.universe = 'evaluator' INTO STRICT question_product;
 question := data.ddo_json(question_product.canonical_body);
 IF ((body ->> 'version') IS DISTINCT FROM 'selected-operation-event-frame-product-1' OR (body ->> 'frame_digest') IS DISTINCT FROM encode(sha256(convert_to((body ->> 'frame_canonical_json'), 'UTF8')), 'hex') OR CAST((body ->> 'frame_canonical_json') AS JSONB) IS DISTINCT FROM frame OR frame['question'] IS DISTINCT FROM question OR frame['question_reference'] IS DISTINCT FROM ops.ddo_structural_product_reference(question_product) OR (question ->> 'pass_kind') IS DISTINCT FROM 'C' OR (question ->> 'exposure') IS DISTINCT FROM 'output_first' OR ((question ->> 'partition') NOT IN ('development', 'feature_fit'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'event frame changes actual protected question or exact canonical frame', ERRCODE = '23514';
 END IF;
 FOR selected IN SELECT question['original_selection'] AS anon_1 UNION SELECT question['prediction_selection'] AS anon_2 LOOP
  IF ((selected ->> 'project_id') IS DISTINCT FROM r.project_id OR (CAST((selected ->> 'cut_canonical_json') AS JSONB) ->> 'demand_id') IS DISTINCT FROM (selected ->> 'demand_id') OR (CAST((selected ->> 'cut_canonical_json') AS JSONB) ->> 'read_id') IS DISTINCT FROM (selected ->> 'read_id') OR (CAST((selected ->> 'cut_canonical_json') AS JSONB) ->> 'release_id') IS DISTINCT FROM (selected ->> 'release_id') OR (CAST((selected ->> 'cut_canonical_json') AS JSONB) ->> 'runtime_id') IS DISTINCT FROM (selected ->> 'runtime_id')) THEN
   RAISE EXCEPTION USING MESSAGE = 'event question changes exact native cut pins', ERRCODE = '23514';
  END IF;
  PERFORM ops.ddo_record_grade_require_cut_material(r.project_id, selected ->> 'cut_canonical_json', selected ->> 'cut_id');
 END LOOP;
 original_census := ops.ddo_record_grade_acquire_census_material(r.project_id, (question['original_selection']) ->> 'cut_canonical_json', (question['original_selection']) ->> 'cut_id');
 prediction_census := ops.ddo_record_grade_acquire_census_material(r.project_id, (question['prediction_selection']) ->> 'cut_canonical_json', (question['prediction_selection']) ->> 'cut_id');
 FOR selected IN SELECT judgment.value['selection'] AS anon_1 
FROM jsonb_array_elements(question['judgments']) AS judgment(value) LOOP
  report_pin := selected['report'];
  source_pin := selected['source'];
  IF ((selected ->> 'origin_group') IS DISTINCT FROM (source_pin ->> 'original_source')) THEN
   RAISE EXCEPTION USING MESSAGE = 'event origin group differs from actual original source', ERRCODE = '23514';
  END IF;
  IF (NOT (reports_ ? (report_pin ->> 'product_id'))) THEN
   reports_ := reports_ || jsonb_build_array((report_pin ->> 'product_id'));
  END IF;
  IF (NOT (sources_ @> jsonb_build_array(jsonb_build_array((source_pin ->> 'source_product'), (source_pin ->> 'source_member'))))) THEN
   sources_ := sources_ || jsonb_build_array(jsonb_build_array((source_pin ->> 'source_product'), (source_pin ->> 'source_member')));
  END IF;
  SELECT item.value 
FROM jsonb_array_elements(r.binding['inputs']) AS item(value) 
WHERE (item.value ->> 'role') = 'reports' AND (item.value ->> 'product_id') = (report_pin ->> 'product_id') AND (item.value ->> 'member_id') IS NULL AND CAST((item.value ->> 'multiplicity') AS INTEGER) = 1 INTO STRICT bound;
  SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = (report_pin ->> 'product_id') AND kb.data_product.project_id = r.project_id INTO STRICT report_product;
  IF (report_pin IS DISTINCT FROM ops.ddo_structural_product_reference(report_product) OR NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(prediction_census['outputs']) AS prediction_output(value) 
WHERE (prediction_output.value ->> 'product_id') = report_product.id AND (prediction_output.value ->> 'derivation_id') = (selected ->> 'derivation_id'))) OR NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(r.binding['support']) AS support(value) 
WHERE (support.value ->> 'role') = 'reports' AND (support.value ->> 'derivation_id') = (selected ->> 'derivation_id')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'event report changes actual selected whole context/producer support', ERRCODE = '23514';
  END IF;
  u := prediction_census['uses'][(selected ->> 'use_id')];
  IF (u IS NULL OR (u ->> 'derivation_id') IS DISTINCT FROM (selected ->> 'derivation_id') OR (u ->> 'completion_state') IS DISTINCT FROM 'success' OR ((u ->> 'fate') NOT IN ('fulfilled', 'attached'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'event report lacks its exact successful selected native use', ERRCODE = '23514';
  END IF;
  SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = (selected ->> 'derivation_id') AND ops.data_derivation.outcome = 'success' INTO STRICT producer;
  SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition JOIN ops.data_request ON ops.data_request.operation_id = sem.data_operation_definition.operation_id 
WHERE ops.data_request.id = producer.request_id AND ops.data_request.project_id = r.project_id AND sem.data_operation_definition.release_id = producer.release_id INTO STRICT definition;
  IF (definition.operation_id IS DISTINCT FROM (selected ->> 'producer_operation') OR definition.implementation_revision IS DISTINCT FROM (selected ->> 'producer_revision') OR producer.release_id IS DISTINCT FROM ((question['prediction_selection']) ->> 'release_id')) THEN
   RAISE EXCEPTION USING MESSAGE = 'event report changes its actual admitted producer revision/release', ERRCODE = '23514';
  END IF;
  SELECT cpu_role.value 
FROM jsonb_array_elements(cpu_roles[1]) AS cpu_role(value) 
WHERE (data.ddo_json(cpu_role.value) ->> 'role') = 'reports' AND (data.ddo_json(cpu_role.value) ->> 'product_id') = report_product.id INTO STRICT role_meaning;
  PERFORM ops.ddo_definition_component_basis(role_meaning);
  IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements((data.ddo_json(report_product.canonical_body))['definition_components']['components']) AS component(value) 
WHERE (component.value ->> 'component_id') = (selected ->> 'component_id')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'event component is absent from its actual whole report', ERRCODE = '23514';
  END IF;
  SELECT item.value 
FROM jsonb_array_elements(r.binding['inputs']) AS item(value) 
WHERE (item.value ->> 'role') = 'sources' AND (item.value ->> 'product_id') = (source_pin ->> 'source_product') AND (item.value ->> 'member_id') IS NOT DISTINCT FROM (source_pin ->> 'source_member') AND CAST((item.value ->> 'multiplicity') AS INTEGER) = 1 INTO STRICT bound;
  IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(original_census['outputs']) AS original_output(value) 
WHERE (original_output.value ->> 'product_id') = (source_pin ->> 'source_product')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'event original source is outside exact original selected support', ERRCODE = '23514';
  END IF;
  actual := ops.ddo_record_grade_input_value(r.project_id, bound ->> 'product_id', bound ->> 'member_id');
  IF (((actual - 'body') - 'analyzed_scope_meaning') IS DISTINCT FROM jsonb_build_object('product_id', (source_pin ->> 'source_product'), 'member_id', (source_pin ->> 'source_member'), 'project_id', (source_pin ->> 'project_id'), 'kind_contract', (source_pin ->> 'kind_contract'), 'subject', (source_pin ->> 'subject'), 'subject_definition', (source_pin ->> 'subject_definition'), 'original_source', (source_pin ->> 'original_source')) OR actual['analyzed_scope_meaning'] IS DISTINCT FROM CAST((source_pin ->> 'analyzed_scope_meaning') AS JSONB) OR ((actual['body']['source']) ->> 'document') IS DISTINCT FROM (source_pin ->> 'document') OR ((actual['body']['source']) ->> 'projection') IS DISTINCT FROM (source_pin ->> 'projection_digest') OR ((actual['body']['source']) ->> 'section_pointer') IS DISTINCT FROM (source_pin ->> 'section_pointer') OR ((actual['body']['source']) ->> 'membership') IS DISTINCT FROM (source_pin ->> 'membership')) THEN
   RAISE EXCEPTION USING MESSAGE = 'event source pin changes exact selected coordinate/context', ERRCODE = '23514';
  END IF;
 END LOOP;
 IF ((SELECT count(*) AS count_1 
FROM jsonb_array_elements(r.binding['inputs']) AS item(value) 
WHERE (item.value ->> 'role') = 'reports') != jsonb_array_length(reports_) OR (SELECT count(*) AS count_2 
FROM jsonb_array_elements(r.binding['inputs']) AS item(value) 
WHERE (item.value ->> 'role') = 'sources') != jsonb_array_length(sources_)) THEN
  RAISE EXCEPTION USING MESSAGE = 'event frame changes the exact declared report/source population', ERRCODE = '23514';
 END IF;
END

