DECLARE
 document kb.document%ROWTYPE;
 original bytea;
 body jsonb;
 coordinate jsonb;
BEGIN
 PERFORM ops.ddo_fields(p_reference, ARRAY['kind', 'project_id', 'document_key', 'content_hash', 'mime']);
 IF ((p_reference ->> 'kind') IS DISTINCT FROM 'original-document') THEN
  RAISE EXCEPTION USING MESSAGE = 'original document reference discriminator differs', ERRCODE = 'P0001';
 END IF;
 SELECT kb.document.id, kb.document.project_id, kb.document.key, kb.document.source_uri, kb.document.content_hash, kb.document.original_path, kb.document.mime, kb.document.title, kb.document.meta 
FROM kb.document 
WHERE kb.document.project_id = (p_reference ->> 'project_id') AND kb.document.key = (p_reference ->> 'document_key') AND kb.document.content_hash = (p_reference ->> 'content_hash') AND kb.document.mime = (p_reference ->> 'mime') INTO STRICT document;
 SELECT kb.source_artifact.content 
FROM kb.source_artifact 
WHERE kb.source_artifact.artifact_digest = document.content_hash INTO STRICT original;
 IF (encode(sha256(original), 'hex') IS DISTINCT FROM document.content_hash) THEN
  RAISE EXCEPTION USING MESSAGE = 'original document retained byte digest differs', ERRCODE = 'P0001';
 END IF;
 body := jsonb_build_object('document', document.key, 'content_hash', document.content_hash, 'mime', document.mime);
 coordinate := jsonb_build_object('document', document.key);
 RETURN jsonb_build_object('body', body, 'meaning_body', data.ddo_normalize(data.record_json_meaning(body)), 'subject_definition', 'original-document', 'subject', 'original-document:' || ops.ddo_digest(coordinate), 'original_source', document.key, 'analyzed_scope', jsonb_build_object('document', document.key, 'scope', 'whole-document'), 'evidence', jsonb_build_object('reference', p_reference, 'document_id', document.id, 'document_content_hash', document.content_hash, 'source_uri', document.source_uri, 'original_path', document.original_path));
END

