DECLARE
 producer ops.data_request%ROWTYPE;
 derivation ops.data_derivation%ROWTYPE;
 intent ops.data_completion_intent%ROWTYPE;
 product kb.data_product%ROWTYPE;
 receipts jsonb;
 receipt jsonb;
 expected jsonb;
BEGIN
 IF (NOT ops.ddo_node_valid('episode', p_derivation, p_read)) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF derivation support is not admitted at selected read', ERRCODE = '23514';
 END IF;
 SELECT ops.data_derivation.id, ops.data_derivation.request_id, ops.data_derivation.generation, ops.data_derivation.intent_id, ops.data_derivation.release_id, ops.data_derivation.recipe, ops.data_derivation.runtime_id, ops.data_derivation.producer_task_id, ops.data_derivation.producer_attempt, ops.data_derivation.outcome, ops.data_derivation.completed_at 
FROM ops.data_derivation JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id 
WHERE ops.data_derivation.id = p_derivation AND ops.data_derivation_output.product_id = p_product AND ops.data_derivation_output.member_id IS NULL INTO STRICT derivation;
 producer := ops.ddo_pdf_producing_request(derivation.id);
 IF (producer.project_id IS DISTINCT FROM p_project OR p_source IS NOT NULL AND producer.original_source IS DISTINCT FROM p_source) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF producer is outside exact qualified selected source', ERRCODE = '23514';
 END IF;
 PERFORM ops.ddo_authorize_request(producer);
 IF (NOT (EXISTS (SELECT sem.data_operation_definition.operation_id 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = derivation.release_id AND sem.data_operation_definition.operation_id = producer.operation_id AND coalesce(sem.data_operation_definition.command_class = 'pdf', false)))) THEN
  RAISE EXCEPTION USING MESSAGE = 'selected source derivation is not an exact approved native PDF command', ERRCODE = '23514';
 END IF;
 PERFORM ops.require_pdf_operation(producer.release_id, 'read_native_source');
 SELECT ops.data_completion_intent.id, ops.data_completion_intent.request_id, ops.data_completion_intent.generation, ops.data_completion_intent.producer_task_id, ops.data_completion_intent.producer_attempt, ops.data_completion_intent.producer_holder, ops.data_completion_intent.runtime_id, ops.data_completion_intent.payload, ops.data_completion_intent.payload_digest, ops.data_completion_intent.created_at, ops.data_completion_intent.validation_seal 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = derivation.intent_id INTO STRICT intent;
 SELECT kb.data_product.id, kb.data_product.kind_contract, kb.data_product.project_id, kb.data_product.subject, kb.data_product.subject_definition, kb.data_product.original_source, kb.data_product.analyzed_scope, kb.data_product.canonical_body, kb.data_product.body_digest, kb.data_product.artifact_digest 
FROM kb.data_product 
WHERE kb.data_product.id = p_product AND kb.data_product.project_id = p_project AND kb.data_product.original_source = producer.original_source INTO STRICT product;
 receipts := intent.payload['execution_evidence']['pdf_receipts'];
 IF (jsonb_typeof(receipts) IS DISTINCT FROM 'array' OR jsonb_array_length(receipts) != 1) THEN
  RAISE EXCEPTION USING MESSAGE = 'selected PDF capture lacks one retained sealed publication', ERRCODE = '23514';
 END IF;
 receipt := receipts[0];
 expected := ops.pdf_publication_projection(receipt, intent.producer_task_id, intent.producer_attempt, intent.producer_holder);
 IF (data.ddo_json(product.canonical_body) IS DISTINCT FROM expected OR (expected ->> 'document') IS DISTINCT FROM producer.original_source) THEN
  RAISE EXCEPTION USING MESSAGE = 'selected PDF capture body differs from actual sealed publication', ERRCODE = '23514';
 END IF;
 RETURN receipt;
END

