 END IF;
 receipt := ops.ddo_pdf_observation_derivation_receipt(p_project, p_product, p_derivation, consumer.original_source);
 SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = p_derivation INTO STRICT derivation;
 producer := ops.ddo_pdf_producing_request(derivation.id);
 SELECT producer_inputs.value 
FROM jsonb_array_elements(producer.binding['inputs']) AS producer_inputs(value) 
WHERE (producer_inputs.value ->> 'role') = 'capture' INTO STRICT raw_capture;
