DECLARE
 episode ops.data_derivation%ROWTYPE;
 intent ops.data_completion_intent%ROWTYPE;
 request ops.data_request%ROWTYPE;
 publication ops.data_publication_receipt%ROWTYPE;
 job ops.task%ROWTYPE;
 definition sem.data_operation_definition%ROWTYPE;
 profile text;
 captured record;
 binding jsonb;
 candidate jsonb;
BEGIN
 SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = p_derivation AND ops.data_derivation.outcome = 'success' INTO STRICT episode;
 SELECT ops.data_publication_receipt.* 
FROM ops.data_publication_receipt 
WHERE ops.data_publication_receipt.intent_id = episode.intent_id AND ops.data_publication_receipt.derivation_id = episode.id INTO STRICT publication;
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = publication.intent_id AND ops.data_completion_intent.request_id = episode.request_id AND ops.data_completion_intent.generation = episode.generation INTO STRICT intent;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = episode.request_id INTO STRICT request;
 SELECT ops.task.* 
FROM ops.task 
WHERE ops.task.id = episode.producer_task_id INTO STRICT job;
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = episode.release_id AND sem.data_operation_definition.operation_id = request.operation_id INTO STRICT definition;
 IF ((intent.producer_task_id, intent.producer_attempt, intent.runtime_id) IS DISTINCT FROM (episode.producer_task_id, episode.producer_attempt, episode.runtime_id) OR publication.publishing_task_id IS DISTINCT FROM episode.producer_task_id OR publication.publishing_attempt NOT BETWEEN intent.producer_attempt AND job.attempt OR (job.data_request_id, job.data_generation, job.release_id) IS DISTINCT FROM (episode.request_id, episode.generation, episode.release_id) OR job.attempt < intent.producer_attempt OR nullif(intent.producer_holder, '') IS NULL OR NOT (EXISTS (SELECT 1 
FROM ops.data_request_generation 
WHERE ops.data_request_generation.request_id = episode.request_id AND ops.data_request_generation.generation = episode.generation AND ops.data_request_generation.task_id = episode.producer_task_id)) OR episode.recipe IS DISTINCT FROM definition.recipe OR request.recipe IS DISTINCT FROM episode.recipe OR (intent.payload ->> 'implementation_revision') IS DISTINCT FROM definition.implementation_revision OR ops.ddo_completion_state(definition, (intent.payload ->> 'outcome')) IS DISTINCT FROM episode.outcome) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF original producer differs from sealed episode/intent/task fences', ERRCODE = '23514';
 END IF;
 SELECT CAST(convert_from(sem.runtime_binding.manifest_bytes, 'UTF8') AS JSONB) ->> 'execution_profile' AS anon_1 
FROM sem.runtime_binding 
WHERE sem.runtime_binding.release_id = episode.release_id AND sem.runtime_binding.runtime_id = episode.runtime_id INTO STRICT profile;
 IF (nullif(profile, '') IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF original producer lacks its admitted execution profile', ERRCODE = '23514';
 END IF;
 FOR captured IN SELECT selected.selection, demand.selection['execution_profile'] AS execution_profile 
FROM ops.demand_use AS selected JOIN ops.data_demand AS demand ON demand.id = selected.demand_id JOIN ops.data_obligation AS obligation ON obligation.id = selected.obligation_id AND obligation.demand_id = demand.id 
WHERE selected.request_id = episode.request_id AND selected.generation = episode.generation AND selected.fate IN ('attached', 'fulfilled') AND (selected.derivation_id IS NULL OR selected.derivation_id = episode.id) AND demand.project_id = request.project_id AND demand.release_id = episode.release_id AND (demand.selection ->> 'execution_profile') = profile AND obligation.operation_id = request.operation_id AND obligation.subject = request.subject AND obligation.original_source IS NOT DISTINCT FROM request.original_source AND obligation.analyzed_scope = request.analyzed_scope AND selected.selection['inputs'] IS NOT DISTINCT FROM intent.payload['inputs'] AND selected.selection['support'] IS NOT DISTINCT FROM intent.payload['support'] ORDER BY selected.created_at, selected.id LOOP
  candidate := captured.selection || jsonb_build_object('execution_profile', captured.execution_profile);
  IF (binding IS NULL) THEN
   binding := candidate;
  ELSE
   IF ((binding - 'read_id') IS DISTINCT FROM (candidate - 'read_id')) THEN
    RAISE EXCEPTION USING MESSAGE = 'PDF original producer binding is ambiguous in immutable admitted uses', ERRCODE = '23514';
   END IF;
  END IF;
 END LOOP;
 IF (binding IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF original producer lacks its full immutable admitted binding', ERRCODE = '23514';
 END IF;
 request.release_id := episode.release_id;
 request.runtime_id := episode.runtime_id;
 request.recipe := episode.recipe;
 request.generation := episode.generation;
 request.live_task_id := episode.producer_task_id;
 request.binding := binding;
 RETURN request;
END

