BEGIN
 IF (NOT coalesce(ops.ddo_policy_authority_leaf(episode), false)) THEN
  RAISE EXCEPTION USING MESSAGE = 'ordinary policy authority summary requires an authenticated native issuer', ERRCODE = '23514';
 END IF;
 SELECT ops.data_demand_read.* 
FROM ops.data_demand_read 
WHERE ops.data_demand_read.id = read_id INTO STRICT boundary;
 IF (NOT boundary.public_disclosure) THEN
  RAISE EXCEPTION USING MESSAGE = 'policy authority summary requires its public acquisition', ERRCODE = '23514';
 END IF;
 SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = episode INTO STRICT d;
 IF (d.completed_at > boundary.frontier_at OR NOT (EXISTS (SELECT published.id 
FROM ops.demand_use AS published 
WHERE published.derivation_id = d.id AND published.fate = 'fulfilled' AND ops.ddo_read_visible(published.created_at, published.created_xid, boundary)))) THEN
  RAISE EXCEPTION USING MESSAGE = 'policy issuer is outside selected native visibility', ERRCODE = '23514';
 END IF;
 SELECT ops.data_derivation_output.* 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = episode INTO STRICT output;
 SELECT ops.data_publication_receipt.* 
FROM ops.data_publication_receipt 
WHERE ops.data_publication_receipt.derivation_id = episode AND ops.data_publication_receipt.intent_id = d.intent_id INTO STRICT receipt;
 IF (selected_use IS NOT NULL) THEN
  SELECT ops.demand_use.* 
FROM ops.demand_use 
WHERE ops.demand_use.id = selected_use AND ops.demand_use.derivation_id = episode INTO STRICT chosen;
  IF (NOT ops.ddo_read_visible(chosen.created_at, chosen.created_xid, boundary)) THEN
   RAISE EXCEPTION USING MESSAGE = 'policy authority use is outside selected native visibility', ERRCODE = '23514';
  END IF;
  standing := CASE WHEN ops.ddo_node_valid('use', chosen.id, boundary) THEN 'valid' ELSE 'unavailable' END;
 ELSE
  standing := CASE WHEN ops.ddo_node_valid('episode', episode, boundary) THEN 'valid' ELSE 'unavailable' END;
