DECLARE
 operator text := node ->> 'operator';
 child jsonb;
 projected jsonb;
 selected jsonb;
 children jsonb := CAST('[]' AS JSONB);
 names text[];
 choice text;
 matches integer := 0;
BEGIN
 IF (operator IS NULL OR (operator NOT IN ('scan', 'join', 'equal', 'literal', 'same', 'distinct', 'cardinality', 'collection', 'all', 'choice', 'optional', 'forall', 'absent', 'range', 'membership', 'covers'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'unrepresentable selected-population filter operator', ERRCODE = 'P0001';
 END IF;
 IF (operator = 'choice') THEN
  choice := coalesce(node ->> 'selected', choices ->> ((node ->> 'choice_parameter')));
  FOR child IN SELECT filter_child.value 
FROM jsonb_array_elements(coalesce(node['children'], CAST('[]' AS JSONB))) AS filter_child(value) LOOP
   IF (choice = ANY (ops.ddo_binding_roles(child))) THEN
    selected := child;
    matches := matches + 1;
   END IF;
  END LOOP;
  IF (matches != 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'population filter branch is not uniquely frozen', ERRCODE = 'P0001';
  END IF;
  RETURN ops.ddo_population_filter(selected, role, choices);
 END IF;
 names := ops.ddo_binding_roles(node);
 IF (NOT (role = ANY (names))) THEN
  RETURN jsonb_build_object('operator', 'all', 'children', CAST('[]' AS JSONB));
 END IF;
 IF (operator = 'absent') THEN
  RAISE EXCEPTION USING MESSAGE = 'absence cannot define a positive selected population', ERRCODE = 'P0001';
 END IF;
 IF (operator = 'optional' AND NOT (EXISTS (WITH RECURSIVE descendants(n) AS 
(SELECT node AS n UNION ALL SELECT filter_descendant.value AS value 
FROM descendants JOIN LATERAL jsonb_array_elements(coalesce(descendants.n['children'], CAST('[]' AS JSONB))) AS filter_descendant(value) ON true)
 SELECT descendants.n 
FROM descendants 
WHERE (descendants.n ->> 'operator') IS NULL OR ((descendants.n ->> 'operator') NOT IN ('optional', 'all', 'scan', 'covers', 'cardinality', 'collection', 'forall', 'same', 'distinct'))))) THEN
  RETURN jsonb_build_object('operator', 'all', 'children', CAST('[]' AS JSONB));
 END IF;
 IF (operator = 'optional' AND (cardinality(names) != 1 OR (EXISTS (WITH RECURSIVE descendants(n) AS 
(SELECT node AS n UNION ALL SELECT filter_descendant.value AS value 
FROM descendants JOIN LATERAL jsonb_array_elements(coalesce(descendants.n['children'], CAST('[]' AS JSONB))) AS filter_descendant(value) ON true)
 SELECT descendants.n 
FROM descendants 
WHERE ((descendants.n ->> 'operator') NOT IN ('optional', 'all', 'scan', 'join', 'equal', 'literal', 'range', 'membership')))))) THEN
  RAISE EXCEPTION USING MESSAGE = 'optional population filter is not a closed row-local predicate', ERRCODE = 'P0001';
 END IF;
 FOR child IN SELECT filter_child.value 
FROM jsonb_array_elements(coalesce(node['children'], CAST('[]' AS JSONB))) AS filter_child(value) LOOP
  projected := ops.ddo_population_filter(child, role, choices);
  IF (projected != jsonb_build_object('operator', 'all', 'children', CAST('[]' AS JSONB))) THEN
   children := children || jsonb_build_array(projected);
  END IF;
 END LOOP;
 names := ops.ddo_binding_roles(node - 'children');
 IF (operator IN ('join', 'equal', 'literal', 'range', 'membership') AND cardinality(names) <= 1) THEN
  IF (EXISTS (SELECT filter_operand.value 
FROM jsonb_array_elements(coalesce(node['operands'], CAST('[]' AS JSONB))) AS filter_operand(value) 
WHERE (filter_operand.value ->> 'kind') = 'population' AND (filter_operand.value ->> 'population_projection') = 'qualified-context')) THEN
   RETURN jsonb_build_object('operator', 'all', 'children', children);
  END IF;
  IF (EXISTS (SELECT filter_operand.value 
FROM jsonb_array_elements(coalesce(node['operands'], CAST('[]' AS JSONB))) AS filter_operand(value) 
WHERE (filter_operand.value ->> 'kind') = 'population')) THEN
   RAISE EXCEPTION USING MESSAGE = 'selected population filter requires explicit non-circular membership operands', ERRCODE = 'P0001';
  END IF;
  children := children || jsonb_build_array(node - 'children');
 END IF;
 RETURN jsonb_build_object('operator', CASE WHEN (operator = 'optional') THEN 'optional' ELSE 'all' END, 'children', children);
END

