BEGIN
 IF (projection = 'qualified-context') THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('project_id', project, 'subject', member.value['subject'], 'subject_definition', member.value['subject_definition'], 'original_source', member.value['original_source'], 'analyzed_scope', member.value['analyzed_scope']) ORDER BY member.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(members) WITH ORDINALITY AS member(value, ordinal) INTO projected;
 ELSE
  IF (projection = 'member') THEN
   SELECT coalesce(jsonb_agg(member.value['member_id'] ORDER BY member.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(members) WITH ORDINALITY AS member(value, ordinal) INTO projected;
  ELSE
   RAISE EXCEPTION USING MESSAGE = 'unknown population projection', ERRCODE = 'P0001';
  END IF;
 END IF;
 result := jsonb_build_object('identity', identity, 'complete', complete, 'members', projected, 'evidence', evidence);
 IF (projection = 'qualified-context') THEN
  result := result || jsonb_build_object('projection', projection);
 END IF;
 RETURN result;
END

