DECLARE
 definition sem.data_operation_definition%ROWTYPE;
 output jsonb;
BEGIN
 IF (NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id AND sem.data_operation_definition.validity_families @> ARRAY['record-fit']))) THEN
  RETURN;
 END IF;
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id INTO STRICT definition;
 IF (definition.profile IS DISTINCT FROM 'derivation' OR definition.support_contract['effects'] IS DISTINCT FROM CAST('[]' AS JSONB) OR nullif(((definition.support_contract['capabilities']['prepared_factory']) ->> 'entrypoint'), '') IS NULL OR (((definition.support_contract['capabilities']['prepared_factory']) ->> 'source_digest') ~ '^[0-9a-f]{64}$') IS NOT true OR (definition.implementation_revision LIKE 'implementation-slice:%') IS NOT true OR (completion ->> 'implementation_revision') IS DISTINCT FROM definition.implementation_revision OR r.recipe IS DISTINCT FROM definition.recipe OR completion['inputs'] IS DISTINCT FROM r.binding['inputs'] OR completion['support'] IS DISTINCT FROM r.binding['support'] OR jsonb_array_length(coalesce(completion['execution_evidence']['cpu_receipts'], CAST('[]' AS JSONB))) != 1) THEN
  RAISE EXCEPTION USING MESSAGE = 'fit completion requires actual protected fit factory/CPU and exact declared inputs', ERRCODE = '23514';
 END IF;
 IF ((completion ->> 'outcome') = 'empty' AND completion['outputs'] = CAST('[]' AS JSONB)) THEN
  RETURN;
 END IF;
 IF ((completion ->> 'outcome') IS DISTINCT FROM 'success' OR jsonb_array_length(completion['outputs']) != 1) THEN
  RAISE EXCEPTION USING MESSAGE = 'fit completion requires one fitted scalar or a non-authoritative empty result', ERRCODE = '23514';
 END IF;
 output := completion['outputs'][0];
 IF ((output ->> 'role') IS DISTINCT FROM 'fitted' OR (output ->> 'member_id') IS NOT NULL OR CAST((output ->> 'position') AS INTEGER) IS DISTINCT FROM 0 OR CAST((output ->> 'multiplicity') AS INTEGER) IS DISTINCT FROM 1 OR output['product']['members'] IS DISTINCT FROM CAST('[]' AS JSONB) OR NOT (EXISTS (SELECT 1 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = ((output['product']) ->> 'kind_contract') AND sem.data_kind_contract.kind = 'https://corpus-structure.dev/semantic/data-operation-record-policy/protected/DdoFittedRecordPolicy' AND sem.data_kind_contract.universe = 'evaluator'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'fit output differs from exact protected fitted scalar contract', ERRCODE = '23514';
 END IF;
END

