CREATE OR REPLACE FUNCTION ops.ddo_record_grade_require_frame(r ops.data_request, grade jsonb) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 a jsonb := ops.ddo_record_grade_input(r, 'reference_a');
 b jsonb := ops.ddo_record_grade_input(r, 'reference_b');
 c jsonb := ops.ddo_record_grade_input(r, 'adjudication');
 specification jsonb := (ops.ddo_record_grade_input(r, 'specification'))['body'];
 frame jsonb := grade['frame'];
 question jsonb;
 selected jsonb;
 source_census jsonb;
 prediction_census jsonb;
 u jsonb;
 obligation jsonb;
 cuts jsonb := CAST('{}' AS JSONB);
 predicted jsonb;
 carrier jsonb;
 candidate jsonb;
 event jsonb;
 actual_event jsonb;
 coverage jsonb;
 ref jsonb;
 pin jsonb;
 bound jsonb;
 pins jsonb := CAST('[]' AS JSONB);
 sources_ jsonb := CAST('[]' AS JSONB);
 reading_completion jsonb;
 reading_body jsonb;
 verified_readings jsonb := CAST('{}' AS JSONB);
 captured record;
 pass_row record;
 n bigint;
 event_count integer := 0;
 selected_count integer := 0;
 reading_key text;
 producer ops.data_derivation%ROWTYPE;
 reading sem.data_operation_definition%ROWTYPE;
 reading_request ops.data_request%ROWTYPE;
 reading_intent ops.data_completion_intent%ROWTYPE;
BEGIN
 IF ((grade ->> 'version') IS DISTINCT FROM 'record-grade-1' OR (grade ->> 'frame_digest') IS DISTINCT FROM encode(sha256(convert_to((grade ->> 'frame_canonical_json'), 'UTF8')), 'hex') OR CAST((grade ->> 'frame_canonical_json') AS JSONB) IS DISTINCT FROM frame OR (frame ->> 'project_id') IS DISTINCT FROM r.project_id OR jsonb_array_length(c['body']['references']) != jsonb_array_length(specification['prediction_selections']) OR jsonb_array_length(c['body']['references']) != jsonb_array_length(frame['coverage']) OR 3 * jsonb_array_length(c['body']['references']) != jsonb_array_length(frame['reference_passes']) OR (a ->> 'product_id') = (b ->> 'product_id') OR (a ->> 'product_id') = (c ->> 'product_id') OR (b ->> 'product_id') = (c ->> 'product_id')) THEN
  RAISE EXCEPTION USING MESSAGE = 'record grade differs from canonical frame and genuine independent pass population', ERRCODE = '23514';
 END IF;
 FOR captured IN SELECT anon_1.cut_text, anon_1.cut_id 
FROM ops.ddo_record_grade_cuts(r) AS anon_1 LOOP
  cuts := cuts || jsonb_build_object(captured.cut_id, ops.ddo_record_grade_acquire_census_material(r.project_id, captured.cut_text, captured.cut_id));
 END LOOP;
 FOR ref, n IN SELECT reference_row.value, reference_row.ordinal 
FROM jsonb_array_elements(c['body']['references']) WITH ORDINALITY AS reference_row(value, ordinal) LOOP
  question := ref['question'];
  selected := specification['prediction_selections'][CAST(n - 1 AS INTEGER)];
  sources_ := sources_ || jsonb_build_array(question['source']);
  IF (selected['source'] IS DISTINCT FROM question['source'] OR frame['sources'][CAST(n - 1 AS INTEGER)] IS DISTINCT FROM question['source'] OR (frame ->> 'partition') IS DISTINCT FROM (question ->> 'partition') OR (frame ->> 'family') IS DISTINCT FROM (question ->> 'family') OR (frame ->> 'family_contract') IS DISTINCT FROM (question ->> 'family_contract') OR (frame ->> 'reading_recipe') IS DISTINCT FROM (question ->> 'reading_recipe') OR (frame ->> 'subset') IS DISTINCT FROM (question ->> 'subset') OR (frame ->> 'source_release_id') IS DISTINCT FROM (question ->> 'source_release_id') OR (frame ->> 'source_cut_id') IS DISTINCT FROM (question ->> 'source_cut_id') OR (frame ->> 'prediction_cut_id') IS DISTINCT FROM (selected ->> 'expected_cut') OR (frame ->> 'prediction_release_id') IS DISTINCT FROM (CAST((selected ->> 'cut_canonical_json') AS JSONB) ->> 'release_id') OR (selected ->> 'project_id') IS DISTINCT FROM r.project_id OR (CAST((selected ->> 'cut_canonical_json') AS JSONB) ->> 'project_id') IS DISTINCT FROM (selected ->> 'project_id') OR (CAST((selected ->> 'cut_canonical_json') AS JSONB) ->> 'demand_id') IS DISTINCT FROM (selected ->> 'demand_id') OR (CAST((selected ->> 'cut_canonical_json') AS JSONB) ->> 'read_id') IS DISTINCT FROM (selected ->> 'read_id')) THEN
   RAISE EXCEPTION USING MESSAGE = 'record question/source/prediction census changed', ERRCODE = '23514';
  END IF;
  source_census := cuts[(question ->> 'source_cut_id')];
  prediction_census := cuts[(selected ->> 'expected_cut')];
  FOR pass_row IN SELECT passes.pass_kind, passes.pass_value 
FROM (SELECT CAST('A' AS TEXT) AS pass_kind, a AS pass_value UNION ALL SELECT CAST('B' AS TEXT) AS anon_1, b UNION ALL SELECT CAST('C' AS TEXT) AS anon_2, c) AS passes LOOP
   bound := pass_row.pass_value;
   IF (((bound['body']) ->> 'pass_kind') IS DISTINCT FROM pass_row.pass_kind OR ((bound['body']['references'][CAST(n - 1 AS INTEGER)]) ->> 'pass_kind') IS DISTINCT FROM pass_row.pass_kind OR bound['body']['references'][CAST(n - 1 AS INTEGER)]['question'] IS DISTINCT FROM question OR bound['body']['references'][CAST(n - 1 AS INTEGER)]['exposed_outputs'] IS DISTINCT FROM CAST('[]' AS JSONB)) THEN
    RAISE EXCEPTION USING MESSAGE = 'record reference pass differs from exact source-only question/exposure', ERRCODE = '23514';
   END IF;
   SELECT reference_pass.value 
FROM jsonb_array_elements(frame['reference_passes']) AS reference_pass 
WHERE (reference_pass.value ->> 'pass_kind') = pass_row.pass_kind AND reference_pass.value['source'] = question['source'] INTO STRICT event;
   IF (((event['reference']) ->> 'product_id') IS DISTINCT FROM (bound ->> 'product_id') OR ((event['reference']) ->> 'member_id') IS NOT NULL OR (event ->> 'author') IS DISTINCT FROM ((bound['body']['references'][CAST(n - 1 AS INTEGER)]) ->> 'author') OR event['adjudicates'] IS DISTINCT FROM bound['body']['references'][CAST(n - 1 AS INTEGER)]['adjudicates']) THEN
    RAISE EXCEPTION USING MESSAGE = 'record grade relabels actual reference pass', ERRCODE = '23514';
   END IF;
  END LOOP;
  FOR pin IN SELECT reference_pin.value 
FROM jsonb_array_elements(jsonb_build_array(question['source']) || coalesce((CAST((question ->> 'frame_canonical_json') AS JSONB))['related_pins'], CAST('[]' AS JSONB))) AS reference_pin LOOP
   IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(pins) AS previous 
WHERE (previous.value ->> 'source_product') = (pin ->> 'source_product') AND (previous.value ->> 'source_member') IS NOT DISTINCT FROM (pin ->> 'source_member')))) THEN
    pins := pins || jsonb_build_array(pin);
   END IF;
   SELECT bound_input.value 
FROM jsonb_array_elements(r.binding['inputs']) AS bound_input 
WHERE (bound_input.value ->> 'role') = 'sources' AND (bound_input.value ->> 'product_id') = (pin ->> 'source_product') AND (bound_input.value ->> 'member_id') IS NOT DISTINCT FROM (pin ->> 'source_member') INTO STRICT bound;
   IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(source_census['outputs']) AS source_output 
WHERE (source_output.value ->> 'product_id') = (pin ->> 'source_product')))) THEN
    RAISE EXCEPTION USING MESSAGE = 'record question source is outside actual selected cut support', ERRCODE = '23514';
   END IF;
   predicted := ops.ddo_record_grade_input_value(r.project_id, bound ->> 'product_id', bound ->> 'member_id');
   IF (((predicted - 'body') - 'analyzed_scope_meaning') IS DISTINCT FROM jsonb_build_object('product_id', (pin ->> 'source_product'), 'member_id', (pin ->> 'source_member'), 'project_id', (pin ->> 'project_id'), 'kind_contract', (pin ->> 'kind_contract'), 'subject', (pin ->> 'subject'), 'subject_definition', (pin ->> 'subject_definition'), 'original_source', (pin ->> 'original_source')) OR predicted['analyzed_scope_meaning'] IS DISTINCT FROM CAST((pin ->> 'analyzed_scope_meaning') AS JSONB) OR ((predicted['body']['source']) ->> 'projection') IS DISTINCT FROM (pin ->> 'projection_digest') OR ((predicted['body']['source']) ->> 'document') IS DISTINCT FROM (pin ->> 'document') OR ((predicted['body']['source']) ->> 'section_pointer') IS DISTINCT FROM (pin ->> 'section_pointer') OR ((predicted['body']['source']) ->> 'membership') IS DISTINCT FROM (pin ->> 'membership')) THEN
    RAISE EXCEPTION USING MESSAGE = 'record source pin differs from actual declared source product/member/context', ERRCODE = '23514';
   END IF;
  END LOOP;
  u := prediction_census['uses'][(selected ->> 'use_id')];
  obligation := prediction_census['obligations'][(selected ->> 'obligation_id')];
  IF (u IS NULL OR obligation IS NULL OR (u ->> 'obligation_id') IS DISTINCT FROM (selected ->> 'obligation_id') OR (u ->> 'request_id') IS DISTINCT FROM (selected ->> 'request_id')) THEN
   RAISE EXCEPTION USING MESSAGE = 'record opportunity is outside its exact native selected census', ERRCODE = '23514';
  END IF;
  IF (NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = (CAST((selected ->> 'cut_canonical_json') AS JSONB) ->> 'release_id') AND sem.data_operation_definition.operation_id = (obligation ->> 'operation_id') AND sem.data_operation_definition.recipe = (question ->> 'reading_recipe') AND sem.data_operation_definition.profile = 'derivation' AND sem.data_operation_definition.support_contract['effects'] = CAST('[]' AS JSONB))) OR (obligation ->> 'subject') IS DISTINCT FROM ((question['source']) ->> 'subject') OR (obligation ->> 'subject_definition') IS DISTINCT FROM ((question['source']) ->> 'subject_definition') OR (obligation ->> 'original_source') IS DISTINCT FROM ((question['source']) ->> 'original_source') OR data.ddo_json_meaning(obligation['analyzed_scope']) IS DISTINCT FROM CAST(((question['source']) ->> 'analyzed_scope_meaning') AS JSONB)) THEN
   RAISE EXCEPTION USING MESSAGE = 'record opportunity differs from actual source context', ERRCODE = '23514';
  END IF;
  coverage := frame['coverage'][CAST(n - 1 AS INTEGER)];
  IF (coverage['source'] IS DISTINCT FROM question['source']) THEN
   RAISE EXCEPTION USING MESSAGE = 'record coverage source changed', ERRCODE = '23514';
  END IF;
  IF ((selected ->> 'outcome') IN ('failed', 'no_output')) THEN
   IF ((u ->> 'completion_state') IS DISTINCT FROM CASE WHEN ((selected ->> 'outcome') = 'failed') THEN 'failed' ELSE 'empty' END OR (u ->> 'fate') IS DISTINCT FROM CASE WHEN ((selected ->> 'outcome') = 'failed') THEN 'failed' ELSE 'known-absent' END OR (coverage ->> 'outcome') IS DISTINCT FROM (selected ->> 'outcome') OR coverage['outputs'] IS DISTINCT FROM CAST('[]' AS JSONB) OR coverage['event_ids'] IS DISTINCT FROM CAST('[]' AS JSONB) OR (selected ->> 'outcome') = 'failed' AND ((coverage ->> 'failure_request_id'), (coverage ->> 'failure_use_id')) IS DISTINCT FROM ((selected ->> 'request_id'), (selected ->> 'use_id'))) THEN
    RAISE EXCEPTION USING MESSAGE = 'failed or empty coverage differs from actual native completion', ERRCODE = '23514';
   END IF;
   CONTINUE;
  END IF;
  IF ((selected ->> 'outcome') IS DISTINCT FROM 'completed' OR (u ->> 'completion_state') IS DISTINCT FROM 'success' OR (u ->> 'fate') IS DISTINCT FROM 'fulfilled' OR (u ->> 'derivation_id') IS DISTINCT FROM (selected ->> 'derivation_id')) THEN
   RAISE EXCEPTION USING MESSAGE = 'record prediction is unavailable or differs from actual native success', ERRCODE = '23514';
  END IF;
  SELECT bound_input.value 
FROM jsonb_array_elements(r.binding['inputs']) AS bound_input 
WHERE (bound_input.value ->> 'role') = 'prediction' AND (bound_input.value ->> 'product_id') = (selected ->> 'product_id') AND (bound_input.value ->> 'member_id') IS NULL AND coalesce(CAST((bound_input.value ->> 'multiplicity') AS INTEGER), 0) = 1 INTO STRICT bound;
  IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(r.binding['support']) AS bound_support 
WHERE (bound_support.value ->> 'derivation_id') = (selected ->> 'derivation_id'))) OR NOT (EXISTS (SELECT 1 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = (selected ->> 'derivation_id') AND ops.data_derivation_output.product_id = (selected ->> 'product_id') AND ops.data_derivation_output.member_id IS NULL))) THEN
   RAISE EXCEPTION USING MESSAGE = 'record prediction lacks exact declared producer/output support', ERRCODE = '23514';
  END IF;
  selected_count := selected_count + 1;
  SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = (selected ->> 'derivation_id') AND ops.data_derivation.request_id = (selected ->> 'request_id') INTO STRICT producer;
  SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = producer.release_id AND sem.data_operation_definition.recipe = producer.recipe INTO STRICT reading;
  IF (producer.recipe IS DISTINCT FROM reading.recipe OR reading.recipe IS DISTINCT FROM (question ->> 'reading_recipe')) THEN
   RAISE EXCEPTION USING MESSAGE = 'record prediction changed its admitted reading recipe', ERRCODE = '23514';
  END IF;
  reading_key := data.canonical_json(jsonb_build_array(producer.id, selected ->> 'product_id'));
  IF (NOT (verified_readings ? reading_key)) THEN
   SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = producer.request_id AND ops.data_request.project_id = r.project_id INTO STRICT reading_request;
   SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent JOIN ops.data_publication_receipt ON ops.data_publication_receipt.intent_id = ops.data_completion_intent.id AND ops.data_publication_receipt.derivation_id = producer.id 
WHERE ops.data_completion_intent.id = producer.intent_id AND ops.data_completion_intent.request_id = producer.request_id AND ops.data_completion_intent.generation = producer.generation INTO STRICT reading_intent;
   IF ((reading_intent.producer_task_id, reading_intent.producer_attempt, reading_intent.runtime_id) IS DISTINCT FROM (producer.producer_task_id, producer.producer_attempt, producer.runtime_id) OR (reading_intent.payload ->> 'outcome') IS DISTINCT FROM producer.outcome) THEN
    RAISE EXCEPTION USING MESSAGE = 'record prediction differs from original reading producer fences', ERRCODE = '23514';
   END IF;
   reading_request.release_id := producer.release_id;
   reading_request.runtime_id := producer.runtime_id;
   reading_request.recipe := producer.recipe;
   reading_request.generation := producer.generation;
   reading_request.binding := reading_request.binding || jsonb_build_object('inputs', reading_intent.payload['inputs'], 'support', reading_intent.payload['support']);
   reading_completion := reading_intent.payload;
   SELECT kb.data_product.canonical_body 
FROM kb.data_product 
WHERE kb.data_product.id = (selected ->> 'product_id') AND kb.data_product.project_id = r.project_id INTO STRICT reading_body;
   IF (reading_request.operation_id IS DISTINCT FROM reading.operation_id OR reading.profile IS DISTINCT FROM 'derivation' OR reading.support_contract['effects'] IS DISTINCT FROM CAST('[]' AS JSONB) OR nullif(((reading.support_contract['capabilities']['prepared_factory']) ->> 'entrypoint'), '') IS NULL OR (((reading.support_contract['capabilities']['prepared_factory']) ->> 'source_digest') ~ '^[0-9a-f]{64}$') IS NOT true OR (reading_completion ->> 'implementation_revision') IS DISTINCT FROM reading.implementation_revision OR ops.ddo_cpu_reply_output(reading_request, reading_completion) IS DISTINCT FROM reading_body) THEN
    RAISE EXCEPTION USING MESSAGE = 'record prediction differs from its actual reading CPU result and native basis', ERRCODE = '23514';
   END IF;
   verified_readings := verified_readings || jsonb_build_object(reading_key, true);
  END IF;
  predicted := ops.ddo_record_grade_input_value(r.project_id, selected ->> 'product_id', NULL);
  carrier := predicted['body'];
  IF (carrier['source_pin'] IS DISTINCT FROM jsonb_strip_nulls(question['source']) OR jsonb_array_length(coverage['outputs']) != 1 OR ((coverage['outputs'][0]) ->> 'product_id') IS DISTINCT FROM (selected ->> 'product_id')) THEN
   RAISE EXCEPTION USING MESSAGE = 'record coverage differs from actual selected carrier/source', ERRCODE = '23514';
  END IF;
  FOR candidate IN SELECT packet.value['body'] AS anon_1 
FROM jsonb_array_elements(carrier['members']) AS packet 
WHERE ((packet.value['body']) ->> 'candidate_type') = 'record' AND ((packet.value['body']) ->> 'family') = (question ->> 'family') LOOP
   event_count := event_count + 1;
   SELECT frame_event.value 
FROM jsonb_array_elements(frame['events']) AS frame_event 
WHERE (frame_event.value ->> 'interpretation_id') = (candidate ->> 'interpretation_id') INTO STRICT event;
   IF ((event ->> 'record_id') IS DISTINCT FROM (candidate ->> 'record_id') OR event['source'] IS DISTINCT FROM question['source'] OR (event ->> 'source_release_id') IS DISTINCT FROM producer.release_id OR (event ->> 'derivation_id') IS DISTINCT FROM producer.id OR (event ->> 'reading_recipe') IS DISTINCT FROM reading.recipe OR ((event['reading']) ->> 'product_id') IS DISTINCT FROM (selected ->> 'product_id') OR ((event['features']) ->> 'record_id') IS DISTINCT FROM (candidate ->> 'record_id') OR ((event['features']) ->> 'interpretation_id') IS DISTINCT FROM (candidate ->> 'interpretation_id') OR ((event['features']) ->> 'release_id') IS DISTINCT FROM producer.release_id OR NOT ((coverage['event_ids'] ? (candidate ->> 'interpretation_id')))) THEN
    RAISE EXCEPTION USING MESSAGE = 'grade event relabels actual eligible reading or producing context', ERRCODE = '23514';
   END IF;
   IF (NOT sem.ddo_model_class_contract(producer.release_id, question ->> 'family_contract', candidate ->> 'contract')) THEN
    RAISE EXCEPTION USING MESSAGE = 'grade family differs from its authenticated effective model class contract', ERRCODE = '23514';
   END IF;
   SELECT carrier_event.value 
FROM jsonb_array_elements((CAST(carrier ->> 'diagnostics_json' AS JSONB))['record_policy_events']) AS carrier_event 
WHERE (carrier_event.value ->> 'record_id') = (candidate ->> 'record_id') AND (carrier_event.value ->> 'interpretation_id') = (candidate ->> 'interpretation_id') INTO STRICT actual_event;
   IF ((actual_event ->> 'outcome') = 'completed') THEN
    IF (event['final_event'] IS DISTINCT FROM jsonb_build_object('outcome', 'completed', 'feature_instance_digest', (actual_event ->> 'feature_instance_digest'), 'feature_input_digest', (actual_event ->> 'feature_input_digest'), 'event_procedure', (actual_event ->> 'event_procedure'), 'final_event_score', actual_event['final_event_score'])) THEN
     RAISE EXCEPTION USING MESSAGE = 'grade final event differs from actual sealed producer score', ERRCODE = '23514';
    END IF;
   ELSE
    IF (event['final_event'] IS DISTINCT FROM CAST('null' AS JSONB) OR (frame ->> 'partition') = 'final_event_calibration') THEN
     RAISE EXCEPTION USING MESSAGE = 'grade invents a completed final event', ERRCODE = '23514';
    END IF;
   END IF;
  END LOOP;
  IF (jsonb_array_length(coverage['event_ids']) != (SELECT count(*) AS count_1 
FROM jsonb_array_elements(carrier['members']) AS packet 
WHERE ((packet.value['body']) ->> 'candidate_type') = 'record' AND ((packet.value['body']) ->> 'family') = (question ->> 'family')) OR (coverage ->> 'outcome') IS DISTINCT FROM CASE WHEN (jsonb_array_length(coverage['event_ids']) = 0) THEN 'no_output' ELSE 'completed' END) THEN
   RAISE EXCEPTION USING MESSAGE = 'grade coverage omits actual eligible reading events', ERRCODE = '23514';
  END IF;
 END LOOP;
 IF (sources_ IS DISTINCT FROM frame['sources'] OR jsonb_array_length(frame['events']) != event_count OR jsonb_array_length(pins) != (SELECT count(*) AS count_1 
FROM jsonb_array_elements(r.binding['inputs']) AS bound_input 
WHERE (bound_input.value ->> 'role') = 'sources') OR selected_count != (SELECT count(*) AS count_2 
FROM jsonb_array_elements(r.binding['inputs']) AS bound_input 
WHERE (bound_input.value ->> 'role') = 'prediction')) THEN
  RAISE EXCEPTION USING MESSAGE = 'grade does not cover exact declared source and prediction populations', ERRCODE = '23514';
 END IF;
END$$

