DECLARE
 demand ops.data_demand%ROWTYPE;
 request ops.data_request%ROWTYPE;
 native_population ops.data_population%ROWTYPE;
 boundary ops.data_demand_read%ROWTYPE;
 binding_model jsonb;
 operation jsonb;
 compiled jsonb;
 selection jsonb;
 expression jsonb;
 population_refs jsonb;
 roles jsonb := CAST('{}' AS JSONB);
 universe jsonb;
 populations jsonb := CAST('{}' AS JSONB);
 witnesses jsonb := CAST('{}' AS JSONB);
 semantic_witnesses jsonb := CAST('{}' AS JSONB);
 states jsonb := CAST('{}' AS JSONB);
 context jsonb;
 item jsonb;
 roledef jsonb;
 row_value jsonb;
 chosen jsonb;
 values jsonb;
 raw jsonb;
 role_meaning jsonb;
 witness jsonb;
 seen jsonb;
 expected jsonb;
 discovery_refs jsonb;
 role text;
 state text;
 projection_mode text;
 inactive text[];
 count_selected bigint;
 multiplicity bigint;
 ordinal bigint;
BEGIN
 SELECT ops.data_demand.* 
FROM ops.data_demand 
WHERE ops.data_demand.id = p_demand INTO STRICT demand;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.request_key = data.ddo_identity('semantic-request', p_request_meaning) INTO STRICT request;
 IF (request.operation_id != p_operation OR request.subject != p_subject OR request.project_id != demand.project_id OR NOT (EXISTS (SELECT sem.data_operation_definition.operation_id 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = demand.release_id AND sem.data_operation_definition.operation_id = p_operation AND sem.data_operation_definition.recipe = request.recipe))) THEN
  RAISE EXCEPTION USING MESSAGE = 'native binding request custody differs', ERRCODE = 'P0001';
 END IF;
 SELECT to_jsonb(data_operation_definition) AS to_jsonb_1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = demand.release_id AND sem.data_operation_definition.operation_id = p_operation INTO STRICT compiled;
 SELECT jsonb_build_object('kinds', sem.data_operation_release.binding_types) AS jsonb_build_object_1 
FROM sem.data_operation_release 
WHERE sem.data_operation_release.release_id = demand.release_id INTO STRICT binding_model;
 expression := compiled['binding_expression'];
 operation := jsonb_build_object('parameters', jsonb_build_object('json', compiled['parameter_definitions']));
 IF (EXISTS (WITH RECURSIVE nodes(n) AS 
(SELECT expression AS n UNION ALL SELECT descendant.value AS value 
FROM nodes JOIN LATERAL jsonb_array_elements(coalesce(nodes.n['children'], CAST('[]' AS JSONB))) AS descendant(value) ON true)
 SELECT nodes.n 
FROM nodes 
WHERE (nodes.n ->> 'operator') IS NULL OR ((nodes.n ->> 'operator') NOT IN ('scan', 'join', 'equal', 'literal', 'same', 'distinct', 'cardinality', 'collection', 'all', 'choice', 'optional', 'forall', 'absent', 'range', 'membership', 'covers')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'authenticated native binding is outside the closed operator vocabulary', ERRCODE = 'P0001';
 END IF;
 SELECT selected_operation.value 
FROM jsonb_array_elements(demand.selection['operations']) AS selected_operation(value) 
WHERE (selected_operation.value ->> 'operation') = p_operation INTO STRICT selection;
 PERFORM ops.ddo_validate_parameters(operation, selection, binding_model);
 IF ((compiled ->> 'definition_identity') IS DISTINCT FROM (selection ->> 'definition') OR (compiled ->> 'eligibility_identity') IS DISTINCT FROM (selection ->> 'eligibility')) THEN
  RAISE EXCEPTION USING MESSAGE = 'binding differs from authenticated frozen definition', ERRCODE = 'P0001';
 END IF;
 IF (jsonb_array_length(compiled['input_roles']) != (SELECT count(DISTINCT (compiled_role.value ->> 'name')) AS count_1 
FROM jsonb_array_elements(compiled['input_roles']) AS compiled_role(value))) THEN
  RAISE EXCEPTION USING MESSAGE = 'admitted input role inventory repeats a role', ERRCODE = 'P0001';
 END IF;
 IF (nullif((p_binding ->> 'read_id'), '') IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'native binding requires its authenticated read receipt', ERRCODE = '23514';
 END IF;
 SELECT ops.data_demand_read.* 
FROM ops.data_demand_read 
WHERE ops.data_demand_read.id = (p_binding ->> 'read_id') AND ops.data_demand_read.demand_id = demand.id INTO STRICT boundary;
 WITH RECURSIVE nodes(n) AS 
(SELECT expression AS n UNION ALL SELECT descendant.value AS value 
FROM nodes JOIN LATERAL jsonb_array_elements(coalesce(nodes.n['children'], CAST('[]' AS JSONB))) AS descendant(value) ON true)
 SELECT coalesce(jsonb_agg(to_jsonb(native_binding_row)), CAST('[]' AS JSONB)) AS coalesce_1 
FROM ops.ddo_binding_rows(p_demand, p_operation, p_trust, p_binding ->> 'read_id', p_subject, coalesce(to_jsonb(request.original_source), CAST('null' AS JSONB)), request.analyzed_scope, false, CASE WHEN (EXISTS (SELECT nodes.n 
FROM nodes 
WHERE (nodes.n ->> 'operator') IN ('forall', 'absent', 'membership', 'covers'))) THEN NULL ELSE p_binding['inputs'] END, p_read_checked) AS native_binding_row INTO universe;
 raw := data.ddo_json(p_binding['request_inputs']);
 FOR roledef IN SELECT compiled_role.value 
FROM jsonb_array_elements(compiled['input_roles']) AS compiled_role(value) LOOP
  role := roledef ->> 'name';
  values := CAST('[]' AS JSONB);
  FOR item IN SELECT selected_input.value 
FROM jsonb_array_elements(p_binding['inputs']) AS selected_input(value) 
WHERE (selected_input.value ->> 'role') = role LOOP
   PERFORM ops.ddo_input_support_selection(item);
   SELECT native_value.value 
FROM jsonb_array_elements(universe) AS native_value(value) 
WHERE (native_value.value ->> 'product') = (item ->> 'product_id') AND (native_value.value ->> 'member') IS NOT DISTINCT FROM (item ->> 'member_id') AND (roledef['accepted_kind_contracts'] ? (native_value.value ->> 'kind_contract')) AND ops.ddo_binding_subject(roledef, native_value.value, p_subject, request.original_source) AND ops.ddo_binding_source(roledef, native_value.value, request.original_source, coalesce(demand.selection['source_sets'], CAST('{}' AS JSONB))) AND (native_value.value ->> 'position') IS NOT DISTINCT FROM (item ->> 'position') AND (native_value.value ->> 'multiplicity') = (item ->> 'multiplicity') AND native_value.value['support_evidence']['producer_output'] IS NOT DISTINCT FROM nullif(item['producer_output'], CAST('null' AS JSONB)) AND coalesce(native_value.value['support_episodes'], CAST('[]' AS JSONB)) = item['support_derivation_ids'] AND (EXISTS (SELECT exact_support.value 
FROM ops.ddo_input_support_refs(p_binding, item) AS exact_support(value) 
WHERE ops.ddo_support_reference_matches(exact_support.value, native_value.value))) 
 LIMIT 1 INTO chosen;
   IF (chosen IS NULL) THEN
    RAISE EXCEPTION USING MESSAGE = 'selected input support set has no exact native binding row', ERRCODE = '23514';
   END IF;
   values := values || jsonb_build_array(chosen);
  END LOOP;
  roles := jsonb_set(roles, ARRAY[role], values);
  role_meaning := data.ddo_field(p_binding['request_inputs'], role);
  state := data.ddo_field(role_meaning, 'value') ->> 0;
  states := jsonb_set(states, ARRAY[role], to_jsonb(state));
  witness := raw[role]['population_witness'];
  IF (witness IS NOT NULL AND witness != CAST('null' AS JSONB)) THEN
   semantic_witnesses := jsonb_set(semantic_witnesses, ARRAY[role], witness);
  END IF;
  SELECT coalesce(sum(CAST(selected_value.value ->> 'multiplicity' AS BIGINT)), 0) AS coalesce_1 
FROM jsonb_array_elements(values) AS selected_value(value) INTO count_selected;
  IF (state = 'present' AND (count_selected < CAST((roledef ->> 'minimum') AS BIGINT) OR (roledef ->> 'maximum') IS NOT NULL AND count_selected > CAST((roledef ->> 'maximum') AS BIGINT))) THEN
   RAISE EXCEPTION USING MESSAGE = 'native binding role cardinality differs', ERRCODE = '23514';
  END IF;
  seen := CAST('[]' AS JSONB);
  FOR row_value IN SELECT selected_value.value 
FROM jsonb_array_elements(values) AS selected_value(value) LOOP
   IF (EXISTS (SELECT support_reference.value 
FROM jsonb_array_elements(coalesce(row_value['support_references'], CAST('[]' AS JSONB))) AS support_reference(value) 
WHERE NOT (coalesce(roledef['support']['origins'], CAST('["computation"]' AS JSONB)) ? (support_reference.value ->> 'kind')))) THEN
    RAISE EXCEPTION USING MESSAGE = 'selected support origin is outside declared eligibility', ERRCODE = '23514';
   END IF;
   multiplicity := CAST(row_value ->> 'multiplicity' AS BIGINT);
   ordinal := CAST(row_value ->> 'position' AS BIGINT);
   IF (multiplicity IS NULL OR multiplicity < 1 OR ordinal < 0 OR (roledef ->> 'collection') != 'bag' AND multiplicity != 1) THEN
    RAISE EXCEPTION USING MESSAGE = 'native binding multiplicity or ordinal differs', ERRCODE = '23514';
   END IF;
   IF ((roledef ->> 'collection') = 'sequence') THEN
    IF (ordinal IS NULL OR (seen @> jsonb_build_array(ordinal))) THEN
     RAISE EXCEPTION USING MESSAGE = 'native sequence has missing or repeated ordinal', ERRCODE = '23514';
    END IF;
    seen := seen || jsonb_build_array(ordinal);
   END IF;
   IF (EXISTS (SELECT required_identity.value 
FROM jsonb_array_elements_text(roledef['identity_requirements']) AS required_identity(value) 
WHERE required_identity.value IN ('provider', 'alternative') AND nullif((row_value ->> (required_identity.value || '_identity')), '') IS NULL)) THEN
    RAISE EXCEPTION USING MESSAGE = 'required native support identity is unavailable', ERRCODE = '23514';
   END IF;
  END LOOP;
 END LOOP;
 IF (EXISTS (SELECT 1 AS anon_1 
FROM jsonb_array_elements(p_binding['populations']) AS population_reference(value) GROUP BY population_reference.value ->> 'name' 
HAVING count(DISTINCT (population_reference.value ->> 'population_id')) != 1)) THEN
  RAISE EXCEPTION USING MESSAGE = 'one named population cannot select conflicting receipt scopes', ERRCODE = '23514';
 END IF;
 FOR native_population IN SELECT pop.* 
FROM ops.data_population AS pop 
WHERE pop.demand_id = p_demand AND ops.ddo_node_valid('population', pop.id) AND (EXISTS (SELECT population_reference.value 
FROM jsonb_array_elements(p_binding['populations']) AS population_reference(value) 
WHERE (population_reference.value ->> 'population_id') = pop.id AND (population_reference.value ->> 'name') = pop.name)) AND ((EXISTS (SELECT population_reference.value 
FROM jsonb_array_elements(p_binding['populations']) AS population_reference(value) 
WHERE (population_reference.value ->> 'population_id') = pop.id AND ops.ddo_discovery_role_population(demand, pop, p_operation, (population_reference.value ->> 'role'), p_subject, request.original_source, request.analyzed_scope, boundary))) OR NOT (pop.evidence ? 'selection') AND (EXISTS (SELECT producer.id 
FROM ops.data_derivation AS producer JOIN ops.data_request AS produced ON produced.id = producer.request_id 
WHERE producer.id = (pop.evidence ->> 'derivation_id') AND produced.subject = p_subject AND produced.original_source IS NOT DISTINCT FROM request.original_source AND produced.analyzed_scope = request.analyzed_scope)) OR ((pop.evidence['selection']) ->> 'subject') = p_subject AND ((pop.evidence['selection']) ->> 'original_source') IS NOT DISTINCT FROM request.original_source AND ((pop.evidence['selection']) ->> 'operation_id') = p_operation AND pop.evidence['selection']['analyzed_scope'] = request.analyzed_scope) LOOP
  SELECT coalesce(ops.ddo_binding_population_projection(expression, jsonb_build_object('choices', selection['choices']), population_reference.value ->> 'role'), 'member') AS coalesce_1 
FROM jsonb_array_elements(p_binding['populations']) AS population_reference(value) 
WHERE (population_reference.value ->> 'population_id') = native_population.id 
 LIMIT 1 INTO projection_mode;
  populations := jsonb_set(populations, ARRAY[native_population.name], ops.ddo_project_population(native_population.semantic_key, native_population.complete, native_population.members, native_population.evidence, demand.project_id, projection_mode));
 END LOOP;
 context := jsonb_build_object('project_id', demand.project_id, 'model', binding_model, 'roledefs', compiled['input_roles'], 'roles', roles, 'states', states, 'witnesses', witnesses, 'universe', universe, 'populations', populations, 'source_sets', coalesce(demand.selection['source_sets'], CAST('{}' AS JSONB)), 'parameters', selection['parameters'], 'parameter_meaning', selection['parameter_meaning'], 'parameterdefs', operation['parameters']['json'], 'choices', selection['choices'], 'subject', p_subject, 'original_source', request.original_source);
 inactive := ops.ddo_binding_inactive(expression, context);
 population_refs := ops.ddo_binding_population_refs(expression, context);
 SELECT coalesce(jsonb_object_agg(discovery_relation.value ->> 'target_role', discovery_relation.value ->> 'population'), CAST('{}' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(demand.selection['discovery']) AS discovery_relation(value) 
WHERE (discovery_relation.value ->> 'target') = p_operation AND (discovery_relation.value ? 'target_role') INTO discovery_refs;
 IF (EXISTS (SELECT discovery_reference.key 
FROM jsonb_each_text(discovery_refs) AS discovery_reference(key, value) 
WHERE (population_refs ? discovery_reference.key) AND (population_refs ->> discovery_reference.key) IS DISTINCT FROM discovery_reference.value)) THEN
  RAISE EXCEPTION USING MESSAGE = 'discovery input conflicts with authored population scope', ERRCODE = '23514';
 END IF;
 population_refs := population_refs || discovery_refs;
 FOR item IN SELECT population_reference.value 
FROM jsonb_array_elements(p_binding['populations']) AS population_reference(value) LOOP
  role := item ->> 'role';
  SELECT compiled_role.value 
FROM jsonb_array_elements(compiled['input_roles']) AS compiled_role(value) 
WHERE (compiled_role.value ->> 'name') = role INTO STRICT roledef;
  IF (witnesses ? role) THEN
   RAISE EXCEPTION USING MESSAGE = 'one role cannot carry two population receipt scopes', ERRCODE = '23514';
  END IF;
  witness := populations[(item ->> 'name')];
  IF (witness IS NULL OR ((witness['evidence']) ->> 'population_id') IS DISTINCT FROM (item ->> 'population_id') OR (item ->> 'name') IS DISTINCT FROM coalesce((population_refs ->> role), role)) THEN
   RAISE EXCEPTION USING MESSAGE = 'population receipt differs from exact current named closure', ERRCODE = '23514';
  END IF;
  expected := CASE WHEN ((states ->> role) = 'known-absent' OR (ops.ddo_binding_population_refs(expression, context) ? role)) THEN ops.ddo_binding_population_meaning(witness, roledef['identity_requirements'] ? 'episode') ELSE NULL END;
  IF (semantic_witnesses[role] IS DISTINCT FROM expected) THEN
   RAISE EXCEPTION USING MESSAGE = 'semantic population witness differs from native closure meaning', ERRCODE = '23514';
  END IF;
  witnesses := jsonb_set(witnesses, ARRAY[role], witness);
 END LOOP;
 FOR roledef IN SELECT compiled_role.value 
FROM jsonb_array_elements(compiled['input_roles']) AS compiled_role(value) LOOP
  role := roledef ->> 'name';
  witness := semantic_witnesses[role];
  IF (role = ANY (inactive)) THEN
   IF (jsonb_array_length(roles[role]) != 0 OR (roledef ->> 'presence') = 'required' OR (witness ->> 'reason') IS DISTINCT FROM 'unselected-declared-branch' OR witness['selection'] IS DISTINCT FROM selection['choices'] OR (witness ->> 'complete') IS DISTINCT FROM 'true') THEN
    RAISE EXCEPTION USING MESSAGE = 'unselected branch is not authenticated by frozen demand', ERRCODE = '23514';
   END IF;
   witnesses := jsonb_set(witnesses, ARRAY[role], witness);
  ELSE
   IF (witness IS NOT NULL AND NOT (witnesses ? role)) THEN
    RAISE EXCEPTION USING MESSAGE = 'population meaning lacks exact native receipt locator', ERRCODE = '23514';
   END IF;
  END IF;
 END LOOP;
 context := jsonb_set(context, ARRAY['witnesses'], witnesses);
 IF (NOT ops.ddo_binding_test(expression, context)) THEN
  RAISE EXCEPTION USING MESSAGE = 'selected native input bundles violate frozen binding', ERRCODE = '23514';
 END IF;
END

