WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'policy'))) AND NOT (((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'scores')))) AND (completion ->> 'outcome') = 'success') THEN
  IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(completion['outputs']) AS output_row(value) 
WHERE output_row.value['product']['body'] IS NOT NULL AND data.ddo_field(data.ddo_normalize(output_row.value['product']['body']), 'linguistic_observation') IS NOT DISTINCT FROM data.record_json_meaning(data.record_json_source(ops.ddo_contextual_linguistic_context()))))) THEN
   RAISE EXCEPTION USING MESSAGE = 'contextual linguistic premises changed', ERRCODE = '23514';
  END IF;
 END IF;
END

