DECLARE
 episode_ ops.data_derivation%ROWTYPE;
 intent_ ops.data_completion_intent%ROWTYPE;
 source_ ops.data_request%ROWTYPE;
 required_ jsonb;
 source_families_ jsonb;
BEGIN
 SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = episode_id_ INTO STRICT episode_;
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = episode_.intent_id INTO STRICT intent_;
 source_ := ops.ddo_require_episode_correspondence(episode_, intent_);
 IF (source_.project_id IS DISTINCT FROM current_.project_id OR source_.operation_id IS DISTINCT FROM current_.operation_id OR source_.recipe IS DISTINCT FROM current_.recipe) THEN
  RAISE EXCEPTION USING MESSAGE = 'consuming validation differs from original producer contract', ERRCODE = '23514';
 END IF;
 required_ := ops.ddo_current_validation_identities(current_.release_id, current_.operation_id);
 IF (source_.request_key IS NOT DISTINCT FROM current_.request_key AND source_.binding IS NOT DISTINCT FROM current_.binding) THEN
  source_families_ := ops.ddo_current_validation_identities(source_.release_id, source_.operation_id);
  SELECT coalesce(jsonb_object_agg(anon_1.key, anon_1.value), CAST('{}' AS JSONB)) AS coalesce_1 
FROM jsonb_each_text(required_) AS anon_1 
WHERE (source_families_ ->> anon_1.key) IS DISTINCT FROM anon_1.value INTO required_;
 END IF;
 IF (required_ != CAST('{}' AS JSONB)) THEN
  PERFORM ops.ddo_require_completion_families(current_, intent_.payload, required_);
 END IF;
 IF (required_ ? 'conservative') THEN
  IF (NOT ops.ddo_conservative_dependencies_valid(episode_id_)) THEN
   RAISE EXCEPTION USING MESSAGE = 'consuming conservative trust changed', ERRCODE = '23514';
  END IF;
 END IF;
END

