 basis jsonb;
 producer_basis jsonb;
 selected_row jsonb;
 component_row jsonb;
 relationship_row jsonb;
 component_id text;
BEGIN
 original.binding := r.binding || jsonb_build_object('inputs', completion['inputs'], 'support', completion['support']);
 basis := ops.ddo_cpu_input_basis(original);
 component_id := data.ddo_field(data.ddo_field(basis, 'parameters'), 'component_id') ->> 1;
 SELECT selected_role.value 
FROM jsonb_array_elements((data.ddo_field(basis, 'roles'))[1]) AS selected_role(value) 
WHERE (data.ddo_field(selected_role.value, 'role') ->> 1) = 'components' INTO STRICT component_row;
 SELECT selected_role.value 
FROM jsonb_array_elements((data.ddo_field(basis, 'roles'))[1]) AS selected_role(value) 
WHERE (data.ddo_field(selected_role.value, 'role') ->> 1) = 'relationship' INTO STRICT relationship_row;
 IF (component_id IS NULL OR data.ddo_field(component_row, 'member_id') IS DISTINCT FROM CAST('["null"]' AS JSONB) OR data.ddo_field(relationship_row, 'member_id') IS DISTINCT FROM CAST('["null"]' AS JSONB)) THEN
  RAISE EXCEPTION USING MESSAGE = 'contextual applicability requires exact whole component and relationship inputs', ERRCODE = '23514';
 END IF;
 PERFORM ops.ddo_definition_component_basis(component_row);
 producer_basis := ops.ddo_contextual_origin_basis(relationship_row, 'vectors');
 SELECT selected_role.value 
