WHERE (data.ddo_field(selected_role.value, 'role') ->> 1) = 'targets' AND (data.ddo_field(data.ddo_field(data.ddo_field(selected_role.value, 'body'), 'vector'), 'object_id') ->> 1) = component_id INTO STRICT selected_row;
 producer_basis := ops.ddo_contextual_origin_basis(selected_row, 'target');
 SELECT selected_role.value 
