eadline","lextype"],"title":"TextSearchParser","type":"object"},"linguistic_UnobservedLinguisticMaterial":{"additionalProperties":false,"properties":{"dictionary_file_bytes":{"const":"unobserved","title":"Dictionary File Bytes","type":"string"},"libc_build":{"const":"unobserved","title":"Libc Build","type":"string"},"locale_data_bytes":{"const":"unobserved","title":"Locale Data Bytes","type":"string"}},"required":["libc_build","locale_data_bytes","dictionary_file_bytes"],"title":"UnobservedLinguisticMaterial","type":"object"}},"properties":{"alias_lower":{"$ref":"#/definitions/linguistic_LinguisticProcedure"},"database_locale":{"$ref":"#/definitions/linguistic_DatabaseLocale"},"encoding":{"title":"Encoding","type":"string"},"policy_id":{"const":"postgres-english-default-locale-observation-1","title":"Policy Id","type":"string"},"text_search":{"$ref":"#/definitions/linguistic_TextSearchContext"},"unobserved_material":{"$ref":"#/definitions/linguistic_UnobservedLinguisticMaterial"}},"required":["policy_id","encoding","database_locale","alias_lower","text_search","unobserved_material"],"title":"LinguisticObservation","type":"object"}' AS JSON), CAST(observed AS JSON)) IS NOT true) THEN
