DECLARE
 operation sem.data_operation_definition%ROWTYPE;
BEGIN
 IF (NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id AND sem.data_operation_definition.validity_families @> ARRAY['contextual']))) THEN
  RETURN;
 END IF;
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id INTO STRICT operation;
 IF (nullif(((operation.support_contract['capabilities']['prepared_factory']) ->> 'entrypoint'), '') IS NULL OR (((operation.support_contract['capabilities']['prepared_factory']) ->> 'source_digest') ~ '^[0-9a-f]{64}$') IS NOT true OR (operation.implementation_revision LIKE 'implementation-slice:%') IS NOT true OR (operation.profile NOT IN ('derivation', 'discovery')) OR operation.recipe IS DISTINCT FROM r.recipe OR (operation.support_contract['capabilities']['forms'] NOT IN (CAST('["batch"]' AS JSONB), CAST('["scalar"]' AS JSONB))) OR ((operation.support_contract['capabilities']) ->> 'preparation') IS DISTINCT FROM 'resource' OR operation.support_contract['effects'] IS DISTINCT FROM CAST('[]' AS JSONB) OR coalesce(CAST(((operation.support_contract['capabilities']) ->> 'cpu_receipts') AS INTEGER), -1) != jsonb_array_length(coalesce(completion['execution_evidence']['cpu_receipts'], CAST('[]' AS JSONB))) OR (completion ->> 'implementation_revision') IS DISTINCT FROM operation.implementation_revision) THEN
  RAISE EXCEPTION USING MESSAGE = 'contextual completion lacks its actual admitted captured producer', ERRCODE = '23514';
 END IF;
END

