DECLARE
 output jsonb;
 actual jsonb;
BEGIN
 IF (NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id AND sem.data_operation_definition.validity_families @> ARRAY['definition']))) THEN
  RETURN;
 END IF;
 PERFORM ops.ddo_require_definition_producer(r, completion);
 actual := ops.ddo_cpu_reply_output(r, completion);
 FOR output IN SELECT outputs_.value 
FROM jsonb_array_elements(completion['outputs']) AS outputs_(value) LOOP
  IF (actual IS DISTINCT FROM data.ddo_normalize(output['product']['body'])) THEN
   RAISE EXCEPTION USING MESSAGE = 'definition publication differs from its actual exact-input CPU reply', ERRCODE = '23514';
  END IF;
 END LOOP;
 IF ((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'query'))) THEN
  PERFORM ops.ddo_require_contextual_definition_lineage(r, completion);
 END IF;
END

