DECLARE
 r ops.data_request%ROWTYPE;
 receipt ops.data_publication_receipt%ROWTYPE;
 definition sem.data_operation_definition%ROWTYPE;
BEGIN
 SELECT ops.data_publication_receipt.* 
FROM ops.data_publication_receipt 
WHERE ops.data_publication_receipt.derivation_id = producing.id AND ops.data_publication_receipt.intent_id = original.id INTO STRICT receipt;
 IF (producing.intent_id IS DISTINCT FROM original.id OR (producing.request_id, producing.generation, producing.producer_task_id, producing.producer_attempt, producing.runtime_id) IS DISTINCT FROM (original.request_id, original.generation, original.producer_task_id, original.producer_attempt, original.runtime_id)) THEN
  RAISE EXCEPTION USING MESSAGE = 'episode differs from its actual retained intent/producer', ERRCODE = '23514';
 END IF;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = producing.request_id INTO STRICT r;
 r := jsonb_populate_record(r, jsonb_build_object('release_id', producing.release_id, 'runtime_id', producing.runtime_id, 'recipe', producing.recipe, 'generation', producing.generation, 'binding', r.binding || jsonb_build_object('inputs', original.payload['inputs'], 'support', original.payload['support'])));
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id AND sem.data_operation_definition.recipe = r.recipe INTO STRICT definition;
 IF (ops.ddo_completion_state(definition, (original.payload ->> 'outcome')) IS DISTINCT FROM producing.outcome) THEN
  RAISE EXCEPTION USING MESSAGE = 'episode terminal state differs from admitted completion', ERRCODE = '23514';
 END IF;
 IF (original.payload_digest IS DISTINCT FROM ops.ddo_digest(original.payload)) THEN
  RAISE EXCEPTION USING MESSAGE = 'historical intent payload digest differs', ERRCODE = '23514';
 END IF;
 PERFORM ops.ddo_require_completion_invariants(r, original.payload, original.producer_task_id, original.producer_attempt, original.producer_holder);
 RETURN r;
END

