WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id AND sem.data_operation_definition.recipe = r.recipe INTO STRICT definition;
 IF (ops.ddo_completion_state(definition, (original.payload ->> 'outcome')) IS DISTINCT FROM producing.outcome) THEN
  RAISE EXCEPTION USING MESSAGE = 'episode terminal state differs from admitted completion', ERRCODE = '23514';
 END IF;
 IF (original.payload_digest IS DISTINCT FROM ops.ddo_digest(original.payload)) THEN
  RAISE EXCEPTION USING MESSAGE = 'historical intent payload digest differs', ERRCODE = '23514';
 END IF;
 PERFORM ops.ddo_require_completion_invariants(r, original.payload, original.producer_task_id, original.producer_attempt, original.producer_holder);
 RETURN r;
END$$

