DECLARE
 definition sem.data_operation_definition%ROWTYPE;
 receipt ops.data_external_receipt%ROWTYPE;
 packet ops.data_external_packet%ROWTYPE;
 wire jsonb;
BEGIN
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id INTO STRICT definition;
 IF (definition.support_contract['external'] IS NULL) THEN
  IF (coalesce(completion['execution_evidence']['external_receipts'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB)) THEN
   RAISE EXCEPTION USING MESSAGE = 'non-external operation cannot assert an external receipt', ERRCODE = 'P0001';
  END IF;
  RETURN;
 END IF;
 IF (jsonb_array_length(coalesce(completion['execution_evidence']['external_receipts'], CAST('[]' AS JSONB))) != 1 OR coalesce(completion['execution_evidence']['host_receipts'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB) OR coalesce(completion['execution_evidence']['cpu_receipts'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB) OR coalesce(completion['execution_evidence']['provider_receipts'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB) OR coalesce(completion['execution_evidence']['pdf_receipts'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB) OR coalesce(completion['execution_evidence']['pdf_observation_receipts'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB)) THEN
  RAISE EXCEPTION USING MESSAGE = 'external completion requires exactly its genuine native admission receipt', ERRCODE = 'P0001';
 END IF;
 wire := completion['execution_evidence']['external_receipts'][0];
 SELECT ops.data_external_receipt.* 
FROM ops.data_external_receipt 
WHERE ops.data_external_receipt.id = (wire ->> 'receipt_id') INTO STRICT receipt;
 SELECT ops.data_external_packet.* 
FROM ops.data_external_packet 
WHERE ops.data_external_packet.id = receipt.packet_id INTO STRICT packet;
 IF (wire IS DISTINCT FROM ops.ddo_external_receipt_value(receipt) OR (receipt.request_id, receipt.generation, receipt.task_id, receipt.attempt, receipt.holder) IS DISTINCT FROM (r.id, r.generation, producer_task, producer_attempt, producer_holder) OR receipt.packet_digest != packet.payload_digest OR packet.payload['binding'] IS DISTINCT FROM r.binding OR receipt.result_digest != ops.ddo_digest(completion - 'execution_evidence')) THEN
  RAISE EXCEPTION USING MESSAGE = 'external receipt is not bound to this exact packet/result/native producer', ERRCODE = 'P0001';
 END IF;
END

