DECLARE
 definition sem.data_operation_definition%ROWTYPE;
 output jsonb;
 body jsonb;
 output_role text;
 output_kind text;
 basis kb.data_product%ROWTYPE;
 producing ops.data_derivation%ROWTYPE;
 fit_request ops.data_request%ROWTYPE;
 fit_intent ops.data_completion_intent%ROWTYPE;
 selected jsonb;
 expected jsonb;
BEGIN
 IF (NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id AND sem.data_operation_definition.validity_families @> ARRAY['operation-event']))) THEN
  RETURN;
 END IF;
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id INTO STRICT definition;
 IF (ops.ddo_completion_state(definition, (completion ->> 'outcome')) IS DISTINCT FROM 'success' OR jsonb_array_length(completion['outputs']) != 1 OR completion['inputs'] IS DISTINCT FROM r.binding['inputs'] OR completion['support'] IS DISTINCT FROM r.binding['support'] OR definition.implementation_revision IS DISTINCT FROM (completion ->> 'implementation_revision') OR definition.recipe IS DISTINCT FROM r.recipe) THEN
  RAISE EXCEPTION USING MESSAGE = 'operation event completion changes exact current request/implementation', ERRCODE = '23514';
 END IF;
 output := completion['outputs'][0];
 IF (definition.command_class = 'operation_event') THEN
  IF (NOT ops.ddo_privileged_effect_admitted(definition, 'native-evaluator-operation-event-authorization')) THEN
   RAISE EXCEPTION USING MESSAGE = 'operation event authorization lacks its independent release effect grant', ERRCODE = '23514';
  END IF;
  IF (NOT coalesce(definition.command_class = 'operation_event', false) OR jsonb_array_length(completion['inputs']) != 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'operation event issuer requires exact command/effect/factory and fit basis', ERRCODE = '23514';
  END IF;
  output_role := 'parameters';
  output_kind := 'urn:corpus:kind:operation-event:parameters';
  selected := completion['inputs'][0];
  IF ((selected ->> 'role') IS DISTINCT FROM 'basis' OR (selected ->> 'member_id') IS NOT NULL OR CAST((selected ->> 'multiplicity') AS INTEGER) != 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'event issuer requires actual whole protected fit basis', ERRCODE = '23514';
  END IF;
  SELECT kb.data_product.* 
FROM kb.data_product JOIN sem.data_kind_contract ON sem.data_kind_contract.kind_contract = kb.data_product.kind_contract 
WHERE kb.data_product.id = (selected ->> 'product_id') AND kb.data_product.project_id = r.project_id AND sem.data_kind_contract.kind = 'https://corpus-structure.dev/semantic/operation-events/protected/DdoOperationEventFit' AND sem.data_kind_contract.universe = 'evaluator' INTO STRICT basis;
  SELECT ops.data_derivation.* 
FROM ops.data_derivation JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id JOIN ops.data_publication_receipt ON ops.data_publication_receipt.derivation_id = ops.data_derivation.id AND ops.data_publication_receipt.intent_id = ops.data_derivation.intent_id 
WHERE ops.data_derivation_output.product_id = basis.id AND ops.data_derivation_output.member_id IS NULL AND ops.data_derivation_output.role = 'fit' AND ops.data_derivation.outcome = 'success' AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(completion['support']) AS support(value) 
WHERE (support.value ->> 'role') = 'basis' AND (support.value ->> 'derivation_id') = ops.data_derivation.id)) AND (ops.ddo_input_support_selection(selected) ? ops.data_derivation.id) INTO STRICT producing;
  SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = producing.request_id AND ops.data_request.project_id = r.project_id AND (SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = ops.data_request.release_id AND sem.data_operation_definition.operation_id = ops.data_request.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'specification')) INTO STRICT fit_request;
  SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = producing.intent_id AND ops.data_completion_intent.request_id = producing.request_id AND ops.data_completion_intent.generation = producing.generation INTO STRICT fit_intent;
  IF ((fit_intent.producer_task_id, fit_intent.producer_attempt, fit_intent.runtime_id) IS DISTINCT FROM (producing.producer_task_id, producing.producer_attempt, producing.runtime_id)) THEN
   RAISE EXCEPTION USING MESSAGE = 'event fit differs from original producer fences', ERRCODE = '23514';
  END IF;
  fit_request.release_id := producing.release_id;
  fit_request.runtime_id := producing.runtime_id;
  fit_request.recipe := producing.recipe;
  fit_request.generation := producing.generation;
  fit_request.binding := fit_request.binding || jsonb_build_object('inputs', fit_intent.payload['inputs'], 'support', fit_intent.payload['support']);
  PERFORM ops.ddo_require_operation_event_completion(fit_request, fit_intent.payload);
  IF (data.ddo_normalize(fit_intent.payload['outputs'][0]['product']['body']) IS DISTINCT FROM basis.canonical_body OR (((data.ddo_json(basis.canonical_body))['result']) ->> 'status') IS DISTINCT FROM 'fitted') THEN
   RAISE EXCEPTION USING MESSAGE = 'event issuer basis differs from actual successful protected CPU fit', ERRCODE = '23514';
  END IF;
  expected := data.ddo_field(data.ddo_field(basis.canonical_body, 'result'), 'parameters');
  IF (expected = CAST('["null"]' AS JSONB) OR data.ddo_normalize(output['product']['body']) IS DISTINCT FROM expected) THEN
   RAISE EXCEPTION USING MESSAGE = 'event issuer may disclose only exact fitted strict parameters', ERRCODE = '23514';
  END IF;
 ELSE
  output_role := CASE WHEN ((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'question'))) THEN 'frame' WHEN ((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'specification'))) THEN 'fit' ELSE 'probability' END;
  output_kind := 'https://corpus-structure.dev/semantic/operation-events/protected/' || CASE WHEN (((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'question')))) THEN 'DdoOperationEventFrame' ELSE 'DdoOperationEventFit' END;
  IF (definition.profile IS DISTINCT FROM 'derivation' OR definition.support_contract['effects'] IS DISTINCT FROM CAST('[]' AS JSONB) OR nullif(((definition.support_contract['capabilities']['prepared_factory']) ->> 'entrypoint'), '') IS NULL OR (((definition.support_contract['capabilities']['prepared_factory']) ->> 'source_digest') ~ '^[0-9a-f]{64}$') IS NOT true OR (definition.implementation_revision LIKE 'implementation-slice:%') IS NOT true OR jsonb_array_length(coalesce(completion['execution_evidence']['cpu_receipts'], CAST('[]' AS JSONB))) != 1 OR data.ddo_normalize(output['product']['body']) IS DISTINCT FROM ops.ddo_cpu_reply_output(r, completion)) THEN
   RAISE EXCEPTION USING MESSAGE = 'event conclusion differs from actual admitted CPU body/factory/receipt', ERRCODE = '23514';
  END IF;
  body := data.ddo_json(output['product']['body']);
  IF ((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'question'))) THEN
   PERFORM ops.ddo_operation_event_require_frame(r, body);
  ELSE
   IF ((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'specification'))) THEN
    PERFORM ops.ddo_operation_event_require_fit(r, body);
   ELSE
    PERFORM ops.ddo_operation_event_require_parameters(r);
   END IF;
  END IF;
 END IF;
 IF ((output ->> 'role') IS DISTINCT FROM output_role OR (output ->> 'member_id') IS NOT NULL OR CAST((output ->> 'position') AS INTEGER) IS DISTINCT FROM 0 OR CAST((output ->> 'multiplicity') AS INTEGER) IS DISTINCT FROM 1 OR output['product']['members'] IS DISTINCT FROM CAST('[]' AS JSONB) OR NOT (EXISTS (SELECT 1 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = ((output['product']) ->> 'kind_contract') AND CASE WHEN (NOT (((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'question')))) AND NOT (((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'specification'))))) THEN sem.data_kind_contract.kind_contract = ((definition.output_roles[0]) ->> 'kind_contract') ELSE sem.data_kind_contract.kind = output_kind END AND sem.data_kind_contract.kind_contract = ((definition.output_roles[0]) ->> 'kind_contract')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'event output changes exact finite whole nominal contract', ERRCODE = '23514';
 END IF;
END

