  IF (receipts != CAST('[]' AS JSONB) OR observations != CAST('[]' AS JSONB)) THEN
   RAISE EXCEPTION USING MESSAGE = 'non-PDF computation cannot acquire a PDF execution event', ERRCODE = '23514';
  END IF;
  RETURN;
 END IF;
 IF (NOT coalesce(definition.command_class = 'pdf', false)) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF completion requires its exact approved command/effect/factory pair', ERRCODE = '23514';
