WHERE ops.data_request.id = context.request_id AND ops.data_request.operation_id = p_operation AND ops.data_request.release_id = p_release))) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF completion differs from actual request owner', ERRCODE = '23514';
 END IF;
 IF (ops.ddo_completion_state(definition, (p_completion ->> 'outcome')) IN ('failed', 'empty')) THEN
  IF (receipts != CAST('[]' AS JSONB) OR observations != CAST('[]' AS JSONB) OR p_completion['outputs'] != CAST('[]' AS JSONB)) THEN
   RAISE EXCEPTION USING MESSAGE = 'non-success PDF completion cannot publish receipts or outputs', ERRCODE = '23514';
  END IF;
  RETURN;
 END IF;
 IF (((definition.support_contract['effects'][0]) ->> 'name') = 'retain_pdf_observations') THEN
  IF (receipts != CAST('[]' AS JSONB) OR jsonb_array_length(observations) IS DISTINCT FROM 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'recognition completion requires only its actual observation-set receipt', ERRCODE = '23514';
  END IF;
  IF (((observations[0]) ->> 'runtime_id') IS DISTINCT FROM ((p_completion['execution_evidence']) ->> 'runtime_id')) THEN
   RAISE EXCEPTION USING MESSAGE = 'observation adoption changes its actual completion runtime', ERRCODE = '23514';
  END IF;
 ELSE
  IF (observations != CAST('[]' AS JSONB) OR jsonb_array_length(receipts) IS DISTINCT FROM 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'sealed PDF completion requires only its actual publication receipt', ERRCODE = '23514';
  END IF;
 END IF;
 IF (jsonb_array_length(p_completion['outputs']) IS DISTINCT FROM 1) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF completion requires one whole-product output', ERRCODE = '23514';
 END IF;
 output := p_completion['outputs'][0];
 IF ((output ->> 'member_id') IS NOT NULL OR (output ->> 'position') IS DISTINCT FROM '0' OR (output ->> 'multiplicity') IS DISTINCT FROM '1' OR output['product']['members'] IS DISTINCT FROM CAST('[]' AS JSONB)) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF completion must name its one whole product', ERRCODE = '23514';
