 expected := CASE WHEN (((definition.support_contract['effects'][0]) ->> 'name') = 'retain_pdf_observations') THEN ops.pdf_observation_projection(observations[0], p_task, p_attempt, p_holder) ELSE ops.pdf_publication_projection(receipts[0], p_task, p_attempt, p_holder) END;
 IF (data.ddo_json(output['product']['body']) IS DISTINCT FROM expected) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF output differs from authentic native effect projection', ERRCODE = '23514';
 END IF;
END

