DECLARE
 definition sem.data_operation_definition%ROWTYPE;
 selected jsonb;
 output jsonb;
 basis kb.data_product%ROWTYPE;
 basis_kind sem.data_kind_contract%ROWTYPE;
 producing ops.data_derivation%ROWTYPE;
 fit_definition sem.data_operation_definition%ROWTYPE;
 fit_intent ops.data_completion_intent%ROWTYPE;
 fit_request ops.data_request%ROWTYPE;
 expected jsonb;
BEGIN
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id INTO STRICT definition;
 IF (NOT coalesce(definition.command_class = 'policy', false)) THEN
  IF (EXISTS (SELECT 1 
FROM jsonb_array_elements(definition.support_contract['effects']) AS effect(value) 
WHERE (effect.value ->> 'name') = 'native-evaluator-policy-authorization')) THEN
   RAISE EXCEPTION USING MESSAGE = 'policy authorization requires its exact admitted command/effect/factory', ERRCODE = '23514';
  END IF;
  RETURN;
 END IF;
 IF (NOT ops.ddo_privileged_effect_admitted(definition, 'native-evaluator-policy-authorization')) THEN
  RAISE EXCEPTION USING MESSAGE = 'policy authorization lacks its independent release effect grant', ERRCODE = '42501';
 END IF;
 IF ((completion ->> 'outcome') IS DISTINCT FROM 'success' OR jsonb_array_length(completion['inputs']) != 1 OR jsonb_array_length(completion['outputs']) != 1) THEN
  RAISE EXCEPTION USING MESSAGE = 'policy authorization requires one exact fitted basis and public conclusion', ERRCODE = '23514';
 END IF;
 selected := completion['inputs'][0];
 output := completion['outputs'][0];
 IF ((selected ->> 'role') IS DISTINCT FROM 'basis' OR (selected ->> 'member_id') IS NOT NULL OR CAST((selected ->> 'position') AS INTEGER) IS DISTINCT FROM 0 OR CAST((selected ->> 'multiplicity') AS INTEGER) IS DISTINCT FROM 1 OR (output ->> 'role') IS DISTINCT FROM 'authorization' OR (output ->> 'member_id') IS NOT NULL OR CAST((output ->> 'position') AS INTEGER) IS DISTINCT FROM 0 OR CAST((output ->> 'multiplicity') AS INTEGER) IS DISTINCT FROM 1 OR output['product']['members'] IS DISTINCT FROM CAST('[]' AS JSONB)) THEN
  RAISE EXCEPTION USING MESSAGE = 'policy authorization must consume and produce exact whole scalar products', ERRCODE = '23514';
 END IF;
 SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = (selected ->> 'product_id') AND kb.data_product.project_id = r.project_id INTO STRICT basis;
 SELECT sem.data_kind_contract.* 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = basis.kind_contract INTO STRICT basis_kind;
 IF (basis_kind.kind IS DISTINCT FROM 'https://corpus-structure.dev/semantic/data-operation-record-policy/protected/DdoFittedRecordPolicy' OR basis_kind.universe IS DISTINCT FROM 'evaluator') THEN
  RAISE EXCEPTION USING MESSAGE = 'policy basis is not the protected fitted contract', ERRCODE = '23514';
 END IF;
 IF ((SELECT count(*) AS count_1 
FROM ops.data_derivation JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id JOIN ops.data_publication_receipt ON ops.data_publication_receipt.derivation_id = ops.data_derivation.id AND ops.data_publication_receipt.intent_id = ops.data_derivation.intent_id 
WHERE ops.data_derivation_output.product_id = basis.id AND ops.data_derivation_output.member_id IS NULL AND ops.data_derivation_output.role = 'fitted' AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(completion['support']) AS support(value) 
WHERE (support.value ->> 'derivation_id') = ops.data_derivation.id)) AND (ops.ddo_input_support_selection(selected) ? ops.data_derivation.id) AND ops.data_derivation_output.position = 0 AND ops.data_derivation_output.multiplicity = 1 AND ops.data_derivation.outcome = 'success') != 1) THEN
  RAISE EXCEPTION USING MESSAGE = 'policy basis lacks one exact supported successful native fit receipt', ERRCODE = '23514';
 END IF;
 SELECT ops.data_derivation.* 
FROM ops.data_derivation JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id 
WHERE ops.data_derivation_output.product_id = basis.id AND ops.data_derivation_output.member_id IS NULL AND ops.data_derivation_output.role = 'fitted' AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(completion['support']) AS support(value) 
WHERE (support.value ->> 'derivation_id') = ops.data_derivation.id)) AND (ops.ddo_input_support_selection(selected) ? ops.data_derivation.id) INTO STRICT producing;
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition JOIN ops.data_request ON ops.data_request.operation_id = sem.data_operation_definition.operation_id 
WHERE ops.data_request.id = producing.request_id AND ops.data_request.project_id = r.project_id AND sem.data_operation_definition.release_id = producing.release_id INTO STRICT fit_definition;
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = producing.intent_id AND ops.data_completion_intent.request_id = producing.request_id AND ops.data_completion_intent.generation = producing.generation INTO STRICT fit_intent;
 IF ((fit_intent.producer_task_id, fit_intent.producer_attempt, fit_intent.runtime_id) IS DISTINCT FROM (producing.producer_task_id, producing.producer_attempt, producing.runtime_id)) THEN
  RAISE EXCEPTION USING MESSAGE = 'policy fit basis differs from original producer fences', ERRCODE = '23514';
 END IF;
 IF (NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = fit_definition.release_id AND sem.data_operation_definition.operation_id = fit_definition.operation_id AND (sem.data_operation_definition.validity_families @> ARRAY['record-fit']))) OR fit_definition.profile IS DISTINCT FROM 'derivation' OR fit_definition.support_contract['effects'] IS DISTINCT FROM CAST('[]' AS JSONB) OR nullif(((fit_definition.support_contract['capabilities']['prepared_factory']) ->> 'entrypoint'), '') IS NULL OR (((fit_definition.support_contract['capabilities']['prepared_factory']) ->> 'source_digest') ~ '^[0-9a-f]{64}$') IS NOT true OR (fit_definition.implementation_revision LIKE 'implementation-slice:%') IS NOT true OR (fit_intent.payload ->> 'implementation_revision') IS DISTINCT FROM fit_definition.implementation_revision OR jsonb_array_length(coalesce(fit_intent.payload['execution_evidence']['cpu_receipts'], CAST('[]' AS JSONB))) != 1 OR producing.recipe IS DISTINCT FROM fit_definition.recipe) THEN
  RAISE EXCEPTION USING MESSAGE = 'policy basis is not the actual admitted protected CPU fit implementation', ERRCODE = '23514';
 END IF;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = producing.request_id AND ops.data_request.project_id = r.project_id INTO STRICT fit_request;
 fit_request := jsonb_populate_record(fit_request, jsonb_build_object('release_id', producing.release_id, 'runtime_id', producing.runtime_id, 'recipe', producing.recipe, 'generation', producing.generation, 'binding', fit_request.binding || jsonb_build_object('inputs', fit_intent.payload['inputs'], 'support', fit_intent.payload['support'])));
 PERFORM ops.ddo_require_record_fit_completion(fit_request, fit_intent.payload);
 IF (data.ddo_normalize(fit_intent.payload['outputs'][0]['product']['body']) IS DISTINCT FROM basis.canonical_body) THEN
  RAISE EXCEPTION USING MESSAGE = 'policy basis differs from actual original fitted completion body', ERRCODE = '23514';
 END IF;
 expected := ops.ddo_policy_authorization_value(data.ddo_json(basis.canonical_body));
 IF (((expected['applicability']) ->> 'project_id') IS DISTINCT FROM r.project_id OR NOT sem.ddo_model_class_contract(r.release_id, (expected ->> 'family_contract')) OR NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.recipe = (expected ->> 'reading_recipe') AND sem.data_operation_definition.profile = 'derivation' AND sem.data_operation_definition.support_contract['effects'] = CAST('[]' AS JSONB))) OR NOT (EXISTS (SELECT 1 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = ((output['product']) ->> 'kind_contract') AND sem.data_kind_contract.kind = 'https://corpus-structure.dev/semantic/data-operation-record-policy/DdoRecordPolicyAuthorization' AND sem.data_kind_contract.universe = 'ordinary')) OR data.ddo_normalize(output['product']['body']) IS DISTINCT FROM ops.ddo_policy_authorization_meaning(basis.canonical_body)) THEN
  RAISE EXCEPTION USING MESSAGE = 'policy authorization public conclusion differs from exact fitted basis and current interpretation', ERRCODE = '23514';
 END IF;
END

