DECLARE
 retained ops.data_demand_read_scope%ROWTYPE;
 epoch bigint;
 snapshot jsonb := CAST('{}' AS JSONB);
BEGIN
 IF (NOT coalesce(ops.ddo_read_acquisition_present(boundary), false)) THEN
  RAISE EXCEPTION USING MESSAGE = 'read requires reacquisition under current native kernel', ERRCODE = '23514';
 END IF;
 FOR retained IN SELECT ops.data_demand_read_scope.read_id, ops.data_demand_read_scope.scope, ops.data_demand_read_scope.epoch, ops.data_demand_read_scope.ordinary, ops.data_demand_read_scope.domain 
FROM ops.data_demand_read_scope 
WHERE ops.data_demand_read_scope.read_id = boundary.id AND (NOT ordinary_only OR ops.data_demand_read_scope.ordinary) ORDER BY ops.data_demand_read_scope.scope LOOP
  SELECT ops.data_trust_scope.epoch 
FROM ops.data_trust_scope 
WHERE ops.data_trust_scope.scope = retained.scope AND ops.data_trust_scope.project_id = project FOR SHARE INTO STRICT epoch;
  IF (epoch != retained.epoch) THEN
   RAISE EXCEPTION USING MESSAGE = 'read trust changed; reacquire demand read', ERRCODE = '23514';
  END IF;
  snapshot := snapshot || jsonb_build_object(retained.scope, epoch);
 END LOOP;
 RETURN snapshot;
END

