FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id AND sem.data_operation_definition.validity_families @> ARRAY['record-fit']))) THEN
  RETURN;
 END IF;
 PERFORM ops.ddo_record_fit_require_producer(r, completion);
 cpu_output := data.ddo_field(ops.ddo_cpu_reply_output(r, completion), 'fitted');
 FOR selected IN SELECT anon_1.role_name, anon_1.selection 
FROM ops.ddo_record_fit_selections(r) AS anon_1 LOOP
  IF (selected.role_name = 'feature_grade') THEN
   feature := ops.ddo_record_fit_require_selection(r, selected.role_name, selected.selection, true);
  ELSE
   calibration := ops.ddo_record_fit_require_selection(r, selected.role_name, selected.selection, true);
  END IF;
 END LOOP;
 IF ((completion ->> 'outcome') = 'empty') THEN
  IF (cpu_output IS DISTINCT FROM CAST('["null"]' AS JSONB)) THEN
   RAISE EXCEPTION USING MESSAGE = 'empty fit differs from its actual CPU result', ERRCODE = '23514';
  END IF;
  RETURN;
 END IF;
 output := completion['outputs'][0];
 IF (cpu_output IS DISTINCT FROM data.ddo_normalize(output['product']['body'])) THEN
  RAISE EXCEPTION USING MESSAGE = 'fitted policy differs from its actual CPU result', ERRCODE = '23514';
 END IF;
 SELECT kb.data_product.canonical_body 
FROM jsonb_array_elements(r.binding['inputs']) AS chosen(value) JOIN kb.data_product ON kb.data_product.id = (chosen.value ->> 'product_id') AND kb.data_product.project_id = r.project_id 
WHERE (chosen.value ->> 'role') = 'specification' AND (chosen.value ->> 'member_id') IS NULL AND CAST((chosen.value ->> 'multiplicity') AS INTEGER) = 1 INTO STRICT specification;
 PERFORM ops.ddo_require_record_fit_correspondence(feature, calibration, specification, data.ddo_normalize(output['product']['body']));
 PERFORM ops.ddo_policy_authorization_value(data.ddo_json(output['product']['body']));
END

