DECLARE
 feature_grade jsonb := data.ddo_json(feature_meaning);
 calibration_grade jsonb := data.ddo_json(calibration_meaning);
 specification jsonb := data.ddo_json(specification_meaning);
 basis jsonb := data.ddo_json(basis_meaning);
 first_ jsonb := feature_grade['frame'];
 second_ jsonb := calibration_grade['frame'];
 instance_meaning jsonb := data.ddo_field(basis_meaning, 'instance');
 instance jsonb := basis['instance'];
 feature jsonb := instance['feature'];
 calibration jsonb := instance['calibration'];
 feature_coverage text;
 calibration_coverage text;
 judgment_basis text;
 first_positive bigint;
 first_negative bigint;
 first_groups bigint;
 second_positive bigint;
 second_negative bigint;
 second_groups bigint;
 wrong_final boolean;
BEGIN
 feature_coverage := ops.ddo_digest(first_['coverage']);
 calibration_coverage := ops.ddo_digest(second_['coverage']);
 judgment_basis := ops.ddo_digest(data.ddo_normalize(jsonb_build_array('sequence', jsonb_build_array(jsonb_build_array('string', feature_grade ->> 'frame_digest'), jsonb_build_array('string', calibration_grade ->> 'frame_digest'), specification_meaning))));
 IF (data.ddo_field(instance_meaning, 'feature') IS DISTINCT FROM data.ddo_field(specification_meaning, 'frozen_feature') OR data.ddo_field(instance_meaning, 'threshold') IS DISTINCT FROM data.ddo_field(specification_meaning, 'threshold') OR data.ddo_field(instance_meaning, 'threshold_procedure') IS DISTINCT FROM data.ddo_field(specification_meaning, 'threshold_procedure') OR data.ddo_field(instance_meaning, 'conditioning_assumptions') IS DISTINCT FROM data.ddo_field(specification_meaning, 'assumptions') OR data.ddo_field(basis_meaning, 'applicability') IS DISTINCT FROM data.ddo_field(specification_meaning, 'applicability') OR data.ddo_field(basis_meaning, 'family_contract') IS DISTINCT FROM data.ddo_field(specification_meaning, 'family_contract') OR data.ddo_field(basis_meaning, 'reading_recipe') IS DISTINCT FROM data.ddo_field(specification_meaning, 'reading_recipe') OR (basis ->> 'judgment_basis_digest') IS DISTINCT FROM judgment_basis) THEN
