CREATE OR REPLACE FUNCTION ops.ddo_require_rich_admission_completion(r ops.data_request, completion jsonb) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 basis jsonb;
 admission_meaning jsonb;
 admission jsonb;
 consolidated_meaning jsonb;
 consolidated jsonb;
 consolidation_basis jsonb;
 selected jsonb;
 resolution_basis jsonb;
 reference jsonb;
 decision jsonb;
 raw_meaning jsonb;
 resolved_meaning jsonb;
 raw_record jsonb;
 resolved_record jsonb;
 resolution_meaning jsonb;
 report jsonb;
 policy_meaning jsonb;
 policy jsonb;
 events jsonb;
 event jsonb;
 item jsonb;
 packet jsonb;
 raw_comparison jsonb;
 resolved_comparison jsonb;
 assertion jsonb;
 known_meaning jsonb;
 known_graph jsonb;
 reports jsonb := CAST('{}' AS JSONB);
 raw_reports jsonb := CAST('{}' AS JSONB);
 policies jsonb := CAST('{}' AS JSONB);
 known_packets jsonb := CAST('{}' AS JSONB);
 consolidation_request ops.data_request%ROWTYPE;
 authorization_request ops.data_request%ROWTYPE;
 resolution_request ops.data_request%ROWTYPE;
 known_request ops.data_request%ROWTYPE;
 authorization_episode text;
 known_episode text;
 raw_digest text;
 family_contract text;
BEGIN
 IF (NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id AND ops.ddo_privileged_effect_admitted(data_operation_definition, 'native-rich-knowledge-admission')))) THEN
  IF (EXISTS (SELECT 1 
FROM sem.data_operation_definition JOIN jsonb_array_elements(sem.data_operation_definition.support_contract['effects']) AS effect(value) ON true 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id AND (effect.value ->> 'name') = 'native-rich-knowledge-admission')) THEN
   RAISE EXCEPTION USING MESSAGE = 'rich admission effect requires its actual operation owner', ERRCODE = '23514';
  END IF;
  RETURN;
 END IF;
 PERFORM ops.ddo_rich_require_admission_producer(r, completion);
 basis := ops.ddo_cpu_input_basis(r);
 admission_meaning := data.ddo_normalize(completion['outputs'][0]['product']['body']);
 IF (ops.ddo_cpu_reply_output(r, completion) IS DISTINCT FROM admission_meaning) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich admission differs from exact CPU decision and graph projection', ERRCODE = '23514';
 END IF;
 admission := data.ddo_json(admission_meaning);
 consolidated_meaning := ops.ddo_rich_selected_value(r.project_id, basis, 'consolidation', admission['consolidation']);
 consolidated := data.ddo_json(consolidated_meaning);
 consolidation_request := ops.ddo_rich_producing_request(r, admission['consolidation'], 'consolidation');
 SELECT ops.data_completion_intent.payload 
FROM ops.data_derivation JOIN ops.data_completion_intent ON ops.data_completion_intent.id = ops.data_derivation.intent_id 
WHERE ops.data_derivation.request_id = consolidation_request.id AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(admission['consolidation']['support_references']) AS support(value) 
WHERE (support.value ->> 'derivation_id') = ops.data_derivation.id)) INTO STRICT item;
 IF (ops.ddo_cpu_reply_output(consolidation_request, item) IS DISTINCT FROM consolidated_meaning) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich consolidation differs from actual original CPU graph reply', ERRCODE = '23514';
 END IF;
 consolidation_basis := ops.ddo_cpu_input_basis(consolidation_request);
 IF ((consolidated ->> 'version') IS DISTINCT FROM 'rich-consolidation-1' OR (consolidated ->> 'standing') IS DISTINCT FROM 'private-consolidated' OR (admission ->> 'version') IS DISTINCT FROM 'rich-admission-1' OR (admission ->> 'standing') IS DISTINCT FROM 'accepted' OR ops.ddo_rich_role_population(basis, 'records') IS DISTINCT FROM ops.ddo_rich_role_population(consolidation_basis, 'records') OR ops.ddo_rich_role_population(basis, 'readings') IS DISTINCT FROM ops.ddo_rich_role_population(consolidation_basis, 'readings')) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich admission changes actual consolidated records/readings population or producer custody', ERRCODE = '23514';
 END IF;
 IF ((admission ->> 'eligibility_policy_digest') IS NULL OR ((admission ->> 'eligibility_policy_digest') !~ '^[0-9a-f]{64}$') OR (admission ->> 'eligibility_policy_digest') IS DISTINCT FROM ((consolidated['eligibility']) ->> 'eligibility_policy_digest') OR admission['selected_fact_ids'] IS DISTINCT FROM consolidated['eligibility']['selected_fact_ids'] OR admission['selected_occurrence_ids'] IS DISTINCT FROM consolidated['eligibility']['selected_occurrence_ids'] OR admission['scientific_representatives'] IS DISTINCT FROM consolidated['eligibility']['scientific_representatives']) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich admission changes actual rule eligibility or its checked policy basis', ERRCODE = '23514';
 END IF;
 PERFORM ops.ddo_rich_require_proposal_inputs(consolidation_request, consolidation_basis);
 FOR selected IN SELECT header.value 
FROM ops.ddo_rich_role_headers(consolidation_basis) AS header(value) 
WHERE (header.value ->> 'role') = 'known_universe' LOOP
  reference := jsonb_build_object('product_id', selected ->> 'product_id', 'member_id', NULL, 'kind_contract', selected ->> 'kind_contract', 'support_references', selected['support']);
  known_request := ops.ddo_rich_producing_request(consolidation_request, reference, 'known_universe');
  SELECT ops.data_derivation.id 
FROM ops.data_derivation 
WHERE ops.data_derivation.request_id = known_request.id AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(reference['support_references']) AS support(value) 
WHERE (support.value ->> 'derivation_id') = ops.data_derivation.id)) INTO STRICT known_episode;
  IF (NOT ops.ddo_rich_admission_dependencies_valid(known_episode)) THEN
   RAISE EXCEPTION USING MESSAGE = 'rich known universe lacks actual sealed native admission authority', ERRCODE = '23514';
  END IF;
  SELECT kb.data_product.canonical_body 
FROM kb.data_product 
WHERE kb.data_product.id = (reference ->> 'product_id') AND kb.data_product.project_id = r.project_id INTO STRICT known_meaning;
  known_graph := data.ddo_json(known_meaning);
  IF ((known_graph ->> 'eligibility_policy_digest') IS DISTINCT FROM (admission ->> 'eligibility_policy_digest') OR jsonb_typeof(known_graph['selected_reading_ids']) IS DISTINCT FROM 'array') THEN
   RAISE EXCEPTION USING MESSAGE = 'rich known eligibility requires its actual current policy basis and selection', ERRCODE = '23514';
  END IF;
  FOR packet IN SELECT known_member.value 
FROM jsonb_array_elements((data.ddo_field(known_meaning, 'members'))[1]) AS known_member(value) 
WHERE data.ddo_field(data.ddo_field(known_member.value, 'body'), 'member_type') = CAST('["string","source-reading-assertion"]' AS JSONB) AND known_graph['selected_reading_ids'] ? (data.ddo_field(known_member.value, 'member_id') ->> 1) LOOP
   known_packets := known_packets || jsonb_build_object(ops.ddo_digest(data.ddo_normalize(packet)), data.ddo_normalize(packet));
  END LOOP;
 END LOOP;
 IF ((EXISTS (SELECT 1 
FROM jsonb_array_elements((data.ddo_field(admission_meaning, 'members'))[1]) AS admitted_member(value) 
WHERE NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements((data.ddo_field(consolidated_meaning, 'members'))[1]) AS original_member(value) 
WHERE data.ddo_normalize(original_member.value) = data.ddo_normalize(admitted_member.value))))) OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(admission['members']) AS member(value) GROUP BY (member.value ->> 'member_id') 
HAVING count(*) != 1))) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich admission changes actual consolidated graph members', ERRCODE = '23514';
 END IF;
 IF (jsonb_array_length(admission['policy_authorizations']) IS DISTINCT FROM jsonb_array_length(ops.ddo_rich_role_population(basis, 'policy_authorizations'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich policy population differs from actual declared authorizations', ERRCODE = '23514';
 END IF;
 FOR reference IN SELECT policy_reference.value 
FROM jsonb_array_elements(admission['policy_authorizations']) AS policy_reference(value) LOOP
  IF ((reference ->> 'member_id') IS NOT NULL OR (policies ? (reference ->> 'product_id'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'rich policy requires unique whole issued authorizations', ERRCODE = '23514';
  END IF;
  policy_meaning := ops.ddo_rich_selected_value(r.project_id, basis, 'policy_authorizations', reference);
  authorization_request := ops.ddo_rich_producing_request(r, reference, 'policy_authorizations');
  IF (NOT (EXISTS (SELECT 1 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = (reference ->> 'kind_contract') AND sem.data_kind_contract.kind = 'https://corpus-structure.dev/semantic/data-operation-record-policy/DdoRecordPolicyAuthorization' AND sem.data_kind_contract.universe = 'ordinary'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'rich policy is not the actual public authorization contract', ERRCODE = '23514';
  END IF;
  SELECT ops.data_derivation.id 
FROM ops.data_derivation JOIN ops.data_completion_intent ON ops.data_completion_intent.id = ops.data_derivation.intent_id 
WHERE ops.data_derivation.request_id = authorization_request.id AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(reference['support_references']) AS support(value) 
WHERE (support.value ->> 'derivation_id') = ops.data_derivation.id)) INTO STRICT authorization_episode;
  IF (ops.ddo_policy_authority_leaf(authorization_episode) IS NOT true) THEN
   RAISE EXCEPTION USING MESSAGE = 'rich policy lacks its authentic issued public authorization', ERRCODE = '23514';
  END IF;
  policies := policies || jsonb_build_object((reference ->> 'product_id'), jsonb_build_object('reference', reference, 'body', data.ddo_json(policy_meaning)));
 END LOOP;
 FOR selected IN SELECT header.value 
FROM ops.ddo_rich_role_headers(consolidation_basis) AS header(value) 
WHERE (header.value ->> 'role') = 'records' LOOP
  reference := jsonb_build_object('product_id', selected ->> 'product_id', 'member_id', NULL, 'kind_contract', selected ->> 'kind_contract', 'support_references', selected['support']);
  PERFORM ops.ddo_rich_producing_request(r, reference, 'records');
  SELECT ops.ddo_digest(kb.data_product.canonical_body) AS ddo_digest_1 
FROM kb.data_product 
WHERE kb.data_product.id = (selected ->> 'product_id') AND kb.data_product.project_id = r.project_id INTO STRICT raw_digest;
  raw_reports := raw_reports || jsonb_build_object((selected ->> 'product_id'), raw_digest);
 END LOOP;
 FOR selected IN SELECT header.value 
FROM ops.ddo_rich_role_headers(consolidation_basis) AS header(value) 
WHERE (header.value ->> 'role') = 'readings' LOOP
  reference := jsonb_build_object('product_id', selected ->> 'product_id', 'member_id', NULL, 'kind_contract', selected ->> 'kind_contract', 'support_references', selected['support']);
  resolution_request := ops.ddo_rich_producing_request(r, reference, 'readings');
  resolution_basis := ops.ddo_cpu_input_basis(resolution_request);
  resolution_meaning := ops.ddo_rich_selected_value(r.project_id, consolidation_basis, 'readings', reference);
  SELECT ops.data_completion_intent.payload 
FROM ops.data_derivation JOIN ops.data_completion_intent ON ops.data_completion_intent.id = ops.data_derivation.intent_id 
WHERE ops.data_derivation.request_id = resolution_request.id AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(reference['support_references']) AS support(value) 
WHERE (support.value ->> 'derivation_id') = ops.data_derivation.id)) INTO STRICT item;
  IF (ops.ddo_cpu_reply_output(resolution_request, item) IS DISTINCT FROM resolution_meaning) THEN
   RAISE EXCEPTION USING MESSAGE = 'rich final-event report differs from actual original reading CPU reply', ERRCODE = '23514';
  END IF;
  report := data.ddo_json(resolution_meaning);
  events := (CAST(report ->> 'diagnostics_json' AS JSONB))['record_policy_events'];
  IF (jsonb_typeof(events) IS DISTINCT FROM 'array' OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(events) AS event_row(value) GROUP BY (event_row.value ->> 'record_id'), (event_row.value ->> 'interpretation_id') 
HAVING count(*) != 1))) THEN
   RAISE EXCEPTION USING MESSAGE = 'rich resolution requires unique actual final-event attribution', ERRCODE = '23514';
  END IF;
  SELECT coalesce(jsonb_object_agg(data.canonical_json(jsonb_build_array(event_row.value ->> 'record_id', event_row.value ->> 'interpretation_id')), event_row.value), CAST('{}' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(events) AS event_row(value) INTO events;
  reports := reports || jsonb_build_object((reference ->> 'product_id'), jsonb_build_object('inputs', (SELECT coalesce(jsonb_agg(resolution_header.value), CAST('[]' AS JSONB)) AS coalesce_1 
FROM ops.ddo_rich_role_headers(resolution_basis) AS resolution_header(value)), 'release_id', resolution_request.release_id, 'recipe', resolution_request.recipe, 'events', events));
 END LOOP;
 IF (EXISTS (SELECT 1 
FROM ops.ddo_rich_role_headers(consolidation_basis) AS header(value) JOIN kb.data_product_member ON kb.data_product_member.product_id = (header.value ->> 'product_id') 
WHERE (header.value ->> 'role') = 'records' AND data.ddo_field(kb.data_product_member.body, 'candidate_type') = CAST('["string","record"]' AS JSONB) AND (SELECT count(*) AS count_1 
FROM jsonb_array_elements(admission['reading_decisions']) AS judgment(value) 
WHERE ((judgment.value['original']) ->> 'product_id') = kb.data_product_member.product_id AND ((judgment.value['original']) ->> 'member_id') = kb.data_product_member.member_id) != 1)) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich decision census omits or duplicates actual raw records', ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM ops.ddo_rich_role_headers(consolidation_basis) AS header(value) JOIN kb.data_product_member ON kb.data_product_member.product_id = (header.value ->> 'product_id') 
WHERE (header.value ->> 'role') = 'readings' AND data.ddo_field(kb.data_product_member.body, 'candidate_type') = CAST('["string","record"]' AS JSONB) AND (SELECT count(*) AS count_1 
FROM jsonb_array_elements(admission['reading_decisions']) AS judgment(value) 
WHERE ((judgment.value['resolved']) ->> 'product_id') = kb.data_product_member.product_id AND ((judgment.value['resolved']) ->> 'member_id') = kb.data_product_member.member_id) != 1)) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich decision census omits or duplicates actual resolved records', ERRCODE = '23514';
 END IF;
 FOR decision IN SELECT judgment.value 
FROM jsonb_array_elements(admission['reading_decisions']) AS judgment(value) LOOP
  raw_meaning := ops.ddo_rich_selected_value(r.project_id, consolidation_basis, 'records', decision['original']);
  raw_record := data.ddo_json(raw_meaning);
  IF ((raw_record ->> 'candidate_type') IS DISTINCT FROM 'record' OR ((decision['original']) ->> 'member_id') IS NULL OR (raw_record ->> 'record_id') IS DISTINCT FROM (decision ->> 'record_id') OR (raw_record ->> 'interpretation_id') IS DISTINCT FROM (decision ->> 'source_interpretation_id')) THEN
   RAISE EXCEPTION USING MESSAGE = 'rich decision relabels actual original record attribution', ERRCODE = '23514';
  END IF;
  IF (decision['resolution'] = CAST('null' AS JSONB) OR decision['resolved'] = CAST('null' AS JSONB)) THEN
   IF (decision['resolution'] IS DISTINCT FROM CAST('null' AS JSONB) OR decision['resolved'] IS DISTINCT FROM CAST('null' AS JSONB) OR (decision ->> 'outcome') IS DISTINCT FROM 'not-checkable' OR (decision ->> 'reason_code') IS DISTINCT FROM 'resolution-unavailable' OR (decision ->> 'assertion_member_id') IS NOT NULL) THEN
    RAISE EXCEPTION USING MESSAGE = 'rich missing resolution must remain explicitly uncheckable', ERRCODE = '23514';
   END IF;
   CONTINUE;
  END IF;
  resolved_meaning := ops.ddo_rich_selected_value(r.project_id, consolidation_basis, 'readings', decision['resolved']);
  PERFORM ops.ddo_rich_selected_value(r.project_id, consolidation_basis, 'readings', decision['resolution']);
  resolved_record := data.ddo_json(resolved_meaning);
  report := reports[((decision['resolution']) ->> 'product_id')];
  IF (report IS NULL OR ((decision['resolved']) ->> 'product_id') IS DISTINCT FROM ((decision['resolution']) ->> 'product_id') OR ((decision['resolution']) ->> 'member_id') IS NOT NULL OR ((decision['original']) ->> 'member_id') IS NULL OR ((decision['resolved']) ->> 'member_id') IS NULL OR (raw_record ->> 'candidate_type') IS DISTINCT FROM 'record' OR (resolved_record ->> 'candidate_type') IS DISTINCT FROM 'record' OR (raw_record ->> 'record_id') IS DISTINCT FROM (decision ->> 'record_id') OR (resolved_record ->> 'record_id') IS DISTINCT FROM (decision ->> 'record_id') OR (raw_record ->> 'interpretation_id') IS DISTINCT FROM (decision ->> 'source_interpretation_id') OR (resolved_record ->> 'interpretation_id') IS DISTINCT FROM (decision ->> 'interpretation_id') OR NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(report['inputs']) AS input(value) 
WHERE (input.value ->> 'role') = 'candidates' AND (input.value ->> 'product_id') = ((decision['original']) ->> 'product_id') AND (input.value ->> 'member_id') IS NULL AND ops.ddo_rich_support_population(input.value['support']) = ops.ddo_rich_support_population(decision['original']['support_references'])))) THEN
   RAISE EXCEPTION USING MESSAGE = 'rich decision relabels actual raw/resolved member and producing report custody', ERRCODE = '23514';
  END IF;
  SELECT jsonb_build_array('mapping', jsonb_agg(raw_pair.value ORDER BY (raw_pair.value ->> 0) COLLATE "C")) AS jsonb_build_array_1 
FROM jsonb_array_elements(raw_meaning[1]) AS raw_pair(value) 
WHERE ((raw_pair.value ->> 0) NOT IN ('interpretation_id', 'computation_dependencies')) INTO raw_comparison;
  SELECT jsonb_build_array('mapping', jsonb_agg(resolved_pair.value ORDER BY (resolved_pair.value ->> 0) COLLATE "C")) AS jsonb_build_array_1 
FROM jsonb_array_elements(resolved_meaning[1]) AS resolved_pair(value) 
WHERE ((resolved_pair.value ->> 0) NOT IN ('interpretation_id', 'computation_dependencies')) INTO resolved_comparison;
  IF (raw_comparison IS DISTINCT FROM resolved_comparison OR NOT (((data.ddo_field(resolved_meaning, 'computation_dependencies'))[1] @> jsonb_build_array(jsonb_build_array('string', 'raw-candidate-result:' || (raw_reports ->> (((decision['original']) ->> 'product_id'))))))) OR (EXISTS (SELECT 1 
FROM jsonb_array_elements((data.ddo_field(raw_meaning, 'computation_dependencies'))[1]) AS dependency(value) 
WHERE NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements((data.ddo_field(resolved_meaning, 'computation_dependencies'))[1]) AS retained(value) 
WHERE retained.value = dependency.value))))) THEN
   RAISE EXCEPTION USING MESSAGE = 'rich resolved reading changes complete original fields/evidence/alternatives', ERRCODE = '23514';
  END IF;
  IF (decision['authorization'] != CAST('null' AS JSONB) AND decision['authorization'] IS DISTINCT FROM policies[(((decision['authorization']) ->> 'product_id'))]['reference']) THEN
   RAISE EXCEPTION USING MESSAGE = 'rich decision references authority outside actual declared issuer population', ERRCODE = '23514';
  END IF;
  IF ((decision ->> 'outcome') IN ('accepted', 'below-threshold')) THEN
   policy := policies[((decision['authorization']) ->> 'product_id')]['body'];
   event := report['events'][data.canonical_json(jsonb_build_array(decision ->> 'record_id', decision ->> 'interpretation_id'))];
   family_contract := ops.ddo_rich_family_contract(report ->> 'release_id', resolved_record ->> 'contract');
   IF (policy IS NULL OR decision['authorization'] IS DISTINCT FROM policies[(((decision['authorization']) ->> 'product_id'))]['reference'] OR event IS NULL OR (event ->> 'outcome') IS DISTINCT FROM 'completed' OR (event ->> 'feature_input_digest') IS DISTINCT FROM (decision ->> 'feature_input_digest') OR (event ->> 'feature_instance_digest') IS DISTINCT FROM (decision ->> 'feature_instance_digest') OR (event ->> 'event_procedure') IS DISTINCT FROM (decision ->> 'event_procedure') OR (policy ->> 'feature_instance_digest') IS DISTINCT FROM (decision ->> 'feature_instance_digest') OR (policy ->> 'event_procedure') IS DISTINCT FROM (decision ->> 'event_procedure') OR (policy ->> 'family') IS DISTINCT FROM (resolved_record ->> 'family') OR (policy ->> 'family_contract') IS DISTINCT FROM family_contract OR family_contract IS DISTINCT FROM ops.ddo_rich_family_contract(r.release_id, (resolved_record ->> 'contract')) OR (policy ->> 'reading_recipe') IS DISTINCT FROM (report ->> 'recipe') OR ((policy['applicability']) ->> 'project_id') IS DISTINCT FROM r.project_id OR encode(sha256(convert_to((event ->> 'feature_input_canonical_json'), 'UTF8')), 'hex') IS DISTINCT FROM (event ->> 'feature_input_digest')) THEN
    RAISE EXCEPTION USING MESSAGE = 'rich decision lacks exact issued policy/current family/recipe and unique sealed feature event', ERRCODE = '23514';
   END IF;
  END IF;
  IF ((decision ->> 'outcome') = 'accepted') THEN
   SELECT member.value 
FROM jsonb_array_elements(admission['members']) AS member(value) 
WHERE (member.value ->> 'member_id') = (decision ->> 'assertion_member_id') INTO STRICT assertion;
   IF (((assertion['body']) ->> 'member_type') IS DISTINCT FROM 'source-reading-assertion' OR assertion['body']['original'] IS DISTINCT FROM decision['original'] OR assertion['body']['resolution'] IS DISTINCT FROM decision['resolution'] OR assertion['body']['resolved'] IS DISTINCT FROM decision['resolved'] OR ((assertion['body']) ->> 'record_id') IS DISTINCT FROM (decision ->> 'record_id') OR ((assertion['body']) ->> 'source_interpretation_id') IS DISTINCT FROM (decision ->> 'source_interpretation_id') OR ((assertion['body']) ->> 'interpretation_id') IS DISTINCT FROM (decision ->> 'interpretation_id')) THEN
    RAISE EXCEPTION USING MESSAGE = 'rich accepted assertion differs from actual complete reading decision', ERRCODE = '23514';
   END IF;
  ELSE
   IF ((decision ->> 'assertion_member_id') IS NOT NULL) THEN
    RAISE EXCEPTION USING MESSAGE = 'rich rejected reading cannot retain an accepted assertion', ERRCODE = '23514';
   END IF;
  END IF;
 END LOOP;
 IF (EXISTS (SELECT 1 
FROM jsonb_array_elements((data.ddo_field(admission_meaning, 'members'))[1]) AS admitted_member(value) 
WHERE data.ddo_field(data.ddo_field(admitted_member.value, 'body'), 'member_type') = CAST('["string","source-reading-assertion"]' AS JSONB) AND (SELECT count(*) AS count_1 
FROM jsonb_array_elements(admission['reading_decisions']) AS judgment(value) 
WHERE (judgment.value ->> 'outcome') = 'accepted' AND (judgment.value ->> 'assertion_member_id') = (data.ddo_field(admitted_member.value, 'member_id') ->> 1)) != 1 AND NOT ops.ddo_rich_carried_reading(admitted_member.value, known_packets))) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich accepted graph has no exact actual reading decision', ERRCODE = '23514';
 END IF;
 IF (jsonb_typeof(admission['selected_reading_ids']) IS DISTINCT FROM 'array' OR (SELECT coalesce(jsonb_agg((member.value ->> 'member_id') ORDER BY (member.value ->> 'member_id') COLLATE "C"), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(admission['members']) AS member(value) 
WHERE ((member.value['body']) ->> 'member_type') = 'source-reading-assertion') IS DISTINCT FROM (SELECT coalesce(jsonb_agg(selected_id.value ORDER BY selected_id.value COLLATE "C"), CAST('[]' AS JSONB)) AS coalesce_2 
FROM jsonb_array_elements_text(admission['selected_reading_ids']) AS selected_id(value))) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich selected readings differ from actual retained assertion packets', ERRCODE = '23514';
 END IF;
END$$

