BEGIN
 IF ((SELECT sem.data_operation_definition.profile 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) != 'derivation') THEN
  RETURN;
 END IF;
 PERFORM ops.ddo_rich_require_preparation_producer(r, completion);
 IF (ops.ddo_cpu_reply_output(r, completion) IS DISTINCT FROM data.ddo_normalize(completion['outputs'][0]['product']['body'])) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich preparation differs from actual original CPU reply and input basis', ERRCODE = '23514';
 END IF;
 IF ((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'proposals'))) THEN
  PERFORM ops.ddo_rich_require_proposal_inputs(r, ops.ddo_cpu_input_basis(r));
 END IF;
END

statements:
CREATE OR REPLACE FUNCTION ops.ddo_require_rich_preparation_completion(r ops.data_request, completion jsonb) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$BEGIN
 IF ((SELECT sem.data_operation_definition.profile 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) != 'derivation') THEN
  RETURN;
 END IF;
 PERFORM ops.ddo_rich_require_preparation_producer(r, completion);
 IF (ops.ddo_cpu_reply_output(r, completion) IS DISTINCT FROM data.ddo_normalize(completion['outputs'][0]['product']['body'])) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich preparation differs from actual original CPU reply and input basis', ERRCODE = '23514';
 END IF;
 IF ((SELECT sem.data_operation_definition.input_roles 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id) @> jsonb_build_array(jsonb_build_object('name', 'proposals'))) THEN
  PERFORM ops.ddo_rich_require_proposal_inputs(r, ops.ddo_cpu_input_basis(r));
 END IF;
END$$

