DECLARE
 definition sem.data_operation_definition%ROWTYPE;
 selected jsonb;
 output jsonb;
 report_product kb.data_product%ROWTYPE;
 pass_product kb.data_product%ROWTYPE;
 pass_kind sem.data_kind_contract%ROWTYPE;
 admitted ops.original_source_admission%ROWTYPE;
 pass_body jsonb;
 frame jsonb;
 passes jsonb := CAST('{}' AS JSONB);
 actors jsonb := CAST('[]' AS JSONB);
 parent_values jsonb := CAST('[]' AS JSONB);
 c jsonb;
 report jsonb;
 statement jsonb;
 expected jsonb;
 selected_case jsonb;
 report_reference jsonb;
 producer_count bigint;
 report_kind text;
 variant text;
 report_role text;
 policy_id text;
 selected_component text;
BEGIN
 BEGIN
  SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = r.release_id AND sem.data_operation_definition.operation_id = r.operation_id INTO STRICT definition;
  IF (NOT coalesce(definition.command_class = 'structural', false)) THEN
   IF (EXISTS (SELECT 1 
FROM jsonb_array_elements(definition.support_contract['effects']) AS effects_(value) 
WHERE (effects_.value ->> 'name') = 'native-evaluator-structural-admission')) THEN
    RAISE EXCEPTION USING MESSAGE = 'structural admission requires its exact command/effect/factory', ERRCODE = '23514';
   END IF;
   RETURN;
  END IF;
  IF (NOT ops.ddo_privileged_effect_admitted(definition, 'native-evaluator-structural-admission')) THEN
   RAISE EXCEPTION USING MESSAGE = 'structural admission lacks its independent release effect grant', ERRCODE = '42501';
  END IF;
  IF ((completion ->> 'outcome') IS DISTINCT FROM 'success' OR jsonb_array_length(completion['inputs']) != 4 OR jsonb_array_length(completion['outputs']) != 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'structural admission requires one report, three exact passes and one conclusion', ERRCODE = '23514';
  END IF;
  SELECT inputs_.value 
FROM jsonb_array_elements(completion['inputs']) AS inputs_(value) 
WHERE (inputs_.value ->> 'role') IN ('comparison', 'condition', 'definition') INTO STRICT selected;
  IF ((selected ->> 'member_id') IS NOT NULL OR CAST((selected ->> 'position') AS INTEGER) IS DISTINCT FROM 0 OR CAST((selected ->> 'multiplicity') AS INTEGER) IS DISTINCT FROM 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'structural report must be its exact whole scalar input', ERRCODE = '23514';
  END IF;
  SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = (selected ->> 'product_id') AND kb.data_product.project_id = r.project_id INTO STRICT report_product;
  SELECT sem.data_kind_contract.kind 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = report_product.kind_contract AND sem.data_kind_contract.universe = 'ordinary' INTO STRICT report_kind;
  IF (report_kind = 'urn:corpus:structural:DeclaredComparisonReport') THEN
   variant := 'qualified_comparison';
   report_role := 'comparison';
   policy_id := 'independent-structural-comparison-1';
  ELSE
   IF (report_kind = 'urn:corpus:structural:DeclaredConditionReport') THEN
    variant := 'condition_qualification';
    report_role := 'condition';
    policy_id := 'independent-condition-qualification-1';
   ELSE
    IF (report_kind = 'urn:corpus:structural:DeclaredDefinitionComponentsReport') THEN
     variant := 'definition_components';
     report_role := 'definition';
     policy_id := 'independent-definition-component-1';
    ELSE
     RAISE EXCEPTION USING MESSAGE = 'structural admission requires its actual released report kind', ERRCODE = '23514';
    END IF;
   END IF;
  END IF;
  report := data.ddo_json(report_product.canonical_body);
  IF ((report ->> 'kind') IS DISTINCT FROM variant OR (selected ->> 'role') IS DISTINCT FROM report_role) THEN
   RAISE EXCEPTION USING MESSAGE = 'structural report differs from its exact choice-bound nominal variant', ERRCODE = '23514';
  END IF;
  SELECT count(*) AS count_1 
FROM ops.data_derivation JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id JOIN ops.data_publication_receipt ON ops.data_publication_receipt.derivation_id = ops.data_derivation.id AND ops.data_publication_receipt.intent_id = ops.data_derivation.intent_id JOIN ops.data_request ON ops.data_request.id = ops.data_derivation.request_id JOIN sem.data_operation_definition AS owner ON owner.release_id = ops.data_derivation.release_id AND owner.operation_id = ops.data_request.operation_id JOIN ops.data_completion_intent ON ops.data_completion_intent.id = ops.data_derivation.intent_id 
WHERE ops.data_derivation_output.product_id = report_product.id AND ops.data_derivation_output.member_id IS NULL AND ops.data_derivation_output.role = 'result' AND ops.data_derivation_output.position = 0 AND ops.data_derivation_output.multiplicity = 1 AND ops.data_derivation.outcome = 'success' AND owner.profile = 'derivation' AND owner.support_contract['effects'] = CAST('[]' AS JSONB) AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(owner.output_roles) AS admitted_report_output(value) JOIN jsonb_array_elements(definition.input_roles) AS admitted_report_input(value) ON true 
WHERE (admitted_report_output.value ->> 'name') = ops.data_derivation_output.role AND (admitted_report_output.value ->> 'kind_contract') = report_product.kind_contract AND (admitted_report_input.value ->> 'name') = report_role AND admitted_report_input.value['accepted_kind_contracts'] @> jsonb_build_array(report_product.kind_contract))) AND nullif(((owner.support_contract['capabilities']['prepared_factory']) ->> 'entrypoint'), '') IS NOT NULL AND (((owner.support_contract['capabilities']['prepared_factory']) ->> 'source_digest') ~ '^[0-9a-f]{64}$') AND owner.implementation_revision LIKE 'implementation-slice:%' AND owner.recipe = ops.data_derivation.recipe AND (ops.data_completion_intent.payload ->> 'implementation_revision') = owner.implementation_revision AND jsonb_array_length(coalesce(ops.data_completion_intent.payload['execution_evidence']['cpu_receipts'], CAST('[]' AS JSONB))) = 1 AND (EXISTS (SELECT 1 
FROM ops.ddo_input_support_refs(r.binding, selected) AS supports_(value) 
WHERE (supports_.value ->> 'kind') = 'computation' AND (supports_.value ->> 'derivation_id') = ops.data_derivation.id)) INTO producer_count;
  IF (producer_count != 1) THEN
   RAISE EXCEPTION USING MESSAGE = 'structural report lacks its one actual captured producer for the selected variant', ERRCODE = '23514';
  END IF;
