  FOR selected IN SELECT inputs_.value 
FROM jsonb_array_elements(completion['inputs']) AS inputs_(value) 
WHERE (inputs_.value ->> 'role') = 'passes' LOOP
   IF ((selected ->> 'member_id') IS NOT NULL OR CAST((selected ->> 'multiplicity') AS INTEGER) IS DISTINCT FROM 1) THEN
    RAISE EXCEPTION USING MESSAGE = 'structural passes require distinct whole original authored products', ERRCODE = '23514';
   END IF;
   SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = (selected ->> 'product_id') AND kb.data_product.project_id = r.project_id INTO STRICT pass_product;
   SELECT sem.data_kind_contract.* 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = pass_product.kind_contract INTO STRICT pass_kind;
   IF (pass_kind.kind IS DISTINCT FROM 'urn:corpus:structural-admission:protected:DdoStructuralReferencePass' OR pass_kind.universe IS DISTINCT FROM 'evaluator') THEN
    RAISE EXCEPTION USING MESSAGE = 'structural pass differs from its protected nominal kind', ERRCODE = '23514';
   END IF;
   SELECT ops.original_source_admission.* 
FROM ops.original_source_admission JOIN ops.ddo_input_support_refs(r.binding, selected) AS supports_(value) ON (supports_.value ->> 'kind') = 'authored' AND (supports_.value ->> 'admission_id') = ops.original_source_admission.id AND (supports_.value ->> 'source_reference') = ops.original_source_admission.source_reference 
WHERE ops.original_source_admission.product_id = pass_product.id AND ops.original_source_admission.project_id = r.project_id AND (ops.original_source_admission.reference ->> 'kind') = 'authored-fact' AND ops.ddo_original_admission_valid(ops.original_source_admission.*) INTO STRICT admitted;
   pass_body := data.ddo_json(pass_product.canonical_body);
   IF ((admitted.evidence ->> 'standing') IS DISTINCT FROM 'authored' OR nullif((admitted.evidence ->> 'submitted_by'), '') IS NULL OR (admitted.reference ->> 'author') IS DISTINCT FROM (pass_body ->> 'author_assertion') OR (admitted.evidence ->> 'author_assertion') IS DISTINCT FROM (pass_body ->> 'author_assertion') OR ((pass_body['actor']) ->> 'principal') IS DISTINCT FROM (pass_body ->> 'author_assertion') OR ((pass_body['actor']) ->> 'basis') IS DISTINCT FROM 'authored_attribution' OR (pass_body ->> 'version') IS DISTINCT FROM 'structural-reference-pass-1' OR ((pass_body ->> 'pass_kind') NOT IN ('A', 'B', 'C')) OR (passes ? (pass_body ->> 'pass_kind'))) THEN
    RAISE EXCEPTION USING MESSAGE = 'structural pass lacks its exact original submitted author attribution', ERRCODE = '23514';
   END IF;
   IF (frame IS NULL) THEN
    frame := pass_body['frame'];
   END IF;
   IF (frame IS DISTINCT FROM pass_body['frame'] OR jsonb_strip_nulls(frame['report']) IS DISTINCT FROM jsonb_strip_nulls(report_reference) OR jsonb_strip_nulls(frame['inputs']) IS DISTINCT FROM jsonb_strip_nulls(report['inputs']) OR (frame ->> 'question') IS DISTINCT FROM ((report['inputs']) ->> 'question') OR jsonb_array_length(pass_body['cases']) != 1 OR ((pass_body['cases'][0]) ->> 'case_id') IS DISTINCT FROM (frame ->> 'case_id') OR (frame ->> 'operation') IS DISTINCT FROM variant OR (frame ->> 'rubric_version') IS DISTINCT FROM policy_id OR NOT ((frame ? 'component_id')) OR ((frame ->> 'component_id') IS NOT NULL) IS DISTINCT FROM (variant = 'definition_components') OR ((frame ->> 'direction') NOT IN ('source_first', 'output_first')) OR (frame ->> 'direction') = 'source_first' AND frame['exposed_outputs'] != CAST('[]' AS JSONB) OR (frame ->> 'direction') = 'output_first' AND NOT (EXISTS (SELECT 1 
