    parent_values := parent_values || jsonb_build_array(jsonb_build_object('reference', ops.ddo_structural_product_reference(pass_product), 'body_digest', pass_product.body_digest));
   END IF;
   passes := passes || jsonb_build_object((pass_body ->> 'pass_kind'), pass_body);
  END LOOP;
  IF ((SELECT count(*) AS count_1 
FROM jsonb_object_keys(passes) AS pass_names_(name)) != 3 OR NOT ((passes ?& ARRAY['A', 'B', 'C']))) THEN
   RAISE EXCEPTION USING MESSAGE = 'structural admission requires the exact A/B/C population', ERRCODE = '23514';
  END IF;
  c := passes['C'];
  IF (jsonb_array_length(c['parents']) != 2 OR ((jsonb_strip_nulls(c['parents']) @> jsonb_strip_nulls(parent_values))) IS NOT true OR ((jsonb_strip_nulls(parent_values) @> jsonb_strip_nulls(c['parents']))) IS NOT true) THEN
   RAISE EXCEPTION USING MESSAGE = 'C does not adjudicate exact original A/B product/body identities', ERRCODE = '23514';
  END IF;
  selected_component := frame ->> 'component_id';
  statement := ops.ddo_structural_statement(report_product.canonical_body, selected_component);
  SELECT cases_.value 
FROM jsonb_array_elements(c['cases']) AS cases_(value) 
WHERE (cases_.value ->> 'facet') = 'public_statement' AND cases_.value['path'] = CAST('["public_statement"]' AS JSONB) AND (cases_.value ->> 'judgment') = 'supported' AND (cases_.value ->> 'expected_meaning_json') = data.canonical_json(statement) INTO STRICT selected_case;
  IF (NOT (selected_case['source_passages'] @> coalesce((SELECT jsonb_agg((source_passages_.value ->> 'passage_id')) AS jsonb_agg_1 
FROM jsonb_array_elements(report['inputs']['passages']) AS source_passages_(value)), CAST('[]' AS JSONB)))) THEN
   RAISE EXCEPTION USING MESSAGE = 'structural supported statement omits selected source passages', ERRCODE = '23514';
  END IF;
  expected := jsonb_build_object('version', 'structural-admission-1', 'report', report_reference, 'component_id', selected_component, 'policy_id', policy_id, 'policy_version', '1', 'statement_encoding', 'ddo-semantic-value-v1', 'statement_meaning_json', data.canonical_json(statement), 'standing', 'admitted_structural_statement', 'assessment_basis', 'independently_attributed_authored_judgments', 'scientific_truth', 'not_established', 'member_truth', 'not_established_by_assembly_admission');
  output := completion['outputs'][0];
  IF ((output ->> 'role') IS DISTINCT FROM 'admission' OR (output ->> 'member_id') IS NOT NULL OR CAST((output ->> 'position') AS INTEGER) IS DISTINCT FROM 0 OR CAST((output ->> 'multiplicity') AS INTEGER) IS DISTINCT FROM 1 OR output['product']['members'] IS DISTINCT FROM CAST('[]' AS JSONB) OR NOT (EXISTS (SELECT 1 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = ((output['product']) ->> 'kind_contract') AND sem.data_kind_contract.kind = 'urn:corpus:structural-admission:DdoStructuralAdmission' AND sem.data_kind_contract.universe = 'ordinary')) OR data.ddo_normalize(output['product']['body']) IS DISTINCT FROM data.ddo_normalize(data.ddo_json_meaning(expected))) THEN
   RAISE EXCEPTION USING MESSAGE = 'structural ordinary conclusion differs from exact independently adjudicated statement', ERRCODE = '23514';
  END IF;
 EXCEPTION WHEN no_data_found OR too_many_rows THEN
  RAISE EXCEPTION USING MESSAGE = 'structural admission cannot resolve exact original custody', ERRCODE = '23514';
 END;
END

