WHERE (inputs_.value ->> 'role') = 'comparisons' AND (inputs_.value ->> 'member_id') IS NULL AND kb.data_product.id = ((admission_value['report']) ->> 'product_id') AND kb.data_product.project_id = r.project_id INTO STRICT comparison_product;
