    RAISE EXCEPTION USING MESSAGE = 'dossier admission differs from the actual retained comparison and exact statement', ERRCODE = '23514';
   END IF;
  END LOOP;
 EXCEPTION WHEN no_data_found OR too_many_rows THEN
  RAISE EXCEPTION USING MESSAGE = 'dossier admission cannot resolve exact ordinary issuer/report custody', ERRCODE = '23514';
 END;
