FROM ops.data_request 
WHERE ops.data_request.id = producer.request_id AND ops.data_request.project_id = consumer.project_id INTO STRICT request;
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = request.release_id AND sem.data_operation_definition.operation_id = request.operation_id INTO STRICT definition;
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = producer.intent_id INTO STRICT intent;
 IF ((requirement ->> 'required_family') != 'none' AND ((definition.validity_families @> ARRAY[(requirement ->> 'required_family')])) IS NOT true) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich selection producer lacks its required validity family', ERRCODE = '23514';
 END IF;
