DECLARE
 passage jsonb;
 source_value jsonb;
BEGIN
 SELECT passages_.value 
FROM jsonb_array_elements((data.ddo_field(data.ddo_field(report, 'inputs'), 'passages'))[1]) AS passages_(value) 
WHERE (data.ddo_field(passages_.value, 'passage_id') ->> 1) = identifier INTO STRICT passage;
 SELECT sources_.value 
FROM jsonb_array_elements((data.ddo_field(data.ddo_field(report, 'inputs'), 'sources'))[1]) AS sources_(value) 
WHERE ops.ddo_digest(data.ddo_json(ops.ddo_structural_pick(sources_.value, ARRAY[]::TEXT[], true))) = (data.ddo_field(passage, 'source_ref') ->> 1) INTO STRICT source_value;
 RETURN ops.ddo_structural_merge(ops.ddo_structural_pick(passage, ARRAY['passage_id', 'source_ref'], true), ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('source', ops.ddo_structural_pick(source_value, ARRAY[]::TEXT[], true)))));
END

