DECLARE
 fields jsonb;
 typed_value jsonb;
 spans jsonb;
BEGIN
 fields := jsonb_build_array(jsonb_build_array('dimension', data.ddo_field(field_value, 'dimension')), jsonb_build_array('lexical_value', data.ddo_field(field_value, 'lexical_value')), jsonb_build_array('evidence', ops.ddo_structural_citations(report, data.ddo_field(field_value, 'evidence'))));
 IF (coalesce(data.ddo_field(field_value, 'span'), CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
  fields := fields || jsonb_build_array(jsonb_build_array('span', ops.ddo_structural_span(report, data.ddo_field(field_value, 'span'))));
 END IF;
 IF (coalesce(data.ddo_field(field_value, 'spans'), CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
  SELECT jsonb_build_array('sequence', coalesce(jsonb_agg(ops.ddo_structural_span(report, spans_.value) ORDER BY spans_.ordinal), CAST('[]' AS JSONB))) AS jsonb_build_array_1 
FROM jsonb_array_elements((data.ddo_field(field_value, 'spans'))[1]) WITH ORDINALITY AS spans_(value, ordinal) INTO spans;
  fields := fields || jsonb_build_array(jsonb_build_array('spans', spans));
 END IF;
 IF (coalesce(data.ddo_field(field_value, 'literal'), CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
  fields := fields || jsonb_build_array(jsonb_build_array('literal', ops.ddo_structural_pick(data.ddo_field(field_value, 'literal'), ARRAY[]::TEXT[], true)));
 END IF;
 IF (coalesce(data.ddo_field(field_value, 'condition'), CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
  fields := fields || jsonb_build_array(jsonb_build_array('condition', data.ddo_field(field_value, 'condition')));
 END IF;
 typed_value := data.ddo_field(field_value, 'typed');
 IF (coalesce(typed_value, CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
  typed_value := ops.ddo_structural_merge(ops.ddo_structural_pick(typed_value, ARRAY['span', 'basis_evidence'], true), ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('span', ops.ddo_structural_span(report, data.ddo_field(typed_value, 'span'))))));
  IF (coalesce(data.ddo_field(data.ddo_field(field_value, 'typed'), 'basis_evidence'), CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
   typed_value := ops.ddo_structural_merge(typed_value, ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('basis_evidence', ops.ddo_structural_span(report, data.ddo_field(data.ddo_field(field_value, 'typed'), 'basis_evidence'))))));
  END IF;
  fields := fields || jsonb_build_array(jsonb_build_array('typed', typed_value));
 END IF;
 RETURN ops.ddo_structural_map(fields);
END

