  typed_value := ops.ddo_structural_merge(ops.ddo_structural_pick(typed_value, ARRAY['span', 'basis_evidence'], true), ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('span', ops.ddo_structural_span(report, data.ddo_field(typed_value, 'span'))))));
