DECLARE
 inputs jsonb := data.ddo_field(report, 'inputs');
 comparison jsonb := data.ddo_field(report, 'comparison');
 fields jsonb;
 dimensions jsonb := CAST('[]' AS JSONB);
 dimension jsonb;
 entry jsonb;
 value jsonb;
 group_value jsonb;
 members jsonb;
 witnesses jsonb;
 coverage jsonb;
 exclusions jsonb;
 succession jsonb;
BEGIN
 IF ((data.ddo_field(report, 'kind') ->> 1) IS DISTINCT FROM 'qualified_comparison') THEN
  RAISE EXCEPTION USING MESSAGE = 'structural admission requires the exact qualified comparison variant', ERRCODE = '23514';
 END IF;
 SELECT jsonb_build_array('sequence', coalesce(jsonb_agg(coverage_.value ORDER BY (coverage_.value ->> 1) COLLATE "C"), CAST('[]' AS JSONB))) AS jsonb_build_array_1 
FROM jsonb_array_elements((data.ddo_field(inputs, 'coverage_limits'))[1]) AS coverage_(value) INTO coverage;
 SELECT jsonb_build_array('sequence', coalesce(jsonb_agg(selected_.item ORDER BY data.canonical_json(data.ddo_json(selected_.item)) COLLATE "C"), CAST('[]' AS JSONB))) AS jsonb_build_array_1 
FROM (SELECT ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('left', ops.ddo_structural_citation(report, data.ddo_field(exclusions_.value, 'left') ->> 1)), jsonb_build_array('right', ops.ddo_structural_citation(report, data.ddo_field(exclusions_.value, 'right') ->> 1)))) AS item 
FROM jsonb_array_elements((data.ddo_field(inputs, 'exclusions'))[1]) AS exclusions_(value)) AS selected_ INTO exclusions;
 FOR dimension IN SELECT dimensions_.value 
FROM jsonb_array_elements((data.ddo_field(comparison, 'dimensions'))[1]) AS dimensions_(value) LOOP
  entry := ops.ddo_structural_pick(dimension, ARRAY['dimension', 'outcome', 'typed_outcome', 'assumptions', 'grouping_outcome', 'member_comparisons'], false);
  value := data.ddo_field(dimension, 'removed_interval');
  IF (coalesce(value, CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
   entry := ops.ddo_structural_merge(entry, ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('removed_interval', ops.ddo_structural_pick(value, ARRAY[]::TEXT[], true)))));
  END IF;
  value := data.ddo_field(dimension, 'added_interval');
  IF (coalesce(value, CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
   entry := ops.ddo_structural_merge(entry, ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('added_interval', ops.ddo_structural_pick(value, ARRAY[]::TEXT[], true)))));
  END IF;
  value := data.ddo_field(dimension, 'left');
  IF (coalesce(value, CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
   entry := ops.ddo_structural_merge(entry, ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('left', ops.ddo_structural_clause_field(report, value)))));
  END IF;
  group_value := data.ddo_field(dimension, 'left_group');
  IF (coalesce(group_value, CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
   SELECT jsonb_build_array('sequence', coalesce(jsonb_agg(ops.ddo_structural_clause_field(report, members_.value) ORDER BY members_.ordinal), CAST('[]' AS JSONB))) AS jsonb_build_array_1 
FROM jsonb_array_elements((data.ddo_field(group_value, 'members'))[1]) WITH ORDINALITY AS members_(value, ordinal) INTO members;
   SELECT jsonb_build_array('sequence', coalesce(jsonb_agg(ops.ddo_structural_span(report, witnesses_.value) ORDER BY witnesses_.ordinal), CAST('[]' AS JSONB))) AS jsonb_build_array_1 
FROM jsonb_array_elements((data.ddo_field(group_value, 'witnesses'))[1]) WITH ORDINALITY AS witnesses_(value, ordinal) INTO witnesses;
   value := ops.ddo_structural_merge(ops.ddo_structural_pick(group_value, ARRAY['state', 'grouping'], false), ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('members', members), jsonb_build_array('witnesses', witnesses))));
   entry := ops.ddo_structural_merge(entry, ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('left_group', value))));
  END IF;
  value := data.ddo_field(dimension, 'right');
  IF (coalesce(value, CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
   entry := ops.ddo_structural_merge(entry, ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('right', ops.ddo_structural_clause_field(report, value)))));
  END IF;
  group_value := data.ddo_field(dimension, 'right_group');
  IF (coalesce(group_value, CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
   SELECT jsonb_build_array('sequence', coalesce(jsonb_agg(ops.ddo_structural_clause_field(report, members_.value) ORDER BY members_.ordinal), CAST('[]' AS JSONB))) AS jsonb_build_array_1 
FROM jsonb_array_elements((data.ddo_field(group_value, 'members'))[1]) WITH ORDINALITY AS members_(value, ordinal) INTO members;
   SELECT jsonb_build_array('sequence', coalesce(jsonb_agg(ops.ddo_structural_span(report, witnesses_.value) ORDER BY witnesses_.ordinal), CAST('[]' AS JSONB))) AS jsonb_build_array_1 
FROM jsonb_array_elements((data.ddo_field(group_value, 'witnesses'))[1]) WITH ORDINALITY AS witnesses_(value, ordinal) INTO witnesses;
   value := ops.ddo_structural_merge(ops.ddo_structural_pick(group_value, ARRAY['state', 'grouping'], false), ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('members', members), jsonb_build_array('witnesses', witnesses))));
   entry := ops.ddo_structural_merge(entry, ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('right_group', value))));
  END IF;
  dimensions := dimensions || jsonb_build_array(entry);
 END LOOP;
 fields := jsonb_build_array(jsonb_build_array('left', ops.ddo_structural_citation(report, data.ddo_field(comparison, 'left_id') ->> 1)), jsonb_build_array('right', ops.ddo_structural_citation(report, data.ddo_field(comparison, 'right_id') ->> 1)), jsonb_build_array('dimensions', jsonb_build_array('sequence', dimensions)));
 value := ops.ddo_structural_merge(ops.ddo_structural_pick(comparison, ARRAY['equivalence', 'identity_standing', 'applicability'], false), ops.ddo_structural_map(fields));
 succession := data.ddo_field(comparison, 'succession');
 IF (coalesce(succession, CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
  value := ops.ddo_structural_merge(value, ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('succession', ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('older', ops.ddo_structural_citation(report, data.ddo_field(succession, 'older_id') ->> 1)), jsonb_build_array('newer', ops.ddo_structural_citation(report, data.ddo_field(succession, 'newer_id') ->> 1)), jsonb_build_array('evidence', ops.ddo_structural_span(report, data.ddo_field(succession, 'evidence'))), jsonb_build_array('older_evidence', ops.ddo_structural_span(report, data.ddo_field(succession, 'older_evidence')))))))));
 END IF;
 RETURN ops.ddo_structural_merge(ops.ddo_structural_pick(inputs, ARRAY['scope', 'inventory_id'], false), ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('version', jsonb_build_array('string', 'structural-public-statement-3')), jsonb_build_array('kind', jsonb_build_array('string', 'qualified_comparison')), jsonb_build_array('input_policy_id', data.ddo_field(inputs, 'policy_id')), jsonb_build_array('coverage_limits', coverage), jsonb_build_array('exclusions', exclusions), jsonb_build_array('comparison', value))));
END

