DECLARE
 inputs jsonb := data.ddo_field(report, 'inputs');
 variant text := data.ddo_field(report, 'kind') ->> 1;
 coverage jsonb;
 exclusions jsonb;
 statement jsonb;
 value jsonb;
 component jsonb;
 fields jsonb;
 citations jsonb;
BEGIN
 IF (variant = 'qualified_comparison') THEN
  IF (component_id IS NOT NULL) THEN
   RAISE EXCEPTION USING MESSAGE = 'comparison statement cannot select a definition component', ERRCODE = '23514';
  END IF;
  RETURN ops.ddo_structural_comparison_statement(report);
 END IF;
 IF ((variant NOT IN ('condition_qualification', 'definition_components'))) THEN
  RAISE EXCEPTION USING MESSAGE = 'structural admission requires its exact released report variant', ERRCODE = '23514';
 END IF;
 IF ((variant = 'definition_components') IS DISTINCT FROM (component_id IS NOT NULL)) THEN
  RAISE EXCEPTION USING MESSAGE = 'only definition publication requires one exact component selector', ERRCODE = '23514';
 END IF;
 SELECT jsonb_build_array('sequence', coalesce(jsonb_agg(coverage_.value ORDER BY (coverage_.value ->> 1) COLLATE "C"), CAST('[]' AS JSONB))) AS jsonb_build_array_1 
FROM jsonb_array_elements((data.ddo_field(inputs, 'coverage_limits'))[1]) AS coverage_(value) INTO coverage;
 SELECT jsonb_build_array('sequence', coalesce(jsonb_agg(selected_.item ORDER BY data.canonical_json(data.ddo_json(selected_.item)) COLLATE "C"), CAST('[]' AS JSONB))) AS jsonb_build_array_1 
FROM (SELECT ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('left', ops.ddo_structural_citation(report, data.ddo_field(exclusions_.value, 'left') ->> 1)), jsonb_build_array('right', ops.ddo_structural_citation(report, data.ddo_field(exclusions_.value, 'right') ->> 1)))) AS item 
FROM jsonb_array_elements((data.ddo_field(inputs, 'exclusions'))[1]) AS exclusions_(value)) AS selected_ INTO exclusions;
 statement := ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('version', jsonb_build_array('string', 'structural-public-statement-3')), jsonb_build_array('kind', jsonb_build_array('string', variant)), jsonb_build_array('scope', data.ddo_field(inputs, 'scope')), jsonb_build_array('coverage_limits', coverage), jsonb_build_array('exclusions', exclusions)));
 IF (variant = 'definition_components') THEN
  SELECT components_.value 
FROM jsonb_array_elements((data.ddo_field(data.ddo_field(report, 'definition_components'), 'components'))[1]) AS components_(value) 
WHERE (data.ddo_field(components_.value, 'component_id') ->> 1) = component_id INTO STRICT component;
  fields := jsonb_build_array(jsonb_build_array('term', ops.ddo_structural_span(report, data.ddo_field(component, 'term'))), jsonb_build_array('content', ops.ddo_structural_span(report, data.ddo_field(component, 'content'))), jsonb_build_array('interpretation', data.ddo_field(component, 'interpretation')), jsonb_build_array('scope', data.ddo_field(component, 'scope')));
  value := data.ddo_field(component, 'effective_version');
  IF (coalesce(value, CAST('["null"]' AS JSONB)) != CAST('["null"]' AS JSONB)) THEN
   fields := fields || jsonb_build_array(jsonb_build_array('effective_version', value));
  END IF;
  RETURN ops.ddo_structural_merge(statement, ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('definition_component', ops.ddo_structural_map(fields)))));
 END IF;
 component := data.ddo_field(report, 'condition_qualification');
 fields := jsonb_build_array(jsonb_build_array('relation', data.ddo_field(component, 'relation')));
 value := data.ddo_field(component, 'effective_version');
 IF (coalesce((value ->> 1), '') != '') THEN
  fields := fields || jsonb_build_array(jsonb_build_array('effective_version', value));
 END IF;
 SELECT jsonb_build_array('sequence', coalesce(jsonb_agg(ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('source_pointer', data.ddo_field(qualifier_.value, 'source_pointer')), jsonb_build_array('passage', ops.ddo_structural_span(report, data.ddo_field(qualifier_.value, 'span'))))) ORDER BY qualifier_.ordinal), CAST('[]' AS JSONB))) AS jsonb_build_array_1 
FROM jsonb_array_elements((data.ddo_field(component, 'qualifier'))[1]) WITH ORDINALITY AS qualifier_(value, ordinal) INTO citations;
 fields := fields || jsonb_build_array(jsonb_build_array('qualifier', citations));
 SELECT jsonb_build_array('sequence', coalesce(jsonb_agg(ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('source_pointer', data.ddo_field(host_predicate_.value, 'source_pointer')), jsonb_build_array('passage', ops.ddo_structural_span(report, data.ddo_field(host_predicate_.value, 'span'))))) ORDER BY host_predicate_.ordinal), CAST('[]' AS JSONB))) AS jsonb_build_array_1 
FROM jsonb_array_elements((data.ddo_field(component, 'host_predicate'))[1]) WITH ORDINALITY AS host_predicate_(value, ordinal) INTO citations;
 fields := fields || jsonb_build_array(jsonb_build_array('host_predicate', citations));
 RETURN ops.ddo_structural_merge(statement, ops.ddo_structural_map(jsonb_build_array(jsonb_build_array('condition_qualification', ops.ddo_structural_map(fields)))));
END

