CREATE OR REPLACE FUNCTION ops.ddo_support_reference_node(reference jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$BEGIN
 IF (jsonb_typeof(reference) IS DISTINCT FROM 'object' OR CASE WHEN ((reference ->> 'kind') IN ('original-source', 'authored')) THEN jsonb_typeof(reference['admission_id']) WHEN ((reference ->> 'admission_use_id') IS NOT NULL) THEN jsonb_typeof(reference['admission_use_id']) WHEN ((reference ->> 'derivation_id') IS NOT NULL) THEN jsonb_typeof(reference['derivation_id']) END IS DISTINCT FROM 'string' OR nullif(CASE WHEN ((reference ->> 'kind') IN ('original-source', 'authored')) THEN (reference ->> 'admission_id') WHEN ((reference ->> 'admission_use_id') IS NOT NULL) THEN (reference ->> 'admission_use_id') WHEN ((reference ->> 'derivation_id') IS NOT NULL) THEN (reference ->> 'derivation_id') END, '') IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'unrecognized native support reference', ERRCODE = '23514';
 END IF;
 RETURN jsonb_build_object('kind', CASE WHEN ((reference ->> 'kind') IN ('original-source', 'authored')) THEN 'original' WHEN ((reference ->> 'admission_use_id') IS NOT NULL) THEN 'use' WHEN ((reference ->> 'derivation_id') IS NOT NULL) THEN 'episode' END, 'id', CASE WHEN ((reference ->> 'kind') IN ('original-source', 'authored')) THEN reference ->> 'admission_id' WHEN ((reference ->> 'admission_use_id') IS NOT NULL) THEN reference ->> 'admission_use_id' WHEN ((reference ->> 'derivation_id') IS NOT NULL) THEN reference ->> 'derivation_id' END);
END$$

