DECLARE
 pair_key text;
 pair_value jsonb;
 epoch numeric;
 result jsonb := CAST('{}' AS JSONB);
BEGIN
 IF (jsonb_typeof(snapshot) IS DISTINCT FROM 'object') THEN
  RAISE EXCEPTION USING MESSAGE = 'trust snapshot requires an explicit epoch mapping', ERRCODE = 'P0001';
 END IF;
 FOR pair_key, pair_value IN SELECT epoch_pair.key, epoch_pair.value 
FROM jsonb_each(snapshot) AS epoch_pair(key, value) LOOP
  IF (nullif(pair_key, '') IS NULL OR jsonb_typeof(pair_value) IS DISTINCT FROM 'number') THEN
   RAISE EXCEPTION USING MESSAGE = 'trust snapshot requires nonnegative integer epochs', ERRCODE = 'P0001';
  END IF;
  epoch := CAST(pair_value #>> ARRAY[]::TEXT[] AS NUMERIC);
  IF (epoch < 0 OR epoch != trunc(epoch)) THEN
   RAISE EXCEPTION USING MESSAGE = 'trust snapshot requires nonnegative integer epochs', ERRCODE = 'P0001';
  END IF;
  IF (epoch != 0) THEN
   result := result || jsonb_build_object(pair_key, epoch);
  END IF;
 END LOOP;
 RETURN result;
END

