DECLARE
 raw jsonb;
 roledef jsonb;
 rv jsonb;
 mv jsonb;
 item jsonb;
 expected jsonb;
 witness jsonb;
 role_meaning jsonb;
 population_reference jsonb;
 frozen_binding jsonb;
 x kb.data_product%ROWTYPE;
 native_member kb.data_product_member%ROWTYPE;
 pop ops.data_population%ROWTYPE;
 d ops.data_demand%ROWTYPE;
 boundary ops.data_demand_read%ROWTYPE;
 state text;
 lexical_alternative text;
BEGIN
 PERFORM ops.ddo_binding_body_access(b, r.project_id);
 SELECT ops.data_demand.* 
FROM ops.data_demand 
WHERE ops.data_demand.id = o.demand_id INTO STRICT d;
 IF ((b ->> 'inference') IS DISTINCT FROM (d.selection ->> 'inference') OR NOT (EXISTS (SELECT frozen_operation.value 
FROM jsonb_array_elements(d.selection['operations']) AS frozen_operation(value) 
WHERE (frozen_operation.value ->> 'operation') = o.operation_id AND frozen_operation.value['parameter_meaning'] = data.ddo_normalize(data.ddo_field(b['parameters'], 'parameters')))) OR data.ddo_field(b['parameters'], 'replicate') IS DISTINCT FROM (CASE WHEN (replicate IS NULL) THEN jsonb_build_array('null') ELSE jsonb_build_array('string', replicate) END) OR NOT (EXISTS (SELECT frozen_operation.value 
FROM jsonb_array_elements(d.selection['operations']) AS frozen_operation(value) 
WHERE (frozen_operation.value ->> 'operation') = o.operation_id AND (frozen_operation.value ->> 'recipe') = def.recipe AND (frozen_operation.value ->> 'replicate') IS NOT DISTINCT FROM replicate))) THEN
  RAISE EXCEPTION USING MESSAGE = 'request differs from frozen inference/parameters/replicate/recipe', ERRCODE = '23514';
 END IF;
 IF (NOT (EXISTS (SELECT ops.data_demand_read.id 
FROM ops.data_demand_read 
WHERE ops.data_demand_read.id = (b ->> 'read_id') AND ops.data_demand_read.demand_id = d.id))) THEN
  RAISE EXCEPTION USING MESSAGE = 'binding lacks exact native read acquisition', ERRCODE = '23514';
 END IF;
 SELECT ops.data_demand_read.* 
FROM ops.data_demand_read 
WHERE ops.data_demand_read.id = (b ->> 'read_id') AND ops.data_demand_read.demand_id = d.id INTO STRICT boundary;
 SELECT coalesce(jsonb_object_agg(named_source.key, named_source.value), CAST('{}' AS JSONB)) AS coalesce_1 
FROM jsonb_each(coalesce(d.selection['source_sets'], CAST('{}' AS JSONB))) AS named_source(key, value) 
WHERE EXISTS (SELECT input_role.value 
FROM jsonb_array_elements(def.input_roles) AS input_role(value) 
WHERE ((input_role.value['support']) ->> 'source_set') = named_source.key) INTO expected;
 IF (expected != CAST('{}' AS JSONB)) THEN
  IF (data.ddo_json(data.ddo_field(b['parameters'], 'source_sets')) IS DISTINCT FROM ops.ddo_source_sets_meaning(expected)) THEN
   RAISE EXCEPTION USING MESSAGE = 'request source-set meaning differs from exact frozen declaration', ERRCODE = '23514';
  END IF;
 ELSE
  IF (data.ddo_field(b['parameters'], 'source_sets') IS NOT NULL) THEN
   RAISE EXCEPTION USING MESSAGE = 'undeclared request source-set meaning', ERRCODE = '23514';
  END IF;
 END IF;
 raw := data.ddo_json(b['request_inputs']);
 IF (jsonb_typeof(raw) != 'object' OR (EXISTS (SELECT role_name.name 
FROM jsonb_object_keys(raw) AS role_name(name) 
WHERE NOT (EXISTS (SELECT input_role.value 
FROM jsonb_array_elements(def.input_roles) AS input_role(value) 
WHERE (input_role.value ->> 'name') = role_name.name))))) THEN
  RAISE EXCEPTION USING MESSAGE = 'request input roles differ from admitted definition', ERRCODE = '23514';
 END IF;
 FOR roledef IN SELECT input_role.value 
FROM jsonb_array_elements(def.input_roles) AS input_role(value) LOOP
  role_meaning := data.ddo_field(b['request_inputs'], roledef ->> 'name');
  rv := raw[(roledef ->> 'name')];
  IF (rv IS NULL) THEN
   RAISE EXCEPTION USING MESSAGE = 'missing request role', ERRCODE = '23514';
  END IF;
  state := data.ddo_field(role_meaning, 'value') ->> 0;
  IF ((state NOT IN ('present', 'known-absent')) OR state = 'known-absent' AND (roledef ->> 'presence') = 'required') THEN
   RAISE EXCEPTION USING MESSAGE = 'incomplete input cannot attach runnable request', ERRCODE = '23514';
  END IF;
  witness := rv['population_witness'];
  pop := NULL;
  SELECT population_ref.value 
FROM jsonb_array_elements(b['populations']) AS population_ref(value) 
WHERE (population_ref.value ->> 'role') = (roledef ->> 'name') INTO population_reference;
  IF (population_reference IS NOT NULL AND population_reference != CAST('null' AS JSONB)) THEN
   IF (population_reference IS NULL) THEN
    RAISE EXCEPTION USING MESSAGE = 'population witness lacks authenticated native receipt reference', ERRCODE = '23514';
   END IF;
   SELECT ops.data_population.* 
FROM ops.data_population 
WHERE ops.data_population.id = (population_reference ->> 'population_id') AND ops.data_population.demand_id = d.id AND ops.data_population.name = (population_reference ->> 'name') INTO STRICT pop;
   IF (NOT ops.ddo_node_valid('population', pop.id)) THEN
    RAISE EXCEPTION USING MESSAGE = 'population witness is historical or revoked', ERRCODE = '23514';
   END IF;
   IF ((pop.evidence ? 'selection') AND (((pop.evidence['selection']) ->> 'obligation_id'), ((pop.evidence['selection']) ->> 'operation_id'), ((pop.evidence['selection']) ->> 'subject'), ((pop.evidence['selection']) ->> 'subject_definition'), ((pop.evidence['selection']) ->> 'original_source')) IS DISTINCT FROM (o.id, o.operation_id, o.subject, ops.ddo_operation_subject(d.release_id, o.operation_id), o.original_source)) THEN
    RAISE EXCEPTION USING MESSAGE = 'selected population belongs to another binding context', ERRCODE = '23514';
   END IF;
   PERFORM ops.ddo_require_release_facts(d.release_id);
   SELECT sem.data_operation_definition.binding_expression 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = d.release_id AND sem.data_operation_definition.operation_id = o.operation_id INTO STRICT frozen_binding;
   expected := CASE WHEN (state = 'known-absent' OR (ops.ddo_binding_population_refs(frozen_binding, jsonb_build_object('choices', (SELECT frozen_operation.value['choices'] AS anon_1 
FROM jsonb_array_elements(d.selection['operations']) AS frozen_operation(value) 
WHERE (frozen_operation.value ->> 'operation') = o.operation_id))) ? (roledef ->> 'name'))) THEN ops.ddo_binding_population_meaning(ops.ddo_project_population(pop.semantic_key, pop.complete, pop.members, pop.evidence, d.project_id, coalesce(ops.ddo_binding_population_projection(frozen_binding, jsonb_build_object('choices', (SELECT frozen_operation.value['choices'] AS anon_1 
FROM jsonb_array_elements(d.selection['operations']) AS frozen_operation(value) 
WHERE (frozen_operation.value ->> 'operation') = o.operation_id)), roledef ->> 'name'), 'member')), roledef['identity_requirements'] ? 'episode') ELSE CAST('null' AS JSONB) END;
   IF (witness IS DISTINCT FROM expected) THEN
    RAISE EXCEPTION USING MESSAGE = 'population semantic witness differs from native closure value', ERRCODE = '23514';
   END IF;
   IF (NOT (EXISTS (SELECT binding_support.value 
FROM jsonb_array_elements(b['support']) AS binding_support(value) 
WHERE (binding_support.value ->> 'role') = ('population:' || pop.name) AND (binding_support.value ->> 'derivation_id') = (pop.evidence ->> 'derivation_id') AND (binding_support.value ->> 'admission_use_id') = (pop.evidence ->> 'admission_use_id')))) THEN
    RAISE EXCEPTION USING MESSAGE = 'population closure lacks authentic derivation support', ERRCODE = '23514';
   END IF;
  ELSE
   IF (population_reference IS NOT NULL) THEN
    RAISE EXCEPTION USING MESSAGE = 'unexpected native population receipt for unwitnessed role', ERRCODE = '23514';
   END IF;
  END IF;
  IF (EXISTS (SELECT discovery_relation.value 
FROM jsonb_array_elements(d.selection['discovery']) AS discovery_relation(value) 
WHERE (discovery_relation.value ->> 'target') = o.operation_id AND (discovery_relation.value ->> 'target_role') = (roledef ->> 'name'))) THEN
   IF (pop.id IS NULL OR NOT coalesce(ops.ddo_discovery_role_population(d, pop, o.operation_id, (roledef ->> 'name'), o.subject, o.original_source, o.analyzed_scope, boundary), false) OR (EXISTS (SELECT manifest_input.value 
FROM jsonb_array_elements(b['inputs']) AS manifest_input(value) 
WHERE (manifest_input.value ->> 'role') = (roledef ->> 'name') AND ((manifest_input.value ->> 'product_id') IS DISTINCT FROM (pop.evidence ->> 'product_id') OR NOT (EXISTS (SELECT population_member.value 
FROM jsonb_array_elements(pop.members) AS population_member(value) 
WHERE (population_member.value ->> 'member_id') = (manifest_input.value ->> 'member_id') AND (population_member.value ->> 'subject') = o.subject AND (population_member.value ->> 'subject_definition') = ops.ddo_operation_subject(d.release_id, o.operation_id) AND (population_member.value ->> 'original_source') IS NOT DISTINCT FROM o.original_source AND population_member.value['analyzed_scope'] = o.analyzed_scope))))) OR (EXISTS (SELECT manifest_input.value 
FROM jsonb_array_elements(b['inputs']) AS manifest_input(value) 
WHERE (manifest_input.value ->> 'role') = (roledef ->> 'name') AND NOT (EXISTS (SELECT discovery_support.value 
FROM ops.ddo_input_support_refs(b, manifest_input.value) AS discovery_support(value) 
WHERE coalesce((discovery_support.value ->> 'kind'), 'computation') = 'computation' AND (discovery_support.value ->> 'derivation_id') = (pop.evidence ->> 'derivation_id') AND (discovery_support.value ->> 'admission_use_id') = (pop.evidence ->> 'admission_use_id')))))) THEN
    RAISE EXCEPTION USING MESSAGE = 'discovery input differs from exact selected parent/member/context support', ERRCODE = '23514';
   END IF;
  END IF;
  IF (state = 'known-absent' AND (EXISTS (SELECT manifest_input.value 
FROM jsonb_array_elements(b['inputs']) AS manifest_input(value) 
WHERE (manifest_input.value ->> 'role') = (roledef ->> 'name')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'absent role cannot carry native inputs', ERRCODE = '23514';
  END IF;
  IF (state = 'known-absent' AND pop.id IS NOT NULL AND NOT pop.complete) THEN
   RAISE EXCEPTION USING MESSAGE = 'open population cannot establish absence', ERRCODE = '23514';
  END IF;
  IF ((roledef ->> 'presence') = 'alternative' AND NOT (roledef['alternatives'] ? (rv ->> 'selected_alternative'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'selected alternative outside declared choice', ERRCODE = '23514';
  END IF;
  IF (state = 'present') THEN
   IF (jsonb_typeof(rv['value']) != 'array') THEN
    RAISE EXCEPTION USING MESSAGE = 'present role has no member collection', ERRCODE = '23514';
   END IF;
   FOR mv IN SELECT semantic_member.value 
FROM jsonb_array_elements(rv['value']) AS semantic_member(value) LOOP
    PERFORM ops.ddo_fields(mv, ARRAY['product', 'kind', 'subject', 'subject_definition', 'member', 'original_source', 'analyzed_scope', 'coverage', 'position', 'multiplicity'], ARRAY['support_episodes', 'original_sources', 'provider', 'alternative']);
    IF ((mv ? 'support_episodes') AND NOT (roledef['identity_requirements'] ? 'episode') OR (mv ? 'original_sources') AND NOT (roledef['identity_requirements'] ? 'original-source')) THEN
     RAISE EXCEPTION USING MESSAGE = 'unrequested support identity cannot salt semantic input', ERRCODE = '23514';
    END IF;
    IF ((roledef ->> 'collection') != 'sequence' AND mv['position'] IS DISTINCT FROM CAST('null' AS JSONB)) THEN
     RAISE EXCEPTION USING MESSAGE = 'nonsequence position is not a semantic determinant', ERRCODE = '23514';
    END IF;
    SELECT manifest_input.value 
FROM jsonb_array_elements(b['inputs']) AS manifest_input(value) 
WHERE (manifest_input.value ->> 'role') = (roledef ->> 'name') AND CASE WHEN ((manifest_input.value ->> 'member_id') IS NULL) THEN (manifest_input.value ->> 'product_id') ELSE (SELECT data.ddo_identity('body', data.ddo_normalize(kb.data_product_member.body)) AS ddo_identity_1 
FROM kb.data_product_member 
WHERE kb.data_product_member.product_id = (manifest_input.value ->> 'product_id') AND kb.data_product_member.member_id = (manifest_input.value ->> 'member_id')) END = (mv ->> 'product') AND (manifest_input.value ->> 'member_id') IS NOT DISTINCT FROM (mv ->> 'member') AND (manifest_input.value ->> 'multiplicity') = (mv ->> 'multiplicity') AND ((roledef ->> 'collection') != 'sequence' OR (manifest_input.value ->> 'position') IS NOT DISTINCT FROM (mv ->> 'position')) AND (NOT (roledef['identity_requirements'] ? 'episode') OR coalesce(mv['support_episodes'], CAST('[]' AS JSONB)) = ops.ddo_input_support_episodes(b, manifest_input.value)) ORDER BY CAST(manifest_input.value ->> 'position' AS INTEGER) 
 LIMIT 1 INTO item;
    IF (item IS NULL) THEN
     RAISE EXCEPTION USING MESSAGE = 'semantic binding has no exact native manifest member for role ' || (roledef ->> 'name'), ERRCODE = '23514', DETAIL = CAST(jsonb_build_object('collection', roledef ->> 'collection', 'multiplicity', mv['multiplicity'], 'position', mv['position'], 'candidates', (SELECT coalesce(jsonb_agg(jsonb_build_object('multiplicity', candidates.candidate['multiplicity'], 'position', candidates.candidate['position'], 'episodes_match', coalesce(mv['support_episodes'], CAST('[]' AS JSONB)) = ops.ddo_input_support_episodes(b, candidates.candidate))), CAST('[]' AS JSONB)) AS coalesce_1 
FROM (SELECT manifest_input.value AS candidate 
FROM jsonb_array_elements(b['inputs']) AS manifest_input(value) 
WHERE (manifest_input.value ->> 'role') = (roledef ->> 'name') AND CASE WHEN ((manifest_input.value ->> 'member_id') IS NULL) THEN (manifest_input.value ->> 'product_id') ELSE (SELECT data.ddo_identity('body', data.ddo_normalize(kb.data_product_member.body)) AS ddo_identity_1 
FROM kb.data_product_member 
WHERE kb.data_product_member.product_id = (manifest_input.value ->> 'product_id') AND kb.data_product_member.member_id = (manifest_input.value ->> 'member_id')) END = (mv ->> 'product') AND (manifest_input.value ->> 'member_id') IS NOT DISTINCT FROM (mv ->> 'member') 
 LIMIT 3) AS candidates)) AS TEXT);
    END IF;
    IF ((SELECT count(*) AS count_1 
FROM jsonb_array_elements(rv['value']) AS semantic_member(value) 
WHERE ((semantic_member.value ->> 'product'), (semantic_member.value ->> 'member'), (semantic_member.value ->> 'multiplicity')) IS NOT DISTINCT FROM ((mv ->> 'product'), (mv ->> 'member'), (mv ->> 'multiplicity')) AND ((roledef ->> 'collection') != 'sequence' OR (semantic_member.value ->> 'position') IS NOT DISTINCT FROM (mv ->> 'position')) AND (NOT (roledef['identity_requirements'] ? 'episode') OR semantic_member.value['support_episodes'] IS NOT DISTINCT FROM mv['support_episodes'])) != (SELECT count(*) AS count_2 
FROM jsonb_array_elements(b['inputs']) AS manifest_input(value) 
WHERE (manifest_input.value ->> 'role') = (roledef ->> 'name') AND CASE WHEN ((manifest_input.value ->> 'member_id') IS NULL) THEN (manifest_input.value ->> 'product_id') ELSE (SELECT data.ddo_identity('body', data.ddo_normalize(kb.data_product_member.body)) AS ddo_identity_1 
FROM kb.data_product_member 
WHERE kb.data_product_member.product_id = (manifest_input.value ->> 'product_id') AND kb.data_product_member.member_id = (manifest_input.value ->> 'member_id')) END = (mv ->> 'product') AND (manifest_input.value ->> 'member_id') IS NOT DISTINCT FROM (mv ->> 'member') AND (manifest_input.value ->> 'multiplicity') = (mv ->> 'multiplicity') AND ((roledef ->> 'collection') != 'sequence' OR (manifest_input.value ->> 'position') IS NOT DISTINCT FROM (mv ->> 'position')) AND (NOT (roledef['identity_requirements'] ? 'episode') OR coalesce(mv['support_episodes'], CAST('[]' AS JSONB)) = ops.ddo_input_support_episodes(b, manifest_input.value)))) THEN
     RAISE EXCEPTION USING MESSAGE = 'semantic member occurrence counts differ from native manifest', ERRCODE = '23514';
    END IF;
    SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = (item ->> 'product_id') INTO STRICT x;
    PERFORM ops.ddo_authorize(sem.data_kind_contract.universe) AS ddo_authorize_1 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = x.kind_contract;
    SELECT kb.data_product_member.* 
FROM kb.data_product_member 
WHERE kb.data_product_member.product_id = x.id AND kb.data_product_member.member_id = (item ->> 'member_id') INTO native_member;
    IF (((mv ->> 'kind'), (mv ->> 'subject'), (mv ->> 'subject_definition'), (mv ->> 'original_source'), (mv ->> 'multiplicity')) IS DISTINCT FROM (coalesce(native_member.kind_contract, x.kind_contract), coalesce(native_member.subject, x.subject), coalesce(native_member.subject_definition, x.subject_definition), x.original_source, (item ->> 'multiplicity')) OR mv['analyzed_scope'] IS DISTINCT FROM coalesce(native_member.analyzed_scope, x.analyzed_scope)) THEN
     RAISE EXCEPTION USING MESSAGE = 'semantic request member differs from native product/member', ERRCODE = '23514';
    END IF;
    SELECT coalesce(jsonb_agg((to_jsonb(data_member_coverage) - 'product_id') - 'member_id' ORDER BY kb.data_member_coverage.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM kb.data_member_coverage 
WHERE kb.data_member_coverage.product_id = x.id AND kb.data_member_coverage.member_id = (item ->> 'member_id') INTO expected;
    IF (mv['coverage'] IS DISTINCT FROM expected) THEN
     RAISE EXCEPTION USING MESSAGE = 'semantic input coverage differs from native projection', ERRCODE = '23514';
    END IF;
    IF ((roledef ->> 'presence') = 'alternative' OR (roledef['identity_requirements'] ? 'alternative')) THEN
     SELECT CASE WHEN (count(DISTINCT source_request.operation_id) = 1) THEN min(source_request.operation_id) ELSE NULL END AS anon_1 
FROM ops.ddo_input_support_refs(b, item) AS selected_reference(value) JOIN ops.data_derivation AS source_episode ON source_episode.id = (selected_reference.value ->> 'derivation_id') JOIN ops.data_request AS source_request ON source_request.id = source_episode.request_id 
WHERE (selected_reference.value ->> 'role') = (roledef ->> 'name') AND (selected_reference.value ->> 'position') IS NOT DISTINCT FROM (item ->> 'position') AND (EXISTS (SELECT ops.data_derivation_output.product_id 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = source_episode.id AND ops.data_derivation_output.product_id = (item ->> 'product_id'))) INTO lexical_alternative;
     IF (lexical_alternative IS NULL OR (roledef ->> 'presence') = 'alternative' AND (rv ->> 'selected_alternative') IS DISTINCT FROM lexical_alternative OR (roledef['identity_requirements'] ? 'alternative') AND (mv ->> 'alternative') IS DISTINCT FROM lexical_alternative) THEN
      RAISE EXCEPTION USING MESSAGE = 'selected alternative differs from actual producing operation', ERRCODE = '23514';
     END IF;
    END IF;
    IF ((roledef['identity_requirements'] ? 'original-source') AND (EXISTS (SELECT selected_reference.value 
FROM ops.ddo_input_support_refs(b, item) AS selected_reference(value) 
WHERE (selected_reference.value ->> 'kind') IN ('original-source', 'authored')))) THEN
     SELECT coalesce(jsonb_agg(original.identity ORDER BY original.identity), CAST('[]' AS JSONB)) AS coalesce_1 
FROM (SELECT DISTINCT selected_reference.value ->> 'source_reference' AS identity 
FROM ops.ddo_input_support_refs(b, item) AS selected_reference(value) 
WHERE (selected_reference.value ->> 'kind') IN ('original-source', 'authored')) AS original INTO expected;
     IF (mv['original_sources'] IS DISTINCT FROM expected) THEN
      RAISE EXCEPTION USING MESSAGE = 'original source identity differs from selected authentic facts', ERRCODE = '23514';
     END IF;
    END IF;
    IF (roledef['identity_requirements'] ? 'provider') THEN
     SELECT CASE WHEN (count(DISTINCT authenticated.provider) = 1 AND count(*) = count(authenticated.provider)) THEN min(authenticated.provider) ELSE NULL END AS anon_1 
FROM (SELECT ops.ddo_episode_provider_identity(selected_reference.value ->> 'derivation_id') AS provider 
FROM ops.ddo_input_support_refs(b, item) AS selected_reference(value) 
WHERE coalesce((selected_reference.value ->> 'kind'), 'computation') = 'computation') AS authenticated INTO lexical_alternative;
     IF (lexical_alternative IS NULL OR (mv ->> 'provider') IS DISTINCT FROM lexical_alternative) THEN
      RAISE EXCEPTION USING MESSAGE = 'provider identity differs from authentic producing custody', ERRCODE = '23514';
     END IF;
    END IF;
    IF ((roledef['identity_requirements'] ? 'episode') AND (EXISTS (SELECT selected_reference.value 
FROM ops.ddo_input_support_refs(b, item) AS selected_reference(value) 
WHERE coalesce((selected_reference.value ->> 'kind'), 'computation') = 'computation'))) THEN
     expected := ops.ddo_input_support_episodes(b, item);
     IF (expected = CAST('[]' AS JSONB) OR mv['support_episodes'] IS DISTINCT FROM expected) THEN
      RAISE EXCEPTION USING MESSAGE = 'required episode identity differs from selected authentic support', ERRCODE = '23514';
     END IF;
    END IF;
   END LOOP;
   IF (jsonb_array_length(rv['value']) != (SELECT count(*) AS count_1 
FROM jsonb_array_elements(b['inputs']) AS manifest_input(value) 
WHERE (manifest_input.value ->> 'role') = (roledef ->> 'name'))) THEN
    RAISE EXCEPTION USING MESSAGE = 'native input manifest differs from semantic request members', ERRCODE = '23514';
   END IF;
  END IF;
 END LOOP;
END

