CREATE OR REPLACE FUNCTION ops.ddo_validate_parameters(operation jsonb, selection jsonb, model jsonb) RETURNS void LANGUAGE plpgsql IMMUTABLE RETURNS NULL ON NULL INPUT SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 definitions jsonb := operation['parameters']['json'];
 name text;
 definition jsonb;
 value jsonb;
 item jsonb;
 kind text;
BEGIN
 IF (jsonb_typeof(selection['parameters']) IS DISTINCT FROM 'object' OR selection['parameter_meaning'] IS NULL OR data.ddo_json(data.ddo_normalize(selection['parameter_meaning'])) IS DISTINCT FROM selection['parameters']) THEN
  RAISE EXCEPTION USING MESSAGE = 'frozen parameter display differs from exact typed meaning', ERRCODE = 'P0001';
 END IF;
 IF ((EXISTS (SELECT declared.key 
FROM jsonb_each(definitions) AS declared(key, value) 
WHERE (declared.value ? 'kind'))) AND (EXISTS (SELECT selected.key 
FROM jsonb_each(selection['parameters']) AS selected(key, value) 
WHERE NOT ((definitions ? selected.key))))) THEN
  RAISE EXCEPTION USING MESSAGE = 'undeclared frozen nominal operation parameter', ERRCODE = 'P0001';
 END IF;
 FOR name, definition IN SELECT declared.key, declared.value 
FROM jsonb_each(definitions) AS declared(key, value) LOOP
  IF (NOT ((definition ? 'kind') OR (definition ? 'value_type'))) THEN
   CONTINUE;
  END IF;
  IF (NOT (selection['parameters'] ? name)) THEN
   IF ((definition ? 'default') OR coalesce((definition ->> 'required'), 'true') = 'true') THEN
    RAISE EXCEPTION USING MESSAGE = format('missing frozen demand parameter %s', name), ERRCODE = 'P0001';
   END IF;
   CONTINUE;
  END IF;
  value := data.ddo_field(selection['parameter_meaning'], name);
  IF (definition ? 'kind') THEN
   IF (jsonb_typeof(definition['body_schema']) IS DISTINCT FROM 'object' OR jsonb_typeof(definition['meaning_schema']) IS DISTINCT FROM 'object' OR NOT public.json_matches_schema(CAST(definition['body_schema'] AS JSON), CAST(selection['parameters'][name] AS JSON)) OR NOT public.json_matches_schema(CAST(definition['meaning_schema'] AS JSON), CAST(value AS JSON))) THEN
    RAISE EXCEPTION USING MESSAGE = format('nominal frozen parameter violates captured schema: %s', name), ERRCODE = 'P0001';
   END IF;
  ELSE
   kind := ops.ddo_binding_type(jsonb_build_object('model', model), definition ->> 'value_type');
   IF (coalesce((definition ->> 'many'), 'false') = 'true') THEN
    IF ((value ->> 0) IS DISTINCT FROM 'sequence') THEN
     RAISE EXCEPTION USING MESSAGE = 'frozen parameter must be a typed sequence', ERRCODE = 'P0001';
    END IF;
    FOR item IN SELECT parameter_item.value 
FROM jsonb_array_elements(value[1]) AS parameter_item(value) LOOP
     PERFORM ops.ddo_binding_typed(item, kind);
    END LOOP;
   ELSE
    PERFORM ops.ddo_binding_typed(value, kind);
   END IF;
  END IF;
 END LOOP;
END$$

