DECLARE
 named record;
 entry jsonb;
 acquired jsonb;
 proof jsonb;
 mode_ text;
 entries_by_address jsonb;
 proof_addresses jsonb;
BEGIN
 IF (pg_catalog.jsonb_typeof(source_sets) != 'object') THEN
  RAISE EXCEPTION USING MESSAGE = 'frozen source sets must be a named object', ERRCODE = 'P0001';
 END IF;
 FOR named IN SELECT source_set_item.key, source_set_item.value 
FROM pg_catalog.jsonb_each(source_sets) AS source_set_item(key, value) LOOP
  PERFORM ops.ddo_fields(named.value, ARRAY['entries', 'acquisition']);
  IF (named.key = '' OR pg_catalog.jsonb_typeof(named.value['entries']) IS DISTINCT FROM 'array') THEN
   RAISE EXCEPTION USING MESSAGE = 'source set requires an explicit name and current acquisition envelope', ERRCODE = 'P0001';
  END IF;
  SELECT coalesce(jsonb_object_agg(CAST(pg_catalog.jsonb_build_array(entry_item.value ->> 'product', entry_item.value ->> 'member') AS TEXT), entry_item.value), CAST('{}' AS JSONB)) AS coalesce_1 
FROM pg_catalog.jsonb_array_elements(named.value['entries']) AS entry_item(value) INTO entries_by_address;
  mode_ := (named.value['acquisition']) ->> 'kind';
  IF ((mode_ NOT IN ('selected-support-v1', 'all-admissible-support-v1')) OR mode_ IS NULL) THEN
   RAISE EXCEPTION USING MESSAGE = 'unsupported source acquisition kind', ERRCODE = 'P0001';
  END IF;
  IF (mode_ = 'all-admissible-support-v1') THEN
   PERFORM ops.ddo_fields(named.value['acquisition'], ARRAY['kind']);
  ELSE
   PERFORM ops.ddo_fields(named.value['acquisition'], ARRAY['kind', 'reads']);
   IF (pg_catalog.jsonb_typeof(named.value['acquisition']['reads']) IS DISTINCT FROM 'array') THEN
    RAISE EXCEPTION USING MESSAGE = 'source acquisition requires exact grouped reads', ERRCODE = 'P0001';
   END IF;
   IF (EXISTS (SELECT 1 
FROM pg_catalog.jsonb_array_elements(named.value['acquisition']['reads']) AS read_item(value) GROUP BY (read_item.value['selection']) ->> 'cut_id' 
HAVING count(*) != 1)) THEN
    RAISE EXCEPTION USING MESSAGE = 'duplicate source acquisition cut', ERRCODE = 'P0001';
   END IF;
   FOR acquired IN SELECT read_item.value 
FROM pg_catalog.jsonb_array_elements(named.value['acquisition']['reads']) AS read_item(value) LOOP
    PERFORM ops.ddo_fields(acquired, ARRAY['selection', 'proofs']);
    IF (((acquired['selection']) ->> 'project_id') IS DISTINCT FROM project OR jsonb_array_length(acquired['proofs']) = 0) THEN
     RAISE EXCEPTION USING MESSAGE = 'source acquisition changes project or has empty proof group', ERRCODE = 'P0001';
    END IF;
    IF (EXISTS (SELECT 1 
FROM pg_catalog.jsonb_array_elements(acquired['proofs']) AS proof_item(value) GROUP BY proof_item.value 
HAVING count(*) != 1)) THEN
     RAISE EXCEPTION USING MESSAGE = 'duplicate source acquisition proof', ERRCODE = 'P0001';
    END IF;
    FOR proof IN SELECT proof_item.value 
FROM pg_catalog.jsonb_array_elements(acquired['proofs']) AS proof_item(value) LOOP
     IF (NOT ((entries_by_address ? CAST(pg_catalog.jsonb_build_array((proof ->> 'product_id'), (proof ->> 'member_id')) AS TEXT))) OR ((proof['support']) ->> 'kind') IS DISTINCT FROM 'computation' OR nullif(((proof['support']) ->> 'admission_use_id'), '') IS NULL OR ((proof['output']) ->> 'member_id') IS NOT NULL AND ((proof['output']) ->> 'member_id') IS DISTINCT FROM (proof ->> 'member_id')) THEN
      RAISE EXCEPTION USING MESSAGE = 'source proof differs from its semantic address/emitting member', ERRCODE = 'P0001';
     END IF;
    END LOOP;
   END LOOP;
  END IF;
  SELECT coalesce(jsonb_object_agg(CAST(pg_catalog.jsonb_build_array(proof_address.value ->> 'product_id', proof_address.value ->> 'member_id') AS TEXT), true), CAST('{}' AS JSONB)) AS coalesce_1 
FROM pg_catalog.jsonb_array_elements(coalesce(named.value['acquisition']['reads'], CAST('[]' AS JSONB))) AS proof_read(value) JOIN pg_catalog.jsonb_array_elements(proof_read.value['proofs']) AS proof_address(value) ON true INTO proof_addresses;
  IF (EXISTS (SELECT 1 
FROM pg_catalog.jsonb_array_elements(named.value['entries']) AS entry_item(value) GROUP BY entry_item.value ->> 'product', entry_item.value ->> 'member' 
HAVING count(*) != 1)) THEN
   RAISE EXCEPTION USING MESSAGE = 'duplicate qualified source-set product/member', ERRCODE = 'P0001';
  END IF;
  FOR entry IN SELECT entry_item.value 
FROM pg_catalog.jsonb_array_elements(named.value['entries']) AS entry_item(value) LOOP
   PERFORM ops.ddo_fields(entry, ARRAY['project_id', 'original_source', 'subject', 'analyzed_scope', 'subject_definition', 'product', 'member', 'source_reference', 'reference']);
   IF ((EXISTS (SELECT 1 
FROM unnest(ARRAY['project_id', 'subject', 'subject_definition', 'product', 'source_reference']) AS entry_field(value) 
WHERE pg_catalog.jsonb_typeof(entry -> entry_field.value) IS DISTINCT FROM 'string')) OR (pg_catalog.jsonb_typeof(entry['member']) NOT IN ('string', 'null')) OR (entry ->> 'project_id') IS DISTINCT FROM project OR (pg_catalog.jsonb_typeof(entry['original_source']) NOT IN ('string', 'null')) OR nullif((entry ->> 'subject'), '') IS NULL OR nullif((entry ->> 'subject_definition'), '') IS NULL OR nullif((entry ->> 'product'), '') IS NULL OR entry['member'] != CAST('null' AS JSONB) AND nullif((entry ->> 'member'), '') IS NULL) THEN
    RAISE EXCEPTION USING MESSAGE = 'source-set entry differs from original qualified reference', ERRCODE = 'P0001';
   END IF;
   PERFORM ops.ddo_require_subject_source(subject_scopes, entry ->> 'subject_definition', entry ->> 'original_source');
   IF (NOT ops.ddo_semantic_source_reference(entry['reference'])) THEN
    RAISE EXCEPTION USING MESSAGE = 'source sets require exact semantic product/member references', ERRCODE = 'P0001';
   END IF;
   IF (((entry['reference']) ->> 'product_id') IS DISTINCT FROM (entry ->> 'product') OR ((entry['reference']) ->> 'member_id') IS DISTINCT FROM (entry ->> 'member') OR (entry ->> 'source_reference') IS DISTINCT FROM (CASE WHEN ((entry['reference'] ? 'member_id')) THEN 'member:' || ops.ddo_digest(entry['reference']) ELSE (entry ->> 'product') END)) THEN
    RAISE EXCEPTION USING MESSAGE = 'source-set semantic reference differs from exact native product/member', ERRCODE = 'P0001';
   END IF;
   IF (mode_ = 'selected-support-v1' AND NOT ((proof_addresses ? CAST(pg_catalog.jsonb_build_array((entry ->> 'product'), (entry ->> 'member')) AS TEXT)))) THEN
    RAISE EXCEPTION USING MESSAGE = 'source entry lacks explicit producing proof', ERRCODE = 'P0001';
   END IF;
  END LOOP;
 END LOOP;
END

