DECLARE
 u ops.demand_use%ROWTYPE;
 pop ops.data_population%ROWTYPE;
 admission ops.original_source_admission%ROWTYPE;
BEGIN
 IF (p_kind = 'producer') THEN
  RETURN (EXISTS (SELECT 1 
FROM ops.data_derivation JOIN ops.data_request ON ops.data_request.id = ops.data_derivation.request_id JOIN sem.data_operation_definition ON sem.data_operation_definition.release_id = ops.data_derivation.release_id AND sem.data_operation_definition.recipe = ops.data_derivation.recipe AND sem.data_operation_definition.operation_id = ops.data_request.operation_id 
WHERE ops.data_derivation.id = p_id AND ops.data_derivation.outcome IN ('success', 'empty') AND (NOT ((sem.data_operation_definition.validity_families @> ARRAY['record-grade'])) OR coalesce(ops.ddo_record_grade_dependencies_valid(p_id), false)) AND (NOT ((sem.data_operation_definition.validity_families @> ARRAY['record-fit'])) OR coalesce(ops.ddo_record_fit_dependencies_valid(p_id), false)) AND (NOT ((sem.data_operation_definition.validity_families @> ARRAY['operation-event'])) OR coalesce(ops.ddo_operation_event_dependencies_valid(p_id), false)) AND (NOT ((sem.data_operation_definition.validity_families @> ARRAY['contextual'])) OR coalesce(ops.ddo_contextual_dependencies_valid(p_id), false)) AND (NOT ((sem.data_operation_definition.validity_families @> ARRAY['definition'])) OR coalesce(ops.ddo_definition_dependencies_valid(p_id), false)) AND (NOT ((sem.data_operation_definition.validity_families @> ARRAY['artifact'])) OR coalesce(ops.ddo_artifact_dependencies_valid(p_id), false)) AND (NOT ((sem.data_operation_definition.validity_families @> ARRAY['rich'])) OR coalesce(ops.ddo_rich_admission_dependencies_valid(p_id), false)) AND (NOT sem.data_operation_definition.validity_conservative OR coalesce(ops.ddo_conservative_dependencies_valid(p_id), false)))) AND NOT (EXISTS (SELECT 1 
FROM ops.data_derivation JOIN ops.data_request ON ops.data_request.id = ops.data_derivation.request_id JOIN ops.data_revocation ON ops.data_revocation.scope = ops.ddo_scope(ops.data_request.project_id, ops.data_request.original_source) 
WHERE ops.data_derivation.id = p_id AND (ops.data_revocation.selector_kind = 'derivation' AND ops.data_revocation.selector = ops.data_derivation.id OR ops.data_revocation.selector_kind = 'recipe' AND ops.data_revocation.selector = ops.data_derivation.recipe OR ops.data_revocation.selector_kind = 'runtime' AND ops.data_revocation.selector = ops.data_derivation.runtime_id OR ops.data_revocation.selector_kind = 'product' AND (EXISTS (SELECT 1 
FROM ops.data_derivation_output 
WHERE ops.data_derivation_output.derivation_id = ops.data_derivation.id AND ops.data_derivation_output.product_id = ops.data_revocation.selector)))));
 END IF;
 IF (p_kind = 'episode') THEN
  RETURN (EXISTS (SELECT 1 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = p_id)) AND NOT (EXISTS (SELECT 1 
FROM ops.data_derivation_support LEFT OUTER JOIN ops.demand_use AS selected_support_use ON selected_support_use.id = ops.data_derivation_support.admission_use_id AND selected_support_use.derivation_id = ops.data_derivation_support.support_derivation_id 
WHERE ops.data_derivation_support.derivation_id = p_id AND ops.data_derivation_support.admission_use_id IS NOT NULL AND selected_support_use.id IS NULL));
 END IF;
 IF (p_kind = 'original') THEN
  SELECT ops.original_source_admission.* 
FROM ops.original_source_admission 
WHERE ops.original_source_admission.id = p_id INTO admission;
  RETURN ops.ddo_original_admission_valid(admission, boundary);
 END IF;
 IF (p_kind = 'use') THEN
  SELECT ops.demand_use.* 
FROM ops.demand_use 
WHERE ops.demand_use.id = p_id INTO u;
  RETURN coalesce(u.fate = 'fulfilled', false) AND u.derivation_id IS NOT NULL AND NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(coalesce(u.selection['populations'], CAST('[]' AS JSONB))) AS selected_population LEFT OUTER JOIN ops.data_population ON ops.data_population.id = (selected_population.value ->> 'population_id') AND ops.data_population.demand_id = u.demand_id 
WHERE ops.data_population.id IS NULL)) AND NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(coalesce(u.selection['support'], CAST('[]' AS JSONB))) AS support_ref LEFT OUTER JOIN ops.demand_use AS selected_support_use ON selected_support_use.id = (support_ref.value ->> 'admission_use_id') AND selected_support_use.derivation_id = (support_ref.value ->> 'derivation_id') LEFT OUTER JOIN ops.original_source_admission ON ops.original_source_admission.id = (support_ref.value ->> 'admission_id') AND ops.original_source_admission.source_reference = (support_ref.value ->> 'source_reference') 
WHERE (support_ref.value ->> 'admission_use_id') IS NOT NULL AND selected_support_use.id IS NULL OR (support_ref.value ->> 'kind') IN ('original-source', 'authored') AND ops.original_source_admission.id IS NULL));
 END IF;
 IF (p_kind = 'population') THEN
  SELECT ops.data_population.* 
FROM ops.data_population 
WHERE ops.data_population.id = p_id INTO pop;
  RETURN pop.id IS NOT NULL AND (EXISTS (SELECT 1 
FROM ops.demand_use 
WHERE ops.demand_use.id = (pop.evidence ->> 'admission_use_id') AND ops.demand_use.demand_id = pop.demand_id AND ops.demand_use.derivation_id = (pop.evidence ->> 'derivation_id'))) AND (NOT ((pop.evidence ? 'selection')) OR (EXISTS (SELECT 1 
FROM ops.data_population 
WHERE ops.data_population.id = ((pop.evidence['selection']) ->> 'parent_population_id') AND ops.data_population.demand_id = pop.demand_id AND ops.data_population.id != pop.id))) AND NOT (EXISTS (SELECT 1 
FROM ops.data_population 
WHERE ops.data_population.demand_id = pop.demand_id AND ops.data_population.name = pop.name AND ops.data_population.context_key = pop.context_key AND (ops.data_population.created_at, ops.data_population.id) > (pop.created_at, pop.id) AND (boundary.id IS NULL OR ops.ddo_read_visible(ops.data_population.created_at, ops.data_population.created_xid, boundary))));
 END IF;
 RETURN false;
END

