DECLARE
 b ops.pdf_stage_build%ROWTYPE;
 o ops.pdf_roundtrip_oracle%ROWTYPE;
BEGIN
 b := ops.require_pdf_frozen(p_build, p_task, p_attempt, p_holder, p_frozen);
 SELECT ops.pdf_roundtrip_oracle.oracle_receipt_id, ops.pdf_roundtrip_oracle.build_id, ops.pdf_roundtrip_oracle.attempt, ops.pdf_roundtrip_oracle.holder, ops.pdf_roundtrip_oracle.frozen_digest, ops.pdf_roundtrip_oracle.lowering_identity, ops.pdf_roundtrip_oracle.kind, ops.pdf_roundtrip_oracle.logical_digest, ops.pdf_roundtrip_oracle.native_document_digest, ops.pdf_roundtrip_oracle.state, ops.pdf_roundtrip_oracle.actual_native_digest, ops.pdf_roundtrip_oracle.error_message 
FROM ops.pdf_roundtrip_oracle 
WHERE ops.pdf_roundtrip_oracle.oracle_receipt_id = p_oracle FOR UPDATE INTO STRICT o;
 IF ((o.build_id, o.attempt, o.holder, o.frozen_digest) IS DISTINCT FROM (p_build, p_attempt, p_holder, p_frozen) OR (p_state NOT IN ('passed', 'failed', 'interrupted')) OR p_state IS NULL OR p_state = 'passed' AND (p_actual IS DISTINCT FROM o.native_document_digest OR p_error IS NOT NULL) OR p_state != 'passed' AND nullif(p_error, '') IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF round-trip oracle result differs from original producer', ERRCODE = '23514';
 END IF;
 IF (o.state != 'running') THEN
  IF ((o.state, o.actual_native_digest, o.error_message) IS NOT DISTINCT FROM (p_state, p_actual, p_error)) THEN
   RETURN;
  END IF;
  RAISE EXCEPTION USING MESSAGE = 'completed PDF oracle receipt is immutable', ERRCODE = '23514';
 END IF;
 UPDATE ops.pdf_roundtrip_oracle SET state=p_state, actual_native_digest=p_actual, error_message=p_error WHERE ops.pdf_roundtrip_oracle.oracle_receipt_id = p_oracle;
END

