DECLARE
 b ops.pdf_stage_build%ROWTYPE;
 owner record;
 f text;
 state_ bytea := ops.pdf_identity_fold_start('pdf-frozen-inventory-v1');
 body_ jsonb;
 payload bytea;
 count_ bigint := 0;
 total_ bigint := 0;
 family_count_ bigint;
 inventory_ jsonb := CAST('{}' AS JSONB);
BEGIN
 IF (NOT (current_setting('transaction_isolation') = ANY (ARRAY['read committed']))) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF freeze requires READ COMMITTED', ERRCODE = '25000';
 END IF;
 SELECT anon_1.project_id, anon_1.release_id, anon_1.request_id, anon_1.generation, anon_1.document_id, anon_1.source_digest 
FROM ops.pdf_task_context(p_task) AS anon_1 INTO STRICT owner;
 IF (NOT ops.pdf_stage_owner_current(p_task, p_attempt, p_holder)) THEN
  RAISE EXCEPTION USING MESSAGE = 'stale private PDF build owner', ERRCODE = 'P0004';
 END IF;
 SELECT ops.pdf_stage_build.build_id, ops.pdf_stage_build.task_id, ops.pdf_stage_build.release_id, ops.pdf_stage_build.source_digest, ops.pdf_stage_build.recipe_digest, ops.pdf_stage_build.schema_digest, ops.pdf_stage_build.replay_key, ops.pdf_stage_build.attempt, ops.pdf_stage_build.holder, ops.pdf_stage_build.state 
FROM ops.pdf_stage_build 
WHERE ops.pdf_stage_build.build_id = p_build AND ops.pdf_stage_build.task_id = p_task INTO STRICT b;
 IF (b.attempt IS DISTINCT FROM p_attempt OR b.holder IS DISTINCT FROM p_holder OR b.state = 'abandoned') THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF freeze owner differs', ERRCODE = '23514';
 END IF;
 SELECT ops.pdf_frozen_build.frozen_digest 
FROM ops.pdf_frozen_build 
WHERE ops.pdf_frozen_build.build_id = p_build INTO f;
 IF (found) THEN
  PERFORM ops.require_pdf_stage_owner(p_task, p_attempt, p_holder);
  SELECT ops.pdf_stage_build.build_id, ops.pdf_stage_build.task_id, ops.pdf_stage_build.release_id, ops.pdf_stage_build.source_digest, ops.pdf_stage_build.recipe_digest, ops.pdf_stage_build.schema_digest, ops.pdf_stage_build.replay_key, ops.pdf_stage_build.attempt, ops.pdf_stage_build.holder, ops.pdf_stage_build.state 
FROM ops.pdf_stage_build 
WHERE ops.pdf_stage_build.build_id = p_build AND ops.pdf_stage_build.task_id = p_task FOR UPDATE INTO STRICT b;
  IF (b.attempt IS DISTINCT FROM p_attempt OR b.holder IS DISTINCT FROM p_holder OR b.state = 'abandoned') THEN
   RAISE EXCEPTION USING MESSAGE = 'PDF freeze owner differs', ERRCODE = '23514';
  END IF;
  IF (p_kind IS DISTINCT FROM (SELECT ops.pdf_frozen_build.kind 
FROM ops.pdf_frozen_build 
WHERE ops.pdf_frozen_build.build_id = p_build)) THEN
   RAISE EXCEPTION USING MESSAGE = 'frozen publication kind differs', ERRCODE = 'P0001';
  END IF;
  RETURN f;
 END IF;
 PERFORM ops.require_pdf_operation(b.release_id, 'freeze_pdf_build');
 IF (NOT (NOT (EXISTS (SELECT 1 
FROM ops.pdf_stage_artifact_stream 
WHERE ops.pdf_stage_artifact_stream.product_id = p_build AND ops.pdf_stage_artifact_stream.revision_id = p_build AND NOT ops.pdf_shared_stream_ready(p_build, ops.pdf_stage_artifact_stream.encoding_profile, ops.pdf_stage_artifact_stream.byte_length, ops.pdf_stage_artifact_stream.byte_root))))) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF freeze requires verified project-scoped stream bytes', ERRCODE = '23514';
 END IF;
 family_count_ := 0;
 FOR body_ IN SELECT to_jsonb(t) AS to_jsonb_1 
FROM ops.pdf_stage_access AS t 
WHERE t.product_id = p_build ORDER BY t.product_id, t.revision_id, t.pointer LOOP
  payload := convert_to(CAST(body_ AS TEXT), 'UTF8');
  state_ := ops.pdf_identity_fold_step(state_, count_, convert_to('access:', 'UTF8') || sha256(payload));
  count_ := count_ + 1;
  total_ := total_ + octet_length(payload);
  family_count_ := family_count_ + 1;
 END LOOP;
 inventory_ := inventory_ || jsonb_build_object('access', family_count_);
 family_count_ := 0;
 FOR body_ IN SELECT to_jsonb(t) AS to_jsonb_1 
FROM ops.pdf_stage_artifact_stream AS t 
WHERE t.product_id = p_build ORDER BY t.product_id, t.revision_id, t.stream_id LOOP
  payload := convert_to(CAST(body_ AS TEXT), 'UTF8');
  state_ := ops.pdf_identity_fold_step(state_, count_, convert_to('artifact_stream:', 'UTF8') || sha256(payload));
  count_ := count_ + 1;
  total_ := total_ + octet_length(payload);
  family_count_ := family_count_ + 1;
 END LOOP;
 inventory_ := inventory_ || jsonb_build_object('artifact_stream', family_count_);
 family_count_ := 0;
 FOR body_ IN SELECT to_jsonb(t) AS to_jsonb_1 
FROM ops.pdf_stage_companion AS t 
WHERE t.product_id = p_build ORDER BY t.product_id, t.revision_id, t.family, t.local_id LOOP
  payload := convert_to(CAST(body_ AS TEXT), 'UTF8');
  state_ := ops.pdf_identity_fold_step(state_, count_, convert_to('companion:', 'UTF8') || sha256(payload));
