  RAISE EXCEPTION USING MESSAGE = 'data task requires protected admitted request generation', ERRCODE = '23514';
 END IF;
 IF (tg_op = 'INSERT') THEN
  IF (new.status != 'pending' OR new.attempt != 0 OR new.claimed_by IS NOT NULL OR new.lease_until IS NOT NULL) THEN
   RAISE EXCEPTION USING MESSAGE = 'invalid initial data task', ERRCODE = 'P0001';
  END IF;
 ELSE
  IF ((new.data_request_id, new.data_generation, new.release_id, new.invocation_key) IS DISTINCT FROM (old.data_request_id, old.data_generation, old.release_id, old.invocation_key) OR old.status IN ('done', 'empty', 'failed', 'cancelled')) THEN
   RAISE EXCEPTION USING MESSAGE = 'data task association/terminal state immutable', ERRCODE = 'P0001';
  END IF;
  IF (new.attempt != old.attempt) THEN
   IF (new.attempt != old.attempt + 1 OR new.status != 'running' OR nullif(new.claimed_by, '') IS NULL OR new.lease_until IS NULL OR new.lease_until <= pg_catalog.clock_timestamp() OR ((old.status, new.status) NOT IN (('pending', 'running'), ('running', 'running'))) OR old.status = 'running' AND (old.lease_until IS NULL OR old.lease_until > pg_catalog.clock_timestamp())) THEN
    RAISE EXCEPTION USING MESSAGE = 'invalid data claim fence', ERRCODE = 'P0001';
   END IF;
  ELSE
   IF (new.claimed_by IS DISTINCT FROM old.claimed_by) THEN
    RAISE EXCEPTION USING MESSAGE = 'data holder requires new attempt', ERRCODE = 'P0001';
   ELSE
    IF (new.status != old.status AND ((old.status, new.status) NOT IN (('running', 'pending'), ('running', 'done'), ('running', 'empty'), ('running', 'failed'), ('running', 'cancelled')))) THEN
     RAISE EXCEPTION USING MESSAGE = 'invalid data task transition', ERRCODE = 'P0001';
    END IF;
   END IF;
  END IF;
 END IF;
 IF (new.status = 'running' AND (new.attempt <= 0 OR new.claimed_by IS NULL OR new.lease_until IS NULL)) THEN
  RAISE EXCEPTION USING MESSAGE = 'data running task requires exact fence', ERRCODE = 'P0001';
 END IF;
 IF (new.status != 'running' AND new.lease_until IS NOT NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'data terminal task retains lease', ERRCODE = 'P0001';
 END IF;
 IF (new.status IN ('done', 'empty', 'failed') AND new.result_digest IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'data completion requires receipt', ERRCODE = 'P0001';
 END IF;
 RETURN new;
END

