DECLARE
 stream ops.pdf_stage_artifact_stream%ROWTYPE;
 project text := ops.pdf_stream_project(p_build);
 content ops.pdf_shared_stream%ROWTYPE;
 owner ops.pdf_stage_build%ROWTYPE;
BEGIN
 IF (project IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'shared stream has no actual build project', ERRCODE = '23514';
 END IF;
 SELECT ops.pdf_stage_build.build_id, ops.pdf_stage_build.task_id, ops.pdf_stage_build.release_id, ops.pdf_stage_build.source_digest, ops.pdf_stage_build.recipe_digest, ops.pdf_stage_build.schema_digest, ops.pdf_stage_build.replay_key, ops.pdf_stage_build.attempt, ops.pdf_stage_build.holder, ops.pdf_stage_build.state 
FROM ops.pdf_stage_build 
WHERE ops.pdf_stage_build.build_id = p_build INTO STRICT owner;
 FOR stream IN EXECUTE pg_catalog.format('SELECT product_id, revision_id, stream_id, byte_length, serialization_sha256, byte_root, encoding_profile FROM %s ORDER BY encoding_profile COLLATE "C", byte_length, byte_root COLLATE "C"', p_streams) LOOP
  INSERT INTO ops.pdf_shared_stream (project_id, encoding_profile, byte_length, byte_root, owner_build_id, owner_attempt, owner_holder) VALUES (project, stream.encoding_profile, stream.byte_length, stream.byte_root, owner.build_id, owner.attempt, owner.holder) ON CONFLICT DO NOTHING;
  SELECT ops.pdf_shared_stream.project_id, ops.pdf_shared_stream.encoding_profile, ops.pdf_shared_stream.byte_length, ops.pdf_shared_stream.byte_root, ops.pdf_shared_stream.owner_build_id, ops.pdf_shared_stream.owner_attempt, ops.pdf_shared_stream.owner_holder 
FROM ops.pdf_shared_stream 
WHERE ops.pdf_shared_stream.project_id = project AND ops.pdf_shared_stream.encoding_profile = stream.encoding_profile AND ops.pdf_shared_stream.byte_length = stream.byte_length AND ops.pdf_shared_stream.byte_root = stream.byte_root FOR UPDATE INTO STRICT content;
  IF (NOT ops.pdf_shared_stream_ready(p_build, stream.encoding_profile, stream.byte_length, stream.byte_root) AND (content.owner_build_id, content.owner_attempt, content.owner_holder) IS DISTINCT FROM (owner.build_id, owner.attempt, owner.holder)) THEN
   PERFORM ops.pdf_reclaim_pending_stream(project, stream.encoding_profile, stream.byte_length, stream.byte_root);
   INSERT INTO ops.pdf_shared_stream (project_id, encoding_profile, byte_length, byte_root, owner_build_id, owner_attempt, owner_holder) VALUES (project, stream.encoding_profile, stream.byte_length, stream.byte_root, owner.build_id, owner.attempt, owner.holder);
  END IF;
 END LOOP;
END

