DECLARE
 part_product_id text;
 part_revision_id text;
 part_stream_id text;
 part_ordinal bigint;
 part_byte_offset bigint;
 part_byte_length bigint;
 part_body bytea;
 part_sha256_digest text;
 stream ops.pdf_stage_artifact_stream%ROWTYPE;
 project text := ops.pdf_stream_project(p_build);
 retained ops.pdf_shared_stream_part%ROWTYPE;
 content ops.pdf_shared_stream%ROWTYPE;
 owner ops.pdf_stage_build%ROWTYPE;
BEGIN
 SELECT ops.pdf_stage_build.build_id, ops.pdf_stage_build.task_id, ops.pdf_stage_build.release_id, ops.pdf_stage_build.source_digest, ops.pdf_stage_build.recipe_digest, ops.pdf_stage_build.schema_digest, ops.pdf_stage_build.replay_key, ops.pdf_stage_build.attempt, ops.pdf_stage_build.holder, ops.pdf_stage_build.state 
FROM ops.pdf_stage_build 
WHERE ops.pdf_stage_build.build_id = p_build INTO STRICT owner;
 FOR part_product_id, part_revision_id, part_stream_id, part_ordinal, part_byte_offset, part_byte_length, part_body, part_sha256_digest IN EXECUTE pg_catalog.format('SELECT product_id, revision_id, stream_id, ordinal, byte_offset, byte_length, body, sha256_digest FROM %s ORDER BY stream_id COLLATE "C", ordinal', p_parts) LOOP
  SELECT ops.pdf_stage_artifact_stream.product_id, ops.pdf_stage_artifact_stream.revision_id, ops.pdf_stage_artifact_stream.stream_id, ops.pdf_stage_artifact_stream.byte_length, ops.pdf_stage_artifact_stream.serialization_sha256, ops.pdf_stage_artifact_stream.byte_root, ops.pdf_stage_artifact_stream.encoding_profile 
FROM ops.pdf_stage_artifact_stream 
WHERE ops.pdf_stage_artifact_stream.product_id = p_build AND ops.pdf_stage_artifact_stream.revision_id = p_build AND ops.pdf_stage_artifact_stream.stream_id = part_stream_id INTO stream;
  IF (NOT found) THEN
   RAISE EXCEPTION USING MESSAGE = 'shared parts require their descriptor before bytes', ERRCODE = '23514';
  END IF;
  IF (part_product_id IS DISTINCT FROM p_build OR part_revision_id IS DISTINCT FROM p_build OR part_ordinal < 0 OR part_byte_offset < 0 OR part_byte_length NOT BETWEEN 1 AND 65536 OR part_byte_length != octet_length(part_body) OR part_sha256_digest != encode(sha256(part_body), 'hex') OR part_byte_offset + part_byte_length > stream.byte_length) THEN
   RAISE EXCEPTION USING MESSAGE = 'shared stream incoming part differs from its descriptor/bytes', ERRCODE = '23514';
  END IF;
  SELECT ops.pdf_shared_stream.project_id, ops.pdf_shared_stream.encoding_profile, ops.pdf_shared_stream.byte_length, ops.pdf_shared_stream.byte_root, ops.pdf_shared_stream.owner_build_id, ops.pdf_shared_stream.owner_attempt, ops.pdf_shared_stream.owner_holder 
FROM ops.pdf_shared_stream 
WHERE ops.pdf_shared_stream.project_id = project AND ops.pdf_shared_stream.encoding_profile = stream.encoding_profile AND ops.pdf_shared_stream.byte_length = stream.byte_length AND ops.pdf_shared_stream.byte_root = stream.byte_root FOR UPDATE INTO STRICT content;
  IF (NOT ops.pdf_shared_stream_ready(p_build, stream.encoding_profile, stream.byte_length, stream.byte_root)) THEN
   IF ((content.owner_build_id, content.owner_attempt, content.owner_holder) IS DISTINCT FROM (owner.build_id, owner.attempt, owner.holder)) THEN
    RAISE EXCEPTION USING MESSAGE = 'pending shared parts belong to another append fence', ERRCODE = '55P03';
   END IF;
   INSERT INTO ops.pdf_shared_stream_part (project_id, encoding_profile, stream_length, byte_root, ordinal, byte_offset, byte_length, body, sha256_digest) VALUES (project, stream.encoding_profile, stream.byte_length, stream.byte_root, part_ordinal, part_byte_offset, part_byte_length, part_body, part_sha256_digest) ON CONFLICT DO NOTHING;
  END IF;
  SELECT ops.pdf_shared_stream_part.project_id, ops.pdf_shared_stream_part.encoding_profile, ops.pdf_shared_stream_part.stream_length, ops.pdf_shared_stream_part.byte_root, ops.pdf_shared_stream_part.ordinal, ops.pdf_shared_stream_part.byte_offset, ops.pdf_shared_stream_part.byte_length, ops.pdf_shared_stream_part.body, ops.pdf_shared_stream_part.sha256_digest 
FROM ops.pdf_shared_stream_part 
WHERE ops.pdf_shared_stream_part.project_id = project AND ops.pdf_shared_stream_part.encoding_profile = stream.encoding_profile AND ops.pdf_shared_stream_part.stream_length = stream.byte_length AND ops.pdf_shared_stream_part.byte_root = stream.byte_root AND ops.pdf_shared_stream_part.ordinal = part_ordinal INTO retained;
  IF (NOT found OR (retained.byte_offset, retained.byte_length, retained.body, retained.sha256_digest) IS DISTINCT FROM (part_byte_offset, part_byte_length, part_body, part_sha256_digest)) THEN
   RAISE EXCEPTION USING MESSAGE = 'shared stream part replay differs', ERRCODE = '23514';
  END IF;
 END LOOP;
END

