DECLARE
 f record;
 body_ jsonb := p_body;
 payload_ bytea;
BEGIN
 IF (NOT (EXISTS (SELECT 1 
FROM ops.pdf_published_revision JOIN kb.pdf_record_companion ON kb.pdf_record_companion.product_id = ops.pdf_published_revision.build_id AND kb.pdf_record_companion.revision_id = ops.pdf_published_revision.build_id 
WHERE ops.pdf_published_revision.build_id = p_product AND p_revision = p_product AND kb.pdf_record_companion.family = p_family AND kb.pdf_record_companion.local_id = p_local AND kb.pdf_record_companion.body = p_body))) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion field is not in a published revision', ERRCODE = 'P0001';
 END IF;
 IF (p_family = 'native_metadata' AND (p_body ->> 'kind') != 'recognition_coverage') THEN
  RAISE EXCEPTION USING MESSAGE = 'metadata value requires the lossless byte reader; SQL supports only typed recognition coverage', ERRCODE = 'P0001';
 END IF;
 FOR f IN SELECT kb.pdf_record_companion_field.product_id, kb.pdf_record_companion_field.revision_id, kb.pdf_record_companion_field.family, kb.pdf_record_companion_field.local_id, kb.pdf_record_companion_field.field_name, kb.pdf_record_companion_field.stream_id, kb.pdf_record_companion_field.scalar_kind 
FROM kb.pdf_record_companion_field 
WHERE kb.pdf_record_companion_field.product_id = p_product AND kb.pdf_record_companion_field.revision_id = p_revision AND kb.pdf_record_companion_field.family = p_family AND kb.pdf_record_companion_field.local_id = p_local ORDER BY kb.pdf_record_companion_field.field_name LOOP
  payload_ := ops.pdf_companion_field_bytes(p_product, p_revision, f.stream_id);
  body_ := body_ || jsonb_build_object(f.field_name, CASE WHEN (f.scalar_kind = 'y') THEN CAST(convert_from(payload_, 'UTF8') AS JSONB) ELSE to_jsonb(convert_from(payload_, 'UTF8')) END);
 END LOOP;
 RETURN body_;
END

