 IF (p_text COLLATE "C" !~ '[^ -~]') THEN
  RETURN CAST(to_jsonb(p_text) AS TEXT);
 END IF;
 RETURN ('"' || (SELECT string_agg(CASE WHEN (anon_1.code IN (34, 92)) THEN chr(92) || chr(anon_1.code) WHEN (anon_1.code = 8) THEN chr(92) || 'b' WHEN (anon_1.code = 9) THEN chr(92) || 't' WHEN (anon_1.code = 10) THEN chr(92) || 'n' WHEN (anon_1.code = 12) THEN chr(92) || 'f' WHEN (anon_1.code = 13) THEN chr(92) || 'r' WHEN (anon_1.code BETWEEN 32 AND 126 AND (anon_1.code NOT IN (34, 92))) THEN chr(anon_1.code) WHEN (anon_1.code <= 65535) THEN (chr(92) || 'u') || lpad(to_hex(anon_1.code), 4, '0') ELSE ((((chr(92) || 'u') || to_hex(55296 + (CAST(anon_1.code - 65536 AS INTEGER) / 1024))) || chr(92)) || 'u') || to_hex(56320 + (anon_1.code - 65536) % 1024) END, '' ORDER BY anon_1.i) AS string_agg_1 
FROM (SELECT anon_2.i AS i, ascii(substr(p_text, anon_2.i, 1)) AS code 
FROM generate_series(1, char_length(p_text)) AS anon_2(i)) AS anon_1)) || '"';
END

