DECLARE
 state bytea := ops.pdf_identity_fold_start('bytes');
 ordinal bigint := 0;
 offset_ integer := 1;
 block_ bytea;
BEGIN
 WHILE offset_ <= octet_length(p_payload) LOOP
  block_ := substr(p_payload, offset_, 65536);
  state := ops.pdf_identity_fold_step(state, ordinal, block_);
  offset_ := offset_ + octet_length(block_);
  ordinal := ordinal + 1;
 END LOOP;
 RETURN ops.pdf_identity_fold_finish(state, ordinal, CAST(octet_length(p_payload) AS BIGINT));
END

