 IF (found) THEN
  IF (p_body ? p_field) THEN
   RAISE EXCEPTION USING MESSAGE = 'companion field has competing inline and external values', ERRCODE = '23514';
  END IF;
  SELECT ops.pdf_artifact_stream.* 
