DECLARE
 root_ ops.pdf_product%ROWTYPE;
 pin_ ops.pdf_product%ROWTYPE;
 revision_ ops.pdf_published_revision%ROWTYPE;
 body_ ops.pdf_product_body%ROWTYPE;
 input_ ops.pdf_product_input%ROWTYPE;
 item_ jsonb;
 pending_ jsonb;
 next_ jsonb;
 resolved_ jsonb := CAST('{}' AS JSONB);
 target_ jsonb;
 inputs_ jsonb;
 selected_ jsonb;
 key_ text;
 root_key_ text;
 ready_ boolean;
 progress_ boolean;
 state_ bytea;
 frame_ bytea;
BEGIN
 SELECT ops.pdf_product.* 
FROM ops.pdf_product 
WHERE ops.pdf_product.task_id = p_task AND ops.pdf_product.product_key = p_key AND ops.pdf_product.content_digest = p_digest INTO STRICT root_;
 root_key_ := data.canonical_json(jsonb_build_array(p_task, p_key, p_digest));
 WITH RECURSIVE lineage(task_id, product_key, content_digest) AS 
(SELECT p_task AS task_id, p_key AS product_key, p_digest AS content_digest UNION SELECT ops.pdf_product_input.input_task_id AS input_task_id, ops.pdf_product_input.input_product_key AS input_product_key, ops.pdf_product_input.input_content_digest AS input_content_digest 
FROM ops.pdf_product_input JOIN lineage ON ops.pdf_product_input.task_id = lineage.task_id AND ops.pdf_product_input.product_key = lineage.product_key JOIN ops.pdf_product AS parent_product ON parent_product.task_id = lineage.task_id AND parent_product.product_key = lineage.product_key AND parent_product.content_digest = lineage.content_digest AND parent_product.kind = 'recognition_observation')
 SELECT jsonb_agg(to_jsonb(pdf_product) ORDER BY ops.pdf_product.task_id, ops.pdf_product.product_key COLLATE "C") AS jsonb_agg_1 
FROM lineage JOIN ops.pdf_product ON ops.pdf_product.task_id = lineage.task_id AND ops.pdf_product.product_key = lineage.product_key AND ops.pdf_product.content_digest = lineage.content_digest INTO pending_;
 WHILE jsonb_array_length(pending_) > 0 LOOP
  next_ := CAST('[]' AS JSONB);
  progress_ := false;
  FOR item_ IN SELECT anon_1.value 
FROM jsonb_array_elements(pending_) AS anon_1 LOOP
   pin_ := pg_catalog.jsonb_populate_record(CAST(NULL AS ops.pdf_product), item_);
   key_ := data.canonical_json(jsonb_build_array(pin_.task_id, pin_.product_key, pin_.content_digest));
   IF (pin_.artifact_digest IS DISTINCT FROM root_.artifact_digest) THEN
    RAISE EXCEPTION USING MESSAGE = 'logical PDF target changes original source', ERRCODE = '23514';
   END IF;
   PERFORM ops.pdf_contract_input(pin_.release_id, 'implementation/pdf/staging-model.yaml');
   IF (pin_.kind IN ('native', 'integrated')) THEN
    SELECT ops.pdf_published_revision.* 
FROM ops.pdf_published_revision JOIN ops.pdf_build_validation ON ops.pdf_build_validation.build_id = ops.pdf_published_revision.build_id AND ops.pdf_build_validation.frozen_digest = ops.pdf_published_revision.frozen_digest AND ops.pdf_build_validation.logical_digest = ops.pdf_published_revision.logical_digest AND ops.pdf_build_validation.native_callbacks 
WHERE ops.pdf_published_revision.task_id = pin_.task_id AND ops.pdf_published_revision.product_key = pin_.product_key AND ops.pdf_published_revision.logical_digest = pin_.content_digest AND ops.pdf_published_revision.kind = pin_.kind AND ops.pdf_published_revision.release_id = pin_.release_id AND ops.pdf_published_revision.source_digest = pin_.artifact_digest AND ops.pdf_build_validation.contract_digest = pin_.contract_digest AND encode(sha256(ops.pdf_contract_input(ops.pdf_published_revision.release_id, 'implementation/pdf/docling-validation.schema.json')), 'hex') = ops.pdf_published_revision.schema_digest INTO STRICT revision_;
    target_ := jsonb_build_object('version', 'pdf-published-target-v1', 'kind', revision_.kind, 'source_digest', revision_.source_digest, 'schema_digest', revision_.schema_digest, 'recipe_digest', revision_.recipe_digest, 'logical_digest', revision_.logical_digest);
   ELSE
    IF (pin_.kind = 'recognition_observation') THEN
     SELECT ops.pdf_product_body.* 
FROM ops.pdf_product_body 
WHERE ops.pdf_product_body.task_id = pin_.task_id AND ops.pdf_product_body.product_key = pin_.product_key AND encode(sha256(ops.pdf_product_body.payload), 'hex') = pin_.content_digest AND encode(sha256(ops.pdf_contract_input(pin_.release_id, 'schema/pdf_products')), 'hex') = pin_.contract_digest INTO STRICT body_;
     inputs_ := CAST('[]' AS JSONB);
     ready_ := true;
     FOR input_ IN SELECT ops.pdf_product_input.* 
FROM ops.pdf_product_input 
WHERE ops.pdf_product_input.task_id = pin_.task_id AND ops.pdf_product_input.product_key = pin_.product_key ORDER BY ops.pdf_product_input.input_index LOOP
      selected_ := resolved_[data.canonical_json(jsonb_build_array(input_.input_task_id, input_.input_product_key, input_.input_content_digest))];
      IF (selected_ IS NULL) THEN
       ready_ := false;
       EXIT;
      END IF;
      IF (input_.input_index != jsonb_array_length(inputs_)) THEN
       RAISE EXCEPTION USING MESSAGE = 'logical PDF target input inventory is not contiguous', ERRCODE = '23514';
      END IF;
      inputs_ := inputs_ || jsonb_build_array(jsonb_build_object('ordinal', input_.input_index, 'role', input_.role, 'target_meaning', selected_));
     END LOOP;
     IF (NOT ready_) THEN
      next_ := next_ || jsonb_build_array(item_);
      CONTINUE;
     END IF;
     IF (NOT (EXISTS (SELECT 1 
FROM ops.pdf_product_input 
WHERE ops.pdf_product_input.task_id = pin_.task_id AND ops.pdf_product_input.product_key = pin_.product_key AND ops.pdf_product_input.role = 'structural'))) THEN
      RAISE EXCEPTION USING MESSAGE = 'logical observation lacks authentic raw lineage', ERRCODE = '23514';
     END IF;
     state_ := ops.pdf_identity_fold_start('records');
     frame_ := ops.pdf_identity_record_frame(pin_.contract_digest, 'observation', 'root', ARRAY['profile', 'source', 'recipe', 'meaning', 'inputs'], ARRAY[ops.pdf_identity_text('pdf-published-target-v1'), ops.pdf_identity_text(pin_.artifact_digest), ops.pdf_identity_text(body_.recipe_digest), ops.pdf_identity_text(data.canonical_json(data.ddo_json_meaning(ops.pdf_observation_meaning(body_.payload)))), ops.pdf_identity_text(data.canonical_json(inputs_))]);
     state_ := ops.pdf_identity_fold_step(state_, CAST(0 AS BIGINT), frame_);
     target_ := jsonb_build_object('version', 'pdf-published-target-v1', 'kind', pin_.kind, 'source_digest', pin_.artifact_digest, 'schema_digest', pin_.contract_digest, 'recipe_digest', body_.recipe_digest, 'logical_digest', encode(ops.pdf_identity_fold_finish(state_, CAST(1 AS BIGINT), CAST(octet_length(frame_) AS BIGINT)), 'hex'));
    ELSE
     RAISE EXCEPTION USING MESSAGE = 'unsupported logical PDF target kind ' || pin_.kind, ERRCODE = '23514';
    END IF;
   END IF;
   resolved_ := jsonb_set(resolved_, ARRAY[key_], target_);
   progress_ := true;
  END LOOP;
  IF (NOT progress_) THEN
   RAISE EXCEPTION USING MESSAGE = 'logical PDF target has missing or cyclic input custody', ERRCODE = '23514';
  END IF;
  pending_ := next_;
 END LOOP;
 RETURN resolved_[root_key_];
END

