DECLARE
 body_ bytea;
 i integer := 1;
 n integer := cardinality(p_names);
 names_ text[] := ARRAY[]::TEXT[];
BEGIN
 IF (p_schema = '' OR p_family = '' OR p_key = '' OR n != cardinality(p_scalars) OR coalesce(array_lower(p_names, 1), 1) != 1 OR coalesce(array_lower(p_scalars, 1), 1) != 1) THEN
  RAISE EXCEPTION USING MESSAGE = 'record schema/family/key/fields invalid', ERRCODE = '23514';
 END IF;
 body_ := (ops.pdf_identity_frame(convert_to('s', 'UTF8'), convert_to(p_schema, 'UTF8')) || ops.pdf_identity_frame(convert_to('f', 'UTF8'), convert_to(p_family, 'UTF8'))) || ops.pdf_identity_frame(convert_to('k', 'UTF8'), convert_to(p_key, 'UTF8'));
 WHILE i <= n LOOP
  IF (p_names[i] IS NULL OR p_names[i] = '' OR p_names[i] = ANY (names_) OR p_scalars[i] IS NULL OR octet_length(p_scalars[i]) != 41 OR (get_byte(p_scalars[i], 0) NOT IN (97, 110, 98, 105, 102, 115, 121, 100)) OR get_byte(p_scalars[i], 1) > 127) THEN
   RAISE EXCEPTION USING MESSAGE = 'record field name/scalar invalid', ERRCODE = '23514';
  END IF;
  IF (get_byte(p_scalars[i], 0) IN (97, 110) AND substr(p_scalars[i], 2, 8) != int8send(CAST(0 AS BIGINT)) OR get_byte(p_scalars[i], 0) = 98 AND substr(p_scalars[i], 2, 8) != int8send(CAST(1 AS BIGINT)) OR get_byte(p_scalars[i], 0) = 102 AND substr(p_scalars[i], 2, 8) != int8send(CAST(8 AS BIGINT))) THEN
   RAISE EXCEPTION USING MESSAGE = 'scalar kind has an invalid payload length', ERRCODE = '23514';
  END IF;
  body_ := (body_ || ops.pdf_identity_frame(convert_to('n', 'UTF8'), convert_to(p_names[i], 'UTF8'))) || p_scalars[i];
  IF (octet_length(body_) + 8 > 65527) THEN
   RAISE EXCEPTION USING MESSAGE = 'record frame exceeds 64 KiB; lower collections into rows', ERRCODE = '23514';
  END IF;
  names_ := array_append(names_, p_names[i]);
  i := i + 1;
 END LOOP;
 IF (octet_length(body_) + 17 > 65536) THEN
  RAISE EXCEPTION USING MESSAGE = 'record frame exceeds 64 KiB', ERRCODE = '23514';
 END IF;
 RETURN ops.pdf_identity_frame(convert_to('R', 'UTF8'), int8send(CAST(n AS BIGINT)) || body_);
END

