DECLARE
 i integer := 0;
 c integer;
 c2 integer;
 width_ integer;
 j integer;
BEGIN
 WHILE i < octet_length(p_payload) LOOP
  c := get_byte(p_payload, i);
  IF (c < 128) THEN
   i := i + 1;
   CONTINUE;
  END IF;
  width_ := CASE WHEN (c BETWEEN 194 AND 223) THEN 2 WHEN (c BETWEEN 224 AND 239) THEN 3 WHEN (c BETWEEN 240 AND 244) THEN 4 END;
  IF (width_ IS NULL OR i + width_ > octet_length(p_payload)) THEN
   RETURN false;
  END IF;
  c2 := get_byte(p_payload, i + 1);
  IF (c = 224 AND c2 < 160 OR c = 237 AND c2 >= 160 OR c = 240 AND c2 < 144 OR c = 244 AND c2 >= 144) THEN
   RETURN false;
  END IF;
  j := 1;
  WHILE j < width_ LOOP
   IF (get_byte(p_payload, i + j) NOT BETWEEN 128 AND 191) THEN
    RETURN false;
   END IF;
   j := j + 1;
  END LOOP;
  i := i + width_;
 END LOOP;
 RETURN true;
END

