 item_ jsonb;
BEGIN
 content_ := ops.pdf_contract_input(p_release, 'implementation/pdf/lowering-contract.json');
 contract_ := CAST(convert_from(content_, 'UTF8') AS JSONB);
 IF ((contract_ ->> 'profile') IS DISTINCT FROM 'pdf-record-lowering-contract-v2' OR jsonb_typeof(contract_['code_identity']['complete']) IS DISTINCT FROM 'boolean' OR contract_['code_identity']['complete'] = CAST('true' AS JSONB) AND (coalesce(((contract_['code_identity']) ->> 'sha256'), '') !~ '^[0-9a-f]{64}$') OR contract_['code_identity']['complete'] = CAST('false' AS JSONB) AND contract_['code_identity']['sha256'] IS DISTINCT FROM CAST('null' AS JSONB) OR jsonb_typeof(contract_['inputs']) IS DISTINCT FROM 'array' OR jsonb_typeof(contract_['libraries']) IS DISTINCT FROM 'object' OR contract_['libraries'] = CAST('{}' AS JSONB)) THEN
  RAISE EXCEPTION USING MESSAGE = 'unsupported released PDF lowering contract', ERRCODE = '23514';
 END IF;
 IF (jsonb_array_length(contract_['inputs']) = 0) THEN
  RAISE EXCEPTION USING MESSAGE = 'released PDF lowering has no captured inputs', ERRCODE = '23514';
 END IF;
 FOR item_ IN SELECT anon_1.value 
FROM jsonb_array_elements(contract_['inputs']) AS anon_1 LOOP
  IF (left((item_ ->> 'name'), 11) != 'pdf-domain/' OR encode(sha256(ops.pdf_contract_input(p_release, substr((item_ ->> 'name'), 12))), 'hex') IS DISTINCT FROM (item_ ->> 'sha256')) THEN
   RAISE EXCEPTION USING MESSAGE = 'released PDF lowering source/codec/schema custody differs', ERRCODE = '23514';
  END IF;
 END LOOP;
 RETURN encode(sha256(content_), 'hex');
END

