 observed jsonb := value['observation'];
 binding jsonb := observed['binding'];
 decoding jsonb;
 observation jsonb;
 coverage jsonb;
BEGIN
 IF ((value ->> 'kind') IS DISTINCT FROM 'recognition_observation' OR ((observed ->> 'pass_role') NOT IN ('A', 'B', 'C')) OR (observed ? 'mapped_evidence_digest') OR coalesce(value['relations'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB) OR coalesce(value['mapping_reports'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB)) THEN
  RAISE EXCEPTION USING MESSAGE = 'recognition meaning requires the finite raw observation producer', ERRCODE = '23514';
 END IF;
 binding := jsonb_build_object('provider', observed['binding']['provider'], 'package_identity', observed['binding']['package_identity'], 'source_identity', observed['binding']['source_identity'], 'weights_digest', observed['binding']['weights_digest'], 'tokenizer_digest', observed['binding']['tokenizer_digest'], 'prompt_digest', observed['binding']['prompt_digest'], 'decoding_json', observed['binding']['decoding_json'], 'seed', observed['binding']['seed'], 'render_policy', observed['binding']['render_policy'], 'crop_policy', observed['binding']['crop_policy'], 'merge_policy', observed['binding']['merge_policy']);
 decoding := CAST(binding ->> 'decoding_json' AS JSONB);
 IF (jsonb_typeof(decoding) IS DISTINCT FROM 'object') THEN
  RAISE EXCEPTION USING MESSAGE = 'recognition decoding must be a declared object', ERRCODE = '23514';
 END IF;
 binding := jsonb_set(binding, ARRAY['decoding_json'], (decoding - 'receipt_digests') - 'service_generation');
 SELECT jsonb_object_agg(anon_1.key, anon_1.value) AS jsonb_object_agg_1 
FROM jsonb_each(observed) AS anon_1 
WHERE anon_1.key IN ('image', 'pass_role', 'outcome', 'raw_response_digest', 'finish_reason') INTO observation;
 observation := observation || jsonb_build_object('binding', binding);
 IF (EXISTS (SELECT 1 
FROM jsonb_array_elements(value['coverage']) WITH ORDINALITY AS anon_1(value, ordinal) 
WHERE anon_1.value['supports'] IS DISTINCT FROM CAST('[]' AS JSONB))) THEN
  RAISE EXCEPTION USING MESSAGE = 'raw recognition coverage cannot inherit a source assessment', ERRCODE = '23514';
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('coverage_id', anon_1.value['coverage_id'], 'scope', anon_1.value['scope'], 'family', anon_1.value['family'], 'discovery_policy', anon_1.value['discovery_policy'], 'outcome', anon_1.value['outcome']) ORDER BY anon_1.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(value['coverage']) WITH ORDINALITY AS anon_1(value, ordinal) INTO coverage;
 RETURN jsonb_build_object('version', 'pdf-observation-meaning-1', 'source_digest', value['artifact_digest'], 'recipe_digest', value['recipe_digest'], 'observation', observation, 'occurrences', value['occurrences'], 'coverage', coverage, 'mapping_outcome', value['health']['mapping_outcome'], 'source_fidelity', value['health']['source_fidelity']);
END

