DECLARE
 job ops.task%ROWTYPE;
 request ops.data_request%ROWTYPE;
 definition sem.data_operation_definition%ROWTYPE;
 product ops.pdf_product%ROWTYPE;
 context record;
 profile jsonb;
 selected jsonb;
 capture jsonb;
 page jsonb;
 request_ref jsonb;
 report jsonb;
 result jsonb;
 request_row jsonb;
 payload jsonb;
 origin jsonb;
 requested jsonb;
 available jsonb;
 page_groups jsonb := CAST('[]' AS JSONB);
 page_requests jsonb;
 pages jsonb := CAST('[]' AS JSONB);
 report_content bytea;
 body_content bytea;
 raw_payload bytea;
 ordinal bigint;
 page_position bigint;
 previous_page bigint;
 previous_outcome text;
 recovery_count integer := 0;
BEGIN
 PERFORM ops.ddo_fields(p_receipt, ARRAY['version', 'request_id', 'generation', 'task_id', 'attempt', 'holder', 'runtime_id', 'source_digest', 'recipe_digest', 'pages']);
 SELECT ops.task.* 
FROM ops.task 
WHERE ops.task.id = p_task INTO STRICT job;
 SELECT * 
FROM ops.pdf_task_context(p_task) INTO STRICT context;
 request := p_request;
 IF (request.generation IS DISTINCT FROM context.generation OR request.release_id IS DISTINCT FROM context.release_id OR request.id IS DISTINCT FROM context.request_id OR request.project_id IS DISTINCT FROM context.project_id OR request.original_source IS DISTINCT FROM (SELECT kb.document.key 
FROM kb.document 
WHERE kb.document.id = context.document_id)) THEN
  RAISE EXCEPTION USING MESSAGE = 'observation projection changes its actual task request basis', ERRCODE = '23514';
 END IF;
 PERFORM ops.ddo_authorize_request(request);
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = context.release_id AND sem.data_operation_definition.operation_id = request.operation_id INTO STRICT definition;
 IF (NOT coalesce(definition.command_class = 'pdf', false) OR request.recipe IS DISTINCT FROM definition.recipe OR ((definition.support_contract['effects'][0]) ->> 'name') IS DISTINCT FROM 'retain_pdf_observations' OR (p_receipt ->> 'version') IS DISTINCT FROM 'pdf-observation-execution-1' OR (p_receipt ->> 'request_id') IS DISTINCT FROM context.request_id OR CAST((p_receipt ->> 'generation') AS BIGINT) IS DISTINCT FROM context.generation OR CAST((p_receipt ->> 'task_id') AS BIGINT) IS DISTINCT FROM p_task OR CAST((p_receipt ->> 'attempt') AS BIGINT) IS DISTINCT FROM p_attempt OR p_attempt IS NULL OR p_attempt < 1 OR nullif(p_holder, '') IS NULL OR (p_receipt ->> 'holder') IS DISTINCT FROM p_holder OR (p_receipt ->> 'source_digest') IS DISTINCT FROM context.source_digest OR NOT (EXISTS (SELECT 1 
FROM sem.runtime_binding 
WHERE sem.runtime_binding.release_id = context.release_id AND sem.runtime_binding.runtime_id = (p_receipt ->> 'runtime_id')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'observation receipt differs from actual native recognition owner', ERRCODE = '23514';
 END IF;
 profile := ops.pdf_recognition_profile(context.release_id, definition);
 IF ((p_receipt ->> 'recipe_digest') IS DISTINCT FROM (profile ->> 'base_recipe_digest')) THEN
  RAISE EXCEPTION USING MESSAGE = 'observation receipt changes configured recognition recipe', ERRCODE = '23514';
 END IF;
 SELECT bindings.value 
FROM jsonb_array_elements(request.binding['inputs']) AS bindings(value) 
WHERE (bindings.value ->> 'role') = 'capture' INTO STRICT selected;
 capture := (ops.ddo_pdf_capture_source_for_request(request, request.project_id, selected ->> 'product_id', ops.ddo_single_input_support_episode(selected)))['publication'];
 requested := (data.ddo_json(data.ddo_field(request.binding['parameters'], 'parameters')))['pages'];
 IF (requested IS NULL OR jsonb_typeof(requested) != 'array') THEN
  RAISE EXCEPTION USING MESSAGE = 'observation request lacks its exact physical page selection', ERRCODE = '23514';
 END IF;
 SELECT coalesce(jsonb_agg(CAST(kb.pdf_record_native.scalars_json ->> 'page_no' AS BIGINT) ORDER BY CAST(kb.pdf_record_native.scalars_json ->> 'page_no' AS BIGINT)), CAST('[]' AS JSONB)) AS coalesce_1 
FROM ops.pdf_record_document JOIN kb.pdf_record_membership ON kb.pdf_record_membership.product_id = ops.pdf_record_document.product_id AND kb.pdf_record_membership.revision_id = ops.pdf_record_document.revision_id AND kb.pdf_record_membership.parent_id = ops.pdf_record_document.root_id AND kb.pdf_record_membership.field_name = 'pages' JOIN kb.pdf_record_native ON kb.pdf_record_native.product_id = kb.pdf_record_membership.product_id AND kb.pdf_record_native.revision_id = kb.pdf_record_membership.revision_id AND kb.pdf_record_native.record_id = kb.pdf_record_membership.record_id 
WHERE ops.pdf_record_document.product_id = (capture ->> 'build_id') AND ops.pdf_record_document.revision_id = (capture ->> 'build_id') INTO available;
 IF (requested = CAST('[]' AS JSONB)) THEN
  requested := available;
 ELSE
  IF (EXISTS (SELECT 1 
FROM jsonb_array_elements(requested) AS numbers(value) 
WHERE NOT (available @> jsonb_build_array(numbers.value)))) THEN
   RAISE EXCEPTION USING MESSAGE = 'recognition page is outside the actual selected native inventory', ERRCODE = '23514';
  END IF;
 END IF;
 IF (jsonb_array_length(p_receipt['pages']) = 0) THEN
  RAISE EXCEPTION USING MESSAGE = 'observation receipt has no inspected page reports', ERRCODE = '23514';
 END IF;
 FOR page, page_position IN SELECT page_rows.value, page_rows.n 
FROM jsonb_array_elements(p_receipt['pages']) WITH ORDINALITY AS page_rows(value, n) LOOP
  PERFORM ops.ddo_fields(page, ARRAY['page_no', 'recipe_digest', 'report_digest', 'adapter_reused', 'observations']);
  IF (jsonb_typeof(page['adapter_reused']) IS DISTINCT FROM 'boolean' OR NOT ((requested @> jsonb_build_array(CAST((page ->> 'page_no') AS BIGINT)))) OR NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(profile['recipes']) AS recipes(value) 
WHERE (recipes.value ->> 'digest') = (page ->> 'recipe_digest')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'observation page/recipe differs from exact requested source', ERRCODE = '23514';
  END IF;
  IF (previous_page IS DISTINCT FROM CAST((page ->> 'page_no') AS BIGINT)) THEN
   IF ((page_groups @> jsonb_build_array(CAST((page ->> 'page_no') AS BIGINT))) OR (page ->> 'recipe_digest') IS DISTINCT FROM (profile ->> 'base_recipe_digest')) THEN
    RAISE EXCEPTION USING MESSAGE = 'observation page ordering/base recipe differs', ERRCODE = '23514';
   END IF;
   page_groups := page_groups || jsonb_build_array(CAST((page ->> 'page_no') AS BIGINT));
   recovery_count := 0;
  ELSE
   recovery_count := recovery_count + 1;
   IF (recovery_count != 1 OR profile['recovery_policy'] = CAST('null' AS JSONB) OR previous_outcome = 'succeeded' OR (page ->> 'recipe_digest') = (profile ->> 'base_recipe_digest')) THEN
    RAISE EXCEPTION USING MESSAGE = 'observation recovery differs from its finite admitted policy', ERRCODE = '23514';
   END IF;
  END IF;
  SELECT kb.source_artifact.content 
FROM kb.source_artifact 
WHERE kb.source_artifact.artifact_digest = (page ->> 'report_digest') AND encode(sha256(kb.source_artifact.content), 'hex') = kb.source_artifact.artifact_digest INTO STRICT report_content;
  report := CAST(convert_from(report_content, 'UTF8') AS JSONB);
  IF (NOT coalesce(public.json_matches_schema(CAST('{"additionalProperties": false, "description": "Finite inspected manifest over retained actual adapter report/request bytes.", "properties": {"version": {"const": "pdf-recognition-page-report-1", "title": "Version", "type": "string"}, "page_no": {"minimum": 1, "title": "Page No", "type": "integer"}, "recipe_digest": {"maxLength": 64, "minLength": 64, "pattern": "^[0-9a-f]{64}$", "title": "Recipe Digest", "type": "string"}, "result_digest": {"maxLength": 64, "minLength": 64, "pattern": "^[0-9a-f]{64}$", "title": "Result Digest", "type": "string"}, "requests": {"items": {"$ref": "#/definitions/PdfObservationRequestReport"}, "minItems": 1, "title": "Requests", "type": "array"}}, "required": ["version", "page_no", "recipe_digest", "result_digest", "requests"], "title": "PdfObservationPageReport", "type": "object", "definitions": {"PdfObservationRequestReport": {"additionalProperties": false, "properties": {"ordinal": {"minimum": 0, "title": "Ordinal", "type": "integer"}, "request_digest": {"maxLength": 64, "minLength": 64, "pattern": "^[0-9a-f]{64}$", "title": "Request Digest", "type": "string"}}, "required": ["ordinal", "request_digest"], "title": "PdfObservationRequestReport", "type": "object"}}}' AS JSON), CAST(report AS JSON)), false)) THEN
   RAISE EXCEPTION USING MESSAGE = 'observation report violates its finite manifest contract', ERRCODE = '23514';
  END IF;
  IF ((report ->> 'page_no') IS DISTINCT FROM (page ->> 'page_no') OR (report ->> 'recipe_digest') IS DISTINCT FROM (page ->> 'recipe_digest') OR jsonb_array_length(report['requests']) IS DISTINCT FROM jsonb_array_length(page['observations'])) THEN
   RAISE EXCEPTION USING MESSAGE = 'observation report differs from exact retained request inventory', ERRCODE = '23514';
  END IF;
  SELECT kb.source_artifact.content 
FROM kb.source_artifact 
WHERE kb.source_artifact.artifact_digest = (report ->> 'result_digest') AND encode(sha256(kb.source_artifact.content), 'hex') = kb.source_artifact.artifact_digest INTO STRICT body_content;
  result := CAST(convert_from(body_content, 'UTF8') AS JSONB);
  IF ((result ->> 'outcome') IS NULL OR ((result ->> 'outcome') NOT IN ('succeeded', 'partial', 'failed', 'unknown', 'unsupported'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'observation report lacks its actual reported page outcome', ERRCODE = '23514';
  END IF;
  page_requests := CAST('[]' AS JSONB);
  FOR request_ref, ordinal IN SELECT refs.value, refs.n - 1 AS anon_1 
FROM jsonb_array_elements(page['observations']) WITH ORDINALITY AS refs(value, n) LOOP
   PERFORM ops.ddo_fields(request_ref, ARRAY['ordinal', 'task_id', 'product_key', 'content_digest', 'publication_context']);
   SELECT ops.pdf_product.* 
FROM ops.pdf_product 
WHERE ops.pdf_product.task_id = CAST((request_ref ->> 'task_id') AS BIGINT) AND ops.pdf_product.product_key = (request_ref ->> 'product_key') AND ops.pdf_product.content_digest = (request_ref ->> 'content_digest') INTO STRICT product;
   origin := product.publication_context;
   IF (product.kind != 'recognition_observation' OR product.task_id != p_task OR product.artifact_digest IS DISTINCT FROM context.source_digest OR origin IS NULL OR origin IS DISTINCT FROM request_ref['publication_context'] OR (origin ->> 'version') IS DISTINCT FROM 'pdf-observation-publication-1' OR (origin ->> 'request_id') IS DISTINCT FROM context.request_id OR CAST((origin ->> 'generation') AS BIGINT) IS DISTINCT FROM context.generation OR CAST((origin ->> 'task_id') AS BIGINT) IS DISTINCT FROM p_task OR (origin ->> 'release_id') IS DISTINCT FROM context.release_id OR (origin ->> 'source_digest') IS DISTINCT FROM context.source_digest OR CAST((origin ->> 'attempt') AS BIGINT) NOT BETWEEN 1 AND p_attempt OR CAST((origin ->> 'attempt') AS BIGINT) = p_attempt AND ((origin ->> 'holder') IS DISTINCT FROM p_holder OR (origin ->> 'runtime_id') IS DISTINCT FROM (p_receipt ->> 'runtime_id')) OR CAST((request_ref ->> 'ordinal') AS BIGINT) IS DISTINCT FROM ordinal OR CAST(((report['requests'][CAST(ordinal AS INTEGER)]) ->> 'ordinal') AS BIGINT) IS DISTINCT FROM ordinal OR NOT (EXISTS (SELECT 1 
FROM sem.runtime_binding 
WHERE sem.runtime_binding.release_id = (origin ->> 'release_id') AND sem.runtime_binding.runtime_id = (origin ->> 'runtime_id'))) OR (EXISTS (SELECT 1 
FROM ops.data_revocation 
WHERE ops.data_revocation.scope = ops.ddo_scope(request.project_id, request.original_source) AND ops.data_revocation.selector_kind = 'runtime' AND ops.data_revocation.selector = (origin ->> 'runtime_id')))) THEN
    RAISE EXCEPTION USING MESSAGE = 'observation publication/adoption loses original native attribution', ERRCODE = '23514';
   END IF;
   SELECT ops.pdf_product_body.payload 
FROM ops.pdf_product_body 
WHERE ops.pdf_product_body.task_id = product.task_id AND ops.pdf_product_body.product_key = product.product_key INTO STRICT raw_payload;
   payload := CAST(convert_from(raw_payload, 'UTF8') AS JSONB);
   SELECT kb.source_artifact.content 
FROM kb.source_artifact 
WHERE kb.source_artifact.artifact_digest = ((report['requests'][CAST(ordinal AS INTEGER)]) ->> 'request_digest') AND encode(sha256(kb.source_artifact.content), 'hex') = kb.source_artifact.artifact_digest INTO STRICT body_content;
   request_row := CAST(convert_from(body_content, 'UTF8') AS JSONB);
   IF (encode(sha256(raw_payload), 'hex') IS DISTINCT FROM product.content_digest OR (payload ->> 'recipe_digest') IS DISTINCT FROM (page ->> 'recipe_digest') OR ((payload['observation']['image']) ->> 'page_no') IS DISTINCT FROM (page ->> 'page_no') OR (request_row ->> 'ordinal') IS DISTINCT FROM (request_ref ->> 'ordinal') OR (request_row ->> 'submitted_digest') IS DISTINCT FROM ((payload['observation']['image']) ->> 'artifact_digest') OR (request_row ->> 'outcome') IS DISTINCT FROM ((payload['observation']) ->> 'outcome') OR CAST(CASE (request_row ->> 'stage') WHEN 'fullpage' THEN 'A' WHEN 'detection' THEN 'B' WHEN 'crop' THEN 'C' END AS TEXT) IS DISTINCT FROM ((payload['observation']) ->> 'pass_role') OR ((request_row ? 'raw_response')) IS DISTINCT FROM ((payload['observation'] ? 'raw_response_digest')) OR (request_row ? 'raw_response') AND (request_row ->> 'raw_digest') IS DISTINCT FROM ((payload['observation']) ->> 'raw_response_digest') OR (EXISTS (SELECT 1 
FROM unnest(ARRAY[(page ->> 'report_digest'), (report ->> 'result_digest'), ((report['requests'][CAST(ordinal AS INTEGER)]) ->> 'request_digest')]) AS required_artifacts(value) 
WHERE NOT (EXISTS (SELECT 1 
FROM ops.pdf_product_artifact 
WHERE ops.pdf_product_artifact.task_id = product.task_id AND ops.pdf_product_artifact.product_key = product.product_key AND ops.pdf_product_artifact.artifact_digest = required_artifacts.value))))) THEN
    RAISE EXCEPTION USING MESSAGE = 'observation report/request bytes differ from native retained evidence', ERRCODE = '23514';
   END IF;
   page_requests := page_requests || jsonb_build_array(jsonb_build_object('ordinal', ordinal, 'meaning_digest', ops.ddo_digest(data.ddo_json_meaning(ops.pdf_observation_meaning(raw_payload))), 'pass_role', payload['observation']['pass_role'], 'outcome', payload['observation']['outcome']));
  END LOOP;
  IF ((result ->> 'outcome') = 'succeeded' AND (jsonb_array_length(page_requests) < 2 OR ((page_requests[0]) ->> 'pass_role') != 'A' OR ((page_requests[1]) ->> 'pass_role') != 'B' OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(page_requests) AS readings(value) 
WHERE (readings.value ->> 'outcome') != 'succeeded')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'successful page report differs from actual retained pass outcomes', ERRCODE = '23514';
  END IF;
  pages := pages || jsonb_build_array(jsonb_build_object('page_no', page['page_no'], 'recipe_digest', page['recipe_digest'], 'outcome', result['outcome'], 'observations', page_requests));
  previous_page := CAST(page ->> 'page_no' AS BIGINT);
  previous_outcome := result ->> 'outcome';
 END LOOP;
 IF (page_groups IS DISTINCT FROM requested) THEN
  RAISE EXCEPTION USING MESSAGE = 'observation reports do not cover the exact requested page inventory', ERRCODE = '23514';
 END IF;
 RETURN jsonb_build_object('document', request.original_source, 'source_digest', context.source_digest, 'recipe_digest', p_receipt['recipe_digest'], 'pages', pages);
END

