 FOR row_ IN SELECT ops.pdf_artifact_stream.product_id, ops.pdf_artifact_stream.revision_id, ops.pdf_artifact_stream.stream_id, ops.pdf_artifact_stream.byte_length, ops.pdf_artifact_stream.serialization_sha256, ops.pdf_artifact_stream.byte_root, ops.pdf_artifact_stream.encoding_profile 
