WHERE ops.pdf_artifact_stream.product_id = p_build AND ops.pdf_artifact_stream.revision_id = p_build ORDER BY ops.pdf_artifact_stream.stream_id COLLATE "C" LOOP
  frame_ := ops.pdf_identity_record_frame(p_schema, 'producer-stream', row_.stream_id, ARRAY['byte_length', 'byte_root', 'encoding_profile', 'serialization_sha256'], CAST(ARRAY[ops.pdf_identity_scalar('i', convert_to(CAST(row_.byte_length AS TEXT), 'UTF8')), ops.pdf_identity_scalar('s', convert_to(row_.byte_root, 'UTF8')), ops.pdf_identity_scalar('s', convert_to(row_.encoding_profile, 'UTF8')), CASE WHEN (row_.serialization_sha256 IS NULL) THEN ops.pdf_identity_scalar('n', CAST('' AS BYTEA)) ELSE ops.pdf_identity_scalar('s', convert_to(row_.serialization_sha256, 'UTF8')) END] AS BYTEA[]));
