 expected_ bytea;
BEGIN
 BEGIN
  IF (p_value IS NULL OR p_expected IS NULL) THEN
   RETURN false;
  END IF;
  IF (jsonb_typeof(p_expected) = 'object' AND (p_expected ? 'native_float64')) THEN
   IF (jsonb_typeof(p_value) != 'number') THEN
    RETURN false;
   END IF;
   actual_ := float8send(CAST(p_value #>> ARRAY[]::TEXT[] AS DOUBLE PRECISION));
   expected_ := decode(p_expected ->> 'native_float64', 'hex');
   RETURN actual_ = expected_ OR expected_ IN (decode('0000000000000000', 'hex'), decode('8000000000000000', 'hex')) AND CAST(p_value #>> ARRAY[]::TEXT[] AS NUMERIC) = 0;
  END IF;
  RETURN jsonb_typeof(p_value) = jsonb_typeof(p_expected) AND p_value = p_expected;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RETURN false;
 END;
END

