 payload_ bytea;
BEGIN
 BEGIN
  IF (p_value IS NULL) THEN
   RETURN false;
  END IF;
  SELECT ops.pdf_artifact_stream.* 
FROM ops.pdf_artifact_stream 
WHERE ops.pdf_artifact_stream.product_id = p_build AND ops.pdf_artifact_stream.revision_id = p_build AND ops.pdf_artifact_stream.stream_id = p_stream INTO STRICT stream_;
  IF (stream_.encoding_profile = 'pdf-record-native-json-v1') THEN
   RETURN ops.pdf_projection_stream_value(p_build, p_stream) = p_value;
  END IF;
  IF (stream_.encoding_profile = 'pdf-record-scalar-v1:s' AND jsonb_typeof(p_value) = 'string') THEN
   payload_ := convert_to(p_value #>> ARRAY[]::TEXT[], 'UTF8');
  ELSE
   IF (stream_.encoding_profile = 'pdf-record-scalar-v1:i' AND jsonb_typeof(p_value) = 'number') THEN
    IF ((p_value #>> ARRAY[]::TEXT[]) !~ '^(0|-?[1-9][0-9]*)$') THEN
     RETURN false;
    END IF;
    payload_ := convert_to(p_value #>> ARRAY[]::TEXT[], 'UTF8');
   ELSE
    IF (stream_.encoding_profile = 'pdf-record-scalar-v1:f' AND jsonb_typeof(p_value) = 'number') THEN
     payload_ := float8send(CAST(p_value #>> ARRAY[]::TEXT[] AS DOUBLE PRECISION));
     IF (CAST(p_value #>> ARRAY[]::TEXT[] AS NUMERIC) = 0 AND stream_.byte_length = 8 AND stream_.byte_root IN (encode(ops.pdf_identity_byte_root(decode('0000000000000000', 'hex')), 'hex'), encode(ops.pdf_identity_byte_root(decode('8000000000000000', 'hex')), 'hex'))) THEN
      RETURN true;
     END IF;
    ELSE
     IF (stream_.encoding_profile = 'pdf-record-scalar-v1:n' AND p_value = CAST('null' AS JSONB)) THEN
      payload_ := decode('', 'hex');
     ELSE
      IF (stream_.encoding_profile = 'pdf-record-scalar-v1:b' AND jsonb_typeof(p_value) = 'boolean') THEN
       payload_ := CASE WHEN (p_value = CAST('true' AS JSONB)) THEN decode('01', 'hex') ELSE decode('00', 'hex') END;
      ELSE
       RETURN false;
      END IF;
     END IF;
    END IF;
   END IF;
  END IF;
  RETURN octet_length(payload_) = stream_.byte_length AND encode(ops.pdf_identity_byte_root(payload_), 'hex') = stream_.byte_root;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RETURN false;
 END;
END

