CREATE OR REPLACE FUNCTION ops.pdf_projection_stream_value(p_build text, p_stream text) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 stream_ ops.pdf_artifact_stream%ROWTYPE;
 actual_length_ bigint;
 payload_ bytea;
BEGIN
 SELECT ops.pdf_artifact_stream.* 
FROM ops.pdf_artifact_stream 
WHERE ops.pdf_artifact_stream.product_id = p_build AND ops.pdf_artifact_stream.revision_id = p_build AND ops.pdf_artifact_stream.stream_id = p_stream INTO STRICT stream_;
 SELECT coalesce(sum(octet_length(parts.body)), 0) AS coalesce_1 
FROM ops.pdf_artifact_parts(p_build, p_build, false, ARRAY[p_stream]) AS parts 
WHERE parts.product_id = p_build AND parts.revision_id = p_build AND parts.stream_id = p_stream INTO actual_length_;
 IF (actual_length_ > 8388608 OR actual_length_ != stream_.byte_length) THEN
  RAISE EXCEPTION USING MESSAGE = 'native access scalar exceeds bounded projection or stream length', ERRCODE = '23514';
 END IF;
 SELECT coalesce(string_agg(parts.body, decode('', 'hex') ORDER BY parts.ordinal), decode('', 'hex')) AS coalesce_1 
FROM ops.pdf_artifact_parts(p_build, p_build, false, ARRAY[p_stream]) AS parts 
WHERE parts.product_id = p_build AND parts.revision_id = p_build AND parts.stream_id = p_stream INTO payload_;
 IF (stream_.encoding_profile = 'pdf-record-native-json-v1') THEN
  RETURN CAST(convert_from(payload_, 'UTF8') AS JSONB);
 END IF;
 IF (stream_.encoding_profile = 'pdf-record-scalar-v1:s') THEN
  RETURN to_jsonb(convert_from(payload_, 'UTF8'));
 END IF;
 RAISE EXCEPTION USING MESSAGE = 'native access requires a JSON/string stream profile', ERRCODE = '23514';
END$$

