DECLARE
 publication ops.pdf_published_revision%ROWTYPE;
 build ops.pdf_stage_build%ROWTYPE;
 context record;
 health jsonb;
BEGIN
 SELECT ops.pdf_published_revision.* 
FROM ops.pdf_published_revision 
WHERE ops.pdf_published_revision.build_id = ((p_receipt['publication']) ->> 'build_id') INTO STRICT publication;
 SELECT ops.pdf_stage_build.* 
FROM ops.pdf_stage_build 
WHERE ops.pdf_stage_build.build_id = publication.build_id INTO STRICT build;
 SELECT anon_1.document_id, anon_1.release_id, anon_1.source_digest 
FROM ops.pdf_task_context(p_task) AS anon_1 INTO STRICT context;
 IF (p_attempt IS NULL OR p_attempt < 1 OR nullif(p_holder, '') IS NULL OR to_jsonb(publication) IS DISTINCT FROM p_receipt['publication'] OR publication.task_id IS DISTINCT FROM p_task OR build.task_id IS DISTINCT FROM p_task OR build.attempt IS DISTINCT FROM CAST((p_receipt ->> 'publisher_attempt') AS BIGINT) OR build.holder IS DISTINCT FROM (p_receipt ->> 'publisher_holder') OR build.attempt > p_attempt OR build.attempt = p_attempt AND build.holder IS DISTINCT FROM p_holder OR p_receipt['contributors'] IS DISTINCT FROM ops.pdf_spool_contributors(publication.build_id) OR NOT (EXISTS (SELECT ops.pdf_build_validation.build_id 
FROM ops.pdf_build_validation 
WHERE ops.pdf_build_validation.build_id = publication.build_id AND p_receipt['certification'] = jsonb_build_object('basis', ops.pdf_build_validation.certification_basis, 'lowering_identity', ops.pdf_build_validation.lowering_identity, 'attested_logical_digest', ops.pdf_build_validation.attested_logical_digest, 'native_document_digest', ops.pdf_build_validation.native_document_digest, 'oracle_receipt_id', ops.pdf_build_validation.oracle_receipt_id))) OR build.state != 'published' OR (build.release_id, build.source_digest, build.schema_digest, build.recipe_digest) IS DISTINCT FROM (publication.release_id, publication.source_digest, publication.schema_digest, publication.recipe_digest) OR (publication.release_id, publication.source_digest) IS DISTINCT FROM (context.release_id, context.source_digest) OR NOT (EXISTS (SELECT ops.pdf_frozen_build.build_id 
FROM ops.pdf_frozen_build JOIN ops.pdf_build_validation ON ops.pdf_build_validation.build_id = ops.pdf_frozen_build.build_id AND ops.pdf_build_validation.frozen_digest = ops.pdf_frozen_build.frozen_digest 
WHERE ops.pdf_frozen_build.build_id = publication.build_id AND ops.pdf_frozen_build.kind = publication.kind AND ops.pdf_frozen_build.frozen_digest = publication.frozen_digest AND ops.pdf_build_validation.native_callbacks AND ops.pdf_build_validation.logical_digest = publication.logical_digest AND ops.pdf_build_validation.native_contract_digest = ops.pdf_validation_contract(publication.release_id)))) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF execution receipt differs from actual sealed publisher', ERRCODE = '23514';
 END IF;
 SELECT kb.pdf_record_companion.body 
FROM kb.pdf_record_companion 
WHERE kb.pdf_record_companion.product_id = publication.build_id AND kb.pdf_record_companion.revision_id = publication.build_id AND kb.pdf_record_companion.family = 'health' AND (kb.pdf_record_companion.body ? 'conversion') INTO STRICT health;
 RETURN jsonb_build_object('document', (SELECT kb.document.key 
FROM kb.document 
WHERE kb.document.id = context.document_id), 'source_digest', publication.source_digest, 'schema_digest', publication.schema_digest, 'recipe_digest', publication.recipe_digest, 'logical_digest', publication.logical_digest, 'kind', publication.kind, 'health', jsonb_build_object('conversion', health['conversion'], 'display_coverage', health['display_coverage'], 'inline_coverage', health['inline_coverage'], 'cell_coverage', health['cell_coverage']));
END

