DECLARE
 content ops.pdf_shared_stream%ROWTYPE;
 owner ops.pdf_stage_build%ROWTYPE;
 job ops.task%ROWTYPE;
 lock_request text;
 lock_id bigint;
 lock_build text;
BEGIN
 SELECT ops.pdf_shared_stream.project_id, ops.pdf_shared_stream.encoding_profile, ops.pdf_shared_stream.byte_length, ops.pdf_shared_stream.byte_root, ops.pdf_shared_stream.owner_build_id, ops.pdf_shared_stream.owner_attempt, ops.pdf_shared_stream.owner_holder 
FROM ops.pdf_shared_stream 
WHERE ops.pdf_shared_stream.project_id = p_project AND ops.pdf_shared_stream.encoding_profile = p_profile AND ops.pdf_shared_stream.byte_length = p_length AND ops.pdf_shared_stream.byte_root = p_root FOR UPDATE INTO STRICT content;
 SELECT ops.pdf_stage_build.build_id, ops.pdf_stage_build.task_id, ops.pdf_stage_build.release_id, ops.pdf_stage_build.source_digest, ops.pdf_stage_build.recipe_digest, ops.pdf_stage_build.schema_digest, ops.pdf_stage_build.replay_key, ops.pdf_stage_build.attempt, ops.pdf_stage_build.holder, ops.pdf_stage_build.state 
FROM ops.pdf_stage_build 
WHERE ops.pdf_stage_build.build_id = content.owner_build_id INTO STRICT owner;
 SELECT ops.task.id, ops.task.release_id, ops.task.data_request_id, ops.task.data_generation, ops.task.invocation_key, ops.task.trigger, ops.task.status, ops.task.attempt, ops.task.claimed_by, ops.task.lease_until, ops.task.result_digest, ops.task.error, ops.task.cost, ops.task.reason, ops.task.priority, ops.task.created_at, ops.task.started_at, ops.task.finished_at 
FROM ops.task 
WHERE ops.task.id = owner.task_id INTO STRICT job;
 SELECT ops.data_request.id 
FROM ops.data_request 
WHERE ops.data_request.id = job.data_request_id FOR UPDATE NOWAIT INTO lock_request;
 SELECT ops.task.id 
FROM ops.task 
WHERE ops.task.id = job.id FOR UPDATE NOWAIT INTO lock_id;
 SELECT ops.pdf_stage_build.build_id 
FROM ops.pdf_stage_build 
WHERE ops.pdf_stage_build.build_id = owner.build_id FOR UPDATE NOWAIT INTO lock_build;
 IF (NOT ops.pdf_pending_stream_owner_dead(content) OR (EXISTS (SELECT 1 
FROM ops.pdf_shared_stream_verification 
WHERE ops.pdf_shared_stream_verification.project_id = p_project AND ops.pdf_shared_stream_verification.encoding_profile = p_profile AND ops.pdf_shared_stream_verification.byte_length = p_length AND ops.pdf_shared_stream_verification.byte_root = p_root))) THEN
  RAISE EXCEPTION USING MESSAGE = 'shared stream is verified or still has a live append owner', ERRCODE = '55P03';
 END IF;
 IF (EXISTS (SELECT 1 
FROM ops.pdf_stage_artifact_stream JOIN ops.pdf_stage_build AS dependent ON dependent.build_id = ops.pdf_stage_artifact_stream.product_id JOIN ops.task AS dependent_task ON dependent_task.id = dependent.task_id 
WHERE ops.pdf_stage_artifact_stream.encoding_profile = p_profile AND ops.pdf_stage_artifact_stream.byte_length = p_length AND ops.pdf_stage_artifact_stream.byte_root = p_root AND ops.pdf_stream_project(dependent.build_id) = p_project AND dependent.build_id != owner.build_id AND dependent.state = 'open' AND dependent_task.status = 'running' AND dependent_task.lease_until > clock_timestamp() AND dependent_task.attempt = dependent.attempt AND dependent_task.claimed_by = dependent.holder)) THEN
  RAISE EXCEPTION USING MESSAGE = 'pending shared stream still has a live dependent build', ERRCODE = '55P03';
 END IF;
 DELETE FROM ops.pdf_shared_stream_part WHERE ops.pdf_shared_stream_part.project_id = p_project AND ops.pdf_shared_stream_part.encoding_profile = p_profile AND ops.pdf_shared_stream_part.stream_length = p_length AND ops.pdf_shared_stream_part.byte_root = p_root;
 DELETE FROM ops.pdf_shared_stream WHERE ops.pdf_shared_stream.project_id = p_project AND ops.pdf_shared_stream.encoding_profile = p_profile AND ops.pdf_shared_stream.byte_length = p_length AND ops.pdf_shared_stream.byte_root = p_root;
END

