 profile jsonb;
BEGIN
 IF (p_definition.release_id IS DISTINCT FROM p_release) THEN
  RAISE EXCEPTION USING MESSAGE = 'recognition policy belongs to another release', ERRCODE = '23514';
 END IF;
 SELECT anon_1.value 
FROM jsonb_array_elements(p_definition.support_contract['assets']) AS anon_1 
WHERE (anon_1.value ->> 'reference') = 'frozen-native-recognition-policy' AND (anon_1.value ->> 'contract') = 'pdf-recognition/policy-v1' AND (anon_1.value ->> 'role') = 'recognition-models-and-recovery-policy' INTO STRICT asset;
 SELECT CAST(convert_from(sem.input.content, 'UTF8') AS JSONB) AS convert_from_1 
FROM sem.input 
WHERE sem.input.release_id = p_release AND sem.input.input_kind = 'dependency' AND sem.input.input_name = ('data-operations/contracts/' || (asset ->> 'contract')) AND sem.input.content_digest = (asset ->> 'content_digest') AND encode(sha256(sem.input.content), 'hex') = sem.input.content_digest INTO STRICT profile;
 PERFORM ops.ddo_fields(profile, ARRAY['version', 'base_recipe_digest', 'recipes', 'recovery_policy', 'source_recovery']);
 IF ((profile ->> 'version') IS DISTINCT FROM 'pdf-recognition-profile-1') THEN
  RAISE EXCEPTION USING MESSAGE = 'unsupported recognition policy', ERRCODE = '23514';
 END IF;
 RETURN profile;
END

