DECLARE
 header_ ops.pdf_record_document%ROWTYPE;
 row_ record;
 node_ kb.pdf_record_native%ROWTYPE;
 member_ kb.pdf_record_membership%ROWTYPE;
 companion_ kb.pdf_record_companion%ROWTYPE;
 endpoint_ kb.pdf_record_endpoint%ROWTYPE;
 field_ text;
 descriptor_ jsonb;
 body_ jsonb;
 names_ text[];
 values_ bytea[];
 frame_ bytea;
 state_ bytea := ops.pdf_identity_fold_start('records');
 count_ bigint := 0;
 length_ bigint := 0;
BEGIN
 SELECT ops.pdf_record_document.* 
FROM ops.pdf_record_document 
WHERE ops.pdf_record_document.product_id = p_product AND ops.pdf_record_document.revision_id = p_revision INTO STRICT header_;
 PERFORM ops.pdf_contract_input(header_.release_id, 'implementation/pdf/staging-model.yaml');
 frame_ := ops.pdf_identity_record_frame(header_.native_schema_digest, '@context', '@context', CAST(ARRAY['protocol', 'record_profile', 'source'] AS TEXT[]), CAST(ARRAY[ops.pdf_identity_scalar('s', convert_to('pdf-record-sha256-fold-v1', 'UTF8')), ops.pdf_identity_scalar('s', convert_to('pdf-publication-records-v3', 'UTF8')), ops.pdf_identity_scalar('s', convert_to(header_.source_digest, 'UTF8'))] AS BYTEA[]));
 IF (p_fold) THEN
  state_ := ops.pdf_identity_fold_step(state_, count_, frame_);
 ELSE
  RETURN NEXT frame_;
 END IF;
 count_ := count_ + 1;
 length_ := length_ + octet_length(frame_);
 FOR row_ IN SELECT ordered.family, ordered.key, ordered.companion, ordered.endpoint, ordered.member, ordered.node, ordered.member_key, ordered.has_relation_fields 
FROM (SELECT 'companion/' || kb.pdf_record_companion.family AS family, kb.pdf_record_companion.local_id AS key, pdf_record_companion AS companion, CAST(NULL AS kb.pdf_record_endpoint) AS endpoint, CAST(NULL AS kb.pdf_record_membership) AS member, CAST(NULL AS kb.pdf_record_native) AS node, CAST(NULL AS BYTEA) AS member_key, field_rows.local_id IS NOT NULL AS has_relation_fields 
FROM kb.pdf_record_companion LEFT OUTER JOIN (SELECT DISTINCT kb.pdf_record_companion_field.local_id AS local_id 
FROM kb.pdf_record_companion_field 
WHERE kb.pdf_record_companion_field.product_id = p_product AND kb.pdf_record_companion_field.revision_id = p_revision AND kb.pdf_record_companion_field.family = 'relation') AS field_rows ON kb.pdf_record_companion.family = 'relation' AND field_rows.local_id = kb.pdf_record_companion.local_id 
WHERE kb.pdf_record_companion.product_id = p_product AND kb.pdf_record_companion.revision_id = p_revision UNION ALL SELECT 'document' AS family, 'root' AS key, CAST(NULL AS kb.pdf_record_companion) AS companion, CAST(NULL AS kb.pdf_record_endpoint) AS endpoint, CAST(NULL AS kb.pdf_record_membership) AS member, CAST(NULL AS kb.pdf_record_native) AS node, CAST(NULL AS BYTEA) AS member_key, false AS has_relation_fields UNION ALL SELECT 'endpoint' AS family, ((('[' || ops.pdf_identity_ascii_string(kb.pdf_record_endpoint.relation_id)) || ',') || CAST(kb.pdf_record_endpoint.ordinal AS TEXT)) || ']' AS key, CAST(NULL AS kb.pdf_record_companion) AS companion, pdf_record_endpoint AS endpoint, CAST(NULL AS kb.pdf_record_membership) AS member, CAST(NULL AS kb.pdf_record_native) AS node, CAST(NULL AS BYTEA) AS member_key, false AS has_relation_fields 
FROM kb.pdf_record_endpoint 
WHERE kb.pdf_record_endpoint.product_id = p_product AND kb.pdf_record_endpoint.revision_id = p_revision UNION ALL SELECT 'membership' AS family, ((((('[' || ops.pdf_identity_ascii_string(kb.pdf_record_membership.parent_id)) || ',') || ops.pdf_identity_ascii_string(kb.pdf_record_membership.field_name)) || ',') || coalesce(ops.pdf_identity_ascii_string(encode(member_key.scalar, 'hex')), CAST(kb.pdf_record_membership.ordinal AS TEXT))) || ']' AS key, CAST(NULL AS kb.pdf_record_companion) AS companion, CAST(NULL AS kb.pdf_record_endpoint) AS endpoint, pdf_record_membership AS member, CAST(NULL AS kb.pdf_record_native) AS node, member_key.scalar AS member_key, false AS has_relation_fields 
FROM kb.pdf_record_membership JOIN LATERAL (SELECT CASE WHEN (kb.pdf_record_membership.member_key IS NOT NULL) THEN ops.pdf_identity_text(kb.pdf_record_membership.member_key) ELSE ops.pdf_identity_stream_scalar(p_product, p_revision, kb.pdf_record_membership.member_key_stream_id) END AS scalar
 LIMIT ALL OFFSET 0) AS member_key ON true 
WHERE kb.pdf_record_membership.product_id = p_product AND kb.pdf_record_membership.revision_id = p_revision UNION ALL SELECT 'native' AS family, kb.pdf_record_native.record_id AS key, CAST(NULL AS kb.pdf_record_companion) AS companion, CAST(NULL AS kb.pdf_record_endpoint) AS endpoint, CAST(NULL AS kb.pdf_record_membership) AS member, pdf_record_native AS node, CAST(NULL AS BYTEA) AS member_key, false AS has_relation_fields 
FROM kb.pdf_record_native 
WHERE kb.pdf_record_native.product_id = p_product AND kb.pdf_record_native.revision_id = p_revision UNION ALL SELECT 'publication' AS family, 'root' AS key, CAST(NULL AS kb.pdf_record_companion) AS companion, CAST(NULL AS kb.pdf_record_endpoint) AS endpoint, CAST(NULL AS kb.pdf_record_membership) AS member, CAST(NULL AS kb.pdf_record_native) AS node, CAST(NULL AS BYTEA) AS member_key, false AS has_relation_fields) AS ordered ORDER BY ordered.family COLLATE "C", ordered.key COLLATE "C" LOOP
  names_ := CAST(ARRAY[] AS TEXT[]);
  values_ := CAST(ARRAY[] AS BYTEA[]);
  IF (row_.family = 'publication') THEN
   names_ := CAST(ARRAY['kind', 'recipe_digest'] AS TEXT[]);
   SELECT CAST(ARRAY[ops.pdf_identity_scalar('s', convert_to(ops.pdf_frozen_build.kind, 'UTF8')), ops.pdf_identity_scalar('s', convert_to(ops.pdf_stage_build.recipe_digest, 'UTF8'))] AS BYTEA[]) AS anon_1 
FROM ops.pdf_frozen_build JOIN ops.pdf_stage_build ON ops.pdf_stage_build.build_id = ops.pdf_frozen_build.build_id 
WHERE ops.pdf_frozen_build.build_id = p_product INTO STRICT values_;
  END IF;
  IF (row_.family = 'document') THEN
   names_ := CAST(ARRAY['mapping_profile', 'contract_version', 'native_schema_digest', 'root_id'] AS TEXT[]);
   values_ := CAST(ARRAY[ops.pdf_identity_scalar('s', convert_to(header_.mapping_profile, 'UTF8')), ops.pdf_identity_scalar('s', convert_to(header_.contract_version, 'UTF8')), ops.pdf_identity_scalar('s', convert_to(header_.native_schema_digest, 'UTF8')), ops.pdf_identity_scalar('s', convert_to(header_.root_id, 'UTF8'))] AS BYTEA[]);
  END IF;
  IF (row_.family = 'native') THEN
   node_ := row_.node;
   names_ := CAST(ARRAY['native_type', 'family'] AS TEXT[]);
   values_ := CAST(ARRAY[ops.pdf_identity_scalar('s', convert_to(node_.native_type, 'UTF8')), ops.pdf_identity_scalar('s', convert_to(node_.family, 'UTF8'))] AS BYTEA[]);
   FOR field_ IN SELECT keys.key 
FROM (SELECT anon_1.key AS key 
FROM jsonb_object_keys(node_.scalars_json) AS anon_1(key) UNION SELECT anon_2.key AS key 
FROM jsonb_object_keys(node_.structure_json['fields']) AS anon_2(key)) AS keys ORDER BY keys.key COLLATE "C" LOOP
    IF (node_.scalars_json ? field_) THEN
     names_ := array_append(names_, field_ || '/value');
     values_ := array_append(values_, ops.pdf_identity_inline(node_.scalars_json[field_]));
    ELSE
     descriptor_ := node_.structure_json['fields'][field_];
     IF ((descriptor_ ->> 'kind') = 'parts') THEN
      names_ := array_append(names_, field_ || '/value');
      values_ := array_append(values_, ops.pdf_identity_stream_scalar(p_product, p_revision, descriptor_ ->> 'stream_id'));
     ELSE
      names_ := array_append(names_, field_ || '/kind');
      values_ := array_append(values_, ops.pdf_identity_scalar('s', convert_to(descriptor_ ->> 'kind', 'UTF8')));
      IF ((descriptor_ ->> 'kind') = 'object') THEN
       names_ := array_append(names_, field_ || '/target');
       values_ := array_append(values_, ops.pdf_identity_scalar('s', convert_to(descriptor_ ->> 'target', 'UTF8')));
      ELSE
       names_ := array_append(names_, field_ || '/length');
       values_ := array_append(values_, ops.pdf_identity_scalar('i', convert_to(descriptor_ ->> 'length', 'UTF8')));
