    names_ := array_append(names_, 'target');
    values_ := array_append(values_, ops.pdf_identity_scalar('s', convert_to(member_.record_id, 'UTF8')));
   ELSE
    names_ := array_append(names_, 'value');
    values_ := array_append(values_, CASE WHEN (member_.value_kind = 'scalar') THEN ops.pdf_identity_inline(member_.scalar_json) ELSE ops.pdf_identity_stream_scalar(p_product, p_revision, member_.stream_id) END);
   END IF;
  END IF;
  IF (left(row_.family, 10) = 'companion/') THEN
   companion_ := row_.companion;
   body_ := CASE WHEN (companion_.family = 'native_metadata' AND (companion_.body ->> 'kind') = 'inline_candidate_pages') THEN companion_.body - CAST(ARRAY['value', 'payload_codec', 'payload_schema_digest'] AS TEXT[]) WHEN (companion_.family = 'native_metadata') THEN companion_.body - 'value' WHEN (companion_.family = 'occurrence') THEN companion_.body - 'text' WHEN row_.has_relation_fields THEN ops.pdf_companion_restore_fields(p_product, p_revision, companion_.family, companion_.local_id, companion_.body) ELSE companion_.body END;
   IF (companion_.family = 'input') THEN
    body_ := jsonb_build_object('role', companion_.body['role'], 'target_meaning', ops.pdf_identity_published_target(CAST(companion_.body ->> 'task_id' AS BIGINT), companion_.body ->> 'product_key', companion_.body ->> 'content_digest'));
   END IF;
   names_ := CAST(ARRAY['body', 'ordinal'] AS TEXT[]);
   values_ := CAST(ARRAY[ops.pdf_identity_text(data.canonical_json(body_)), ops.pdf_identity_scalar('i', convert_to(CAST(companion_.ordinal AS TEXT), 'UTF8'))] AS BYTEA[]);
