    field_ := CASE WHEN (row_.family = 'companion/native_metadata') THEN 'value' ELSE 'text' END;
    names_ := array_append(names_, field_);
    values_ := array_append(values_, ops.pdf_identity_companion_scalar(p_product, p_revision, companion_.family, companion_.local_id, field_, companion_.body));
   END IF;
  END IF;
  IF (row_.family = 'endpoint') THEN
   endpoint_ := row_.endpoint;
   IF (endpoint_.target_task_id = 0 AND (endpoint_.target_product_key, endpoint_.target_content_digest) IS DISTINCT FROM ('@self', '@self')) THEN
    RAISE EXCEPTION USING MESSAGE = 'logical PDF self endpoint differs from canonical physical sentinel', ERRCODE = '23514';
   END IF;
   names_ := CAST(ARRAY['relation_id', 'ordinal', 'target_meaning', 'occurrence_id', 'role'] AS TEXT[]);
   values_ := CAST(ARRAY[ops.pdf_identity_text(endpoint_.relation_id), ops.pdf_identity_scalar('i', convert_to(CAST(endpoint_.ordinal AS TEXT), 'UTF8')), ops.pdf_identity_text(CASE WHEN (endpoint_.target_task_id = 0) THEN '@self' ELSE data.canonical_json(ops.pdf_identity_published_target(endpoint_.target_task_id, endpoint_.target_product_key, endpoint_.target_content_digest)) END), ops.pdf_identity_text(endpoint_.occurrence_id), ops.pdf_identity_text(endpoint_.role)] AS BYTEA[]);
  END IF;
  frame_ := ops.pdf_identity_record_frame(header_.native_schema_digest, row_.family, row_.key, names_, values_);
  IF (p_fold) THEN
   state_ := ops.pdf_identity_fold_step(state_, count_, frame_);
  ELSE
   IF (octet_length(frame_) > 65536 OR count_ >= 1000000 OR length_ + octet_length(frame_) > 402653184) THEN
    RAISE EXCEPTION USING MESSAGE = 'review native proof exceeds frame budget', ERRCODE = '54000';
   END IF;
   RETURN NEXT frame_;
  END IF;
  count_ := count_ + 1;
  length_ := length_ + octet_length(frame_);
 END LOOP;
 IF (p_fold) THEN
  RETURN NEXT ops.pdf_identity_fold_finish(state_, count_, length_);
 END IF;
END

