CREATE OR REPLACE FUNCTION ops.pdf_shared_stream_mutation_guard() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 row_ jsonb;
 content ops.pdf_shared_stream%ROWTYPE;
BEGIN
 IF (tg_op IN ('UPDATE', 'TRUNCATE')) THEN
  RAISE EXCEPTION USING MESSAGE = 'shared content cannot be updated or truncated', ERRCODE = '23514';
 END IF;
 row_ := CASE WHEN (tg_op = 'INSERT') THEN to_jsonb(new) ELSE to_jsonb(old) END;
 SELECT ops.pdf_shared_stream.project_id, ops.pdf_shared_stream.encoding_profile, ops.pdf_shared_stream.byte_length, ops.pdf_shared_stream.byte_root, ops.pdf_shared_stream.owner_build_id, ops.pdf_shared_stream.owner_attempt, ops.pdf_shared_stream.owner_holder 
FROM ops.pdf_shared_stream 
WHERE ops.pdf_shared_stream.project_id = (row_ ->> 'project_id') AND ops.pdf_shared_stream.encoding_profile = (row_ ->> 'encoding_profile') AND ops.pdf_shared_stream.byte_length = coalesce(CAST((row_ ->> 'stream_length') AS BIGINT), CAST((row_ ->> 'byte_length') AS BIGINT)) AND ops.pdf_shared_stream.byte_root = (row_ ->> 'byte_root') INTO STRICT content;
 IF (EXISTS (SELECT 1 
FROM ops.pdf_shared_stream_verification 
WHERE ops.pdf_shared_stream_verification.project_id = content.project_id AND ops.pdf_shared_stream_verification.encoding_profile = content.encoding_profile AND ops.pdf_shared_stream_verification.byte_length = content.byte_length AND ops.pdf_shared_stream_verification.byte_root = content.byte_root)) THEN
  RAISE EXCEPTION USING MESSAGE = 'verified content is immutable', ERRCODE = '23514';
 END IF;
 IF (tg_op = 'INSERT') THEN
  IF (ops.pdf_pending_stream_owner_dead(content)) THEN
   RAISE EXCEPTION USING MESSAGE = 'pending byte append fence is closed', ERRCODE = 'P0004';
  END IF;
  RETURN new;
 END IF;
 IF (NOT ops.pdf_pending_stream_owner_dead(content)) THEN
  RAISE EXCEPTION USING MESSAGE = 'verified content or live pending content is immutable', ERRCODE = '23514';
 END IF;
 RETURN old;
END$$

