DECLARE
 item_ record;
 state_ bytea := ops.pdf_identity_fold_start('pdf-validation-contract-v5');
 count_ bigint := 0;
 length_ bigint := 0;
 frame_ bytea;
BEGIN
 FOR item_ IN SELECT sem.input.input_name, sem.input.content 
FROM sem.input 
WHERE sem.input.release_id = p_release AND sem.input.input_kind = 'dependency' ORDER BY sem.input.input_name COLLATE "C" LOOP
  frame_ := (int8send(CAST(octet_length(item_.input_name) AS BIGINT)) || convert_to(item_.input_name, 'UTF8')) || sha256(item_.content);
  state_ := ops.pdf_identity_fold_step(state_, count_, frame_);
  count_ := count_ + 1;
  length_ := length_ + octet_length(frame_);
 END LOOP;
 IF (count_ = 0) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF validation release dependencies missing', ERRCODE = 'P0001';
 END IF;
 frame_ := convert_to('pdf-projection-write-profile-v1', 'UTF8') || decode('f5e16a3a9743d88eff168bea393ef48bfd577ef3df7c408c37430b7ef177dbed', 'hex');
 state_ := ops.pdf_identity_fold_step(state_, count_, frame_);
 count_ := count_ + 1;
 length_ := length_ + octet_length(frame_);
 frame_ := convert_to('pdf-integrated-metadata-policy-v1', 'UTF8') || decode('94131a5361dd8b9975c566c96742fffed41402cd67b575174643a28de59e6074', 'hex');
 state_ := ops.pdf_identity_fold_step(state_, count_, frame_);
 count_ := count_ + 1;
 length_ := length_ + octet_length(frame_);
 RETURN encode(ops.pdf_identity_fold_finish(state_, count_, length_), 'hex');
END

