DECLARE
 stream ops.pdf_stage_artifact_stream%ROWTYPE;
 project text := ops.pdf_stream_project(p_build);
 part ops.pdf_shared_stream_part%ROWTYPE;
 state bytea;
 pending bytea := CAST('' AS BYTEA);
 next_ordinal bigint := 0;
 offset_ bigint := 0;
 block_ordinal bigint := 0;
 present bigint;
 content ops.pdf_shared_stream%ROWTYPE;
 owner ops.pdf_stage_build%ROWTYPE;
BEGIN
 SELECT ops.pdf_stage_artifact_stream.product_id, ops.pdf_stage_artifact_stream.revision_id, ops.pdf_stage_artifact_stream.stream_id, ops.pdf_stage_artifact_stream.byte_length, ops.pdf_stage_artifact_stream.serialization_sha256, ops.pdf_stage_artifact_stream.byte_root, ops.pdf_stage_artifact_stream.encoding_profile 
FROM ops.pdf_stage_artifact_stream 
WHERE ops.pdf_stage_artifact_stream.product_id = p_build AND ops.pdf_stage_artifact_stream.revision_id = p_build AND ops.pdf_stage_artifact_stream.stream_id = p_stream INTO STRICT stream;
 SELECT ops.pdf_shared_stream.project_id, ops.pdf_shared_stream.encoding_profile, ops.pdf_shared_stream.byte_length, ops.pdf_shared_stream.byte_root, ops.pdf_shared_stream.owner_build_id, ops.pdf_shared_stream.owner_attempt, ops.pdf_shared_stream.owner_holder 
FROM ops.pdf_shared_stream 
WHERE ops.pdf_shared_stream.project_id = project AND ops.pdf_shared_stream.encoding_profile = stream.encoding_profile AND ops.pdf_shared_stream.byte_length = stream.byte_length AND ops.pdf_shared_stream.byte_root = stream.byte_root FOR UPDATE INTO STRICT content;
 IF (ops.pdf_shared_stream_ready(p_build, stream.encoding_profile, stream.byte_length, stream.byte_root)) THEN
  RETURN;
 END IF;
 SELECT ops.pdf_stage_build.build_id, ops.pdf_stage_build.task_id, ops.pdf_stage_build.release_id, ops.pdf_stage_build.source_digest, ops.pdf_stage_build.recipe_digest, ops.pdf_stage_build.schema_digest, ops.pdf_stage_build.replay_key, ops.pdf_stage_build.attempt, ops.pdf_stage_build.holder, ops.pdf_stage_build.state 
FROM ops.pdf_stage_build 
WHERE ops.pdf_stage_build.build_id = p_build INTO STRICT owner;
 IF ((content.owner_build_id, content.owner_attempt, content.owner_holder) IS DISTINCT FROM (owner.build_id, owner.attempt, owner.holder)) THEN
  RAISE EXCEPTION USING MESSAGE = 'pending fold belongs to another append fence', ERRCODE = '55P03';
 END IF;
 state := ops.pdf_identity_fold_start('bytes');
 SELECT coalesce(sum(ops.pdf_shared_stream_part.byte_length), 0) AS coalesce_1 
FROM ops.pdf_shared_stream_part 
WHERE ops.pdf_shared_stream_part.project_id = project AND ops.pdf_shared_stream_part.encoding_profile = stream.encoding_profile AND ops.pdf_shared_stream_part.stream_length = stream.byte_length AND ops.pdf_shared_stream_part.byte_root = stream.byte_root INTO present;
 IF (NOT p_complete AND present < stream.byte_length) THEN
  RETURN;
 END IF;
 FOR part IN SELECT ops.pdf_shared_stream_part.project_id, ops.pdf_shared_stream_part.encoding_profile, ops.pdf_shared_stream_part.stream_length, ops.pdf_shared_stream_part.byte_root, ops.pdf_shared_stream_part.ordinal, ops.pdf_shared_stream_part.byte_offset, ops.pdf_shared_stream_part.byte_length, ops.pdf_shared_stream_part.body, ops.pdf_shared_stream_part.sha256_digest 
FROM ops.pdf_shared_stream_part 
WHERE ops.pdf_shared_stream_part.project_id = project AND ops.pdf_shared_stream_part.encoding_profile = stream.encoding_profile AND ops.pdf_shared_stream_part.stream_length = stream.byte_length AND ops.pdf_shared_stream_part.byte_root = stream.byte_root ORDER BY ops.pdf_shared_stream_part.ordinal LOOP
  IF (part.ordinal != next_ordinal OR part.byte_offset != offset_ OR part.byte_length != octet_length(part.body) OR part.byte_length NOT BETWEEN 1 AND 65536 OR part.sha256_digest != encode(sha256(part.body), 'hex')) THEN
   RAISE EXCEPTION USING MESSAGE = 'shared stream actual bytes/ordinal/offset/length/hash differs', ERRCODE = '23514';
  END IF;
  pending := pending || part.body;
  WHILE octet_length(pending) >= 65536 LOOP
   state := ops.pdf_identity_fold_step(state, block_ordinal, substr(pending, 1, 65536));
   pending := substr(pending, 65537);
   block_ordinal := block_ordinal + 1;
  END LOOP;
  offset_ := offset_ + part.byte_length;
  next_ordinal := next_ordinal + 1;
 END LOOP;
 IF (octet_length(pending) > 0) THEN
  state := ops.pdf_identity_fold_step(state, block_ordinal, pending);
  block_ordinal := block_ordinal + 1;
 END IF;
 IF (offset_ != stream.byte_length OR encode(ops.pdf_identity_fold_finish(state, block_ordinal, offset_), 'hex') != stream.byte_root) THEN
  RAISE EXCEPTION USING MESSAGE = 'shared stream actual fold differs from its content key', ERRCODE = '23514';
 END IF;
 INSERT INTO ops.pdf_shared_stream_verification (project_id, encoding_profile, byte_length, byte_root, part_count) VALUES (project, stream.encoding_profile, stream.byte_length, stream.byte_root, next_ordinal) ON CONFLICT DO NOTHING;
END

