DECLARE
 build ops.pdf_stage_build%ROWTYPE;
 packet jsonb;
 descriptor jsonb;
BEGIN
 build := ops.require_pdf_build(p_build, p_task, p_attempt, p_holder);
 PERFORM ops.require_pdf_operation(build.release_id, 'adopt_pdf_batch');
 IF (p_streams IS NULL OR octet_length(p_streams) > 67108864) THEN
  RAISE EXCEPTION USING MESSAGE = 'shared stream probe exceeds its upload bound', ERRCODE = '23514';
 END IF;
 packet := CAST(convert_from(p_streams, 'UTF8') AS JSONB);
 IF (jsonb_typeof(packet) IS DISTINCT FROM 'array') THEN
  RAISE EXCEPTION USING MESSAGE = 'shared stream probe requires an array', ERRCODE = '23514';
 END IF;
 IF (jsonb_array_length(packet) > 65536) THEN
  RAISE EXCEPTION USING MESSAGE = 'shared stream probe requires a bounded descriptor set', ERRCODE = '23514';
 END IF;
 FOR descriptor IN SELECT anon_1.value 
FROM jsonb_array_elements(packet) AS anon_1 LOOP
  PERFORM ops.ddo_fields(descriptor, ARRAY['product_id', 'revision_id', 'stream_id', 'encoding_profile', 'byte_length', 'byte_root'], ARRAY['serialization_sha256']);
  IF (jsonb_typeof(descriptor['product_id']) IS DISTINCT FROM 'string' OR jsonb_typeof(descriptor['revision_id']) IS DISTINCT FROM 'string' OR jsonb_typeof(descriptor['stream_id']) IS DISTINCT FROM 'string' OR jsonb_typeof(descriptor['encoding_profile']) IS DISTINCT FROM 'string' OR jsonb_typeof(descriptor['byte_root']) IS DISTINCT FROM 'string' OR (descriptor ->> 'product_id') IS DISTINCT FROM p_build OR (descriptor ->> 'revision_id') IS DISTINCT FROM p_build OR nullif((descriptor ->> 'stream_id'), '') IS NULL OR nullif((descriptor ->> 'encoding_profile'), '') IS NULL OR jsonb_typeof(descriptor['byte_length']) IS DISTINCT FROM 'number' OR NOT coalesce((descriptor ->> 'byte_length') ~ '^(0|[1-9][0-9]*)$', false) OR NOT coalesce((descriptor ->> 'byte_root') ~ '^[0-9a-f]{64}$', false) OR (descriptor ? 'serialization_sha256') AND descriptor['serialization_sha256'] != CAST('null' AS JSONB) AND (jsonb_typeof(descriptor['serialization_sha256']) IS DISTINCT FROM 'string' OR NOT coalesce((descriptor ->> 'serialization_sha256') ~ '^[0-9a-f]{64}$', false))) THEN
   RAISE EXCEPTION USING MESSAGE = 'shared stream probe changes its owned build/key', ERRCODE = '23514';
  END IF;
  RETURN QUERY SELECT descriptor ->> 'stream_id' AS anon_1, ops.pdf_shared_stream_ready(p_build, descriptor ->> 'encoding_profile', CAST(descriptor ->> 'byte_length' AS BIGINT), descriptor ->> 'byte_root') AS pdf_shared_stream_ready_1;
 END LOOP;
END

