CREATE OR REPLACE FUNCTION ops.publish_pdf_observation(p_task bigint, p_attempt bigint, p_holder text, p_runtime text, p_contract text, p_payload bytea, p_artifacts bytea[]) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 job ops.task%ROWTYPE;
 context record;
 definition sem.data_operation_definition%ROWTYPE;
 native_request ops.data_request%ROWTYPE;
 previous ops.pdf_product%ROWTYPE;
 pin ops.pdf_product%ROWTYPE;
 product jsonb := CAST('{}' AS JSONB);
 digest text := encode(sha256(p_payload), 'hex');
 original text;
 wire json;
 field_name text;
 field_value json;
 envelope_fields text[] := ARRAY[]::TEXT[];
 input_rows json;
 occurrence_rows json;
 relation_rows json;
 coverage_rows json;
 mapping_rows json;
 input jsonb;
 occurrence jsonb;
 relation jsonb;
 endpoint jsonb;
 coverage jsonb;
 mapping_report jsonb;
 selected jsonb;
 publication jsonb;
 recognition_profile jsonb;
 idx bigint;
 eid bigint;
BEGIN
 SELECT ops.task.* 
FROM ops.task 
WHERE ops.task.id = p_task INTO STRICT job;
 SELECT * 
FROM ops.pdf_task_context(p_task) INTO STRICT context;
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition JOIN ops.data_request ON ops.data_request.release_id = sem.data_operation_definition.release_id AND ops.data_request.operation_id = sem.data_operation_definition.operation_id 
WHERE ops.data_request.id = context.request_id INTO STRICT definition;
 IF (NOT coalesce(definition.command_class = 'pdf', false) OR ((definition.support_contract['effects'][0]) ->> 'name') IS DISTINCT FROM 'retain_pdf_observations') THEN
  RAISE EXCEPTION USING MESSAGE = 'native observations require the exact approved PDF recognition effect', ERRCODE = '23514';
 END IF;
 IF (job.attempt IS DISTINCT FROM p_attempt OR job.claimed_by IS DISTINCT FROM p_holder) THEN
  RAISE EXCEPTION USING MESSAGE = 'stale recognition observation attempt', ERRCODE = 'P0004';
 END IF;
 PERFORM sem.require_runtime_binding(context.release_id, p_runtime);
 IF (NOT (EXISTS (SELECT 1 
FROM sem.runtime_binding 
WHERE sem.runtime_binding.release_id = context.release_id AND sem.runtime_binding.runtime_id = p_runtime AND (CAST(convert_from(sem.runtime_binding.manifest_bytes, 'UTF8') AS JSONB) ->> 'execution_profile') = (SELECT (ops.data_request.binding ->> 'execution_profile') AS anon_1 
FROM ops.data_request 
WHERE ops.data_request.id = context.request_id))) OR (EXISTS (SELECT 1 
FROM ops.data_revocation 
WHERE ops.data_revocation.scope = ops.ddo_scope(context.project_id, (SELECT ops.data_request.original_source 
FROM ops.data_request 
WHERE ops.data_request.id = context.request_id)) AND ops.data_revocation.selector_kind = 'runtime' AND ops.data_revocation.selector = p_runtime))) THEN
  RAISE EXCEPTION USING MESSAGE = 'observation publisher runtime differs from admitted request profile/trust', ERRCODE = '23514';
 END IF;
 wire := CAST(convert_from(p_payload, 'UTF8') AS JSON);
 IF (json_typeof(wire) IS DISTINCT FROM 'object' OR (wire ->> 'kind') IS DISTINCT FROM 'recognition_observation') THEN
  RAISE EXCEPTION USING MESSAGE = 'parsing record must be an object: PdfIntegratedProduct', ERRCODE = '23514';
 END IF;
 FOR field_name, field_value IN SELECT fields.key, fields.value 
FROM json_each(wire) AS fields(key, value) LOOP
  envelope_fields := array_append(envelope_fields, field_name);
  IF (field_name = 'content') THEN
   RAISE EXCEPTION USING MESSAGE = 'document content is not an observation', ERRCODE = '23514';
  END IF;
  IF (field_name = 'inputs') THEN
   input_rows := field_value;
  END IF;
  IF (field_name = 'occurrences') THEN
   occurrence_rows := field_value;
  END IF;
  IF (field_name = 'relations') THEN
   relation_rows := field_value;
  END IF;
  IF (field_name = 'coverage') THEN
   coverage_rows := field_value;
  END IF;
  IF (field_name = 'mapping_reports') THEN
   mapping_rows := field_value;
  END IF;
  IF ((field_name NOT IN ('inputs', 'occurrences', 'relations', 'coverage', 'mapping_reports', 'content'))) THEN
   product := product || jsonb_build_object(field_name, CAST(field_value AS JSONB));
  END IF;
 END LOOP;
 IF (jsonb_typeof(product) IS DISTINCT FROM 'object') THEN
  RAISE EXCEPTION USING MESSAGE = 'parsing record must be an object: PdfObservationProduct', ERRCODE = '23514';
 END IF;
 IF ((EXISTS (SELECT shape_0.value 
FROM unnest(envelope_fields) AS shape_0(value) 
WHERE NOT (shape_0.value = ANY (ARRAY['mapping_reports', 'version', 'kind', 'product_key', 'artifact_digest', 'recipe_digest', 'inputs', 'occurrences', 'relations', 'coverage', 'health', 'observation', 'content'])))) OR 'mapping_reports' = ANY (envelope_fields) AND json_typeof(mapping_rows) IS DISTINCT FROM 'array' OR NOT ('version' = ANY (envelope_fields)) OR 'version' = ANY (envelope_fields) AND (jsonb_typeof(product['version']) IS DISTINCT FROM 'number' OR ((product['version'] #>> ARRAY[]::TEXT[]) !~ '^[0-9]+$')) OR 'version' = ANY (envelope_fields) AND CAST(product['version'] #>> ARRAY[]::TEXT[] AS NUMERIC) < '1' OR 'version' = ANY (envelope_fields) AND CAST(product['version'] #>> ARRAY[]::TEXT[] AS NUMERIC) > '1' OR NOT ('kind' = ANY (envelope_fields)) OR 'kind' = ANY (envelope_fields) AND (jsonb_typeof(product['kind']) IS DISTINCT FROM 'string' OR ((product['kind'] #>> ARRAY[]::TEXT[]) NOT IN ('recognition_observation'))) OR NOT ('product_key' = ANY (envelope_fields)) OR 'product_key' = ANY (envelope_fields) AND jsonb_typeof(product['product_key']) IS DISTINCT FROM 'string' OR NOT ('artifact_digest' = ANY (envelope_fields)) OR 'artifact_digest' = ANY (envelope_fields) AND jsonb_typeof(product['artifact_digest']) IS DISTINCT FROM 'string' OR 'artifact_digest' = ANY (envelope_fields) AND ((product['artifact_digest'] #>> ARRAY[]::TEXT[]) !~ '^[0-9a-f]{64}$(?![\s\S])') OR NOT ('recipe_digest' = ANY (envelope_fields)) OR 'recipe_digest' = ANY (envelope_fields) AND jsonb_typeof(product['recipe_digest']) IS DISTINCT FROM 'string' OR 'recipe_digest' = ANY (envelope_fields) AND ((product['recipe_digest'] #>> ARRAY[]::TEXT[]) !~ '^[0-9a-f]{64}$(?![\s\S])') OR 'inputs' = ANY (envelope_fields) AND json_typeof(input_rows) IS DISTINCT FROM 'array' OR 'occurrences' = ANY (envelope_fields) AND json_typeof(occurrence_rows) IS DISTINCT FROM 'array' OR 'relations' = ANY (envelope_fields) AND json_typeof(relation_rows) IS DISTINCT FROM 'array' OR NOT ('coverage' = ANY (envelope_fields)) OR 'coverage' = ANY (envelope_fields) AND (json_typeof(coverage_rows) IS DISTINCT FROM 'array' OR json_array_length(coverage_rows) < 1) OR NOT ('health' = ANY (envelope_fields)) OR 'health' = ANY (envelope_fields) AND (jsonb_typeof(product['health']) IS DISTINCT FROM 'object' OR (EXISTS (SELECT shape_1.value 
FROM jsonb_object_keys(product['health']) AS shape_1(value) 
WHERE NOT (shape_1.value = ANY (ARRAY['execution_outcome', 'mapping_outcome', 'source_fidelity', 'validation_report'])))) OR NOT (product['health'] ? 'execution_outcome') OR (product['health'] ? 'execution_outcome') AND (jsonb_typeof(product['health']['execution_outcome']) IS DISTINCT FROM 'string' OR ((product['health']['execution_outcome'] #>> ARRAY[]::TEXT[]) NOT IN ('failed', 'partial', 'succeeded', 'unknown', 'unsupported'))) OR NOT (product['health'] ? 'mapping_outcome') OR (product['health'] ? 'mapping_outcome') AND (jsonb_typeof(product['health']['mapping_outcome']) IS DISTINCT FROM 'string' OR ((product['health']['mapping_outcome'] #>> ARRAY[]::TEXT[]) NOT IN ('coarse', 'partial', 'unknown', 'unsupported'))) OR NOT (product['health'] ? 'source_fidelity') OR (product['health'] ? 'source_fidelity') AND (jsonb_typeof(product['health']['source_fidelity']) IS DISTINCT FROM 'string' OR ((product['health']['source_fidelity'] #>> ARRAY[]::TEXT[]) NOT IN ('conflict', 'unassessed', 'unknown'))) OR NOT (product['health'] ? 'validation_report') OR (product['health'] ? 'validation_report') AND jsonb_typeof(product['health']['validation_report']) IS DISTINCT FROM 'string') OR 'observation' = ANY (envelope_fields) AND (jsonb_typeof(product['observation']) IS DISTINCT FROM 'object' OR (EXISTS (SELECT shape_2.value 
FROM jsonb_object_keys(product['observation']) AS shape_2(value) 
WHERE NOT (shape_2.value = ANY (ARRAY['binding', 'image', 'pass_role', 'raw_response_digest', 'mapped_evidence_digest', 'finish_reason', 'usage_json', 'outcome', 'usage_availability', 'diagnostic'])))) OR NOT (product['observation'] ? 'binding') OR (product['observation'] ? 'binding') AND (jsonb_typeof(product['observation']['binding']) IS DISTINCT FROM 'object' OR (EXISTS (SELECT shape_3.value 
FROM jsonb_object_keys(product['observation']['binding']) AS shape_3(value) 
WHERE NOT (shape_3.value = ANY (ARRAY['provider', 'package_identity', 'source_identity', 'weights_digest', 'tokenizer_digest', 'prompt_digest', 'decoding_json', 'seed', 'render_policy', 'crop_policy', 'merge_policy'])))) OR NOT (product['observation']['binding'] ? 'provider') OR (product['observation']['binding'] ? 'provider') AND jsonb_typeof(product['observation']['binding']['provider']) IS DISTINCT FROM 'string' OR NOT (product['observation']['binding'] ? 'package_identity') OR (product['observation']['binding'] ? 'package_identity') AND jsonb_typeof(product['observation']['binding']['package_identity']) IS DISTINCT FROM 'string' OR NOT (product['observation']['binding'] ? 'source_identity') OR (product['observation']['binding'] ? 'source_identity') AND jsonb_typeof(product['observation']['binding']['source_identity']) IS DISTINCT FROM 'string' OR NOT (product['observation']['binding'] ? 'weights_digest') OR (product['observation']['binding'] ? 'weights_digest') AND jsonb_typeof(product['observation']['binding']['weights_digest']) IS DISTINCT FROM 'string' OR (product['observation']['binding'] ? 'weights_digest') AND ((product['observation']['binding']['weights_digest'] #>> ARRAY[]::TEXT[]) !~ '^[0-9a-f]{64}$(?![\s\S])') OR NOT (product['observation']['binding'] ? 'tokenizer_digest') OR (product['observation']['binding'] ? 'tokenizer_digest') AND jsonb_typeof(product['observation']['binding']['tokenizer_digest']) IS DISTINCT FROM 'string' OR (product['observation']['binding'] ? 'tokenizer_digest') AND ((product['observation']['binding']['tokenizer_digest'] #>> ARRAY[]::TEXT[]) !~ '^[0-9a-f]{64}$(?![\s\S])') OR NOT (product['observation']['binding'] ? 'prompt_digest') OR (product['observation']['binding'] ? 'prompt_digest') AND jsonb_typeof(product['observation']['binding']['prompt_digest']) IS DISTINCT FROM 'string' OR (product['observation']['binding'] ? 'prompt_digest') AND ((product['observation']['binding']['prompt_digest'] #>> ARRAY[]::TEXT[]) !~ '^[0-9a-f]{64}$(?![\s\S])') OR NOT (product['observation']['binding'] ? 'decoding_json') OR (product['observation']['binding'] ? 'decoding_json') AND jsonb_typeof(product['observation']['binding']['decoding_json']) IS DISTINCT FROM 'string' OR NOT (product['observation']['binding'] ? 'seed') OR (product['observation']['binding'] ? 'seed') AND jsonb_typeof(product['observation']['binding']['seed']) IS DISTINCT FROM 'string' OR NOT (product['observation']['binding'] ? 'render_policy') OR (product['observation']['binding'] ? 'render_policy') AND jsonb_typeof(product['observation']['binding']['render_policy']) IS DISTINCT FROM 'string' OR NOT (product['observation']['binding'] ? 'crop_policy') OR (product['observation']['binding'] ? 'crop_policy') AND jsonb_typeof(product['observation']['binding']['crop_policy']) IS DISTINCT FROM 'string' OR NOT (product['observation']['binding'] ? 'merge_policy') OR (product['observation']['binding'] ? 'merge_policy') AND jsonb_typeof(product['observation']['binding']['merge_policy']) IS DISTINCT FROM 'string') OR NOT (product['observation'] ? 'image') OR (product['observation'] ? 'image') AND (jsonb_typeof(product['observation']['image']) IS DISTINCT FROM 'object' OR (EXISTS (SELECT shape_4.value 
FROM jsonb_object_keys(product['observation']['image']) AS shape_4(value) 
WHERE NOT (shape_4.value = ANY (ARRAY['artifact_digest', 'page_no', 'width', 'height', 'encoding', 'transform', 'precision'])))) OR NOT (product['observation']['image'] ? 'artifact_digest') OR (product['observation']['image'] ? 'artifact_digest') AND jsonb_typeof(product['observation']['image']['artifact_digest']) IS DISTINCT FROM 'string' OR (product['observation']['image'] ? 'artifact_digest') AND ((product['observation']['image']['artifact_digest'] #>> ARRAY[]::TEXT[]) !~ '^[0-9a-f]{64}$(?![\s\S])') OR NOT (product['observation']['image'] ? 'page_no') OR (product['observation']['image'] ? 'page_no') AND (jsonb_typeof(product['observation']['image']['page_no']) IS DISTINCT FROM 'number' OR ((product['observation']['image']['page_no'] #>> ARRAY[]::TEXT[]) !~ '^[0-9]+$')) OR (product['observation']['image'] ? 'page_no') AND CAST(product['observation']['image']['page_no'] #>> ARRAY[]::TEXT[] AS NUMERIC) < '1' OR NOT (product['observation']['image'] ? 'width') OR (product['observation']['image'] ? 'width') AND (jsonb_typeof(product['observation']['image']['width']) IS DISTINCT FROM 'number' OR ((product['observation']['image']['width'] #>> ARRAY[]::TEXT[]) !~ '^[0-9]+$')) OR (product['observation']['image'] ? 'width') AND CAST(product['observation']['image']['width'] #>> ARRAY[]::TEXT[] AS NUMERIC) < '1' OR NOT (product['observation']['image'] ? 'height') OR (product['observation']['image'] ? 'height') AND (jsonb_typeof(product['observation']['image']['height']) IS DISTINCT FROM 'number' OR ((product['observation']['image']['height'] #>> ARRAY[]::TEXT[]) !~ '^[0-9]+$')) OR (product['observation']['image'] ? 'height') AND CAST(product['observation']['image']['height'] #>> ARRAY[]::TEXT[] AS NUMERIC) < '1' OR NOT (product['observation']['image'] ? 'encoding') OR (product['observation']['image'] ? 'encoding') AND jsonb_typeof(product['observation']['image']['encoding']) IS DISTINCT FROM 'string' OR (product['observation']['image']['encoding'] #>> ARRAY[]::TEXT[]) IS DISTINCT FROM 'png' OR NOT (product['observation']['image'] ? 'transform') OR (product['observation']['image'] ? 'transform') AND (jsonb_typeof(product['observation']['image']['transform']) IS DISTINCT FROM 'object' OR (EXISTS (SELECT shape_5.value 
