DECLARE
 b ops.pdf_stage_build%ROWTYPE;
 c ops.pdf_producer_certification%ROWTYPE;
 oracle_ text;
 basis_ text;
BEGIN
 b := ops.require_pdf_frozen(p_build, p_task, p_attempt, p_holder, p_frozen);
 SELECT ops.pdf_producer_certification.build_id, ops.pdf_producer_certification.attempt, ops.pdf_producer_certification.holder, ops.pdf_producer_certification.lowering_identity, ops.pdf_producer_certification.kind, ops.pdf_producer_certification.logical_digest, ops.pdf_producer_certification.native_document_digest, ops.pdf_producer_certification.stream_inventory_digest, ops.pdf_producer_certification.source_digest, ops.pdf_producer_certification.recipe_digest, ops.pdf_producer_certification.schema_digest 
FROM ops.pdf_producer_certification 
WHERE ops.pdf_producer_certification.build_id = p_build INTO STRICT c;
 IF (c.lowering_identity IS DISTINCT FROM ops.pdf_lowering_identity(b.release_id) OR (c.source_digest, c.recipe_digest, c.schema_digest, c.kind) IS DISTINCT FROM (b.source_digest, b.recipe_digest, b.schema_digest, (SELECT ops.pdf_frozen_build.kind 
FROM ops.pdf_frozen_build 
WHERE ops.pdf_frozen_build.build_id = p_build))) THEN
  RAISE EXCEPTION USING MESSAGE = 'frozen PDF producer certification differs', ERRCODE = '23514';
 END IF;
 SELECT ops.pdf_roundtrip_oracle.oracle_receipt_id 
FROM ops.pdf_roundtrip_oracle 
WHERE ops.pdf_roundtrip_oracle.build_id = p_build AND ops.pdf_roundtrip_oracle.frozen_digest = p_frozen AND ops.pdf_roundtrip_oracle.lowering_identity = c.lowering_identity AND ops.pdf_roundtrip_oracle.kind = c.kind AND ops.pdf_roundtrip_oracle.logical_digest = c.logical_digest AND ops.pdf_roundtrip_oracle.native_document_digest = c.native_document_digest AND ops.pdf_roundtrip_oracle.state = 'passed' ORDER BY ops.pdf_roundtrip_oracle.oracle_receipt_id 
 LIMIT 1 INTO oracle_;
 basis_ := 'round-trip-verified';
 IF (oracle_ IS NULL) THEN
  SELECT ops.pdf_roundtrip_oracle.oracle_receipt_id 
FROM ops.pdf_roundtrip_oracle JOIN ops.pdf_published_revision ON ops.pdf_published_revision.build_id = ops.pdf_roundtrip_oracle.build_id AND ops.pdf_published_revision.frozen_digest = ops.pdf_roundtrip_oracle.frozen_digest AND ops.pdf_published_revision.logical_digest = ops.pdf_roundtrip_oracle.logical_digest AND ops.pdf_published_revision.kind = ops.pdf_roundtrip_oracle.kind JOIN ops.pdf_build_validation ON ops.pdf_build_validation.build_id = ops.pdf_published_revision.build_id AND ops.pdf_build_validation.frozen_digest = ops.pdf_published_revision.frozen_digest AND ops.pdf_build_validation.logical_digest = ops.pdf_published_revision.logical_digest AND ops.pdf_build_validation.oracle_receipt_id = ops.pdf_roundtrip_oracle.oracle_receipt_id JOIN ops.pdf_stage_build AS prior_build ON prior_build.build_id = ops.pdf_roundtrip_oracle.build_id 
WHERE ops.pdf_roundtrip_oracle.lowering_identity = c.lowering_identity AND (CAST(convert_from(ops.pdf_contract_input(b.release_id, 'implementation/pdf/lowering-contract.json'), 'UTF8') AS JSONB))['code_identity']['complete'] = CAST('true' AS JSONB) AND ops.pdf_lowering_identity(prior_build.release_id) = c.lowering_identity AND ops.pdf_roundtrip_oracle.kind = c.kind AND ops.pdf_roundtrip_oracle.state = 'passed' ORDER BY ops.pdf_roundtrip_oracle.oracle_receipt_id 
 LIMIT 1 INTO oracle_;
  basis_ := 'producer-certified';
 END IF;
 RETURN QUERY SELECT c.lowering_identity, c.kind, c.logical_digest, c.native_document_digest, oracle_, basis_;
END

