FROM ops.pdf_roundtrip_oracle JOIN ops.pdf_published_revision ON ops.pdf_published_revision.build_id = ops.pdf_roundtrip_oracle.build_id AND ops.pdf_published_revision.frozen_digest = ops.pdf_roundtrip_oracle.frozen_digest AND ops.pdf_published_revision.logical_digest = ops.pdf_roundtrip_oracle.logical_digest AND ops.pdf_published_revision.kind = ops.pdf_roundtrip_oracle.kind JOIN ops.pdf_build_validation ON ops.pdf_build_validation.build_id = ops.pdf_published_revision.build_id AND ops.pdf_build_validation.frozen_digest = ops.pdf_published_revision.frozen_digest AND ops.pdf_build_validation.logical_digest = ops.pdf_published_revision.logical_digest AND ops.pdf_build_validation.oracle_receipt_id = ops.pdf_roundtrip_oracle.oracle_receipt_id JOIN ops.pdf_stage_build AS prior_build ON prior_build.build_id = ops.pdf_roundtrip_oracle.build_id 
WHERE ops.pdf_roundtrip_oracle.lowering_identity = c.lowering_identity AND (CAST(convert_from(ops.pdf_contract_input(b.release_id, 'implementation/pdf/lowering-contract.json'), 'UTF8') AS JSONB))['code_identity']['complete'] = CAST('true' AS JSONB) AND ops.pdf_lowering_identity(prior_build.release_id) = c.lowering_identity AND ops.pdf_roundtrip_oracle.kind = c.kind AND ops.pdf_roundtrip_oracle.state = 'passed' ORDER BY ops.pdf_roundtrip_oracle.oracle_receipt_id 
 LIMIT 1 INTO oracle_;
  basis_ := 'producer-certified';
 END IF;
 RETURN QUERY SELECT c.lowering_identity, c.kind, c.logical_digest, c.native_document_digest, oracle_, basis_;
END$$

