DECLARE
 b ops.pdf_stage_build%ROWTYPE;
 item_ jsonb;
 result_ jsonb := CAST('[]' AS JSONB);
 meaning_ jsonb;
BEGIN
 b := ops.require_pdf_build(p_build, p_task, p_attempt, p_holder);
 IF (jsonb_typeof(p_targets) IS DISTINCT FROM 'array' OR jsonb_array_length(p_targets) > 512) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF producer targets must be a bounded array', ERRCODE = 'P0001';
 END IF;
 FOR item_ IN SELECT anon_1.value 
FROM jsonb_array_elements(p_targets) AS anon_1 LOOP
  meaning_ := ops.pdf_identity_published_target(CAST(item_ ->> 0 AS BIGINT), item_ ->> 1, item_ ->> 2);
  IF ((meaning_ ->> 'source_digest') IS DISTINCT FROM b.source_digest) THEN
   RAISE EXCEPTION USING MESSAGE = 'PDF producer target changes original source', ERRCODE = '23514';
  END IF;
  result_ := result_ || jsonb_build_array(jsonb_build_object('pin', item_, 'meaning', meaning_));
 END LOOP;
 RETURN convert_to(CAST(result_ AS TEXT), 'UTF8');
END

