  RETURN;
 END IF;
 IF (p_family = 'companion') THEN
  IF (EXISTS (SELECT 1 
FROM jsonb_object_keys(p_filters) AS anon_1(value) 
WHERE NOT (anon_1.value = ANY (ARRAY['family', 'local_id', 'kind', 'pointer', 'page_nos'])))) THEN
   RAISE EXCEPTION USING MESSAGE = 'unsupported published record filter', ERRCODE = '22023';
  END IF;
  RETURN QUERY SELECT (to_jsonb(r) || jsonb_build_object('_cursor', jsonb_build_array(r.family, r.ordinal, r.local_id))) || jsonb_build_object('_fields', coalesce((SELECT jsonb_agg(jsonb_build_object('field_name', kb.pdf_record_companion_field.field_name, 'stream_id', kb.pdf_record_companion_field.stream_id, 'scalar_kind', kb.pdf_record_companion_field.scalar_kind, 'encoding_profile', ops.pdf_artifact_stream.encoding_profile) ORDER BY kb.pdf_record_companion_field.field_name) AS jsonb_agg_1 
FROM kb.pdf_record_companion_field JOIN ops.pdf_artifact_stream ON kb.pdf_record_companion_field.product_id = ops.pdf_artifact_stream.product_id AND kb.pdf_record_companion_field.revision_id = ops.pdf_artifact_stream.revision_id AND kb.pdf_record_companion_field.stream_id = ops.pdf_artifact_stream.stream_id 
WHERE kb.pdf_record_companion_field.product_id = r.product_id AND kb.pdf_record_companion_field.revision_id = r.revision_id AND kb.pdf_record_companion_field.family = r.family AND kb.pdf_record_companion_field.local_id = r.local_id), CAST('[]' AS JSONB))) AS anon_1 
FROM kb.pdf_record_companion AS r 
WHERE r.product_id = published.build_id AND r.revision_id = published.build_id AND (NOT ((p_filters ? 'family')) OR r.family = (p_filters ->> 'family')) AND (NOT ((p_filters ? 'local_id')) OR r.local_id = (p_filters ->> 'local_id')) AND (NOT ((p_filters ? 'kind')) OR r.body['kind'] = p_filters['kind']) AND (NOT ((p_filters ? 'pointer')) OR r.body['pointer'] = p_filters['pointer']) AND (NOT ((p_filters ? 'page_nos')) OR r.body['page_no'] IN (SELECT anon_2.value 
FROM jsonb_array_elements(p_filters['page_nos']) AS anon_2)) AND (p_after IS NULL OR p_after[1] = CAST('null' AS JSONB) AND (r.family > CAST((p_after ->> 0) AS TEXT) OR r.family = CAST((p_after ->> 0) AS TEXT) AND r.ordinal IS NULL AND r.local_id > CAST((p_after ->> 2) AS TEXT)) OR p_after[1] != CAST('null' AS JSONB) AND ((r.family, r.ordinal, r.local_id) > (CAST((p_after ->> 0) AS TEXT), CAST((p_after ->> 1) AS BIGINT), CAST((p_after ->> 2) AS TEXT)) OR r.family = CAST((p_after ->> 0) AS TEXT) AND r.ordinal IS NULL)) ORDER BY r.family, r.ordinal NULLS LAST, r.local_id 
 LIMIT p_limit;
  RETURN;
 END IF;
 IF (p_family = 'companion_field') THEN
  IF (EXISTS (SELECT 1 
FROM jsonb_object_keys(p_filters) AS anon_1(value) 
WHERE NOT (anon_1.value = ANY (ARRAY['family', 'local_id', 'field_name'])))) THEN
   RAISE EXCEPTION USING MESSAGE = 'unsupported published record filter', ERRCODE = '22023';
  END IF;
  RETURN QUERY SELECT to_jsonb(r) || jsonb_build_object('_cursor', jsonb_build_array(r.family, r.local_id, r.field_name)) AS anon_1 
FROM kb.pdf_record_companion_field AS r 
WHERE r.product_id = published.build_id AND r.revision_id = published.build_id AND (NOT ((p_filters ? 'family')) OR r.family = (p_filters ->> 'family')) AND (NOT ((p_filters ? 'local_id')) OR r.local_id = (p_filters ->> 'local_id')) AND (NOT ((p_filters ? 'field_name')) OR r.field_name = (p_filters ->> 'field_name')) AND (p_after IS NULL OR (r.family, r.local_id, r.field_name) > (CAST((p_after ->> 0) AS TEXT), CAST((p_after ->> 1) AS TEXT), CAST((p_after ->> 2) AS TEXT))) ORDER BY r.family, r.local_id, r.field_name 
 LIMIT p_limit;
  RETURN;
 END IF;
 IF (p_family = 'endpoint') THEN
  IF (EXISTS (SELECT 1 
FROM jsonb_object_keys(p_filters) AS anon_1(value) 
WHERE NOT (anon_1.value = ANY (ARRAY['relation_id', 'occurrence_id'])))) THEN
   RAISE EXCEPTION USING MESSAGE = 'unsupported published record filter', ERRCODE = '22023';
  END IF;
  RETURN QUERY SELECT to_jsonb(r) || jsonb_build_object('_cursor', jsonb_build_array(r.relation_id, r.ordinal)) AS anon_1 
FROM kb.pdf_record_endpoint AS r 
WHERE r.product_id = published.build_id AND r.revision_id = published.build_id AND (NOT ((p_filters ? 'relation_id')) OR r.relation_id = (p_filters ->> 'relation_id')) AND (NOT ((p_filters ? 'occurrence_id')) OR r.occurrence_id = (p_filters ->> 'occurrence_id')) AND (p_after IS NULL OR (r.relation_id, r.ordinal) > (CAST((p_after ->> 0) AS TEXT), CAST((p_after ->> 1) AS BIGINT))) ORDER BY r.relation_id, r.ordinal NULLS LAST 
 LIMIT p_limit;
  RETURN;
 END IF;
 RAISE EXCEPTION USING MESSAGE = 'unknown published record family', ERRCODE = '22023';
END$$

