DECLARE
 owner record;
BEGIN
 SELECT anon_1.project_id, anon_1.release_id, anon_1.request_id, anon_1.generation, anon_1.document_id, anon_1.source_digest 
FROM ops.require_pdf_stage_owner(p_task, p_attempt, p_holder) AS anon_1 INTO STRICT owner;
 PERFORM ops.require_pdf_operation(owner.release_id, 'retain_pdf_original');
 PERFORM sem.require_runtime_binding(owner.release_id, p_runtime);
 RETURN QUERY SELECT ops.data_request.id, ops.data_request.generation, ops.data_request.release_id, ops.data_request.operation_id, sem.data_operation_definition.definition_identity, sem.data_operation_definition.recipe, sem.data_operation_definition.implementation_revision, sem.runtime_binding.execution_profile, sem.runtime_binding.runtime_id, encode(sha256(sem.runtime_binding.manifest_bytes), 'hex') AS encode_1, sem.input.content_digest 
FROM ops.data_request JOIN sem.data_operation_definition ON sem.data_operation_definition.release_id = ops.data_request.release_id AND sem.data_operation_definition.operation_id = ops.data_request.operation_id JOIN sem.runtime_binding ON sem.runtime_binding.release_id = ops.data_request.release_id AND sem.runtime_binding.runtime_id = p_runtime JOIN sem.input ON sem.input.release_id = ops.data_request.release_id AND sem.input.input_kind = 'dependency' AND sem.input.input_name = 'pdf-domain/contract.json' AND encode(sha256(sem.input.content), 'hex') = sem.input.content_digest 
WHERE ops.data_request.id = owner.request_id AND ops.data_request.generation = owner.generation AND ops.data_request.runtime_id = p_runtime;
 IF (NOT found) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF producer runtime differs from current request fence', ERRCODE = 'P0004';
 END IF;
END

