  RETURN QUERY SELECT to_jsonb(r) || jsonb_build_object('_cursor', jsonb_build_array(r.parent_id, r.field_name, r.ordinal)) AS anon_1 
FROM kb.pdf_record_membership AS r 
WHERE r.product_id = published.build_id AND r.revision_id = published.build_id AND (NOT ((p_filters ? 'parent_id')) OR r.parent_id = (p_filters ->> 'parent_id')) AND (NOT ((p_filters ? 'field_name')) OR r.field_name = (p_filters ->> 'field_name')) AND (p_after IS NULL OR (r.parent_id, r.field_name, r.ordinal) > (CAST((p_after ->> 0) AS TEXT), CAST((p_after ->> 1) AS TEXT), CAST((p_after ->> 2) AS BIGINT))) ORDER BY r.parent_id, r.field_name, r.ordinal NULLS LAST 
 LIMIT p_limit;
  RETURN;
 END IF;
 IF (p_family = 'reference') THEN
  IF (EXISTS (SELECT 1 
FROM jsonb_object_keys(p_filters) AS anon_1(value) 
WHERE NOT (anon_1.value = ANY (ARRAY['source_id', 'target_id'])))) THEN
   RAISE EXCEPTION USING MESSAGE = 'unsupported published record filter', ERRCODE = '22023';
  END IF;
  RETURN QUERY SELECT to_jsonb(r) || jsonb_build_object('_cursor', jsonb_build_array(r.reference_id)) AS anon_1 
FROM kb.pdf_record_reference AS r 
WHERE r.product_id = published.build_id AND r.revision_id = published.build_id AND (NOT ((p_filters ? 'source_id')) OR r.source_id = (p_filters ->> 'source_id')) AND (NOT ((p_filters ? 'target_id')) OR r.target_id = (p_filters ->> 'target_id')) AND (p_after IS NULL OR (r.reference_id) > (CAST((p_after ->> 0) AS TEXT))) ORDER BY r.reference_id 
 LIMIT p_limit;
  RETURN;
 END IF;
 IF (p_family = 'artifact_stream') THEN
  IF (EXISTS (SELECT 1 
FROM jsonb_object_keys(p_filters) AS anon_1(value) 
WHERE NOT (anon_1.value = ANY (ARRAY['stream_id', 'stream_ids'])))) THEN
   RAISE EXCEPTION USING MESSAGE = 'unsupported published record filter', ERRCODE = '22023';
  END IF;
  IF (p_filters ? 'stream_ids') THEN
   IF (jsonb_typeof(p_filters['stream_ids']) IS DISTINCT FROM 'array') THEN
    RAISE EXCEPTION USING MESSAGE = 'published stream set requires 1..512 exact IDs', ERRCODE = '22023';
   END IF;
   IF (jsonb_array_length(p_filters['stream_ids']) NOT BETWEEN 1 AND 512 OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(p_filters['stream_ids']) AS anon_1 
WHERE jsonb_typeof(anon_1.value) != 'string'))) THEN
    RAISE EXCEPTION USING MESSAGE = 'published stream set requires 1..512 exact IDs', ERRCODE = '22023';
   END IF;
  END IF;
  selected_stream_ids := CASE WHEN (p_filters ? 'stream_id') THEN ARRAY[p_filters ->> 'stream_id'] WHEN (p_filters ? 'stream_ids') THEN (SELECT array_agg(anon_1.value) AS array_agg_1 
FROM jsonb_array_elements_text(p_filters['stream_ids']) AS anon_1) END;
  RETURN QUERY SELECT to_jsonb(r) || jsonb_build_object('_cursor', jsonb_build_array(r.stream_id)) AS anon_1 
FROM ops.pdf_artifact_stream AS r 
WHERE r.product_id = published.build_id AND r.revision_id = published.build_id AND (NOT ((p_filters ? 'stream_id')) OR r.stream_id = (p_filters ->> 'stream_id')) AND (NOT ((p_filters ? 'stream_ids')) OR r.stream_id IN (SELECT anon_2.value 
FROM jsonb_array_elements_text(p_filters['stream_ids']) AS anon_2)) AND (p_after IS NULL OR (r.stream_id) > (CAST((p_after ->> 0) AS TEXT))) ORDER BY r.stream_id 
 LIMIT p_limit;
  RETURN;
 END IF;
 IF (p_family = 'artifact_part') THEN
  IF (EXISTS (SELECT 1 
FROM jsonb_object_keys(p_filters) AS anon_1(value) 
WHERE NOT (anon_1.value = ANY (ARRAY['stream_id', 'stream_ids'])))) THEN
   RAISE EXCEPTION USING MESSAGE = 'unsupported published record filter', ERRCODE = '22023';
  END IF;
  IF (p_filters ? 'stream_ids') THEN
   IF (jsonb_typeof(p_filters['stream_ids']) IS DISTINCT FROM 'array') THEN
    RAISE EXCEPTION USING MESSAGE = 'published stream set requires 1..512 exact IDs', ERRCODE = '22023';
   END IF;
   IF (jsonb_array_length(p_filters['stream_ids']) NOT BETWEEN 1 AND 512 OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(p_filters['stream_ids']) AS anon_1 
WHERE jsonb_typeof(anon_1.value) != 'string'))) THEN
    RAISE EXCEPTION USING MESSAGE = 'published stream set requires 1..512 exact IDs', ERRCODE = '22023';
   END IF;
  END IF;
  selected_stream_ids := CASE WHEN (p_filters ? 'stream_id') THEN ARRAY[p_filters ->> 'stream_id'] WHEN (p_filters ? 'stream_ids') THEN (SELECT array_agg(anon_1.value) AS array_agg_1 
FROM jsonb_array_elements_text(p_filters['stream_ids']) AS anon_1) END;
  RETURN QUERY SELECT to_jsonb(anon_2) || jsonb_build_object('_cursor', jsonb_build_array(anon_2.stream_id, anon_2.ordinal)) AS anon_1 
FROM ops.pdf_artifact_parts(published.build_id, published.build_id, false, selected_stream_ids) AS anon_2 
WHERE anon_2.product_id = published.build_id AND anon_2.revision_id = published.build_id AND (NOT ((p_filters ? 'stream_id')) OR anon_2.stream_id = (p_filters ->> 'stream_id')) AND (NOT ((p_filters ? 'stream_ids')) OR anon_2.stream_id IN (SELECT anon_3.value 
FROM jsonb_array_elements_text(p_filters['stream_ids']) AS anon_3)) AND (p_after IS NULL OR (anon_2.stream_id, anon_2.ordinal) > (CAST((p_after ->> 0) AS TEXT), CAST((p_after ->> 1) AS BIGINT))) ORDER BY anon_2.stream_id, anon_2.ordinal NULLS LAST 
 LIMIT p_limit;
  RETURN;
 END IF;
 IF (p_family = 'companion') THEN
  IF (EXISTS (SELECT 1 
FROM jsonb_object_keys(p_filters) AS anon_1(value) 
WHERE NOT (anon_1.value = ANY (ARRAY['family', 'local_id', 'kind', 'pointer', 'page_nos'])))) THEN
   RAISE EXCEPTION USING MESSAGE = 'unsupported published record filter', ERRCODE = '22023';
  END IF;
  RETURN QUERY SELECT (to_jsonb(r) || jsonb_build_object('_cursor', jsonb_build_array(r.family, r.ordinal, r.local_id))) || jsonb_build_object('_fields', coalesce((SELECT jsonb_agg(jsonb_build_object('field_name', kb.pdf_record_companion_field.field_name, 'stream_id', kb.pdf_record_companion_field.stream_id, 'scalar_kind', kb.pdf_record_companion_field.scalar_kind, 'encoding_profile', ops.pdf_artifact_stream.encoding_profile) ORDER BY kb.pdf_record_companion_field.field_name) AS jsonb_agg_1 
FROM kb.pdf_record_companion_field JOIN ops.pdf_artifact_stream ON kb.pdf_record_companion_field.product_id = ops.pdf_artifact_stream.product_id AND kb.pdf_record_companion_field.revision_id = ops.pdf_artifact_stream.revision_id AND kb.pdf_record_companion_field.stream_id = ops.pdf_artifact_stream.stream_id 
WHERE kb.pdf_record_companion_field.product_id = r.product_id AND kb.pdf_record_companion_field.revision_id = r.revision_id AND kb.pdf_record_companion_field.family = r.family AND kb.pdf_record_companion_field.local_id = r.local_id), CAST('[]' AS JSONB))) AS anon_1 
FROM kb.pdf_record_companion AS r 
WHERE r.product_id = published.build_id AND r.revision_id = published.build_id AND (NOT ((p_filters ? 'family')) OR r.family = (p_filters ->> 'family')) AND (NOT ((p_filters ? 'local_id')) OR r.local_id = (p_filters ->> 'local_id')) AND (NOT ((p_filters ? 'kind')) OR r.body['kind'] = p_filters['kind']) AND (NOT ((p_filters ? 'pointer')) OR r.body['pointer'] = p_filters['pointer']) AND (NOT ((p_filters ? 'page_nos')) OR r.body['page_no'] IN (SELECT anon_2.value 
FROM jsonb_array_elements(p_filters['page_nos']) AS anon_2)) AND (p_after IS NULL OR p_after[1] = CAST('null' AS JSONB) AND (r.family > CAST((p_after ->> 0) AS TEXT) OR r.family = CAST((p_after ->> 0) AS TEXT) AND r.ordinal IS NULL AND r.local_id > CAST((p_after ->> 2) AS TEXT)) OR p_after[1] != CAST('null' AS JSONB) AND ((r.family, r.ordinal, r.local_id) > (CAST((p_after ->> 0) AS TEXT), CAST((p_after ->> 1) AS BIGINT), CAST((p_after ->> 2) AS TEXT)) OR r.family = CAST((p_after ->> 0) AS TEXT) AND r.ordinal IS NULL)) ORDER BY r.family, r.ordinal NULLS LAST, r.local_id 
 LIMIT p_limit;
