DECLARE
 b ops.pdf_stage_build%ROWTYPE;
 basis_ record;
 candidate_basis_ jsonb;
 candidate_premises_ jsonb;
 request_snapshot_ jsonb;
 candidate_recovery_key_ text;
BEGIN
 b := ops.require_pdf_build(p_build, p_task, p_attempt, p_holder);
 PERFORM ops.require_pdf_operation(b.release_id, 'stage_pdf_producer');
 SELECT spool_basis.* 
FROM ops.read_pdf_producer_basis(p_task, p_attempt, p_holder, p_runtime) AS spool_basis INTO STRICT basis_;
 candidate_basis_ := to_jsonb(basis_);
 candidate_premises_ := CAST(convert_from(p_premises, 'UTF8') AS JSONB);
 request_snapshot_ := (SELECT to_jsonb(data_request) || jsonb_build_object('subject_definition', sem.data_operation_definition.subject_definition) AS anon_1 
FROM ops.data_request JOIN sem.data_operation_definition ON sem.data_operation_definition.release_id = ops.data_request.release_id AND sem.data_operation_definition.operation_id = ops.data_request.operation_id 
WHERE ops.data_request.id = (candidate_basis_ ->> 'request_id'));
 IF (ops.pdf_spool_request_material(request_snapshot_) IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF recovery lacks valid original support material', ERRCODE = '23514';
 END IF;
 IF (candidate_premises_['producer'] IS DISTINCT FROM candidate_basis_ OR (candidate_premises_ ->> 'source_digest') IS DISTINCT FROM b.source_digest OR (candidate_premises_ ->> 'native_recipe_digest') IS DISTINCT FROM b.recipe_digest OR (candidate_premises_ ->> 'native_schema_digest') IS DISTINCT FROM b.schema_digest) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF recovery premises differ from current native basis', ERRCODE = '23514';
 END IF;
 candidate_recovery_key_ := encode(sha256(convert_to(CAST(jsonb_build_array(ops.pdf_spool_request_material(request_snapshot_), (((((((candidate_basis_ - 'runtime_id') - 'runtime_manifest_digest') - 'request_id') - 'generation') - 'release_id') - 'definition_identity') - 'definition') - 'pdf_domain_digest', to_jsonb(b.source_digest), to_jsonb(b.recipe_digest), to_jsonb(b.schema_digest)) AS TEXT), 'UTF8')), 'hex');
 RETURN QUERY SELECT ops.pdf_spool_producer.build_id, ops.pdf_spool_producer.task_id, ops.pdf_spool_producer.producer_id, ops.pdf_spool_producer.attempt, ops.pdf_spool_producer.holder, ops.pdf_spool_producer.writer_device, ops.pdf_spool_producer.writer_inode, ops.pdf_spool_producer.premises_bytes 
FROM ops.pdf_spool_producer JOIN ops.data_execution_origin ON ops.data_execution_origin.id = ops.pdf_spool_producer.execution_origin_id 
WHERE (EXISTS (SELECT 1 
FROM ops.data_attempt_failure 
WHERE ops.data_attempt_failure.request_id = (((CAST(convert_from(ops.pdf_spool_producer.premises_bytes, 'UTF8') AS JSONB))['producer']) ->> 'request_id') AND ops.data_attempt_failure.generation = CAST((((CAST(convert_from(ops.pdf_spool_producer.premises_bytes, 'UTF8') AS JSONB))['producer']) ->> 'generation') AS BIGINT) AND ops.data_attempt_failure.task_id = ops.pdf_spool_producer.task_id AND ops.data_attempt_failure.attempt = ops.pdf_spool_producer.attempt AND ops.data_attempt_failure.holder = ops.pdf_spool_producer.holder)) AND (CAST(convert_from(ops.pdf_spool_producer.premises_bytes, 'UTF8') AS JSONB) - 'producer') IS NOT DISTINCT FROM (candidate_premises_ - 'producer') AND ops.pdf_spool_producer.recovery_key = candidate_recovery_key_ AND ops.pdf_spool_producer.execution_origin_id IS NOT NULL AND ops.pdf_spool_request_material(ops.data_execution_origin.request_snapshot || jsonb_build_object('subject_definition', ops.data_execution_origin.definition_snapshot['subject_definition'])) IS NOT NULL AND ops.pdf_spool_request_material(request_snapshot_) IS NOT NULL AND ops.pdf_spool_request_material(ops.data_execution_origin.request_snapshot || jsonb_build_object('subject_definition', ops.data_execution_origin.definition_snapshot['subject_definition'])) IS NOT DISTINCT FROM ops.pdf_spool_request_material(request_snapshot_) AND (((((((((CAST(convert_from(ops.pdf_spool_producer.premises_bytes, 'UTF8') AS JSONB))['producer'] - 'runtime_id') - 'runtime_manifest_digest') - 'request_id') - 'generation') - 'release_id') - 'definition_identity') - 'definition') - 'pdf_domain_digest') IS NOT DISTINCT FROM ((((((((candidate_basis_ - 'runtime_id') - 'runtime_manifest_digest') - 'request_id') - 'generation') - 'release_id') - 'definition_identity') - 'definition') - 'pdf_domain_digest') AND coalesce(ops.pdf_spool_material_identity((((CAST(convert_from(ops.pdf_spool_producer.premises_bytes, 'UTF8') AS JSONB))['producer']) ->> 'release_id'), (((CAST(convert_from(ops.pdf_spool_producer.premises_bytes, 'UTF8') AS JSONB))['producer']) ->> 'pdf_domain_digest')) = ops.pdf_spool_material_identity((candidate_basis_ ->> 'release_id'), (candidate_basis_ ->> 'pdf_domain_digest')), false) AND (CAST(convert_from(ops.pdf_spool_producer.premises_bytes, 'UTF8') AS JSONB) ->> 'source_digest') = b.source_digest AND (CAST(convert_from(ops.pdf_spool_producer.premises_bytes, 'UTF8') AS JSONB) ->> 'native_recipe_digest') = b.recipe_digest AND (CAST(convert_from(ops.pdf_spool_producer.premises_bytes, 'UTF8') AS JSONB) ->> 'native_schema_digest') = b.schema_digest ORDER BY ops.pdf_spool_producer.task_id DESC, ops.pdf_spool_producer.attempt DESC, ops.pdf_spool_producer.producer_id 
 LIMIT 64;
END

