DECLARE
 placement ops.pdf_published_revision%ROWTYPE;
 selected_body jsonb;
 relation_body jsonb;
 provider jsonb;
 observation jsonb;
BEGIN
 BEGIN
  SELECT anon_1.build_id, anon_1.task_id, anon_1.product_key, anon_1.logical_digest, anon_1.release_id, anon_1.source_digest, anon_1.schema_digest, anon_1.recipe_digest, anon_1.frozen_digest, anon_1.kind 
FROM ops.read_pdf_published_revision(p_task, p_key, p_digest) AS anon_1 INTO STRICT placement;
  SELECT anon_1.body 
FROM ops.pdf_record_context_rows(p_task, p_key, p_digest, ARRAY[p_pointer], p_pointer) AS anon_1 
WHERE anon_1.family = 'occurrence' AND anon_1.local_id = (p_address ->> 'selected_occurrence_id') INTO STRICT selected_body;
  IF ((selected_body ->> 'pointer') IS DISTINCT FROM p_pointer) THEN
   RAISE EXCEPTION USING MESSAGE = 'captured recognition selected occurrence differs from source pointer', ERRCODE = '23514';
  END IF;
  SELECT anon_1.body 
FROM ops.pdf_record_context_rows(p_task, p_key, p_digest, ARRAY[p_pointer], p_pointer) AS anon_1 
WHERE anon_1.family = 'relation' AND anon_1.local_id = (p_address ->> 'relation_id') INTO STRICT relation_body;
  IF (((p_address ->> 'endpoint_role') NOT IN ('input', 'evidence', 'alternative')) OR (p_address ->> 'relation_kind') IS DISTINCT FROM 'decision' OR (relation_body ->> 'kind') IS DISTINCT FROM (p_address ->> 'relation_kind') OR (relation_body ->> 'outcome') IS DISTINCT FROM (p_address ->> 'relation_outcome') OR ((relation_body ->> 'outcome') NOT IN ('selected', 'added', 'replaced', 'retained_alternative')) OR NOT (EXISTS (SELECT 1 
FROM kb.pdf_record_endpoint 
WHERE kb.pdf_record_endpoint.product_id = placement.build_id AND kb.pdf_record_endpoint.revision_id = placement.build_id AND kb.pdf_record_endpoint.relation_id = (p_address ->> 'relation_id') AND kb.pdf_record_endpoint.role = 'output' AND kb.pdf_record_endpoint.occurrence_id = (p_address ->> 'selected_occurrence_id') AND ((kb.pdf_record_endpoint.target_task_id, kb.pdf_record_endpoint.target_product_key, kb.pdf_record_endpoint.target_content_digest) = (p_task, p_key, p_digest) OR (kb.pdf_record_endpoint.target_task_id, kb.pdf_record_endpoint.target_product_key, kb.pdf_record_endpoint.target_content_digest) = (0, '@self', '@self')))) OR NOT (EXISTS (SELECT 1 
FROM kb.pdf_record_endpoint 
WHERE kb.pdf_record_endpoint.product_id = placement.build_id AND kb.pdf_record_endpoint.revision_id = placement.build_id AND kb.pdf_record_endpoint.relation_id = (p_address ->> 'relation_id') AND kb.pdf_record_endpoint.role = (p_address ->> 'endpoint_role') AND kb.pdf_record_endpoint.occurrence_id = (p_address ->> 'occurrence_id') AND (kb.pdf_record_endpoint.target_task_id, kb.pdf_record_endpoint.target_product_key, kb.pdf_record_endpoint.target_content_digest) = (CAST((p_address ->> 'task_id') AS BIGINT), (p_address ->> 'product_key'), (p_address ->> 'content_digest'))))) THEN
   RAISE EXCEPTION USING MESSAGE = 'unsupported or forged captured recognition decision lineage', ERRCODE = '23514';
  END IF;
  SELECT kb.pdf_occurrence.body, ops.pdf_product_body.descriptor['observation'] AS anon_1 
FROM kb.pdf_occurrence JOIN ops.pdf_product ON kb.pdf_occurrence.task_id = ops.pdf_product.task_id AND kb.pdf_occurrence.product_key = ops.pdf_product.product_key JOIN ops.pdf_product_body ON kb.pdf_occurrence.task_id = ops.pdf_product_body.task_id AND kb.pdf_occurrence.product_key = ops.pdf_product_body.product_key 
WHERE kb.pdf_occurrence.task_id = CAST((p_address ->> 'task_id') AS BIGINT) AND kb.pdf_occurrence.product_key = (p_address ->> 'product_key') AND ops.pdf_product.content_digest = (p_address ->> 'content_digest') AND ops.pdf_product.kind = 'recognition_observation' AND encode(sha256(ops.pdf_product_body.payload), 'hex') = ops.pdf_product.content_digest AND kb.pdf_occurrence.occurrence_id = (p_address ->> 'occurrence_id') INTO STRICT provider, observation;
  IF (provider IS DISTINCT FROM CAST((p_address ->> 'provider_occurrence_json') AS JSONB) OR observation IS DISTINCT FROM CAST((p_address ->> 'observation_json') AS JSONB) OR ((provider ->> 'precision') NOT IN ('unknown', 'coarse', 'block')) OR (provider ? 'start') OR (provider ? 'end') OR jsonb_typeof(provider['text']) IS DISTINCT FROM 'string') THEN
   RAISE EXCEPTION USING MESSAGE = 'captured recognition provider custody or original precision differs', ERRCODE = '23514';
  END IF;
  RETURN provider ->> 'text';
 EXCEPTION WHEN no_data_found OR too_many_rows THEN
  RAISE EXCEPTION USING MESSAGE = 'captured recognition has no unique admitted retained lineage/body', ERRCODE = '23514';
 END;
END

