DECLARE
 digest text := encode(sha256(p_original), 'hex');
 document_key text;
 retained kb.document%ROWTYPE;
BEGIN
 PERFORM ops.require_source_admission(p_release);
 IF (NOT pg_has_role(coalesce(nullif(current_setting('role'), 'none'), SESSION_USER), 'corpus_sem_writer', 'MEMBER')) THEN
  RAISE EXCEPTION USING MESSAGE = 'source registration requires native write purpose', ERRCODE = '42501';
 END IF;
 IF (p_original IS NULL OR p_content_hash IS DISTINCT FROM digest) THEN
  RAISE EXCEPTION USING MESSAGE = 'original artifact differs from registered document', ERRCODE = '23514';
 END IF;
 document_key := 'doc:' || left(ops.ddo_digest(jsonb_build_object('project', normalize(p_project_id), 'source_uri', normalize(p_source_uri), 'content_hash', digest)), 32);
 INSERT INTO kb.document (project_id, key, source_uri, content_hash, original_path, mime, title, meta) VALUES (p_project_id, document_key, p_source_uri, digest, p_original_path, p_mime, p_title, p_meta) ON CONFLICT (project_id, key) DO NOTHING;
 SELECT kb.document.* 
FROM kb.document 
WHERE kb.document.project_id = p_project_id AND kb.document.key = document_key FOR SHARE INTO STRICT retained;
 IF ((retained.project_id, retained.key, retained.source_uri, retained.content_hash, retained.original_path, retained.mime, retained.title, retained.meta) IS DISTINCT FROM (p_project_id, document_key, p_source_uri, digest, p_original_path, p_mime, p_title, p_meta)) THEN
  RAISE EXCEPTION USING MESSAGE = 'source identity denotes another source descriptor', ERRCODE = '23505', CONSTRAINT = 'original_document_descriptor_identity';
 END IF;
 INSERT INTO kb.source_artifact (artifact_digest, content) VALUES (digest, p_original) ON CONFLICT DO NOTHING;
 IF (NOT (EXISTS (SELECT 1 
FROM kb.source_artifact 
WHERE kb.source_artifact.artifact_digest = digest AND kb.source_artifact.content = p_original))) THEN
  RAISE EXCEPTION USING MESSAGE = 'original artifact identity differs', ERRCODE = '23505';
 END IF;
 RETURN NEXT retained;
END

