DECLARE
 b ops.pdf_stage_build%ROWTYPE;
 producer_ ops.pdf_spool_producer%ROWTYPE;
 current_ record;
 original_ jsonb;
 current_basis_ jsonb;
 current_premises_ jsonb;
 original_request_ jsonb;
 current_request_ jsonb;
 header_ jsonb;
 declaration_ jsonb;
 entry_ jsonb;
 selected_ jsonb;
 replay_ jsonb;
 inventory_ jsonb := CAST('[]' AS JSONB);
 lines_ text[];
 line_ text;
 id_ text;
 manifest_ text;
 selection_ text;
 prior ops.pdf_spool_contributor%ROWTYPE;
BEGIN
 b := ops.require_pdf_build(p_build, p_task, p_attempt, p_holder);
 PERFORM ops.require_pdf_operation(b.release_id, 'stage_pdf_producer');
 SELECT spool_basis.* 
FROM ops.read_pdf_producer_basis(p_task, p_attempt, p_holder, p_runtime) AS spool_basis INTO STRICT current_;
 SELECT ops.pdf_spool_producer.* 
FROM ops.pdf_spool_producer 
WHERE ops.pdf_spool_producer.producer_id = p_producer INTO STRICT producer_;
 original_ := CAST(convert_from(producer_.premises_bytes, 'UTF8') AS JSONB);
 current_basis_ := (((((((to_jsonb(current_) - 'runtime_id') - 'runtime_manifest_digest') - 'request_id') - 'generation') - 'release_id') - 'definition_identity') - 'definition') - 'pdf_domain_digest';
 SELECT CAST(convert_from(ops.pdf_spool_producer.premises_bytes, 'UTF8') AS JSONB) AS convert_from_1 
FROM ops.pdf_spool_producer 
WHERE ops.pdf_spool_producer.build_id = p_build AND ops.pdf_spool_producer.attempt = p_attempt AND ops.pdf_spool_producer.holder = p_holder INTO STRICT current_premises_;
 original_request_ := (SELECT ops.data_execution_origin.request_snapshot || jsonb_build_object('subject_definition', ops.data_execution_origin.definition_snapshot['subject_definition']) AS anon_1 
FROM ops.data_execution_origin 
WHERE ops.data_execution_origin.id = producer_.execution_origin_id);
 current_request_ := (SELECT to_jsonb(data_request) || jsonb_build_object('subject_definition', sem.data_operation_definition.subject_definition) AS anon_1 
FROM ops.data_request JOIN sem.data_operation_definition ON sem.data_operation_definition.release_id = ops.data_request.release_id AND sem.data_operation_definition.operation_id = ops.data_request.operation_id 
WHERE ops.data_request.id = ((current_premises_['producer']) ->> 'request_id'));
 IF (ops.pdf_spool_request_material(current_request_) IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF contribution lacks valid original support material', ERRCODE = '23514';
 END IF;
 IF (NOT (producer_.build_id = p_build AND producer_.task_id = p_task AND producer_.attempt = p_attempt AND producer_.holder = p_holder AND original_ IS NOT DISTINCT FROM current_premises_ OR (EXISTS (SELECT 1 
FROM ops.data_attempt_failure 
WHERE ops.data_attempt_failure.request_id = ((original_['producer']) ->> 'request_id') AND ops.data_attempt_failure.generation = CAST(((original_['producer']) ->> 'generation') AS BIGINT) AND ops.data_attempt_failure.task_id = producer_.task_id AND ops.data_attempt_failure.attempt = producer_.attempt AND ops.data_attempt_failure.holder = producer_.holder)) AND producer_.execution_origin_id IS NOT NULL AND ops.pdf_spool_request_material(original_request_) IS NOT NULL AND ops.pdf_spool_request_material(current_request_) IS NOT NULL AND ops.pdf_spool_request_material(original_request_) IS NOT DISTINCT FROM ops.pdf_spool_request_material(current_request_) AND ((((((((original_['producer'] - 'runtime_id') - 'runtime_manifest_digest') - 'request_id') - 'generation') - 'release_id') - 'definition_identity') - 'definition') - 'pdf_domain_digest') IS NOT DISTINCT FROM current_basis_ AND coalesce(ops.pdf_spool_material_identity(((original_['producer']) ->> 'release_id'), ((original_['producer']) ->> 'pdf_domain_digest')) = ops.pdf_spool_material_identity(((current_premises_['producer']) ->> 'release_id'), ((current_premises_['producer']) ->> 'pdf_domain_digest')), false)) OR (original_ ->> 'source_digest') IS DISTINCT FROM b.source_digest OR (original_ ->> 'native_recipe_digest') IS DISTINCT FROM b.recipe_digest OR (original_ ->> 'native_schema_digest') IS DISTINCT FROM b.schema_digest OR (original_ - 'producer') IS DISTINCT FROM (current_premises_ - 'producer')) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF spool contributor has no matching original producer', ERRCODE = '23514';
 END IF;
 IF (p_manifest IS NULL OR octet_length(p_manifest) = 0 OR right(convert_from(p_manifest, 'UTF8'), 1) != '
') THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF spool manifest has no durable complete entries', ERRCODE = '23514';
 END IF;
 lines_ := string_to_array(rtrim(convert_from(p_manifest, 'UTF8'), '
'), '
');
 IF (cardinality(lines_) < 2) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF spool manifest lacks producer declaration', ERRCODE = 'P0001';
 END IF;
 header_ := CAST(lines_[1] AS JSONB);
 declaration_ := CAST(lines_[2] AS JSONB);
 IF ((header_ ->> 'version') IS DISTINCT FROM 'pdf-build-spool-1' OR (header_ ->> 'build_id') IS DISTINCT FROM producer_.build_id OR CAST((header_ ->> 'task_id') AS BIGINT) IS DISTINCT FROM producer_.task_id OR CAST((header_ ->> 'attempt') AS BIGINT) IS DISTINCT FROM producer_.attempt OR (header_ ->> 'holder') IS DISTINCT FROM producer_.holder OR CAST(((header_['writer']) ->> 'device') AS BIGINT) IS DISTINCT FROM producer_.writer_device OR CAST(((header_['writer']) ->> 'inode') AS BIGINT) IS DISTINCT FROM producer_.writer_inode OR (declaration_ ->> 'producer_id') IS DISTINCT FROM p_producer OR declaration_['premises'] IS DISTINCT FROM original_) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF manifest differs from immutable original producer custody', ERRCODE = '23514';
 END IF;
 FOR line_ IN SELECT manifest_line.value 
FROM unnest(lines_) WITH ORDINALITY AS manifest_line(value, ordinal) 
WHERE manifest_line.ordinal >= 3 ORDER BY manifest_line.ordinal LOOP
  entry_ := CAST(line_ AS JSONB);
  IF (entry_ ? 'replay') THEN
   inventory_ := inventory_ || jsonb_build_array(entry_['replay']);
  ELSE
   IF (NOT (entry_ ? 'completion')) THEN
    RAISE EXCEPTION USING MESSAGE = 'PDF spool manifest entry is not declared', ERRCODE = 'P0001';
   END IF;
  END IF;
 END LOOP;
 selected_ := CAST(convert_from(p_selected, 'UTF8') AS JSONB);
 IF (jsonb_typeof(selected_) IS DISTINCT FROM 'array' OR jsonb_array_length(selected_) = 0) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF spool contributor selected no files', ERRCODE = 'P0001';
 END IF;
 FOR replay_ IN SELECT selected_replay.value 
FROM jsonb_array_elements(selected_) AS selected_replay(value) LOOP
  IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(inventory_) AS inventory_member(value) 
WHERE inventory_member.value = replay_)) OR (coalesce((replay_ ->> 'digest'), '') !~ '^[0-9a-f]{64}$') OR CAST((replay_ ->> 'byte_length') AS BIGINT) < 0 OR nullif((replay_ ->> 'path'), '') IS NULL) THEN
   RAISE EXCEPTION USING MESSAGE = 'selected PDF replay differs from original manifest membership', ERRCODE = '23514';
  END IF;
 END LOOP;
 IF (jsonb_array_length(selected_) IS DISTINCT FROM (SELECT count(DISTINCT (selected_replay.value ->> 'path')) AS count_1 
FROM jsonb_array_elements(selected_) AS selected_replay(value))) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF spool contributor repeats a selected path', ERRCODE = 'P0001';
 END IF;
 manifest_ := encode(sha256(p_manifest), 'hex');
 selection_ := encode(sha256(p_selected), 'hex');
 id_ := encode(sha256(convert_to(CAST(jsonb_build_array(p_build, p_producer, manifest_, selection_) AS TEXT), 'UTF8')), 'hex');
 INSERT INTO ops.pdf_spool_contributor (contributor_id, build_id, producer_id, manifest_digest, selection_digest, manifest_bytes, selected_replays, adopter_attempt, adopter_holder) VALUES (id_, p_build, p_producer, manifest_, selection_, p_manifest, p_selected, p_attempt, p_holder) ON CONFLICT DO NOTHING;
 SELECT ops.pdf_spool_contributor.* 
FROM ops.pdf_spool_contributor 
WHERE ops.pdf_spool_contributor.contributor_id = id_ INTO STRICT prior;
 IF (prior.manifest_bytes IS DISTINCT FROM p_manifest OR prior.selected_replays IS DISTINCT FROM p_selected) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF contributor replay differs', ERRCODE = 'P0001';
 END IF;
 RETURN id_;
END

