DECLARE
 owner record;
 original_digest text;
 recipe_digest_ text;
BEGIN
 SELECT anon_1.project_id, anon_1.release_id, anon_1.request_id, anon_1.generation, anon_1.document_id, anon_1.source_digest 
FROM ops.require_pdf_stage_owner(p_task, p_attempt, p_holder) AS anon_1 INTO STRICT owner;
 PERFORM ops.require_pdf_operation(owner.release_id, 'retain_pdf_original');
 IF (p_original IS NULL OR substr(p_original, 1, 5) != convert_to('%PDF-', 'UTF8') OR p_recipe IS NULL OR octet_length(p_recipe) = 0) THEN
  RAISE EXCEPTION USING MESSAGE = 'original PDF or recipe bytes unavailable', ERRCODE = '23514';
 END IF;
 PERFORM CAST(convert_from(p_recipe, 'UTF8') AS JSONB);
 original_digest := encode(sha256(p_original), 'hex');
 recipe_digest_ := encode(sha256(p_recipe), 'hex');
 IF (original_digest IS DISTINCT FROM owner.source_digest) THEN
  RAISE EXCEPTION USING MESSAGE = 'original PDF differs from exact document custody', ERRCODE = '23514';
 END IF;
 INSERT INTO kb.source_artifact (artifact_digest, content) VALUES (original_digest, p_original), (recipe_digest_, p_recipe) ON CONFLICT DO NOTHING;
 IF (NOT (EXISTS (SELECT 1 
FROM kb.source_artifact 
WHERE kb.source_artifact.artifact_digest = original_digest AND kb.source_artifact.content = p_original)) OR NOT (EXISTS (SELECT 1 
FROM kb.source_artifact 
WHERE kb.source_artifact.artifact_digest = recipe_digest_ AND kb.source_artifact.content = p_recipe))) THEN
  RAISE EXCEPTION USING MESSAGE = 'original PDF or recipe artifact digest conflict', ERRCODE = '23514';
 END IF;
 INSERT INTO ops.source_build (task_id, release_id, artifact_digest, recipe_digest) VALUES (p_task, owner.release_id, original_digest, recipe_digest_) ON CONFLICT DO NOTHING;
 IF (NOT (EXISTS (SELECT 1 
FROM ops.source_build 
WHERE ops.source_build.task_id = p_task AND ops.source_build.release_id = owner.release_id AND ops.source_build.artifact_digest = original_digest AND ops.source_build.recipe_digest = recipe_digest_))) THEN
  RAISE EXCEPTION USING MESSAGE = 'original PDF source build replay differs', ERRCODE = '23514';
 END IF;
 RETURN original_digest;
END

