DECLARE
 b ops.pdf_stage_build%ROWTYPE;
 v ops.pdf_build_validation%ROWTYPE;
 prior ops.pdf_published_revision%ROWTYPE;
 kind_ text;
BEGIN
 PERFORM ops.require_pdf_stage_owner(p_task, p_attempt, p_holder);
 PERFORM 1 AS anon_1 
FROM ops.pdf_stage_build 
WHERE ops.pdf_stage_build.build_id = p_build FOR NO KEY UPDATE;
 b := ops.require_pdf_frozen(p_build, p_task, p_attempt, p_holder, p_frozen);
 SELECT ops.pdf_published_revision.build_id, ops.pdf_published_revision.task_id, ops.pdf_published_revision.product_key, ops.pdf_published_revision.logical_digest, ops.pdf_published_revision.release_id, ops.pdf_published_revision.source_digest, ops.pdf_published_revision.schema_digest, ops.pdf_published_revision.recipe_digest, ops.pdf_published_revision.frozen_digest, ops.pdf_published_revision.kind 
FROM ops.pdf_published_revision 
WHERE ops.pdf_published_revision.build_id = p_build INTO prior;
 IF (found) THEN
  IF (prior.product_key IS DISTINCT FROM p_key) THEN
   RAISE EXCEPTION USING MESSAGE = 'published key replay differs', ERRCODE = 'P0001';
  END IF;
  RETURN QUERY SELECT prior.build_id, prior.task_id, prior.product_key, prior.logical_digest, prior.release_id, prior.source_digest, prior.schema_digest, prior.recipe_digest, prior.frozen_digest, prior.kind;
  RETURN;
 END IF;
 PERFORM ops.require_pdf_operation(b.release_id, 'seal_pdf_build');
 SELECT anon_1.build_id, anon_1.frozen_digest, anon_1.logical_digest, anon_1.contract_digest, anon_1.native_callbacks, anon_1.native_contract_digest, anon_1.certification_basis, anon_1.lowering_identity, anon_1.attested_logical_digest, anon_1.native_document_digest, anon_1.oracle_receipt_id 
FROM ops.lookup_pdf_validation(p_build, p_task, p_attempt, p_holder, p_frozen) AS anon_1 INTO STRICT v;
 IF (p_key IS NULL OR p_key = '') THEN
  RAISE EXCEPTION USING MESSAGE = 'empty PDF product key', ERRCODE = 'P0001';
 END IF;
 SELECT ops.pdf_frozen_build.kind 
FROM ops.pdf_frozen_build 
WHERE ops.pdf_frozen_build.build_id = p_build INTO STRICT kind_;
 IF (kind_ = 'integrated' AND (NOT (EXISTS (SELECT 1 
FROM kb.pdf_record_companion 
WHERE kb.pdf_record_companion.product_id = p_build AND kb.pdf_record_companion.family = 'input')) OR NOT (EXISTS (SELECT 1 
FROM kb.pdf_record_companion 
WHERE kb.pdf_record_companion.product_id = p_build AND kb.pdf_record_companion.family = 'coverage')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'integrated publication lacks input/coverage inventory', ERRCODE = '23514';
 END IF;
 INSERT INTO ops.pdf_product (task_id, product_key, content_digest, kind, artifact_digest, release_id, contract_digest) VALUES (p_task, p_key, v.logical_digest, kind_, b.source_digest, b.release_id, v.contract_digest);
 INSERT INTO ops.pdf_product_input (task_id, product_key, input_index, role, input_task_id, input_product_key, input_content_digest) SELECT p_task, p_key, CAST(kb.pdf_record_companion.local_id AS BIGINT) AS local_id, kb.pdf_record_companion.body ->> 'role' AS anon_1, CAST(kb.pdf_record_companion.body ->> 'task_id' AS BIGINT) AS anon_2, kb.pdf_record_companion.body ->> 'product_key' AS anon_3, kb.pdf_record_companion.body ->> 'content_digest' AS anon_4 
FROM kb.pdf_record_companion 
WHERE kb.pdf_record_companion.product_id = p_build AND kb.pdf_record_companion.family = 'input';
 INSERT INTO kb.source_artifact (artifact_digest, content) SELECT b.schema_digest, ops.pdf_contract_input(b.release_id, 'implementation/pdf/docling-validation.schema.json') AS pdf_contract_input_1 ON CONFLICT DO NOTHING;
 INSERT INTO ops.pdf_product_artifact (task_id, product_key, artifact_digest) SELECT p_task, p_key, kb.source_artifact.artifact_digest 
FROM kb.source_artifact 
WHERE kb.source_artifact.artifact_digest IN (b.source_digest, b.schema_digest, b.recipe_digest);
 INSERT INTO ops.pdf_published_revision (build_id, task_id, product_key, logical_digest, release_id, source_digest, schema_digest, recipe_digest, frozen_digest, kind) VALUES (p_build, p_task, p_key, v.logical_digest, b.release_id, b.source_digest, b.schema_digest, b.recipe_digest, p_frozen, kind_) RETURNING ops.pdf_published_revision.build_id, ops.pdf_published_revision.task_id, ops.pdf_published_revision.product_key, ops.pdf_published_revision.logical_digest, ops.pdf_published_revision.release_id, ops.pdf_published_revision.source_digest, ops.pdf_published_revision.schema_digest, ops.pdf_published_revision.recipe_digest, ops.pdf_published_revision.frozen_digest, ops.pdf_published_revision.kind INTO prior;
 UPDATE ops.pdf_stage_build SET state='published' WHERE ops.pdf_stage_build.build_id = p_build;
 RETURN QUERY SELECT prior.build_id, prior.task_id, prior.product_key, prior.logical_digest, prior.release_id, prior.source_digest, prior.schema_digest, prior.recipe_digest, prior.frozen_digest, prior.kind;
END

