DECLARE
 b ops.pdf_stage_build%ROWTYPE;
 row_ jsonb;
 body_ jsonb;
 family_ text;
 owned_ jsonb;
 access_ ops.pdf_stage_access%ROWTYPE;
 region_ ops.pdf_stage_region%ROWTYPE;
BEGIN
 b := ops.require_pdf_build(p_build, p_task, p_attempt, p_holder);
 PERFORM ops.require_pdf_operation(b.release_id, 'stage_pdf_producer');
 IF (jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows) > 128 OR octet_length(CAST(p_rows AS TEXT)) > 16777216) THEN
  RAISE EXCEPTION USING MESSAGE = 'access projection batch exceeds profile', ERRCODE = 'P0001';
 END IF;
 FOR row_ IN SELECT anon_1.value 
FROM jsonb_array_elements(p_rows) AS anon_1 LOOP
  family_ := row_ ->> 'family';
  body_ := row_['body'];
  owned_ := body_ || jsonb_build_object('product_id', p_build, 'revision_id', p_build);
  IF (family_ = 'access') THEN
   access_ := pg_catalog.jsonb_populate_record(CAST(NULL AS ops.pdf_stage_access), owned_);
   INSERT INTO ops.pdf_stage_access (product_id, revision_id, pointer, ordinal, label, parent_pointer, section_pointer, content_layer, text, native_json) VALUES (access_.product_id, access_.revision_id, access_.pointer, access_.ordinal, access_.label, access_.parent_pointer, access_.section_pointer, access_.content_layer, access_.text, access_.native_json) ON CONFLICT DO NOTHING;
   IF (NOT (EXISTS (SELECT 1 
FROM ops.pdf_stage_access AS r 
WHERE r.product_id = p_build AND r.revision_id = p_build AND r.pointer = (body_ ->> 'pointer') AND (to_jsonb(r) - 'product_id') - 'revision_id' = body_))) THEN
    RAISE EXCEPTION USING MESSAGE = 'changed access projection', ERRCODE = '23514';
   END IF;
  ELSE
   IF (family_ = 'region') THEN
    region_ := pg_catalog.jsonb_populate_record(CAST(NULL AS ops.pdf_stage_region), owned_);
    INSERT INTO ops.pdf_stage_region (product_id, revision_id, pointer, region_index, page_no, page_width, page_height, "left", top, "right", bottom, origin) VALUES (region_.product_id, region_.revision_id, region_.pointer, region_.region_index, region_.page_no, region_.page_width, region_.page_height, region_."left", region_.top, region_."right", region_.bottom, region_.origin) ON CONFLICT DO NOTHING;
    IF (NOT (EXISTS (SELECT 1 
FROM ops.pdf_stage_region AS r 
WHERE r.product_id = p_build AND r.revision_id = p_build AND r.pointer = (body_ ->> 'pointer') AND (to_jsonb(r) - 'product_id') - 'revision_id' = body_ AND r.region_index = CAST((body_ ->> 'region_index') AS BIGINT)))) THEN
     RAISE EXCEPTION USING MESSAGE = 'changed region projection', ERRCODE = '23514';
    END IF;
   ELSE
    RAISE EXCEPTION USING MESSAGE = 'invalid projection family', ERRCODE = 'P0001';
   END IF;
  END IF;
 END LOOP;
END

