DECLARE
 b ops.pdf_stage_build%ROWTYPE;
 logical_ text;
 contract_ text;
 certification_ record;
 prior_validation ops.pdf_build_validation%ROWTYPE;
BEGIN
 IF (NOT (current_setting('transaction_isolation') = ANY (ARRAY['read committed']))) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF projection admission requires READ COMMITTED', ERRCODE = '25000';
 END IF;
 IF (EXISTS (SELECT 1 
FROM ops.pdf_validation_check 
WHERE ops.pdf_validation_check.build_id = p_build AND ops.pdf_validation_check.check_name = 'seal')) THEN
  PERFORM ops.require_pdf_stage_owner(p_task, p_attempt, p_holder);
 END IF;
 PERFORM 1 AS anon_1 
FROM ops.pdf_stage_build 
WHERE ops.pdf_stage_build.build_id = p_build FOR NO KEY UPDATE;
 b := ops.require_pdf_frozen(p_build, p_task, p_attempt, p_holder, p_frozen);
 PERFORM ops.require_pdf_operation(b.release_id, 'validate_pdf_build');
 SELECT anon_1.build_id, anon_1.frozen_digest, anon_1.logical_digest, anon_1.contract_digest, anon_1.native_callbacks, anon_1.native_contract_digest, anon_1.certification_basis, anon_1.lowering_identity, anon_1.attested_logical_digest, anon_1.native_document_digest, anon_1.oracle_receipt_id 
FROM ops.lookup_pdf_validation(p_build, p_task, p_attempt, p_holder, p_frozen) AS anon_1 INTO prior_validation;
 IF (found) THEN
  RETURN QUERY SELECT prior_validation.build_id, prior_validation.frozen_digest, prior_validation.logical_digest, prior_validation.contract_digest, prior_validation.native_callbacks, prior_validation.native_contract_digest, prior_validation.certification_basis, prior_validation.lowering_identity, prior_validation.attested_logical_digest, prior_validation.native_document_digest, prior_validation.oracle_receipt_id;
  RETURN;
 END IF;
 SELECT anon_1.lowering_identity, anon_1.kind, anon_1.logical_digest, anon_1.native_document_digest, anon_1.oracle_receipt_id, anon_1.certification_basis 
FROM ops.read_pdf_certification_requirement(p_build, p_task, p_attempt, p_holder, p_frozen) AS anon_1 INTO STRICT certification_;
 IF (certification_.oracle_receipt_id IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF lowering has no passed round-trip oracle', ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM ops.pdf_validation_check 
WHERE ops.pdf_validation_check.build_id = p_build AND ops.pdf_validation_check.check_name = 'seal')) THEN
  SELECT max(ops.pdf_validation_check.result_digest) FILTER (WHERE ops.pdf_validation_check.check_name = 'identity') AS anon_1, max(ops.pdf_validation_check.result_digest) FILTER (WHERE ops.pdf_validation_check.check_name = 'projection') AS anon_2 
FROM ops.pdf_validation_check 
WHERE ops.pdf_validation_check.build_id = p_build AND ops.pdf_validation_check.attempt = p_attempt AND ops.pdf_validation_check.holder = p_holder AND ops.pdf_validation_check.frozen_digest = p_frozen AND ops.pdf_validation_check.contract_digest = ops.pdf_validation_contract(b.release_id) 
HAVING count(*) = 5 INTO logical_, contract_;
  IF (logical_ IS NULL OR contract_ IS NULL) THEN
   RAISE EXCEPTION USING MESSAGE = 'incomplete frozen PDF validation checks', ERRCODE = '23514';
  END IF;
 ELSE
  PERFORM ops.pdf_check_build_inventory(p_build, b.source_digest, (SELECT anon_1.project_id 
FROM ops.pdf_task_context(b.task_id) AS anon_1));
  PERFORM ops.pdf_check_access_correspondence(p_build);
  logical_ := ops.pdf_record_logical_identity(p_build, p_build);
  contract_ := ops.pdf_projection_contract(p_build, b.release_id);
 END IF;
 PERFORM ops.require_pdf_frozen(p_build, p_task, p_attempt, p_holder, p_frozen);
 IF (ops.pdf_producer_stream_identity(p_build, b.schema_digest) IS DISTINCT FROM (SELECT ops.pdf_producer_certification.stream_inventory_digest 
FROM ops.pdf_producer_certification 
WHERE ops.pdf_producer_certification.build_id = p_build)) THEN
  RAISE EXCEPTION USING MESSAGE = 'stored PDF stream roots differ from producer attestation', ERRCODE = '23514';
 END IF;
 IF (logical_ IS DISTINCT FROM certification_.logical_digest) THEN
  RAISE EXCEPTION USING MESSAGE = 'stored PDF identity differs from producer attestation', ERRCODE = '23514';
 END IF;
 INSERT INTO ops.pdf_build_validation (build_id, frozen_digest, logical_digest, contract_digest, native_callbacks, native_contract_digest, certification_basis, lowering_identity, attested_logical_digest, native_document_digest, oracle_receipt_id) VALUES (p_build, p_frozen, logical_, contract_, true, ops.pdf_validation_contract(b.release_id), certification_.certification_basis, certification_.lowering_identity, certification_.logical_digest, certification_.native_document_digest, certification_.oracle_receipt_id) ON CONFLICT DO NOTHING;
 IF (NOT (EXISTS (SELECT 1 
FROM ops.pdf_build_validation 
WHERE ops.pdf_build_validation.build_id = p_build AND ops.pdf_build_validation.frozen_digest = p_frozen AND ops.pdf_build_validation.logical_digest = logical_ AND ops.pdf_build_validation.contract_digest = contract_ AND ops.pdf_build_validation.native_contract_digest = ops.pdf_validation_contract(b.release_id) AND ops.pdf_build_validation.native_callbacks))) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF validation result differs for frozen premises', ERRCODE = '23514';
 END IF;
 RETURN QUERY SELECT ops.pdf_build_validation.build_id, ops.pdf_build_validation.frozen_digest, ops.pdf_build_validation.logical_digest, ops.pdf_build_validation.contract_digest, ops.pdf_build_validation.native_callbacks, ops.pdf_build_validation.native_contract_digest, ops.pdf_build_validation.certification_basis, ops.pdf_build_validation.lowering_identity, ops.pdf_build_validation.attested_logical_digest, ops.pdf_build_validation.native_document_digest, ops.pdf_build_validation.oracle_receipt_id 
FROM ops.pdf_build_validation 
WHERE ops.pdf_build_validation.build_id = p_build AND ops.pdf_build_validation.frozen_digest = p_frozen AND ops.pdf_build_validation.contract_digest = contract_;
END

