HAVING count(*) != 1)) THEN
  RAISE EXCEPTION USING MESSAGE = 'duplicate approved effect owner', ERRCODE = '23514';
 END IF;
 FOR approved IN SELECT approved_effect.value 
FROM jsonb_array_elements(payload['grants']) AS approved_effect(value) LOOP
  IF (NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = (payload ->> 'release_id') AND sem.data_operation_definition.operation_id = (approved ->> 'operation_id') AND sem.data_operation_definition.definition_identity = (approved ->> 'definition_identity') AND sem.data_operation_definition.support_contract['effects'] = jsonb_build_array(approved['contract']) AND ((approved['contract']) ->> 'name') = (approved ->> 'effect') AND ops.ddo_privileged_effect_eligible(data_operation_definition, approved ->> 'effect')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'effect approval differs from its exact admitted definition', ERRCODE = '23514';
  END IF;
  INSERT INTO sem.data_operation_effect_grant (release_id, operation_id, definition_identity, effect, contract) VALUES ((payload ->> 'release_id'), (approved ->> 'operation_id'), (approved ->> 'definition_identity'), (approved ->> 'effect'), (approved['contract'])) ON CONFLICT DO NOTHING;
  IF (NOT (EXISTS (SELECT 1 
FROM sem.data_operation_effect_grant 
WHERE sem.data_operation_effect_grant.release_id IS NOT DISTINCT FROM (payload ->> 'release_id') AND sem.data_operation_effect_grant.operation_id IS NOT DISTINCT FROM (approved ->> 'operation_id') AND sem.data_operation_effect_grant.definition_identity IS NOT DISTINCT FROM (approved ->> 'definition_identity') AND sem.data_operation_effect_grant.effect IS NOT DISTINCT FROM (approved ->> 'effect') AND sem.data_operation_effect_grant.contract IS NOT DISTINCT FROM approved['contract']))) THEN
   RAISE EXCEPTION USING MESSAGE = 'effect grant changed under its admitted identity', ERRCODE = '23514';
  END IF;
 END LOOP;
 RETURN payload ->> 'release_id';
END

