_stage_membership.arrow","sha256":"c738995d5369b576fabe732e3f9e212461d98e3072115db8d311d15beb1afd8f"},{"name":"pdf-domain/implementation/pdf/lowering/codec/ops.pdf_stage_native.arrow","sha256":"ac25de74ff0a117f2b098f040fad912a344496d4d06863773a5c6a8b8ee292b8"},{"name":"pdf-domain/implementation/pdf/lowering/codec/ops.pdf_stage_reference.arrow","sha256":"f42f4999f33387e1dcefb4d11b357becda2974ad038b975a859b4a4a4b029f3c"},{"name":"pdf-domain/analysis/libraries.json","sha256":"f4cd9fdaed1a86181814ffdf784d6f55a3b5b5344288a7782e28c0958c076984"},{"name":"pdf-domain/schema/pdf_products","sha256":"e4787e8e36389c6e1a190d9611e662f2a4a706675f7eddea0c23d64a84e9e7cc"},{"name":"pdf-domain/schema/pdf-observation-vocabulary","sha256":"c460ea2b7c71490b2599e3f647893d1b40daedaea89410996941269ba12b8f71"},{"name":"pdf-domain/schema/pdf_observation_meaning","sha256":"1727e9623479e65afdb4b9b01ecea02c35bb52c58c0e15a82b42ed3f29c03c73"},{"name":"pdf-domain/schema/core","sha256":"dbc48b38f4d1630c48310ad78578a2ce3b42050d96262c219bde42db5496bda2"},{"name":"pdf-domain/schema/pdf_domain_schema","sha256":"697d52f38f0feb258511187fb8d8b209dc37fcc1ba52e82282dfcc93d503bdbd"},{"name":"pdf-domain/implementation/pdf/staging-model.yaml","sha256":"f26e45ac615b0fb9373b318d0fd8d9919613d9f332b1519be4424b5e07889383"},{"name":"pdf-domain/implementation/pdf/docling-validation.schema.json","sha256":"91d32d744d82f331889fa673b933b856add9153a1512aae6ff48ca1fc0217b9c"},{"name":"pdf-domain/native/data-operation-protocol.yaml","sha256":"a9aedeb6c6af927db1af5913ea44cff863392d1e40c9cf225b5877ebd4c7b742"}]' AS JSONB))) IS DISTINCT FROM true) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF domain contract differs', ERRCODE = '23514';
 END IF;
 IF (NOT (EXISTS (SELECT sem.data_operation_definition.release_id 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = p_release AND ((sem.data_operation_definition.support_contract['capabilities']) ->> 'preparation') = 'pdf-native' AND (EXISTS (SELECT anon_1.value 
FROM jsonb_array_elements(sem.data_operation_definition.support_contract['assets']) AS anon_1 
WHERE (anon_1.value ->> 'reference') = 'pdf-domain/contract.json' AND (anon_1.value ->> 'contract') = 'pdf-native/helper-bindings' AND (anon_1.value ->> 'role') = 'native-pdf-helper-bindings' AND (anon_1.value ->> 'content_digest') = facet_digest))))) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF action/capability correspondence differs', ERRCODE = '23514';
 END IF;
 FOR input_ IN SELECT anon_1.value 
FROM jsonb_array_elements(facet['inputs']) AS anon_1 LOOP
  IF (NOT (EXISTS (SELECT sem.input.input_name 
FROM sem.input 
WHERE sem.input.release_id = p_release AND sem.input.input_kind = 'dependency' AND sem.input.input_name = (input_ ->> 'name') AND sem.input.content_digest = (input_ ->> 'sha256') AND encode(sha256(sem.input.content), 'hex') = sem.input.content_digest))) THEN
   RAISE EXCEPTION USING MESSAGE = 'PDF domain input differs from retained contract', ERRCODE = '23514';
  END IF;
 END LOOP;
 FOR action_id, action_value IN SELECT anon_1.key, anon_1.value 
FROM jsonb_each(facet['actions']) AS anon_1 LOOP
  IF (((action_value['contract']) ->> 'id') IS DISTINCT FROM action_id) THEN
   RAISE EXCEPTION USING MESSAGE = 'PDF action contract identity differs', ERRCODE = '23514';
  END IF;
  INSERT INTO sem.pdf_operation_contract (release_id, operation_id, contract_id, contract_digest) VALUES (p_release, action_id, action_id, facet_digest) ON CONFLICT DO NOTHING;
  IF (NOT (EXISTS (SELECT sem.pdf_operation_contract.contract_digest 
FROM sem.pdf_operation_contract 
WHERE sem.pdf_operation_contract.release_id = p_release AND sem.pdf_operation_contract.operation_id = action_id AND sem.pdf_operation_contract.contract_id = action_id AND sem.pdf_operation_contract.contract_digest = facet_digest))) THEN
   RAISE EXCEPTION USING MESSAGE = 'PDF action changed under admitted release', ERRCODE = '23514';
  END IF;
 END LOOP;
END$$

