DECLARE
 p jsonb := p_payload;
 k jsonb;
 o jsonb;
 archived jsonb;
 operation jsonb;
 expected_inputs jsonb;
 expected_outputs jsonb;
 expected_support jsonb;
 subject_ jsonb;
 provider_profile jsonb;
 old sem.data_kind_contract%ROWTYPE;
 lowered sem.data_operation_definition%ROWTYPE;
 header sem.data_operation_release%ROWTYPE;
BEGIN
 PERFORM ops.ddo_fields(p, ARRAY['release_id', 'model_digest', 'native_digest', 'kinds', 'operations']);
 IF (p_new_release AND (p ->> 'native_digest') IS DISTINCT FROM (sem.data_operation_native_descriptor() ->> 'source_digest')) THEN
  RAISE EXCEPTION USING MESSAGE = 'native source correspondence mismatch', ERRCODE = 'P0001';
 END IF;
 SELECT CAST(convert_from(sem.artifact.content, 'UTF8') AS JSONB) AS convert_from_1 
FROM sem.artifact 
WHERE sem.artifact.release_id = (p ->> 'release_id') AND sem.artifact.artifact_name = 'data_operations.json' AND encode(sha256(sem.artifact.content), 'hex') = (p ->> 'model_digest') INTO archived;
 IF (archived IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'effective operation archive is absent or differs', ERRCODE = 'P0001';
 END IF;
 IF (jsonb_typeof(archived['subject_definitions']) IS DISTINCT FROM 'array' OR (EXISTS (SELECT 1 
FROM jsonb_array_elements(archived['subject_definitions']) AS subjects(value) 
WHERE nullif((subjects.value ->> 'semantic_id'), '') IS NULL OR NOT ((CAST('["invocation","original-document","original-source","project","selected-source-set"]' AS JSONB) ? (subjects.value ->> 'scope'))))) OR (EXISTS (SELECT (subjects.value ->> 'semantic_id') AS anon_1 
FROM jsonb_array_elements(archived['subject_definitions']) AS subjects(value) GROUP BY (subjects.value ->> 'semantic_id') 
HAVING count(*) != 1))) THEN
  RAISE EXCEPTION USING MESSAGE = 'release subject definitions are unavailable or invalid', ERRCODE = '23514';
 END IF;
 IF (NOT (EXISTS (SELECT 1 
FROM sem.artifact 
WHERE sem.artifact.release_id = (p ->> 'release_id') AND sem.artifact.artifact_name = 'data_operation_native_definitions.json' AND CAST(convert_from(sem.artifact.content, 'UTF8') AS JSONB) = (p - 'release_id')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'native definition projection differs from authenticated release artifact', ERRCODE = 'P0001';
 END IF;
 FOR k IN SELECT kind_rows.value 
FROM jsonb_array_elements(p['kinds']) AS kind_rows(value) LOOP
  IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(archived['kinds']) AS archive_kinds(value) 
WHERE (archive_kinds.value ->> 'semantic_id') = (k ->> 'kind') AND coalesce(((archive_kinds.value['facts']['json']) ->> 'universe'), 'ordinary') = (k ->> 'universe') AND coalesce(archive_kinds.value['facts']['json']['projection_families'], CAST('[]' AS JSONB)) = k['families']))) THEN
   RAISE EXCEPTION USING MESSAGE = 'kind purpose/projection policy differs from archived facts', ERRCODE = 'P0001';
  END IF;
  IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(archived['identities']) AS archive_identities(value) 
WHERE (archive_identities.value ->> 'owner') = (k ->> 'kind') AND (archive_identities.value ->> 'domain') = 'kind' AND (archive_identities.value ->> 'key') = (k ->> 'kind_contract')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'kind identity differs from archived effective model', ERRCODE = 'P0001';
  END IF;
  INSERT INTO sem.data_kind_contract (kind_contract, kind, body_schema, meaning_schema, member_schema, member_contracts, families, universe) VALUES ((k ->> 'kind_contract'), (k ->> 'kind'), (k['body_schema']), (k['meaning_schema']), (k['member_schema']), (k['member_contracts']), (k['families']), (k ->> 'universe')) ON CONFLICT DO NOTHING;
  SELECT sem.data_kind_contract.* 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = (k ->> 'kind_contract') INTO STRICT old;
  IF (old.kind IS DISTINCT FROM (k ->> 'kind') OR old.universe IS DISTINCT FROM (k ->> 'universe') OR old.body_schema IS DISTINCT FROM k['body_schema'] OR old.meaning_schema IS DISTINCT FROM k['meaning_schema'] OR old.member_schema IS DISTINCT FROM k['member_schema'] OR old.member_contracts IS DISTINCT FROM k['member_contracts'] OR old.families IS DISTINCT FROM k['families']) THEN
   RAISE EXCEPTION USING MESSAGE = 'kind contract changed under stable identity', ERRCODE = 'P0001';
  END IF;
  INSERT INTO sem.data_kind_release (release_id, kind_contract) VALUES ((p ->> 'release_id'), old.kind_contract) ON CONFLICT DO NOTHING;
 END LOOP;
 FOR o IN SELECT operation_rows.value 
FROM jsonb_array_elements(p['operations']) AS operation_rows(value) LOOP
  SELECT archive_operations.value 
FROM jsonb_array_elements(archived['operations']) AS archive_operations(value) 
WHERE (archive_operations.value ->> 'semantic_id') = (o ->> 'operation_id') INTO STRICT operation;
  PERFORM ops.ddo_replicate_required(operation ->> 'replicate_policy');
  IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(archived['subject_definitions']) AS subjects(value) 
WHERE (subjects.value ->> 'semantic_id') = (operation ->> 'subject')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'operation subject has no admitted definition', ERRCODE = 'P0001';
  END IF;
  SELECT coalesce(jsonb_agg(roles.value || jsonb_build_object('kind_contract', (SELECT (role_identities.value ->> 'key') AS anon_1 
FROM jsonb_array_elements(archived['identities']) AS role_identities(value) 
WHERE (role_identities.value ->> 'owner') = (roles.value ->> 'kind') AND (role_identities.value ->> 'domain') = 'kind'), 'identity_requirements', coalesce(roles.value['support']['identity_requirements'], CAST('[]' AS JSONB))) || jsonb_build_object('accepted_kind_contracts', sem.ddo_input_kind_contracts(archived, (roles.value ->> 'kind'))) ORDER BY roles.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(operation['roles']) WITH ORDINALITY AS roles(value, ordinal) 
WHERE (roles.value ->> 'direction') = 'input' INTO expected_inputs;
  SELECT coalesce(jsonb_agg(roles.value || jsonb_build_object('kind_contract', (SELECT (role_identities.value ->> 'key') AS anon_1 
FROM jsonb_array_elements(archived['identities']) AS role_identities(value) 
WHERE (role_identities.value ->> 'owner') = (roles.value ->> 'kind') AND (role_identities.value ->> 'domain') = 'kind'), 'identity_requirements', coalesce(roles.value['support']['identity_requirements'], CAST('[]' AS JSONB))) ORDER BY roles.ordinal), CAST('[]' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(operation['roles']) WITH ORDINALITY AS roles(value, ordinal) 
WHERE (roles.value ->> 'direction') = 'output' INTO expected_outputs;
  expected_support := jsonb_build_object('policy', operation['support_policy'], 'coverage', operation['coverage'], 'outcomes', operation['outcomes'], 'replicate_policy', operation['replicate_policy'], 'state_dimensions', operation['state_dimensions'], 'transitions', operation['transitions'], 'effects', operation['effects'], 'capabilities', operation['capabilities'], 'provenance', CASE WHEN (EXISTS (SELECT 1 
FROM jsonb_array_elements(operation['roles']) AS support_roles(value) 
WHERE support_roles.value['support'] != CAST('null' AS JSONB) AND ((support_roles.value['support']) ->> 'provenance') != 'value_substitution')) THEN 'exact' ELSE 'value_substitution' END, 'reuse_eligible', NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(operation['assets']) AS reuse_assets(value) 
WHERE (reuse_assets.value ->> 'reuse_eligible') = 'false')), 'assets', operation['assets'], 'numerical_policy', operation['numerical_policy'], 'result_fields', (SELECT coalesce(jsonb_object_agg(result_fields.value ->> 0, result_fields.value ->> 1), CAST('{}' AS JSONB)) AS coalesce_1 
FROM jsonb_array_elements(coalesce(operation['result_fields'], CAST('[]' AS JSONB))) AS result_fields(value)));
  provider_profile := sem.ddo_provider_profile(p ->> 'release_id', operation);
  IF (provider_profile IS NOT NULL) THEN
   expected_support := expected_support || jsonb_build_object('provider_profile', provider_profile);
  END IF;
  IF (operation['external'] IS NOT NULL) THEN
   expected_support := expected_support || jsonb_build_object('external', operation['external']);
  END IF;
  IF (coalesce(operation['output_witnesses'], CAST('[]' AS JSONB)) != CAST('[]' AS JSONB)) THEN
   expected_support := expected_support || jsonb_build_object('output_witnesses', operation['output_witnesses']);
  END IF;
  IF (EXISTS (SELECT 1 
FROM jsonb_array_elements(operation['validity']['families']) AS claimed_family(value) 
WHERE ((value #>> ARRAY[]::TEXT[]) NOT IN ('record-grade', 'record-fit', 'operation-event', 'contextual', 'definition', 'artifact', 'rich')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'operation claims a family without an installed ready validator', ERRCODE = 'P0001';
  END IF;
  IF (o['input_roles'] IS DISTINCT FROM expected_inputs OR o['output_roles'] IS DISTINCT FROM expected_outputs OR (o ->> 'subject_definition') IS DISTINCT FROM (operation ->> 'subject') OR o['support_contract'] IS DISTINCT FROM expected_support OR o['validity_families'] IS DISTINCT FROM operation['validity']['families'] OR o['validity_conservative'] IS DISTINCT FROM operation['validity']['conservative'] OR o['profile'] IS DISTINCT FROM operation['profile'] OR o['binding'] IS DISTINCT FROM (SELECT archive_bindings.value['expression'] AS anon_1 
FROM jsonb_array_elements(archived['bindings']) AS archive_bindings(value) 
WHERE (archive_bindings.value ->> 'semantic_id') = (operation ->> 'binding')) OR (o ->> 'definition') IS DISTINCT FROM (SELECT (archive_identities.value ->> 'key') AS anon_2 
FROM jsonb_array_elements(archived['identities']) AS archive_identities(value) 
WHERE (archive_identities.value ->> 'owner') = (o ->> 'operation_id') AND (archive_identities.value ->> 'domain') = 'definition') OR (o ->> 'eligibility') IS DISTINCT FROM (SELECT (archive_identities.value ->> 'key') AS anon_3 
FROM jsonb_array_elements(archived['identities']) AS archive_identities(value) 
WHERE (archive_identities.value ->> 'owner') = (o ->> 'operation_id') AND (archive_identities.value ->> 'domain') = 'eligibility') OR (o ->> 'implementation_revision') IS DISTINCT FROM coalesce((SELECT (archive_identities.value ->> 'key') AS anon_4 
FROM jsonb_array_elements(archived['identities']) AS archive_identities(value) 
WHERE (archive_identities.value ->> 'owner') = (operation ->> 'implementation_root') AND (archive_identities.value ->> 'domain') = 'implementation-slice'), CASE WHEN (operation['external'] IS NULL) THEN (operation ->> 'behavior') ELSE 'external:' || (o ->> 'recipe') END)) THEN
   RAISE EXCEPTION USING MESSAGE = 'native definition projection disagrees with archived operation facts', ERRCODE = 'P0001';
  END IF;
  IF (NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(archived['identities']) AS archive_identities(value) 
WHERE (archive_identities.value ->> 'owner') = (o ->> 'operation_id') AND (archive_identities.value ->> 'domain') = 'recipe' AND (archive_identities.value ->> 'key') = (o ->> 'recipe')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'recipe differs from archived effective model', ERRCODE = 'P0001';
  END IF;
  lowered := jsonb_populate_record(CAST(NULL AS sem.data_operation_definition), o || jsonb_build_object('release_id', (p ->> 'release_id'), 'binding_expression', o['binding'], 'parameter_definitions', coalesce(operation['parameters']['json'], CAST('{}' AS JSONB)), 'definition_identity', (o ->> 'definition'), 'eligibility_identity', (o ->> 'eligibility'), 'dependencies', jsonb_build_object('required', coalesce(operation['dependencies'], CAST('[]' AS JSONB)), 'potential', coalesce(operation['potential_dependencies'], CAST('[]' AS JSONB)))));
  lowered := jsonb_populate_record(lowered, jsonb_build_object('quantified', EXISTS (WITH RECURSIVE nodes(node) AS 
(SELECT o['binding'] AS node UNION ALL SELECT child_nodes.value AS value 
FROM nodes JOIN jsonb_array_elements(coalesce(nodes.node['children'], CAST('[]' AS JSONB))) AS child_nodes(value) ON true)
 SELECT 1 
FROM nodes 
WHERE (nodes.node ->> 'operator') IN ('forall', 'absent', 'membership', 'covers')), 'validity_families', operation['validity']['families'], 'validity_conservative', operation['validity']['conservative']));
  lowered := jsonb_populate_record(lowered, jsonb_build_object('command_class', ops.ddo_classify_command(lowered)));
  INSERT INTO sem.data_operation_definition (release_id, operation_id, subject_definition, recipe, profile, implementation_revision, input_roles, output_roles, support_contract, binding_expression, parameter_definitions, definition_identity, eligibility_identity, quantified, validity_families, validity_conservative, command_class, dependencies) SELECT lowered.release_id, lowered.operation_id, lowered.subject_definition, lowered.recipe, lowered.profile, lowered.implementation_revision, lowered.input_roles, lowered.output_roles, lowered.support_contract, lowered.binding_expression, lowered.parameter_definitions, lowered.definition_identity, lowered.eligibility_identity, lowered.quantified, lowered.validity_families, lowered.validity_conservative, lowered.command_class, lowered.dependencies ON CONFLICT DO NOTHING;
  IF (NOT p_new_release) THEN
   UPDATE sem.data_operation_definition SET binding_expression=lowered.binding_expression, parameter_definitions=lowered.parameter_definitions, definition_identity=lowered.definition_identity, eligibility_identity=lowered.eligibility_identity, quantified=lowered.quantified, validity_families=lowered.validity_families, validity_conservative=lowered.validity_conservative, command_class=lowered.command_class, dependencies=lowered.dependencies WHERE sem.data_operation_definition.release_id = lowered.release_id AND sem.data_operation_definition.operation_id = lowered.operation_id AND (sem.data_operation_definition.binding_expression, sem.data_operation_definition.parameter_definitions, sem.data_operation_definition.definition_identity, sem.data_operation_definition.eligibility_identity, sem.data_operation_definition.quantified, sem.data_operation_definition.validity_families, sem.data_operation_definition.validity_conservative, sem.data_operation_definition.command_class, sem.data_operation_definition.dependencies) IS DISTINCT FROM (lowered.binding_expression, lowered.parameter_definitions, lowered.definition_identity, lowered.eligibility_identity, lowered.quantified, lowered.validity_families, lowered.validity_conservative, lowered.command_class, lowered.dependencies);
  END IF;
  IF (NOT (EXISTS (SELECT 1 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = lowered.release_id AND sem.data_operation_definition.operation_id = lowered.operation_id AND to_jsonb(data_operation_definition) = to_jsonb(lowered)))) THEN
   RAISE EXCEPTION USING MESSAGE = 'operation definition changed under admitted release', ERRCODE = 'P0001';
  END IF;
  IF (EXISTS (SELECT 1 
FROM jsonb_array_elements(lowered.support_contract['effects']) AS granted_effect(value) 
WHERE (granted_effect.value ->> 'name') IN ('native-rich-knowledge-admission', 'native-evaluator-policy-authorization', 'native-evaluator-structural-admission', 'native-evaluator-operation-event-authorization') AND NOT ops.ddo_privileged_effect_eligible(lowered, granted_effect.value ->> 'name'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'privileged effect does not satisfy its closed integrity contract', ERRCODE = 'P0001';
  END IF;
 END LOOP;
 FOR subject_ IN SELECT subjects.value 
FROM jsonb_array_elements(archived['subject_definitions']) AS subjects(value) LOOP
  INSERT INTO sem.data_subject_scope (release_id, subject_definition, scope) VALUES ((p ->> 'release_id'), (subject_ ->> 'semantic_id'), (subject_ ->> 'scope')) ON CONFLICT DO NOTHING;
  IF (NOT (EXISTS (SELECT 1 
FROM sem.data_subject_scope 
WHERE sem.data_subject_scope.release_id = (p ->> 'release_id') AND sem.data_subject_scope.subject_definition = (subject_ ->> 'semantic_id') AND sem.data_subject_scope.scope = (subject_ ->> 'scope')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'subject scope changed under admitted release', ERRCODE = 'P0001';
  END IF;
 END LOOP;
 INSERT INTO sem.data_operation_release (release_id, model_digest, native_definitions_digest, native_kernel_digest, lowering_digest, binding_types) SELECT p ->> 'release_id' AS anon_1, p ->> 'model_digest' AS anon_2, sem.artifact.content_digest, p ->> 'native_digest' AS anon_3, sem.data_operation_native_descriptor() ->> 'lowering_digest' AS anon_4, archived['kinds'] AS anon_5 
FROM sem.artifact 
WHERE sem.artifact.release_id = (p ->> 'release_id') AND sem.artifact.artifact_name = 'data_operation_native_definitions.json' ON CONFLICT DO NOTHING;
 IF (NOT p_new_release) THEN
  UPDATE sem.data_operation_release SET lowering_digest=(sem.data_operation_native_descriptor() ->> 'lowering_digest'), binding_types=(archived['kinds']) WHERE sem.data_operation_release.release_id = (p ->> 'release_id') AND sem.data_operation_release.model_digest = (p ->> 'model_digest') AND sem.data_operation_release.native_kernel_digest = (p ->> 'native_digest') AND (sem.data_operation_release.lowering_digest IS DISTINCT FROM (sem.data_operation_native_descriptor() ->> 'lowering_digest') OR sem.data_operation_release.binding_types IS DISTINCT FROM archived['kinds']);
 END IF;
 SELECT sem.data_operation_release.* 
FROM sem.data_operation_release 
WHERE sem.data_operation_release.release_id = (p ->> 'release_id') INTO STRICT header;
 IF (header.model_digest IS DISTINCT FROM (p ->> 'model_digest') OR header.native_kernel_digest IS DISTINCT FROM (p ->> 'native_digest') OR header.lowering_digest IS DISTINCT FROM (sem.data_operation_native_descriptor() ->> 'lowering_digest') OR header.binding_types IS DISTINCT FROM archived['kinds'] OR header.native_definitions_digest IS DISTINCT FROM (SELECT sem.artifact.content_digest 
FROM sem.artifact 
WHERE sem.artifact.release_id = (p ->> 'release_id') AND sem.artifact.artifact_name = 'data_operation_native_definitions.json')) THEN
  RAISE EXCEPTION USING MESSAGE = 'release facts changed under admitted release', ERRCODE = 'P0001';
 END IF;
 PERFORM sem.admit_pdf_operation_contracts(p ->> 'release_id', p_new_release);
 RETURN jsonb_build_object('release_id', p ->> 'release_id', 'model_digest', p ->> 'model_digest');
END

