DECLARE
 asset jsonb;
 content_ bytea;
 profile jsonb;
BEGIN
 IF ((SELECT count(*) AS count_1 
FROM jsonb_array_elements(operation_['assets']) AS assets(value) 
WHERE (assets.value ->> 'role') = 'provider-inference-profile') = 0) THEN
  RETURN NULL;
 END IF;
 SELECT assets.value 
FROM jsonb_array_elements(operation_['assets']) AS assets(value) 
WHERE (assets.value ->> 'role') = 'provider-inference-profile' INTO STRICT asset;
 SELECT sem.input.content 
FROM sem.input 
WHERE sem.input.release_id = release_ AND sem.input.input_kind = 'dependency' AND sem.input.input_name = ('data-operations/contracts/' || (asset ->> 'contract')) INTO STRICT content_;
 IF (encode(sha256(content_), 'hex') IS DISTINCT FROM (asset ->> 'content_digest')) THEN
  RAISE EXCEPTION USING MESSAGE = 'provider profile captured digest differs', ERRCODE = 'P0001';
 END IF;
 profile := CAST(convert_from(content_, 'UTF8') AS JSONB);
 PERFORM ops.ddo_fields(profile, ARRAY['version', 'identity', 'meaning']);
 IF ((profile ->> 'version') IS DISTINCT FROM 'provider-inference-profile-v1' OR profile['meaning'][0] IS DISTINCT FROM CAST('"ddo"' AS JSONB) OR profile['meaning'][1] IS DISTINCT FROM CAST('"inference"' AS JSONB) OR profile['meaning'][2] IS DISTINCT FROM CAST('"1"' AS JSONB) OR jsonb_array_length(profile['meaning']) IS DISTINCT FROM 4 OR data.ddo_identity('inference', profile['meaning'][3]) IS DISTINCT FROM (profile ->> 'identity') OR content_ IS DISTINCT FROM convert_to(data.canonical_json(profile), 'UTF8')) THEN
  RAISE EXCEPTION USING MESSAGE = 'provider profile canonical meaning differs', ERRCODE = 'P0001';
 END IF;
 RETURN profile || jsonb_build_object('contract', (asset ->> 'contract'), 'sha256', (asset ->> 'content_digest'));
END

