DECLARE
 semantic_fields jsonb;
 field jsonb;
BEGIN
 PERFORM ops.ddo_fields(attestation, ARRAY['version', 'identity', 'meaning', 'execution_identity', 'execution_meaning']);
 IF ((attestation ->> 'version') IS DISTINCT FROM 'provider-profile-attestation-v1' OR attestation['identity'] IS DISTINCT FROM profile['identity'] OR attestation['meaning'] IS DISTINCT FROM profile['meaning'] OR attestation['execution_meaning'][0] IS DISTINCT FROM CAST('"ddo"' AS JSONB) OR attestation['execution_meaning'][1] IS DISTINCT FROM CAST('"execution-profile"' AS JSONB) OR attestation['execution_meaning'][2] IS DISTINCT FROM CAST('"1"' AS JSONB) OR jsonb_array_length(attestation['execution_meaning']) IS DISTINCT FROM 4 OR data.ddo_identity('execution-profile', attestation['execution_meaning'][3]) IS DISTINCT FROM (attestation ->> 'execution_identity')) THEN
  RAISE EXCEPTION USING MESSAGE = 'provider execution attestation differs', ERRCODE = 'P0001';
 END IF;
 FOR field IN SELECT execution_fields.value 
FROM jsonb_array_elements(attestation['execution_meaning'][3][1]) AS execution_fields(value) LOOP
  IF ((data.ddo_field(field[1], 'role') ->> 1) IS NULL OR ((data.ddo_field(field[1], 'role') ->> 1) NOT IN ('semantic', 'execution'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'unknown provider projection field role', ERRCODE = 'P0001';
  END IF;
 END LOOP;
 SELECT jsonb_build_array('mapping', coalesce(jsonb_agg(jsonb_build_array(semantic_profile_fields.value[0], data.ddo_field(semantic_profile_fields.value[1], 'value')) ORDER BY (semantic_profile_fields.value ->> 0) COLLATE "C"), CAST('[]' AS JSONB))) AS jsonb_build_array_1 
FROM jsonb_array_elements(attestation['execution_meaning'][3][1]) AS semantic_profile_fields(value) 
