DECLARE
 replay boolean;
 archive_digest text;
BEGIN
 PERFORM sem.require_admission_caller();
 IF (nullif(p_release_id, '') IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'archive identity missing', ERRCODE = '23514';
 END IF;
