 IF ((SELECT coalesce(array_agg(CAST(pg_catalog.pg_class.relname AS TEXT) ORDER BY pg_catalog.pg_class.relname), ARRAY[]::TEXT[]) AS coalesce_1 
FROM pg_catalog.pg_class 
WHERE pg_catalog.pg_class.relnamespace = pg_my_temp_schema() AND left(pg_catalog.pg_class.relname, 11) = 'cs_archive_') IS DISTINCT FROM ARRAY['cs_archive_artifact', 'cs_archive_class_definition', 'cs_archive_class_hierarchy', 'cs_archive_conditional_atom', 'cs_archive_conditional_rule', 'cs_archive_identity_slot', 'cs_archive_input', 'cs_archive_metric_definition', 'cs_archive_operation_property_role', 'cs_archive_property_applicability', 'cs_archive_property_definition', 'cs_archive_registry_row', 'cs_archive_release', 'cs_archive_scientific_decision_rule', 'cs_archive_vocabulary_member']) THEN
  RAISE EXCEPTION USING MESSAGE = 'archive scratch relation set differs', ERRCODE = '23514';
 END IF;
