FROM pg_temp.cs_archive_release 
WHERE pg_temp.cs_archive_release.release_id IS DISTINCT FROM p_release_id)) OR (EXISTS (SELECT 1 
FROM pg_temp.cs_archive_release GROUP BY pg_temp.cs_archive_release.release_id 
HAVING count(*) != 1))) THEN
  RAISE EXCEPTION USING MESSAGE = 'archive row scope/key differs: release', ERRCODE = '23514';
 END IF;
 IF ((SELECT count(*) AS count_1 
FROM pg_temp.cs_archive_release) != 1) THEN
  RAISE EXCEPTION USING MESSAGE = 'one complete release required', ERRCODE = '23514';
