DECLARE
 archived sem.release;
 document jsonb;
 manifest jsonb;
BEGIN
 SELECT sem.release.* 
FROM sem.release 
WHERE sem.release.release_id = r INTO STRICT archived;
 document := CAST(convert_from(archived.prepared_bytes, 'UTF8') AS JSONB);
 manifest := CAST(convert_from(archived.manifest_bytes, 'UTF8') AS JSONB);
 IF ((archived.profile NOT IN ('semantic-1', 'semantic-2')) OR (document ->> 'format') IS DISTINCT FROM 'semantic-release-archive-4' OR ((manifest['profile']) ->> 'compiler_version') IS DISTINCT FROM '25' OR archived.release_id != ('release:' || encode(sha256(archived.manifest_bytes), 'hex')) OR archived.content_digest != encode(sha256(archived.prepared_bytes), 'hex') OR ((document['products']) ->> 'release_id') IS DISTINCT FROM r OR ((manifest['profile']) ->> 'version') IS DISTINCT FROM archived.profile) THEN
  RAISE EXCEPTION USING MESSAGE = 'archive manifest identity differs', ERRCODE = '23514';
 END IF;
 IF (manifest['sources'] IS DISTINCT FROM (SELECT coalesce(jsonb_agg(jsonb_build_array(sem.input.input_name, sem.input.content_digest) ORDER BY sem.input.input_name), CAST('[]' AS JSONB)) AS coalesce_1 
FROM sem.input 
WHERE sem.input.release_id = r AND sem.input.input_kind = 'source')) THEN
  RAISE EXCEPTION USING MESSAGE = 'archive input manifest differs: source', ERRCODE = '23514';
 END IF;
 IF (manifest['dependencies'] IS DISTINCT FROM (SELECT coalesce(jsonb_agg(jsonb_build_array(sem.input.input_name, sem.input.content_digest) ORDER BY sem.input.input_name), CAST('[]' AS JSONB)) AS coalesce_1 
FROM sem.input 
WHERE sem.input.release_id = r AND sem.input.input_kind = 'dependency')) THEN
  RAISE EXCEPTION USING MESSAGE = 'archive input manifest differs: dependency', ERRCODE = '23514';
 END IF;
 IF ((manifest ->> 'version') IS DISTINCT FROM 'semantic-release-manifest-2' OR manifest['artifacts'] IS DISTINCT FROM (SELECT coalesce(jsonb_agg(jsonb_build_array(sem.artifact.artifact_name, sem.artifact.content_digest) ORDER BY sem.artifact.artifact_name), CAST('[]' AS JSONB)) AS coalesce_1 
FROM sem.artifact 
WHERE sem.artifact.release_id = r) OR (manifest ->> 'products_digest') IS DISTINCT FROM encode(sha256(convert_to(data.canonical_json(document['products'] - 'release_id'), 'UTF8')), 'hex')) THEN
  RAISE EXCEPTION USING MESSAGE = 'archive generated products differ from release identity', ERRCODE = '23514';
 END IF;
 IF ((SELECT coalesce(jsonb_agg(jsonb_build_array(sem.artifact.artifact_name, sem.artifact.content_digest) ORDER BY sem.artifact.artifact_name), CAST('[]' AS JSONB)) AS coalesce_1 
FROM sem.artifact 
WHERE sem.artifact.release_id = r) IS DISTINCT FROM (SELECT coalesce(jsonb_agg(jsonb_build_array((anon_1.value ->> 'kind'), (anon_1.value ->> 'digest')) ORDER BY (anon_1.value ->> 'kind')), CAST('[]' AS JSONB)) AS coalesce_2 
FROM jsonb_array_elements(document['products']['artifacts']) AS anon_1) OR (EXISTS (SELECT 1 
FROM sem.input 
WHERE sem.input.release_id = r AND sem.input.content_digest != encode(sha256(sem.input.content), 'hex'))) OR (EXISTS (SELECT 1 
FROM sem.artifact 
WHERE sem.artifact.release_id = r AND sem.artifact.content_digest != encode(sha256(sem.artifact.content), 'hex'))) OR (SELECT count(*) AS count_1 
FROM sem.input 
WHERE sem.input.release_id = r) != jsonb_array_length(manifest['sources']) + jsonb_array_length(manifest['dependencies']) + 3 OR (SELECT count(*) AS count_1 
FROM sem.input 
WHERE sem.input.release_id = r AND (sem.input.input_kind, sem.input.input_name) IN (('profile', 'profile'), ('vocabulary', 'vocabulary'), ('ontology_sources', 'ontology_sources'))) != 3) THEN
  RAISE EXCEPTION USING MESSAGE = 'archive product or input closure differs', ERRCODE = '23514';
 END IF;
 IF (manifest ? 'data_operation_model') THEN
  IF ((manifest ? 'execution_model_id') OR (document['products'] ? 'execution_model_id') OR NOT (EXISTS (SELECT 1 
FROM sem.artifact 
WHERE sem.artifact.release_id = r AND sem.artifact.artifact_name = 'data_operations.json' AND sem.artifact.content_digest = (manifest ->> 'data_operation_model'))) OR NOT (EXISTS (SELECT 1 
FROM sem.input 
WHERE sem.input.release_id = r AND sem.input.input_kind = 'dependency' AND sem.input.input_name = 'data-operations/manifest.json')) OR (EXISTS (SELECT 1 
FROM sem.input 
WHERE sem.input.release_id = r AND sem.input.input_kind = 'dependency' AND sem.input.input_name LIKE 'execution/%'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'target operation archive binding differs', ERRCODE = '23514';
  END IF;
 END IF;
END

