FROM sem.artifact JOIN LATERAL pg_catalog.jsonb_array_elements((CAST(pg_catalog.convert_from(sem.artifact.content, 'UTF8') AS JSONB))['decision_rules']) AS decision_rules_1(value) ON true 
WHERE sem.artifact.release_id = r AND sem.artifact.artifact_name = 'operation/scientific-policy.json') AS archived_decisions INTO expected;
 SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(anon_1) ORDER BY CAST(pg_catalog.to_jsonb(anon_1) AS TEXT)), CAST('[]' AS JSONB)) AS coalesce_1 
