WHERE (definitions_1.value ->> 'name') != 'SourceRecordProduct' AND NOT (definitions_1.value['ancestors'] ? 'SourceRecordProduct'))
 SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(archived_properties) ORDER BY CAST(pg_catalog.to_jsonb(archived_properties) AS TEXT)), CAST('[]' AS JSONB)) AS coalesce_1 
FROM (SELECT DISTINCT r AS release_id, props.definition ->> 'iri' AS class_id, props.property ->> 'iri' AS property_id, roles.role AS role 
