WHERE CAST((props.property ->> 'required') AS BOOLEAN) OR coalesce(CAST((props.property ->> 'minimum_cardinality') AS INTEGER), 0) > 0 UNION ALL SELECT 'display' AS anon_2 
WHERE EXISTS (SELECT 1 
