 SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(anon_1) ORDER BY CAST(pg_catalog.to_jsonb(anon_1) AS TEXT)), CAST('[]' AS JSONB)) AS coalesce_1 
FROM (SELECT sem.operation_property_role.release_id AS release_id, sem.operation_property_role.class_id AS class_id, sem.operation_property_role.property_id AS property_id, sem.operation_property_role.role AS role 
FROM sem.operation_property_role 
WHERE sem.operation_property_role.release_id = r) AS anon_1 INTO actual;
 IF (actual IS DISTINCT FROM expected) THEN
  RAISE EXCEPTION USING MESSAGE = 'archived operation_property_role projection differs', ERRCODE = '23514';
 END IF;
END

