 PERFORM ops.ddo_fields(manifest, ARRAY['version', 'release_id', 'model_digest', 'python_version', 'semantic_inputs', 'implementation_inputs', 'runtime_artifact', 'runtime_meaning', 'attestation', 'attestation_meaning', 'execution_profile', 'observed', 'provider_profiles']);
 PERFORM ops.ddo_fields(archive, ARRAY['version', 'inputs']);
 IF (manifest_content IS DISTINCT FROM pg_catalog.convert_to(data.canonical_json(manifest), 'UTF8') OR archive_content IS DISTINCT FROM pg_catalog.convert_to(data.canonical_json(archive), 'UTF8') OR runtime IS DISTINCT FROM ('runtime:' || pg_catalog.encode(pg_catalog.sha256(manifest_content), 'hex')) OR (manifest ->> 'release_id') IS DISTINCT FROM r OR (archive ->> 'version') IS DISTINCT FROM 'runtime-source-archive-1' OR nullif((manifest ->> 'python_version'), '') IS NULL OR nullif((manifest ->> 'execution_profile'), '') IS NULL OR NOT (EXISTS (SELECT 1 
FROM sem.artifact 
WHERE sem.artifact.release_id = r AND sem.artifact.artifact_name = 'data_operations.json' AND sem.artifact.content_digest = (manifest ->> 'model_digest')))) THEN
  RAISE EXCEPTION USING MESSAGE = 'target runtime identity or release differs', ERRCODE = '23514';
 END IF;
 SELECT CAST(pg_catalog.convert_from(sem.artifact.content, 'UTF8') AS JSONB) AS convert_from_1 
FROM sem.artifact 
WHERE sem.artifact.release_id = r AND sem.artifact.artifact_name = 'data_operation_runtime_inputs.json' INTO STRICT expected;
 IF (manifest['semantic_inputs'] IS DISTINCT FROM expected OR pg_catalog.jsonb_typeof(archive['inputs']) IS DISTINCT FROM 'array' OR pg_catalog.jsonb_typeof(manifest['implementation_inputs']) IS DISTINCT FROM 'array') THEN
  RAISE EXCEPTION USING MESSAGE = 'target runtime input requirements differ', ERRCODE = '23514';
 END IF;
 FOR item IN SELECT archive_inputs.value 
FROM pg_catalog.jsonb_array_elements(archive['inputs']) AS archive_inputs(value) LOOP
  PERFORM ops.ddo_fields(item, ARRAY['name', 'sha256', 'content_hex']);
  IF (nullif((item ->> 'name'), '') IS NULL OR (item ->> 'content_hex') !~ '^([0-9a-f]{2})*$' OR (item ->> 'sha256') IS DISTINCT FROM pg_catalog.encode(pg_catalog.sha256(pg_catalog.decode((item ->> 'content_hex'), 'hex')), 'hex')) THEN
   RAISE EXCEPTION USING MESSAGE = 'target runtime source bytes differ', ERRCODE = '23514';
  END IF;
 END LOOP;
 SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name', archive_inputs.value ->> 'name', 'sha256', archive_inputs.value ->> 'sha256') ORDER BY (archive_inputs.value ->> 'name') COLLATE "C"), CAST('[]' AS JSONB)) AS coalesce_1 
FROM pg_catalog.jsonb_array_elements(archive['inputs']) AS archive_inputs(value) INTO actual;
 IF (actual IS DISTINCT FROM manifest['implementation_inputs'] OR (SELECT count(*) != count(DISTINCT (actual_inputs.value ->> 'name')) AS anon_1 
FROM pg_catalog.jsonb_array_elements(actual) AS actual_inputs(value)) OR NOT ((actual @> expected))) THEN
  RAISE EXCEPTION USING MESSAGE = 'target runtime source closure differs', ERRCODE = '23514';
 END IF;
 IF (manifest['runtime_meaning'][0] IS DISTINCT FROM CAST('"ddo"' AS JSONB) OR manifest['runtime_meaning'][1] IS DISTINCT FROM CAST('"runtime-artifact"' AS JSONB) OR manifest['runtime_meaning'][2] IS DISTINCT FROM CAST('"1"' AS JSONB) OR data.ddo_identity('runtime-artifact', manifest['runtime_meaning'][3]) IS DISTINCT FROM (manifest ->> 'runtime_artifact') OR data.ddo_json(manifest['runtime_meaning'][3]) IS DISTINCT FROM pg_catalog.jsonb_build_object('python', (manifest ->> 'python_version'), 'inputs', actual) OR manifest['attestation_meaning'][0] IS DISTINCT FROM CAST('"ddo"' AS JSONB) OR manifest['attestation_meaning'][1] IS DISTINCT FROM CAST('"execution-attestation"' AS JSONB) OR manifest['attestation_meaning'][2] IS DISTINCT FROM CAST('"1"' AS JSONB) OR data.ddo_identity('execution-attestation', manifest['attestation_meaning'][3]) IS DISTINCT FROM (manifest ->> 'attestation') OR data.ddo_json(manifest['attestation_meaning'][3]) IS DISTINCT FROM pg_catalog.jsonb_build_object('runtime_artifact', (manifest ->> 'runtime_artifact'), 'release', r, 'execution_profile', (manifest ->> 'execution_profile'), 'observed', manifest['observed'])) THEN
  RAISE EXCEPTION USING MESSAGE = 'target runtime artifact or attestation differs', ERRCODE = '23514';
 END IF;
 SELECT CAST(pg_catalog.convert_from(sem.artifact.content, 'UTF8') AS JSONB) AS convert_from_1 
FROM sem.artifact 
WHERE sem.artifact.release_id = r AND sem.artifact.artifact_name = 'data_operations.json' INTO STRICT model;
 profiles_ := CAST('{}' AS JSONB);
 FOR operation_ IN SELECT operations.value 
FROM pg_catalog.jsonb_array_elements(model['operations']) AS operations(value) LOOP
  profile_ := sem.ddo_provider_profile(r, operation_);
  IF (profile_ IS NOT NULL) THEN
   item := manifest['provider_profiles'][(operation_ ->> 'semantic_id')];
   PERFORM ops.ddo_fields(item, ARRAY['profile', 'attestation', 'runtime_contract', 'runtime_sha256']);
   IF (item['profile'] IS DISTINCT FROM profile_) THEN
    RAISE EXCEPTION USING MESSAGE = 'runtime provider semantic contract differs', ERRCODE = 'P0001';
   END IF;
   SELECT archive_inputs.value 
FROM pg_catalog.jsonb_array_elements(archive['inputs']) AS archive_inputs(value) 
WHERE (archive_inputs.value ->> 'name') = (item ->> 'runtime_contract') INTO STRICT runtime_source;
   IF ((runtime_source ->> 'sha256') IS DISTINCT FROM (item ->> 'runtime_sha256') OR (CAST(pg_catalog.convert_from(pg_catalog.decode((runtime_source ->> 'content_hex'), 'hex'), 'UTF8') AS JSONB))['provider_profile'] IS DISTINCT FROM item['attestation']) THEN
    RAISE EXCEPTION USING MESSAGE = 'runtime provider execution asset differs', ERRCODE = 'P0001';
   END IF;
   PERFORM sem.ddo_validate_provider_attestation(item['attestation'], profile_);
   profiles_ := profiles_ || pg_catalog.jsonb_build_object((operation_ ->> 'semantic_id'), item);
  END IF;
 END LOOP;
 IF (manifest['provider_profiles'] IS DISTINCT FROM profiles_) THEN
  RAISE EXCEPTION USING MESSAGE = 'runtime provider profile operation coverage differs', ERRCODE = 'P0001';
 END IF;
END$$

