 INSERT INTO ops.pdf_stage_companion_field (product_id, revision_id, family, local_id, field_name, stream_id, scalar_kind) SELECT pg_temp.pc_pdf_stage_companion_field.product_id, pg_temp.pc_pdf_stage_companion_field.revision_id, pg_temp.pc_pdf_stage_companion_field.family, pg_temp.pc_pdf_stage_companion_field.local_id, pg_temp.pc_pdf_stage_companion_field.field_name, pg_temp.pc_pdf_stage_companion_field.stream_id, pg_temp.pc_pdf_stage_companion_field.scalar_kind 
FROM pg_temp.pc_pdf_stage_companion_field ON CONFLICT DO NOTHING;
 IF (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_companion 
WHERE (SELECT count(*) AS count_1 
FROM ops.pdf_stage_companion_field 
WHERE ops.pdf_stage_companion_field.product_id = p_build AND ops.pdf_stage_companion_field.family = pg_temp.pc_pdf_stage_companion.family AND ops.pdf_stage_companion_field.local_id = pg_temp.pc_pdf_stage_companion.local_id) != (SELECT count(*) AS count_2 
FROM pg_temp.pc_pdf_stage_companion_field 
WHERE pg_temp.pc_pdf_stage_companion_field.family = pg_temp.pc_pdf_stage_companion.family AND pg_temp.pc_pdf_stage_companion_field.local_id = pg_temp.pc_pdf_stage_companion.local_id))) THEN
  RAISE EXCEPTION USING MESSAGE = 'changed companion field inventory', ERRCODE = '23514';
 END IF;
 WITH rows_ AS 
(SELECT pg_temp.pc_pdf_stage_companion.product_id AS product_id, pg_temp.pc_pdf_stage_companion.revision_id AS revision_id, pg_temp.pc_pdf_stage_companion.family AS family, pg_temp.pc_pdf_stage_companion.local_id AS local_id, pg_temp.pc_pdf_stage_companion.body AS body, pg_temp.pc_pdf_stage_companion.ordinal AS ordinal, pg_temp.pc_pdf_stage_companion.body || coalesce((SELECT jsonb_object_agg(pg_temp.pc_pdf_stage_companion_field.field_name, CASE WHEN (pg_temp.pc_pdf_stage_companion_field.field_name = 'endpoints') THEN CAST(convert_from(ops.pdf_companion_field_bytes(p_build, p_build, pg_temp.pc_pdf_stage_companion_field.stream_id, true), 'UTF8') AS JSONB) ELSE to_jsonb(convert_from(ops.pdf_companion_field_bytes(p_build, p_build, pg_temp.pc_pdf_stage_companion_field.stream_id, true), 'UTF8')) END) AS jsonb_object_agg_1 
FROM pg_temp.pc_pdf_stage_companion_field 
WHERE pg_temp.pc_pdf_stage_companion_field.family = pg_temp.pc_pdf_stage_companion.family AND pg_temp.pc_pdf_stage_companion_field.local_id = pg_temp.pc_pdf_stage_companion.local_id AND pg_temp.pc_pdf_stage_companion_field.field_name IN ('text', 'endpoints', 'evidence')), CAST('{}' AS JSONB)) AS body_ 
FROM pg_temp.pc_pdf_stage_companion)
 INSERT INTO pg_temp.pc_pdf_stage_endpoint (product_id, revision_id, relation_id, ordinal, target_task_id, target_product_key, target_content_digest, occurrence_id, role) SELECT p_build, p_build, c.local_id, CAST(endpoint.ordinality - 1 AS BIGINT) AS anon_1, CASE WHEN (endpoint.value ? 'input_index') THEN coalesce(CAST(input_.body ->> 'task_id' AS BIGINT), 0) ELSE 0 END AS anon_2, CASE WHEN (endpoint.value ? 'input_index') THEN coalesce(input_.body ->> 'product_key', '@missing') ELSE '@self' END AS anon_3, CASE WHEN (endpoint.value ? 'input_index') THEN coalesce(input_.body ->> 'content_digest', '@missing') ELSE '@self' END AS anon_4, endpoint.value ->> 'occurrence_id' AS anon_5, endpoint.value ->> 'role' AS anon_6 
FROM rows_ AS c JOIN LATERAL jsonb_array_elements(c.body_['endpoints']) WITH ORDINALITY AS endpoint(value, ordinality) ON true LEFT OUTER JOIN ops.pdf_stage_companion AS input_ ON input_.product_id = p_build AND input_.family = 'input' AND input_.local_id = (endpoint.value ->> 'input_index') 
WHERE c.family = 'relation';
 IF (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_endpoint 
WHERE pg_temp.pc_pdf_stage_endpoint.target_content_digest = '@missing')) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion endpoint input is outside the admitted input inventory', ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_endpoint AS incoming JOIN ops.pdf_stage_endpoint AS retained ON incoming.product_id = retained.product_id AND incoming.revision_id = retained.revision_id AND incoming.relation_id = retained.relation_id AND incoming.ordinal = retained.ordinal 
WHERE (incoming.product_id, incoming.revision_id, incoming.relation_id, incoming.ordinal, incoming.target_task_id, incoming.target_product_key, incoming.target_content_digest, incoming.occurrence_id, incoming.role) IS DISTINCT FROM (retained.product_id, retained.revision_id, retained.relation_id, retained.ordinal, retained.target_task_id, retained.target_product_key, retained.target_content_digest, retained.occurrence_id, retained.role))) THEN
  RAISE EXCEPTION USING MESSAGE = 'changed companion endpoint duplicate', ERRCODE = '23514';
 END IF;
 INSERT INTO ops.pdf_stage_endpoint (product_id, revision_id, relation_id, ordinal, target_task_id, target_product_key, target_content_digest, occurrence_id, role) SELECT pg_temp.pc_pdf_stage_endpoint.product_id, pg_temp.pc_pdf_stage_endpoint.revision_id, pg_temp.pc_pdf_stage_endpoint.relation_id, pg_temp.pc_pdf_stage_endpoint.ordinal, pg_temp.pc_pdf_stage_endpoint.target_task_id, pg_temp.pc_pdf_stage_endpoint.target_product_key, pg_temp.pc_pdf_stage_endpoint.target_content_digest, pg_temp.pc_pdf_stage_endpoint.occurrence_id, pg_temp.pc_pdf_stage_endpoint.role 
FROM pg_temp.pc_pdf_stage_endpoint ON CONFLICT DO NOTHING;
END

