CREATE OR REPLACE FUNCTION ops.adopt_pdf_companions(p_build text, p_task bigint, p_attempt bigint, p_holder text, p_key text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 b ops.pdf_stage_build%ROWTYPE;
 n bigint;
 size_ bigint;
 total bigint := 0;
 total_bytes bigint := 0;
BEGIN
 b := ops.require_pdf_build(p_build, p_task, p_attempt, p_holder);
 PERFORM ops.require_pdf_operation(b.release_id, 'adopt_pdf_companions');
 IF (p_key IS NULL OR p_key = '' OR octet_length(p_key) > 1024) THEN
  RAISE EXCEPTION USING MESSAGE = 'invalid companion replay key', ERRCODE = '23514';
 END IF;
 PERFORM ops.require_pdf_stage_scratch('pc_pdf_stage_companion', CAST('ops.pdf_stage_companion' AS REGCLASS));
 IF ((EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_companion 
WHERE pg_temp.pc_pdf_stage_companion.product_id IS DISTINCT FROM p_build OR pg_temp.pc_pdf_stage_companion.revision_id IS DISTINCT FROM p_build)) OR (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_companion GROUP BY pg_temp.pc_pdf_stage_companion.product_id, pg_temp.pc_pdf_stage_companion.revision_id, pg_temp.pc_pdf_stage_companion.family, pg_temp.pc_pdf_stage_companion.local_id 
HAVING count(*) > 1))) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion upload ownership or duplicate key differs', ERRCODE = '23514';
 END IF;
 SELECT count(*) AS count_1, coalesce(sum(1 + CASE WHEN (pg_temp.pc_pdf_stage_companion.product_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_companion.product_id) END + CASE WHEN (pg_temp.pc_pdf_stage_companion.revision_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_companion.revision_id) END + CASE WHEN (pg_temp.pc_pdf_stage_companion.family IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_companion.family) END + CASE WHEN (pg_temp.pc_pdf_stage_companion.local_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_companion.local_id) END + CASE WHEN (pg_temp.pc_pdf_stage_companion.body IS NULL) THEN 0 ELSE 4 + octet_length(convert_to(CAST(pg_temp.pc_pdf_stage_companion.body AS TEXT), 'UTF8')) END + CASE WHEN (pg_temp.pc_pdf_stage_companion.ordinal IS NULL) THEN 0 ELSE 8 END), 0) AS coalesce_1 
FROM pg_temp.pc_pdf_stage_companion INTO n, size_;
 total := total + n;
 total_bytes := total_bytes + size_;
 IF (total > 65536 OR total_bytes > 8388608) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion upload profile exceeded', ERRCODE = '23514';
 END IF;
 PERFORM ops.require_pdf_stage_scratch('pc_pdf_stage_companion_field', CAST('ops.pdf_stage_companion_field' AS REGCLASS));
 IF ((EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_companion_field 
WHERE pg_temp.pc_pdf_stage_companion_field.product_id IS DISTINCT FROM p_build OR pg_temp.pc_pdf_stage_companion_field.revision_id IS DISTINCT FROM p_build)) OR (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_companion_field GROUP BY pg_temp.pc_pdf_stage_companion_field.product_id, pg_temp.pc_pdf_stage_companion_field.revision_id, pg_temp.pc_pdf_stage_companion_field.family, pg_temp.pc_pdf_stage_companion_field.local_id, pg_temp.pc_pdf_stage_companion_field.field_name 
HAVING count(*) > 1))) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion upload ownership or duplicate key differs', ERRCODE = '23514';
 END IF;
 SELECT count(*) AS count_1, coalesce(sum(1 + CASE WHEN (pg_temp.pc_pdf_stage_companion_field.product_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_companion_field.product_id) END + CASE WHEN (pg_temp.pc_pdf_stage_companion_field.revision_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_companion_field.revision_id) END + CASE WHEN (pg_temp.pc_pdf_stage_companion_field.family IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_companion_field.family) END + CASE WHEN (pg_temp.pc_pdf_stage_companion_field.local_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_companion_field.local_id) END + CASE WHEN (pg_temp.pc_pdf_stage_companion_field.field_name IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_companion_field.field_name) END + CASE WHEN (pg_temp.pc_pdf_stage_companion_field.stream_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_companion_field.stream_id) END + CASE WHEN (pg_temp.pc_pdf_stage_companion_field.scalar_kind IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_companion_field.scalar_kind) END), 0) AS coalesce_1 
FROM pg_temp.pc_pdf_stage_companion_field INTO n, size_;
 total := total + n;
 total_bytes := total_bytes + size_;
 IF (total > 65536 OR total_bytes > 8388608) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion upload profile exceeded', ERRCODE = '23514';
 END IF;
 PERFORM ops.require_pdf_stage_scratch('pc_pdf_stage_artifact_stream', CAST('ops.pdf_stage_artifact_stream' AS REGCLASS));
 IF ((EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_artifact_stream 
WHERE pg_temp.pc_pdf_stage_artifact_stream.product_id IS DISTINCT FROM p_build OR pg_temp.pc_pdf_stage_artifact_stream.revision_id IS DISTINCT FROM p_build)) OR (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_artifact_stream GROUP BY pg_temp.pc_pdf_stage_artifact_stream.product_id, pg_temp.pc_pdf_stage_artifact_stream.revision_id, pg_temp.pc_pdf_stage_artifact_stream.stream_id 
HAVING count(*) > 1))) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion upload ownership or duplicate key differs', ERRCODE = '23514';
 END IF;
 SELECT count(*) AS count_1, coalesce(sum(1 + CASE WHEN (pg_temp.pc_pdf_stage_artifact_stream.product_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_artifact_stream.product_id) END + CASE WHEN (pg_temp.pc_pdf_stage_artifact_stream.revision_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_artifact_stream.revision_id) END + CASE WHEN (pg_temp.pc_pdf_stage_artifact_stream.stream_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_artifact_stream.stream_id) END + CASE WHEN (pg_temp.pc_pdf_stage_artifact_stream.byte_length IS NULL) THEN 0 ELSE 8 END + CASE WHEN (pg_temp.pc_pdf_stage_artifact_stream.serialization_sha256 IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_artifact_stream.serialization_sha256) END + CASE WHEN (pg_temp.pc_pdf_stage_artifact_stream.byte_root IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_artifact_stream.byte_root) END + CASE WHEN (pg_temp.pc_pdf_stage_artifact_stream.encoding_profile IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_artifact_stream.encoding_profile) END), 0) AS coalesce_1 
FROM pg_temp.pc_pdf_stage_artifact_stream INTO n, size_;
 total := total + n;
 total_bytes := total_bytes + size_;
 IF (total > 65536 OR total_bytes > 8388608) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion upload profile exceeded', ERRCODE = '23514';
 END IF;
 PERFORM ops.require_pdf_stage_scratch('pc_pdf_stage_artifact_part', ops.pdf_part_upload_contract());
 IF ((EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_artifact_part 
WHERE pg_temp.pc_pdf_stage_artifact_part.product_id IS DISTINCT FROM p_build OR pg_temp.pc_pdf_stage_artifact_part.revision_id IS DISTINCT FROM p_build)) OR (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_artifact_part GROUP BY pg_temp.pc_pdf_stage_artifact_part.product_id, pg_temp.pc_pdf_stage_artifact_part.revision_id, pg_temp.pc_pdf_stage_artifact_part.stream_id, pg_temp.pc_pdf_stage_artifact_part.ordinal 
HAVING count(*) > 1))) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion upload ownership or duplicate key differs', ERRCODE = '23514';
 END IF;
 PERFORM ops.require_pdf_stage_scratch('pc_pdf_stage_endpoint', CAST('ops.pdf_stage_endpoint' AS REGCLASS));
 IF ((EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_endpoint 
WHERE pg_temp.pc_pdf_stage_endpoint.product_id IS DISTINCT FROM p_build OR pg_temp.pc_pdf_stage_endpoint.revision_id IS DISTINCT FROM p_build)) OR (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_endpoint GROUP BY pg_temp.pc_pdf_stage_endpoint.product_id, pg_temp.pc_pdf_stage_endpoint.revision_id, pg_temp.pc_pdf_stage_endpoint.relation_id, pg_temp.pc_pdf_stage_endpoint.ordinal 
HAVING count(*) > 1))) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion upload ownership or duplicate key differs', ERRCODE = '23514';
 END IF;
 SELECT count(*) AS count_1, coalesce(sum(2 + CASE WHEN (pg_temp.pc_pdf_stage_endpoint.product_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_endpoint.product_id) END + CASE WHEN (pg_temp.pc_pdf_stage_endpoint.revision_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_endpoint.revision_id) END + CASE WHEN (pg_temp.pc_pdf_stage_endpoint.relation_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_endpoint.relation_id) END + CASE WHEN (pg_temp.pc_pdf_stage_endpoint.ordinal IS NULL) THEN 0 ELSE 8 END + CASE WHEN (pg_temp.pc_pdf_stage_endpoint.target_task_id IS NULL) THEN 0 ELSE 8 END + CASE WHEN (pg_temp.pc_pdf_stage_endpoint.target_product_key IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_endpoint.target_product_key) END + CASE WHEN (pg_temp.pc_pdf_stage_endpoint.target_content_digest IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_endpoint.target_content_digest) END + CASE WHEN (pg_temp.pc_pdf_stage_endpoint.occurrence_id IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_endpoint.occurrence_id) END + CASE WHEN (pg_temp.pc_pdf_stage_endpoint.role IS NULL) THEN 0 ELSE 4 + octet_length(pg_temp.pc_pdf_stage_endpoint.role) END), 0) AS coalesce_1 
FROM pg_temp.pc_pdf_stage_endpoint INTO n, size_;
 total := total + n;
 total_bytes := total_bytes + size_;
 IF (total > 65536 OR total_bytes > 8388608) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion upload profile exceeded', ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_endpoint)) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion endpoints must be derived natively', ERRCODE = '23514';
 END IF;
 IF ((EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_companion 
WHERE pg_temp.pc_pdf_stage_companion.local_id = '' OR pg_temp.pc_pdf_stage_companion.ordinal < 0 OR jsonb_typeof(pg_temp.pc_pdf_stage_companion.body) IS DISTINCT FROM 'object' OR octet_length(CAST(pg_temp.pc_pdf_stage_companion.body AS TEXT)) > 65536 OR pg_temp.pc_pdf_stage_companion.family = 'occurrence' AND pg_temp.pc_pdf_stage_companion.local_id IS DISTINCT FROM (pg_temp.pc_pdf_stage_companion.body ->> 'occurrence_id') OR pg_temp.pc_pdf_stage_companion.family = 'relation' AND pg_temp.pc_pdf_stage_companion.local_id IS DISTINCT FROM (pg_temp.pc_pdf_stage_companion.body ->> 'relation_id') OR pg_temp.pc_pdf_stage_companion.family = 'coverage' AND pg_temp.pc_pdf_stage_companion.local_id IS DISTINCT FROM (pg_temp.pc_pdf_stage_companion.body ->> 'coverage_id') OR pg_temp.pc_pdf_stage_companion.family IN ('input', 'mapping_report') AND pg_temp.pc_pdf_stage_companion.local_id IS DISTINCT FROM CAST(pg_temp.pc_pdf_stage_companion.ordinal AS TEXT) OR pg_temp.pc_pdf_stage_companion.family = 'native_metadata' AND pg_temp.pc_pdf_stage_companion.local_id IS DISTINCT FROM ((pg_temp.pc_pdf_stage_companion.body ->> 'kind') || ':' || (pg_temp.pc_pdf_stage_companion.body ->> 'ordinal')))) OR (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_companion GROUP BY pg_temp.pc_pdf_stage_companion.family, CASE WHEN (pg_temp.pc_pdf_stage_companion.family = 'native_metadata') THEN (pg_temp.pc_pdf_stage_companion.body ->> 'kind') ELSE '' END, pg_temp.pc_pdf_stage_companion.ordinal 
HAVING count(*) > 1)) OR (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_companion JOIN ops.pdf_stage_companion AS "old" ON "old".product_id = p_build AND "old".family = pg_temp.pc_pdf_stage_companion.family AND "old".ordinal = pg_temp.pc_pdf_stage_companion.ordinal AND "old".local_id != pg_temp.pc_pdf_stage_companion.local_id AND (pg_temp.pc_pdf_stage_companion.family != 'native_metadata' OR ("old".body ->> 'kind') = (pg_temp.pc_pdf_stage_companion.body ->> 'kind'))))) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion identity/order differs from declared semantic row', ERRCODE = '23514';
 END IF;
 IF (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_companion_field LEFT OUTER JOIN pg_temp.pc_pdf_stage_companion ON pg_temp.pc_pdf_stage_companion_field.product_id = pg_temp.pc_pdf_stage_companion.product_id AND pg_temp.pc_pdf_stage_companion_field.revision_id = pg_temp.pc_pdf_stage_companion.revision_id AND pg_temp.pc_pdf_stage_companion_field.family = pg_temp.pc_pdf_stage_companion.family AND pg_temp.pc_pdf_stage_companion_field.local_id = pg_temp.pc_pdf_stage_companion.local_id 
WHERE pg_temp.pc_pdf_stage_companion.local_id IS NULL OR (pg_temp.pc_pdf_stage_companion.body ? pg_temp.pc_pdf_stage_companion_field.field_name) OR NOT (pg_temp.pc_pdf_stage_companion_field.family = 'native_metadata' AND pg_temp.pc_pdf_stage_companion_field.field_name = 'value' OR pg_temp.pc_pdf_stage_companion_field.family = 'occurrence' AND pg_temp.pc_pdf_stage_companion_field.field_name = 'text' OR pg_temp.pc_pdf_stage_companion_field.family = 'relation' AND pg_temp.pc_pdf_stage_companion_field.field_name IN ('endpoints', 'evidence')) OR pg_temp.pc_pdf_stage_companion_field.scalar_kind IS DISTINCT FROM CASE WHEN (pg_temp.pc_pdf_stage_companion_field.field_name IN ('value', 'endpoints')) THEN 'y' ELSE 's' END)) THEN
  RAISE EXCEPTION USING MESSAGE = 'invalid companion external field', ERRCODE = '23514';
 END IF;
 IF ((EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_artifact_stream 
WHERE NOT (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_companion_field 
WHERE pg_temp.pc_pdf_stage_companion_field.stream_id = pg_temp.pc_pdf_stage_artifact_stream.stream_id)))) OR (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_artifact_part 
WHERE NOT (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_companion_field 
WHERE pg_temp.pc_pdf_stage_companion_field.stream_id = pg_temp.pc_pdf_stage_artifact_part.stream_id))))) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion artifact is outside its field inventory', ERRCODE = '23514';
 END IF;
 PERFORM ops.pdf_adopt_shared_stream_descriptors(p_build, CAST('pg_temp.pc_pdf_stage_artifact_stream' AS REGCLASS));
 IF (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_artifact_stream AS incoming JOIN ops.pdf_stage_artifact_stream AS retained ON incoming.product_id = retained.product_id AND incoming.revision_id = retained.revision_id AND incoming.stream_id = retained.stream_id 
WHERE (incoming.product_id, incoming.revision_id, incoming.stream_id, incoming.byte_length, incoming.serialization_sha256, incoming.byte_root, incoming.encoding_profile) IS DISTINCT FROM (retained.product_id, retained.revision_id, retained.stream_id, retained.byte_length, retained.serialization_sha256, retained.byte_root, retained.encoding_profile))) THEN
  RAISE EXCEPTION USING MESSAGE = 'changed companion artifact duplicate', ERRCODE = '23514';
 END IF;
 INSERT INTO ops.pdf_stage_artifact_stream (product_id, revision_id, stream_id, byte_length, serialization_sha256, byte_root, encoding_profile) SELECT pg_temp.pc_pdf_stage_artifact_stream.product_id, pg_temp.pc_pdf_stage_artifact_stream.revision_id, pg_temp.pc_pdf_stage_artifact_stream.stream_id, pg_temp.pc_pdf_stage_artifact_stream.byte_length, pg_temp.pc_pdf_stage_artifact_stream.serialization_sha256, pg_temp.pc_pdf_stage_artifact_stream.byte_root, pg_temp.pc_pdf_stage_artifact_stream.encoding_profile 
FROM pg_temp.pc_pdf_stage_artifact_stream ON CONFLICT DO NOTHING;
 PERFORM ops.pdf_adopt_shared_stream_parts(p_build, CAST('pg_temp.pc_pdf_stage_artifact_part' AS REGCLASS));
 PERFORM ops.pdf_verify_shared_stream(p_build, pg_temp.pc_pdf_stage_artifact_stream.stream_id) AS pdf_verify_shared_stream_1 
FROM pg_temp.pc_pdf_stage_artifact_stream;
 IF (EXISTS (SELECT 1 
FROM pg_temp.pc_pdf_stage_companion_field JOIN pg_temp.pc_pdf_stage_companion ON pg_temp.pc_pdf_stage_companion_field.product_id = pg_temp.pc_pdf_stage_companion.product_id AND pg_temp.pc_pdf_stage_companion_field.revision_id = pg_temp.pc_pdf_stage_companion.revision_id AND pg_temp.pc_pdf_stage_companion_field.family = pg_temp.pc_pdf_stage_companion.family AND pg_temp.pc_pdf_stage_companion_field.local_id = pg_temp.pc_pdf_stage_companion.local_id LEFT OUTER JOIN ops.pdf_stage_artifact_stream ON ops.pdf_stage_artifact_stream.product_id = p_build AND ops.pdf_stage_artifact_stream.revision_id = p_build AND ops.pdf_stage_artifact_stream.stream_id = pg_temp.pc_pdf_stage_companion_field.stream_id 
WHERE ops.pdf_stage_artifact_stream.encoding_profile IS DISTINCT FROM CASE WHEN (pg_temp.pc_pdf_stage_companion_field.field_name = 'value' AND (pg_temp.pc_pdf_stage_companion.body ->> 'kind') = 'inline_candidate_pages') THEN 'pdf-ocr-candidate-ipc-v1' WHEN (pg_temp.pc_pdf_stage_companion_field.field_name IN ('value', 'endpoints')) THEN 'pdf-companion-json-field-v1' ELSE 'pdf-record-scalar-v1:s' END)) THEN
  RAISE EXCEPTION USING MESSAGE = 'companion field encoding differs', ERRCODE = '23514';
 END IF;
 PERFORM sum(octet_length(ops.pdf_companion_field_bytes(p_build, p_build, pg_temp.pc_pdf_stage_companion_field.stream_id, true))) AS sum_1 
