ype":"string"}}}' AS JSONB) || jsonb_build_object('table_pointer', jsonb_build_object('type', 'string', 'const', pg_temp.pc_pdf_stage_companion.body['pointer']))))) ELSE CAST('{"properties":{"pointer":{"not":{"type":"string"}},"prose_pointer":{"not":{"type":"string"}},"table_pointer":{"not":{"type":"string"}}}}' AS JSONB) END, CASE WHEN ((pg_temp.pc_pdf_stage_companion.body ->> 'kind') = 'formula_outcomes') THEN jsonb_build_object('required', jsonb_build_array('outcome'), 'properties', jsonb_build_object('outcome', jsonb_build_object('const', pg_temp.pc_pdf_stage_companion.body['outcome']))) || CASE WHEN (pg_temp.pc_pdf_stage_companion.body['has_diagnostic'] = CAST('true' AS JSONB)) THEN CAST('{"required":["outcome","error"]}' AS JSONB) ELSE CAST('{"not":{"required":["error"]}}' AS JSONB) END ELSE CAST('{}' AS JSONB) END)) AS JSON), CAST(convert_from(ops.pdf_companion_field_bytes(p_build, p_build, pg_temp.pc_pdf_stage_companion_field.stream_id, true), 'UTF8') AS JSON)) IS NOT true)) THEN
