DECLARE
 source jsonb;
 cut jsonb;
 body jsonb;
 observation jsonb;
 image jsonb;
 mapping jsonb;
 raw_pin jsonb;
 raw_input jsonb;
 mapped jsonb;
 result jsonb;
 artifact bytea;
 image_bytes bytea;
 response_bytes bytea;
 total integer;
 offset_ integer;
 length_ integer;
 kind text;
 digest text;
 media text;
 product kb.data_product%ROWTYPE;
 boundary ops.data_demand_read%ROWTYPE;
 raw_product kb.data_product%ROWTYPE;
 episode ops.data_derivation%ROWTYPE;
 raw_episode ops.data_derivation%ROWTYPE;
 intent ops.data_completion_intent%ROWTYPE;
BEGIN
 source := (ops.ddo_impl_read_selected_pdf_source(p_payload['source']))['payload'];
 cut := ops.ddo_require_selected_output((p_payload['source']) ->> 'demand_id', (p_payload['source']) ->> 'read_id', (p_payload['evidence']) ->> 'use_id', (p_payload['evidence']) ->> 'product_id', (p_payload['evidence']) ->> 'derivation_id');
 IF (cut IS DISTINCT FROM source['cut']) THEN
  RAISE EXCEPTION USING MESSAGE = 'visual evidence differs from selected source cut', ERRCODE = '23514';
 END IF;
 SELECT ops.data_demand_read.* 
FROM ops.data_demand_read 
WHERE ops.data_demand_read.id = ((p_payload['source']) ->> 'read_id') AND ops.data_demand_read.demand_id = ((p_payload['source']) ->> 'demand_id') INTO STRICT boundary;
 IF (NOT boundary.public_disclosure AND boundary.scope != CAST('{}' AS JSONB)) THEN
  PERFORM ops.ddo_authorize('evaluator');
 END IF;
 SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = ((p_payload['evidence']) ->> 'product_id') AND kb.data_product.project_id = ((p_payload['source']) ->> 'project_id') INTO STRICT product;
 SELECT sem.data_kind_contract.kind 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = product.kind_contract INTO STRICT kind;
 SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = ((p_payload['evidence']) ->> 'derivation_id') INTO STRICT episode;
 body := data.ddo_json(product.canonical_body);
 raw_pin := p_payload['evidence'];
 raw_episode := episode;
 IF (kind = 'https://corpus-structure.dev/semantic/data-operation-visual/DdoVisualMapping') THEN
  mapping := body;
  observation := body['observation'];
  SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = episode.intent_id INTO STRICT intent;
  SELECT selected.value 
FROM jsonb_array_elements(intent.payload['inputs']) AS selected(value) 
WHERE (selected.value ->> 'role') = 'observation' AND (selected.value ->> 'member_id') IS NULL INTO STRICT raw_input;
  IF (NOT (EXISTS (SELECT 1 
FROM ops.data_derivation_input 
WHERE ops.data_derivation_input.derivation_id = episode.id AND ops.data_derivation_input.role = 'observation' AND ops.data_derivation_input.product_id = (raw_input ->> 'product_id') AND ops.data_derivation_input.member_id IS NULL)) OR NOT (EXISTS (SELECT 1 
FROM ops.data_derivation_support 
WHERE ops.data_derivation_support.derivation_id = episode.id AND ops.data_derivation_support.support_derivation_id = ops.ddo_single_input_support_episode(raw_input)))) THEN
   RAISE EXCEPTION USING MESSAGE = 'visual mapping lacks exact admitted raw input', ERRCODE = '23514';
  END IF;
  raw_pin := jsonb_build_object('use_id', (p_payload['evidence']) ->> 'use_id', 'product_id', raw_input ->> 'product_id', 'derivation_id', ops.ddo_single_input_support_episode(raw_input));
  PERFORM ops.ddo_require_selected_output((p_payload['source']) ->> 'demand_id', (p_payload['source']) ->> 'read_id', raw_pin ->> 'use_id', raw_pin ->> 'product_id', raw_pin ->> 'derivation_id');
  SELECT kb.data_product.* 
FROM kb.data_product 
WHERE kb.data_product.id = (raw_pin ->> 'product_id') AND kb.data_product.project_id = product.project_id AND kb.data_product.original_source = product.original_source INTO STRICT raw_product;
  IF (NOT (EXISTS (SELECT 1 
FROM sem.data_kind_contract 
WHERE sem.data_kind_contract.kind_contract = raw_product.kind_contract AND sem.data_kind_contract.kind = 'https://corpus-structure.dev/semantic/data-operation-visual/DdoChandraObservation')) OR data.ddo_json(raw_product.canonical_body) IS DISTINCT FROM observation) THEN
   RAISE EXCEPTION USING MESSAGE = 'visual mapping differs from its admitted raw observation', ERRCODE = '23514';
  END IF;
  SELECT ops.data_derivation.* 
FROM ops.data_derivation 
WHERE ops.data_derivation.id = (raw_pin ->> 'derivation_id') INTO STRICT raw_episode;
 ELSE
  IF (kind = 'https://corpus-structure.dev/semantic/data-operation-visual/DdoChandraObservation') THEN
   observation := body;
  ELSE
   RAISE EXCEPTION USING MESSAGE = 'selected product is not visual evidence', ERRCODE = '23514';
  END IF;
 END IF;
 image := observation['image'];
 IF (product.original_source IS DISTINCT FROM (image ->> 'document') OR product.original_source IS DISTINCT FROM (source ->> 'original_source') OR (image ->> 'source_digest') IS DISTINCT FROM ((source['receipt']['publication']) ->> 'source_digest') OR (image ->> 'logical_digest') IS DISTINCT FROM ((source['receipt']['publication']) ->> 'logical_digest')) THEN
  RAISE EXCEPTION USING MESSAGE = 'visual image differs from selected original PDF source', ERRCODE = '23514';
 END IF;
 image_bytes := decode(image ->> 'content_hex', 'hex');
 response_bytes := convert_to(observation ->> 'raw_response', 'UTF8');
 IF (encode(sha256(image_bytes), 'hex') IS DISTINCT FROM (image ->> 'content_digest') OR substr(image_bytes, 1, 8) IS DISTINCT FROM decode('89504e470d0a1a0a', 'hex') OR octet_length(image_bytes) < 24 OR 0 + CAST(get_byte(image_bytes, 16) AS BIGINT) * 16777216 + get_byte(image_bytes, 17) * 65536 + get_byte(image_bytes, 18) * 256 + get_byte(image_bytes, 19) != CAST((image ->> 'width') AS INTEGER) OR 0 + CAST(get_byte(image_bytes, 20) AS BIGINT) * 16777216 + get_byte(image_bytes, 21) * 65536 + get_byte(image_bytes, 22) * 256 + get_byte(image_bytes, 23) != CAST((image ->> 'height') AS INTEGER) OR encode(sha256(response_bytes), 'hex') IS DISTINCT FROM (observation ->> 'response_digest')) THEN
  RAISE EXCEPTION USING MESSAGE = 'visual retained bytes differ from their exact digests', ERRCODE = '23514';
 END IF;
 IF (mapping IS NOT NULL AND (mapping ->> 'mapped_hex') != '') THEN
  artifact := decode(mapping ->> 'mapped_hex', 'hex');
  IF (octet_length(artifact) > 8388608) THEN
   RAISE EXCEPTION USING MESSAGE = 'visual mapped artifact exceeds byte bound', ERRCODE = '54000';
  END IF;
  mapped := CAST(convert_from(artifact, 'UTF8') AS JSONB);
  IF (NOT public.json_matches_schema(CAST('{"$schema":"http://json-schema.org/draft-07/schema#","additionalProperties":false,"definitions":{"visual_read_JsonValue":{},"visual_read_VisualCaption":{"additionalProperties":false,"description":"A transcription candidate with the parser''s attachment.","properties":{"kind":{"const":"caption","default":"caption","title":"Kind","type":"string"},"occurrence_id":{"minLength":1,"title":"Occurrence Id","type":"string"},"parent_occurrence_id":{"minLength":1,"title":"Parent Occurrence Id","type":"string"},"parser_attachment_occurrence_ids":{"default":[],"items":{"type":"string"},"title":"Parser Attachment Occurrence Ids","type":"array"},"provider_locator":{"anyOf":[{"minLength":1,"type":"string"},{"type":"null"}],"default":null,"title":"Provider Locator"},"source_region":{"anyOf":[{"$ref":"#/definitions/visual_read_VisualSourceRegion"},{"type":"null"}],"default":null},"text":{"title":"Text","type":"string"}},"required":["occurrence_id","parent_occurrence_id","text"],"title":"VisualCaption","type":"object"},"visual_read_VisualCaptionCandidate":{"additionalProperties":false,"description":"A detached transcription candidate with optional source-qualified associations.","properties":{"associated_picture_occurrence_ids":{"default":[],"items":{"type":"string"},"title":"Associated Picture Occurrence Ids","type":"array"},"kind":{"const":"caption_candidate","default":"caption_candidate","title":"Kind","type":"string"},"occurrence_id":{"minLength":1,"title":"Occurrence Id","type":"string"},"parent_occurrence_id":{"default":null,"title":"Parent Occurrence Id","type":"null"},"parser_attachment_occurrence_ids":{"default":[],"items":{"type":"string"},"title":"Parser Attachment Occurrence Ids","type":"array"},"provider_locator":{"anyOf":[{"minLength":1,"type":"string"},{"type":"null"}],"default":null,"title":"Provider Locator"},"source_region":{"anyOf":[{"$ref":"#/definitions/visual_read_VisualSourceRegion"},{"type":"null"}],"default":null},"text":{"title":"Text","type":"string"}},"required":["occurrence_id","text"],"title":"VisualCaptionCandidate","type":"object"},"visual_read_VisualCellGroup":{"additionalProperties":false,"properties":{"kind":{"const":"cell_group","default":"cell_group","title":"Kind","type":"string"},"native_label":{"title":"Native Label","type":"string"},"occurrence_id":{"minLength":1,"title":"Occurrence Id","type":"string"},"parent_occurrence_id":{"minLength":1,"title":"Parent Occurrence Id","type":"string"},"provider_locator":{"anyOf":[{"minLength":1,"type":"string"},{"type":"null"}],"default":null,"title":"Provider Locator"},"source_region":{"anyOf":[{"$ref":"#/definitions/visual_read_VisualSourceRegion"},{"type":"null"}],"default":null}},"required":["occurrence_id","parent_occurrence_id","native_label"],"title":"VisualCellGroup","type":"object"},"visual_read_VisualPicture":{"additionalProperties":false,"properties":{"kind":{"const":"picture","default":"picture","title":"Kind","type":"string"},"metadata":{"anyOf":[{"additionalProperties":{"$ref":"#/definitions/visual_read_JsonValue"},"type":"object"},{"type":"null"}],"default":null,"title":"Metadata"},"occurrence_id":{"minLength":1,"title":"Occurrence Id","type":"string"},"parent_occurrence_id":{"anyOf":[{"minLength":1,"type":"string"},{"type":"null"}],"default":null,"title":"Parent Occurrence Id"},"provider_locator":{"anyOf":[{"minLength":1,"type":"string"},{"type":"null"}],"default":null,"title":"Provider Locator"},"source_region":{"anyOf":[{"$ref":"#/definitions/visual_read_VisualSourceRegion"},{"type":"null"}],"default":null}},"required":["occurrence_id"],"title":"VisualPicture","type":"object"},"visual_read_VisualSourceRegion":{"additionalProperties":false,"description":"A coarse region in the original page''s top-left PDF point frame.","properties":{"address_space":{"const":"pdf_points","default":"pdf_points","title":"Address Space","type":"string"},"bottom":{"exclusiveMinimum":0,"title":"Bottom","type":"number"},"enclosing_occurrence_id":{"anyOf":[{"minLength":1,"type":"string"},{"type":"null"}],"default":null,"title":"Enclosing Occurrence Id"},"left":{"minimum":0,"title":"Left","type":"number"},"origin":{"const":"top_left","default":"top_left","title":"Origin","type":"string"},"precision":{"const":"coarse","default":"coarse","title":"Precision","type":"string"},"right":{"exclusiveMinimum":0,"title":"Right","type":"number"},"top":{"minimum":0,"title":"Top","type":"number"}},"required":["left","top","right","bottom"],"title":"VisualSourceRegion","type":"object"},"visual_read_VisualTable":{"additionalProperties":false,"properties":{"cells":{"items":{"$ref":"#/definitions/visual_read_VisualTableCell"},"title":"Cells","type":"array"},"kind":{"const":"table","default":"table","title":"Kind","type":"string"},"num_cols":{"minimum":0,"title":"Num Cols","type":"integer"},"num_rows":{"minimum":0,"title":"Num Rows","type":"integer"},"occurrence_id":{"minLength":1,"title":"Occurrence Id","type":"string"},"parent_occurrence_id":{"anyOf":[{"minLength":1,"type":"string"},{"type":"null"}],"default":null,"title":"Parent Occurrence Id"},"provider_locator":{"anyOf":[{"minLength":1,"type":"string"},{"type":"null"}],"default":null,"title":"Provider Locator"},"source_region":{"anyOf":[{"$ref":"#/definitions/visual_read_VisualSourceRegion"},{"type":"null"}],"default":null}},"required":["occurrence_id","cells","num_rows","num_cols"],"title":"VisualTable","type":"object"},"visual_read_VisualTableCell":{"additionalProperties":false,"properties":{"column_header":{"default":false,"title":"Column Header","type":"boolean"},"column_header_path":{"default":[],"items":{"type":"integer"},"title":"Column Header Path","type":"array"},"content_occurrence_id":{"anyOf":[{"minLength":1,"type":"string"},{"type":"null"}],"default":null,"title":"Content Occurrence Id"},"end_col_offset_idx":{"exclusiveMinimum":0,"title":"End Col Offset Idx","type":"integer"},"end_row_offset_idx":{"exclusiveMinimum":0,"title":"End Row Offset Idx","type":"integer"},"row_header":{"default":false,"title":"Row Header","type":"boolean"},"row_header_path":{"default":[],"items":{"type":"integer"},"title":"Row Header Path","type":"array"},"start_col_offset_idx":{"minimum":0,"title":"Start Col Offset Idx","type":"integer"},"start_row_offset_idx":{"minimum":0,"title":"Start Row Offset Idx","type":"integer"},"text":{"title":"Text","type":"string"}},"required":["text","start_row_offset_idx","end_row_offset_idx","start_col_offset_idx","end_col_offset_idx"],"title":"VisualTableCell","type":"object"},"visual_read_VisualText":{"additionalProperties":false,"properties":{"kind":{"enum":["picture_description","picture_text","formula","mermaid","cell_text"],"title":"Kind","type":"string"},"native_label":{"anyOf":[{"type":"string"},{"type":"null"}],"default":null,"title":"Native Label"},"occurrence_id":{"minLength":1,"title":"Occurrence Id","type":"string"},"original_text":{"anyOf":[{"type":"string"},{"type":"null"}],"default":null,"title":"Original Text"},"parent_occurrence_id":{"anyOf":[{"minLength":1,"type":"string"},{"type":"null"}],"default":null,"title":"Parent Occurrence Id"},"provider_locator":{"anyOf":[{"minLength":1,"type":"string"},{"type":"null"}],"default":null,"title":"Provider Locator"},"source_region":{"anyOf":[{"$ref":"#/definitions/visual_read_VisualSourceRegion"},{"type":"null"}],"default":null},"text":{"title":"Text","type":"string"}},"required":["occurrence_id","kind","text"],"title":"VisualText","type":"object"}},"description":"One submitted page/crop. Row identities preserve distinct repeated occurrences.","properties":{"page_no":{"exclusiveMinimum":0,"title":"Page No","type":"integer"},"rows":{"items":{"discriminator":{"mapping":{"caption":"#/definitions/visual_read_VisualCaption","caption_candidate":"#/definitions/visual_read_VisualCaptionCandidate","cell_group":"#/definitions/visual_read_VisualCellGroup","cell_text":"#/definitions/visual_read_VisualText","formula":"#/definitions/visual_read_VisualText","mermaid":"#/definitions/visual_read_VisualText","picture":"#/definitions/visual_read_VisualPicture","picture_description":"#/definitions/visual_read_VisualText","picture_text":"#/definitions/visual_read_VisualText","table":"#/definitions/visual_read_VisualTable"},"propertyName":"kind"},"oneOf":[{"$ref":"#/definitions/visual_read_VisualPicture"},{"$ref":"#/definitions/visual_read_VisualCaption"},{"$ref":"#/definitions/visual_read_VisualCaptionCandidate"},{"$ref":"#/definitions/visual_read_VisualText"},{"$ref":"#/definitions/visual_read_VisualTable"},{"$ref":"#/definitions/visual_read_VisualCellGroup"}]},"maxItems":10000,"title":"Rows","type":"array"},"version":{"const":1,"default":1,"title":"Version","type":"integer"}},"required":["page_no","rows"],"title":"VisualEvidenceArtifact","type":"object"}' AS JSON), CAST(mapped AS JSON)) OR CAST((mapped ->> 'page_no') AS INTEGER) != CAST((image ->> 'page_no') AS INTEGER)) THEN
   RAISE EXCEPTION USING MESSAGE = 'visual mapped artifact violates current candidate schema', ERRCODE = '23514';
  END IF;
 END IF;
 IF ((p_payload ->> 'mode') = 'header') THEN
  result := jsonb_build_object('kind', 'header', 'header', jsonb_build_object('evidence', p_payload['evidence'], 'raw', raw_pin, 'producer', to_jsonb(episode), 'raw_producer', to_jsonb(raw_episode), 'observation', ((observation - 'raw_response') - 'image') || jsonb_build_object('image', ((image - 'content_hex') - 'transform_json') || jsonb_build_object('transform', CAST((image ->> 'transform_json') AS JSONB))), 'mapping_availability', CASE WHEN (mapping IS NULL) THEN 'not_selected' WHEN (mapped IS NULL) THEN 'unavailable' ELSE 'available' END, 'mapping', CASE WHEN (mapping IS NULL) THEN NULL ELSE (mapping - 'observation') - 'mapped_hex' END, 'mapped_digest', CASE WHEN (mapped IS NULL) THEN NULL ELSE encode(sha256(artifact), 'hex') END));
 ELSE
  IF ((p_payload ->> 'mode') = 'artifact') THEN
   digest := p_payload ->> 'artifact_digest';
   IF (digest = (image ->> 'content_digest')) THEN
    artifact := image_bytes;
    media := 'image/png';
   ELSE
    IF (digest = (observation ->> 'response_digest')) THEN
     artifact := response_bytes;
     media := 'text/html; charset=utf-8';
    ELSE
     IF (mapped IS NOT NULL AND digest = encode(sha256(artifact), 'hex')) THEN
      media := 'application/json';
     ELSE
      RAISE EXCEPTION USING MESSAGE = 'visual artifact is outside exact selected evidence', ERRCODE = '23514';
     END IF;
    END IF;
   END IF;
   total := octet_length(artifact);
   offset_ := CAST(p_payload ->> 'after' AS INTEGER);
   IF (offset_ > total OR offset_ = total AND offset_ != 0) THEN
    RAISE EXCEPTION USING MESSAGE = 'visual byte continuation is outside artifact', ERRCODE = '23514';
   END IF;
   length_ := least(65536, total - offset_);
   result := jsonb_build_object('kind', 'artifact', 'digest', digest, 'media_type', media, 'content_hex', encode(substr(artifact, offset_ + 1, length_), 'hex'), 'offset', offset_, 'total_bytes', total, 'next_offset', CASE WHEN (offset_ + length_ < total) THEN offset_ + length_ END);
  ELSE
   IF ((p_payload ->> 'mode') = 'rows') THEN
    result := ops.ddo_visual_candidate_rows(mapped, p_payload);
   ELSE
    RAISE EXCEPTION USING MESSAGE = 'unknown visual read mode', ERRCODE = '23514';
   END IF;
  END IF;
 END IF;
 IF (octet_length(CAST(result AS TEXT)) > CAST((p_payload ->> 'max_bytes') AS INTEGER)) THEN
  RAISE EXCEPTION USING MESSAGE = 'visual result exceeds byte bound', ERRCODE = '54000';
 END IF;
 RETURN jsonb_build_object('payload', result);
END

