CREATE OR REPLACE FUNCTION ops.ddo_impl_read_selected_visual_evidence(p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 source jsonb;
 cut jsonb;
 body jsonb;
 observation jsonb;
 image jsonb;
 mapping jsonb;
 raw_pin jsonb;
 raw_input jsonb;
 mapped jsonb;
 result jsonb;
 artifact bytea;
 image_bytes bytea;
 response_bytes bytea;
 total integer;
 offset_ integer;
 length_ integer;
 kind text;
 digest text;
 media text;
 product kb.data_product%ROWTYPE;
 boundary ops.data_demand_read%ROWTYPE;
 raw_product kb.data_product%ROWTYPE;
 episode ops.data_derivation%ROWTYPE;
 raw_episode ops.data_derivation%ROWTYPE;
 intent ops.data_completion_intent%ROWTYPE;
BEGIN
 source := (ops.ddo_impl_read_selected_pdf_source(p_payload['source']))['payload'];
 cut := ops.ddo_require_selected_output((p_payload['source']) ->> 'demand_id', (p_payload['source']) ->> 'read_id', (p_payload['evidence']) ->> 'use_id', (p_payload['evidence']) ->> 'product_id', (p_payload['evidence']) ->> 'derivation_id');
 IF (cut IS DISTINCT FROM source['cut']) THEN
  RAISE EXCEPTION USING MESSAGE = 'visual evidence differs from selected source cut', ERRCODE = '23514';
 END IF;
