   offset_ := CAST(p_payload ->> 'after' AS INTEGER);
   IF (offset_ > total OR offset_ = total AND offset_ != 0) THEN
    RAISE EXCEPTION USING MESSAGE = 'visual byte continuation is outside artifact', ERRCODE = '23514';
   END IF;
   length_ := least(65536, total - offset_);
