DECLARE
 requirement jsonb;
 request ops.data_request%ROWTYPE;
 producer ops.data_derivation%ROWTYPE;
 definition sem.data_operation_definition%ROWTYPE;
 intent ops.data_completion_intent%ROWTYPE;
BEGIN
 SELECT consumer_role.value['producer_requirement'] AS anon_1 
FROM sem.data_operation_definition JOIN jsonb_array_elements(sem.data_operation_definition.input_roles) AS consumer_role(value) ON true 
WHERE sem.data_operation_definition.release_id = consumer.release_id AND sem.data_operation_definition.operation_id = consumer.operation_id AND (consumer_role.value ->> 'name') = role INTO STRICT requirement;
 IF (requirement IS NULL OR (requirement ->> 'required_family') IS NULL OR (requirement ->> 'required_family') = 'undetermined' OR jsonb_typeof(requirement['requires_cpu']) IS DISTINCT FROM 'boolean') THEN
  RAISE EXCEPTION USING MESSAGE = 'consumer role has unresolved producer requirements', ERRCODE = '23514';
 END IF;
 SELECT ops.data_derivation.* 
FROM ops.data_derivation JOIN ops.data_derivation_output ON ops.data_derivation_output.derivation_id = ops.data_derivation.id JOIN ops.data_publication_receipt ON ops.data_publication_receipt.derivation_id = ops.data_derivation.id AND ops.data_publication_receipt.intent_id = ops.data_derivation.intent_id 
WHERE ops.data_derivation_output.product_id = (selected ->> 'product_id') AND ops.data_derivation_output.member_id IS NULL AND ((requirement ->> 'output_role') IS NULL OR ops.data_derivation_output.role = (requirement ->> 'output_role')) AND ops.data_derivation_output.multiplicity = 1 AND ops.data_derivation.outcome = 'success' AND (EXISTS (SELECT 1 
FROM jsonb_array_elements(selected['support_references']) AS reference(value) 
WHERE (reference.value ->> 'kind') = 'computation' AND (reference.value ->> 'derivation_id') = ops.data_derivation.id)) INTO STRICT producer;
 SELECT ops.data_request.* 
FROM ops.data_request 
WHERE ops.data_request.id = producer.request_id AND ops.data_request.project_id = consumer.project_id INTO STRICT request;
 SELECT sem.data_operation_definition.* 
FROM sem.data_operation_definition 
WHERE sem.data_operation_definition.release_id = request.release_id AND sem.data_operation_definition.operation_id = request.operation_id INTO STRICT definition;
 SELECT ops.data_completion_intent.* 
FROM ops.data_completion_intent 
WHERE ops.data_completion_intent.id = producer.intent_id INTO STRICT intent;
 IF ((requirement ->> 'required_family') != 'none' AND ((definition.validity_families @> ARRAY[(requirement ->> 'required_family')])) IS NOT true) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich selection producer lacks its required validity family', ERRCODE = '23514';
 END IF;
 IF ((requirement ->> 'required_effect') IS NOT NULL AND ops.ddo_privileged_effect_admitted(definition, (requirement ->> 'required_effect')) IS NOT true OR (((definition.support_contract['capabilities']['prepared_factory']) ->> 'source_digest') ~ '^[0-9a-f]{64}$') IS NOT true OR (definition.implementation_revision LIKE 'implementation-slice:%') IS NOT true OR (intent.payload ->> 'implementation_revision') IS DISTINCT FROM definition.implementation_revision OR producer.recipe IS DISTINCT FROM definition.recipe OR request.recipe IS DISTINCT FROM definition.recipe OR CAST((requirement ->> 'requires_cpu') AS BOOLEAN) AND (definition.profile IS NOT DISTINCT FROM 'derivation' AND definition.support_contract['effects'] IS NOT DISTINCT FROM CAST('[]' AS JSONB) AND jsonb_array_length(coalesce(intent.payload['execution_evidence']['cpu_receipts'], CAST('[]' AS JSONB))) = 1) IS NOT true) THEN
  RAISE EXCEPTION USING MESSAGE = 'rich selection lacks its actual admitted producer and CPU/common receipt', ERRCODE = '23514';
 END IF;
 RETURN request;
END

