 IF (expected_ IS NULL) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF domain contract differs', ERRCODE = '23514';
 END IF;
 SELECT sem.input.content 
FROM sem.input 
WHERE sem.input.release_id = p_release AND sem.input.input_kind = 'dependency' AND sem.input.input_name = ('pdf-domain/' || p_name) AND (EXISTS (SELECT anon_1.value 
FROM jsonb_array_elements(expected_) AS anon_1 
WHERE (anon_1.value ->> 'name') = sem.input.input_name AND (anon_1.value ->> 'sha256') = sem.input.content_digest)) AND encode(sha256(sem.input.content), 'hex') = sem.input.content_digest INTO STRICT content_;
 RETURN content_;
END

