FROM json_array_elements(coalesce(mapping_rows, CAST('[]' AS JSON))) WITH ORDINALITY AS mappings(value, n) LEFT OUTER JOIN ops.pdf_product_input ON ops.pdf_product_input.task_id = p_task AND ops.pdf_product_input.product_key = (product ->> 'product_key') AND ops.pdf_product_input.input_index = CAST((CAST(mappings.value AS JSONB) ->> 'input_index') AS BIGINT) 
WHERE ops.pdf_product_input.role IS DISTINCT FROM 'recognition' OR (CAST(mappings.value AS JSONB) ->> 'outcome') != 'mapped' AND coalesce((CAST(mappings.value AS JSONB) ->> 'reason'), '') = '' OR (CAST(mappings.value AS JSONB) ? 'occurrence_id') AND NOT (EXISTS (SELECT 1 
FROM kb.pdf_occurrence 
WHERE kb.pdf_occurrence.task_id = ops.pdf_product_input.input_task_id AND kb.pdf_occurrence.product_key = ops.pdf_product_input.input_product_key AND kb.pdf_occurrence.occurrence_id = (CAST(mappings.value AS JSONB) ->> 'occurrence_id'))))) THEN
  RAISE EXCEPTION USING MESSAGE = 'mapping disposition differs from recognition custody', ERRCODE = '23514';
 END IF;
 FOR mapping_report, idx IN SELECT CAST(mappings.value AS JSONB) AS value, mappings.n - 1 AS anon_1 
FROM json_array_elements(coalesce(mapping_rows, CAST('[]' AS JSON))) WITH ORDINALITY AS mappings(value, n) LOOP
  IF (jsonb_typeof(mapping_report) IS DISTINCT FROM 'object') THEN
   RAISE EXCEPTION USING MESSAGE = 'parsing record must be an object: PdfMappingDisposition', ERRCODE = '23514';
  END IF;
  IF ((EXISTS (SELECT shape_0.value 
FROM jsonb_object_keys(mapping_report) AS shape_0(value) 
WHERE NOT (shape_0.value = ANY (ARRAY['input_index', 'occurrence_id', 'outcome', 'label', 'reason', 'raw_start', 'coordinate_frame', 'coordinate_scale', 'normalization'])))) OR NOT (mapping_report ? 'input_index') OR (mapping_report ? 'input_index') AND (jsonb_typeof(mapping_report['input_index']) IS DISTINCT FROM 'number' OR ((mapping_report['input_index'] #>> ARRAY[]::TEXT[]) !~ '^[0-9]+$')) OR (mapping_report ? 'input_index') AND CAST(mapping_report['input_index'] #>> ARRAY[]::TEXT[] AS NUMERIC) < '0' OR (mapping_report ? 'occurrence_id') AND jsonb_typeof(mapping_report['occurrence_id']) IS DISTINCT FROM 'string' OR NOT (mapping_report ? 'outcome') OR (mapping_report ? 'outcome') AND (jsonb_typeof(mapping_report['outcome']) IS DISTINCT FROM 'string' OR ((mapping_report['outcome'] #>> ARRAY[]::TEXT[]) NOT IN ('dropped', 'evidence_only', 'mapped', 'unresolved', 'unsupported'))) OR (mapping_report ? 'label') AND jsonb_typeof(mapping_report['label']) IS DISTINCT FROM 'string' OR (mapping_report ? 'reason') AND jsonb_typeof(mapping_report['reason']) IS DISTINCT FROM 'string' OR (mapping_report ? 'raw_start') AND (jsonb_typeof(mapping_report['raw_start']) IS DISTINCT FROM 'number' OR ((mapping_report['raw_start'] #>> ARRAY[]::TEXT[]) !~ '^[0-9]+$')) OR (mapping_report ? 'raw_start') AND CAST(mapping_report['raw_start'] #>> ARRAY[]::TEXT[] AS NUMERIC) < '0' OR (mapping_report ? 'coordinate_frame') AND jsonb_typeof(mapping_report['coordinate_frame']) IS DISTINCT FROM 'string' OR (mapping_report ? 'coordinate_scale') AND jsonb_typeof(mapping_report['coordinate_scale']) IS DISTINCT FROM 'number' OR (mapping_report ? 'coordinate_scale') AND CAST(mapping_report['coordinate_scale'] #>> ARRAY[]::TEXT[] AS NUMERIC) < '1' OR (mapping_report ? 'normalization') AND (jsonb_typeof(mapping_report['normalization']) IS DISTINCT FROM 'string' OR ((mapping_report['normalization'] #>> ARRAY[]::TEXT[]) NOT IN ('clipped', 'inherited', 'none', 'normalized', 'unknown')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'parsing record shape differs: PdfMappingDisposition', ERRCODE = '23514';
  END IF;
  INSERT INTO kb.pdf_mapping_report (task_id, product_key, report_index, input_index, body) VALUES (p_task, (product ->> 'product_key'), idx, CAST(mapping_report ->> 'input_index' AS BIGINT), mapping_report);
 END LOOP;
 IF (json_array_length(coverage_rows) = 0) THEN
  RAISE EXCEPTION USING MESSAGE = 'PDF coverage is mandatory', ERRCODE = '23514';
 END IF;
 FOR coverage IN SELECT CAST(coverage_rows.value AS JSONB) AS value 
FROM json_array_elements(coverage_rows) AS coverage_rows(value) LOOP
  IF (jsonb_typeof(coverage) IS DISTINCT FROM 'object') THEN
   RAISE EXCEPTION USING MESSAGE = 'parsing record must be an object: PdfProductCoverage', ERRCODE = '23514';
  END IF;
  IF ((EXISTS (SELECT shape_0.value 
FROM jsonb_object_keys(coverage) AS shape_0(value) 
WHERE NOT (shape_0.value = ANY (ARRAY['coverage_id', 'scope', 'family', 'discovery_policy', 'outcome', 'detail', 'supports'])))) OR NOT (coverage ? 'coverage_id') OR (coverage ? 'coverage_id') AND jsonb_typeof(coverage['coverage_id']) IS DISTINCT FROM 'string' OR NOT (coverage ? 'scope') OR (coverage ? 'scope') AND jsonb_typeof(coverage['scope']) IS DISTINCT FROM 'string' OR NOT (coverage ? 'family') OR (coverage ? 'family') AND jsonb_typeof(coverage['family']) IS DISTINCT FROM 'string' OR NOT (coverage ? 'discovery_policy') OR (coverage ? 'discovery_policy') AND jsonb_typeof(coverage['discovery_policy']) IS DISTINCT FROM 'string' OR NOT (coverage ? 'outcome') OR (coverage ? 'outcome') AND (jsonb_typeof(coverage['outcome']) IS DISTINCT FROM 'string' OR ((coverage['outcome'] #>> ARRAY[]::TEXT[]) NOT IN ('capped', 'complete', 'partial', 'unknown', 'unrequested', 'unsupported'))) OR NOT (coverage ? 'detail') OR (coverage ? 'detail') AND jsonb_typeof(coverage['detail']) IS DISTINCT FROM 'string' OR (coverage ? 'supports') AND (jsonb_typeof(coverage['supports']) IS DISTINCT FROM 'array' OR (EXISTS (SELECT shape_1.value 
FROM jsonb_array_elements(coverage['supports']) AS shape_1(value) 
WHERE jsonb_typeof(shape_1.value) IS DISTINCT FROM 'object' OR (EXISTS (SELECT shape_2.value 
FROM jsonb_object_keys(shape_1.value) AS shape_2(value) 
WHERE NOT (shape_2.value = ANY (ARRAY['input_index', 'coverage_id'])))) OR NOT (shape_1.value ? 'input_index') OR (shape_1.value ? 'input_index') AND (jsonb_typeof(shape_1.value['input_index']) IS DISTINCT FROM 'number' OR ((shape_1.value['input_index'] #>> ARRAY[]::TEXT[]) !~ '^[0-9]+$')) OR (shape_1.value ? 'input_index') AND CAST(shape_1.value['input_index'] #>> ARRAY[]::TEXT[] AS NUMERIC) < '0' OR NOT (shape_1.value ? 'coverage_id') OR (shape_1.value ? 'coverage_id') AND jsonb_typeof(shape_1.value['coverage_id']) IS DISTINCT FROM 'string')))) THEN
   RAISE EXCEPTION USING MESSAGE = 'parsing record shape differs: PdfProductCoverage', ERRCODE = '23514';
  END IF;
  IF ((coverage ->> 'coverage_id') = '' OR (coverage ->> 'scope') = '' OR (coverage ->> 'family') = '' OR (coverage ->> 'discovery_policy') = '' OR (coverage ->> 'detail') = '' OR (coverage ->> 'outcome') = 'complete') THEN
   RAISE EXCEPTION USING MESSAGE = 'PDF coverage scope/policy/outcome differs', ERRCODE = '23514';
  END IF;
  IF ((EXISTS (SELECT 1 
FROM jsonb_array_elements(coverage['supports']) AS supports(value) LEFT OUTER JOIN ops.pdf_product_input ON ops.pdf_product_input.task_id = p_task AND ops.pdf_product_input.product_key = (product ->> 'product_key') AND ops.pdf_product_input.input_index = CAST((supports.value ->> 'input_index') AS BIGINT) LEFT OUTER JOIN kb.pdf_product_coverage ON kb.pdf_product_coverage.task_id = ops.pdf_product_input.input_task_id AND kb.pdf_product_coverage.product_key = ops.pdf_product_input.input_product_key AND kb.pdf_product_coverage.coverage_id = (supports.value ->> 'coverage_id') 
WHERE kb.pdf_product_coverage.coverage_id IS NULL OR (kb.pdf_product_coverage.body ->> 'scope') IS DISTINCT FROM (coverage ->> 'scope') OR (kb.pdf_product_coverage.body ->> 'family') IS DISTINCT FROM (coverage ->> 'family'))) OR (coverage ->> 'outcome') = 'complete' AND NOT (EXISTS (SELECT 1 
FROM jsonb_array_elements(coverage['supports']) AS supports(value) JOIN ops.pdf_product_input ON ops.pdf_product_input.task_id = p_task AND ops.pdf_product_input.product_key = (product ->> 'product_key') AND ops.pdf_product_input.input_index = CAST((supports.value ->> 'input_index') AS BIGINT) JOIN kb.pdf_product_coverage ON kb.pdf_product_coverage.task_id = ops.pdf_product_input.input_task_id AND kb.pdf_product_coverage.product_key = ops.pdf_product_input.input_product_key AND kb.pdf_product_coverage.coverage_id = (supports.value ->> 'coverage_id') 
WHERE (kb.pdf_product_coverage.body ->> 'scope') = (coverage ->> 'scope') AND (kb.pdf_product_coverage.body ->> 'family') = (coverage ->> 'family') AND (kb.pdf_product_coverage.body ->> 'outcome') = 'complete'))) THEN
   RAISE EXCEPTION USING MESSAGE = 'complete coverage lacks qualified scope/family input attribution', ERRCODE = '23514';
  END IF;
  INSERT INTO kb.pdf_product_coverage (task_id, product_key, coverage_id, body) VALUES (p_task, (product ->> 'product_key'), (coverage ->> 'coverage_id'), coverage);
 END LOOP;
 RETURN digest;
END

