DECLARE
 published ops.pdf_published_revision%ROWTYPE;
 selected_release text;
BEGIN
 published := ops.require_published_companion_pin(p_project, p_demand, p_read, p_use, p_product, p_derivation);
 SELECT ops.data_demand.release_id 
FROM ops.data_demand 
WHERE ops.data_demand.id = p_demand INTO STRICT selected_release;
 RETURN QUERY WITH companions AS MATERIALIZED 
(SELECT CAST(raw.product_id AS TEXT) AS product_id, CAST(raw.revision_id AS TEXT) AS revision_id, CAST(raw.family AS TEXT) AS family, CAST(raw.local_id AS TEXT) AS local_id, CAST(raw.ordinal AS BIGINT) AS ordinal, CAST(ops.pdf_companion_body(raw.product_id, raw.revision_id, raw.family, raw.local_id, raw.body) AS JSONB) AS body 
FROM kb.pdf_record_companion AS raw 
WHERE raw.product_id = published.build_id AND raw.revision_id = published.build_id AND raw.family IN ('coverage'))
 SELECT CAST(c.local_id AS TEXT) AS coverage_id, CAST(c.body ->> 'scope' AS TEXT) AS scope, CAST(c.body ->> 'family' AS TEXT) AS coverage_family, CAST(c.body ->> 'discovery_policy' AS TEXT) AS discovery_policy, CAST(c.body ->> 'outcome' AS TEXT) AS outcome, CAST(c.body ->> 'detail' AS TEXT) AS detail, CAST(c.body['supports'] AS JSONB) AS supports_json, CAST(p_project AS TEXT) AS project_id, CAST(p_demand AS TEXT) AS demand_id, CAST(p_read AS TEXT) AS read_id, CAST(p_use AS TEXT) AS use_id, CAST(p_product AS TEXT) AS product_id, CAST(p_derivation AS TEXT) AS derivation_id, CAST(selected_release AS TEXT) AS selection_release_id, CAST(published.release_id AS TEXT) AS producer_release_id, CAST(published.task_id AS BIGINT) AS task_id, CAST(published.product_key AS TEXT) AS product_key, CAST(published.logical_digest AS TEXT) AS content_digest, CAST('pdf-companion-projection-v4:08560b6d21fbbc6a73ff3c2c2a905816112b97e92889545e9dbbb7c22a84f698' AS TEXT) AS projection_id 
FROM companions AS c 
WHERE c.family = 'coverage' ORDER BY CAST(c.local_id AS TEXT) COLLATE "C";
END

