_stage_membership.arrow","sha256":"c738995d5369b576fabe732e3f9e212461d98e3072115db8d311d15beb1afd8f"},{"name":"pdf-domain/implementation/pdf/lowering/codec/ops.pdf_stage_native.arrow","sha256":"ac25de74ff0a117f2b098f040fad912a344496d4d06863773a5c6a8b8ee292b8"},{"name":"pdf-domain/implementation/pdf/lowering/codec/ops.pdf_stage_reference.arrow","sha256":"f42f4999f33387e1dcefb4d11b357becda2974ad038b975a859b4a4a4b029f3c"},{"name":"pdf-domain/analysis/libraries.json","sha256":"f4cd9fdaed1a86181814ffdf784d6f55a3b5b5344288a7782e28c0958c076984"},{"name":"pdf-domain/schema/pdf_products","sha256":"e4787e8e36389c6e1a190d9611e662f2a4a706675f7eddea0c23d64a84e9e7cc"},{"name":"pdf-domain/schema/pdf-observation-vocabulary","sha256":"c460ea2b7c71490b2599e3f647893d1b40daedaea89410996941269ba12b8f71"},{"name":"pdf-domain/schema/pdf_observation_meaning","sha256":"1727e9623479e65afdb4b9b01ecea02c35bb52c58c0e15a82b42ed3f29c03c73"},{"name":"pdf-domain/schema/core","sha256":"dbc48b38f4d1630c48310ad78578a2ce3b42050d96262c219bde42db5496bda2"},{"name":"pdf-domain/schema/pdf_domain_schema","sha256":"697d52f38f0feb258511187fb8d8b209dc37fcc1ba52e82282dfcc93d503bdbd"},{"name":"pdf-domain/implementation/pdf/staging-model.yaml","sha256":"f26e45ac615b0fb9373b318d0fd8d9919613d9f332b1519be4424b5e07889383"},{"name":"pdf-domain/implementation/pdf/docling-validation.schema.json","sha256":"91d32d744d82f331889fa673b933b856add9153a1512aae6ff48ca1fc0217b9c"},{"name":"pdf-domain/native/data-operation-protocol.yaml","sha256":"a9aedeb6c6af927db1af5913ea44cff863392d1e40c9cf225b5877ebd4c7b742"}]' AS JSONB))) IS DISTINCT FROM true) THEN
