CREATE OR REPLACE FUNCTION sem.admit_pdf_operation_contracts(p_release text, p_new_release boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$DECLARE
 facet jsonb;
 facet_digest text;
 input_ jsonb;
 action_id text;
 action_value jsonb;
BEGIN
 SELECT CAST(convert_from(sem.input.content, 'UTF8') AS JSONB) AS convert_from_1, sem.input.content_digest 
FROM sem.input 
WHERE sem.input.release_id = p_release AND sem.input.input_kind = 'dependency' AND sem.input.input_name = 'pdf-domain/contract.json' AND encode(sha256(sem.input.content), 'hex') = sem.input.content_digest INTO facet, facet_digest;
 IF (NOT found) THEN
  IF (EXISTS (SELECT sem.input.input_name 
FROM sem.input 
WHERE sem.input.release_id = p_release AND sem.input.input_kind = 'dependency' AND sem.input.input_name = 'pdf-domain/contract.json')) THEN
   RAISE EXCEPTION USING MESSAGE = 'PDF domain contract differs', ERRCODE = '23514';
  END IF;
